// ─── PERFORMANCE: RAW ROSTER VIEW ─────────────────────────────────────────
/**
 * Return a plain (non-draft) view of the roster for READ-ONLY work.
 *
 * Inside a `set()` producer, `state.npcs` is an immer Proxy. Array methods over
 * a Proxy are dramatically slower than over a plain array — v8 cannot use its
 * fast paths, so every single element access goes through a trap. Measured on
 * this roster: one `filter().sort().slice()` costs **6.5 ms plain vs 48 ms
 * through the proxy** — a 7x penalty, paid several times per turn.
 *
 * `current()` unwraps the draft to the underlying plain object, so scans
 * (filtering artists, finding a manager, building a lookup map) run at full
 * speed. It is safe because the result is only ever read: any NPC that must
 * actually change is looked up on the real draft by id.
 */
/**
 * A plain, owned copy of a slice of state.
 *
 * `structuredClone` rather than a spread, because the engines mutate the day
 * arrays *inside* each platform slice — a shallow copy would still hand them
 * the draft's arrays. These are plain numbers and strings, so the clone is
 * cheap; it is the per-write proxy cost it avoids that was expensive.
 */
function clonePlain<T>(value: T): T {
  return structuredClone(value);
}

/** The roster as it stood when this change began — no clone, for reading only. */
function baseNpcs(state: GameState): NPC[] {
  const list = state.npcs as NPC[];
  return isDraft(list) ? ((original(list) as NPC[] | undefined) ?? (raw(list) as NPC[])) : list;
}

function raw<T>(value: T): T {
  // GUARD REQUIRED. immer 11 changed `current()` to THROW on a value that is
  // not a draft (`die(10)` — "Cannot use a proxy that has been revoked");
  // immer 10 simply returned it. This helper is called both inside producers,
  // where the value IS a draft, and outside them, where it is already plain —
  // notably `saveGame`, which reads `get()` and is not inside a producer. The
  // unguarded version made the Save button throw every single time, while the
  // auto-save inside `advanceTurn` kept working (it runs inside a producer),
  // which is exactly the kind of split that hides the bug.
  return isDraft(value) ? (current(value as never) as T) : value;
}

// ─── SHOWS: READING THE STATE INTO THE ENGINE ──────────────────────────────
//
// `sim/shows.ts` is pure and knows nothing about the store. These two are the
// only bridge: one reads the live state into the engine's input, the other
// hands back the manager's commission. The screen's preview and the booking
// itself both go through here, so the estimate the player acted on and the show
// that happened cannot drift apart.

/**
 * The manager's commission on the door.
 *
 * A retainer manager takes nothing off the takings — that is what the monthly
 * fee buys — so this returns 0 for them rather than their headline percentage.
 */
function managerCommissionPct(contracts: ActiveContract[]): number {
  const c = contracts.find((x) => x.type === 'management' && x.active);
  if (!c) return 0;
  if (c.terms?.feeKind === 'retainer') return 0;
  const pct = c.terms?.percentage ?? 0;
  // Stored as a percentage (15), not a fraction (0.15). Accept either, because
  // a mis-scaled commission is a silent 100x error in somebody's favour.
  return Math.max(0, Math.min(0.35, pct > 1 ? pct / 100 : pct));
}

// `slotRequirement` used to live here. It moved to `sim/shows.ts` when the tour
// planner arrived: a run of dates has to ask this of every leg before the player
// commits, and a store-private copy could not be reached from there.

/**
 * One city on a run, as the screen asks for it.
 *
 * Deliberately thin — a venue id and a price. Everything the show engine needs
 * is read off the live state, so the UI cannot pass a stale capacity or a
 * fatigue figure the engine would then disagree with.
 */
export interface TourStop {
  venueId: string;
  type: ShowType;
  price: number;
  /** The night the player wants. Omitted means "route it from the travel". */
  wantedSerial?: number;
}

/**
 * How long ago the newest thing the player put out came out.
 *
 * A tour in the weeks after a record draws better than the same tour in a dead
 * month, which is the whole reason an album and a run of dates belong together.
 * Albums carry an exact `releaseSerial`; songs only carry a date string, so
 * those are parsed and an unparseable one is skipped rather than counted as
 * "out today" — a bad date should not mint free buzz.
 */
function daysSinceLastRelease(state: GameState, nowSerial: number): number | null {
  let newest: number | null = null;
  const consider = (serial: number | null) => {
    if (serial === null || serial > nowSerial) return;
    if (newest === null || serial > newest) newest = serial;
  };

  for (const s of state.songs) {
    if (!isReleased(s)) continue;
    const d = parseGameDate(s.releaseDate);
    consider(d ? dateToSerial(d) : null);
  }
  for (const a of state.albums) {
    if (a.releaseSerial !== undefined) consider(a.releaseSerial);
    else {
      const d = parseGameDate(a.releaseDate);
      consider(d ? dateToSerial(d) : null);
    }
  }

  return newest === null ? null : nowSerial - newest;
}

/** Turn the screen's thin stops into everything the tour planner needs. */
function tourStopsFrom(state: GameState, stops: TourStop[]): TourStopRequest[] {
  const out: TourStopRequest[] = [];
  for (const s of stops) {
    const venue = findVenue(s.venueId);
    if (!venue) continue;
    const input = showInputFrom(state, venue, s.price);
    out.push({
      type: s.type,
      venue,
      price: s.price,
      wantedSerial: s.wantedSerial,
      lastShowSerial: state.cityMarkets[venue.city]?.lastShowSerial,
      base: {
        fame: input.fame,
        momentum: input.momentum,
        artistCountry: input.artistCountry,
        cityCountry: input.cityCountry,
        capacity: input.capacity,
        promo: input.promo,
        fatigue: input.fatigue,
        visualMult: input.visualMult,
        managerPct: input.managerPct,
        promoterPct: input.promoterPct,
        cutRelief: input.cutRelief,
        logisticsMult: input.logisticsMult,
        venueHireMult: input.venueHireMult,
      },
    });
  }
  return out;
}

/**
 * The stops whose room could not be resolved.
 *
 * `findVenue` only knows the cities in `SHOW_CITIES`, so a stop built for any
 * other city resolves to nothing — and `tourStopsFrom` drops it with a bare
 * `continue`. The player asks for six dates and gets three, with nothing said
 * about the other three. That is the silent no-op this codebase does not allow,
 * so both `planTourAt` and `bookTour` ask this question FIRST and refuse out
 * loud, before anything is planned or charged.
 */
function unresolvedStops(stops: TourStop[]): TourStop[] {
  return stops.filter((s) => !findVenue(s.venueId));
}

/** The skill of whoever is negotiating for the player in this role, 0 when nobody is. */
function playerNegotiatorSkill(state: GameState, role: 'manager' | 'lawyer'): number {
  const member = (raw(state.crew) as CrewMember[]).find((c) => c.role === role);
  let skill = member?.skill ?? 0;
  if (role === 'manager') {
    const signed = activeManager(raw(state.contracts) as ActiveContract[], raw(state.npcs) as NPC[]);
    if (signed) skill = Math.max(skill, managerSkillOf(signed) ?? 0);
  }
  return skill;
}

/** Whether the player already has something that night. One event per night. */
function playerBusyOn(state: GameState, serial: number): boolean {
  if (state.scheduledShows.some((s) => s.serial === serial)) return true;
  if (state.bookedGigs.some((g) => g.serial === serial)) return true;
  return state.tours.some(
    (t) => t.status !== 'cancelled' && t.legs.some((l) => l.playedSerial === undefined && l.serial === serial),
  );
}

/**
 * Who wants the player on a bill this turn.
 *
 * Returns at most one offer a turn (two on a month jump). Hosts are drawn from
 * the real roster, filtered by an ACCESS rule: you are only invited by people
 * near your own level, or by somebody further up who already likes you.
 */
function rollShowOffers(
  state: GameState,
  npcs: NPC[],
  nowSerial: number,
  days: number,
  hasManager: boolean,
  hasPromoter: boolean,
  songs: Song[],
): ShowOffer[] {
  const player = state.player;
  if (!player) return [];
  const open = state.showOffers.filter((o) => o.status === 'open');
  if (open.length >= 5) return [];

  const fame = blendedFame(player);
  // Nobody books an act with nothing out and no name.
  const out0 = songs.filter((s) => isSongReleased(s)).length;
  if (out0 === 0 && fame < 15) return [];
  // What kind of manager you have decides how often the phone rings for
  // bookings, and from where.
  const mgr = managerOf(state, npcs);
  const spec = mgr ? SPECIALTIES[managerSpecialty(mgr)] : null;
  const reach = mgr ? managerReach(mgr) : null;
  const travelOk = (country: string) => {
    if (country === player.country) return true;
    // Nobody abroad books a name nobody abroad knows.
    if (player.career.nationalFame < 30 && marketPresence(state, country) < 0.25) return false;
    if (mgr && reach && !reachIncludes(reach, mgr.country, player.country, country)) return false;
    return true;
  };
  let perDay = 0.08 + fame / 400 + (hasManager ? 0.05 : 0) + (hasPromoter ? 0.04 : 0) + (spec?.showRate ?? 0);
  if (!hasManager) perDay *= 0.6;
  const chance = 1 - Math.pow(1 - perDay, Math.min(days, 14));
  const attempts = days >= 14 ? 2 : 1;
  const out: ShowOffer[] = [];

  const HOST_ROLES = ['promoter', 'venue_owner', 'dj', 'artist'];
  const hostsOpen = new Set(open.map((o) => o.hostId));
  const recentHit = songs.some((s) => isSongReleased(s) && (s.weeksOut ?? 99) <= 10 && s.quality >= 70);

  for (let a = 0; a < attempts; a++) {
    if (Math.random() > chance) continue;
    if (open.length + out.length >= 5) break;

    // WHERE first, then who. Most nights are at home; a date abroad needs a
    // name that travels there — national standing, your music charting in
    // that country, or a manager who works abroad. The country is weighted by
    // how well your music crosses into it, so a Ghanaian act gets Lagos and
    // London long before Seoul.
    const wantAbroad = !!spec && Math.random() < spec.abroad && player.career.nationalFame >= 30;
    const abroadChance = wantAbroad ? 0.75 : Math.min(0.3, Math.max(0, (player.career.nationalFame - 25) / 120));
    let where = player.country;
    if (Math.random() < abroadChance) {
      const cands = SHOW_COUNTRIES.filter((c) => c !== player.country && travelOk(c));
      const weights = cands.map((c) => Math.pow(Math.max(affinity(player.country, c), marketPresence(state, c)), 2));
      const total = weights.reduce((x, y) => x + y, 0);
      if (total > 0) {
        let r = Math.random() * total;
        for (let i = 0; i < cands.length; i++) { r -= weights[i]; if (r <= 0) { where = cands[i]; break; } }
      }
    }
    // Sample the roster rather than sort it — 11k NPCs, one pass, cheap.
    let host: NPC | undefined;
    // Friends in the scene bring you out first. An artist who rates you is the
    // most likely person in the world to put you on their show.
    if (Math.random() < 0.45) {
      const friends = npcs.filter((n) => n.role === 'artist' && n.relationshipScore >= 20 && !hostsOpen.has(n.id) && n.fame >= 8 && n.fame - fame <= 45 && (n.country === player.country || travelOk(n.country)));
      host = pickFrom(friends);
    }
    // The scene in that country: one pass, then random picks from it.
    const local = host ? [] : npcs.filter((n) => n.country === where && HOST_ROLES.includes(n.role) && !hostsOpen.has(n.id));
    for (let tries = 0; tries < 60 && !host && local.length; tries++) {
      const n = local[Math.floor(Math.random() * local.length)];
      // Artists put on most of the nights in a scene.
      if (n.role !== 'artist' && Math.random() < 0.5) continue;
      if (n.role === 'artist') {
        if (n.fame < 8) continue;
        const gap = n.fame - fame;
        if (gap > 40) continue;
        if (gap > 20 && n.relationshipScore < 25) continue;
      }
      host = n;
    }
    if (!host) continue;

    // The room: in the host's own city.
    const place =
      SHOW_CITIES.find((c) => c.city === host!.city && c.country === host!.country) ??
      pickFrom(SHOW_CITIES.filter((c) => c.country === host!.country)) ??
      pickFrom(SHOW_CITIES.filter((c) => c.country === player.country)) ??
      SHOW_CITIES[0];
    const venues = venuesInCity(place.city, place.country);
    // A road manager with a real network gets you one size of room up.
    const bump = spec?.id === 'booker' && mgr && managerNetwork(mgr) >= 55 ? 15 : 0;
    const cap = host.role === 'artist' ? accessTier(host.fame) : accessTier(fame + bump);
    const allowed = venues.filter((v) => VENUE_CLASSES[v.cls].tier <= cap && (host!.role === 'artist' || !venueLockReason(v, fame + bump)));
    const venue = allowed[allowed.length - 1] ?? venues[0];

    // The night.
    let serial = -1;
    for (let t = 0; t < 12; t++) {
      const s = nowSerial + MIN_LEAD_DAYS[venue.cls] + 3 + Math.floor(Math.random() * 40);
      if (isNightFree(venue, s) && !playerBusyOn(state, s) && !state.showOffers.some((o) => o.status === 'open' && o.serial === s)) {
        serial = s;
        break;
      }
    }
    if (serial < 0) continue;

    const gap = host.fame - fame;
    const billing: OfferBilling =
      host.role === 'artist'
        ? gap >= 25 ? 'guest' : gap >= 8 ? 'support' : 'co_headliner'
        : host.role === 'dj' ? 'guest' : fame < 10 ? 'co_headliner' : 'headliner';
    const kind: ShowOffer['kind'] =
      host.role === 'artist' ? 'invite' : host.role === 'dj' ? 'club_night' : venue.cls === 'hall' || venue.cls === 'arena' ? 'festival' : 'headline';

    out.push(
      buildOffer({
        id: uuidv4(),
        host,
        venueId: venue.id,
        venueName: venue.name,
        city: venue.city,
        country: venue.country,
        capacity: venue.capacity,
        serial,
        nowSerial,
        playerFame: fame,
        relationship: host.relationshipScore,
        billing,
        kind,
        reason: whyInvited({
          relationship: host.relationshipScore,
          playerFame: fame,
          hostFame: host.fame,
          hasManager,
          hasPromoter,
          hit: recentHit,
          roll: Math.random(),
        }),
        hasManager,
        roll: Math.random(),
      }),
    );
    // Who else is on the bill.
    const made = out[out.length - 1];
    made.lineup = buildLineup({
      host,
      kind,
      capacity: venue.capacity,
      playerFame: fame,
      playerBilling: billing,
      pool: npcs,
      beefIds: activeBeefIds(state),
      friendIds: friendIdsOf(npcs),
      seed: made.id,
    });
    if (made.lineup.some((a) => a.beef)) {
      const r = made.lineup.find((a) => a.beef)!;
      made.log = [`Heads up: ${r.name} is on this bill too.`, ...made.log];
    }
    hostsOpen.add(host.id);
  }
  return out;
}

/** Everyone the player is currently at war with. */
function activeBeefIds(state: GameState): Set<string> {
  return new Set((state.beefs ?? []).filter((b) => !b.resolution).map((b) => b.npcId));
}

/** The player's friends in the scene: artists who like them. */
function friendIdsOf(npcs: NPC[]): Set<string> {
  const out = new Set<string>();
  for (const n of npcs) if (n.role === 'artist' && n.relationshipScore >= 30) out.add(n.id);
  return out;
}

/** Turn up (or down) the heat on a live beef from something that happened in the world. */
function nudgeBeef(state: GameState, npcId: string, heat: number, serial: number, win?: boolean): void {
  const beef = (state.beefs ?? []).find((b) => b.npcId === npcId && !b.resolution);
  if (!beef) return;
  beef.heat = Math.max(0, Math.min(100, settleHeat(beef, serial) + heat));
  beef.heatSerial = serial;
  if (win === true) beef.wins += 1;
  if (win === false) beef.losses += 1;
}

function pickFrom<T>(arr: T[]): T | undefined {
  return arr.length ? arr[Math.floor(Math.random() * arr.length)] : undefined;
}

/** Everything a night on somebody else's bill does to the world. */
function playBookedGig(
  state: GameState,
  gig: BookedGig,
  crew: ReturnType<typeof crewBonuses>,
  log: string[],
): void {
  const player = state.player!;
  const venue = findVenue(gig.venueId);
  const host = state.npcs.find((n) => n.id === gig.hostId);
  const hostFame = host?.fame ?? 30;

  // The host drew this crowd, not you — so the room is mostly full whatever
  // you do, and it is the host's name that sets how many.
  const hostFill = Math.min(1, Math.max(0.55, 0.62 + hostFame / 250) * (0.92 + Math.random() * 0.16));
  const audience = Math.round(gig.capacity * hostFill);

  const quality = performanceScore({
    stagePresence: player.stats.stagePresence,
    performance: player.stats.performance,
    charisma: player.stats.charisma,
    consistency: player.stats.consistency,
    stageBonus: crew.stageBonus,
    energyRatio: 1,
    fill: hostFill,
  });

  const merch = Math.round(audience * 2.2 * (gig.terms.merchSplit / 100));
  const reach = affinity(player.country, gig.country);
  const travel = gig.terms.travel
    ? 0
    : Math.round((gig.country === player.country ? 350 : 900 + (1 - reach) * 5200) * crew.logisticsMult);
  const gross = gig.terms.fee + merch;
  const managerCut = Math.round(gross * managerCommissionPct(raw(state.contracts) as ActiveContract[]));
  const net = gross - travel - managerCut;

  const costs: ShowCostLine[] = [];
  if (travel > 0) costs.push({ key: 'travel', label: 'Travel & hotel', amount: travel });
  if (managerCut > 0) costs.push({ key: 'manager', label: "Manager's commission", amount: managerCut, to: 'Manager' });

  const exposure = exposureOf(gig.terms.billing);
  const fameGained = Math.round(Math.min(8, (quality / 100) * 2.5 * exposure + Math.sqrt(audience) / 55));

  const before = player.career.money;
  player.career.money += net;
  player.career.totalEarnings += Math.max(0, net);
  player.career.localFame = Math.min(100, player.career.localFame + fameGained * 0.5);
  if (gig.capacity >= 2500) player.career.nationalFame = Math.min(100, player.career.nationalFame + fameGained * 0.25);
  if (gig.country !== player.country) player.career.internationalFame = Math.min(100, player.career.internationalFame + fameGained * 0.2);
  player.career.reputation = Math.min(100, Math.max(0, player.career.reputation + (quality >= 60 ? 1 : -1)));
  addMomentum(state, quality >= 70 ? 3 : 1);
  player.stats.stagePresence = Math.min(100, player.stats.stagePresence + 0.4);
  player.stats.performance = Math.min(100, player.stats.performance + 0.4);
  player.stats.charisma = Math.min(100, player.stats.charisma + 0.3);
  ledgerAdd('shows', player.career.money - before);

  // The city remembers this too.
  const market = state.cityMarkets[gig.city];
  state.cityMarkets[gig.city] = {
    city: gig.city,
    country: gig.country,
    fatigue: addFatigue(decayedFatigue(market, gig.serial), hostFill * 0.5),
    fatigueSerial: gig.serial,
    lastShowSerial: gig.serial,
    shows: (market?.shows ?? 0) + 1,
  };

  state.shows.push({
    id: uuidv4(),
    type: gig.kind === 'festival' ? 'festival' : 'local_club',
    city: gig.city,
    country: gig.country,
    date: formatGameDate(serialToDate(gig.serial)),
    ticketPrice: 0,
    capacity: gig.capacity,
    attendance: audience,
    performanceQuality: quality,
    moneyEarned: net,
    fameGained,
    completed: true,
    venueId: gig.venueId,
    venueName: gig.venueName,
    venueClass: venue?.cls,
    merch,
    costs,
    gross,
    avgTicket: 0,
    hostName: gig.hostName,
    billing: gig.terms.billing,
  });

  // The host's opinion of you.
  let relDelta = relationshipFromNight(quality, gig.terms.billing);
  let outshone = false;
  if (quality >= 88 && gig.archetype === 'status' && gig.terms.billing !== 'headliner') {
    relDelta = Math.min(relDelta, 3) - 5;
    outshone = true;
  }
  if (host) {
    host.relationshipScore = Math.max(-100, Math.min(100, host.relationshipScore + relDelta));
    host.memoryLog = [`You played their ${gig.city} bill (${quality}/100)`, ...(host.memoryLog ?? [])].slice(0, 10);
  }

  // A touch of the unexpected.
  let extra = '';
  const dice = Math.random();
  if (quality >= 70 && dice < 0.2) {
    extra = ` ${gig.hostName} pulled you back on stage for the finale.`;
    player.career.localFame = Math.min(100, player.career.localFame + 0.5);
  } else if (quality >= 70 && dice < 0.35) {
    extra = ' Somebody from the crowd filmed your set and it started to travel.';
    addMomentum(state, 2);
  } else if (quality < 40 && dice < 0.3) {
    extra = ' A clip of the set is doing the rounds for the wrong reasons.';
  }

  // ── The rest of the bill ──────────────────────────────────────────────
  const billNotes: string[] = [];
  for (const act of gig.lineup ?? []) {
    if (act.npcId === gig.hostId) continue;
    const npc = state.npcs.find((n) => n.id === act.npcId);
    if (!npc) continue;
    const beefLive = (state.beefs ?? []).some((b) => b.npcId === act.npcId && !b.resolution);
    if (act.beef && beefLive) {
      const beef = state.beefs.find((b) => b.npcId === act.npcId && !b.resolution)!;
      const c = clashOutcome({
        rivalName: act.name,
        quality,
        playerFame: blendedFame(player),
        rivalFame: npc.fame,
        heat: settleHeat(beef, gig.serial),
        relationship: npc.relationshipScore,
        avoided: !!gig.avoidRival,
        roll: Math.random(),
      });
      player.career.localFame = Math.max(0, Math.min(100, player.career.localFame + c.fame));
      player.career.reputation = Math.max(0, Math.min(100, player.career.reputation + c.reputation));
      if (c.momentum) addMomentum(state, c.momentum);
      if (c.money) { player.career.money += c.money; ledgerAdd('shows', c.money); }
      npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + c.relationship));
      nudgeBeef(state, act.npcId, c.heat, gig.serial, c.win);
      if (c.kind === 'squashed') {
        beef.resolution = { kind: 'truce', at: gig.serial, line: `Squashed backstage at ${gig.hostName}'s ${gig.city} show.` };
      }
      billNotes.push(c.text);
      if (c.kind !== 'cold') {
        const headline = c.kind === 'brawl' ? `Backstage chaos: ${player.artistName} and ${act.name} crews clash in ${gig.city}`
          : c.kind === 'squashed' ? `${player.artistName} and ${act.name} squash it backstage`
          : c.kind === 'bodied' ? `${player.artistName} steals the night from ${act.name} in ${gig.city}`
          : `${act.name} upstages ${player.artistName} in ${gig.city}`;
        state.headlines.unshift({
          id: uuidv4(),
          text: headline,
          fullStory: c.text,
          date: formatGameDate(serialToDate(gig.serial)),
          relatedEntities: [player.id, act.npcId],
          priority: c.kind === 'brawl' ? 7 : 5,
          category: c.kind === 'brawl' ? 'scandal' : 'beef',
        });
      }
      continue;
    }
    const d = networkingDelta(act, quality, Math.random());
    npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + d));
    if (act.slot === 'headliner' && quality >= 72 && Math.random() < 0.25) {
      billNotes.push(`${act.name} watched your set from the side of the stage and asked for your number.`);
      npc.relationshipScore = Math.min(100, npc.relationshipScore + 5);
    }
  }
  if (billNotes.length) extra += ' ' + billNotes.join(' ');

  const feel = outshone
    ? ` You outshone the bill and their camp was not thrilled (${relDelta} relationship).`
    : ` ${relDelta >= 0 ? '+' : ''}${relDelta} with ${gig.hostName}.`;
  log.push(
    `🎤 ${gig.hostName}'s bill, ${gig.city} — ${audience.toLocaleString()} in the room, ` +
      `${net >= 0 ? '+' : '−'}$${Math.abs(net).toLocaleString()}, reviewed ${quality}/100.${extra}`,
  );
  state.mailbox.unshift({
    id: uuidv4(), from: 'booking_desk', fromName: 'Booking desk',
    subject: `🎤 Settlement: ${gig.hostName}'s bill, ${gig.city}`,
    body:
      `${BILLING_LABEL[gig.terms.billing]} · ${gig.terms.slotMins} min · ${audience.toLocaleString()} of ${gig.capacity.toLocaleString()} in the room.\n` +
      `Fee $${gig.terms.fee.toLocaleString()} + merch $${merch.toLocaleString()}` +
      `${travel ? ` − travel $${travel.toLocaleString()}` : ''}${managerCut ? ` − commission $${managerCut.toLocaleString()}` : ''}.\n` +
      `Net ${net >= 0 ? '+' : '−'}$${Math.abs(net).toLocaleString()}. Reviewed ${quality}/100.${extra}${feel}`,
    timestamp: new Date().toISOString(), read: false, type: 'general',
  });
}

/**
 * The crowd demand supports for a scheduled show RIGHT NOW.
 *
 * Re-read from the live state every tick, so a hit single that lands between
 * announcement and the night really does lift the on-sale, and a scandal really
 * does sink it. The hidden `luck` is the one thing fixed at announcement.
 */
export function liveShowTarget(state: GameState, show: ScheduledShow, venue: Venue): number {
  const input = showInputFrom(state, venue, show.price, show.serial);
  const promo = input.promo * marketingMult(show.marketingSpend, show.capacity, show.price);
  const d = computeDemand({ ...input, promo });
  // A special guest on the poster sells tickets.
  const guests = guestDemandBoost(show.guests ?? [], state.player ? blendedFame(state.player) : 0);
  return Math.min(venue.capacity, Math.max(0, d.draw * d.elasticity * d.saturation * show.luck * guests));
}

const VENUE_CLASS_LABEL: Record<string, string> = {
  club: 'Club', theatre: 'Theatre', hall: 'Concert hall', arena: 'Arena', stadium: 'Stadium',
};

/**
 * Everything a played night does to the world, in ONE place.
 *
 * `bookShow` and the tour tick both need this, and the moment it exists twice
 * the two copies drift — which is how the old code ended up with two formulas
 * for the same event. So the settlement lives here, and the only thing the
 * callers differ on is whether the calendar moves.
 *
 * `advanceCalendar` is that difference. A single show is played NOW and eats
 * the rest of the day; a tour date arrives on the clock the tour was booked
 * against, so the day has already passed and must not be spent twice.
 */
function applyShowOutcome(
  state: GameState,
  opts: {
    venue: Venue;
    type: ShowType;
    price: number;
    night: ShowSettlement;
    performanceQuality: number;
    /** Energy actually spent, for the log line. */
    energy: number;
    nowSerial: number;
    controversyMult: number;
    advanceCalendar: boolean;
    /** Set when the night belongs to a tour, so history can group it. */
    tourId?: string;
    /**
     * Where the log line goes.
     *
     * `bookShow` wants it on `lastEventLog` immediately. The tick cannot use
     * that: it REPLACES `lastEventLog` wholesale at the end of the turn from
     * its own array, so a direct write from in here would be silently thrown
     * away — and a tour date that plays with no line in the feed is a night the
     * player never sees happen.
     */
    logSink?: string[];
  },
): { attendance: number; fameGained: number; daysOff: number } {
  const { venue, type, price, night } = opts;
  const attendance = night.tickets;
  const nowSerial = opts.nowSerial;
  const market = state.cityMarkets[venue.city];

  const fameGained = Math.round(
    Math.min(6, (opts.performanceQuality / 100) * 3 + Math.pow(Math.max(0, attendance), 0.55) / 60),
  );

  const show: Show = {
    id: uuidv4(),
    type,
    city: venue.city,
    country: venue.country,
    // Dated from the NIGHT, not the clock. The tick can jump thirty days in one
    // go, and a tour date settled at the far end of that jump was still played
    // on its own night — dating it "today" would put three shows on one date.
    date: formatGameDate(serialToDate(nowSerial)),
    ticketPrice: price,
    capacity: venue.capacity,
    attendance,
    performanceQuality: opts.performanceQuality,
    moneyEarned: night.net,
    fameGained,
    completed: true,
    venueId: venue.id,
    venueName: venue.name,
    venueClass: venue.cls,
    merch: night.merch,
    costs: night.costs,
    gross: night.gross,
    avgTicket: attendance > 0 ? Math.round(night.gross / attendance) : 0,
    tourId: opts.tourId,
  };

  state.shows.push(show);

  // ── The city remembers ────────────────────────────────────────────────
  // Decayed to now before adding to it, so a city that has been left alone for
  // two months is not still carrying the last show's weight.
  state.cityMarkets[venue.city] = {
    city: venue.city,
    country: venue.country,
    fatigue: addFatigue(decayedFatigue(market, nowSerial), night.fill),
    fatigueSerial: nowSerial,
    lastShowSerial: nowSerial,
    shows: (market?.shows ?? 0) + 1,
  };

  state.player!.career.money += night.net;
  state.player!.career.totalEarnings += Math.max(0, night.net);
  state.player!.career.localFame = Math.min(
    100,
    state.player!.career.localFame + fameGained * 0.5,
  );
  // A publicist does not make the bad night good — they make it cost less.
  // Standing lost is scaled; standing gained is not touched.
  const repDelta =
    opts.performanceQuality >= 60 ? Math.min(4, 1 + Math.round(attendance / 4000)) : -1;
  state.player!.career.reputation = Math.min(
    100,
    state.player!.career.reputation + (repDelta < 0 ? repDelta * opts.controversyMult : repDelta),
  );

  // Playing live is the oldest way there is to make people look at you, and a
  // good night is worth more than a bad one. The show logs its own line below,
  // so this gain stays silent.
  addMomentum(state, opts.performanceQuality >= 70 ? 4 : 2);

  // Stat growth from shows
  state.player!.stats.stagePresence = Math.min(100, state.player!.stats.stagePresence + 0.5);
  state.player!.stats.performance = Math.min(100, state.player!.stats.performance + 0.5);
  state.player!.stats.charisma = Math.min(100, state.player!.stats.charisma + 0.3);

  // Social post about show
  const showPost: SocialPost = {
    id: uuidv4(),
    platform: 'chirp',
    authorId: 'player',
    authorName: state.player!.artistName,
    content:
      opts.performanceQuality >= 70
        ? `Just rocked ${venue.city}! The crowd was INSANE 🔥 ${attendance.toLocaleString()} people. Thank you ${venue.city}!`
        : `Just finished my set in ${venue.city}. Building. 💪 More shows coming.`,
    likes: Math.floor(attendance * 0.1),
    shares: Math.floor(Math.random() * 20),
    comments: [],
    timestamp: new Date().toISOString(),
    isPlayerPost: true,
    trendingScore: opts.performanceQuality * 0.5,
  };
  state.socialPosts.unshift(showPost);

  state.headlines.unshift({
    id: uuidv4(),
    text: generateHeadline('show', state.player!.artistName, venue.city),
    fullStory: `${state.player!.artistName} played ${venue.name} in ${venue.city} to ${attendance.toLocaleString()} of ${venue.capacity.toLocaleString()}. Performance quality: ${opts.performanceQuality}/100.`,
    date: formatGameDate(serialToDate(nowSerial)),
    relatedEntities: [state.player!.id],
    priority: opts.performanceQuality >= 70 ? 6 : 3,
    category: 'show',
  });

  // The date moves. A tour is two weeks of your life, not a free click.
  const daysOff = opts.advanceCalendar
    ? type === 'international_tour'
      ? 14
      : type === 'festival'
        ? 3
        : 1
    : 0;
  if (daysOff > 0) {
    state.gameDate = advanceDate(state.gameDate, daysOff) as typeof state.gameDate;
    state.turnCount += 1;
  }

  const tail =
    daysOff > 0
      ? `${opts.energy} energy, ${daysOff} day${daysOff > 1 ? 's' : ''}.`
      : // A tour date costs no energy of its own: the nights between dates are
        // what pays for it, and the tick has already given them back.
        'on the road.';
  const line =
    `${opts.tourId ? '🚌' : '🎭'} ${venue.name}, ${venue.city} — ` +
    `${attendance.toLocaleString()}/${venue.capacity.toLocaleString()} in, ` +
    `$${Math.abs(night.net).toLocaleString()} ${night.net >= 0 ? 'clear' : 'LOST'}. ${tail}`;
  if (opts.logSink) {
    opts.logSink.push(line);
  } else {
    state.lastEventLog.unshift(line);
    state.lastEventLog = state.lastEventLog.slice(0, 10);
  }

  return { attendance, fameGained, daysOff };
}

/**
 * How much your music is actually playing in a country: your best position on
 * its chart, and whether you have played there before. 0 = nobody there has
 * heard of you beyond what distance allows; 1 = you are on top of their chart.
 */
function marketPresence(state: GameState, country: string): number {
  const p = state.player;
  if (!p) return 0;
  const chart = state.charts?.[country] ?? [];
  let best = 0;
  for (const e of chart) {
    if (e.artistId !== p.id) continue;
    best = Math.max(best, 1 - (Math.max(1, e.position) - 1) / 50);
  }
  const played = (state.shows ?? []).some((sh) => findVenue(sh.venueId ?? '')?.country === country) ? 0.12 : 0;
  return Math.max(0, Math.min(1, best + played));
}

/** Everything the show engine needs, read off the live state. */
/**
 * Everything the show engine needs, read off the live state.
 *
 * `atSerial` is for the tour tick. A tour leg is planned and settled against
 * its OWN night, and a city's fatigue has to be measured against the night it
 * was caused on — otherwise a month-long jump would settle every leg with the
 * same "as of today" fatigue and the second date in a city would look like the
 * first. Defaults to now, which is what a single booking wants.
 */
function showInputFrom(
  state: GameState,
  venue: Venue,
  price: number,
  atSerial?: number,
): ShowPlanInput {
  const p = state.player!;
  const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
  const night = atSerial ?? dateToSerial(state.gameDate);
  const season = seasonalDemand(venue.country, venue.city, night, venue.cls, getCountry(venue.country)?.continent);
  const mgr = activeManager(raw(state.contracts) as ActiveContract[], raw(state.npcs) as NPC[]);
  return {
    presence: venue.country === p.country ? 0 : marketPresence(state, venue.country),
    season: season.mult,
    // A manager who works abroad gets the visas done for less.
    visaMult: mgr && managerSpecialty(mgr) === 'global' ? 0.6 : mgr ? 0.85 : 1,
    venue,
    price,
    fame: blendedFame(p),
    momentum: p.career.momentum,
    artistCountry: p.country,
    cityCountry: venue.country,
    capacity: venue.capacity,
    promo: bonuses.promoSales,
    fatigue: decayedFatigue(state.cityMarkets[venue.city], atSerial ?? dateToSerial(state.gameDate)),
    visualMult: bonuses.visualMult,
    managerPct: managerCommissionPct(raw(state.contracts) as ActiveContract[]),
    promoterPct: bonuses.promoterCut,
    cutRelief: bonuses.cutRelief,
    logisticsMult: bonuses.logisticsMult,
    venueHireMult: bonuses.venueHireMult,
  };
}

// ─── STUDIO VAULT HELPERS ──────────────────────────────────────────────────

/** A master still sitting in the vault: recorded, not out, not archived. */
export function isVaultMaster(song: Song): boolean {
  return !isReleased(song) && !song.archivedAt;
}

/**
 * Rebuild the inputs a stored master was tracked with, so an edit can be scored
 * by the very same function a fresh session uses. Nothing here is random: the
 * same words and the same production always produce the same numbers, which is
 * what lets the vault show a score the player can trust before committing.
 */
function rescoreMaster(
  state: GameState,
  song: Song,
  overrides: {
    lyrics?: string;
    producerSkill?: number | null;
    beatQuality?: number;
    features?: Array<{ npc: NPC; relationship: number }>;
  } = {},
): StudioScores {
  const npcs = raw(state.npcs) as NPC[];
  const features =
    overrides.features ??
    (song.featuredArtists ?? [])
      .map((id) => npcs.find((n) => n.id === id))
      .filter((n): n is NPC => Boolean(n))
      .map((npc) => ({ npc, relationship: npc.relationshipScore ?? 0 }));

  const ghostwriter = song.ghostwriterId ? ghostwriterById(song.ghostwriterId) : undefined;

  return scoreStudioSession({
    stats: state.player!.stats,
    lyrics: overrides.lyrics ?? song.lyrics ?? '',
    genre: song.genre,
    bpm: song.bpm ?? 90,
    mood: song.mood ?? 'defiant',
    vocals: song.vocalSettings ?? { ...VOCAL_DEFAULTS },
    producerSkill:
      overrides.producerSkill !== undefined ? overrides.producerSkill : song.producerSkill ?? null,
    beatQuality: overrides.beatQuality ?? song.beatQuality ?? 50,
    features,
    effort: 2,
    ghostwriterSkill: ghostwriter ? ghostwriter.skill : null,
    // Re-recording happens in the same room as the first take, so the crew's
    // contribution has to be the same number both times — otherwise a
    // re-record would silently drop the engineer's work.
    crewProductionBonus: crewBonuses(raw(state.crew) as CrewMember[]).productionBonus,
    // The room the take was ACTUALLY made in, read off the record rather than
    // off the player's current studio. Buying a better mic today must not
    // re-track a master cut last month, and a room rented once is not a room
    // you still have. A master from before the room system carries no figure
    // and falls back to the player's own gear, which is what it was made on.
    studioBonus: song.studioBonus ?? roomProductionBonus(state.studio?.levels, null).bonus,
  });
}

/**
 * Write a fresh score set onto a master, keeping whatever the mix session had
 * already achieved.
 *
 * A mix is a finished artefact: rewriting the words does not un-mix the record,
 * so a master that has been through a mix session keeps its production figures
 * and only the dimensions the edit actually touched move. New material is the
 * exception — a new beat means the mix is gone, and `keepProduction` is false.
 */
function applyRescore(song: Song, fresh: StudioScores, keepProduction: boolean) {
  song.lyricsQuality = fresh.lyricsQuality;
  song.vocalPerformance = fresh.vocalPerformance;
  song.chemistry = fresh.chemistry;
  if (!keepProduction) {
    song.productionQuality = fresh.productionQuality;
    song.productionCeiling = fresh.productionCeiling;
  }
  song.commercialPotential = fresh.commercialPotential;
  song.criticalPotential = fresh.criticalPotential;
  // Re-blended from what is actually on the record now, through the same two
  // functions the record path uses, so the two can never drift apart.
  song.quality = applyMoodPenalty(
    blendQuality({
      lyricsQuality: song.lyricsQuality,
      productionQuality: song.productionQuality ?? 0,
      vocalPerformance: song.vocalPerformance,
      chemistry: song.chemistry,
    }),
    song.mood ?? 'defiant',
    song.genre,
  );
}

/** Total units a song has done in its last seven days, across every platform. */
function recentWeek(state: GameState, songId: string): number {
  const st = state.platformStats?.[songId];
  if (!st) return 0;
  let total = 0;
  for (const key of Object.keys(st.byPlatform)) {
    const slice = st.byPlatform[key];
    for (let i = Math.max(0, slice.d.length - 7); i < slice.d.length; i++) total += slice.d[i];
  }
  return total;
}

/** Lifetime units for a song, straight off its platform state. */
function lifetimeUnits(state: GameState, songId: string): number {
  const st = state.platformStats?.[songId];
  if (!st) return 0;
  let total = 0;
  for (const key of Object.keys(st.byPlatform)) total += st.byPlatform[key].t;
  return total;
}

/**
 * How much of a second wind a remix gives back to the record it reworks.
 *
 * Three things decide it, and they are the three the player can actually see:
 *
 *  - **How big the original is.** A remix multiplies a record; it does not
 *    replace it. A remix of something nobody heard multiplies a small number
 *    and stays small, which is why this is driven off real lifetime units and
 *    not off the original's `quality`.
 *  - **How well timed it is.** A remix lands best on a record that still has
 *    life in it — climbing, or just starting to come down. Dropping one on a
 *    song that is already dead is a footnote, and dropping one on a record in
 *    its first days wastes the move because the record is doing that work
 *    already.
 *  - **Who is on it.** A real feature brings their own audience with them.
 */
function revivalFor(
  state: GameState,
  original: Song,
  remix: Song,
): { power: number; width: number; reason: string } {
  const lifetime = lifetimeUnits(state, original.id);
  const week = recentWeek(state, original.id);
  const st = state.platformStats?.[original.id];
  const ageDays = st ? dateToSerial(state.gameDate) - st.release : 0;

  // A record nobody heard gives almost nothing back. 10M units is a real
  // record; a million is a local one.
  const size = Math.min(1, Math.log10(1 + lifetime) / 7.4);

  // Timing: peaks when the record is past its opening fortnight but still
  // moving. Both tails fade out.
  const traction = Math.min(1, Math.log10(1 + week) / 6.6);
  const freshness = ageDays < 14 ? ageDays / 14 : Math.max(0.15, 1 - (ageDays - 14) / 420);
  const timing = traction * freshness;

  // The feature's own pull. Capped hard — a cosign helps, it does not carry.
  let featureFactor = 0;
  for (const id of remix.featuredArtists ?? []) {
    const npc = (raw(state.npcs) as NPC[]).find((n) => n.id === id);
    if (npc) featureFactor = Math.max(featureFactor, Math.min(1, npc.fame / 90));
  }

  const power = 0.25 + size * 1.5 * timing + featureFactor * 0.55;
  const width = 9 + size * 10;

  const reason =
    power < 0.45
      ? 'the remix did not find much of an audience to build on'
      : featureFactor > 0.5
        ? 'a big feature put the record back in front of people'
        : 'the timing caught the record while it still had momentum';

  return { power: Math.min(3.2, power), width, reason };
}

/**
 * Plant a second wind on a record, at a given age in its own life.
 *
 * The record is the source of truth: `song.revivals` is what gets saved, and
 * the streaming engine copies it into whatever state it rebuilds on load. The
 * derived state is updated here too when it already exists, so the very next
 * tick sees the push without waiting for a rebuild.
 */
function plantRevival(
  state: GameState,
  songId: string,
  revival: { power: number; width: number; reason: string },
  atAge: number,
) {
  const song = state.songs.find((s) => s.id === songId) ?? state.npcSongs.find((s) => s.id === songId);
  const st = state.platformStats?.[songId];

  // Nothing to attach to. NOTE the guard is `&&`, not `!list`: a record being
  // given its FIRST second wind has no `revivals` array yet, and an early
  // return on that read as "the push silently did nothing" — which is exactly
  // what a remix of a fresh record looks like.
  if (!song && !st) return;

  // Idempotent on the day, so re-releasing or re-entering a project cannot
  // stack the same push twice.
  const existing = song?.revivals ?? st?.revivals ?? [];
  if (existing.some((r) => r.at === atAge)) return;

  const entry = { at: atAge, power: revival.power, width: revival.width, reason: revival.reason };
  if (song) {
    const own = song.revivals ?? (song.revivals = []);
    own.push(entry);
    // A record cannot carry an unbounded history of pushes.
    if (own.length > 6) own.shift();
  }
  if (st) {
    const derived = st.revivals ?? (st.revivals = []);
    if (!derived.some((r) => r.at === atAge)) derived.push({ ...entry });
    if (derived.length > 6) derived.shift();
  }
}

/**
 * Pick `count` random artists from the roster without sorting it.
 *
 * The obvious `filter(artist).sort(random).slice(n)` is O(n log n) over the
 * whole roster AND allocates a full copy of every artist — 4,254 objects just
 * to end up with 5. Reservoir sampling does it in a single O(n) pass with no
 * intermediate array, and because it only ever compares against a set of
 * `count` slots it does not care how large the roster grows.
 */
function pickRandomArtists(npcs: NPC[], count: number): NPC[] {
  const picked: NPC[] = [];
  let seen = 0;
  for (const npc of npcs) {
    if (npc.role !== 'artist') continue;
    seen++;
    if (picked.length < count) {
      picked.push(npc);
      continue;
    }
    // Replace a random incumbent with probability count/seen.
    const j = Math.floor(Math.random() * seen);
    if (j < count) picked[j] = npc;
  }
  return picked;
}

// ─── PERFORMANCE: DISABLE IMMER AUTO-FREEZE ──────────────────────────────
// Immer's `autoFreeze` deep-freezes the ENTIRE returned state tree after every
// `set()`. With ~12,000 NPCs (each with a nested `memoryLog` array) that is a
// full walk of the roster on every single action — measured at ~285 ms per
// turn on its own.
//
// Freezing is a development safety net that catches accidental mutation outside
// of a producer. This store only ever mutates inside `set()`, and every action
// already goes through immer's draft, so the net catches nothing here while
// costing real time. Turning it off is the documented remedy for large stores.
setAutoFreeze(false);

// ─── CREATE STORE ─────────────────────────────────────────────────────────

// ─── YOUR OWN LABEL: STORE HELPERS ─────────────────────────────────────────
//
// The engine is `sim/label.ts`. These are the bits that touch the game state:
// moving money in and out of the label's account, writing the mailbox and the
// feed, the artists' own work cycle, and the daily/monthly tick.

/** Everybody the label still has a live claim on. */
function labelSigneeIds(label: PlayerLabel): Set<string> {
  return new Set(
    label.roster
      .filter((s) => s.status === 'active' || s.status === 'dispute' || s.status === 'expiring')
      .map((s) => s.npcId),
  );
}

/** How many people follow the label's pages: its roster's audience, and its name. */
export function labelFollowers(label: PlayerLabel, npcs: NPC[]): number {
  const byId = new Map(npcs.map((n) => [n.id, n]));
  const roster = label.roster.reduce((a, s) => { const n = byId.get(s.npcId); return a + (n ? audienceOf(n) * 0.12 : 0); }, 0);
  return Math.round(400 + roster + label.reputation * 120 + label.roster.length * 300);
}

/**
 * The label posts from its own account. Your page is yours; the label has a
 * page of its own, and the office runs it.
 */
function labelPost(state: GameState, label: PlayerLabel, posts: [SocialApp, string, PostKind][], songId?: string, tagNpcId?: string): void {
  const npcs = raw(state.npcs) as NPC[];
  const audience = labelFollowers(label, npcs);
  const tag = tagNpcId ? npcs.find((n) => n.id === tagNpcId) : undefined;
  const minute = gameMinute(state);
  posts.forEach(([app, content, kind], i) => {
    const post: SocialPost = {
      id: uuidv4(), platform: app, authorId: `label:${label.id}`, authorName: label.name, content,
      likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 40,
      daySerial: dateToSerial(state.gameDate), kind, relatedSongId: songId, tags: tag ? [{ id: tag.id, name: tag.name }] : undefined,
    };
    livenPost(state, post, { at: minute + 20 + i * 40, audience, heat: 1 });
    state.socialPosts.unshift(post);
  });
}

function labelEvent(label: PlayerLabel, serial: number, text: string, tone: LabelEvent['tone'] = 'neutral'): void {
  label.events.unshift({ serial, text, tone });
  if (label.events.length > 100) label.events.length = 100;
}

function labelMail(state: GameState, subject: string, body: string): void {
  const name = state.label?.name ?? 'Your label';
  state.mailbox.unshift({
    id: uuidv4(),
    from: 'label_office',
    fromName: `${name} — office`,
    subject,
    body,
    timestamp: new Date().toISOString(),
    read: false,
    type: 'general',
  });
}

function labelSpend(label: PlayerLabel, amount: number): void {
  label.cash -= amount;
  label.monthCosts += amount;
}

function labelEarn(label: PlayerLabel, amount: number): void {
  label.cash += amount;
  label.monthRevenue += amount;
}

/** A label's legal read: its own business-affairs hire, or the player's lawyer. */
function labelLegalSkill(state: GameState): number {
  const own = state.label ? staffSkill(state.label.staff, 'legal') : 0;
  return Math.max(own, playerNegotiatorSkill(state, 'lawyer') * 0.8);
}

/** How good the player is at the table: business sense plus their manager. */
function labelNegotiatorSkill(state: GameState): number {
  const biz = state.player?.stats.businessKnowledge ?? 30;
  const mgr = playerNegotiatorSkill(state, 'manager');
  return Math.round(Math.min(100, biz * 0.6 + mgr * 0.5));
}

/**
 * Fill in everything a label saved by an older build is missing. Safe to call
 * on every load and before every action: it only adds what is absent.
 */
function normalizeLabel(label: PlayerLabel, serial: number): void {
  for (const k of ['roster', 'alumni', 'pitches', 'prospects', 'staff', 'history', 'events', 'submissions'] as const) {
    if (!Array.isArray(label[k])) (label as unknown as Record<string, unknown[]>)[k] = [];
  }
  if (!label.policy) label.policy = { ...DEFAULT_POLICY };
  if (!label.studio) label.studio = emptyStudio();
  if (!label.studio.gear) label.studio.gear = emptyStudio().gear;
  for (const s of [...label.roster, ...label.alumni]) {
    s.terms = normalizeTerms(s.terms ?? {});
    if (typeof s.fund !== 'number') s.fund = 0;
    if (!Array.isArray(s.albums)) s.albums = [];
    if (typeof s.albumsDelivered !== 'number') s.albumsDelivered = 0;
    if (typeof s.singlesSinceAlbum !== 'number') s.singlesSinceAlbum = s.releases?.length ?? 0;
    if (typeof s.optionsUsed !== 'number') s.optionsUsed = 0;
    if (typeof s.workSerial !== 'number') s.workSerial = serial + 7;
    // A v1 "release request" becomes the artist's next demo, straight away.
    if (s.requestSerial !== undefined) { s.workSerial = Math.min(s.workSerial, serial); s.requestSerial = undefined; }
    if (s.inStudio && !s.inStudio.kind) {
      const old = s.inStudio as unknown as { until: number; tier: LabelReleaseTier; cost: number; quality: number; marketing: number };
      s.inStudio = { kind: 'single', title: generateSongTitle(), trackCount: 1, until: old.until, tier: old.tier, cost: old.cost, quality: old.quality, marketing: old.marketing };
    }
  }
  for (const p of label.pitches) {
    p.terms = normalizeTerms(p.terms ?? {});
    p.wants = normalizeTerms(p.wants ?? {});
    if (p.agreedTerms) p.agreedTerms = normalizeTerms(p.agreedTerms);
  }
}

/** Move a signee off the roster and into the alumni list. */
function retireSignee(state: GameState, label: PlayerLabel, s: LabelSignee, status: LabelSignee['status']): void {
  s.status = status;
  s.inStudio = undefined;
  s.videoShoot = undefined;
  s.requestSerial = undefined;
  s.demand = undefined;
  s.rivalOffer = undefined;
  label.roster = label.roster.filter((x) => x.npcId !== s.npcId);
  label.alumni.unshift(s);
  if (label.alumni.length > 30) label.alumni.length = 30;
  for (const sub of label.submissions) {
    if (sub.npcId === s.npcId && (sub.status === 'pending' || sub.status === 'reworking')) sub.status = 'rejected';
  }
  const npc = state.npcs.find((n) => n.id === s.npcId);
  if (npc?.team?.label === label.name) npc.team = { ...npc.team, label: undefined };
}

/** Write signee fame (and the label's name) back onto the live roster. */
function mirrorSigneesToRoster(state: GameState, rawNPCs: NPC[]): void {
  const label = state.label;
  if (!label || label.roster.length === 0) return;
  const byId = new Map(label.roster.map((s) => [s.npcId, s]));
  const arr = state.npcs;
  // Ids are read off the plain snapshot so the 11.6k-row scan never creates a
  // draft for somebody who is not on the label.
  for (let i = 0; i < rawNPCs.length; i++) {
    const s = byId.get(rawNPCs[i].id);
    if (!s) continue;
    const npc = arr[i];
    if (!npc || npc.id !== s.npcId) continue;
    npc.fame = Math.round(s.fame * 10) / 10;
    const live = s.status === 'active' || s.status === 'dispute' || s.status === 'expiring';
    if (live && npc.team?.label !== label.name) npc.team = { ...(npc.team ?? {}), label: label.name };
    rawNPCs[i].fame = npc.fame;
  }
}

/**
 * Give a brand-new record its first day of numbers at once, so it is never
 * sitting on zero until the next midnight.
 */
function seedLabelSong(state: GameState, song: Song, npc: NPC, serial: number): void {
  const stats = state.platformStats ?? (state.platformStats = {});
  if (stats[song.id]) return;
  const ctx = contextForSong({
    song,
    isPlayer: false,
    popularity: npc.fame,
    fanbase: npcFanbase(npc.fame),
    genre: npc.genre ?? 'hip_hop',
    homeCountry: song.ownerCountry ?? npc.country,
    hasVideo: !!song.hasVideo,
  });
  const st = seedStreamState(song, ctx, serial);
  stats[song.id] = st;
  const totals = songTotals(st);
  song.weeklyStreams = totals.week;
  song.totalStreams = totals.lifetime;
}

/** Put a finished single or album out. */
function releaseLabelRecord(
  state: GameState,
  label: PlayerLabel,
  s: LabelSignee,
  npc: NPC,
  serial: number,
  rec: LabelSession,
  log: string[],
  how: 'release' | 'leak' = 'release',
): Song[] {
  const eff = marketingEfficiency(staffSkill(label.staff, 'marketing'));
  const radio = staffSkill(label.staff, 'radio') * 20;
  const artist = { ...npc, fame: s.fame };
  const made: Song[] = [];
  const count = rec.kind === 'album' ? Math.max(2, rec.trackCount) : 1;
  for (let i = 0; i < count; i++) {
    const song = createNPCSong(artist, state.gameDate);
    if (i === 0 && rec.kind === 'single') song.title = rec.title;
    // The focus track carries the campaign; the deep cuts ride along.
    const spread = rec.kind === 'album' ? (unit(`trk|${s.npcId}|${serial}|${i}`) - 0.55) * 16 : 0;
    song.quality = Math.max(10, Math.min(99, Math.round(rec.quality + spread)));
    const share = rec.kind === 'album' ? (i === 0 ? 0.45 : 0.55 / (count - 1)) : 1;
    // The lead track is the single; the rest are heard by the fans who press
    // play on the whole thing. Better albums keep more people listening.
    if (rec.kind === 'album' && i > 0) {
      song.streamWeight = Math.round((0.1 + Math.max(0, rec.quality - 40) / 300 + unit(`dc|${song.id}`) * 0.08) * 100) / 100;
    }
    song.marketingBudget = how === 'leak' ? 0 : Math.round(rec.marketing * share * eff + (i === 0 ? radio : radio * 0.2));
    song.labelName = label.name;
    state.npcSongs.push(song);
    seedLabelSong(state, song, artist, serial);
    s.releases.push(song.id);
    made.push(song);
  }

  const lead = made[0];
  let albumTitle = '';
  if (rec.kind === 'album') {
    albumTitle = rec.title;
    const albums = state.npcAlbums ?? (state.npcAlbums = []);
    const id = `alb_label_${uuidv4()}`;
    albums.push({
      id,
      title: albumTitle,
      songs: made.map((x) => x.id),
      releaseDate: lead.releaseDate,
      totalStreams: 0,
      totalEarnings: 0,
      certifications: [],
      ownerId: npc.id,
      ownerName: npc.name,
      ownerCountry: npc.country,
      type: made.length >= 7 ? 'album' : 'ep',
      coverSeed: hashString(`label-cover|${id}`),
      releaseSerial: serial,
    } as (typeof albums)[number]);
    s.albums.push(id);
    s.albumsDelivered += 1;
    s.singlesSinceAlbum = 0;
  } else {
    s.releasesDelivered += 1;
    s.singlesSinceAlbum += 1;
  }

  s.lastReleaseSerial = serial;
  s.inStudio = undefined;
  s.workSerial = serial + workGap(npc, `gap|${s.npcId}|${serial}`) + (rec.kind === 'album' ? 30 : 0);
  s.fame = Math.max(1, Math.min(100, s.fame + releaseFameBump(s, rec.quality, lead.marketingBudget) * (rec.kind === 'album' ? 1.6 : 1)));
  s.mood = Math.max(0, Math.min(100, s.mood + (how === 'leak' ? -5 : 3)));
  const what = rec.kind === 'album' ? `the ${made.length >= 7 ? 'album' : 'EP'} "${albumTitle}" (${made.length} tracks)` : `"${lead.title}"`;
  const whatCap = what.charAt(0).toUpperCase() + what.slice(1);
  s.notes.unshift(how === 'leak' ? `${whatCap} leaked before you answered.` : `Released ${what} — quality ${rec.quality}.`);
  if (s.notes.length > 12) s.notes.length = 12;

  const verdict = rec.quality >= 75 ? 'The office thinks it is a hit.' : rec.quality >= 55 ? 'Solid record.' : 'Not their best. It happens.';
  labelEvent(
    label,
    serial,
    how === 'leak' ? `${whatCap} by ${s.name} leaked online. No campaign, no rollout.` : `${s.name} released ${what}. ${verdict}`,
    how === 'leak' ? 'bad' : rec.quality >= 60 ? 'good' : 'neutral',
  );
  log.push(`💿 ${label.name}: ${s.name} — ${what} ${how === 'leak' ? 'leaked' : 'is out'}.`);
  pushNotification(state, {
    kind: 'business',
    title: how === 'leak' ? `${s.name}'s record leaked` : `${label.name}: ${rec.kind === 'album' ? albumTitle : `"${lead.title}"`} is out`,
    body: how === 'leak' ? 'It is out there with no campaign behind it.' : `${s.name}'s new ${rec.kind === 'album' ? 'project' : 'record'} is live on every platform.`,
    artSeed: `song|${lead.id}`,
    action: { type: 'song', id: lead.id },
  });
  // The label announces it on the label's own pages — not yours.
  if (state.player && how === 'release') {
    labelPost(state, label, rec.kind === 'album'
      ? [['chirp', `OUT NOW 💿 ${s.name} — "${albumTitle}". ${made.length} tracks. Front to back.`, 'announce'], ['snapgram', `${s.name} · "${albumTitle}" · out everywhere`, 'cover']]
      : [['chirp', `New music from ${s.name} 🔥 "${lead.title}" is out now. Go run it up.`, 'announce'], ['snapgram', `${s.name} — "${lead.title}" · out now`, 'cover']], lead.id, s.npcId);
  }
  return made;
}

/** Book the studio for an approved demo. Returns a reason when it cannot. */
function startLabelSession(
  _state: GameState,
  label: PlayerLabel,
  s: LabelSignee,
  sub: Pick<LabelSubmission, 'id' | 'kind' | 'title' | 'trackCount' | 'quality'> | null,
  tier: LabelReleaseTier,
  serial: number,
): string | null {
  if (s.inStudio) return `${s.name} is already in the studio.`;
  const kind = sub?.kind ?? 'single';
  if (s.terms.allIn || s.terms.dealType === 'distribution') {
    // Their money, their call on the budget.
    const own = s.terms.dealType === 'distribution' ? tier : allInTier(s.fund, kind, tier, label.studio, label.staff);
    if (!own) return `${s.name}'s recording fund is down to ${money(s.fund)} — not enough for a session. Top it up or wait.`;
    tier = own;
  }
  const plan = sessionPlan({ kind, tier, studio: label.studio, staff: label.staff, marketingCommit: s.terms.allIn ? 0 : s.terms.marketingCommit });
  const cost = plan.recording + plan.marketing;
  const selfFunded = s.terms.allIn || s.terms.dealType === 'distribution';
  if (!selfFunded) {
    if (label.cash < 0) return 'The label is overdrawn. Put money in first.';
    if (label.cash < cost) return `That costs ${money(cost)} (recording ${money(plan.recording)} + marketing ${money(plan.marketing)}). The label has ${money(label.cash)}.`;
    labelSpend(label, cost);
    s.recoupBalance += plan.recording * recoupShare(s.terms.dealType, 'recording') + plan.marketing * recoupShare(s.terms.dealType, 'marketing');
  } else if (s.terms.allIn) {
    s.fund = Math.max(0, s.fund - cost);
    // Booking your own label's studio: the label is paid for the room.
    if (label.studio.tier > 0) {
      const rent = Math.round(plan.recording * 0.35);
      labelEarn(label, rent);
    }
  }
  const baseQuality = sub?.quality ?? releaseQuality(s.fame, tier, 0, Math.random());
  s.inStudio = {
    submissionId: sub?.id,
    kind,
    title: sub?.title ?? generateSongTitle(),
    trackCount: sub?.trackCount ?? 1,
    until: serial + plan.days,
    tier,
    cost,
    quality: Math.round(Math.max(10, Math.min(99, baseQuality + plan.qualityBonus))),
    marketing: plan.marketing,
    selfFunded,
  };
  if (label.studio.tier > 0) label.studio.busyDays = Math.min(30, label.studio.busyDays + plan.days);
  s.mood = Math.min(100, s.mood + (tier === 'major' ? 5 : tier === 'standard' ? 3 : 1));
  labelEvent(
    label,
    serial,
    `${s.name} is in the studio — ${kind === 'album' ? `the album "${s.inStudio.title}" (${s.inStudio.trackCount} tracks, ${tier === 'major' ? 'big' : tier === 'standard' ? 'proper' : 'tight'} budget)` : `"${s.inStudio.title}", ${RELEASE_TIERS[tier].label.toLowerCase()}`}${selfFunded && s.terms.allIn ? ' on their own fund' : ''}. Out in ${plan.days} days.`,
    'neutral',
  );
  return null;
}

/** Schedule a video. The label pays, or the artist pays from their fund. */
function startLabelVideo(state: GameState, label: PlayerLabel, s: LabelSignee, song: Song, budget: number, days: number, payer: 'label' | 'fund', serial: number): string | null {
  if (s.videoShoot) return `${s.name} is already shooting a video.`;
  if ((state.videos ?? []).some((v) => v.songId === song.id && !v.removed)) return 'That record already has a video.';
  if (payer === 'label') {
    if (label.cash < budget) return `The shoot costs ${money(budget)}. The label has ${money(label.cash)}.`;
    labelSpend(label, budget);
    s.recoupBalance += budget * recoupShare(s.terms.dealType, 'video');
  } else {
    if (s.fund < budget) return `${s.name} has ${money(s.fund)} left in their fund.`;
    s.fund -= budget;
  }
  const director = Math.min(100, 30 + Math.log10(Math.max(1000, budget)) * 12);
  const seed = videoSeed(`vid-label-${song.id}`);
  const quality = Math.round(shootQuality({ directorSkill: director, budget, songQuality: song.quality, seed }));
  s.videoShoot = { songId: song.id, until: serial + days, budget, quality };
  labelEvent(label, serial, `${s.name} is shooting a video for "${song.title}" (${money(budget)}${payer === 'fund' ? ', their own fund' : ''}).`, 'neutral');
  return null;
}

function publishLabelVideo(state: GameState, label: PlayerLabel, s: LabelSignee, npc: NPC, serial: number, log: string[]): void {
  const shoot = s.videoShoot;
  s.videoShoot = undefined;
  if (!shoot) return;
  const song = state.npcSongs.find((x) => x.id === shoot.songId);
  if (!song) return;
  const videos = state.videos ?? (state.videos = []);
  if (videos.some((v) => v.songId === song.id && !v.removed)) return;
  const id = `vid-label-${song.id}`;
  const seed = videoSeed(id);
  const video = createVideo({
    id,
    songId: song.id,
    songTitle: song.title,
    title: videoTitle(song.title, seed, npc.genre),
    artistId: npc.id,
    artistName: npc.name,
    artistCountry: song.ownerCountry ?? npc.country,
    artistGenre: npc.genre,
    directorId: 'label-director',
    directorName: npcDirectorName(seed),
    concept: npcConcept(seed),
    visualStyle: npcStyle(seed),
    quality: shoot.quality,
    budget: shoot.budget,
    marketingBudget: Math.round(shoot.budget * 0.3 * marketingEfficiency(staffSkill(label.staff, 'marketing'))),
    uploadSerial: serial,
    uploadDate: formatDateString(state.gameDate),
    isPlayer: false,
    songQuality: song.quality,
  });
  const opening = Math.round(Math.pow(Math.max(5, s.fame) / 100, 2) * 26_000 * (0.5 + shoot.quality / 200) * (1 + shoot.budget / 60_000));
  video.views = opening;
  video.hist = [...new Array(29).fill(0), opening];
  video.peakDay = opening;
  video.likes = Math.round(opening * 0.05);
  video.dislikes = Math.round(opening * 0.004);
  video.commentCount = Math.round(opening * 0.0035);
  videos.unshift(video);
  song.hasVideo = true;
  s.mood = Math.min(100, s.mood + 3);
  labelEvent(label, serial, `${s.name}'s video for "${song.title}" is up — quality ${shoot.quality}.`, shoot.quality >= 60 ? 'good' : 'neutral');
  labelPost(state, label, [['clip', `${s.name} — "${song.title}" (Official Video) 🎬 out now`, 'bts']], song.id, s.npcId);
  log.push(`🎬 ${label.name}: ${s.name}'s "${song.title}" video is live.`);
  pushNotification(state, {
    kind: 'business',
    title: `${s.name}: "${song.title}" video is live`,
    body: `${label.name} premiered the visual.`,
    artSeed: `video|${id}`,
    action: { type: 'video', id },
  });
}

/** After a single drops: does it get a video, and who pays? */
function autoVideoAfterRelease(state: GameState, label: PlayerLabel, s: LabelSignee, song: Song, serial: number): void {
  if (s.videoShoot) return;
  if (s.terms.allIn) {
    const tier = [...VIDEO_TIERS].reverse().find((v) => v.budget <= s.fund * 0.35) ?? (VIDEO_TIERS[0].budget <= s.fund ? VIDEO_TIERS[0] : null);
    if (tier) startLabelVideo(state, label, s, song, tier.budget, tier.days, 'fund', serial);
    return;
  }
  if (s.terms.dealType === 'distribution') {
    if (song.quality >= 60 && s.fame >= 20) startLabelVideo(state, label, s, song, VIDEO_TIERS[0].budget, VIDEO_TIERS[0].days, 'fund', serial);
    return;
  }
  // Promised in the contract: the label owes it.
  if (s.terms.videoBudget > 0) {
    const err = startLabelVideo(state, label, s, song, s.terms.videoBudget, s.terms.videoBudget >= 40_000 ? 18 : s.terms.videoBudget >= 10_000 ? 10 : 5, 'label', serial);
    if (err) {
      s.mood = Math.max(0, s.mood - 8);
      labelEvent(label, serial, `The label could not pay ${s.name}'s contracted video. They noticed.`, 'bad');
    }
    return;
  }
  const p = label.policy.videos;
  if (p === 'all' || (p === 'hits' && song.quality >= 65)) {
    const tier = song.quality >= 75 ? VIDEO_TIERS[2] : VIDEO_TIERS[1];
    const pick = label.cash >= tier.budget * 2 ? tier : VIDEO_TIERS[0];
    startLabelVideo(state, label, s, song, pick.budget, pick.days, 'label', serial);
  }
}

/** Whether policy lets the office say yes to this demo without the player. */
function policyApproves(label: PlayerLabel, sub: LabelSubmission): boolean {
  if (label.policy.approve === 'all') return true;
  if (label.policy.approve === 'good') return sub.estimate >= label.policy.threshold;
  return false;
}

function policyTier(label: PlayerLabel, sub: LabelSubmission): LabelReleaseTier {
  return label.policy.tier === 'ask' ? sub.askTier : label.policy.tier;
}

/**
 * The label's day (or days). Called once per turn from `advanceTurn`, after
 * the streaming engine has run, with what the label's records earned.
 */
function labelTick(
  state: GameState,
  rawNPCs: NPC[],
  labelRevenueBySong: Record<string, number>,
  serial: number,
  days: number,
  log: string[],
): void {
  const label = state.label;
  if (!label || !state.player) return;
  normalizeLabel(label, serial);
  const playerFame = blendedFame(state.player);
  const npcById = new Map<string, NPC>();
  const wanted = new Set<string>([...label.roster.map((s) => s.npcId), ...label.pitches.map((p) => p.npcId)]);
  for (const n of rawNPCs) if (wanted.has(n.id)) npcById.set(n.id, n);
  const legal = labelLegalSkill(state);
  const arSkill = staffSkill(label.staff, 'ar');
  const live = labelSigneeIds(label);
  let rosterChanged = false;

  // ── 1. The money the records made ──────────────────────────────────────
  for (const s of [...label.roster, ...label.alumni]) {
    if (!s.releases.length) continue;
    // On a distribution deal the artist owns the masters: once they leave, the
    // fee stops. Every other deal leaves the masters with the label for good.
    if (s.terms.dealType === 'distribution' && !live.has(s.npcId)) continue;
    let gross = 0;
    for (const id of s.releases) gross += labelRevenueBySong[id] ?? 0;
    if (gross <= 0) continue;
    const split = splitRevenue(s, gross);
    s.recoupBalance = Math.max(0, s.recoupBalance - split.recouped);
    s.grossEarned += gross;
    s.labelEarned += split.label;
    s.artistPaid += split.artist;
    s.monthGross += gross;
    labelEarn(label, split.label);
  }

  // ── 2. Records and videos finishing ────────────────────────────────────
  for (const s of label.roster) {
    const npc = npcById.get(s.npcId);
    if (s.inStudio && s.inStudio.until <= serial) {
      if (!npc) { s.inStudio = undefined; continue; }
      const rec = s.inStudio;
      const made = releaseLabelRecord(state, label, s, npc, serial, rec, log);
      const sub = rec.submissionId ? label.submissions.find((x) => x.id === rec.submissionId) : undefined;
      if (sub) sub.status = 'released';
      if (rec.kind === 'single' && made[0]) autoVideoAfterRelease(state, label, s, made[0], serial);
      rosterChanged = true;
    }
    if (s.videoShoot && s.videoShoot.until <= serial && npc) publishLabelVideo(state, label, s, npc, serial, log);
  }

  // ── 3. The artists at work ─────────────────────────────────────────────
  for (const s of label.roster) {
    if (s.status !== 'active' && s.status !== 'expiring') continue;
    const npc = npcById.get(s.npcId);
    const mine = label.submissions.filter((x) => x.npcId === s.npcId && (x.status === 'pending' || x.status === 'reworking'));

    // A rework comes back.
    for (const sub of mine) {
      if (sub.status !== 'reworking' || (sub.dueSerial ?? 0) > serial) continue;
      sub.status = 'pending';
      sub.submittedSerial = serial;
      const spread = arSkill > 0 ? (100 - arSkill) / 6 : 18;
      sub.estimate = Math.round(Math.max(5, Math.min(99, sub.quality + (unit(`rest|${sub.id}|${serial}`) - 0.5) * 2 * spread)));
      labelEvent(label, serial, `${s.name} sent back the new version of "${sub.title}".`, 'neutral');
      labelMail(state, `🎧 ${s.name}: new version of "${sub.title}"`, `They went back in. The office now rates it around ${sub.estimate}. Answer from My Label → A&R.`);
    }

    // Something new to pitch.
    if (!s.inStudio && mine.length === 0 && serial >= s.workSerial) {
      if (s.terms.allIn && s.fund < 2_000) {
        if (!s.notes[0]?.startsWith('Out of fund')) {
          s.notes.unshift('Out of fund — cannot make records until it is topped up.');
          labelEvent(label, serial, `${s.name} has spent their whole recording fund.`, 'bad');
          labelMail(state, `💸 ${s.name} is out of money`, `${s.name}'s all-in fund is spent. They cannot book sessions until you top it up (recoupable) from My Label → Roster.`);
        }
        s.workSerial = serial + 14;
        continue;
      }
      const kindTitle = generateSongTitle();
      const raw = makeSubmission({ npc, signee: s, serial, arSkill, title: kindTitle, roll: Math.random() });
      const sub: LabelSubmission = { id: uuidv4(), ...raw };
      label.submissions.unshift(sub);
      const auto = s.terms.creativeControl || s.terms.dealType === 'distribution';
      if (auto || policyApproves(label, sub)) {
        const tier = auto ? sub.askTier : policyTier(label, sub);
        const err = startLabelSession(state, label, s, sub, tier, serial);
        if (!err) {
          sub.status = 'approved';
          sub.auto = true;
          labelEvent(label, serial, auto
            ? `${s.name} is recording "${sub.title}" — creative control means they don't need your yes.`
            : `The office approved ${s.name}'s "${sub.title}" under your auto-approve rules.`, 'neutral');
        } else {
          labelMail(state, `🎧 ${s.name} wants to release "${sub.title}"`, `${sub.pitch}\n\nAuto-approve could not go ahead: ${err}\n\nAnswer from My Label → A&R.`);
        }
      } else {
        labelEvent(label, serial, `${s.name} pitched ${sub.kind === 'album' ? `an album, "${sub.title}"` : `a new single, "${sub.title}"`}. Office rates it ~${sub.estimate}.`, 'neutral');
        labelMail(
          state,
          `🎧 ${s.name} pitched ${sub.kind === 'album' ? 'an album' : 'a single'}: "${sub.title}"`,
          `${sub.pitch}\n\nOffice estimate: ${sub.estimate}/100. They're asking for a ${RELEASE_TIERS[sub.askTier].label.toLowerCase()}${sub.kind === 'album' ? ` (${sub.trackCount} tracks)` : ''}.\n\nApprove, send it back for another pass, or shelve it — My Label → A&R. Leave it too long and they'll get restless.`,
        );
      }
      s.workSerial = serial + 999; // the next one waits until this one is dealt with
      rosterChanged = true;
    }

    // Unanswered for too long: it leaks.
    for (const sub of mine) {
      if (sub.status !== 'pending' || serial - sub.submittedSerial < LEAK_DAYS || s.inStudio || !npc) continue;
      sub.status = 'leaked';
      releaseLabelRecord(state, label, s, npc, serial, {
        submissionId: sub.id, kind: sub.kind, title: sub.title, trackCount: sub.trackCount,
        until: serial, tier: 'demo', cost: 0, quality: Math.max(10, sub.quality - 4), marketing: 0,
      }, log, 'leak');
      label.reputation = Math.max(0, label.reputation - 1);
      s.loyalty = Math.max(0, s.loyalty - 6);
      labelMail(state, `⚠️ "${sub.title}" leaked`, `${s.name}'s record sat in your inbox for ${serial - sub.submittedSerial} days. It is online now — no campaign, no rollout. The label still owns it, but ${s.name} is not happy and the press is asking questions.`);
      rosterChanged = true;
    }
  }

  // ── 4. Deadlines: demands, rival offers, pitches, contracts ────────────
  for (const s of [...label.roster]) {
    if (s.demand && serial - s.demand.openedSerial > DEMAND_WINDOW_DAYS) {
      s.demand = undefined;
      s.mood = Math.max(0, s.mood - 15);
      s.loyalty = Math.max(0, s.loyalty - 10);
      labelEvent(label, serial, `${s.name}'s camp took the silence as a no.`, 'bad');
      if (s.mood < 25 && s.status === 'active') {
        s.status = 'dispute';
        labelEvent(label, serial, `${s.name} is refusing to record until this is fixed.`, 'bad');
        labelMail(state, `⚠️ ${s.name} is in dispute`, `${s.name}'s camp says they will not record another note for ${label.name} until the money is right. Settle it or let them go.`);
      }
    }
    if (s.rivalOffer && serial > s.rivalOffer.expiresSerial) {
      const offer = s.rivalOffer;
      s.rivalOffer = undefined;
      if (s.loyalty >= 70) {
        s.mood = Math.min(100, s.mood + 3);
        labelEvent(label, serial, `${s.name} turned down ${offer.labelName}. Loyal.`, 'good');
      } else {
        s.mood = Math.max(0, s.mood - 12);
        labelEvent(label, serial, `${s.name} wanted to talk about ${offer.labelName}'s offer and never heard back.`, 'bad');
        if (s.mood < 25 && s.status === 'active') s.status = 'dispute';
      }
    }
    if ((s.status === 'active' || s.status === 'dispute') && serial >= s.endsSerial) {
      s.status = 'expiring';
      const npc = npcById.get(s.npcId);
      if (npc) {
        const competing = s.fame >= 35 && unit(`renew|${s.npcId}|${serial}`) < 0.5;
        const wants = wantsFor(npc, s.terms.dealType, {
          labelRep: label.reputation,
          playerFame,
          relationship: npc.relationshipScore + (s.mood - 50) / 2 + (s.loyalty - 50) / 2,
          competing,
          allIn: s.terms.allIn,
        });
        label.pitches.unshift({
          id: uuidv4(),
          npcId: s.npcId,
          name: s.name,
          openedSerial: serial,
          expiresSerial: serial + 21,
          terms: { ...s.terms, advance: 0, signingBonus: 0, recordingFund: s.terms.allIn ? wants.recordingFund : 0 },
          wants,
          patience: patienceFor(npc) + (s.loyalty >= 60 ? 1 : 0),
          rounds: 0,
          status: 'open',
          competing: competing ? RIVAL_LABELS[hashString(`rc|${s.npcId}`) % RIVAL_LABELS.length] : undefined,
          renewal: true,
          warmth: s.loyalty >= 70 ? 0.04 : 0,
        });
      }
      const option = s.terms.optionYears > s.optionsUsed;
      labelEvent(label, serial, `${s.name}'s deal is up.${option ? ' You hold an option year.' : ''} Re-sign within three weeks or they walk.`, 'neutral');
      labelMail(
        state,
        `📝 ${s.name}'s contract is up`,
        `${s.name}'s deal with ${label.name} has run its course.\n\n` +
          (option ? `You hold ${s.terms.optionYears - s.optionsUsed} option year${s.terms.optionYears - s.optionsUsed === 1 ? '' : 's'}: you can extend them 12 months on the same terms without asking — they may not love it.\n\n` : '') +
          `Or open My Label → Deals to negotiate a renewal. If nothing is signed within 21 days they leave — and the records you released stay yours${s.terms.dealType === 'distribution' ? ', except on a distribution deal, where the masters go with them' : ''}.`,
      );
    }
  }

  for (const p of label.pitches) {
    if (p.status !== 'open' || serial <= p.expiresSerial) continue;
    p.status = 'expired';
    p.lastReply = p.competing ? `They signed with ${p.competing} instead.` : 'They stopped waiting.';
    if (p.renewal) {
      const s = label.roster.find((x) => x.npcId === p.npcId);
      if (s && s.status === 'expiring') {
        retireSignee(state, label, s, 'left');
        labelEvent(label, serial, `${s.name} left ${label.name} when the deal ran out.`, 'bad');
        rosterChanged = true;
      }
    } else {
      labelEvent(label, serial, `${p.name} stopped waiting on your offer.`, 'neutral');
    }
  }
  if (label.pitches.length > 30) label.pitches = label.pitches.filter((p, i) => p.status === 'open' || i < 20);
  if (label.submissions.length > 60) label.submissions = label.submissions.filter((x, i) => x.status === 'pending' || x.status === 'reworking' || i < 40);

  // ── 5. The scouting report, weekly ─────────────────────────────────────
  if (serial - label.prospectsSerial >= PROSPECT_REFRESH_DAYS) {
    label.prospects = pickProspects(rawNPCs, label, playerFame, arSkill, serial);
    label.prospectsSerial = serial;
  }
  void days;

  // ── 6. Month end ───────────────────────────────────────────────────────
  const key = monthKeyOf(state.gameDate);
  if (key !== label.monthKey) {
    labelMonthEnd(state, label, npcById, serial, playerFame, legal, log);
    label.monthKey = key;
    rosterChanged = true;
  }

  if (rosterChanged) mirrorSigneesToRoster(state, rawNPCs);
}

function labelMonthEnd(
  state: GameState,
  label: PlayerLabel,
  npcById: Map<string, NPC>,
  serial: number,
  playerFame: number,
  legal: number,
  log: string[],
): void {
  // Running costs.
  const salaries = label.staff.reduce((a, s) => a + s.salary, 0);
  const overhead = overheadFor(label);
  const fx = studioEffects(label.studio, label.staff);
  labelSpend(label, salaries + overhead + fx.upkeep);
  // Other artists renting the rooms.
  const rent = studioRent(label.studio, label.reputation);
  if (rent > 0) labelEarn(label, rent);
  label.studio.busyDays = 0;

  const charting = new Set<string>();
  for (const row of state.globalSongs ?? []) charting.add(row.itemId);
  for (const list of Object.values(state.charts ?? {})) for (const e of list) charting.add(e.songId);
  const songById = new Map<string, Song>();
  for (const s of state.npcSongs) songById.set(s.id, s);

  let chartingTotal = 0;
  let releasesThisMonth = 0;
  let disputes = 0;
  const marketingSkill = staffSkill(label.staff, 'marketing');
  const lines: string[] = [];

  for (const s of [...label.roster]) {
    const npc = npcById.get(s.npcId);
    const monthArtistShare = s.monthGross * 0.85 * (s.terms.royalty / 100);

    // 360: a cut of the road and the merch.
    if (s.terms.dealType === 'three_sixty' && s.status === 'active') {
      const side = threeSixtyMonthly(s.fame, s.terms.touringShare || 20);
      if (side > 0) { labelEarn(label, side); s.labelEarned += side; }
    }

    const charted = s.releases.filter((id) => charting.has(id)).length;
    chartingTotal += charted;
    const bestWeekly = Math.max(0, ...s.releases.map((id) => songById.get(id)?.weeklyStreams ?? 0));
    if (s.lastReleaseSerial !== undefined && serial - s.lastReleaseSerial <= 31) releasesThisMonth++;
    const pending = label.submissions.find((x) => x.npcId === s.npcId && x.status === 'pending');

    const before = s.fame;
    s.fame = monthlyFame(s, { serial, labelRep: label.reputation, chartingSongs: charted, bestWeekly });
    const mood = monthlyMood(npc, s, {
      serial, labelRep: label.reputation, labelBroke: label.cash < 0, marketingSkill, monthArtistShare,
      pendingDays: pending ? serial - pending.submittedSerial : 0,
    });
    s.mood = mood.mood;
    s.loyalty = mood.loyalty;
    if (mood.notes.length) {
      s.notes.unshift(mood.notes[0]);
      if (s.notes.length > 12) s.notes.length = 12;
    }

    lines.push(
      `• ${s.name}: ${money(s.monthGross)} gross` +
        (s.recoupBalance > 0 ? `, ${money(s.recoupBalance)} still to recoup` : ', recouped') +
        (s.terms.allIn ? ` · fund ${money(s.fund)}` : '') +
        ` · fame ${before.toFixed(0)}→${s.fame.toFixed(0)} · ${moodWord(s.mood).toLowerCase()}`,
    );
    s.monthGross = 0;

    if (s.status === 'dispute') {
      disputes++;
      // A dispute nobody settles ends in court, and courts are slow and expensive.
      if (unit(`court|${s.npcId}|${serial}`) < 0.25) {
        const fee = Math.round(settlementCost(s, legal) * 0.5);
        labelSpend(label, fee);
        retireSignee(state, label, s, 'left');
        labelEvent(label, serial, `${s.name} won their release in court. Legal fees: ${money(fee)}.`, 'bad');
        labelMail(state, `⚖️ ${s.name} is gone`, `${s.name}'s lawyers got them out of the contract. ${label.name} paid ${money(fee)} in legal fees. The records already released stay in your catalogue.`);
        log.push(`⚖️ ${s.name} left ${label.name} after a contract dispute.`);
        continue;
      }
    } else if (s.status === 'active') {
      if (s.mood < 15) {
        s.status = 'dispute';
        labelEvent(label, serial, `${s.name} has stopped returning the office's calls.`, 'bad');
      }
      const raise = maybeRaiseDemand(s, serial);
      if (raise) {
        s.demand = { kind: 'raise', openedSerial: serial, royalty: raise.royalty, bonus: raise.bonus, text: raise.text };
        labelEvent(label, serial, `${s.name} wants a better deal.`, 'neutral');
        labelMail(state, `💰 ${s.name} wants to renegotiate`, `${raise.text}\n\nAnswer from My Label → Roster within ${DEMAND_WINDOW_DAYS} days.`);
      }
      const monthlyTake = s.labelEarned / Math.max(1, (serial - s.signedSerial) / 30);
      const rival = maybeRivalOffer(s, serial, monthlyTake, legal);
      if (rival) {
        s.rivalOffer = { labelName: rival.labelName, royalty: rival.royalty, buyout: rival.buyout, openedSerial: serial, expiresSerial: serial + rival.window };
        s.lastRivalSerial = serial;
        labelEvent(label, serial, `${rival.labelName} is circling ${s.name}.`, 'bad');
        labelMail(
          state,
          `🦈 ${rival.labelName} wants ${s.name}`,
          `${rival.labelName} has offered ${s.name} ${rival.royalty}% and will pay ${label.name} ${money(rival.buyout)} to release them.\n\n` +
            `Match it, sell the contract, or refuse. ${s.loyalty >= 70 ? `${s.name} is loyal and has told them no for now — but they want to hear from you.` : `${s.name} is listening.`}`,
        );
      }
    }
  }

  // Reputation drifts toward what the label has actually done.
  const target = reputationTarget({
    playerFame,
    topSigneeFames: label.roster.map((s) => s.fame),
    chartingThisMonth: chartingTotal,
    disputes,
    radioSkill: staffSkill(label.staff, 'radio'),
    releasesThisMonth,
    studioTier: label.studio.tier,
  });
  label.reputation = Math.round((label.reputation + (target - label.reputation) * 0.15) * 10) / 10;

  if (label.cash < 0) {
    label.debtMonths += 1;
    labelEvent(label, serial, `The label is ${money(label.cash)} in the red (${label.debtMonths} month${label.debtMonths === 1 ? '' : 's'}).`, 'bad');
  } else {
    label.debtMonths = 0;
  }

  // A retired artist running the business side (or managing the acts) shows up in the numbers.
  const postRole = state.legacy?.mode === 'retired' ? state.legacy.postCareerRole : undefined;
  if ((postRole === 'executive' || postRole === 'manager') && label.monthRevenue > 0) {
    const bonus = Math.round(label.monthRevenue * (postRole === 'executive' ? 0.1 : 0.06));
    label.monthRevenue += bonus;
    label.cash += bonus;
  }

  const profit = label.monthRevenue - label.monthCosts;
  label.history.push({ key: label.monthKey, revenue: Math.round(label.monthRevenue), costs: Math.round(label.monthCosts), profit: Math.round(profit) });
  if (label.history.length > 36) label.history = label.history.slice(-36);

  labelMail(
    state,
    `📊 ${label.name} — statement for ${label.monthKey}`,
    `Revenue ${money(label.monthRevenue)} · Costs ${money(label.monthCosts)} (staff ${money(salaries)}, office ${money(overhead)}${fx.upkeep ? `, studio ${money(fx.upkeep)}` : ''})${rent ? ` · Studio rent in ${money(rent)}` : ''} · ` +
      `${profit >= 0 ? 'Profit' : 'Loss'} ${money(Math.abs(profit))}\n` +
      `Cash in the bank: ${money(label.cash)} · Reputation ${label.reputation.toFixed(0)}/100\n\n` +
      (lines.length ? lines.join('\n') : 'No artists on the roster yet. Open My Label → Scouting.') +
      (label.cash < 0 ? `\n\n⚠️ The label is overdrawn. Nothing can be funded until you put money in, and the artists can tell.` : ''),
  );
  if (profit !== 0) log.push(`🏷️ ${label.name}: ${profit >= 0 ? '+' : '−'}${money(Math.abs(profit)).replace('−', '')} this month.`);
  label.monthRevenue = 0;
  label.monthCosts = 0;
}

// ─── MOMENTS: STORE SIDE ───────────────────────────────────────────────────
// The engine is `sim/moments.ts`. This builds its picture of the world,
// delivers moments into PingChat and the team room, and applies what the
// player's choices do.

/** Reservoir-pick up to `k` NPCs matching `match`, in one pass. */
function sampleNpcs(npcs: NPC[], k: number, match: (n: NPC) => boolean): NPC[] {
  const out: NPC[] = [];
  let seen = 0;
  for (const n of npcs) {
    if (!match(n)) continue;
    seen++;
    if (out.length < k) out.push(n);
    else {
      const j = Math.floor(Math.random() * seen);
      if (j < k) out[j] = n;
    }
  }
  return out;
}

function momentWorld(state: GameState, npcs: NPC[], serial: number): MomentWorld | null {
  const p = state.player;
  if (!p) return null;
  const fame = blendedFame(p);
  const beefs = activeBeefIds(state);
  const generated = (n: NPC) => !isRealId(n.id) && n.isAvailable !== false;
  const home = p.country;
  return {
    serial,
    country: p.country,
    homeTier: state.home?.tier ?? 'family',
    playerName: p.artistName,
    playerFame: fame,
    money: p.career.money,
    energy: p.energy,
    charisma: p.stats.charisma,
    businessKnowledge: p.stats.businessKnowledge,
    crew: raw(state.crew) as CrewMember[],
    friends: sampleNpcs(npcs, 4, (n) => n.role === 'artist' && generated(n) && n.relationshipScore >= 15 && !beefs.has(n.id)),
    strangers: sampleNpcs(npcs, 6, (n) => n.role === 'artist' && generated(n) && n.country === home && Math.abs(n.fame - fame) <= 25 && n.relationshipScore > -20 && n.relationshipScore < 15),
    rivals: sampleNpcs(npcs, 3, (n) => n.role === 'artist' && generated(n) && (beefs.has(n.id) || n.relationshipScore <= -15)),
    bloggers: sampleNpcs(npcs, 2, (n) => (n.role === 'blogger' || n.role === 'media') && generated(n) && n.country === home),
    promoters: sampleNpcs(npcs, 2, (n) => (n.role === 'promoter' || n.role === 'venue_owner') && generated(n) && n.country === home),
    producers: sampleNpcs(npcs, 2, (n) => n.role === 'producer' && generated(n) && n.country === home && n.fame <= fame + 30),
    // A fan page from home writes to you; one from the other side of the world is rare.
    fans: p.career.fanbase < 400 ? [] : (() => { const local = sampleNpcs(npcs, 1, (n) => n.role === 'fan_account' && n.country === home); return local.length ? local : sampleNpcs(npcs, 1, (n) => n.role === 'fan_account' && fame >= 40); })(),
    stars: sampleNpcs(npcs, 3, (n) => n.role === 'artist' && generated(n) && n.fame >= fame + 8 && n.fame <= fame + 40 && n.relationshipScore >= 0),
    unreleased: (state.songs ?? []).filter((s) => !isSongReleased(s) && !s.archivedAt).slice(0, 3),
    hasUpcomingShow: state.scheduledShows.some((s) => s.serial - serial > 3),
    activeBeefIds: beefs,
    hasLawyer: state.crew.some((c) => c.role === 'lawyer'),
    hasPlayedShow: (state.shows ?? []).length > 0,
    ownsCar: (state.ownedAssets ?? []).some((a) => a.category === 'car'),
    releasedTitles: (state.songs ?? []).filter((s) => isSongReleased(s)).slice(-3).reverse().map((s) => s.title),
    released: (state.songs ?? []).filter((s) => isSongReleased(s)).map((s) => {
      const beat = (state.beats?.library ?? []).find((b) => b.usedOnSongId === s.id);
      return { id: s.id, title: s.title, quality: s.quality, streams: s.totalStreams ?? 0, age: Math.max(0, serial - releaseSerialOf(state, s, serial)), lease: beat?.license === 'lease', producerId: beat?.producerId, producerName: beat?.producerName };
    }),
    manager: (() => { const m = managerOf(state, npcs); return m ? { id: m.id, name: m.name, skill: managerNetwork(m), specialty: SPECIALTIES[managerSpecialty(m)].label } : undefined; })(),
    nextAward: (() => {
      // Presenters are asked by the ceremonies that are about you: home, your region, the global ones.
      const mineIds = new Set(bodiesFor(state).filter((b) => b.scope === 'global' || b.country === p.country || (b.scope === 'continental' && inRegion(b, p.country))).map((b) => b.id));
      const s0 = Object.values(state.awardSeasons ?? {}).filter((x) => x.phase !== 'done' && mineIds.has(x.bodyId) && x.cal.ceremony > serial).sort((a, b) => a.cal.ceremony - b.cal.ceremony)[0];
      const b = s0 ? bodiesFor(state).find((x) => x.id === s0.bodyId) : undefined;
      return s0 && b ? { name: b.name, daysOut: s0.cal.ceremony - serial, city: b.city, ceremonyMinute: s0.cal.ceremonyMinute } : undefined;
    })(),
    flags: { ...(state.lifeFlags ?? {}) },
    djs: sampleNpcs(npcs, 1, (n) => n.role === 'dj' && generated(n) && n.country === home),
    genre: p.genre,
    city: p.city,
    fanbase: p.career.fanbase,
  };
}

/** Put a moment into the world: a text in PingChat, or a knock on the door. */
function deliverMoment(state: GameState, draft: Omit<Moment, 'id' | 'createdSerial' | 'status'>, serial: number, status: Moment['status'] = 'open', dueSerial?: number): Moment {
  // Somebody you blocked cannot reach you.
  if (draft.npcId && isBlocked(state, draft.npcId) && status === 'open') status = 'expired';
  const m: Moment = { ...draft, id: uuidv4(), createdSerial: serial, status, dueSerial };
  const list = state.moments ?? (state.moments = []);
  list.unshift(m);
  if (list.length > 60) state.moments = list.filter((x, i) => x.status === 'open' || x.status === 'scheduled' || i < 40);
  if (status === 'open') announceMoment(state, m);
  return m;
}

function announceMoment(state: GameState, m: Moment): void {
  if (m.channel === 'dm' && m.npcId) {
    const thread = state.dmThreads[m.npcId] ?? { npcId: m.npcId, messages: [], unread: 0 };
    thread.messages.push({ id: uuidv4(), npcId: m.npcId, fromPlayer: false, content: m.body, timestamp: new Date().toISOString(), read: false, momentId: m.id });
    thread.unread += 1;
    state.dmThreads[m.npcId] = thread;
  }
  pushNotification(state, {
    kind: 'feature',
    title: m.title,
    body: m.channel === 'dm' ? 'New message in PingChat — they want an answer.' : m.channel === 'life' ? 'Something happened. It\'s on your dashboard.' : 'Your team needs a decision.',
    artSeed: `moment|${m.id}`,
    action: m.channel === 'dm' && m.npcId ? { type: 'artist', id: m.npcId } : undefined,
  });
}

function applyMomentEffects(state: GameState, effects: MomentEffect[], serial: number): void {
  const p = state.player;
  if (!p) return;
  const clampN = (n: number) => Math.max(0, Math.min(100, n));
  for (const e of effects) {
    switch (e.k) {
      case 'money': p.career.money += e.v; if (e.v > 0) p.career.totalEarnings += e.v; break;
      case 'fame':
        p.career.localFame = clampN(p.career.localFame + e.v);
        p.career.nationalFame = clampN(p.career.nationalFame + e.v * 0.3);
        break;
      case 'fans': p.career.fanbase = Math.max(0, p.career.fanbase + e.v); break;
      case 'momentum': addMomentum(state, e.v); break;
      case 'reputation': p.career.reputation = clampN(p.career.reputation + e.v); break;
      case 'energy': p.energy = Math.max(0, Math.min(p.maxEnergy ?? MAX_ENERGY, p.energy + e.v)); break;
      case 'rel': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (n) {
          n.relationshipScore = Math.max(-100, Math.min(100, n.relationshipScore + e.v));
          n.lastReachOut = serial;
        }
        break;
      }
      case 'heat': nudgeBeef(state, e.npcId, e.v, serial, e.win); break;
      case 'startBeef': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (!n || n.role !== 'artist' || state.beefs.some((b) => b.npcId === e.npcId && !b.resolution)) break;
        state.beefs.push({ id: uuidv4(), npcId: n.id, npcName: n.name, rung: 0, heat: 10, heatSerial: serial, startedSerial: serial, lastMoveSerial: serial, wins: 0, losses: 0, moves: [] });
        break;
      }
      case 'morale': {
        const c = state.crew.find((x) => x.id === e.crewId);
        if (c) c.morale = clampN((c.morale ?? 70) + e.v);
        break;
      }
      case 'wage': {
        const c = state.crew.find((x) => x.id === e.crewId);
        if (c) c.monthlyWage += e.v;
        break;
      }
      case 'quit': {
        const c = state.crew.find((x) => x.id === e.crewId);
        if (c) {
          state.crew = state.crew.filter((x) => x.id !== e.crewId);
          state.lastEventLog.unshift(`👋 ${c.npcName} quit.`);
        }
        break;
      }
      case 'stat': {
        const stats = p.stats as unknown as Record<string, number>;
        stats[e.stat] = clampN((stats[e.stat] ?? 0) + e.v);
        break;
      }
      case 'post':
        state.socialPosts.unshift({
          id: uuidv4(), platform: 'chirp', authorId: e.authorId, authorName: e.authorId === 'player' ? p.artistName : e.authorName,
          content: e.content, likes: e.likes, shares: Math.round(e.likes * 0.12), comments: [], timestamp: new Date().toISOString(),
          isPlayerPost: e.authorId === 'player', trendingScore: 30, daySerial: serial,
        });
        break;
      case 'headline':
        state.headlines.unshift({ id: uuidv4(), text: e.text, fullStory: e.story, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 5, category: e.category });
        break;
      case 'followUp': {
        const draft = buildFollowUp(e.template, e.data, serial + e.days);
        if (draft) deliverMoment(state, draft, serial, 'scheduled', serial + e.days);
        break;
      }
      case 'inboundAsk': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (!n || n.role !== 'artist') break;
        let song = [...state.npcSongs].reverse().find((s) => s.ownerId === n.id);
        if (!song) {
          song = createNPCSong(n as NPC, state.gameDate);
          state.npcSongs.push(song);
        }
        if (state.inboundRequests.some((r) => r.npcId === n.id && (r.status === 'open' || r.status === 'agreed'))) break;
        // You already said yes in the chat: no second ask, it goes straight to the studio.
        // (The chat already has their answer and the outcome — no extra lines.)
        if (e.free) { agreeInboundVerse(state, n as NPC, song, 'free', 0, true); break; }
        openInboundAsk(state, n as NPC, song, pickLine([`Let's do it properly then. What's your number for a verse on "${song.title}"?`, `Business is business. Send me your price for "${song.title}" 🤝🏾`], song.id));
        break;
      }
      case 'tradeVerse': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (!n) break;
        // Their tape: a record of theirs that wants your verse on it.
        const song = createNPCSong(n as NPC, state.gameDate);
        if (n.role !== 'artist') song.title = `${song.title} (${n.name.split(' ')[0]} Tape)`;
        state.npcSongs.push(song);
        agreeInboundVerse(state, n as NPC, song, 'trade', e.value, true);
        break;
      }
      case 'beat': {
        const b = state.beats ?? (state.beats = emptyBeats());
        const g = state.player?.genre ?? 'hip_hop';
        const beat: OwnedBeat = {
          id: `beat:dm:${uuidv4()}`, name: beatName(`dm|${e.npcId}|${serial}`), quality: e.quality, genre: g,
          bpm: 88 + (hashString(e.npcId) % 50), mood: (['aggressive', 'melancholy', 'celebratory', 'introspective', 'sensual', 'defiant'] as SongMood[])[hashString(e.npcId + serial) % 6],
          producerId: e.npcId, producerName: e.npcName, source: 'custom', license: 'exclusive', acquiredSerial: serial, price: e.price || undefined,
        };
        b.library.unshift(beat);
        pushNotification(state, { kind: 'feature', title: `🎹 "${beat.name}" is in your beats`, body: `From ${e.npcName}${e.how === 'traded' ? ', traded for a verse' : ''}. ${beatGrade(beat.quality)} — record on it in the Studio.`, artSeed: `beat|${beat.id}` });
        break;
      }
      case 'guestVerse': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        const song = (state.songs ?? []).filter((x) => !isSongReleased(x) && !x.archivedAt).sort((a, b) => b.quality - a.quality)[0];
        if (!n || !song) break;
        if (state.featureRequests.some((r) => r.songId === song.id && r.npcId === n.id && r.status !== 'declined')) break;
        const plan = planDelivery(personaOf(n as NPC), Math.random(), Math.random());
        state.featureRequests.push({
          id: uuidv4(), songId: song.id, songTitle: song.title, npcId: n.id, npcName: n.name, status: 'paid_waiting',
          sentDate: formatGameDate(state.gameDate), dueDate: formatGameDate(state.gameDate), fee: 0, freeVerse: true,
          reason: `${n.name} heard "${song.title}" and offered a verse, free.`, paid: true,
          verseDueSerial: serial + plan.days, delivery: { outcome: plan.outcome === 'ghost' ? 'late' : plan.outcome, lateBy: plan.lateBy },
        } as FeatureRequest);
        pushNotification(state, { kind: 'feature', title: `${n.name} is on "${song.title}"`, body: 'A free verse — it lands in Studio → Features when they send it.', artSeed: `npc|${n.id}`, action: { type: 'features', id: song.id } });
        break;
      }
      case 'dripGift': {
        const d = dripOf(state);
        const pickable = d.shop.filter((x) => !d.wardrobe.some((w) => w.id === x.id) && (x.slot === 'top' || x.slot === 'shoes' || x.slot === 'bottom'));
        const item = pickable.sort((a, b) => b.hype - a.hype)[hashString(`${serial}|gift`) % Math.max(1, Math.min(4, pickable.length))];
        if (!item) break;
        d.wardrobe.unshift({ ...item, bought: serial, paid: 0 });
        pushNotification(state, { kind: 'business', title: `🎁 ${item.name} is in your wardrobe`, body: `A gift from ${e.from}. Wear it in Drip & Ink.`, artSeed: `drip|${item.id}` });
        break;
      }
      case 'revival':
        pushSong(state, e.songId, e.power, e.width, e.reason);
        break;
      case 'removeVerse':
        removeVerseFromSong(state, e.songId, e.npcId, e.requestId);
        break;
      case 'sueBreach': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        const r = state.featureRequests.find((x) => x.id === e.requestId);
        if (n && !isRealId(n.id)) {
          const c = npcSues(state, n as NPC, 'breach_feature', e.claim, 72, [
            `You agreed to their terms on "${r?.songTitle ?? 'the record'}".`,
            ...(r?.breaches ?? []).slice(-1).map((b) => b.text),
            'They say the record went out in breach of that deal.',
          ], e.requestId);
          if (r) r.caseId = c.id;
        }
        break;
      }
      case 'settleBreach': {
        const r = state.featureRequests.find((x) => x.id === e.requestId);
        for (const b of r?.breaches ?? []) b.settled = true;
        break;
      }
      case 'cypher': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (!n) break;
        const at = Math.max(e.atMinute, nowMinuteOf(state) + 60);
        const fame = blendedFame(p);
        const pool = sampleNpcs(baseNpcs(state), 5, (x) => x.role === 'artist' && !isRealId(x.id) && x.id !== n.id && x.country === p.country && Math.abs(x.fame - fame) <= 22);
        const spec = cypherSpecFor({ host: n as NPC, city: p.city, playerFame: fame, pool, seed: `${n.id}|${at}` });
        createAppointment(state, n as NPC, 'cypher', at, 'npc', 'confirmed', { place: e.place, title: `Cypher at ${e.place}`, cypher: spec });
        break;
      }
      case 'birthdayPlan': {
        const b = state.birthday && state.birthday.year === state.gameDate.year ? state.birthday : (state.birthday = { year: state.gameDate.year });
        b.plan = e.plan;
        break;
      }
      case 'starFeature': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        const song = state.songs.find((x) => x.id === e.songId);
        if (!n || !song || isSongReleased(song)) break;
        if (state.featureRequests.some((r) => r.songId === song.id && r.npcId === n.id && r.status !== 'declined' && r.status !== 'ignored')) break;
        const mgr = managerOf(state);
        const fee = Math.max(500, Math.round(featureFee(n as unknown as FeatureCandidate, song.quality) * managerFeatureDiscount(mgr ? managerNetwork(mgr) : 40) / 100) * 100);
        const req: FeatureRequest = {
          id: uuidv4(), songId: song.id, songTitle: song.title, npcId: n.id, npcName: n.name, status: 'terms',
          sentDate: formatGameDate(state.gameDate), dueDate: formatGameDate(state.gameDate), fee, freeVerse: false,
          reason: `${isRealId(n.id) ? `${n.name}'s team` : n.name} came back after the meeting: a verse for $${fee.toLocaleString()}.`, originalFee: fee,
        };
        state.featureRequests.push(req);
        attachTerms(state, req, n as NPC, baseNpcs(state), serial);
        pushNotification(state, { kind: 'feature', title: `${n.name} is open to a verse on "${song.title}"`, body: `$${fee.toLocaleString()} — the terms are in Studio → Features.`, artSeed: `npc|${n.id}`, action: { type: 'features', id: song.id } });
        remember(state, 'career', `After the meeting, ${isRealId(n.id) ? `${n.name}'s team` : n.name} agreed a verse on "${song.title}" could happen.`, { npcIds: [n.id], weight: 4, tone: 'good' });
        break;
      }
      case 'cosign': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (!n) break;
        const song = e.songId ? state.songs.find((x) => x.id === e.songId) : undefined;
        addMomentum(state, 6, `${n.name} shared your music`);
        p.career.fanbase += Math.round(400 + n.fame * 60);
        p.career.localFame = Math.min(100, p.career.localFame + 1.2);
        p.career.nationalFame = Math.min(100, p.career.nationalFame + 0.8);
        if (song && isSongReleased(song)) pushSong(state, song.id, 0.35, 12, `${n.name} shared it`);
        state.headlines.unshift({ id: uuidv4(), text: `${n.name} shares ${p.artistName}'s ${song ? `"${song.title}"` : 'music'}`, fullStory: `${n.name} posted ${p.artistName}'s ${song ? `"${song.title}"` : 'music'} to their story. Fans noticed within the hour.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id, n.id], priority: 7, category: 'feature' });
        pushNotification(state, { kind: 'milestone', title: `👀 ${n.name} shared your ${song ? `"${song.title}"` : 'music'}`, body: 'Your phone is going crazy.', artSeed: `npc|${n.id}` });
        remember(state, 'career', `${n.name} shared your ${song ? `"${song.title}"` : 'music'} — a real co-sign.`, { npcIds: [n.id], weight: 4, tone: 'good' });
        break;
      }
      case 'remixGuest': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        const orig = state.songs.find((x) => x.id === e.songId);
        if (!n || !orig || !isSongReleased(orig)) break;
        if (state.songs.some((x) => x.originalSongId === orig.id && x.lineage === 'remix' && !isSongReleased(x))) break;
        const rem: Song = {
          ...orig, id: uuidv4(), title: `${orig.title} (Remix)`, version: 'remix', lineage: 'remix', originalSongId: orig.id,
          masterStatus: 'mastered', releaseDate: formatGameDate(state.gameDate), recordingDate: formatGameDate(state.gameDate),
          totalStreams: 0, weeklyStreams: 0, totalEarnings: 0, peakWeeklyStreams: 0, chartPositions: {}, certifications: [], revivals: undefined,
          hasVideo: false, videoViews: 0, marketingBudget: 0, platformIds: undefined, weeksOut: 0, readyToRelease: true,
          featuredArtists: [...(orig.featuredArtists ?? []), n.id], featureArtistNames: [...(orig.featureArtistNames ?? []), n.name],
          quality: Math.min(99, Math.round((orig.quality + (n.fame > blendedFame(p) ? 3 : 1)) * 10) / 10),
        };
        state.songs.push(rem);
        pushNotification(state, { kind: 'feature', title: `🎛️ "${rem.title}" ft. ${n.name} is in your vault`, body: 'Their verse is on it. Release it while the original is still hot.', artSeed: `song|${rem.id}`, action: { type: 'song', id: rem.id } });
        remember(state, 'music', `${n.name} jumped on the remix of "${orig.title}".`, { npcIds: [n.id], weight: 3, tone: 'good' });
        break;
      }
      case 'pullMyVerse': {
        const song = state.npcSongs.find((x) => x.id === e.songId);
        if (song) {
          const i = (song.featuredArtists ?? []).indexOf(p.id);
          if (i >= 0) { song.featuredArtists = song.featuredArtists.filter((_, k) => k !== i); song.featureArtistNames = (song.featureArtistNames ?? []).filter((nm) => nm !== p.artistName); song.quality = Math.max(1, song.quality - 3); }
        }
        const r = state.inboundRequests.find((x) => x.id === e.requestId);
        for (const b of r?.myBreaches ?? []) b.settled = true;
        break;
      }
      case 'introDone': {
        const list = state.starIntros ?? (state.starIntros = []);
        list.unshift({ npcId: e.npcId, serial, outcome: e.outcome });
        if (list.length > 20) list.length = 20;
        break;
      }
      case 'extendTerms': {
        const r = state.featureRequests.find((x) => x.id === e.requestId);
        const c = r?.conditions?.find((x) => x.kind === 'release_window');
        if (r && c) {
          c.bySerial = serial + e.days;
          c.extended = (c.extended ?? 0) + 1;
          // The clock starts again: miss this one and it's a new breach.
          r.breaches = (r.breaches ?? []).filter((b) => b.kind !== 'release_window');
        }
        break;
      }
      case 'dropTerm': {
        const r = state.featureRequests.find((x) => x.id === e.requestId);
        if (r?.conditions) r.conditions = r.conditions.filter((x) => x.kind !== e.kind);
        break;
      }
      case 'flag': {
        const flags = state.lifeFlags ?? (state.lifeFlags = {});
        flags[e.id] = e.v;
        break;
      }
      case 'gig': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        if (!n) break;
        const now = nowMinuteOf(state);
        const at = Math.max(e.atMinute, now + 45);
        createAppointment(state, n as NPC, 'gig', at, 'npc', 'confirmed', { fee: e.fee, bringOut: e.bringOut, place: e.place, title: e.bringOut ? `${n.name}'s show — they bring you out` : `Cash gig at ${e.place}` });
        break;
      }
      case 'featureFree': {
        const req = state.featureRequests.find((r) => r.id === e.requestId);
        if (!req || req.status !== 'terms') break;
        const n = state.npcs.find((x) => x.id === req.npcId);
        const song = state.songs.find((x) => x.id === req.songId);
        req.status = 'verse_ready';
        req.freeVerse = true;
        req.fee = 0;
        req.verseQuality = n ? verseQualityFor(n as FeatureCandidate, song?.quality ?? 50) : 55;
        req.reason = 'Verse for a verse — no fee.';
        break;
      }
      case 'featureCancel': {
        const req = state.featureRequests.find((r) => r.id === e.requestId);
        if (req && (req.status === 'sent' || req.status === 'terms' || req.status === 'verse_ready')) {
          req.status = 'declined';
          req.reason = 'Called off.';
        }
        break;
      }
      case 'featureNow': {
        const req = state.featureRequests.find((r) => r.id === e.requestId);
        if (req && req.status === 'sent') req.dueDate = formatGameDate(state.gameDate);
        break;
      }
      case 'featureDelay': {
        const req = state.featureRequests.find((r) => r.id === e.requestId);
        if (req && req.status === 'sent') req.dueDate = formatGameDate(advanceDate(state.gameDate, e.days) as GameDate);
        break;
      }
      case 'addOpener': {
        const n = state.npcs.find((x) => x.id === e.npcId);
        const show = [...state.scheduledShows].filter((s) => s.serial - serial > 2).sort((a, b) => a.serial - b.serial)[0];
        if (!n || !show) break;
        show.guests = show.guests ?? [];
        if (show.guests.some((g) => g.npcId === n.id && g.status === 'confirmed')) break;
        show.guests.push({ npcId: n.id, name: n.name, fame: Math.round(n.fame), role: 'opener', fee: 0, status: 'confirmed', askedSerial: serial });
        show.notes.unshift(`${n.name} is opening — for free.`);
        break;
      }
    }
  }
}

// ─── SOCIAL v2: STORE SIDE ─────────────────────────────────────────────────
// The engine is `sim/social.ts`. This holds the follower counts, makes posts,
// applies what tags and comments do to people, and runs the daily social life
// of the scene: posts collecting engagement, fan wars, rivals hitting back.

function socialStatsOf(state: GameState): Record<string, { followers: number; lastPostSerial?: number }> {
  const fanbase = state.player?.career.fanbase ?? 0;
  const stats = state.socialStats ?? (state.socialStats = {});
  for (const app of SOCIAL_APPS) {
    if (!stats[app] || typeof stats[app].followers !== 'number') stats[app] = { followers: seedFollowers(app, fanbase) };
  }
  return stats;
}

function fanClubOf(state: GameState): FanClub {
  if (!state.fanClub) {
    const c = newFanClub();
    // A career that already has fans has already passed those milestones.
    c.milestones = FAN_MILESTONES.filter((m) => (state.player?.career.fanbase ?? 0) >= m);
    state.fanClub = c;
  }
  return state.fanClub;
}

/** Daily: the fans' mood moves, milestones get celebrated. */
function fanClubTick(state: GameState, serial: number, days: number): void {
  const p = state.player;
  if (!p) return;
  const club = fanClubOf(state);
  const newest = state.songs.filter((x) => isSongReleased(x)).reduce((m, x) => Math.max(m, releaseSerialOf(state, x, -999)), -999);
  const lastPost = Math.max(-999, ...Object.values(state.socialStats ?? {}).map((x) => x.lastPostSerial ?? -999));
  fanDay(club, { daysSinceRelease: newest > -999 ? serial - newest : undefined, daysSincePost: lastPost < 0 ? 99 : serial - lastPost, momentum: p.career.momentum ?? 0, days });
  const next = FAN_MILESTONES.find((m) => p.career.fanbase >= m && !club.milestones.includes(m));
  if (next) {
    club.milestones.push(next);
    club.hype = Math.min(100, club.hype + 8);
    const label = next >= 1_000_000 ? `${next / 1_000_000}M` : `${next / 1000}K`;
    addMomentum(state, next >= 100_000 ? 4 : 2, `${label} fans`);
    pushNotification(state, { kind: 'milestone', title: `🎉 ${label} fans — ${fanbaseNameOf(state)} keep growing`, body: next >= 100_000 ? 'Fan pages are throwing a party in your comments. Thank them.' : 'A real fanbase. Look after them.', artSeed: `fans|${next}` });
    const mgr = managerOf(state);
    if (mgr) pushTeamLines(state, [{ from: mgr.id, name: mgr.name, role: 'manager', text: `${label} fans 🎉 Do something for them this week — a meet-up, a giveaway. That's how they stay.`, key: `fans:${next}` }], serial);
  }
}

function fanbaseNameOf(state: GameState): string {
  if (!state.fanbaseName && state.player) state.fanbaseName = fanbaseNameFor(state.player.artistName, state.player.id);
  return state.fanbaseName ?? 'the fans';
}

/** One like/comment per person counts; the tenth today does not. */
function socialTouch(state: GameState, npcId: string, serial: number): number {
  if (!state.socialTouches || state.socialTouches.serial !== serial) state.socialTouches = { serial, counts: {} };
  const n = (state.socialTouches.counts[npcId] ?? 0) + 1;
  state.socialTouches.counts[npcId] = n;
  return n;
}

function bumpRel(state: GameState, npcId: string, delta: number, serial: number, why?: string): void {
  if (!delta) return;
  const npc = state.npcs.find((n) => n.id === npcId);
  if (!npc) return;
  // The same person can only be charmed so much in one day.
  if (delta > 0 && socialTouch(state, npcId, serial) > 3) return;
  npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + delta));
  if (why) npc.memoryLog = [...(npc.memoryLog ?? []).slice(-9), why];
}

/** The rival in an active fan war or beef, for comment sections. */
function currentRival(state: GameState): { name: string; fans: string } | undefined {
  const war = (state.fanWars ?? []).find((w) => w.status === 'active' && w.intensity >= 25);
  if (war) return { name: war.npcName, fans: war.theirFans };
  const beef = (state.beefs ?? []).find((b) => !b.resolution && b.heat >= 30);
  if (beef) return { name: beef.npcName, fans: fanbaseNameFor(beef.npcName, beef.npcId) };
  return undefined;
}

function commentContext(state: GameState, controversy: boolean, seed: string): SocialCommentContext {
  const p = state.player!;
  const rival = currentRival(state);
  const friends: { id: string; name: string }[] = [];
  for (const n of raw(state.npcs) as NPC[]) {
    if (friends.length >= 4) break;
    if (n.role === 'artist' && n.relationshipScore >= 40 && !isRealId(n.id)) friends.push({ id: n.id, name: n.name });
  }
  return {
    fame: blendedFame(p),
    reputation: p.career.reputation,
    controversy,
    rivalName: rival?.name,
    rivalFans: rival?.fans,
    artistFriends: friends,
    seed,
  };
}

/** A fan war, opened or fed. */
function sparkFanWar(state: GameState, npc: NPC, cause: string, serial: number, intensity: number): FanWar {
  const wars = state.fanWars ?? (state.fanWars = []);
  let war = wars.find((w) => w.npcId === npc.id && w.status === 'active');
  if (war) {
    war.intensity = Math.min(100, war.intensity + intensity);
    war.lastSerial = serial;
    war.log = [cause, ...war.log].slice(0, 12);
    return war;
  }
  war = {
    id: uuidv4(), npcId: npc.id, npcName: npc.name, theirFans: fanbaseNameFor(npc.name, npc.id),
    intensity, edge: 0, cause, startedSerial: serial, lastSerial: serial, status: 'active', log: [cause],
  };
  wars.unshift(war);
  if (wars.length > 12) state.fanWars = wars.filter((w, i) => w.status === 'active' || i < 8);
  pushNotification(state, {
    kind: 'feature',
    title: `Fan war: ${fanbaseNameOf(state)} vs ${war.theirFans}`,
    body: cause,
    artSeed: `fanwar|${war.id}`,
    action: { type: 'artist', id: npc.id },
  });
  return war;
}

/** An NPC fires the first shot. The beef ladder starts with them. */
function npcStartsBeef(state: GameState, npc: NPC, serial: number, why: string): void {
  if (!state.player || npc.role !== 'artist') return;
  if (state.beefs.some((b) => b.npcId === npc.id && !b.resolution)) return;
  state.beefs.push({ id: uuidv4(), npcId: npc.id, npcName: npc.name, rung: 0, heat: 22, heatSerial: serial, startedSerial: serial, lastMoveSerial: serial, wins: 0, losses: 0, moves: [{ serial, by: 'npc', rung: 0, line: `${npc.name} fired the first shot: ${why}`, landed: true, score: 50, heatDelta: 22 }] });
  state.socialPosts.unshift({
    id: uuidv4(), platform: 'chirp', authorId: npc.id, authorName: npc.name,
    content: isRealId(npc.id) ? `[Reported] ${npc.name} took a shot at ${state.player.artistName} in a new post.` : pick3([
      `Funny how some people only got popular by copying. You know who you are. 🤫`,
      `Some of y'all are industry plants and it shows. @${state.player.artistName.replace(/\s+/g, '')}`,
      `Not everybody with a hit is an artist. Remember that.`,
    ], `${npc.id}|${serial}`),
    likes: Math.round(800 + npc.fame * 150), shares: Math.round(80 + npc.fame * 20), comments: [], timestamp: new Date().toISOString(),
    isPlayerPost: false, trendingScore: 60, daySerial: serial, tags: [{ id: 'player', name: state.player.artistName }],
  });
  deliverMoment(state, buildFollowUp('diss_track', { npcId: npc.id, npcName: npc.name }, serial)!, serial);
  state.lastEventLog.unshift(`⚔️ ${npc.name} came for you: ${why}`);
}

function pick3<T>(arr: T[], seed: string): T {
  return arr[hashString(seed) % arr.length];
}

/** Map a post kind to the closest kind on another app, for cross-posting. */
function kindOnApp(kind: PostKind, app: SocialApp, hasSong: boolean): PostKind {
  if (kindDef(kind).app === app) return kind;
  if (app === 'chirp') return hasSong ? 'announce' : 'thought';
  if (app === 'snapgram') return hasSong ? 'cover' : 'photo';
  if (app === 'clip') return hasSong ? 'challenge' : 'bts';
  return 'community';
}

/** The daily social life of the scene. */
// ─── LIVE SOCIAL HELPERS ───────────────────────────────────────────────────

const npcIndexCache = new WeakMap<NPC[], Map<string, NPC>>();
/** id → NPC over a plain roster, built once per roster array. */
function npcIndex(list: NPC[]): Map<string, NPC> {
  let m = npcIndexCache.get(list);
  if (!m) {
    m = new Map(list.map((n) => [n.id, n]));
    npcIndexCache.set(list, m);
  }
  return m;
}

/** The absolute game minute, for screens that show live numbers. */
export function nowMinuteOf(state: Pick<GameState, 'gameDate' | 'clockMinute'>): number {
  return dateToSerial(state.gameDate) * MINUTES_PER_DAY + (state.clockMinute ?? 0);
}

function pushActivity(state: GameState, a: Omit<SocialActivity, 'id'>): void {
  const list = state.socialActivity ?? (state.socialActivity = []);
  list.unshift({ id: uuidv4(), ...a });
  if (list.length > 90) list.length = 90;
}

function isBlocked(state: GameState, id: string | undefined): boolean {
  return !!id && (state.blocked ?? []).includes(id);
}

/** Who the player follows. Seeded the first time from the home scene. */
function followingOf(state: GameState, npcs: NPC[]): string[] {
  if (state.following) return state.following;
  const p = state.player;
  const out: string[] = [];
  if (p) {
    const home = npcs.filter((n) => n.role === 'artist' && n.country === p.country).sort((a, b) => b.fame - a.fame);
    for (const n of home.slice(0, 8)) out.push(n.id);
    for (const n of npcs) if (n.relationshipScore >= 40 && n.role === 'artist' && !out.includes(n.id) && out.length < 14) out.push(n.id);
    const global = npcs.filter((n) => isRealId(n.id) && n.fame >= 92).slice(0, 3);
    for (const n of global) if (!out.includes(n.id)) out.push(n.id);
  }
  state.following = out;
  if (!state.followedBy) state.followedBy = npcs.filter((n) => n.relationshipScore >= 45 && n.role === 'artist').slice(0, 6).map((n) => n.id);
  return out;
}

/**
 * Give a post live numbers: where it ends up (from who posted it) and the
 * minute it went up, plus a comment section to match its size.
 */
function livenPost(state: GameState, post: SocialPost, opts: { npcs?: NPC[]; at?: number; heat?: number; viral?: boolean; minComments?: number; audience?: number } = {}): void {
  if (post.target && post.postedMinute !== undefined) return;
  const at = opts.at ?? gameMinute(state);
  const list = opts.npcs ?? (raw(state.npcs) as NPC[]);
  const npc = npcIndex(list).get(post.authorId);
  const audience = opts.audience ?? (npc ? audienceOf(npc) : Math.max(800, post.likes * 40));
  const app = (SOCIAL_APPS.includes(post.platform as SocialApp) ? post.platform : 'chirp') as SocialApp;
  const t = postTarget({ audience, app, heat: opts.heat ?? (post.trendingScore >= 60 ? 1 : 0), roll: Math.random(), viral: opts.viral });
  post.target = t;
  post.postedMinute = at;
  post.likes = t.likes;
  post.shares = t.shares;
  if (t.views) post.views = t.views;
  post.daySerial = Math.floor(at / MINUTES_PER_DAY);
  const want = opts.minComments ?? Math.min(10, 3 + Math.floor(Math.log10(Math.max(10, t.comments)) * 1.5));
  if (post.comments.length < want) {
    // Other artists in the scene drop comments too — never real-named ones.
    const home = npc?.country ?? state.player?.country;
    const friends: { id: string; name: string }[] = [];
    if (!post.isPlayerPost) {
      const pool = list.filter((n) => n.role === 'artist' && n.id !== post.authorId && n.country === home && !isRealId(n.id));
      for (let k = 0; k < 3 && pool.length; k++) { const f = pool[Math.floor(Math.random() * pool.length)]; if (!friends.some((x) => x.id === f.id)) friends.push({ id: f.id, name: f.name }); }
    }
    post.comments.push(...socialComments(post, want - post.comments.length, {
      fame: npc?.fame ?? 30, reputation: 60, controversy: post.trendingScore >= 60,
      artistFriends: friends, seed: `${at}|${post.id}`,
    }, new Date().toISOString()));
  }
  // Comments arrive through the hours after posting, not all at once.
  const when = commentMinutes(at, post.comments.length, hashString(post.id) >>> 0);
  post.comments.forEach((c, i) => { if (c.minute === undefined) c.minute = when[i]; });
}

const STAR_CAPTIONS = ['📸', '🎥', '🌍', '✈️', '🏟️', '🖤', '🔥', '🌙', '🙏🏾', '💿', '🎤', '⚡️'];

/**
 * A star posts. Real-named artists post a picture or a clip with an emoji, or
 * a sticker for one of their records — never words in their mouth.
 */
function starPost(state: GameState, star: NPC, app: SocialApp, at: number, npcs: NPC[]): SocialPost {
  const real = isRealId(star.id);
  // Their newest record, not the first one on file.
  const song = Math.random() < 0.35 ? (state.npcSongs as Song[]).filter((x) => x.ownerId === star.id).pop() : undefined;
  const fresh = song && (song.weeksOut ?? 9) <= 2;
  const lines = ['Thank you for everything this year.', 'Back in the studio. You know what that means.', 'Tour mode 🌍', 'New era loading…', 'Different energy tonight.', 'Grateful 🙏'];
  const content = real
    ? song ? `🎵 "${song.title}"` : STAR_CAPTIONS[Math.floor(Math.random() * STAR_CAPTIONS.length)]
    : song ? (fresh ? `"${song.title}" — out now. Run it.` : `"${song.title}" still in rotation 🔁`) : lines[Math.floor(Math.random() * lines.length)];
  const post: SocialPost = {
    id: uuidv4(), platform: app, authorId: star.id, authorName: star.name, content,
    likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(),
    isPlayerPost: false, trendingScore: 50 + star.fame / 3, kind: app === 'clip' ? 'bts' : app === 'snapgram' ? (song ? 'cover' : 'photo') : app === 'circle' ? 'community' : 'thought',
    relatedSongId: song?.id,
  };
  livenPost(state, post, { npcs, at, heat: 1 });
  return post;
}

function socialTick(state: GameState, npcs: NPC[], serial: number, days: number): void {
  const p = state.player;
  if (!p) return;
  const stats = socialStatsOf(state);
  const fame = blendedFame(p);
  const now = new Date().toISOString();
  const minute = gameMinute(state);
  followingOf(state, npcs);

  // 1. Posts keep collecting: followers from what you posted, and the
  //    comment section fills in. Milestones get announced.
  for (const post of state.socialPosts) {
    if (!post.isPlayerPost) continue;
    if (post.growth && post.growth.days > 0) {
      const steps = Math.min(days, post.growth.days);
      const share = steps / post.growth.days;
      const add = (n: number) => Math.round(n * share);
      if (!post.target) {
        post.likes += add(post.growth.likes);
        post.shares += add(post.growth.shares);
        post.views = (post.views ?? 0) + add(post.growth.views);
      }
      const follows = add(post.growth.follows);
      if (stats[post.platform]) stats[post.platform].followers += follows;
      const newComments = Math.min(add(post.growth.comments), 5);
      if (newComments > 0 && post.comments.length < 30) {
        const more = socialComments(post, newComments, commentContext(state, post.content.includes('@') && post.trendingScore > 50, `${serial}|${post.id}`), now);
        // Spread through the day that just started, not all at midnight.
        more.forEach((c, i) => { c.minute = minute + 30 + Math.round(((i + 1) / (more.length + 1)) * 900); });
        post.comments.push(...more);
        const one = more[0];
        if (one) pushActivity(state, { kind: 'comment', text: `${one.authorName} commented: "${one.content}"`, actorName: one.authorName, postId: post.id, minute: one.minute! });
      }
      post.growth = {
        likes: post.growth.likes - add(post.growth.likes), shares: post.growth.shares - add(post.growth.shares),
        comments: post.growth.comments - add(post.growth.comments), views: post.growth.views - add(post.growth.views),
        follows: post.growth.follows - follows, days: post.growth.days - steps,
      };
    }
    announceMilestones(state, post, minute);
  }

  // 2. Followers follow the fanbase; a silent account slowly bleeds.
  for (const app of SOCIAL_APPS) {
    const st = stats[app];
    const floor = seedFollowers(app, p.career.fanbase);
    if (st.followers < floor) st.followers += Math.ceil((floor - st.followers) * 0.08 * Math.min(days, 7));
    if (st.lastPostSerial !== undefined && serial - st.lastPostSerial > 21) st.followers = Math.round(st.followers * Math.pow(0.998, days));
  }

  // 3. The scene posts on every app and puts up stories; some of it is about you.
  scenePosts(state, npcs, serial, Math.min(days, 3));
  // 3b. Fans talk — about you, and about the rest of the scene.
  fanChatter(state, npcs, serial, days);

  // 4. People who rate you follow you. A star following you is news.
  if (Math.random() < 1 - Math.pow(0.7, Math.min(days, 5))) {
    const by = state.followedBy ?? (state.followedBy = []);
    const bySet = new Set(by);
    const blockedSet = new Set(state.blocked ?? []);
    const candidates = npcs.filter((n) => n.role === 'artist' && !bySet.has(n.id) && !blockedSet.has(n.id) && (n.relationshipScore >= 30 || (n.fame <= fame + 15 && n.country === p.country && Math.random() < 0.02)));
    const who = candidates[Math.floor(Math.random() * candidates.length)];
    if (who && (!isRealId(who.id) || (who.relationshipScore >= 40 && fame >= who.fame - 35))) {
      by.push(who.id);
      pushActivity(state, { kind: 'follow', text: `${who.name} followed you`, actorId: who.id, actorName: who.name, minute: minute + Math.floor(Math.random() * 600) });
      if (who.fame >= 70) state.lastEventLog.unshift(`👀 ${who.name} followed you. People noticed.`);
    }
  }

  // 5. The blue tick.
  const total = SOCIAL_APPS.reduce((a, x) => a + stats[x].followers, 0);
  if (!state.verified && (total >= 60_000 || fame >= 45)) {
    state.verified = true;
    pushActivity(state, { kind: 'verified', text: 'Your accounts are verified ✓', minute });
    pushNotification(state, { kind: 'milestone', title: 'You\'re verified ✓', body: 'The blue tick is on every app. Your posts reach a little further.', artSeed: 'verified' });
  }

  // 6. Fan wars: spark, burn, cool.
  const wars = state.fanWars ?? (state.fanWars = []);
  for (const war of wars) {
    if (war.status !== 'active') continue;
    const rival = npcs.find((n) => n.id === war.npcId);
    const beef = state.beefs.find((b) => b.npcId === war.npcId && !b.resolution);
    for (let d = 0; d < Math.min(days, 7); d++) {
      const t = fanWarDay({ intensity: war.intensity, edge: war.edge, playerFame: fame, rivalFame: rival?.fame ?? 30, playerMomentum: p.career.momentum, beefHeat: beef ? settleHeat(beef, serial) : 0, playerFans: fanbaseNameOf(state), rivalFans: war.theirFans, roll: Math.random() });
      war.intensity = t.intensity;
      war.edge = t.edge;
      if (t.momentum) addMomentum(state, t.momentum);
      if (t.reputation) p.career.reputation = Math.max(0, p.career.reputation + t.reputation);
      if (t.line) war.log = [t.line, ...war.log].slice(0, 12);
      if (t.spillsIntoBeef && rival && !beef) npcStartsBeef(state, rival, serial, `the fan war with ${war.theirFans} spilled over.`);
    }
    war.lastSerial = serial;
    // Loyal fans fight harder.
    war.edge = Math.max(-50, Math.min(50, war.edge + ((fanClubOf(state).loyalty - 50) / 100) * Math.min(days, 7)));
    if (war.intensity < 6) {
      war.status = 'over';
      const club = fanClubOf(state);
      const us = fanbaseNameOf(state);
      if (war.edge > 10) {
        club.war.won += 1; club.loyalty = Math.min(100, club.loyalty + 4); club.hype = Math.min(100, club.hype + 6); addMomentum(state, 3, `${us} won the fan war`);
        war.log = [`It's over — ${us} won. The timeline agrees.`, ...war.log].slice(0, 12);
        pushNotification(state, { kind: 'milestone', title: `🏆 ${us} won the fan war with ${war.theirFans}`, body: `Record: ${club.war.won}W–${club.war.lost}L${club.war.drawn ? `–${club.war.drawn}D` : ''}. Your fans are feeling themselves.`, artSeed: `fanwar|${war.id}|won` });
      } else if (war.edge < -10) {
        club.war.lost += 1; club.hype = Math.max(0, club.hype - 6); club.loyalty = Math.max(0, club.loyalty - 2);
        war.log = [`It's over — ${war.theirFans} took this one.`, ...war.log].slice(0, 12);
        pushNotification(state, { kind: 'business', title: `${war.theirFans} won the fan war`, body: `Record: ${club.war.won}W–${club.war.lost}L. Your fans want a response — new music is the best one.`, artSeed: `fanwar|${war.id}|lost` });
      } else {
        club.war.drawn += 1;
        war.log = [`It's over. Nobody won — both sides are claiming it.`, ...war.log].slice(0, 12);
      }
    }
  }
  const activeWars = wars.filter((w) => w.status === 'active').length;
  if (activeWars < 2 && Math.random() < 1 - Math.pow(0.96, Math.min(days, 7))) {
    const hot = state.beefs.find((b) => !b.resolution && settleHeat(b, serial) >= 30 && !wars.some((w) => w.npcId === b.npcId && w.status === 'active'));
    if (hot) {
      const rival = npcs.find((n) => n.id === hot.npcId);
      if (rival) sparkFanWar(state, rival, `The beef with ${rival.name} spilled into the comments. Both fanbases are out.`, serial, 30);
    } else {
      const home = (state.charts?.[p.country] ?? []) as ChartEntry[];
      const mine = home.find((e) => e.artistId === p.id);
      const near = mine ? home.find((e) => e.artistId !== p.id && Math.abs(e.position - mine.position) <= 2) : undefined;
      const rival = near ? npcs.find((n) => n.id === near.artistId) : undefined;
      if (rival && !wars.some((w) => w.npcId === rival.id && w.status === 'active')) {
        sparkFanWar(state, rival, `You and ${rival.name} are fighting for the same spot on the chart. The fans have noticed.`, serial, 22);
      } else if (fame >= 15 && Math.random() < 0.25) {
        const peer = npcs.find((n) => n.role === 'artist' && n.country === p.country && Math.abs(n.fame - fame) <= 6 && n.relationshipScore < 20 && !wars.some((w) => w.npcId === n.id));
        if (peer) sparkFanWar(state, peer, `A blog posted "${p.artistName} or ${peer.name}?" and the replies turned into a war.`, serial, 18);
      }
    }
  }

  // 7. Organic beef: people who can't stand you, and rivals hitting back.
  if (Math.random() < 1 - Math.pow(0.95, Math.min(days, 7))) {
    const enemy = npcs.find((n) => n.role === 'artist' && n.relationshipScore <= -35 && Math.abs(n.fame - fame) <= 30 && !state.beefs.some((b) => b.npcId === n.id && !b.resolution));
    if (enemy) npcStartsBeef(state, enemy, serial, 'they never liked you, and now they said it out loud.');
  }
  for (const beef of state.beefs) {
    if (beef.resolution) continue;
    const heat = settleHeat(beef, serial);
    const lastYours = beef.moves.find((m) => m.by === 'player')?.serial ?? beef.startedSerial;
    if (heat < 35 || serial - lastYours > 14) continue;
    if (Math.random() > 1 - Math.pow(0.88, Math.min(days, 7))) continue;
    const rival = npcs.find((n) => n.id === beef.npcId);
    if (!rival) continue;
    const landed = Math.random() < 0.35 + (rival.fame - fame) / 100;
    beef.heat = Math.min(100, heat + (landed ? 10 : 5));
    beef.heatSerial = serial;
    if (landed) { beef.losses += 1; addMomentum(state, -2); } else { beef.wins += 1; addMomentum(state, 1); }
    const real = isRealId(rival.id);
    beef.moves.unshift({ serial, by: 'npc', rung: beef.rung, line: `${rival.name} hit back online${landed ? ' and it landed' : ', and it fell flat'}.`, landed, score: landed ? 65 : 35, heatDelta: landed ? 10 : 5 });
    beef.lastMoveSerial = serial;
    const post: SocialPost = real
      ? { id: uuidv4(), platform: 'chirp', authorId: 'scene_watch', authorName: 'Scene Watch', content: `${rival.name} and ${p.artistName}: the back-and-forth continues. The timeline has picked sides.`, likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 70, tags: [{ id: 'player', name: p.artistName }] }
      : {
          id: uuidv4(), platform: Math.random() < 0.5 ? 'chirp' : 'clip', authorId: rival.id, authorName: rival.name,
          content: pick3([
            `Keep my name out your mouth. Last warning.`,
            `I heard the song. I laughed. That's the review.`,
            `You want smoke? Check the charts first 📉`,
            `Y'all really think they wrote that themselves? 😂`,
            `Imagine dissing me and I still outsold you this week.`,
          ], `${rival.id}|${serial}|${beef.wins + beef.losses}`),
          likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 75, tags: [{ id: 'player', name: p.artistName }],
        };
    livenPost(state, post, { npcs, at: minute + Math.floor(Math.random() * 900), heat: 2 });
    state.socialPosts.unshift(post);
    pushActivity(state, { kind: 'mention', text: `${rival.name} came at you${real ? ' (reported)' : ''}`, actorId: rival.id, actorName: rival.name, postId: post.id, minute: post.postedMinute! });
    state.lastEventLog.unshift(`⚔️ ${rival.name} hit back${landed ? ' — and it landed.' : ', and missed.'}`);
  }

  // 8. Relationships drift when nobody tends them.
  if (Math.floor(serial / 30) !== Math.floor((serial - days) / 30)) {
    for (let i = 0; i < npcs.length; i++) {
      const n = npcs[i];
      if (Math.abs(n.relationshipScore) < 30) continue;
      if (n.lastReachOut !== undefined && serial - n.lastReachOut <= 45) continue;
      const draft = state.npcs[i];
      if (!draft || draft.id !== n.id) continue;
      draft.relationshipScore += n.relationshipScore > 0 ? -2 : 1;
    }
  }

  // Stories last a day.
  if (state.stories) state.stories = state.stories.filter((s) => minute - s.postedMinute < MINUTES_PER_DAY);
  if (state.socialPosts.length > 320) trimFeed(state);
}

const MILESTONES = [100, 1_000, 10_000, 100_000, 1_000_000];
function announceMilestones(state: GameState, post: SocialPost, minute: number): void {
  if (!post.target || post.postedMinute === undefined) return;
  const live = liveCounts(post, minute).likes;
  const hit = MILESTONES.filter((m) => live >= m && m > (post.milestone ?? 0)).pop();
  if (!hit) return;
  post.milestone = hit;
  const app = APP_META[post.platform as SocialApp]?.name ?? 'Chirp';
  pushActivity(state, { kind: 'milestone', text: `Your ${app} post hit ${hit >= 1_000_000 ? '1M' : hit >= 1000 ? `${hit / 1000}K` : hit} likes`, postId: post.id, minute });
}

/** Posts from the older generators: live numbers and a comment section. */
function settleScenePosts(state: GameState, posts: SocialPost[], npcs?: NPC[]): void {
  const minute = gameMinute(state);
  for (const post of posts) livenPost(state, post, { npcs, at: minute - Math.floor(Math.random() * 120) });
}

function trimFeed(state: GameState): void {
  if (state.socialPosts.length <= 150) return;
  state.socialPosts = feedSlice(state.socialPosts, 80, 220);
}

function feedSlice(posts: SocialPost[], mineMax: number, othersMax: number): SocialPost[] {
  const share: Record<string, number> = { chirp: 0.4, snapgram: 0.24, clip: 0.24, circle: 0.12 };
  let mine = 0;
  const per: Record<string, number> = {};
  const out: SocialPost[] = [];
  for (const x of posts) {
    if (x.isPlayerPost) { if (mine < mineMax) { out.push(x); mine += 1; } continue; }
    const cap = Math.ceil(othersMax * (share[x.platform] ?? 0.1));
    const n = per[x.platform] ?? 0;
    if (n < cap) { out.push(x); per[x.platform] = n + 1; }
  }
  return out;
}

/** What goes into the save: your last 60 posts and the freshest others, with their top comments. */
function feedForSave(posts: SocialPost[]): SocialPost[] {
  return feedSlice(posts, 60, 140).map((p) => (p.comments.length > 8 ? { ...p, comments: p.comments.slice(0, 8) } : p));
}

/**
 * The scene living its life on every app. Daily it puts up a day's worth of
 * posts spread across the coming hours (they "arrive" as the clock runs) and a
 * handful of stories; a refresh puts up a few right now.
 */
/** A teaser or a release-day post from the artist (cards only for real people). */
function releasePosts(state: GameState, npc: NPC, song: Song, stage: 'teaser' | 'out', dayName: string): void {
  const real = isRealId(npc.id);
  const posts: [SocialApp, string, PostKind][] = real
    ? stage === 'teaser' ? [['snapgram', `🗓️ "${song.title}" · ${dayName}`, 'cover']] : [['snapgram', `🎵 "${song.title}" — out now`, 'cover'], ['chirp', `🎵 "${song.title}"`, 'announce']]
    : stage === 'teaser'
      ? [['chirp', `New single "${song.title}" drops ${dayName} 🗓️ you ready?`, 'announce'], ['snapgram', `"${song.title}" · ${dayName} 🖤`, 'cover']]
      : [['chirp', `"${song.title}" is OUT NOW 🔥 go run it up`, 'announce'], ['snapgram', `"${song.title}" out everywhere. Link in bio 🎧`, 'cover'], ['clip', `Behind the scenes of "${song.title}" 🎬`, 'bts']];
  const minute = gameMinute(state);
  posts.forEach(([app, content, kind], i) => {
    const post: SocialPost = { id: uuidv4(), platform: app, authorId: npc.id, authorName: npc.name, content, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 45 + npc.fame / 2, daySerial: dateToSerial(state.gameDate), kind, relatedSongId: stage === 'out' ? song.id : undefined, soundSongId: app === 'clip' && stage === 'out' ? song.id : undefined };
    livenPost(state, post, { at: minute + 30 + i * 45 + Math.floor(Math.random() * 120), heat: stage === 'out' ? 1.4 : 1 });
    state.socialPosts.unshift(post);
  });
}

/** Big names announce, then release; songs already announced come out today. */
function rolloutReleases(state: GameState, fresh: Song[], events: string[], npcs: NPC[], serial: number): void {
  const queue = state.npcUpcoming ?? (state.npcUpcoming = []);
  const byId = npcIndex(npcs);
  const follows = (id: string) => (state.subscriptions ?? []).some((s) => s.artistId === id);
  // Announce: hold the big names' new records for a few days.
  for (let i = fresh.length - 1; i >= 0; i--) {
    const song = fresh[i];
    const npc = song.ownerId ? byId.get(song.ownerId) : undefined;
    if (!npc || npc.fame < 45) continue;
    const day = serial + 2 + Math.floor(Math.random() * 3);
    queue.push({ song, releaseSerial: day });
    fresh.splice(i, 1);
    const at = events.findIndex((e) => e.includes(`"${song.title}"`));
    if (at >= 0) events.splice(at, 1);
    const dayName = new Date(day * 86_400_000).toLocaleDateString('en-GB', { weekday: 'long', timeZone: 'UTC' });
    releasePosts(state, npc, song, 'teaser', dayName);
    events.push(`🗓️ ${npc.name} announced "${song.title}" for ${dayName}.`);
    if (follows(npc.id)) {
      pushNotification(state, { kind: 'artist_release', title: `${npc.name} announced "${song.title}"`, body: `Out ${dayName}.`, artSeed: `song|${song.id}` });
    }
  }
  // Release what's due (the subscriber notification goes out with the rest).
  const due = queue.filter((u) => u.releaseSerial <= serial);
  if (!due.length) return;
  state.npcUpcoming = queue.filter((u) => u.releaseSerial > serial);
  for (const u of due) {
    const npc = u.song.ownerId ? byId.get(u.song.ownerId) : undefined;
    // Signed to the player's label since the announcement: the label owns the drop now.
    if (state.label && npc && labelSigneeIds(state.label).has(npc.id)) continue;
    u.song.releaseDate = formatGameDate(serialToDate(serial));
    u.song.weeksOut = 0;
    fresh.push(u.song);
    if (npc) { releasePosts(state, npc, u.song, 'out', ''); events.push(`🎵 ${npc.name} dropped "${u.song.title}".`); }
  }
}

/**
 * Fans post too: about your songs, your shows, your news — and about the rest
 * of the scene. How much depends on how many fans you have and what you just
 * did. Fan accounts are ordinary people with handles, not anyone famous.
 */
function fanChatter(state: GameState, npcs: NPC[], serial: number, days: number): void {
  const p = state.player;
  if (!p) return;
  const minute = gameMinute(state);
  const fans = p.career.fanbase;
  const crew = state.fanbaseName ?? fanbaseNameFor(p.artistName, p.id);
  const released = (state.songs ?? []).filter((s) => isSongReleased(s));
  const latest = released[released.length - 1];
  const fresh = latest && state.platformStats?.[latest.id] && serial - state.platformStats[latest.id].release <= 14 ? latest : undefined;
  // Fans talk about a nomination the day after your team has told you, not before.
  const nom = Object.values(state.awardSeasons ?? {}).find((x) => x.phase === 'nominations' && serial > x.cal.nominations && x.categories.some((c) => c.nominees.some((n) => n.isPlayer)));
  const nomBody = nom ? bodiesFor(state).find((b) => b.id === nom.bodyId) : undefined;
  const liveCase = (state.cases ?? []).find((c) => c.public && (c.status === 'served' || c.status === 'hearing'));
  const beef = state.beefs.find((b) => !b.resolution);
  const mom = p.career.momentum;
  const lines: [SocialApp, string, PostKind][] = [];
  // About you.
  if (fresh) lines.push(['chirp', pick2([`"${fresh.title}" on repeat since it dropped 🔁`, `${p.artistName} really cooked on "${fresh.title}" 🔥`, `If you haven't heard "${fresh.title}" yet what are you doing`, `"${fresh.title}" is the song of the summer, I'm calling it now`], fresh.id), 'thought'], ['clip', pick2([`My edit to "${fresh.title}" 🎬`, `POV: "${fresh.title}" comes on in the car`], fresh.id + 'c'), 'challenge']);
  if (latest && !fresh && released.length >= 2) lines.push(['chirp', pick2([`Underrated ${p.artistName} song: "${released[Math.floor(Math.random() * released.length)].title}". Don't argue.`, `${p.artistName} needs to drop. We're starving 😩`], latest.id + serial), 'thought']);
  if (!released.length && fans >= 300) lines.push(['chirp', `When is ${p.artistName} dropping? Heard them freestyle once, it was crazy 👀`, 'thought']);
  if (nom && nomBody) lines.push(['chirp', pick2([`${crew} vote vote VOTE 🗳️ ${p.artistName} for the ${nomBody.short}!!`, `${p.artistName} nominated at the ${nomBody.name}. Deserved. 🏆`], nom.key + serial), 'thought']);
  if (liveCase) lines.push(['chirp', pick2([`The ${liveCase.plaintiff.name} v ${liveCase.defendant.name} case is wild 😭⚖️`, `Not ${p.artistName} in court 💀 somebody explain`, `${p.artistName} and ${liveCase.side === 'plaintiff' ? liveCase.defendant.name : liveCase.plaintiff.name} need to settle this offline`], liveCase.id + serial), 'thought']);
  if (beef) lines.push(['chirp', pick2([`${p.artistName} vs ${beef.npcName}… who's winning this one? 🍿`, `${crew} ready for war 😤`, `This ${p.artistName} and ${beef.npcName} thing is getting out of hand`], beef.npcId + serial), 'thought']);
  if (mom >= 60) lines.push(['snapgram', pick2([`${p.artistName} era 🖤`, `Nobody moving like ${p.artistName} right now`], `mom${serial}`), 'photo']);
  if (fans >= 2000) lines.push(['circle', pick2([`${crew} check in 🫡 where y'all listening from?`, released.length >= 3 ? `Ranking every ${p.artistName} song. Go.` : `What do we want on the next ${p.artistName} record?`, `${crew} appreciation thread 🧵`], `circ${serial}`), 'community']);
  if (fans >= 500 && Math.random() < 0.3) lines.push(['chirp', pick2([`${p.artistName} is overrated. There, I said it.`, `I don't get the ${p.artistName} hype tbh`], `hate${serial}`), 'thought']);
  // About the scene: the hottest fictional record this week.
  const hot = (state.npcSongs ?? []).filter((x) => x.ownerId && !isRealId(x.ownerId) && (x.weeksOut ?? 99) <= 3).sort((a, b) => (b.weeklyStreams ?? 0) - (a.weeklyStreams ?? 0))[0];
  if (hot) lines.push(['chirp', pick2([`"${hot.title}" by ${hot.ownerName} has no skips 🔥`, `${hot.ownerName} dropped and nobody's talking about it enough`, `Is "${hot.title}" the best thing out right now? Be honest`, `${hot.ownerName} - "${hot.title}". That's it. That's the tweet.`, `Played "${hot.title}" five times on the way to work 😭`], hot.id + serial), 'thought']);
  // The same take twice in a week reads like a bot.
  const said = new Set(state.socialPosts.filter((x) => x.authorId.startsWith('fan:') && (x.daySerial ?? 0) >= serial - 14).map((x) => x.content));
  for (let i = lines.length - 1; i >= 0; i--) if (said.has(lines[i][1])) lines.splice(i, 1);
  if (!lines.length) return;
  // How many of these actually get posted today.
  const n = Math.min(lines.length, Math.max(1, Math.round(Math.log10(1 + fans) - 1 + mom / 50 + (fresh ? 1 : 0))) * Math.min(days, 2));
  const chosen = [...lines].sort(() => Math.random() - 0.5).slice(0, n);
  chosen.forEach(([app, content, kind], i) => {
    const handle = `@${fanHandle(`${serial}|${i}|${content.length}`)}`;
    const post: SocialPost = { id: uuidv4(), platform: app, authorId: `fan:${handle}`, authorName: handle, content, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 20 + Math.min(40, mom / 2), daySerial: serial, kind, relatedSongId: fresh?.id, soundSongId: app === 'clip' ? fresh?.id : undefined, tags: content.includes(p.artistName) ? [{ id: 'player', name: p.artistName }] : undefined };
    livenPost(state, post, { npcs, at: minute + 20 + Math.floor(((i + 0.5) / chosen.length) * 900), minComments: 3 });
    state.socialPosts.unshift(post);
    if (post.tags) pushActivity(state, { kind: 'mention', text: `${handle} mentioned you: "${content.slice(0, 60)}"`, actorName: handle, actorId: post.authorId, postId: post.id, minute: post.postedMinute! });
  });
}

const LIFE_REPLIES = ['😂😂😂', 'Facts', 'Same here 😭', 'Exactly this', 'lol true', 'This is me 😅', 'Amen 🙏🏾', '😭😭', 'Say it louder', 'Not you calling me out', 'Real', 'Why is this so accurate', 'I felt that', 'Eh?? 😂', 'Preach', '💯', 'Tell them!!', 'Me every day', 'No lies detected'];

/** Ordinary people living their lives: the bulk of any real timeline. */
function everydayFeed(state: GameState, npcs: NPC[], serial: number, days: number, live: boolean): void {
  const p = state.player;
  if (!p) return;
  const minute = gameMinute(state);
  const month = ((serialToDate(serial).month - 1) % 12 + 12) % 12;
  const count = live ? 5 + Math.floor(Math.random() * 5) : Math.min(34, Math.round(Math.max(1, Math.min(days, 3)) * (11 + Math.random() * 7)));
  // The scene's records get talked about by everybody, not just your fans.
  const hot = (state.npcSongs ?? []).filter((x) => x.ownerId && !isRealId(x.ownerId) && (x.weeksOut ?? 99) <= 6).sort((a, b) => (b.weeklyStreams ?? 0) - (a.weeklyStreams ?? 0)).slice(0, 6);
  for (let i = 0; i < count; i++) {
    const at = live ? minute - 3 - Math.floor(Math.random() * 120) : minute + Math.floor(Math.random() * 1300) - 60;
    const hour = Math.floor((((at % 1440) + 1440) % 1440) / 60);
    const sceneSong = hot.length && Math.random() < 0.22 ? hot[Math.floor(Math.random() * hot.length)] : undefined;
    const handle = `@${fanHandle(`${serial}|life|${i}|${Math.floor(Math.random() * 1e6)}`)}`;
    const base = sceneSong
      ? sceneFanPost({ title: sceneSong.title, artist: sceneSong.ownerName ?? 'them', seed: `${serial}|${i}|${sceneSong.id}` })
      : everydayPost({ country: p.country, seed: `${serial}|${i}|${Math.floor(Math.random() * 1e6)}`, hour, month });
    const post: SocialPost = {
      id: uuidv4(), platform: base.app, authorId: `fan:${handle}`, authorName: handle, content: base.text, likes: 0, shares: 0, comments: [],
      timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 12 + Math.floor(Math.random() * 18), daySerial: Math.floor(at / MINUTES_PER_DAY), kind: base.kind,
      relatedSongId: sceneSong?.id,
    } as SocialPost;
    const nC = Math.random() < 0.65 ? 1 + Math.floor(Math.random() * 4) : 0;
    for (let k = 0; k < nC; k++) {
      const ch = `@${fanHandle(`${serial}|lc|${i}|${k}|${Math.floor(Math.random() * 1e6)}`)}`;
      post.comments.push({ id: uuidv4(), authorId: `fan:${ch}`, authorName: ch, content: LIFE_REPLIES[Math.floor(Math.random() * LIFE_REPLIES.length)], likes: Math.floor(Math.random() * 40), timestamp: new Date().toISOString(), tone: 'neutral' });
    }
    livenPost(state, post, { npcs, at, minComments: nC, audience: 300 + Math.floor(Math.random() * 4000) });
    state.socialPosts.unshift(post);
  }
}

function pick2<T>(arr: T[], seed: string): T {
  return arr[(hashString(seed) >>> 0) % arr.length];
}

function scenePosts(state: GameState, npcs: NPC[], _serial: number, days: number, opts: { app?: SocialApp; live?: boolean } = {}): number {
  const p = state.player;
  if (!p) return 0;
  const now = new Date().toISOString();
  const minute = gameMinute(state);
  const home = p.country;
  const following = new Set(followingOf(state, npcs));
  const pool: NPC[] = [];
  const stars: NPC[] = [];
  const pages: NPC[] = [];
  const followed: NPC[] = [];
  const blockedSet = new Set(state.blocked ?? []);
  for (const n of npcs) {
    if (blockedSet.size && blockedSet.has(n.id)) continue;
    if (following.has(n.id)) followed.push(n);
    if (n.role === 'artist') {
      if ((isRealId(n.id) && (n.country === home || n.fame >= 90)) || (n.country === home && n.fame >= 55)) stars.push(n);
      if (!isRealId(n.id) && (n.country === home || n.relationshipScore >= 20)) pool.push(n);
    } else if ((n.role === 'fan_account' || n.role === 'media' || n.role === 'blogger') && (n.country === home || !n.country)) pages.push(n);
  }
  if (!pool.length) return 0;
  const starSet = new Set(stars.map((x) => x.id));
  const followedStars = followed.filter((f) => starSet.has(f.id));
  const when = () => opts.live ? minute - 5 - Math.floor(Math.random() * 85) : minute + Math.floor(Math.random() * 1300) - 60;
  const city = p.city || 'the city';
  const bank: Record<SocialApp, string[]> = {
    chirp: ['Industry is a movie. I\'m just watching.', 'Who\'s the best in the country right now? Wrong answers only.', 'Album 80% done. 👀', 'If you know, you know.', 'Some of y\'all need to listen more and talk less.', `${city} we outside this weekend?`, 'Rate my last 3 songs. Be honest.', 'Studio till sunrise again. Worth it.', 'Never let them tell you your dream is too big.'],
    snapgram: ['Studio flow 📸', 'New fit, new energy.', `${city} nights 🌃`, 'Grateful for the journey 🙏', 'Rehearsals. You\'re not ready.', 'Photo dump from the week 🗂️', 'Mood: unbothered.', 'Sunday reset ☀️', 'Back on stage soon 🎤'],
    clip: ['POV: you just finished the hook at 4am', 'Freestyle Friday 🎤', 'Tried the challenge. Rate it 1-10 😂', 'Tour diaries ep. 3', 'Studio session — guess the sample 👂', 'My producer when the beat drops 😭', 'Teaching my mum the dance 😂', 'Unreleased snippet. Should I drop it? 👀'],
    circle: ['Day ones — new music Friday. You heard it here first.', 'Thank you for the love this month. Real talk. 🫂', 'Ask me anything for the next hour.', 'Voting on the next single — reply 1 or 2.', 'Members-only listening session Sunday.'],
  };
  const kindFor: Record<SocialApp, string> = { chirp: 'thought', snapgram: 'photo', clip: 'bts', circle: 'community' };
  const weights: SocialApp[] = opts.app ? [opts.app, opts.app, opts.app, 'chirp', 'snapgram', 'clip'] : ['chirp', 'snapgram', 'snapgram', 'snapgram', 'clip', 'clip', 'clip', 'circle'];
  const count = opts.live ? 4 + Math.floor(Math.random() * 5) : Math.min(26, Math.round(days * (13 + Math.random() * 8)));
  let made = 0;
  for (let i = 0; i < count; i++) {
    const app = weights[Math.floor(Math.random() * weights.length)];
    const r = Math.random();
    const at = when();
    // A star posts — the big numbers.
    if (r < 0.2 && stars.length) {
      const star = followedStars.length && Math.random() < 0.5 ? followedStars[Math.floor(Math.random() * followedStars.length)] : stars[Math.floor(Math.random() * stars.length)];
      state.socialPosts.unshift(starPost(state, star, app === 'circle' ? 'snapgram' : app, at, npcs));
      made += 1;
      continue;
    }
    // A blog reporting on a star, or a fan page about you.
    if (r < 0.32 && pages.length) {
      const page = pages[Math.floor(Math.random() * pages.length)];
      const aboutYou = blendedFame(p) >= 15 && Math.random() < 0.45;
      const hit = state.songs.filter((x) => isSongReleased(x)).sort((a, b) => (b.weeklyStreams ?? 0) - (a.weeklyStreams ?? 0))[0];
      const star = stars[Math.floor(Math.random() * Math.max(1, stars.length))];
      const content = aboutYou
        ? pick3(hit ? [`${p.artistName} — "${hit.title}" on repeat all week 🔁`, `Edit: ${p.artistName} x "${hit.title}" 🎬🔥`, `Underrated: ${p.artistName}. That's the tweet.`, `${p.artistName} different this year. Agree?`] : [`Keep an eye on ${p.artistName}. Trust me.`, `${p.artistName} is next up. Bookmark this.`], `${page.id}|${at}`)
        : star ? pick3([`${star.name} spotted in the studio again 👀 something is coming`, `${star.name} just posted and the comments are a mess 😭`, `Rumour: ${star.name} has a big feature on the way.`, `${star.name} live at the weekend — the crowd went crazy 🎥`], `${page.id}|${star.id}|${at}`) : 'The scene is busy this week.';
      const post: SocialPost = {
        id: uuidv4(), platform: app === 'circle' ? 'chirp' : app, authorId: page.id, authorName: page.name, content,
        likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 35, kind: app === 'clip' ? 'bts' : kindFor[app === 'circle' ? 'chirp' : app],
        relatedSongId: aboutYou ? hit?.id : undefined, tags: aboutYou ? [{ id: 'player', name: p.artistName }] : undefined,
      };
      livenPost(state, post, { npcs, at });
      state.socialPosts.unshift(post);
      if (aboutYou) pushActivity(state, { kind: 'mention', text: `${page.name} posted about you`, actorId: page.id, actorName: page.name, postId: post.id, minute: at });
      made += 1;
      continue;
    }
    // Somebody in the scene. People you follow post more.
    const who = following.size && Math.random() < 0.45 && followed.length ? followed[Math.floor(Math.random() * followed.length)] : pool[Math.floor(Math.random() * pool.length)];
    if (isRealId(who.id) || who.role !== 'artist') {
      if (who.role === 'artist') { state.socialPosts.unshift(starPost(state, who, app === 'circle' ? 'snapgram' : app, at, npcs)); made += 1; }
      continue;
    }
    const friendShout = who.relationshipScore >= 40 && Math.random() < 0.12;
    const song = Math.random() < 0.3 ? state.npcSongs.find((x) => x.ownerId === who.id) : undefined;
    const content = friendShout
      ? `Shout out @${p.artistName.replace(/\s+/g, '')} — one of the realest in the game right now 🙌`
      : song && app !== 'circle'
        ? pick3((song.weeksOut ?? 9) <= 2 ? [`"${song.title}" out now 🔥 run it up`, `Thank you for the love on "${song.title}" 🙏`, `"${song.title}" challenge — show me what you got 💃`] : [`Y'all slept on "${song.title}" 😴 wake up`, `"${song.title}" still hitting different 🔁`, `Throwback: "${song.title}" 🎧`], `${who.id}|${song.id}|${at}`)
        : bank[app][Math.floor(Math.random() * bank[app].length)];
    const post: SocialPost = {
      id: uuidv4(), platform: app, authorId: who.id, authorName: who.name, content,
      likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 20 + who.fame / 3,
      kind: song && app === 'clip' ? 'challenge' : kindFor[app], relatedSongId: song?.id, soundSongId: song && app === 'clip' ? song.id : undefined,
      tags: friendShout ? [{ id: 'player', name: p.artistName }] : undefined,
    };
    livenPost(state, post, { npcs, at });
    state.socialPosts.unshift(post);
    made += 1;
    if (friendShout) {
      addMomentum(state, 1);
      socialStatsOf(state).chirp.followers += Math.round(20 + who.fame * 8);
      pushActivity(state, { kind: 'mention', text: `${who.name} gave you a shout-out`, actorId: who.id, actorName: who.name, postId: post.id, minute: at });
    }
  }

  // Stories: people you follow first.
  const stories = state.stories ?? (state.stories = []);
  const storyCount = opts.live ? 1 + Math.floor(Math.random() * 2) : 4 + Math.floor(Math.random() * 5);
  for (let i = 0; i < storyCount; i++) {
    const src = followed.length && Math.random() < 0.7 ? followed : pool;
    const who = src[Math.floor(Math.random() * src.length)];
    if (!who || who.role !== 'artist' || stories.some((s) => s.authorId === who.id && minute - s.postedMinute < 600)) continue;
    stories.unshift(npcStory(who, when(), Math.random()));
  }
  if (stories.length > 40) stories.length = 40;
  everydayFeed(state, npcs, _serial, days, !!opts.live);
  return made;
}

/**
 * An artist posts about a record you are both on, on every app, and tags you.
 * Their audience finds you. Real-named artists: a blog reports it instead.
 */
function promoPosts(state: GameState, npc: Pick<NPC, 'id' | 'name' | 'fame'>, title: string, songId: string, serial: number, theirs: boolean): void {
  const p = state.player;
  if (!p) return;
  const tag = [{ id: 'player', name: p.artistName }];
  // Who tags you depends on who they are: their manager and their label post
  // too — and somebody with a big ego might "forget" the tag altogether.
  if (theirs && !isRealId(npc.id)) {
    const full = state.npcs.find((x) => x.id === npc.id) as NPC | undefined;
    const persona = full ? personaOf(full) : null;
    const handle = p.artistName.replace(/\s+/g, '');
    const now0 = new Date().toISOString();
    if (persona && persona.ego > 0.78 && persona.warmth < 0.35) {
      state.socialPosts.unshift({ id: uuidv4(), platform: 'chirp', authorId: npc.id, authorName: npc.name, content: `"${title}" OUT NOW 🔥`, likes: 0, shares: 0, comments: [], timestamp: now0, isPlayerPost: false, trendingScore: 55, daySerial: serial, relatedSongId: songId, kind: 'announce' } as SocialPost);
      livenPost(state, state.socialPosts[0]);
      pushNotification(state, { kind: 'feature', title: `${npc.name} dropped "${title}" — no tag`, body: 'Your verse is on it. Your name isn\'t in the post. People noticed.', artSeed: `song|${songId}`, action: { type: 'song', id: songId } });
      if (full) full.relationshipScore = Math.max(-100, full.relationshipScore - 2);
      return;
    }
    const mgrName = full?.team?.managerName;
    if (mgrName && !(full?.team?.managerId && isRealId(full.team.managerId))) {
      state.socialPosts.unshift({ id: uuidv4(), platform: 'chirp', authorId: full?.team?.managerId ?? `mgr:${npc.id}`, authorName: mgrName, content: `${npc.name} x @${handle} — "${title}" is out now. Proud of this one 🙏🏾`, likes: 0, shares: 0, comments: [], timestamp: now0, isPlayerPost: false, trendingScore: 45, daySerial: serial, relatedSongId: songId, tags: tag, kind: 'announce' } as SocialPost);
      livenPost(state, state.socialPosts[0]);
    }
    const label = full?.team?.label;
    if (label) {
      state.socialPosts.unshift({ id: uuidv4(), platform: 'snapgram', authorId: `label:${label}`, authorName: label, content: `New music: ${npc.name} — "${title}" ft. @${handle} 💿 Streaming everywhere.`, likes: 0, shares: 0, comments: [], timestamp: now0, isPlayerPost: false, trendingScore: 50, daySerial: serial, relatedSongId: songId, tags: tag, kind: 'cover' } as SocialPost);
      livenPost(state, state.socialPosts[0]);
    }
    pushNotification(state, { kind: 'feature', title: `🏷️ ${npc.name} tagged you — "${title}" is out`, body: `${label ? `${label} and ` : ''}${mgrName ? `${mgrName.split(' ')[0]} posted it too. ` : ''}It's in your Catalog under Featured on.`, artSeed: `song|${songId}`, action: { type: 'song', id: songId } });
  }
  const now = new Date().toISOString();
  const minute = gameMinute(state);
  const made: SocialPost[] = [];
  if (isRealId(npc.id)) {
    made.push({
      id: uuidv4(), platform: 'chirp', authorId: 'scene_watch', authorName: 'Scene Watch',
      content: `${npc.name} and ${p.artistName} link up on "${title}" — out now.`,
      likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 60, relatedSongId: songId, tags: tag, kind: 'announce',
    });
    made.push({ id: uuidv4(), platform: 'snapgram', authorId: npc.id, authorName: npc.name, content: `🎵 "${title}"`, likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 70, relatedSongId: songId, tags: tag, kind: 'cover' });
  } else {
    const handle = p.artistName.replace(/\s+/g, '');
    const posts: [SocialApp, string, PostKind][] = theirs
      ? [
          ['chirp', `My new one "${title}" ft. @${handle} is OUT 🔥 that verse is crazy`, 'announce'],
          ['snapgram', `"${title}" ft. @${handle} 🖤 out now, link in bio`, 'cover'],
          ['clip', `When @${handle}'s verse comes in on "${title}" 😮‍💨`, 'bts'],
        ]
      : [
          ['chirp', `"${title}" with @${handle} is OUT NOW 🔥 go run it up`, 'announce'],
          ['snapgram', `Me & @${handle} 🤝 "${title}" out everywhere. Link in bio.`, 'cover'],
          ['clip', `Doing the "${title}" challenge with @${handle} 💃 your turn`, 'challenge'],
        ];
    for (const [app, content, kind] of posts) {
      made.push({ id: uuidv4(), platform: app, authorId: npc.id, authorName: npc.name, content, likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 60, daySerial: serial, relatedSongId: songId, soundSongId: app === 'clip' ? songId : undefined, tags: tag, kind });
    }
  }
  for (const post of made) {
    livenPost(state, post, { at: minute + Math.floor(Math.random() * 90), heat: 1.5 });
    state.socialPosts.unshift(post);
    if (post.authorId === npc.id) pushActivity(state, { kind: 'mention', text: `${npc.name} tagged you on ${APP_META[post.platform as SocialApp].name}`, actorId: npc.id, actorName: npc.name, postId: post.id, minute: post.postedMinute! });
  }
  const stats = socialStatsOf(state);
  stats.chirp.followers += Math.round(npc.fame * 10);
  stats.snapgram.followers += Math.round(npc.fame * 25);
  stats.clip.followers += Math.round(npc.fame * 20);
}

/** Everybody featured on your record posts about it. */
function featureCrossPosts(state: GameState, song: Song, serial: number): void {
  if (!state.player || !song.featuredArtists?.length) return;
  for (const id of song.featuredArtists) {
    const npc = state.npcs.find((n) => n.id === id);
    if (npc) promoPosts(state, npc, song.title, song.id, serial, false);
  }
}

// ─── THE MANAGER'S DESK ────────────────────────────────────────────────────
// With a manager, the business does not land in your DMs. Show offers,
// feature asks and interview requests go to them; they read the small print,
// work out what it is worth, and brief you with a recommendation — once a day,
// in one message. Without a manager, every promoter, artist and station
// messages you directly.

function managerOf(state: GameState, npcs?: NPC[]): NPC | undefined {
  const c = state.contracts.find((x) => x.type === 'management' && x.active);
  if (!c) return undefined;
  // The roster is big; look it up by id on a plain copy rather than scanning the draft.
  return npcIndex(npcs ?? (raw(state.npcs) as NPC[])).get(c.npcId);
}

/** Whatever happened to an offer, the brief about it on the manager's desk is closed. */
function closeBriefs(state: GameState, refId: string, outcome: string): void {
  for (const b of state.managerDesk ?? []) if (b.refId === refId && b.status !== 'done') { b.status = 'done'; b.outcome = outcome; }
}

function fileBrief(state: GameState, b: Omit<ManagerBrief, 'id' | 'status' | 'createdSerial'>): ManagerBrief {
  const desk = state.managerDesk ?? (state.managerDesk = []);
  const brief: ManagerBrief = { ...b, id: uuidv4(), status: 'new', createdSerial: dateToSerial(state.gameDate) };
  desk.unshift(brief);
  if (desk.length > 40) state.managerDesk = desk.filter((x, i) => x.status !== 'done' || i < 25);
  return brief;
}

// ─── WHAT THE MANAGER WENT OUT AND GOT ─────────────────────────────────────
// Once a month a manager works the phones in their specialty: a connector
// chases a verse from somebody above you, a road manager a festival slot, a
// dealmaker a brand, a creative director a producer, a hype machine the radio,
// a global operator a date abroad. What lands goes on the desk; what doesn't
// is reported, with the reason — which is usually advice.

function releaseSerialOf(state: GameState, song: Song, fallback: number): number {
  return state.platformStats?.[song.id]?.release ?? serialOfGameDate(song.releaseDate, fallback);
}

/** A second wind on a released record, from today. */
function pushSong(state: GameState, songId: string, power: number, width: number, reason: string): void {
  const song = state.songs.find((x) => x.id === songId);
  if (!song) return;
  const serial = dateToSerial(state.gameDate);
  const age = Math.max(0, serial - releaseSerialOf(state, song, serial));
  plantRevival(state, songId, { power, width, reason }, age + 2);
}

/** A date the manager found: a festival at home, or a show abroad. */
function managerShowOffer(state: GameState, npcs: NPC[], mgr: NPC, abroad: boolean, serial: number, pol: TeamPolicy): ShowOffer | null {
  const p = state.player!;
  const fame = blendedFame(p);
  const reach = managerReach(mgr);
  const myCont = getCountry(p.country)?.continent;
  let countries: string[] = [p.country];
  if (abroad) {
    countries = foreignMarkets(reach, mgr.country, p.country)
      .filter((c) => pol.travel === 'anywhere' || (pol.travel === 'continent' && getCountry(c)?.continent === myCont))
      // Where your music already plays first.
      .sort((a, b) => (marketPresence(state, b) + affinity(p.country, b)) - (marketPresence(state, a) + affinity(p.country, a)))
      .slice(0, 6);
    if (pol.travel === 'home') countries = [];
  }
  if (!countries.length) return null;
  const country = countries[Math.floor(Math.random() * countries.length)];
  const cities = SHOW_CITIES.filter((c) => c.country === country);
  if (!cities.length) return null;
  // Festivals and big dates happen in the big cities.
  const ranked = [...cities].sort((a, b) => venuesInCity(b.city, b.country).length - venuesInCity(a.city, a.country).length);
  const place = ranked[abroad ? 0 : Math.floor(Math.random() * Math.min(2, ranked.length))];
  const hosts = npcs.filter((n) => (n.role === 'promoter' || n.role === 'venue_owner') && n.country === country && !isBlocked(state, n.id));
  const host = hosts.length ? hosts[Math.floor(Math.random() * hosts.length)] : null;
  if (!host) return null;
  // A room you can at least half-fill — the road manager's rule.
  const presence = marketPresence(state, country);
  const draw = fairDraw(fame, p.career.momentum, p.country, country, 1, presence, 1);
  const rooms = venuesInCity(place.city, place.country);
  const fits = rooms.filter((v) => !venueLockReason(v, fame + 15) && v.capacity <= draw * 2.2).sort((a, b) => b.capacity - a.capacity);
  const venue = fits[0] ?? rooms[0];
  if (!venue) return null;
  const lead = abroad ? 24 : MIN_LEAD_DAYS[venue.cls] + 5;
  let night = -1;
  for (let t = 0; t < 16; t++) {
    const sv = serial + lead + Math.floor(Math.random() * 40);
    if (pol.restDay >= 0 && serialWeekday(sv) === pol.restDay) continue;
    if (isNightFree(venue, sv) && !playerBusyOn(state, sv) && !state.showOffers.some((o) => o.status === 'open' && o.serial === sv)) { night = sv; break; }
  }
  if (night < 0) return null;
  const billing: OfferBilling = venue.capacity > draw * 1.3 ? 'support' : fame >= 45 ? 'headliner' : 'co_headliner';
  const o = buildOffer({
    id: uuidv4(), host, venueId: venue.id, venueName: venue.name, city: venue.city, country: venue.country, capacity: venue.capacity,
    serial: night, nowSerial: serial, playerFame: fame, relationship: host.relationshipScore, billing, kind: abroad ? 'headline' : 'festival',
    reason: abroad ? `${mgr.name} has been talking to promoters in ${country}. Your records are getting played there${presence > 0.2 ? ' — you are on their chart' : ''}.` : `${mgr.name} got you on the bill for the season's big night in ${venue.city}.`,
    hasManager: true, roll: Math.random(),
  });
  // A manager with a network opens higher, and every promoter knows it.
  o.terms.fee = Math.round(Math.min(o.ceiling, o.terms.fee * (1 + managerNetwork(mgr) / 400)) / 10) * 10;
  if (showBreaksPolicy(pol, { fee: o.terms.fee, weekday: serialWeekday(night), abroad, sameContinent: getCountry(country)?.continent === myCont })) return null;
  o.lineup = buildLineup({ host, kind: o.kind, capacity: venue.capacity, playerFame: fame, playerBilling: billing, pool: npcs, beefIds: activeBeefIds(state), friendIds: friendIdsOf(npcs), seed: o.id });
  return o;
}

function managerPitchTick(state: GameState, npcs: NPC[], mgr: NPC, serial: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  const specId = managerSpecialty(mgr);
  const spec = SPECIALTIES[specId];
  const net = managerNetwork(mgr);
  const fame = blendedFame(p);
  const pol = policyOf(state.teamPolicy);
  const vault = state.songs.filter((x) => isVaultMaster(x)).sort((a, b) => b.quality - a.quality);
  const released = state.songs.filter((x) => isSongReleased(x));
  const newest = [...released].sort((a, b) => releaseSerialOf(state, b, serial) - releaseSerialOf(state, a, serial))[0];
  const bestOut = [...released].sort((a, b) => b.quality - a.quality)[0];
  const gate = {
    playerFame: fame, nationalFame: p.career.nationalFame, fanbase: p.career.fanbase,
    bestUnreleased: vault[0]?.quality, bestReleased: bestOut?.quality,
    daysSinceRelease: newest ? serial - releaseSerialOf(state, newest, serial) : undefined,
  };
  const kinds = monthPitches(specId, net, Math.random(), Math.floor(serial / 30));
  // What you told them to push gets a try of its own.
  if (state.managerPush && state.managerPush.until >= serial) {
    const extra: PitchKind = state.managerPush.kind === 'shows' ? (specId === 'global' ? 'abroad_show' : 'festival') : state.managerPush.kind === 'features' ? 'big_feature' : 'brand';
    if (!kinds.includes(extra)) kinds.push(extra);
  }
  const beefIds = activeBeefIds(state);
  const fam = GENRE_BY_ID[p.genre]?.family ?? 'rap';
  const costIdx = costIndex(p.country);
  const notes: string[] = [];
  const landed: string[] = [];
  for (const kind of kinds) {
    const blocked = pitchBlocked(kind, gate);
    if (blocked) { notes.push(blocked); continue; }
    switch (kind) {
      case 'big_feature':
      case 'abroad_feature': {
        const song = vault[0];
        const abroad = kind === 'abroad_feature';
        const reach = managerReach(mgr);
        if ((song.featuredArtists ?? []).length >= 2) { notes.push(`"${song.title}" already has two guests on it. Finish it before I add a third.`); break; }
        const busy = new Set(state.featureRequests.filter((f) => f.songId === song.id && f.status !== 'declined' && f.status !== 'ignored').map((f) => f.npcId));
        const maxUp = spec.reachUp + (net >= 70 ? 12 : 0) + ((bestOut?.quality ?? 0) >= 75 ? 8 : 0);
        const cands = sampleNpcs(npcs, 30, (n) => n.role === 'artist' && n.fame >= fame + 5 && n.fame <= fame + maxUp && !beefIds.has(n.id)
          && (n.relationshipScore ?? 0) > -20 && !busy.has(n.id) && !(song.featuredArtists ?? []).includes(n.id) && !isBlocked(state, n.id)
          && (abroad ? n.country !== p.country && reachIncludes(reach, mgr.country, p.country, n.country) : (n.country === p.country || (n.tier === 'international' && net >= 60))));
        if (!cands.length) { notes.push(`I went through my phone for "${song.title}" and nobody at the right level could take it this month.`); break; }
        const score = (n: NPC) => (GENRE_BY_ID[n.genre as Genre]?.family === fam ? 15 : 0) + n.fame;
        cands.sort((a, b) => score(b) - score(a));
        const t = cands[Math.floor(Math.random() * Math.min(4, cands.length))];
        const sameGenre = GENRE_BY_ID[t.genre as Genre]?.family === fam;
        const odds = bigFeatureOdds({ net, gap: t.fame - fame, songQuality: song.quality, craft: craftScore(p.stats, fam), relationship: t.relationshipScore ?? 0, sameGenre, real: isRealId(t.id) });
        if (Math.random() >= odds) {
          notes.push(`I played "${song.title}" for ${t.name}'s camp. They passed this time${t.fame - fame > 25 ? ' — the gap between you is still big' : song.quality < 65 ? ' — they want a stronger record' : ''}.`);
          break;
        }
        const fee = Math.max(300, Math.round(featureFee(t as unknown as FeatureCandidate, song.quality) * managerFeatureDiscount(net) / 100) * 100);
        const afford = p.career.money - pol.cashFloor >= fee;
        const b = fileBrief(state, {
          kind: 'pitch', pitch: kind, refId: t.id,
          title: `${t.name} will jump on "${song.title}"`,
          details: [
            `${t.name}${t.country !== p.country ? ` (${t.country})` : ''} — fame ${Math.round(t.fame)}${isRealId(t.id) ? ', agreed through their team' : ''}`,
            `"${song.title}" scores ${Math.round(song.quality)}. A bigger name on it carries the record further.`,
            `$${fee.toLocaleString()} for the verse — I got it down from their usual rate.`,
          ],
          advice: afford ? 'take' : 'your call',
          reason: afford ? `This is the kind of name that moves a record. Say yes and I'll send the money and the session files today.` : `It's a great look, but it takes you under your cash floor. Your call.`,
          data: { npcId: t.id, songId: song.id, fee },
        });
        b.expiresSerial = serial + 10;
        landed.push(`${t.name} said yes to "${song.title}"`);
        break;
      }
      case 'festival':
      case 'abroad_show': {
        const o = managerShowOffer(state, npcs, mgr, kind === 'abroad_show', serial, pol);
        if (!o) { notes.push(kind === 'abroad_show' ? 'I chased dates abroad — nothing fit your calendar, your rules or the paperwork this month.' : 'The lineups I called this month were already full.'); break; }
        state.showOffers.push(o);
        const b = fileBrief(state, { ...showBrief(state, o), title: `${PITCH_LABEL[kind].emoji} ${o.venueName}, ${o.city}${o.country !== p.country ? ` (${o.country})` : ''}` });
        if (pol.autoTake && b.advice === 'take') b.auto = true;
        landed.push(kind === 'abroad_show' ? `a date in ${o.city}, ${o.country} — $${o.terms.fee.toLocaleString()}` : `a slot at ${o.venueName}, ${o.city} — $${o.terms.fee.toLocaleString()}`);
        break;
      }
      case 'brand': {
        const careful = specId === 'dealmaker' || !traitsFor(mgr).visible.includes('ruthless');
        const flags = state.lifeFlags ?? {};
        let brand = pickBrand(p.genre, Math.random(), careful);
        // One ambassador deal per category at a time — exclusivity is the whole point of a deal.
        if ((flags[`brand:${brand.kind}`] ?? -1) > serial) brand = pickBrand(p.genre, Math.random(), true);
        if ((flags[`brand:${brand.kind}`] ?? -1) > serial) { notes.push(`You're already the face of a ${brand.kind}. I'm not going to break that.`); break; }
        const fee = brandFee({ fame, fanbase: p.career.fanbase, net, costIndex: costIdx, dealmaker: specId === 'dealmaker', roll: Math.random() });
        const clash = brand.clash.includes(p.genre);
        const months = 6 + Math.floor(Math.random() * 7);
        const b = fileBrief(state, {
          kind: 'pitch', pitch: 'brand',
          title: `${brand.name} wants you as an ambassador`,
          details: [
            `${brand.name} — ${brand.kind}. $${fee.toLocaleString()} for ${months} months: posts and one appearance.`,
            `Exclusive: no other ${brand.kind} while it runs.`,
            clash || brand.shady ? `Careful: a ${brand.kind} sits badly with your audience. Expect some backlash.` : 'Fits your image.',
          ],
          advice: clash || brand.shady ? 'your call' : 'take',
          reason: clash || brand.shady ? `The money is real. So is what your fans will say. I'm only bringing it because you'd want to know.` : `Clean money for the audience you already have. I'd sign.`,
          data: { brand: brand.name, kind: brand.kind, fee, rep: brand.rep - (clash ? 3 : 0), months },
        });
        b.expiresSerial = serial + 10;
        landed.push(`${brand.name} (${brand.kind}) — $${fee.toLocaleString()}`);
        break;
      }
      case 'sync': {
        const pool = released.filter((x) => x.quality >= 58).sort((a, b) => b.quality - a.quality);
        const song = pool[Math.floor(Math.random() * Math.min(3, pool.length))];
        if (!song) break;
        const odds = 0.35 + net / 250 + (song.quality - 58) / 100;
        if (Math.random() >= odds) { notes.push(`I sent "${song.title}" to music supervisors. Nothing yet — these take time.`); break; }
        const fee = syncFee({ fame, quality: song.quality, costIndex: costIdx, roll: Math.random() });
        const where = syncPlace(Math.random());
        const b = fileBrief(state, {
          kind: 'pitch', pitch: 'sync', title: `"${song.title}" in ${where}`,
          details: [`$${fee.toLocaleString()} licence fee.`, 'A sync puts the record in front of people who have never heard you — expect a second wind on the streams.'],
          advice: 'take', reason: 'Money now and new ears on an old record. Easy yes.',
          data: { songId: song.id, fee, where },
        });
        b.expiresSerial = serial + 8;
        landed.push(`a sync for "${song.title}"`);
        break;
      }
      case 'producer': {
        const target = Math.max(58, fame + 12);
        const cands = sampleNpcs(npcs, 25, (n) => n.role === 'producer' && producerSkillOf(n) >= target - 6 && !beefIds.has(n.id) && !isBlocked(state, n.id) && (n.country === p.country || net >= 55));
        if (!cands.length) { notes.push('I tried to get you in a room with a bigger producer. Nobody had a slot.'); break; }
        cands.sort((a, b) => producerSkillOf(b) - producerSkillOf(a));
        const t = cands[Math.floor(Math.random() * Math.min(3, cands.length))];
        const q = orderQuote(producerSkillOf(t), false);
        const fee = Math.max(100, Math.round(q.fee * Math.max(0.5, 0.75 - net / 400) / 10) * 10);
        if (p.career.money - pol.cashFloor < fee) { notes.push(`I can get you a beat from ${t.name}, but it's $${fee.toLocaleString()} and that's more than you can spend right now.`); break; }
        const b = fileBrief(state, {
          kind: 'pitch', pitch: 'producer', refId: t.id, title: `${t.name} will build you a beat`,
          details: [`${t.name} — producer, skill ${Math.round(producerSkillOf(t))}.`, `Custom beat to your brief for $${fee.toLocaleString()} (they usually charge $${q.fee.toLocaleString()}). Ready in about ${q.days} days.`],
          advice: 'take', reason: 'A better beat is the cheapest way to a better record.',
          data: { npcId: t.id, fee, days: q.days },
        });
        b.expiresSerial = serial + 10;
        landed.push(`a beat from ${t.name}`);
        break;
      }
      case 'radio':
      case 'playlist': {
        const song = newest;
        if (!song) break;
        const odds = kind === 'radio' ? 0.4 + net / 200 + (song.quality - 50) / 200 : 0.3 + net / 300 + (song.quality - 50) / 80;
        if (Math.random() >= odds) { notes.push(kind === 'radio' ? `I pushed "${song.title}" to radio. The programmers want to see it grow first.` : `Pitched "${song.title}" to playlists. No placement this month.`); break; }
        const slot = kind === 'radio' ? radioSlot(Math.random()) : playlistSlot(Math.random());
        pushSong(state, song.id, kind === 'radio' ? 0.22 + net / 450 : 0.3 + (song.quality - 50) / 160, kind === 'radio' ? 16 : 12, `${kind === 'radio' ? 'Radio' : 'Playlist'}: ${slot}`);
        p.career.localFame = Math.min(100, p.career.localFame + (kind === 'radio' ? 0.8 : 0.4) + net / 120);
        p.career.nationalFame = Math.min(100, p.career.nationalFame + (kind === 'radio' ? 0.4 : 0.3));
        addMomentum(state, kind === 'radio' ? 3 : 2);
        const b = fileBrief(state, { kind: 'fyi', pitch: kind, title: `${PITCH_LABEL[kind].emoji} "${song.title}" — ${slot}`, details: ['Done. No cost to you.', 'Expect the streams to pick up over the next two weeks.'], advice: 'take', reason: "That one's handled." });
        b.status = 'done';
        b.outcome = 'Handled by your manager.';
        landed.push(`"${song.title}" on ${slot}`);
        break;
      }
      case 'intro': {
        const reach = managerReach(mgr);
        const met = new Set((state.starIntros ?? []).filter((x) => serial - x.serial < 240).map((x) => x.npcId));
        const pending = new Set((state.managerDesk ?? []).filter((x) => x.pitch === 'intro' && x.status !== 'done').map((x) => x.refId));
        const minFame = Math.max(fame + 18, 55);
        const cands = npcs.filter((n) => (n.role === 'artist' || (n.role === 'label_ceo' && isRealId(n.id))) && n.fame >= minFame && !met.has(n.id) && !pending.has(n.id)
          && !beefIds.has(n.id) && !isBlocked(state, n.id) && (n.isAvailable !== false || net >= 80)
          && (n.country === p.country || reachIncludes(reach, mgr.country, p.country, n.country)));
        if (!cands.length) { notes.push('I tried to get you in a room with somebody big. Nobody I can reach is taking meetings this month.'); break; }
        // Real stars first when the manager can reach them — those are the rooms that change a career.
        const score = (n: NPC) => n.fame + (isRealId(n.id) ? 18 : 0) + (n.country === p.country ? 10 : 0) + (GENRE_BY_ID[n.genre as Genre]?.family === fam ? 6 : 0) - Math.max(0, n.fame - fame - 45) * 1.5;
        cands.sort((a, b) => score(b) - score(a));
        const t = cands[Math.floor(Math.random() * Math.min(3, cands.length))];
        const odds = Math.max(0.12, Math.min(0.85, 0.3 + net / 180 - Math.max(0, t.fame - fame - 30) / 120 + ((bestOut?.quality ?? vault[0]?.quality ?? 50) - 60) / 200));
        if (Math.random() >= odds) { notes.push(`I asked ${isRealId(t.id) ? `${t.name}'s team` : t.name} for a meeting. ${t.fame - fame > 40 ? 'The gap between you is still big — they said "later".' : 'They\'re busy this month. I\'ll ask again.'}`); break; }
        let day = serial + 3 + Math.floor(Math.random() * 6);
        if (serialWeekday(day) === 0) day += 1;
        const atMinute = day * MINUTES_PER_DAY + (13 + Math.floor(Math.random() * 4)) * 60;
        const pitch = { starId: t.id, starName: t.name, real: isRealId(t.id), fame: Math.round(t.fame) };
        const b = fileBrief(state, {
          kind: 'pitch', pitch: 'intro', refId: t.id,
          title: `A room with ${pitch.real ? `${t.name}'s team` : t.name}`,
          details: [
            `${t.name} — ${t.country}, fame ${pitch.fame}${pitch.real ? '. Their team takes the meeting.' : ''}`,
            `${formatGameDate(serialToDate(day))}, ${fmtMinute(atMinute)} · fifteen minutes.`,
            'Bring your best record. You get one shot at a room like this.',
          ],
          advice: 'take',
          reason: introPitchLine(pitch),
          data: { npcId: t.id, atMinute },
        });
        b.expiresSerial = day - 1;
        landed.push(`a meeting with ${pitch.real ? `${t.name}'s team` : t.name}`);
        break;
      }
      case 'opener': {
        // A star from home is playing a big room and needs a support act.
        const stars = npcs.filter((n) => n.role === 'artist' && n.country === p.country && n.fame >= fame + 12 && n.fame <= fame + 50 && !beefIds.has(n.id) && !isBlocked(state, n.id)).sort((a, b) => b.fame - a.fame);
        if (!stars.length) { notes.push('No big shows at home need an opener this month.'); break; }
        const star = stars[Math.floor(Math.random() * Math.min(5, stars.length))];
        const o = managerShowOffer(state, npcs, mgr, false, serial, pol);
        if (!o) { notes.push(`${star.name} needs an opener, but the dates clash with your calendar or your rules.`); break; }
        // The star's crowd, in the biggest room that night allows.
        const big = venuesInCity(o.city, o.country).filter((v) => v.capacity > o.capacity && isNightFree(v, o.serial)).sort((a, b) => b.capacity - a.capacity)[0];
        if (big) { o.venueId = big.id; o.venueName = big.name; o.capacity = big.capacity; }
        o.terms.billing = 'support';
        o.terms.fee = Math.max(150, Math.round(o.terms.fee * 0.7 / 10) * 10);
        o.reason = `${star.name} is headlining ${o.venueName} and needs an opener. ${mgr.name} put your name forward — it's their crowd, not yours. Win them.`;
        o.lineup = [{ npcId: star.id, name: star.name, fame: Math.round(star.fame), slot: 'headliner' }, ...(o.lineup ?? []).filter((x) => x.slot !== 'headliner' && x.npcId !== star.id).slice(0, 2)];
        state.showOffers.push(o);
        const b = fileBrief(state, { ...showBrief(state, o), title: `${PITCH_LABEL.opener.emoji} Opening for ${star.name} at ${o.venueName}`, reason: `${star.name}'s crowd, ${o.capacity.toLocaleString()} people who have never heard you. Money's small; the room is the point.`, advice: playerBusyOn(state, o.serial) ? 'pass' : 'take' });
        if (pol.autoTake && b.advice === 'take') b.auto = true;
        landed.push(`an opening slot for ${star.name}`);
        break;
      }
      case 'interview': {
        const before = (state.interviewInvites ?? []).filter((x) => x.status === 'open').length;
        interviewTick(state, serial, 21, npcs);
        const after = (state.interviewInvites ?? []).filter((x) => x.status === 'open').length;
        if (after > before) landed.push('an interview request');
        else notes.push('I pitched you to a few shows. Nobody has bitten yet.');
        break;
      }
    }
  }
  const msg = [landed.length ? `Got you ${landed.join('; ')}.${landed.some((x) => !x.includes(' on ')) ? ' Details on my desk.' : ''}` : '', ...notes].filter(Boolean).join(' ');
  if (msg) pushDM(state, mgr.id, { fromPlayer: false, content: `📋 ${spec.emoji} This month: ${msg}` });
  if (landed.length) log.push(`📋 ${mgr.name} (${spec.label}) landed ${landed.length} thing${landed.length > 1 ? 's' : ''}: ${landed.join(', ')}.`);
}

/** Once a day the manager sends one message about everything new. */
function managerDigest(state: GameState, serial: number, npcs?: NPC[]): void {
  const fresh = (state.managerDesk ?? []).filter((b) => b.status === 'new' && b.createdSerial === serial);
  if (!fresh.length) return;
  const mgr = managerOf(state, npcs);
  if (!mgr) return;
  const takes = fresh.filter((b) => b.advice === 'take').length;
  const lines = fresh.slice(0, 4).map((b) => `• ${b.title} — ${b.advice === 'take' ? 'I\'d take it' : b.advice === 'pass' ? 'I\'d pass' : b.advice === 'counter' ? `I'd counter${b.counterAt ? ` at $${b.counterAt.toLocaleString()}` : ''}` : 'your call'}`);
  const thread = state.dmThreads[mgr.id] ?? { npcId: mgr.id, messages: [], unread: 0 };
  thread.messages.push({
    id: uuidv4(), npcId: mgr.id, fromPlayer: false,
    content: `📋 ${fresh.length} new thing${fresh.length > 1 ? 's' : ''} on my desk${takes ? ` — ${takes} worth taking` : ''}:\n${lines.join('\n')}\nDetails on the desk. Tell me what you want to do.`,
    timestamp: new Date().toISOString(), read: false,
  });
  thread.unread += 1;
  state.dmThreads[mgr.id] = thread;
}

function showBrief(state: GameState, o: ShowOffer): Omit<ManagerBrief, 'id' | 'status' | 'createdSerial'> {
  const busy = playerBusyOn(state, o.serial);
  const beefAct = (o.lineup ?? []).find((a) => a.beef);
  const friends = (o.lineup ?? []).filter((a) => a.friend).map((a) => a.name);
  const counter = Math.round(Math.min(o.ceiling * 0.95, o.fair * 1.1) / 50) * 50;
  const details = [
    `${o.venueName}, ${o.city} · ${formatGameDate(serialToDate(o.serial))}`,
    `${BILLING_LABEL[o.terms.billing]} · ${o.terms.slotMins} min · $${o.terms.fee.toLocaleString()} guaranteed`,
    `Room holds ${o.capacity.toLocaleString()}. Fair money for the slot is about $${o.fair.toLocaleString()}.`,
  ];
  if (o.lineup?.length) details.push(`On the bill: ${o.lineup.map((a) => a.name).join(', ')}`);
  if (o.hidden.includes('cancel')) details.push('Small print: they can cancel late without paying. I\'d get that removed.');
  if (o.hidden.includes('exclusivity')) details.push('Small print: no other shows in that city for a while.');
  let advice: ManagerBrief['advice'] = 'take';
  let reason = 'Good money for that room.';
  if (busy) { advice = 'pass'; reason = 'You\'re already booked that night.'; }
  else if (beefAct) { advice = 'your call'; reason = `${beefAct.name} is on the bill. Could be a moment, could be a mess.`; }
  else if (o.terms.fee < o.fair * 0.82) { advice = 'counter'; reason = `They're lowballing. I know they can do around $${counter.toLocaleString()}.`; }
  else if (friends.length) reason = `Fair money, and ${friends[0]} is on it — good night for the network.`;
  return { kind: 'show', refId: o.id, title: `${o.hostName}: ${o.venueName}, ${o.city}`, details, advice, reason, counterAt: advice === 'counter' ? counter : undefined };
}

function featureBrief(state: GameState, req: InboundRequest, npc: NPC): Omit<ManagerBrief, 'id' | 'status' | 'createdSerial'> {
  const p = state.player!;
  const beef = activeBeefIds(state).has(npc.id);
  const counter = Math.round((req.ceiling * 0.9) / 50) * 50;
  const details = [
    `"${req.npcSongTitle}" by ${npc.name} — the record reads ${gradeLabel(req.songQuality)}`,
    `${npc.name}: fame ${Math.round(npc.fame)}, relationship ${npc.relationshipScore > 0 ? '+' : ''}${Math.round(npc.relationshipScore)}`,
    req.offer > 0 ? `Opening at $${req.offer.toLocaleString()} for a verse. They keep the publishing.` : 'No money — they want you on it as a favour.',
  ];
  let advice: ManagerBrief['advice'] = 'take';
  let reason = 'Fair, and it keeps your name moving.';
  if (beef) { advice = 'pass'; reason = 'You two are at war. Not a good look.'; }
  else if (npc.fame > blendedFame(p) + 15) { advice = 'take'; reason = 'Their audience is bigger than yours. Take it for the exposure.'; }
  else if (req.offer > 0 && req.offer < req.ceiling * 0.75) { advice = 'counter'; reason = `They have more room. I'd ask for $${counter.toLocaleString()}.`; }
  else if (req.songQuality < 45) { advice = 'your call'; reason = 'The record is weak. Money is money, but your name goes on it.'; }
  return { kind: 'feature', refId: req.id, title: `${npc.name} wants a verse on "${req.npcSongTitle}"`, details, advice, reason, counterAt: advice === 'counter' ? counter : undefined };
}

function interviewBrief(state: GameState, inv: InterviewInvite, outlet: Outlet): Omit<ManagerBrief, 'id' | 'status' | 'createdSerial'> {
  const p = state.player!;
  const f = FORMAT_INFO[inv.format as InterviewFormat];
  const rel = state.outletRel?.[outlet.id] ?? 0;
  const details = [
    `${KIND_EMOJI[outlet.kind]} ${outlet.name} with ${outlet.host} · about ${compactNum(outlet.reach)} listeners`,
    `${f.emoji} ${f.label} — risk: ${f.risk}`,
    inv.fee ? `They pay $${inv.fee.toLocaleString()} to appear.` : 'No fee — it\'s promo.',
    inv.reason,
  ];
  let advice: ManagerBrief['advice'] = 'take';
  let reason = outlet.reach >= 1_000_000 ? 'Huge audience. Do it.' : 'Good platform for you right now.';
  if (rel < -10) { advice = 'pass'; reason = 'Last time there went badly. Let it cool.'; }
  else if (f.risk === 'High' && p.career.reputation < 30) { advice = 'your call'; reason = 'Messy show and your reputation is fragile. Know what you\'ll say.'; }
  return { kind: 'interview', refId: inv.id, title: `${outlet.name} wants you on`, details, advice, reason };
}

function compactNum(n: number): string {
  return n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${Math.round(n / 1000)}K` : String(n);
}

// ─── INTERVIEWS: STORE SIDE ────────────────────────────────────────────────

function outletsNow(state: GameState): Outlet[] {
  const p = state.player;
  return p ? outletsFor(p.country, p.city || p.country) : [];
}

function interviewContext(state: GameState, roster?: NPC[]): IvContext {
  const p = state.player!;
  const npcs = roster ?? (raw(state.npcs) as NPC[]);
  const idx = npcIndex(npcs);
  const fame = blendedFame(p);
  const released = state.songs.filter((s) => isSongReleased(s));
  const latest = released[released.length - 1];
  const unreleased = state.songs.find((s) => s.masterStatus !== undefined && s.masterStatus !== 'released' && !s.archivedAt);
  const serial = dateToSerial(state.gameDate);
  const beef = [...state.beefs].filter((b) => !b.resolution).sort((a, b) => settleHeat(b, serial) - settleHeat(a, serial))[0];
  const war = (state.fanWars ?? []).find((w) => w.status === 'active');
  const rivalId = beef?.npcId ?? war?.npcId;
  const rivalNpc = rivalId ? idx.get(rivalId) : undefined;
  const person = (n: NPC) => ({ id: n.id, name: n.name, real: isRealId(n.id), fame: n.fame });
  const friends = npcs.filter((n) => n.role === 'artist' && n.relationshipScore >= 35 && !isBlocked(state, n.id)).sort((a, b) => b.relationshipScore - a.relationshipScore).slice(0, 4).map(person);
  const homeArtists = npcs.filter((n) => n.role === 'artist' && n.country === p.country);
  const stars = [...homeArtists].sort((a, b) => b.fame - a.fame).slice(0, 6).map(person);
  const friendIds = new Set(friends.map((f) => f.id));
  const peers = homeArtists.filter((n) => Math.abs(n.fame - fame) <= 12 && n.relationshipScore < 25 && !friendIds.has(n.id)).sort((a, b) => Number(isRealId(a.id)) - Number(isRealId(b.id))).slice(0, 4).map(person);
  const prodCrew = (state.crew ?? []).find((c) => c.role === 'producer');
  const prodNpc = prodCrew ? idx.get(prodCrew.npcId) : npcs.find((n) => n.role === 'producer' && n.relationshipScore >= 25);
  const latestProducer = latest?.producerId ? idx.get(latest.producerId) : undefined;
  const label = state.contracts.find((c) => c.active && c.type === 'label');
  return {
    name: p.artistName, city: p.city || p.country, country: p.country, genre: p.genre,
    fame, reputation: p.career.reputation, momentum: p.career.momentum,
    charisma: p.stats.charisma, freestyle: p.stats.freestyle, lyricism: p.stats.lyricism, performance: p.stats.performance,
    latestSong: latest ? { id: latest.id, title: latest.title, quality: latest.quality, producer: latestProducer ? person(latestProducer) : undefined, hasVideo: !!latest.hasVideo, chartPos: latest.chartPositions?.[p.country] } : undefined,
    unreleased: unreleased?.title,
    rival: rivalNpc ? { ...person(rivalNpc), heat: beef ? settleHeat(beef, serial) : 30 } : undefined,
    friends, stars, peers,
    producerFriend: prodNpc ? person(prodNpc) : undefined,
    label: label?.npcName, ownLabel: state.label?.name,
    manager: managerOf(state, npcs)?.name,
    money: p.career.money,
    hasAlbum: (state.albums ?? []).length > 0,
  };
}

function startInterviewSession(state: GameState, outlet: Outlet, format: InterviewFormat, fee: number, inviteId?: string): void {
  const ctx = interviewContext(state);
  state.activeInterview = {
    id: uuidv4(), inviteId, outletId: outlet.id, outletName: outlet.name, host: outlet.host, format,
    questions: buildInterview(format, ctx, Math.random), idx: 0, transcript: [], effects: [], fee,
    startedSerial: dateToSerial(state.gameDate),
  };
}

// ─── MONEY: MARKETS, BUSINESSES, PROPERTY, CASINO, TEAM WORK ───────────────

function marketOf(state: GameState): MarketState {
  if (!state.market || !Array.isArray(state.market.stocks)) state.market = newMarket(dateToSerial(state.gameDate), Math.random);
  return state.market;
}
function portfolioOf(state: GameState): Portfolio {
  if (!state.portfolio) state.portfolio = { stocks: [], coins: [], realized: 0, dividends: 0 };
  return state.portfolio;
}
function casinoOf(state: GameState): CasinoState {
  if (!state.casino) state.casino = { vipPoints: 0, net: 0, biggestWin: 0, biggestLoss: 0, day: { serial: -1, net: 0 }, blackjack: null, fixtures: [], bets: [], history: [] };
  return state.casino;
}

/** Who on the payroll is doing what. */
function crewOn(state: GameState, role: string, assignment: string): CrewMember | undefined {
  return (state.crew ?? []).find((c) => c.role === role && (c.assignment ?? assignmentsFor(role)[0]?.id) === assignment);
}
function socialBoost(state: GameState): number {
  return (crewOn(state, 'photographer', 'socials') ? 0.15 : 0) + (crewWithSkill(state.crew, 'viral_eye') ? 0.1 : 0);
}
export function advisorOf(state: Pick<GameState, 'crew'>): { name: string; skill: number } | null {
  const c = (state.crew ?? []).find((x) => x.role === 'accountant' && x.assignment === 'markets');
  if (!c) return null;
  const sharp = specialSkillOf(c.npcId, c.role, c.skill)?.id === 'market_reader';
  return { name: c.npcName, skill: Math.min(100, c.skill + (sharp ? 15 : 0)) };
}
/** What your accountant knocks off a big purchase. */
export function dealDiscountOf(state: Pick<GameState, 'crew'>): number {
  const crew = state.crew ?? [];
  const dealer = crew.find((c) => c.role === 'accountant' && c.assignment === 'deals');
  const haggler = crewWithSkill(crew, 'haggler');
  if (dealer) return haggler && haggler.id === dealer.id ? 0.12 : 0.08;
  return haggler ? 0.04 : 0;
}
function dealDiscount(state: GameState): number {
  return dealDiscountOf(state);
}
/** The casino floor's limit for you — VIP tier, doubled if your assistant is the plug. */
export function casinoLimitOf(state: Pick<GameState, 'crew' | 'casino'>): number {
  return tableLimit(state.casino?.vipPoints ?? 0) * (crewWithSkill(state.crew, 'the_plug') ? 2 : 1);
}

export function priceMapOf(m: MarketState): Map<string, number> {
  const out = new Map<string, number>();
  for (const s of m.stocks) out.set(s.ticker, s.price);
  for (const c of m.coins) out.set(c.ticker, c.price);
  return out;
}

/** Everything you own, at today's prices. */
export function netWorthOf(state: GameState): { cash: number; stocks: number; crypto: number; businesses: number; property: number; other: number; total: number } {
  const p = state.player;
  const cash = p?.career.money ?? 0;
  const m = state.market;
  const prices = m ? priceMapOf(m) : new Map<string, number>();
  const pf = state.portfolio;
  const stocks = pf ? holdingValue(pf.stocks, prices) : 0;
  const crypto = pf ? holdingValue(pf.coins, prices) : 0;
  const businesses = (state.ventures ?? []).filter((v) => !v.closed).reduce((a, v) => a + ventureValue(v), 0) + state.businesses.reduce((a, b) => a + (b.monthlyRevenue / 0.026) * 0.7, 0);
  const serial = dateToSerial(state.gameDate);
  const property = (state.devProjects ?? []).reduce((a, d) => a + projectValue(d, m?.propertyIndex ?? 100, serial), 0) + state.investments.reduce((a, i) => a + i.currentValue, 0)
    + (state.homes ?? []).reduce((a, h) => a + ownedValue(h, m?.propertyIndex ?? 100), 0);
  const other = (state.ownedAssets ?? []).reduce((a, x) => a + (x.cost ?? 0) * 0.6, 0);
  return { cash, stocks, crypto, businesses, property, other, total: Math.round(cash + stocks + crypto + businesses + property + other) };
}

function monthsCrossed(serial: number, days: number): number {
  const a = serialToDate(serial - days);
  const b = serialToDate(serial);
  return (b.year * 12 + b.month) - (a.year * 12 + a.month);
}

function ventureCtx(state: GameState, v: Venture): VentureCtx {
  const p = state.player!;
  const merch = v.type === 'clothing' ? (crewOn(state, 'stylist', 'merch') ? 0.15 : 0) + (crewWithSkill(state.crew, 'trendsetter') ? 0.12 : 0) + (crewWithSkill(state.crew, 'cover_artist') ? 0.05 : 0) : 0;
  return { fame: blendedFame(p), fanbase: p.career.fanbase, momentum: p.career.momentum, businessSkill: p.stats.businessKnowledge ?? 40, managerBoost: state.contracts.some((c) => c.type === 'management' && c.active) ? 0.03 : 0, merchBoost: merch };
}

/** Daily: the markets move; monthly: businesses, rent, dividends; on site: builds progress. */
function moneyTick(state: GameState, serial: number, days: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  const m = marketOf(state);
  const steps = Math.min(Math.max(0, serial - m.day), 45);
  const fresh: MarketNews[] = [];
  for (let i = steps - 1; i >= 0; i--) fresh.push(...stepMarket(m, serial - i, Math.random));
  // Your holdings in the news.
  const pf = portfolioOf(state);
  const held = new Set([...pf.stocks, ...pf.coins].map((h) => h.ticker));
  for (const n of fresh) if (n.ticker && held.has(n.ticker)) log.push(n.text);

  brandTick(state, serial, days, log);

  const months = monthsCrossed(serial, days);
  if (months > 0) {
    const prices = priceMapOf(m);
    const d = serialToDate(serial);
    // Dividends, quarterly.
    if ([1, 4, 7, 10].includes(d.month)) {
      let div = 0;
      for (const h of pf.stocks) { const s = m.stocks.find((x) => x.ticker === h.ticker); if (s) div += h.units * s.price * s.dividend / 4; }
      div = Math.round(div);
      if (div > 0) { p.career.money += div; pf.dividends += div; ledgerAdd('dividends', div); log.push(`💵 Dividends paid: $${div.toLocaleString()}.`); }
    }
    // A financial advisor earns their keep.
    const adv = advisorOf(state);
    if (adv) {
      const value = holdingValue(pf.stocks, prices) + holdingValue(pf.coins, prices);
      const bonus = Math.round(value * 0.002 * (adv.skill / 100) * months);
      if (bonus > 0) { p.career.money += bonus; ledgerAdd('advisor', bonus); log.push(`📈 ${adv.name} rebalanced your portfolio: +$${bonus.toLocaleString()}.`); }
    }
    // Businesses you run.
    for (const v of state.ventures ?? []) {
      if (v.closed) continue;
      if (v.type === 'clothing') {
        // The brand is paid week by week; the month is the summary.
        const b = brandOf(v, serial);
        const acc = b.monthAcc;
        b.monthAcc = { revenue: 0, costs: 0, profit: 0 };
        v.months = [...v.months, { serial, revenue: acc.revenue, costs: acc.costs, profit: acc.profit }].slice(-24);
        v.redMonths = acc.profit < 0 ? v.redMonths + 1 : 0;
        log.push(`👕 ${v.name}: ${acc.profit >= 0 ? '+' : '−'}$${Math.abs(acc.profit).toLocaleString()} this month.`);
        if (v.redMonths === 3) pushNotification(state, { kind: 'business', title: `${v.name} is losing money`, body: 'Three months in the red. Check your prices, your stock and your running costs.', artSeed: `venture|${v.id}` });
        continue;
      }
      for (let k = 0; k < Math.min(months, 3); k++) {
        const ctx = ventureCtx(state, v);
        const res = ventureMonth(v, ctx, Math.random);
        let profit = res.month.profit;
        // Your attention: business focus (or retirement) means the companies get more of it.
        const focus = MODES[state.legacy?.mode ?? 'active'].ventures;
        if (profit > 0 && focus !== 1) profit = Math.round(profit * focus);
        if (res.events.length && profit < 0) {
          const lawyer = crewOn(state, 'lawyer', 'disputes');
          const shark = lawyer && specialSkillOf(lawyer.npcId, lawyer.role, lawyer.skill)?.id === 'shark';
          if (lawyer) profit = Math.round(profit * (shark ? 0.5 : 0.7));
          if (crewWithSkill(state.crew, 'fixer')) profit = Math.round(profit * 0.8);
        }
        res.month.serial = serial;
        res.month.profit = profit;
        v.months = [...v.months, res.month].slice(-24);
        p.career.money += profit;
        ledgerAdd('ventures', profit);
        if (res.events[0]) { v.log = [res.events[0], ...v.log].slice(0, 12); log.push(`${VENTURE_BY_TYPE[v.type].emoji} ${v.name}: ${res.events[0]}`); }
        else log.push(`${VENTURE_BY_TYPE[v.type].emoji} ${v.name}: ${profit >= 0 ? '+' : '−'}$${Math.abs(profit).toLocaleString()} this month.`);
        if (v.redMonths === 3) pushNotification(state, { kind: 'business', title: `${v.name} is losing money`, body: 'Three months in the red. Cut costs, change the price, or sell before it gets worse.', artSeed: `venture|${v.id}` });
      }
    }
    // Rent from what you've built.
    for (const proj of state.devProjects ?? []) {
      const rent = monthlyRent(proj, m.propertyIndex) * months;
      if (rent > 0) { p.career.money += rent; proj.totalRent += rent; ledgerAdd('rent', rent); }
    }
    // Legacy holdings.
    for (const inv of state.investments) {
      p.career.money += inv.monthlyIncome * months;
      ledgerAdd('investments', inv.monthlyIncome * months);
      const changeRange = inv.riskLevel === 'low' ? 0.02 : inv.riskLevel === 'medium' ? 0.08 : 0.2;
      inv.currentValue = Math.max(inv.initialCost * 0.1, inv.currentValue * (1 + (Math.random() - 0.4) * changeRange));
    }
    for (const biz of state.businesses) {
      const profit = (biz.monthlyRevenue - biz.monthlyCosts) * months;
      p.career.money += profit;
      ledgerAdd('business', profit);
    }
  }

  // Building sites.
  for (const proj of state.devProjects ?? []) {
    if (proj.stage !== 'building') continue;
    if (Math.random() < 1 - Math.pow(1 - 1 / 30, days)) {
      const line = buildMonth(proj, { lawyer: (state.crew ?? []).some((c) => c.role === 'lawyer'), assistant: !!crewOn(state, 'personal_assistant', 'errands') }, Math.random);
      if (line) { proj.log = [line, ...proj.log].slice(0, 10); log.push(`🏗️ ${line}`); }
    }
    if (proj.owed > 0 && proj.doneSerial !== undefined) proj.doneSerial += Math.min(days, 7); // work stops while unpaid
    if (proj.owed <= 0 && proj.doneSerial !== undefined && serial >= proj.doneSerial) {
      proj.stage = 'done';
      proj.renting = true;
      const b = buildOf(proj.build!);
      proj.log = [`Finished. ${b.name} in the ${zoneOf(proj.zone).name.toLowerCase()} — ready to rent or sell.`, ...proj.log];
      log.push(`🏗️ Your ${b.name.toLowerCase()} is finished.`);
      pushNotification(state, { kind: 'business', title: `${b.emoji} ${b.name} finished`, body: 'Rent it out for monthly income, or sell it.', artSeed: `dev|${proj.id}` });
    }
  }

  // The sports book: yesterday's matches are played and bets settle.
  const cas = casinoOf(state);
  // Old local bets placed before the world football book still settle; no new local fixtures.
  if (cas.bets.some((b) => !b.settled) && (!cas.fixtures.length || cas.fixtures[0].serial < serial)) {
    const played = cas.fixtures.map((f) => (f.result ? f : playFixture(f, Math.random)));
    for (const b of cas.bets) {
      if (b.settled) continue;
      const f = played.find((x) => x.id === b.fixtureId);
      if (!f || !f.result) continue;
      b.settled = true;
      b.won = f.result === b.pick;
      const payout = b.won ? Math.round(b.stake * b.odds) : 0;
      // The stake left your account (and the casino net) when the bet was placed.
      if (payout) { p.career.money += payout; cas.net += payout; cas.biggestWin = Math.max(cas.biggestWin, payout - b.stake); ledgerAdd('casino', payout); }
      const line = `${b.won ? '✅' : '❌'} ${b.label} — ${f.home} ${f.score} ${f.away}${b.won ? ` · won $${payout.toLocaleString()}` : ''}`;
      cas.history = [line, ...cas.history].slice(0, 30);
      log.push(`🎰 ${line}`);
    }
    cas.bets = cas.bets.filter((b) => !b.settled).concat(cas.bets.filter((b) => b.settled).slice(-10));
    cas.fixtures = [];
  }

  // World football: tomorrow's fixtures, and anything that finished.
  ensureFixtures(state);
  settleFootball(state, nowMinuteOf(state));

  // Retirement, semi-retirement, business focus, comebacks.
  careerModeTick(state, serial, days, log);
  // The shops: a new drop every other Friday.
  dripTick(state);
  // The journal picks up the day's big moments.
  captureMemories(state);

  // Net worth, weekly.
  const hist = state.wealthHistory ?? (state.wealthHistory = []);
  if (!hist.length || serial - hist[hist.length - 1].serial >= 7) {
    hist.push({ serial, net: netWorthOf(state).total });
    if (hist.length > 104) hist.shift();
  }
}

/**
 * The social media manager posts for you through the week: what's going on in
 * your career right now, in your name, marked as run by your team. Your pages
 * stay active and the comments get answered.
 */
function teamPosts(state: GameState, manager: string, n: number, serial: number): void {
  const p = state.player;
  if (!p) return;
  const stats = socialStatsOf(state);
  const released = state.songs.filter((x) => isSongReleased(x));
  const latest = released[released.length - 1];
  const fresh = latest && (latest.weeksOut ?? 9) <= 4 ? latest : undefined;
  const show = (state.scheduledShows ?? []).find((x) => x.serial >= serial);
  const nom = Object.values(state.awardSeasons ?? {}).find((x) => x.phase === 'nominations' && x.categories.some((c) => c.nominees.some((m) => m.isPlayer)));
  const nomBody = nom ? bodiesFor(state).find((b) => b.id === nom.bodyId) : undefined;
  const ideas: [SocialApp, string, PostKind, string?][] = [];
  if (fresh) ideas.push(['chirp', `"${fresh.title}" is still out everywhere 🎧 thank you for the love`, 'announce', fresh.id], ['snapgram', `"${fresh.title}" 🖤`, 'cover', fresh.id], ['clip', `Doing the "${fresh.title}" challenge — your turn 💃`, 'challenge', fresh.id]);
  if (show) ideas.push(['snapgram', `${show.city ?? 'Next show'} — see you soon 🎟️ link in bio`, 'photo']);
  if (nomBody) ideas.push(['chirp', `Nominated at the ${nomBody.name} 🙏🏾 vote if you've got love for us`, 'thought']);
  ideas.push(['snapgram', 'Studio flow 📸', 'photo'], ['clip', 'Behind the scenes this week 🎬', 'bts'], ['circle', 'Day ones — what do you want to hear next? Reply below 👇🏾', 'community'], ['chirp', 'Grateful for every one of you. More coming.', 'thought']);
  const minute = gameMinute(state);
  for (let i = 0; i < n; i++) {
    const [app, content, kind, songId] = ideas[(serial + i * 3) % ideas.length];
    const post: SocialPost = {
      id: uuidv4(), platform: app, authorId: 'player', authorName: p.artistName, content, likes: 0, shares: 0, comments: [],
      timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 15, daySerial: serial, kind, relatedSongId: songId, byTeam: manager,
    };
    // Spread through the week, at the hours people actually scroll.
    const at = minute + i * Math.round(1440 * 7 / Math.max(1, n)) / 2 + 60;
    const t = postTarget({ audience: Math.max(200, stats[app].followers), app, heat: 0.3, roll: Math.random() });
    post.target = t; post.postedMinute = Math.round(at); post.likes = t.likes; post.shares = t.shares; if (t.views) post.views = t.views;
    post.comments = socialComments(post, Math.max(2, Math.min(8, t.comments)), commentContext(state, false, `${post.id}|team`), new Date().toISOString());
    const when = commentMinutes(post.postedMinute, post.comments.length, hashString(post.id) >>> 0);
    post.comments.forEach((c, k) => { c.minute = when[k]; });
    state.socialPosts.unshift(post);
    stats[app].lastPostSerial = serial;
  }
}

const GROW_TRAIT: Record<string, VisibleTrait> = { engineer: 'meticulous', producer: 'creative', songwriter: 'creative', publicist: 'charismatic', dj: 'charismatic', stylist: 'creative', photographer: 'creative', accountant: 'smart', lawyer: 'ruthless', personal_assistant: 'smart', trainer: 'brave', vocal_coach: 'meticulous' };

/**
 * People change. Six good months in and somebody can pick up a strength they
 * didn't have; a lazy hire who got warned and then delivered can turn it
 * around for good.
 */
function crewCharacterGrowth(state: GameState, c: CrewMember, log: string[]): void {
  const months = c.monthsServed ?? 0;
  const grades = c.perf?.grades ?? [];
  const good = grades.length >= 2 && grades.slice(0, 2).every((g) => g === 'A' || g === 'B');
  if ((c.hidden ?? []).includes('lazy') && c.warnedSerial !== undefined && good && (c.morale ?? 70) >= 55) {
    c.hidden = (c.hidden ?? []).filter((t) => t !== 'lazy');
    const line = `🌱 ${c.npcName} turned it around — two strong months since you had that talk. Not lazy any more.`;
    log.push(line);
    pushNotification(state, { kind: 'business', title: `🌱 ${c.npcName.split(' ')[0]} turned it around`, body: 'Two strong months since you had that talk. The work ethic is real now.', artSeed: `npc|${c.npcId}`, action: { type: 'team' } });
    return;
  }
  if ((months === 6 || months === 12 || months === 24) && good && (c.morale ?? 70) >= 60 && (c.visible ?? []).length < 3) {
    const t = GROW_TRAIT[c.role] ?? 'smart';
    if ((c.visible ?? []).includes(t)) return;
    c.visible = [...(c.visible ?? []), t];
    const spec = VISIBLE_TRAITS[t];
    log.push(`🌱 ${c.npcName} has grown with you: now ${spec.emoji} ${spec.label}.`);
    pushNotification(state, { kind: 'business', title: `🌱 ${c.npcName.split(' ')[0]} has grown: ${spec.emoji} ${spec.label}`, body: `${months} months with you. ${spec.blurb}`, artSeed: `npc|${c.npcId}`, action: { type: 'team' } });
  }
}

/** A week that matters: a release just out, a show coming, an award night close. */
function bigWeekFor(state: GameState, serial: number): boolean {
  if (state.songs.some((x) => isSongReleased(x) && serial - releaseSerialOf(state, x, -999) <= 7)) return true;
  if (state.scheduledShows.some((x) => x.serial >= serial && x.serial - serial <= 7)) return true;
  if ((state.bookedGigs ?? []).some((g) => g.serial >= serial && g.serial - serial <= 7)) return true;
  return Object.values(state.awardSeasons ?? {}).some((x) => x.phase !== 'done' && !x.quiet && x.cal.ceremony >= serial && x.cal.ceremony - serial <= 7 && x.categories.some((c) => c.nominees.some((n) => n.isPlayer)));
}

/** Weekly: everybody on the payroll does what you have them on — or doesn't. Monthly: the review. */
function teamWorkTick(state: GameState, serial: number, days: number, weeklyStreamIncome: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  const newWeek = Math.floor(serial / 7) !== Math.floor((serial - days) / 7);
  const newMonth = serialToDate(serial).month !== serialToDate(serial - days).month;
  if (!newWeek && !newMonth) return;
  if (newMonth) crewReviewTick(state, serial);
  if (!newWeek) return;
  const lines: string[] = [];
  const big = bigWeekFor(state, serial);
  for (const c of state.crew ?? []) {
    const style = workStyleOf(c);
    const warned = c.warnedSerial !== undefined && serial - c.warnedSerial <= 45;
    const effort = weekEffort(style, c.morale ?? 70, Math.random(), big, warned);
    c.perf = recordWeek(c.perf, effort.kind);
    const special = effortLine(c.npcName, effort.kind, style, `${c.id}|${serial}`);
    // Finding out who they are: a month in, you know.
    if (!c.styleKnown && knowsStyle(c.perf, c.monthsServed ?? 0)) {
      c.styleKnown = true;
      const ws = WORK_STYLE[style];
      pushNotification(state, { kind: 'business', title: `🔎 You know ${c.npcName.split(' ')[0]} now: ${ws.emoji} ${ws.label}`, body: ws.line, artSeed: `npc|${c.npcId}`, action: { type: 'team' } });
      remember(state, 'people', `${c.npcName} turned out to be ${ws.label.toLowerCase()}: ${ws.line}`, { npcIds: [c.npcId], weight: 2 });
    }
    if (effort.kind === 'none') {
      c.lastWork = special ?? `${c.npcName.split(' ')[0]} did nothing this week.`;
      lines.push(c.lastWork);
      continue;
    }
    const res = weekOfWork(c.role, c.assignment, c.skill, c.morale ?? 70, { fame: blendedFame(p), weeklyStreamIncome, studioLevel: buildingLevel(state.studio?.levels), npcName: c.npcName, special: specialSkillOf(c.npcId, c.role, c.skill)?.id });
    if (!res) { if (special) c.lastWork = special; continue; }
    const k = effort.mult;
    const scaled = (v: number | undefined) => (v ? Math.round(v * k * 10) / 10 : 0);
    const money = Math.round(scaled(res.money));
    if (money) { p.career.money += money; p.career.totalEarnings += money; ledgerAdd('team_work', money); }
    const mom = scaled(res.momentum);
    if (mom) addMomentum(state, mom);
    const rep = scaled(res.rep);
    if (rep) p.career.reputation = Math.min(100, p.career.reputation + rep);
    const fame = scaled(res.fame);
    if (fame) p.career.localFame = Math.min(100, p.career.localFame + fame);
    const followers = Math.round(scaled(res.followers));
    if (followers) { const st = socialStatsOf(state); st.snapgram.followers += Math.round(followers * 0.5); st.clip.followers += Math.round(followers * 0.3); st.chirp.followers += Math.round(followers * 0.2); }
    const posts = res.posts ? Math.max(1, Math.round(res.posts * Math.min(1.5, k))) : 0;
    if (posts) teamPosts(state, c.npcName, posts, serial);
    for (const [key, v] of Object.entries(res.stats ?? {})) {
      const stats = p.stats as unknown as Record<string, number>;
      if (typeof stats[key] === 'number') stats[key] = Math.min(100, stats[key] + v * k);
    }
    c.lastWork = special ? `${special} ${res.line}` : res.line;
    lines.push(c.lastWork);
  }
  if (lines.length) log.push(`👥 Team week: ${lines.slice(0, 2).join(' ')}${lines.length > 2 ? ` (+${lines.length - 2} more on the Team page)` : ''}`);
}

/**
 * The first of the month: every hire's month is graded. Two bad months in a
 * row and the manager (or whoever is most senior) says it in the group.
 */
function crewReviewTick(state: GameState, serial: number): void {
  const p = state.player;
  if (!p || !(state.crew ?? []).length) return;
  const graded: { c: CrewMember; grade: string }[] = [];
  for (const c of state.crew) {
    if (!c.perf) continue;
    const g = gradeOf(c.perf.month);
    if (!g) continue;
    const style = workStyleOf(c);
    c.lastReview = { serial, grade: g.grade, text: reviewLine(c.npcName, c.perf.month, g.grade, style, !!c.styleKnown) };
    c.perf = { ...c.perf, grades: [g.grade, ...c.perf.grades].slice(0, 6), month: { none: 0, low: 0, normal: 0, extra: 0, clutch: 0 } };
    c.strikes = g.grade === 'D' || g.grade === 'F' ? (c.strikes ?? 0) + 1 : g.grade === 'A' || g.grade === 'B' ? Math.max(0, (c.strikes ?? 0) - 1) : (c.strikes ?? 0);
    // How the month went is how they feel about it.
    c.morale = Math.max(0, Math.min(100, (c.morale ?? 70) + (g.grade === 'A' ? 3 : g.grade === 'F' ? -3 : 0)));
    graded.push({ c, grade: g.grade });
  }
  if (!graded.length) return;
  const mgr = managerOf(state);
  const speaker = mgr ? { from: mgr.id, name: mgr.name, role: 'manager' } : (() => { const top = [...state.crew].sort((a, b) => b.skill - a.skill)[0]; return { from: top.npcId, name: top.npcName, role: top.role }; })();
  const best = graded.filter((x) => x.grade === 'A').map((x) => x.c.npcName.split(' ')[0]);
  const worst = graded.filter((x) => x.grade === 'D' || x.grade === 'F');
  const summary = `Month review — ${graded.map((x) => `${x.c.npcName.split(' ')[0]} ${x.grade}`).join(', ')}.${best.length ? ` ${best.join(' and ')} carried us.` : ''}${worst.length ? ` ${worst.map((x) => x.c.npcName.split(' ')[0]).join(' and ')} need${worst.length === 1 ? 's' : ''} to step up.` : ''}`;
  pushTeamLines(state, [{ ...speaker, text: summary, key: `review:${serial}` }], serial);
  for (const x of worst) {
    if ((x.c.strikes ?? 0) < 2) continue;
    const n = x.c.npcName.split(' ')[0];
    pushTeamLines(state, [{ ...speaker, text: pickLine([`Real talk, ${p.artistName.split(' ')[0]}: ${n} has let us down two months running. Warn them properly or let them go — the rest of the team sees it.`, `I'll say what everybody's thinking: ${n} isn't pulling their weight. Your call, but I'd make a change.`], `${x.c.id}|${serial}`), key: `fire:${x.c.id}` }], serial);
    pushNotification(state, { kind: 'business', title: `⚠️ ${x.c.npcName} is underperforming`, body: `${x.c.lastReview?.text ?? ''} Warn them, or let them go on the Team page.`, artSeed: `npc|${x.c.npcId}`, action: { type: 'team' } });
  }
}

/** Every bet goes through here: the money, the VIP points, the headlines. */
function settleBet(state: GameState, stake: number, payout: number, what: string): string {
  const p = state.player!;
  const cas = casinoOf(state);
  const serial = dateToSerial(state.gameDate);
  if (cas.day.serial !== serial) cas.day = { serial, net: 0 };
  const net = payout - stake;
  p.career.money += payout;
  ledgerAdd('casino', payout);
  cas.net += net;
  cas.day.net += net;
  cas.vipPoints += stake;
  cas.biggestWin = Math.max(cas.biggestWin, net);
  cas.biggestLoss = Math.min(cas.biggestLoss, net);
  const line = `${what}: ${net >= 0 ? `+$${net.toLocaleString()}` : `−$${Math.abs(net).toLocaleString()}`}`;
  cas.history = [line, ...cas.history].slice(0, 30);
  const fame = blendedFame(p);
  if (net >= 50_000 && fame >= 15) {
    state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} wins big at the casino`, fullStory: `A $${net.toLocaleString()} win, according to people who were there.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 4, category: 'general' });
    addMomentum(state, 1);
  }
  if (cas.day.net <= -40_000 && fame >= 15 && !cas.day.reported) {
    cas.day.reported = true;
    p.career.reputation = Math.max(0, p.career.reputation - (crewWithSkill(state.crew, 'fixer') ? 0.75 : 1.5));
    state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} spotted losing a fortune at the casino`, fullStory: `Sources say over $${Math.abs(cas.day.net).toLocaleString()} went in one night.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 5, category: 'scandal' });
  }
  return line;
}

function canStake(state: GameState, stake: number): string | null {
  const p = state.player;
  if (!p) return 'No career.';
  const cas = casinoOf(state);
  if (cas.visitSerial !== dateToSerial(state.gameDate)) return 'Walk in first.';
  if (!Number.isFinite(stake) || stake < 10) return 'The minimum bet is $10.';
  if (stake > casinoLimitOf(state)) return `The table limit for ${vipTier(cas.vipPoints)} players is $${casinoLimitOf(state).toLocaleString()}.`;
  if (stake > p.career.money) return 'You don\'t have that much cash.';
  return null;
}

// ─── DMS THAT READ LIKE DMS, AND PLANS ON THE CLOCK ────────────────────────

function pushDM(state: GameState, npcId: string, msg: Omit<DMMessage, 'id' | 'npcId' | 'timestamp' | 'read'> & { read?: boolean }): DMMessage {
  // Real people don't text you in this game; their people do. Anything that
  // reaches a real-named thread is labelled as coming from their team.
  if (isRealId(npcId) && !msg.fromPlayer && !msg.system && !msg.content.startsWith('📨')) {
    const who = (raw(state.npcs) as NPC[]).find((n) => n.id === npcId)?.name ?? 'Their';
    msg = { ...msg, content: `📨 ${who}'s team: ${msg.content}` };
  }
  const thread = state.dmThreads[npcId] ?? (state.dmThreads[npcId] = { npcId, messages: [], unread: 0 });
  const m: DMMessage = { id: uuidv4(), npcId, timestamp: new Date().toISOString(), read: msg.read ?? true, ...msg };
  thread.messages.push(m);
  if (!m.read && !m.fromPlayer && !m.system) thread.unread += 1;
  if (thread.messages.length > 160) thread.messages.splice(0, thread.messages.length - 160);
  return m;
}

/**
 * What they actually text back about a verse. The story ("X's people came back
 * with a number…") is narration — it goes in as a small note, never as a
 * bubble from them.
 */
/** What a real artist's manager says about a verse — their business, never a quote from them. */
function managerVoice(who: string, kind: 'free' | 'terms' | 'declined' | 'took' | 'counter' | 'final' | 'off' | 'hold', fee: number, seed: string, song: string): string {
  const f = `$${Math.round(fee).toLocaleString()}`;
  const lines: Record<typeof kind, string[]> = {
    free: [`Good news — ${who} heard "${song}" and is happy to jump on it, no fee. Send the stems.`, `We played "${song}" for ${who}. They're in, as a favour. Send the files over.`],
    terms: [`We heard "${song}" and ${who} is interested. The fee is ${f} for the verse and they keep their publishing.`, `${who} likes the record. Their rate for this is ${f}. Let me know if you want to go ahead.`, `Thanks for sending "${song}". ${who} can do it for ${f}.`],
    declined: [`Thanks for sending "${song}". ${who} is going to pass this time — the schedule is full. Keep making music.`, `${who} has passed on this one. Nothing personal, it's just not the right moment.`],
    took: [`${f} works for us. Send the stems when you're ready.`, `We can do ${f}. I'll tell ${who}.`],
    counter: [`We can't go that low. ${f} and we have a deal.`, `The best I can do is ${f}.`],
    final: [`${f} is our final number.`, `That's as low as it goes: ${f}.`],
    off: [`That offer isn't serious. We're done on this one.`, `We'll leave it there. Good luck with the record.`],
    hold: [`The number is ${f}.`, `Like I said, ${f}.`],
  };
  const list = lines[kind];
  return `📨 ${who}'s manager: ${list[hashString(seed) % list.length]}`;
}

function featureVoice(kind: 'free' | 'terms' | 'declined' | 'took' | 'counter' | 'final' | 'off' | 'hold', fee: number, seed: string): string {
  const f = `$${Math.round(fee).toLocaleString()}`;
  const lines: Record<typeof kind, string[]> = {
    free: ['I\'m in. No fee — send the stems 🔥', 'For you? Free. Send it over', 'Say less. I got you, no charge 🙏🏾'],
    terms: [`I'm down. ${f} for the verse, I keep my publishing.`, `Love the record. My rate is ${f}.`, `${f} and it's done. Send the stems when you're ready.`],
    declined: ['Not for me this time, respect 🙏🏾', 'Locked in on my own project right now. Can\'t.', 'It\'s not my lane. Keep pushing though'],
    took: [`${f} works. Deal 🤝🏾`, `Cool, ${f} it is. Send the stems.`, `Fine — ${f}. Let's work.`],
    counter: [`Can't do that. ${f} and we're good.`, `Meet me at ${f}.`, `${f} — that's as low as I go right now.`],
    final: [`${f}. Final answer.`, `Last time: ${f} or I'm out.`],
    off: ['Nah. That offer was disrespectful. Forget it.', 'I\'m good. Find someone else.'],
    hold: [`Come again? ${f} is the price.`, `Be serious. ${f}.`],
  };
  const list = lines[kind];
  return list[hashString(seed) % list.length];
}

function scheduleDM(state: GameState, npcId: string, text: string, atMinute: number): void {
  const list = state.pendingDMs ?? (state.pendingDMs = []);
  list.push({ id: uuidv4(), npcId, text, atMinute });
  if (list.length > 40) list.splice(0, list.length - 40);
}

function deliverPendingDMs(state: GameState, now: number): void {
  const list = state.pendingDMs;
  if (!list?.length) return;
  const due = list.filter((d) => d.atMinute <= now);
  if (!due.length) return;
  state.pendingDMs = list.filter((d) => d.atMinute > now);
  for (const d of due) {
    if (isBlocked(state, d.npcId)) continue;
    pushDM(state, d.npcId, { fromPlayer: false, content: d.text, read: false });
  }
}

/** Put a plan in the diary, with a card in your chat with them. */
function createAppointment(state: GameState, npc: Pick<NPC, 'id' | 'name' | 'city'>, kind: Appointment['kind'], atMinute: number, from: Appointment['from'], status: Appointment['status'] = 'confirmed', extra: Partial<Pick<Appointment, 'place' | 'title' | 'fee' | 'bringOut' | 'cypher' | 'pitch'>> = {}): Appointment {
  const list = state.appointments ?? (state.appointments = []);
  const a: Appointment = {
    id: uuidv4(), npcId: npc.id, npcName: npc.name, kind,
    title: `${KIND_LABEL[kind].label} with ${npc.name}`,
    // You meet where you are — they come through. A gig is at their venue.
    place: placeFor(kind === 'gig' || !state.player ? npc : { ...npc, city: state.player.city }, kind, buildingLevel(state.studio?.levels) >= 2),
    atMinute, from, status, createdSerial: dateToSerial(state.gameDate),
    ...extra,
  };
  list.push(a);
  if (list.length > 40) state.appointments = list.filter((x, i) => x.status === 'confirmed' || x.status === 'live' || i >= list.length - 25);
  pushDM(state, npc.id, { fromPlayer: false, system: true, content: `${KIND_LABEL[kind].emoji} ${status === 'proposed' ? `${npc.name.split(' ')[0]} invited you: ` : ''}${a.bringOut ? 'Their show — they bring you out' : KIND_LABEL[kind].label} · ${whenLabel(atMinute, nowMinuteOf(state))} · ${a.place}${a.fee ? ` · $${a.fee.toLocaleString()} cash after the set` : ''}`, appointmentId: a.id, read: status !== 'proposed' });
  return a;
}

/** "20:00", "8pm", "8:30 PM" → the next time that comes round at least 45 minutes from now. */
function parseClock(text: string | undefined, now: number): number | null {
  if (!text) return null;
  const m = /(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i.exec(text);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2] ?? 0);
  const ap = m[3]?.toLowerCase();
  if (ap === 'pm' && h < 12) h += 12;
  if (ap === 'am' && h === 12) h = 0;
  if (h > 23 || min > 59) return null;
  const day = Math.floor(now / MINUTES_PER_DAY) * MINUTES_PER_DAY;
  let at = day + h * 60 + min;
  while (at - now < 45) at += MINUTES_PER_DAY;
  return at;
}

function pickLine(lines: string[], seed: string): string {
  return lines[Math.abs(hashString(seed)) % lines.length];
}

/** Anything else on the clock (final whistles) due by this minute? */
function clockEventsDue(state: GameState, nowAbs: number): boolean {
  return (state.football?.matches ?? []).some((m) => !m.settled && m.kickoff + MATCH_LENGTH <= nowAbs);
}

function footballOf(state: GameState): FootballState {
  if (!state.football) state.football = newFootball();
  return state.football;
}

/** Count a finished match: league table, cup table or knockout, results feed. */
function recordMatch(state: GameState, fb: FootballState, m: FootballMatch): void {
  const season = seasonYearOf(Math.floor(m.kickoff / MINUTES_PER_DAY));
  const { h, a } = finalScore(m);
  const pens = m.pens ? ` (${m.pens === 'h' ? m.home : m.away} on pens)` : '';
  fb.results = [`${LEAGUE_BY_ID[m.league]?.flag ?? '⚽'} ${m.home} ${h}–${a} ${m.away}${pens}${m.stage ? ` · ${m.stage}` : ''}`, ...fb.results].slice(0, 60);
  if (season !== fb.season) {
    // Last season's final, whistled after the calendar ticked over.
    if (m.ko === 'final') honour(state, fb, season, 'ucl', koWinner(m));
    return;
  }
  if (m.league === 'ucl') {
    const cup = fb.cup ?? (fb.cup = { season, table: {}, ko: {} });
    if (m.ko) {
      cup.ko[m.ko] = koWinner(m);
      if (m.ko === 'final') honour(state, fb, season, 'ucl', koWinner(m));
    } else addRow(cup.table, m);
  } else addToTable(fb.tables, m);
}

function honour(state: GameState, fb: FootballState, season: number, league: string, team: string): void {
  const list = fb.honours ?? (fb.honours = []);
  if (list.some((x) => x.season === season && x.league === league)) return;
  list.unshift({ season, league, team });
  fb.honours = list.slice(0, 80);
  const L = LEAGUE_BY_ID[league];
  if (state.player) pushNotification(state, { kind: 'business', title: `${L?.flag ?? '🏆'} ${team} ${league === 'ucl' ? 'win the Champions Cup' : `are ${L?.name.split(' · ')[0]} champions`}`, body: `Season ${seasonLabel(season)} is in the books.`, artSeed: `honour|${season}|${league}` });
}

/** A new season: crown the champions, wipe the tables, draw the cup. */
function rollSeason(state: GameState, fb: FootballState, year: number): void {
  if (fb.season !== undefined) {
    for (const [lg, rows] of Object.entries(fb.tables)) {
      const top = Object.entries(rows).sort((x, y) => sortRows(x[1], y[1]))[0];
      if (top && top[1].p > 0) honour(state, fb, fb.season, lg, top[0]);
    }
  } else {
    // A save from before seasons existed: its fixtures were random pairings.
    // Keep only matches someone has money on, and rebuild from the calendar.
    const openIds = new Set(fb.bets.filter((b) => b.status === 'open').flatMap((b) => b.selections.map((x) => x.matchId)));
    fb.matches = fb.matches.filter((m) => openIds.has(m.id));
    fb.scheduled = [];
    fb.through = seasonInfo(year).start - 1;
  }
  fb.tables = {};
  fb.cup = { season: year, table: {}, ko: {} };
  fb.season = year;
}

/**
 * The fixture board: today's and tomorrow's matches are up with odds. Days the
 * player slept through are played out of sight so the tables stay true, and a
 * new career starts mid-season with the season so far already played.
 */
function ensureFixtures(state: GameState): void {
  const fb = footballOf(state);
  const today = dateToSerial(state.gameDate);
  if (fb.through === undefined && fb.season === undefined) fb.through = seasonInfo(seasonYearOf(today)).start - 1;
  for (let d = (fb.through ?? today - 1) + 1; d <= today + 1; d++) {
    const yr = seasonYearOf(d);
    if (fb.season !== yr) rollSeason(state, fb, yr);
    if (fb.scheduled.includes(d)) continue;
    const ms = fixturesForDay(d, fb.cup, Math.random);
    if (d < today) {
      for (const m of ms) recordMatch(state, fb, m);
    } else {
      fb.matches.push(...ms);
      fb.scheduled.push(d);
    }
    fb.through = d;
  }
  fb.scheduled = fb.scheduled.filter((d) => d >= today - 3);
  const openIds = new Set(fb.bets.filter((b) => b.status === 'open').flatMap((b) => b.selections.map((x) => x.matchId)));
  fb.matches = fb.matches.filter((m) => m.kickoff >= (today - 2) * MINUTES_PER_DAY || openIds.has(m.id));
}

/** Final whistles: tables, results and bets. */
function settleFootball(state: GameState, now: number): void {
  const fb = state.football;
  const p = state.player;
  if (!fb || !p) return;
  let any = false;
  for (const m of fb.matches) {
    if (m.settled || m.kickoff + MATCH_LENGTH > now) continue;
    m.settled = true;
    any = true;
    if (m.stage) recordMatch(state, fb, m);
  }
  if (!any) return;
  const byId = new Map(fb.matches.map((m) => [m.id, m]));
  const cas = casinoOf(state);
  for (const b of fb.bets) {
    if (b.status !== 'open') continue;
    const ms = b.selections.map((x) => byId.get(x.matchId));
    if (ms.some((m) => m && !m.settled)) continue;
    const won = b.selections.every((x, i) => { const m = ms[i]; return m ? selectionWon(x, m) : false; });
    b.status = won ? 'won' : 'lost';
    b.payout = won ? Math.round(b.stake * b.odds) : 0;
    const label = b.selections.length > 1 ? `${b.selections.length}-fold acca @ ${b.odds.toFixed(2)}` : `${b.selections[0].label} @ ${b.odds.toFixed(2)}`;
    if (won) {
      p.career.money += b.payout;
      cas.net += b.payout;
      cas.biggestWin = Math.max(cas.biggestWin, b.payout - b.stake);
      ledgerAdd('casino', b.payout);
      pushNotification(state, { kind: 'business', title: `⚽ Bet won: +$${(b.payout - b.stake).toLocaleString()}`, body: `${label} — $${b.stake.toLocaleString()} returned $${b.payout.toLocaleString()}.`, artSeed: `bet|${b.id}` });
      if (b.payout - b.stake >= 50_000 && blendedFame(p) >= 15) {
        state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} lands a huge football bet`, fullStory: `A $${b.stake.toLocaleString()} bet returned $${b.payout.toLocaleString()}.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 3, category: 'general' });
      }
    }
    cas.history = [`${won ? '✅' : '❌'} ${label} · $${b.stake.toLocaleString()}${won ? ` → $${b.payout.toLocaleString()}` : ''}`, ...cas.history].slice(0, 30);
  }
  fb.bets = fb.bets.filter((b) => b.status === 'open').concat(fb.bets.filter((b) => b.status !== 'open').slice(-30));
}

/** Minute-level things: late messages arriving, plans starting. */
function minuteTick(state: GameState, reason: 'clock' | 'rest' | 'skip' = 'clock'): void {
  const now = nowMinuteOf(state);
  deliverPendingDMs(state, now);
  settleFootball(state, now);
  // Award nights: you're in the room (the modal opens), or the world tells you.
  for (const season of Object.values(state.awardSeasons ?? {})) {
    if (season.phase !== 'nominations' || season.cal.ceremonyMinute > now) continue;
    const late = now - season.cal.ceremonyMinute;
    const going = !!season.rsvp && reason === 'clock' && late <= 180 && !state.activeAppointment && !state.activeHearing && !state.activeCeremony;
    runCeremony(state, season, going);
    if (going) { state.activeCeremony = { key: season.key, step: 'carpet', revealed: 0, notes: [] }; state.clockPaused = true; }
  }
  // Court dates: you're there (the modal opens), or your lawyer is, or nobody is.
  for (const c of state.cases ?? []) {
    if (c.status !== 'hearing') continue;
    for (const h of c.hearings) {
      if (h.done || h.atMinute > now) continue;
      const late = now - h.atMinute;
      if (reason === 'clock' && late <= 120 && !state.activeHearing && !state.activeAppointment) {
        state.activeHearing = `${c.id}|${h.id}`;
        state.clockPaused = true;
      } else if (state.activeHearing !== `${c.id}|${h.id}`) {
        runHearing(state, c, h, c.ourLawyer ? 'lawyer' : 'absent');
      }
    }
  }
  for (const a of state.appointments ?? []) {
    // A plan that was mid-scene when the game was closed goes back in the diary.
    if (a.status === 'live' && state.activeAppointment !== a.id) a.status = 'confirmed';
    if (a.status === 'proposed' && a.atMinute <= now) {
      a.status = 'cancelled';
      a.outcome = a.ignored ? 'You left it on read.' : 'You never answered the invite.';
      const n = state.npcs.find((x) => x.id === a.npcId);
      if (n) {
        // Leaving someone on read lands differently depending on who they are.
        const pp = personaOf(n);
        const hurt = a.ignored ? Math.round(3 + (1 - pp.forgiveness) * 5 + pp.ego * 2) : Math.round(1 + (1 - pp.forgiveness) * 2);
        n.relationshipScore = Math.max(-100, n.relationshipScore - hurt);
        if (a.ignored && pp.messy > 0.6 && Math.random() < pp.messy * 0.5 && !isRealId(n.id)) npcPost(state, n, pickLine(['Left on read by people I put on. Noted 🤐', 'Funny how quick people forget who picked up the phone for them.', 'Read 8:02pm. Cool cool cool.'], a.id));
        n.memoryLog = [...(n.memoryLog ?? []).slice(-9), `[${a.kind}] ${a.ignored ? 'Left my invite on read' : 'Never answered my invite'}`];
      }
      remember(state, 'plans', a.ignored ? `You left ${a.npcName} on read about the ${KIND_LABEL[a.kind].label.toLowerCase()}.` : `You never answered ${a.npcName}'s invite.`, { npcIds: [a.npcId], weight: 2, tone: 'bad' });
      continue;
    }
    if (a.status !== 'confirmed' || a.atMinute > now) continue;
    const late = now - a.atMinute;
    if (reason !== 'skip' && late <= 120 && !state.activeAppointment) {
      startAppointment(state, a, late);
    } else if (late > 120 || reason === 'skip') {
      autoAttendOrMiss(state, a, reason === 'rest' ? 'slept' : 'skip');
    }
  }
}

function startAppointment(state: GameState, a: Appointment, playerLate: number): void {
  const npc = state.npcs.find((n) => n.id === a.npcId);
  if (!npc) { a.status = 'cancelled'; return; }
  const persona = personaOf(npc);
  a.status = 'live';
  a.lateBy = a.kind === 'gig' ? 0 : Math.max(0, lateness(persona, a.id) - playerLate);
  if (playerLate > 10) a.outcome = `You're ${playerLate} minutes late.`;
  state.activeAppointment = a.id;
  state.clockPaused = true;
}

function autoAttendOrMiss(state: GameState, a: Appointment, reason: 'slept' | 'skip'): void {
  const p = state.player;
  const npc = state.npcs.find((n) => n.id === a.npcId);
  if (!p || !npc) { a.status = 'cancelled'; return; }
  const persona = personaOf(npc);
  const assistant = crewWithSkill(state.crew, 'organized');
  if (reason === 'skip' && (p.energy >= 12 || assistant)) {
    const choice = a.kind === 'studio' ? (p.energy >= 25 ? 'record' : 'vibe') : a.kind === 'party' ? 'network' : a.kind === 'gig' ? (p.energy >= 15 ? 'perform' : 'short') : 'vibe';
    const best = (state.songs ?? []).filter((s) => !isSongReleased(s) && !s.archivedAt).reduce((m, s) => Math.max(m, s.quality), 0);
    const res = resolveScene(a, choice, persona, { rel: npc.relationshipScore, unreleasedQuality: best, playerFame: blendedFame(p), producerSkill: npc.role === 'producer' ? producerSkillOf(npc as NPC) : undefined }, Math.random());
    finishAppointment(state, a, res, 'done', assistant && p.energy < 12 ? `${assistant.npcName.split(' ')[0]} got you there. ` : '');
    return;
  }
  const res = noShow(a, persona, reason === 'slept' ? 'slept' : 'missed', a.id);
  finishAppointment(state, a, res, 'missed');
}

const STAT_NAME = (k: string) => k.replace(/([A-Z])/g, ' $1').replace(/^./, (c) => c.toUpperCase());

/** Practice shows: a stat that moved up a whole point gets a line, a round number gets a notification. */
function statUps(state: GameState, before: ArtistStats, why: string): void {
  const p = state.player;
  if (!p) return;
  const ups: string[] = [];
  let milestone = '';
  for (const k of Object.keys(before) as (keyof ArtistStats)[]) {
    const a = Math.floor(before[k] ?? 0);
    const b = Math.floor(p.stats[k] ?? 0);
    if (b > a) {
      ups.push(`${STAT_NAME(k)} ${a} → ${b}`);
      if (Math.floor(b / 5) > Math.floor(a / 5)) milestone = `${STAT_NAME(k)} hit ${b}`;
    }
  }
  if (!ups.length) return;
  state.lastEventLog.unshift(`📈 ${ups.join(', ')} — from ${why}.`);
  state.lastEventLog = state.lastEventLog.slice(0, 12);
  if (milestone) pushNotification(state, { kind: 'milestone', title: `📈 ${milestone}`, body: `Practice pays: ${ups.join(', ')} — from ${why}.`, artSeed: `stat|${milestone}` });
}

/** What you can play a big name's team: your best record out, and your best one in the vault. */
export function pitchSongs(state: Pick<GameState, 'songs'>): { best?: Song; fresh?: Song } {
  const best = state.songs.filter((x) => isSongReleased(x)).sort((a, b) => b.quality - a.quality)[0];
  const fresh = state.songs.filter((x) => isVaultMaster(x)).sort((a, b) => b.quality - a.quality)[0];
  return { best, fresh };
}

function finishAppointment(state: GameState, a: Appointment, res: SceneResult & { post?: string }, status: Appointment['status'], prefix = ''): void {
  const serial = dateToSerial(state.gameDate);
  applyMomentEffects(state, res.effects, serial);
  a.status = status;
  a.outcome = prefix + res.text;
  a.chips = outcomeChips(res.effects, a.npcName);
  if (state.activeAppointment === a.id) state.activeAppointment = null;
  const npc = state.npcs.find((n) => n.id === a.npcId);
  if (npc) npc.memoryLog = [...(npc.memoryLog ?? []).slice(-9), `[${a.kind}] ${status === 'missed' ? 'You did not show up' : res.text.slice(0, 60)}`];
  pushDM(state, a.npcId, { fromPlayer: false, system: true, content: a.outcome, chips: a.chips });
  if (res.npcLine && !isRealId(a.npcId)) scheduleDM(state, a.npcId, res.npcLine, nowMinuteOf(state) + (status === 'missed' ? 20 : 45));
  if (res.post && npc) npcPost(state, npc, res.post);
  state.lastEventLog.unshift(`${KIND_LABEL[a.kind].emoji} ${a.title}: ${a.outcome}`);
  state.lastEventLog = state.lastEventLog.slice(0, 12);
  const what = KIND_LABEL[a.kind].label.toLowerCase();
  const hurt = res.effects.some((e) => e.k === 'rel' && e.v < 0);
  remember(state, 'plans',
    status === 'missed' ? `You didn't show up to the ${what} with ${a.npcName}.`
      : status === 'cancelled' ? `You bailed on the ${what} with ${a.npcName}.`
        : `${KIND_LABEL[a.kind].label} with ${a.npcName} at ${a.place}: ${res.text}`,
    { npcIds: [a.npcId], weight: status === 'done' ? 2 : 3, tone: status === 'done' && !hurt ? 'good' : 'bad' });
}

// ─── MONEY THAT MOVES BETWEEN PEOPLE ───────────────────────────────────────

/** A payment with a receipt: the chat shows it, the journal keeps it. */
function receipt(state: GameState, npcId: string, amount: number, text: string, opts: { notify?: boolean; memory?: string } = {}): void {
  if (!state.player || !amount) return;
  pushDM(state, npcId, { fromPlayer: false, system: true, content: text });
  if (opts.notify !== false) pushNotification(state, { kind: 'business', title: amount > 0 ? `💰 +$${amount.toLocaleString()}` : `💸 -$${Math.abs(amount).toLocaleString()}`, body: text.replace(/^[^\p{L}\p{N}$]+/u, ''), artSeed: `pay|${npcId}|${amount}` });
  if (opts.memory) remember(state, 'money', opts.memory, { npcIds: [npcId], weight: Math.abs(amount) >= 5000 ? 3 : 2 });
}

// ─── THE TERMS ON A VERSE ──────────────────────────────────────────────────
// Who an artist won't share a record with, the terms they set when they agree,
// and what happens when a release breaks them. See `sim/featureTerms.ts`.

function rivalsOf(npc: NPC, npcs: NPC[]): { id: string; name: string }[] {
  if (isRealId(npc.id)) {
    const idx = npcIndex(npcs);
    return seededRivalries(npcs).filter((r) => r.a === npc.id || r.b === npc.id).map((r) => idx.get(r.a === npc.id ? r.b : r.a)).filter((n): n is NPC => !!n).map((n) => ({ id: n.id, name: n.name }));
  }
  return sceneRivalsOf(npc, npcs).map((n) => ({ id: n.id, name: n.name }));
}

function attachTerms(state: GameState, req: FeatureRequest, npc: NPC, npcs: NPC[], serial: number): void {
  if (req.conditions || !state.player) return;
  const conds = conditionsFor({ npc, persona: personaOf(npc), playerFame: blendedFame(state.player), serial, rivals: rivalsOf(npc, npcs), real: isRealId(npc.id), seed: req.id });
  if (!conds.length) return;
  req.conditions = conds;
  pushDM(state, npc.id, { fromPlayer: false, system: true, content: `📜 Terms on "${req.songTitle}": ${conds.map((c) => c.text.replace(/^📨[^:]+: /, '')).join(' · ')}` });
}

/** The terms this release would break, in sentences — for the release screens. */
export function termsWarnings(state: GameState, songId: string, viaProject: boolean): string[] {
  const song = state.songs.find((x) => x.id === songId);
  if (!song) return [];
  const out: string[] = [];
  const idx = npcIndex(state.npcs as NPC[]);
  const featured = (song.featuredArtists ?? []).map((id) => idx.get(id)).filter((n): n is NPC => !!n);
  for (const r of state.featureRequests) {
    if (r.songId !== songId || r.status !== 'added' || !r.conditions?.length) continue;
    const others = featured.filter((n) => n.id !== r.npcId).map((n) => ({ id: n.id, name: n.name, fame: n.fame }));
    for (const c of r.conditions) {
      const b = breachOf(c, { others, viaProject, serial: dateToSerial(state.gameDate), released: true });
      if (b && c.kind !== 'release_window') out.push(`${r.npcName}: ${b}`);
    }
  }
  return out;
}

/** Take a guest's verse off one of your records. */
function removeVerseFromSong(state: GameState, songId: string, npcId: string, requestId: string): void {
  const song = state.songs.find((x) => x.id === songId);
  const req = state.featureRequests.find((x) => x.id === requestId);
  if (song) {
    const ids = song.featuredArtists ?? [];
    const names = song.featureArtistNames ?? [];
    const i = ids.indexOf(npcId);
    if (i >= 0) {
      song.featuredArtists = ids.filter((_, k) => k !== i);
      if (names.length === ids.length) song.featureArtistNames = names.filter((_, k) => k !== i);
      else song.featureArtistNames = names.filter((nm) => nm !== req?.npcName);
      // A verse was part of what made the record; without it it is a little less.
      song.quality = Math.max(1, Math.round((song.quality - 3) * 10) / 10);
    }
  }
  if (req) req.status = 'removed';
  const n = state.npcs.find((x) => x.id === npcId);
  pushNotification(state, { kind: 'feature', title: `${n?.name ?? 'Their'} verse is off "${song?.title ?? 'the record'}"`, body: 'The record carries on without it.', artSeed: `verse|${requestId}` });
}

/**
 * A record just came out (or a deadline passed): check every deal on it.
 * Broken terms reach the artist a few days later, the way news does.
 */
function checkFeatureTerms(state: GameState, songId: string, viaProject: boolean, released: boolean, npcsIn?: NPC[]): void {
  // Most records carry no deal at all: nothing to read.
  if (!state.featureRequests.some((r) => r.songId === songId && r.status === 'added')) return;
  const song = state.songs.find((x) => x.id === songId);
  const p = state.player;
  if (!song || !p) return;
  const npcs = npcsIn ?? (raw(state.npcs) as NPC[]);
  const serial = dateToSerial(state.gameDate);
  const idx = npcIndex(npcs);
  const featured = (song.featuredArtists ?? []).map((id) => idx.get(id)).filter((n): n is NPC => !!n);
  const relay = (() => { const law = state.crew.find((c) => c.role === 'lawyer'); const mgr = managerOf(state, npcs); return mgr ? { name: mgr.name, role: 'manager' } : law ? { name: law.npcName, role: 'lawyer' } : undefined; })();
  for (const r of state.featureRequests) {
    if (r.songId !== songId || r.status !== 'added') continue;
    const npc = idx.get(r.npcId);
    if (!npc) continue;
    const others = featured.filter((n) => n.id !== r.npcId).map((n) => ({ id: n.id, name: n.name, fame: n.fame }));
    const conds: FeatureCondition[] = [...(r.conditions ?? [])];
    // An artist with bad blood doesn't need a clause to mind sharing a record.
    const rivals = rivalsOf(npc, npcs);
    if (released && !conds.some((c) => c.kind === 'no_rival') && rivals.some((x) => others.some((o) => o.id === x.id)) && Math.random() < 0.55) {
      conds.push({ kind: 'no_rival', text: '', rivalIds: rivals.map((x) => x.id), rivalNames: rivals.map((x) => x.name) });
    }
    for (const c of conds) {
      // Still in the vault: only a deadline can be broken.
      if (!released && c.kind !== 'release_window') continue;
      const what = breachOf(c, { others, viaProject, serial, released });
      if (!what) continue;
      const list = r.breaches ?? (r.breaches = []);
      if (list.some((b) => b.kind === c.kind)) continue;
      const persona = personaOf(npc);
      const real = isRealId(npc.id);
      const how = enforcementOf(persona, real, r.fee, Math.random());
      list.push({ kind: c.kind, serial, how, text: what });
      remember(state, 'beef', `You broke ${npc.name}'s terms on "${song.title}": ${what}`, { npcIds: [npc.id], weight: 3, tone: 'bad' });
      const ask = Math.max(500, Math.round(((r.fee || featureFee(npc as unknown as FeatureCandidate, song.quality) * 0.4) * (how === 'renegotiate' ? 0.8 : 1.2)) / 100) * 100);
      const due = serial + 1 + Math.floor(Math.random() * 5);
      if (c.kind === 'release_window') {
        // Nobody has heard it — it's a deadline, not a release. They either let
        // it ride, or want the song out, money for the wait, or the verse back.
        const again = (c.extended ?? 0) > 0;
        if (how === 'ignore' && !again) {
          if (!real) scheduleDM(state, npc.id, pickLine([`"${song.title}" still isn't out, huh. Not what we said — but I won't chase it.`, `Four months and "${song.title}" is still sitting. Your call. I'm not going to fight about it.`], r.id), nowMinuteOf(state) + 60 * 24 * (due - serial));
          list[list.length - 1].settled = true;
          continue;
        }
        list[list.length - 1].how = again ? 'remove' : 'window';
        deliverMoment(state, buildBreachMoment({ requestId: r.id, songId, songTitle: song.title, npcId: npc.id, npcName: npc.name, real, how: again ? 'remove' : 'window', what: again ? 'You said two weeks, and it still isn\'t out.' : what, fee: r.fee, ask, litigious: persona.litigious, warmth: persona.warmth, relay }, due), serial, 'scheduled', due);
        continue;
      }
      if (how === 'ignore') {
        const live = state.npcs.find((x) => x.id === npc.id);
        if (live) live.relationshipScore = Math.max(-100, live.relationshipScore - 4);
        if (!real) scheduleDM(state, npc.id, pickLine([`Heard "${song.title}". Not what we agreed, but I'll let it go this once.`, `Saw what you did on "${song.title}". We move — but I noticed.`], r.id), nowMinuteOf(state) + 60 * 24 * (due - serial));
        list[list.length - 1].settled = true;
        continue;
      }
      if (how === 'sue') {
        deliverMoment(state, {
          kind: 'feature_breach', channel: 'team', npcName: relay?.name ?? 'Court registry', crewRole: relay?.role,
          title: `${npc.name} is taking "${song.title}" to court`,
          body: `${relay ? `"${npc.name}'s lawyers have been in touch about "${song.title}". ` : ''}${what} They are filing for breach of the feature deal.${relay ? '"' : ''}`,
          options: [{ id: 'remove', label: 'Take the verse off and settle' }, { id: 'refuse', label: 'Let them sue' }],
          expiresSerial: due + 4,
          data: { requestId: r.id, songId, npcId: npc.id, fee: r.fee, ask, real, name: npc.name, how: 'remove', litigious: 1, warmth: persona.warmth },
        }, serial, 'scheduled', due);
        continue;
      }
      if (how === 'public' && !real) {
        // They say it where everybody can see it.
        state.socialPosts.unshift({ id: uuidv4(), platform: 'chirp', authorId: npc.id, authorName: npc.name, content: pickLine([`Some people don't respect a deal. "${song.title}" — we'll talk.`, `Funny how terms don't matter once the song is out. Noted.`, `I said one thing about "${song.title}". ONE thing.`], r.id), likes: Math.round(400 + npc.fame * 120), shares: Math.round(40 + npc.fame * 15), comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 55, daySerial: serial, tags: [{ id: 'player', name: p.artistName }] } as SocialPost);
        livenPost(state, state.socialPosts[0]);
        p.career.reputation = Math.max(0, p.career.reputation - 1);
      }
      deliverMoment(state, buildBreachMoment({ requestId: r.id, songId, songTitle: song.title, npcId: npc.id, npcName: npc.name, real, how: how === 'public' && real ? 'remove' : how, what, fee: r.fee, ask, litigious: persona.litigious, warmth: persona.warmth, relay }, due), serial, 'scheduled', due);
    }
  }
}

// ─── FEATURE DEALS ─────────────────────────────────────────────────────────

/** A number is agreed on a verse for THEIR record: the terms decide what moves now. */
function sealInboundDeal(state: GameState, req: InboundRequest, fee: number): void {
  const p = state.player!;
  const npc = state.npcs.find((n) => n.id === req.npcId);
  const persona = npc ? personaOf(npc) : null;
  const terms = fee <= 0 ? 'free' : (req.payTerms ?? (persona ? payTermsFor(persona, npc!.fame, blendedFame(p), fee, Math.random()) : 'half'));
  const now = upfrontShare(terms, fee);
  const serial = dateToSerial(state.gameDate);
  req.status = 'agreed';
  req.agreedFee = fee;
  req.agreedDate = formatGameDate(state.gameDate);
  req.payTerms = terms;
  req.paidSoFar = now;
  req.dueSerial = serial + VERSE_DEADLINE_DAYS;
  if (now > 0) {
    p.career.money += now;
    p.career.totalEarnings += now;
    receipt(state, req.npcId, now, `💰 ${req.npcName} paid you $${now.toLocaleString()} ${terms === 'upfront' ? 'up front' : 'now (half)'} for your verse on "${req.npcSongTitle}".${terms === 'half' ? ` The other $${(fee - now).toLocaleString()} comes when you deliver.` : ''}`, { memory: `${req.npcName} paid you $${now.toLocaleString()} for a verse on "${req.npcSongTitle}".` });
  } else {
    pushDM(state, req.npcId, { fromPlayer: false, system: true, content: terms === 'free' ? `🤝 Deal: a verse on "${req.npcSongTitle}", no fee. Due in ${VERSE_DEADLINE_DAYS} days.` : `🤝 Deal: $${fee.toLocaleString()} for your verse on "${req.npcSongTitle}", paid when you deliver. Due in ${VERSE_DEADLINE_DAYS} days.` });
  }
  pushNotification(state, { kind: 'feature', title: `"${req.npcSongTitle}" is in your studio`, body: `Add your verse in Studio → Features. Due in ${VERSE_DEADLINE_DAYS} days.`, artSeed: `npc|${req.npcId}`, action: { type: 'features', id: req.id } });
}

/**
 * A verse you've already agreed to in the chat: no second ask, no letter. The
 * record goes straight into Studio → Features with its due date, and the chat
 * gets their line and a small deal note.
 */
function agreeInboundVerse(state: GameState, npc: NPC, song: Song, terms: 'free' | 'trade', value: number, quiet = false): InboundRequest {
  const serial = dateToSerial(state.gameDate);
  const req: InboundRequest = {
    id: uuidv4(), npcSongId: song.id, npcSongTitle: song.title, songQuality: song.quality,
    npcId: npc.id, npcName: npc.name, status: 'agreed', sentDate: formatGameDate(state.gameDate),
    openingOffer: 0, offer: 0, ceiling: 0, reason: '', negotiationRound: 0,
    agreedFee: 0, agreedDate: formatGameDate(state.gameDate), payTerms: terms,
    // A trade is paid in kind: what they gave you is what they'd want back if you never deliver.
    paidSoFar: terms === 'trade' ? value : 0,
    dueSerial: serial + VERSE_DEADLINE_DAYS,
  };
  state.inboundRequests.push(req);
  if (!quiet && !isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, content: pickLine(terms === 'trade'
    ? [`Sending the beat now. Tape drops soon — need your verse on "${song.title}" 🙏🏾`, `Beat's yours. Just bless "${song.title}" for me 🔥`]
    : [`Sending "${song.title}" now 🔥 take your time with it`, `Here it is — "${song.title}". Can't wait to hear you on it`], req.id) });
  if (!quiet) pushDM(state, npc.id, { fromPlayer: false, system: true, content: `🤝 ${terms === 'trade' ? 'Trade' : 'Deal'}: your verse on "${song.title}"${terms === 'trade' ? ', for the beat' : ', no fee'}. In Studio → Features — due in ${VERSE_DEADLINE_DAYS} days.` });
  pushNotification(state, { kind: 'feature', title: `"${song.title}" is in your studio`, body: `Add your verse in Studio → Features. Due in ${VERSE_DEADLINE_DAYS} days.`, artSeed: `npc|${npc.id}`, action: { type: 'features', id: req.id } });
  return req;
}

/** Days and quality for the three ways to write a guest verse. */
export const VERSE_EFFORT = {
  quick: { label: 'Quick sixteen', days: 1, quality: -8, energy: 0.7 },
  standard: { label: 'Proper verse', days: 0, quality: 0, energy: 1 },
  polished: { label: 'Take your time', days: 3, quality: 7, energy: 1.25 },
} as const;

/** Bring a new case. `them` is an NPC; `side` is the player's side. */
function openCase(state: GameState, o: { kind: CaseKind; side: 'plaintiff' | 'defendant'; npcId: string; npcName: string; claim: number; evidence: number; facts: string[]; refId?: string; lawyer?: Lawyer }): LegalCase {
  const p = state.player!;
  const npc = state.npcs.find((n) => n.id === o.npcId);
  const serial = dateToSerial(state.gameDate);
  const seed = hashString(`${o.npcId}|${serial}|${o.kind}`) >>> 0;
  const me = { id: 'player' as const, name: p.artistName };
  const them = { id: o.npcId, name: o.npcName };
  const c: LegalCase = {
    id: uuidv4(), kind: o.kind, side: o.side,
    plaintiff: o.side === 'plaintiff' ? me : them, defendant: o.side === 'plaintiff' ? them : me,
    claim: Math.round(o.claim), facts: o.facts, evidence: Math.round(Math.max(5, Math.min(95, o.evidence))),
    filedSerial: serial, status: 'served', court: courtFor(p.city, o.claim), hearings: [],
    ourLawyer: o.lawyer, theirLawyer: opposingLawyer(npc?.fame ?? 20, seed), offers: [], log: [], costs: 0, refId: o.refId,
    answerBy: o.side === 'defendant' ? serial + 10 : undefined,
    nextMoveSerial: o.side === 'plaintiff' ? serial + 3 + (seed % 5) : undefined,
  };
  c.log.push({ serial, text: o.side === 'plaintiff' ? `You filed ${CASE_LABEL[o.kind].title.toLowerCase()} against ${o.npcName} for $${c.claim.toLocaleString()}.` : `${o.npcName} sued you: ${CASE_LABEL[o.kind].title.toLowerCase()}, $${c.claim.toLocaleString()}.` });
  (state.cases ?? (state.cases = [])).unshift(c);
  if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - (o.side === 'plaintiff' ? 25 : 15));
  const big = newsworthy(blendedFame(p), npc?.fame ?? 0, c.claim);
  if (big) {
    c.public = true;
    state.headlines.unshift({ id: uuidv4(), text: o.side === 'plaintiff' ? `${p.artistName} sues ${o.npcName}` : `${o.npcName} takes ${p.artistName} to court`, fullStory: `${CASE_LABEL[o.kind].blurb} The claim: $${c.claim.toLocaleString()}.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id, o.npcId], priority: 6, category: 'scandal' });
  }
  remember(state, 'beef', o.side === 'plaintiff' ? `You sued ${o.npcName} (${CASE_LABEL[o.kind].title.toLowerCase()}).` : `${o.npcName} sued you (${CASE_LABEL[o.kind].title.toLowerCase()}).`, { npcIds: [o.npcId], weight: 4, tone: 'bad' });
  return c;
}

/** Someone takes the player to court. */
function npcSues(state: GameState, npc: NPC, kind: CaseKind, claim: number, evidence: number, facts: string[], refId?: string): LegalCase {
  const c = openCase(state, { kind, side: 'defendant', npcId: npc.id, npcName: npc.name, claim, evidence, facts, refId });
  state.mailbox.unshift({ id: uuidv4(), from: 'court_registry', fromName: c.court, subject: `⚖️ You've been served: ${npc.name} v. ${state.player!.artistName}`, body: `${npc.name} has filed a claim against you: ${CASE_LABEL[kind].title.toLowerCase()}, $${claim.toLocaleString()}.\n\n${facts.map((f) => `• ${f}`).join('\n')}\n\nYou have 10 days to answer: pay, offer a settlement, or fight it. Ignoring it means the court decides without you. Open the Courthouse.`, timestamp: new Date().toISOString(), read: false, type: 'legal' });
  pushNotification(state, { kind: 'business', title: `⚖️ ${npc.name} is suing you`, body: `$${claim.toLocaleString()} — ${CASE_LABEL[kind].title}. Answer within 10 days.`, artSeed: `case|${c.id}`, action: { type: 'court', id: c.id } });
  if (!isRealId(npc.id) && !npc.id.startsWith('bank:') && !npc.id.startsWith('rights:')) scheduleDM(state, npc.id, pickLine(['My lawyers will be in touch.', 'See you in court.', 'You should\'ve just paid me back.'], c.id), nowMinuteOf(state) + 30);
  return c;
}

/** The team lawyer, if there is one. */
function teamLawyer(state: GameState): Lawyer | undefined {
  const c = (state.crew ?? []).find((x) => x.role === 'lawyer');
  if (!c) return undefined;
  const shark = specialSkillOf(c.npcId, c.role, c.skill)?.id === 'shark';
  return { name: c.npcName, skill: Math.min(100, c.skill + (shark ? 10 : 0)), source: 'team', perHearing: 0, crewId: c.id };
}

function scheduleHearing(state: GameState, c: LegalCase, kind: 'mention' | 'trial', days: number): void {
  const at = nextCourtDate(nowMinuteOf(state), days, c.hearings.length + c.claim);
  c.hearings.push({ id: uuidv4(), atMinute: at, kind });
  c.status = 'hearing';
  const when = new Date(Math.floor(at / 1440) * 86400000).toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'UTC' });
  c.log.push({ serial: dateToSerial(state.gameDate), text: `${kind === 'trial' ? 'Trial' : 'First hearing'} set for ${when}, ${Math.floor((at % 1440) / 60)}:${String(at % 60).padStart(2, '0')} at the ${c.court}.` });
  pushNotification(state, { kind: 'business', title: `⚖️ Court date: ${when}`, body: `${c.plaintiff.name} v. ${c.defendant.name} — ${kind === 'trial' ? 'the trial' : 'first hearing'} at the ${c.court}.`, artSeed: `case|${c.id}|${at}`, action: { type: 'court', id: c.id } });
}

/** Money changes hands at the end of a case. */
function closeCase(state: GameState, c: LegalCase, status: LegalCase['status'], text: string, playerPays: number, playerGets: number): void {
  const p = state.player!;
  const serial = dateToSerial(state.gameDate);
  c.status = status;
  if (playerPays) { p.career.money -= playerPays; ledgerAdd('legal', -playerPays); }
  if (playerGets) { p.career.money += playerGets; p.career.totalEarnings += playerGets; ledgerAdd('legal', playerGets); }
  c.outcome = { text, damages: playerGets - playerPays, costs: c.costs, serial };
  c.log.push({ serial, text });
  for (const o of c.offers) if (o.status === 'open') o.status = 'lapsed';
  const them = c.side === 'plaintiff' ? c.defendant : c.plaintiff;
  const won = status === 'won' || (status === 'settled' && playerGets > 0) || (status === 'dismissed' && c.side === 'defendant');
  if (c.public || newsworthy(blendedFame(p), state.npcs.find((n) => n.id === them.id)?.fame ?? 0, c.claim)) {
    const head = status === 'settled' ? `${c.plaintiff.name} and ${c.defendant.name} settle out of court`
      : status === 'won' || status === 'lost' ? `Court rules for ${(status === 'won') === (c.side === 'plaintiff') ? c.plaintiff.name : c.defendant.name} in ${c.plaintiff.name} v. ${c.defendant.name}` : `${c.plaintiff.name} v. ${c.defendant.name} thrown out`;
    state.headlines.unshift({ id: uuidv4(), text: head, fullStory: text, date: formatGameDate(state.gameDate), relatedEntities: [p.id, them.id], priority: 6, category: 'scandal' });
    // The timeline has opinions.
    const fan = pickLine(['@court_watch_gh', '@naija_tea', '@afrobuzz_daily', '@thegossipmill'], c.id);
    state.socialPosts.unshift({ id: uuidv4(), platform: 'chirp', authorId: `fan:${fan}`, authorName: fan, content: `${head}. ${won ? `${p.artistName} came out on top` : `L for ${p.artistName}`} 👀⚖️`, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 55, daySerial: serial, postedMinute: nowMinuteOf(state) } as SocialPost);
    livenPost(state, state.socialPosts[0]);
  }
  if (status === 'won' || status === 'lost') p.career.reputation = Math.max(0, Math.min(100, p.career.reputation + (status === 'won' ? 1 : -3)));
  remember(state, 'beef', text, { npcIds: [them.id], weight: 4, tone: won ? 'good' : 'bad' });
  pushNotification(state, { kind: 'business', title: `⚖️ ${status === 'settled' ? 'Settled' : status === 'won' ? 'You won' : status === 'lost' ? 'You lost' : 'Case closed'}: ${c.plaintiff.name} v. ${c.defendant.name}`, body: text, artSeed: `case|${c.id}|end`, action: { type: 'court', id: c.id } });
  // Deals the case was about are closed too.
  const fr = state.featureRequests.find((r) => r.caseId === c.id);
  if (fr && fr.status === 'paid_waiting') fr.status = 'declined';
  const ir = state.inboundRequests.find((r) => r.caseId === c.id);
  if (ir && ir.status === 'agreed') ir.status = 'withdrawn';
  // A debt judgment or settlement closes the loan.
  const loan = (state.loans ?? []).find((l) => l.caseId === c.id);
  if (loan) { loan.status = 'paid'; loan.balance = 0; }
}

/** Run a hearing. `mode`: the player there with their lawyer, testifying, or not there at all. */
function runHearing(state: GameState, c: LegalCase, h: LegalCase['hearings'][number], mode: 'lawyer' | 'testify' | 'absent'): string {
  const p = state.player!;
  const serial = dateToSerial(state.gameDate);
  h.done = true;
  const fee = c.ourLawyer?.perHearing ?? 0;
  if (fee && mode !== 'absent') { p.career.money -= fee; c.costs += fee; ledgerAdd('legal', -fee); }
  const npc = state.npcs.find((n) => n.id === (c.side === 'plaintiff' ? c.defendant.id : c.plaintiff.id));
  const persona = npc ? personaOf(npc) : null;
  const nobody = mode === 'absent' && !c.ourLawyer;
  if (h.kind === 'mention') {
    if (nobody) {
      // Not turning up to your own case, or to answer one, has a price.
      if (c.side === 'plaintiff') { closeCase(state, c, 'dismissed', `You didn't turn up to your own case against ${c.defendant.name}. The judge struck it out.`, 0, 0); return h.note = 'Struck out — you weren\'t there.'; }
      const j = judgment(c.claim, Math.max(c.evidence, 70), Math.random());
      const costs = Math.round(c.claim * 0.08);
      closeCase(state, c, 'lost', `Nobody answered for you, so the court ruled for ${c.plaintiff.name} by default: $${(j.damages + costs).toLocaleString()} including costs.`, j.damages + costs, 0);
      return h.note = 'Default judgment against you.';
    }
    scheduleHearing(state, c, 'trial', 18 + (c.claim > 50_000 ? 10 : 0));
    h.note = `The judge heard both sides and set the matter down for trial. ${mode === 'absent' ? `${c.ourLawyer!.name} handled it.` : ''}`;
    // The judge pushes for settlement; the other side often listens.
    if (persona && Math.random() < 0.55) {
      const amt = npcSettlement(c, persona, Math.random());
      c.offers.push({ id: uuidv4(), from: 'them', amount: amt, serial, status: 'open' });
      c.log.push({ serial, text: c.side === 'plaintiff' ? `${c.defendant.name} offered $${amt.toLocaleString()} to settle.` : `${c.plaintiff.name} would settle for $${amt.toLocaleString()}.` });
    }
    c.log.push({ serial, text: h.note });
    return h.note;
  }
  // The trial.
  const testimony = mode === 'testify' ? testimonyEffect(p.stats.charisma, p.stats.discipline, Math.random()) : null;
  const ours = c.ourLawyer?.skill ?? (mode === 'testify' ? 15 : 0);
  const odds = plaintiffOdds({
    evidence: c.evidence,
    plaintiffLawyer: c.side === 'plaintiff' ? ours : c.theirLawyer.skill,
    defendantLawyer: c.side === 'plaintiff' ? c.theirLawyer.skill : ours,
    testimony: testimony?.effect ?? 0,
    playerAbsent: nobody,
  }, c.side);
  const plaintiffWins = Math.random() < odds;
  const playerWins = plaintiffWins === (c.side === 'plaintiff');
  const j = judgment(c.claim, c.evidence, Math.random());
  const theirCosts = Math.round(c.claim * 0.12 + c.theirLawyer.skill * 40);
  const intro = testimony ? `${testimony.text} ` : nobody ? 'You weren\'t there and had nobody to speak for you. ' : '';
  if (playerWins) {
    const gets = c.side === 'plaintiff' ? j.damages + Math.round(c.costs * j.costsShare) : Math.round(c.costs * j.costsShare);
    closeCase(state, c, 'won', `${intro}The judge ruled in your favour.${c.side === 'plaintiff' ? ` ${c.defendant.name} must pay $${j.damages.toLocaleString()} plus part of your costs.` : ` The claim was dismissed and ${c.plaintiff.name} pays part of your costs.`}`, 0, gets);
  } else {
    const pays = c.side === 'defendant' ? j.damages + Math.round(theirCosts * j.costsShare) : Math.round(theirCosts * j.costsShare);
    closeCase(state, c, 'lost', `${intro}The judge ruled against you.${c.side === 'defendant' ? ` You owe ${c.plaintiff.name} $${j.damages.toLocaleString()} plus part of their costs.` : ` Your claim failed and you pay part of ${c.defendant.name}'s costs.`}`, pays, 0);
  }
  return h.note = c.outcome!.text;
}

/** Daily: the other side's moves, deadlines, offers lapsing. */
function courtTick(state: GameState, serial: number): void {
  const p = state.player;
  if (!p) return;
  for (const c of state.cases ?? []) {
    if (!['served', 'hearing'].includes(c.status)) continue;
    for (const o of c.offers) if (o.status === 'open' && serial - o.serial > 10) o.status = 'lapsed';
    const npcId = c.side === 'plaintiff' ? c.defendant.id : c.plaintiff.id;
    const npc = state.npcs.find((n) => n.id === npcId);
    const persona = npc ? personaOf(npc) : null;
    // You sued: they answer.
    if (c.side === 'plaintiff' && c.status === 'served' && c.nextMoveSerial !== undefined && serial >= c.nextMoveSerial && persona) {
      c.nextMoveSerial = undefined;
      const ans = npcAnswer(persona, c, (npc!.fame + 10) * 3000, Math.random());
      if (ans === 'pay') {
        closeCase(state, c, 'settled', `${c.defendant.name} paid the full $${c.claim.toLocaleString()} rather than go to court.`, 0, c.claim);
      } else if (ans === 'settle') {
        const amt = npcSettlement(c, persona, Math.random());
        c.offers.push({ id: uuidv4(), from: 'them', amount: amt, serial, status: 'open' });
        c.log.push({ serial, text: `${c.defendant.name}'s lawyers offered $${amt.toLocaleString()} to settle.` });
        pushNotification(state, { kind: 'business', title: `⚖️ ${c.defendant.name} wants to settle`, body: `They offer $${amt.toLocaleString()}. Take it, counter, or see them in court.`, artSeed: `case|${c.id}|o`, action: { type: 'court', id: c.id } });
        scheduleHearing(state, c, 'mention', 14);
      } else {
        c.log.push({ serial, text: ans === 'ignore' ? `${c.defendant.name} didn't answer. The court will hear it anyway.` : `${c.defendant.name} is fighting it, with ${c.theirLawyer.name}.` });
        scheduleHearing(state, c, 'mention', 14);
      }
    }
    // You were sued and never answered: it goes before the judge anyway.
    if (c.side === 'defendant' && c.status === 'served' && c.answerBy !== undefined && serial > c.answerBy) {
      c.answerBy = undefined;
      c.log.push({ serial, text: 'You didn\'t answer the claim in time. It\'s going before the judge.' });
      scheduleHearing(state, c, 'mention', 7);
    }
  }
}

/** Daily: verses owed both ways, money owed both ways. */
function featureDealsTick(state: GameState, serial: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  // ── Verses you owe (their record) ──
  for (const r of state.inboundRequests) {
    const npc = state.npcs.find((n) => n.id === r.npcId);
    const persona = npc ? personaOf(npc) : null;
    // An ask nobody answers doesn't sit there forever. Two weeks on read and
    // they find somebody else for the record.
    if (r.status === 'open') {
      const sent = r.sentDate ? parseGameDate(r.sentDate) : null;
      if (sent && serial - dateToSerial(sent) > 14) {
        r.status = 'withdrawn';
        r.lapsed = true;
        if (npc) {
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - 3);
          npc.memoryLog = [...(npc.memoryLog ?? []).slice(-9), `[Feature] ${p.artistName} never answered about "${r.npcSongTitle}".`];
          if (!isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, read: false, content: pickLine(['Guess that\'s a no. All good 🤝', 'Found someone else for it. Next time.', 'No reply? Say less.'], r.id) });
        }
        log.push(`⌛ ${r.npcName} gave the verse on "${r.npcSongTitle}" to someone else.`);
      }
      continue;
    }
    if (r.status === 'agreed') {
      if (r.dueSerial === undefined) {
        // A deal from before terms existed: everything was paid up front.
        r.payTerms = r.payTerms ?? ((r.agreedFee ?? 0) > 0 ? 'upfront' : 'free');
        r.paidSoFar = r.paidSoFar ?? (r.agreedFee ?? 0);
        const agreed = r.agreedDate ? parseGameDate(r.agreedDate) : null;
        r.dueSerial = (agreed ? dateToSerial(agreed) : serial) + VERSE_DEADLINE_DAYS;
      }
      const writing = (state.workItems ?? []).some((w) => w.kind === 'verse' && (w.payload as VerseWork).requestId === r.id);
      if (writing || r.caseId) continue;
      const left = r.dueSerial - serial;
      const paid = r.paidSoFar ?? 0;
      if (left <= 4 && !r.chased && npc && !isRealId(npc.id) && persona) {
        r.chased = true;
        pushDM(state, npc.id, { fromPlayer: false, content: r.payTerms === 'trade'
          ? pickLine([`You've had the beat a while 👀 how far with my verse on "${r.npcSongTitle}"?`, `Tape's nearly done. Just need your verse on "${r.npcSongTitle}".`], r.id)
          : chaseLine(persona, paid, Math.max(0, left), hashString(r.id) >>> 0) });
        // Say what they're on about: the deal, who agreed it, and where to do it.
        const viaManager = state.contracts.some((c) => c.type === 'management' && c.active);
        pushDM(state, npc.id, { fromPlayer: false, system: true, content: `📋 ${viaManager ? 'Your manager agreed' : 'You agreed'} a verse on their song "${r.npcSongTitle}"${r.agreedDate ? ` on ${r.agreedDate}` : ''}${paid > 0 ? ` — they've paid $${paid.toLocaleString()}` : r.payTerms === 'trade' ? ' — traded for a beat' : ''}. ${left > 0 ? `Due in ${left} day${left === 1 ? '' : 's'}` : 'Due today'}. Write it in Studio → Features.` });
        log.push(`⏳ ${r.npcName} is asking about the verse for "${r.npcSongTitle}".`);
      }
      if (left < -GRACE_DAYS && !r.refundDemanded) {
        r.refundDemanded = serial;
        if (npc) {
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - (paid > 0 ? 12 : 6));
          npc.memoryLog = [...(npc.memoryLog ?? []).slice(-9), `[Feature] ${p.artistName} never sent the verse${paid > 0 ? ' I paid for' : ''}.`];
        }
        if (paid > 0) {
          const trade = r.payTerms === 'trade';
          if (npc && !isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, content: trade ? `Forget the verse. You kept my beat — pay me the $${paid.toLocaleString()} for it.` : `Forget the verse. Send back my $${paid.toLocaleString()}.` });
          pushNotification(state, { kind: 'feature', title: trade ? `${r.npcName} wants paying for the beat` : `${r.npcName} wants their money back`, body: trade ? `You took the beat and never sent the verse. $${paid.toLocaleString()} — settle it from Studio → Features.` : `$${paid.toLocaleString()} for a verse you never sent. Refund it from Studio → Features.`, artSeed: `npc|${r.npcId}`, action: { type: 'features', id: r.id } });
        } else {
          r.status = 'withdrawn';
          r.lapsed = true;
          log.push(`🚪 ${r.npcName} gave up waiting on the verse for "${r.npcSongTitle}".`);
          remember(state, 'people', `You never sent ${r.npcName} the verse for "${r.npcSongTitle}".`, { npcIds: [r.npcId], weight: 2, tone: 'bad' });
        }
      }
      // Asked for a refund, never got it: some people let it go, some sue.
      if (r.refundDemanded && paid > 0 && serial - r.refundDemanded >= 10 && r.status === 'agreed') {
        r.status = 'withdrawn';
        r.lapsed = true;
        if (npc && persona && suesForUndelivered(persona, paid, Math.random())) {
          const c = npcSues(state, npc, 'refund', Math.round(paid * 1.5), 82, [r.payTerms === 'trade' ? `${npc.name} gave you a beat worth $${paid.toLocaleString()} in exchange for a verse on "${r.npcSongTitle}".` : `${npc.name} paid you $${paid.toLocaleString()} for a verse on "${r.npcSongTitle}" (${TERMS_LABEL[r.payTerms ?? 'upfront'].toLowerCase()}).`, `The verse was due ${formatGameDate(serialToDate(r.dueSerial))} and never came.`, `They asked for the money back; you didn't return it.`], r.id);
          r.caseId = c.id;
          log.push(`⚖️ ${r.npcName} is suing you over the verse.`);
        } else {
          remember(state, 'people', `You kept ${r.npcName}'s $${paid.toLocaleString()} and never sent the verse.`, { npcIds: [r.npcId], weight: 3, tone: 'bad' });
          if (npc && persona && persona.messy > 0.55 && !isRealId(npc.id)) npcPost(state, npc, pickLine(['Paid for a verse months ago. Still waiting. Some people are only business when it suits them.', 'Lesson: never pay up front. Never.'], r.id));
        }
      }
    }
    // Delivered, balance owed to you.
    if (r.status === 'delivered' && (r.balanceDue ?? 0) > 0 && r.balanceDueSerial !== undefined && !r.caseId) {
      if (r.balancePlan !== 'never' && serial >= r.balanceDueSerial) {
        const amt = r.balanceDue!;
        r.balanceDue = 0;
        r.paidSoFar = (r.paidSoFar ?? 0) + amt;
        p.career.money += amt;
        p.career.totalEarnings += amt;
        receipt(state, r.npcId, amt, `💰 ${r.npcName} paid the balance: $${amt.toLocaleString()} for your verse on "${r.npcSongTitle}".${r.balancePlan === 'late' ? ' Late, but paid.' : ''}`, { memory: `${r.npcName} paid you $${amt.toLocaleString()} for the verse on "${r.npcSongTitle}".` });
      }
    }
  }

  // ── Verses you paid for (your record) ──
  for (const r of state.featureRequests) {
    if (r.status !== 'paid_waiting' || r.verseDueSerial === undefined || r.caseId) continue;
    const npc = state.npcs.find((n) => n.id === r.npcId);
    const d = r.delivery ?? { outcome: 'on_time' as const, lateBy: 0 };
    if (serial < r.verseDueSerial) continue;
    if (d.outcome === 'late' && !d.excused) {
      d.excused = true;
      r.delivery = d;
      r.verseDueSerial += d.lateBy;
      if (npc && !isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, content: lateExcuse(hashString(r.id) >>> 0) });
      continue;
    }
    if (d.outcome === 'ghost') continue; // Nothing comes. Chase, ask for a refund, or sue.
    r.status = 'verse_ready';
    if (npc && !isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, content: pickLine(['Verse done 🔥 sent it over', 'Your verse is in. Tell me what you think', 'Done. Go crazy with it 🎙️'], r.id) });
    else if (npc) pushDM(state, npc.id, { fromPlayer: false, system: true, content: `🎙️ ${r.npcName}'s verse for "${r.songTitle}" arrived.` });
    pushNotification(state, { kind: 'feature', title: `${r.npcName}'s verse is in`, body: `Cut it into "${r.songTitle}" from Studio → Features.`, artSeed: `npc|${r.npcId}`, action: { type: 'features', id: r.id } });
    remember(state, 'music', `${r.npcName} delivered their verse for "${r.songTitle}"${d.outcome === 'late' ? ', late' : ''}.`, { npcIds: [r.npcId], weight: 2, tone: 'good' });
  }
}

// ─── AWARD SEASONS ─────────────────────────────────────────────────────────

export interface AwardSeason {
  key: string;
  bodyId: string;
  year: number;
  cal: Calendar;
  phase: 'upcoming' | 'nominations' | 'done';
  categories: CategoryState[];
  campaign: { academy: number; rally: number; spent: number; lastRally?: number };
  /** Your entries are in. Seasons from before entries existed count as entered. */
  entered?: boolean;
  /** Who put them in: 'team' (manager, publicist, label) or 'you'. */
  enteredBy?: 'team' | 'you';
  /** You were reminded to enter. */
  entryReminded?: boolean;
  /** A body that has nothing to do with you runs quietly: no posts, no headlines. */
  quiet?: boolean;
  /** invited (nominee or famous), performer, or bought a ticket. */
  invite?: 'invited' | 'performer' | 'ticket';
  rsvp?: boolean;
  /** What happened on the night, for the page. */
  night?: string[];
  told?: { tonight?: boolean };
}

let bodiesCache: { country: string; list: AwardBody[] } | null = null;
function bodiesFor(state: GameState): AwardBody[] {
  const c = state.player?.country ?? 'Ghana';
  if (!bodiesCache || bodiesCache.country !== c) bodiesCache = { country: c, list: awardBodies(c) };
  return bodiesCache.list;
}

/**
 * Does this ceremony concern the player? Home, their region, the global ones,
 * anything they follow, and any country where their music is charting. The
 * rest of the world's awards still happen — quietly.
 */
function awardRelevant(state: GameState, body: AwardBody): boolean {
  const p = state.player;
  if (!p) return false;
  if (body.scope === 'global') return true;
  if (body.scope === 'country' && body.country === p.country) return true;
  if (body.scope === 'continental' && inRegion(body, p.country)) return true;
  if ((state.awardFollows ?? []).includes(body.id)) return true;
  if (body.scope === 'country' && body.country && marketPresence(state, body.country) >= 0.2) return true;
  return false;
}

/** Whoever handles your paperwork puts your entries in. */
function entriesHandler(state: GameState): string | null {
  const mgr = managerOf(state);
  if (mgr) return mgr.name;
  const pub = (state.crew ?? []).find((c) => c.role === 'publicist' || c.role === 'personal_assistant');
  if (pub) return pub.npcName;
  if ((state.contracts ?? []).some((c) => c.type === 'label' && c.active)) return 'Your label';
  return null;
}

/** Everything the academy looks at, from the world as it is today. */
export function awardWorld(state: GameState, npcs: NPC[], npcSongs: Song[]): AwardWorld {
  const p = state.player!;
  const serial = dateToSerial(state.gameDate);
  const relOf = (s: Song) => state.platformStats?.[s.id]?.release ?? serialOfGameDate(s.releaseDate, serial);
  const entrants = new Map<string, Entrant>();
  const debut = new Map<string, number>();
  for (const s of npcSongs) if (s.ownerId) debut.set(s.ownerId, Math.min(debut.get(s.ownerId) ?? Infinity, relOf(s)));
  for (const n of npcs) if (n.role === 'artist') entrants.set(n.id, { id: n.id, name: n.name, country: n.country, genre: n.genre, gender: n.gender, fame: n.fame, isPlayer: false, real: isRealId(n.id), debutSerial: debut.get(n.id) });
  const mine = (state.songs ?? []).filter((s) => isSongReleased(s));
  entrants.set(p.id, { id: p.id, name: p.artistName, country: p.country, genre: p.genre, gender: p.gender, fame: blendedFame(p), isPlayer: true, real: false, debutSerial: mine.length ? Math.min(...mine.map(relOf)) : undefined });
  const vids = new Map((state.videos ?? []).map((v) => [v.songId, v.quality]));
  const sceneAlbums: AwardWorld['albums'] = [];
  const toEntry = (s: Song, owner: string): SongEntry => ({ id: s.id, title: s.title, ownerId: owner, genre: s.genre, quality: s.quality, streams: s.totalStreams, release: relOf(s), features: s.featuredArtists ?? [], hasVideo: !!s.hasVideo || vids.has(s.id), videoQuality: vids.get(s.id) });
  const songs: SongEntry[] = [...npcSongs.filter((s) => s.ownerId && entrants.has(s.ownerId)).map((s) => toEntry(s, s.ownerId!)), ...mine.map((s) => toEntry(s, p.id))];
  // Every country's scene, not just the few hundred artists on the global
  // charts: fictional local acts with a name are credited with the year's best
  // single (see `sceneSingle`). Real artists only appear with their real records.
  {
    const year = new Date(serial * 86400000).getUTCFullYear();
    const recent = new Set(songs.filter((x) => serial - x.release < 365).map((x) => x.ownerId));
    const byCountry = new Map<string, NPC[]>();
    for (const n of npcs) {
      if (n.role !== 'artist' || n.fame < 18 || isRealId(n.id) || recent.has(n.id)) continue;
      const list = byCountry.get(n.country) ?? [];
      list.push(n);
      byCountry.set(n.country, list);
    }
    for (const list of byCountry.values()) {
      const top = list.sort((a, b) => b.fame - a.fame).slice(0, 30);
      for (const n of top) {
        const single = sceneSingle(n, year, serial, top);
        songs.push(single);
        const e = entrants.get(n.id);
        // A newcomer's first record is this one; an established act has been around.
        if (e && e.debutSerial === undefined) e.debutSerial = n.fame < 35 ? single.release : serial - 1500 - (single.quality * 13) % 900;
        if (n.fame >= 45 && single.quality % 3 === 0) sceneAlbums.push({ id: `scene-lp:${n.id}:${year}`, title: `${single.title} (The Album)`, ownerId: n.id, release: single.release - 20, streams: single.streams * 4, quality: Math.min(95, single.quality + 2) });
      }
    }
  }
  const albums = [...(state.npcAlbums ?? []), ...(state.albums ?? [])].filter((a) => a.ownerId && entrants.has(a.ownerId === 'player' ? p.id : a.ownerId)).map((a) => {
    const owner = a.ownerId === 'player' || !a.ownerId ? p.id : a.ownerId;
    const qs = a.songs.map((id) => [...npcSongs, ...(state.songs ?? [])].find((x) => x.id === id)?.quality ?? 50);
    return { id: a.id, title: a.title, ownerId: owner, release: a.releaseSerial ?? serialOfGameDate(a.releaseDate, serial), streams: a.totalStreams, quality: qs.length ? qs.reduce((x, y) => x + y, 0) / qs.length : 50 };
  });
  // The academy remembers scandals and lost cases; a campaign helps.
  const lost = (state.cases ?? []).filter((c) => c.status === 'lost' && serial - (c.outcome?.serial ?? 0) < 365).length;
  const academy = Math.max(0.6, Math.min(1.25, 0.85 + p.career.reputation / 250 - lost * 0.06));
  return { entrants, songs, albums: [...albums, ...sceneAlbums], playerId: p.id, playerAcademy: academy };
}

function awardPost(state: GameState, body: AwardBody, content: string, trending = 60): void {
  state.socialPosts.unshift({ id: uuidv4(), platform: 'chirp', authorId: `org:${body.id}`, authorName: body.name, content, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: trending, daySerial: dateToSerial(state.gameDate), postedMinute: nowMinuteOf(state) } as SocialPost);
  livenPost(state, state.socialPosts[0], { minComments: 6 });
}

/** Run the night: every envelope opened, the world told. */
function runCeremony(state: GameState, season: AwardSeason, attended: boolean): void {
  const p = state.player!;
  const body = bodiesFor(state).find((b) => b.id === season.bodyId);
  if (!body || season.phase === 'done') return;
  const followed = (state.awardFollows ?? []).includes(body.id);
  const academy = Math.max(0.6, Math.min(1.5, 0.85 + p.career.reputation / 250 + season.campaign.academy));
  const wins: string[] = [];
  const night: string[] = [];
  const nominatedHere = season.categories.some((c) => c.nominees.some((n) => n.isPlayer));
  const quiet = !!season.quiet && !nominatedHere && !followed;
  for (const c of season.categories) {
    const w = decide(c, academy, Math.random);
    c.winnerId = w.id;
    night.push(`${c.name}: ${w.name}${w.work ? ` — "${w.work}"` : ''}`);
    // A night on the other side of the world is in the record on its own page;
    // the trophy cabinet keeps the ones that touched your career.
    if (quiet) {
      const n = state.npcs.find((x) => x.id === w.id);
      if (n) n.fame = Math.min(100, n.fame + (c.major ? 1 : 0.4) * body.prestige / 70);
      continue;
    }
    state.awards.push({ id: uuidv4(), name: `${body.name} — ${c.name}`, tier: body.scope === 'country' ? 'country' : body.scope === 'continental' ? 'regional' : 'global', country: body.country, category: c.name, year: season.year, winner: w.id, nominees: c.nominees.map((n) => n.id) } as GameState['awards'][number]);
    if (w.isPlayer) {
      wins.push(c.name);
      const r = winRewards(body, c.major);
      p.career.localFame = Math.min(100, p.career.localFame + r.fame);
      p.career.nationalFame = Math.min(100, p.career.nationalFame + r.fame * (body.scope === 'country' ? 0.8 : 0.6));
      if (body.scope !== 'country') p.career.internationalFame = Math.min(100, p.career.internationalFame + r.fame * (body.scope === 'global' ? 0.8 : 0.5));
      p.career.fanbase += Math.round(p.career.fanbase * r.fansPct / 100);
      p.career.reputation = Math.min(100, p.career.reputation + r.reputation);
      addMomentum(state, r.momentum);
    } else {
      const n = state.npcs.find((x) => x.id === w.id);
      if (n) n.fame = Math.min(100, n.fame + (c.major ? 1.5 : 0.6) * body.prestige / 60);
    }
  }
  season.phase = 'done';
  season.night = night;
  if (quiet) {
    // Keep the podium, drop the long lists: the world's awards are many.
    for (const c of season.categories) c.nominees = c.nominees.filter((n, i) => n.id === c.winnerId || i < 3);
    return;
  }
  const major = season.categories.filter((c) => c.major);
  const nominatedMe = season.categories.filter((c) => c.nominees.some((n) => n.isPlayer));
  // The headlines and the timeline.
  if (wins.length) {
    state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} wins ${wins.length > 1 ? `${wins.length} awards` : wins[0]} at the ${body.name}`, fullStory: `Wins: ${wins.join(', ')}.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 8, category: 'award' });
    remember(state, 'career', `You won ${wins.join(', ')} at the ${body.name} ${season.year}.`, { weight: 5, tone: 'good' });
    pushNotification(state, { kind: 'milestone', title: `🏆 You won ${wins.length > 1 ? `${wins.length} awards` : wins[0]}!`, body: `${body.name} ${season.year}`, artSeed: `award|${season.key}|win`, action: { type: 'awards', id: season.key } });
  } else if (nominatedMe.length) {
    remember(state, 'career', `You were nominated ${nominatedMe.length} time${nominatedMe.length > 1 ? 's' : ''} at the ${body.name} ${season.year} and went home empty-handed.`, { weight: 3 });
  }
  for (const c of major) {
    const w = c.nominees.find((n) => n.id === c.winnerId)!;
    state.headlines.unshift({ id: uuidv4(), text: `${w.name} wins ${c.name} at the ${body.name}`, fullStory: `${c.name}: ${c.nominees.map((n) => n.name).join(', ')}.`, date: formatGameDate(state.gameDate), relatedEntities: [w.id], priority: 6, category: 'award' });
    awardPost(state, body, `🏆 ${c.name.toUpperCase()}: ${w.name}${w.work ? ` — "${w.work}"` : ''}! #${body.short.replace(/[^A-Za-z0-9]/g, '')}${season.year}`, 70);
    if (followed || w.isPlayer) pushNotification(state, { kind: 'business', title: `${body.emoji} ${c.name}: ${w.name}`, body: `${body.name} ${season.year}`, artSeed: `award|${season.key}|${c.id}`, action: { type: 'awards', id: season.key } });
  }
  if (followed && !wins.length) pushNotification(state, { kind: 'business', title: `${body.emoji} ${body.name}: full winners list`, body: `${season.categories.length} categories. Tap for the night.`, artSeed: `award|${season.key}|all`, action: { type: 'awards', id: season.key } });
  // Fictional winners thank people; real ones are reported, not quoted.
  for (const c of major.slice(0, 2)) {
    const w = c.nominees.find((n) => n.id === c.winnerId)!;
    if (w.isPlayer || w.real) continue;
    const n = state.npcs.find((x) => x.id === w.id);
    if (n) npcPost(state, n as NPC, pickLine(['Thank you God, thank you fans. This one is for the city 🏆', 'We really did it. Love to everyone who voted 🙏🏾🏆', 'Still can\'t believe it. Back to work tomorrow 🏆'], season.key + c.id));
  }
  if (attended) season.night.unshift('You were in the room.');
}

/** Daily: the calendars, entries, nominations and the voting — for every body in the world. */
function awardsTick(state: GameState, serial: number, npcs: NPC[], npcSongs: Song[]): void {
  const p = state.player;
  if (!p) return;
  const seasons = state.awardSeasons ?? (state.awardSeasons = {});
  const bodies = bodiesFor(state);
  if (!state.awardFollows) state.awardFollows = [bodies.find((b) => b.country === p.country)?.id ?? 'ghana'];
  const fame = blendedFame(p);
  // Nights that passed while the days were being skipped still happened.
  for (const season of Object.values(seasons)) if (season.phase === 'nominations' && serial > season.cal.ceremony) runCeremony(state, season, false);
  // The academy's view of the world is built once, and only on a day somebody needs it.
  let world: AwardWorld | null = null;
  const worldOf = () => world ?? (world = awardWorld(state, npcs, npcSongs));
  const handler = entriesHandler(state);
  // One lookup table for the whole day's voting, not a roster scan per nominee.
  const idx = npcIndex(npcs);
  const fansOf = (id: string) => (id === p.id ? p.career.fanbase : (idx.get(id)?.fame ?? 10) * 400);
  const eligibleWork = (cal: Calendar) => (state.songs ?? []).some((x) => isSongReleased(x) && (() => { const r = releaseSerialOf(state, x, serial); return r >= cal.windowStart - 365 && r <= cal.windowEnd; })());
  for (const body of bodies) {
    const cal = nextCalendar(body, serial);
    const key = `${body.id}:${cal.year}`;
    const relevant = awardRelevant(state, body);
    let s = seasons[key];
    if (!s) {
      // Far-away ceremonies only start existing a couple of months out.
      if (!relevant && cal.nominations - serial > 60) continue;
      s = seasons[key] = { key, bodyId: body.id, year: cal.year, cal, phase: 'upcoming', categories: [], campaign: { academy: 0, rally: 0, spent: 0 }, quiet: !relevant };
    }
    if (relevant && s.quiet) s.quiet = false;
    const followed = (state.awardFollows ?? []).includes(body.id);
    const close = s.cal.entriesClose;
    // ── Entries ─────────────────────────────────────────────────────────
    // Nobody is nominated for something they never entered. Your team puts
    // the entries in for you; on your own, you have to do it yourself.
    if (s.phase === 'upcoming' && close !== undefined && !s.entered && relevant && body.scope !== 'global' && eligibleWork(s.cal)) {
      if (handler && serial >= close - 14) {
        s.entered = true;
        s.enteredBy = 'team';
        if (body.scope === 'country' && body.country === p.country) pushTeamLines(state, [{ from: managerOf(state)?.id ?? 'team', name: handler, role: managerOf(state) ? 'manager' : 'team', text: `Submitted your entries for the ${body.name} ${s.cal.year}. Nominations come out ${new Date(s.cal.nominations * 86400000).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', timeZone: 'UTC' })}.` }], serial);
      } else if (!handler && !s.entryReminded && serial >= close - 10 && serial <= close) {
        s.entryReminded = true;
        pushNotification(state, { kind: 'business', title: `${body.emoji} Enter the ${body.name}`, body: `Entries close ${new Date(close * 86400000).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', timeZone: 'UTC' })}. Nobody on your team handles it — submit them yourself on the Awards page.`, artSeed: `award|${key}|entries`, action: { type: 'awards', id: key } });
      }
    }
    if (s.phase === 'upcoming' && serial >= s.cal.nominations) {
      const w = worldOf();
      // Global academies watch the charts themselves; everywhere else you have
      // to have entered. Old seasons (no deadline) count as entered.
      const entered = body.scope === 'global' || close === undefined || !!s.entered;
      const wv: AwardWorld = entered ? w : { ...w, songs: w.songs.filter((x) => x.ownerId !== w.playerId), albums: w.albums.filter((a) => a.ownerId !== w.playerId) };
      s.categories = nominate(body, s.cal, wv, Math.random);
      s.phase = 'nominations';
      if (!s.categories.length) {
        // A year too thin to fill a shortlist: the academy postpones rather
        // than hand out trophies to nobody.
        s.phase = 'done';
        s.night = ['Not enough eligible releases this year — the academy postponed the night.'];
        continue;
      }
      const mine = s.categories.filter((c) => c.nominees.some((n) => n.isPlayer));
      if (!entered && relevant && eligibleWork(s.cal)) {
        pushNotification(state, { kind: 'business', title: `${body.emoji} ${body.name} nominations are out`, body: 'You never entered, so you were not considered. Next year, put your entries in — or have somebody on your team do it.', artSeed: `award|${key}|missed`, action: { type: 'awards', id: key } });
      }
      if (mine.length) {
        s.quiet = false;
        s.invite = fame >= 45 && mine.some((c) => c.major) ? 'performer' : 'invited';
        s.rsvp = true;
        state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} earns ${mine.length} nomination${mine.length > 1 ? 's' : ''} at the ${body.name}`, fullStory: mine.map((c) => c.name).join(', '), date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 7, category: 'award' });
        // Your people tell you before the internet does.
        const teller = managerOf(state) ?? null;
        const crewTeller = !teller ? (state.crew ?? [])[0] : undefined;
        if (teller || crewTeller) {
          const from = teller ? { from: teller.id, name: teller.name, role: 'manager' } : { from: crewTeller!.npcId, name: crewTeller!.npcName, role: crewTeller!.role };
          const line = `${p.artistName.split(' ')[0]}!! I just got the call — we're nominated at the ${body.name}: ${mine.map((c) => c.name).join(', ')} 🏆 ${s.invite === 'performer' ? 'And they want you to perform.' : 'Clear the night.'}`;
          pushTeamLines(state, [{ ...from, text: line, key: `nom:${key}` }], serial);
          if (teller) pushDM(state, teller.id, { fromPlayer: false, content: `📞 ${line}` });
        }
        pushNotification(state, { kind: 'milestone', title: teller ? `📞 ${teller.name.split(' ')[0]}: "We're nominated!" — ${mine.length} at the ${body.name}` : `${body.emoji} A letter from the academy: you're nominated — ${mine.length} at the ${body.name}`, body: `${mine.map((c) => c.name).join(', ')}. The night is ${new Date(s.cal.ceremony * 86400000).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', timeZone: 'UTC' })} in ${body.city}.${s.invite === 'performer' ? ' They want you to perform.' : ''}`, artSeed: `award|${key}|noms`, action: { type: 'awards', id: key } });
        remember(state, 'career', `You were nominated for ${mine.map((c) => c.name).join(', ')} at the ${body.name} ${s.cal.year}.`, { weight: 4, tone: 'good' });
      } else if (fame >= 55 && (relevant || fame >= 75)) {
        s.invite = 'invited';
      }
      if (!s.quiet) {
        if (followed && !mine.length) pushNotification(state, { kind: 'business', title: `${body.emoji} ${body.name} nominations are out`, body: s.categories.filter((c) => c.major).map((c) => `${c.name}: ${c.nominees.slice(0, 3).map((n) => n.name).join(', ')}…`).join(' · ').slice(0, 220), artSeed: `award|${key}|noms`, action: { type: 'awards', id: key } });
        const top = s.categories.find((c) => c.major);
        if (top) awardPost(state, body, `📣 Nominations for the ${body.name} ${s.cal.year} are OUT. ${top.name}: ${top.nominees.map((n) => n.name).join(', ')}. ${s.categories.some((c) => c.fanVote) ? 'Voting is open now 🗳️' : ''}`, 65);
      }
    }
    if (s.phase === 'nominations' && serial <= s.cal.votingCloses) {
      for (const c of s.categories) if (c.fanVote) voteDay(c, fansOf, s.campaign.rally, Math.random);
    }
    if (s.phase === 'nominations' && serial === s.cal.ceremony && !s.told?.tonight && (followed || s.rsvp)) {
      s.told = { ...(s.told ?? {}), tonight: true };
      pushNotification(state, { kind: 'business', title: `${body.emoji} ${body.name} is tonight`, body: `${body.venue}, ${body.city} · 7:00 PM${s.rsvp ? ' — you\'re going.' : ''}`, artSeed: `award|${key}|tonight`, action: { type: 'awards', id: key } });
    }
  }
  // History: two years for the ceremonies that concern you, one for the rest.
  for (const k of Object.keys(seasons)) {
    const v = seasons[k];
    if (v.phase === 'done' && serial - v.cal.ceremony > (v.quiet ? 380 : 760)) delete seasons[k];
  }
}

/** Put your own entries in. */
export function enterAwardsFor(state: GameState, key: string): { ok: boolean; message: string } {
  const s = state.awardSeasons?.[key];
  if (!s) return { ok: false, message: 'That season is not open.' };
  const serial = dateToSerial(state.gameDate);
  if (s.entered) return { ok: false, message: 'Your entries are already in.' };
  if (s.phase !== 'upcoming' || (s.cal.entriesClose !== undefined && serial > s.cal.entriesClose)) return { ok: false, message: 'Entries are closed for this year.' };
  const fee = 50;
  if ((state.player?.career.money ?? 0) < fee) return { ok: false, message: `The entry fee is $${fee}.` };
  state.player!.career.money -= fee;
  s.entered = true;
  s.enteredBy = 'you';
  return { ok: true, message: `Entered. $${fee} admin fee. Nominations come out ${new Date(s.cal.nominations * 86400000).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', timeZone: 'UTC' })}.` };
}

// ─── CAREER MODES ──────────────────────────────────────────────────────────

/** Leave retirement (or business focus) without the ceremony of a comeback. */
function unretire(state: GameState, to: CareerMode, why: string): void {
  state.legacy.mode = to;
  state.legacy.retired = false;
  state.legacy.modeSince = dateToSerial(state.gameDate);
  remember(state, 'career', why, { weight: 3 });
}

function legacyScoreOf(state: GameState): number {
  const p = state.player!;
  return Math.round(p.career.totalStreams / 100000 + state.awards.filter((a) => a.winner === p.id).length * 250 + state.certifications.length * 100 + p.career.totalEarnings / 10000 + p.career.internationalFame * 20);
}

function legacyTitles(state: GameState): string[] {
  const p = state.player!;
  const wins = state.awards.filter((a) => a.winner === p.id).length;
  const t: string[] = [];
  if (p.career.internationalFame >= 60) t.push('Global icon');
  else if (p.career.nationalFame >= 60) t.push('National treasure');
  if (wins >= 10) t.push('Decorated'); else if (wins >= 3) t.push('Award winner');
  if (state.certifications.length >= 10) t.push('Hit machine');
  if (p.career.totalEarnings >= 5_000_000) t.push('Mogul');
  if ((state.ventures ?? []).filter((v) => !v.closed).length >= 2) t.push('Businessman');
  return t;
}

/** Daily: the comeback clock, post-career income, the nostalgia bump. */
function careerModeTick(state: GameState, serial: number, days: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  const L = state.legacy;
  const cb = L.comeback;
  if (cb && !cb.used && serial > cb.until) {
    cb.used = true;
    p.career.reputation = Math.max(0, p.career.reputation - 4);
    p.career.momentum = Math.max(0, p.career.momentum - 10);
    state.headlines.unshift({ id: uuidv4(), text: `Where is ${p.artistName}'s comeback?`, fullStory: 'The announcement came. The music didn\'t.', date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 4, category: 'general' });
    remember(state, 'career', 'You announced a comeback and never dropped anything.', { weight: 3, tone: 'bad' });
    log.push('📉 The comeback you announced never came. Fans noticed.');
  }
  if (L.mode !== 'retired') return;
  const weeks = Math.floor(((serial - (L.modeSince ?? serial)) % 7 + days) / 7);
  if (L.postCareerRole === 'producer' && weeks > 0) {
    const pay = producerIncome(p.stats.productionKnowledge, blendedFame(p)) * weeks;
    p.career.money += pay;
    p.career.totalEarnings += pay;
    ledgerAdd('producing', pay);
  }
  if (L.postCareerRole === 'mentor' && weeks > 0) p.career.reputation = Math.min(100, p.career.reputation + 0.15 * weeks);
}

/**
 * Time spent in a chair (tattoo, barber): the clock moves on even if the
 * player had it paused, exactly as the running clock would move it.
 */
function passTime(minutes: number): void {
  const st = useGameStore.getState();
  const paused = st.clockPaused;
  if (paused) useGameStore.setState({ clockPaused: false });
  useGameStore.getState().advanceClock(minutes);
  if (paused) useGameStore.setState({ clockPaused: true });
}

// ─── THE JOURNAL ───────────────────────────────────────────────────────────

/** Write a line in the career's journal. */
function remember(state: GameState, kind: MemoryKind, text: string, opts: { npcIds?: string[]; weight?: number; tone?: Memory['tone'] } = {}): void {
  if (!state.player) return;
  state.memories = addMemory(state.memories ?? [], {
    id: uuidv4(), serial: dateToSerial(state.gameDate), minute: nowMinuteOf(state), kind, text: text.slice(0, 220),
    npcIds: opts.npcIds?.filter((id) => !!id), weight: opts.weight ?? 2, tone: opts.tone,
  });
}

const HEADLINE_KIND: Record<string, MemoryKind> = { award: 'career', chart: 'music', beef: 'beef', feature: 'music', show: 'career', scandal: 'life', business: 'money', general: 'career' };
// Awards, court and deals write their own journal lines where they happen;
// these are the things that otherwise only reach the player as a notification.
const NOTE_KIND: Partial<Record<string, { kind: MemoryKind; weight: number }>> = { chart_number_one: { kind: 'music', weight: 5 }, chart_debut: { kind: 'music', weight: 3 }, certification: { kind: 'music', weight: 4 } };

/** Headlines about the player and the big notifications go in the journal. */
function captureMemories(state: GameState): void {
  const p = state.player;
  if (!p) return;
  const cur = state.memoryCursor ?? (state.memoryCursor = {});
  const heads: Headline[] = [];
  for (const h of state.headlines ?? []) { if (h.id === cur.headline || heads.length >= 30) break; heads.push(h); }
  if (state.headlines?.[0]) cur.headline = state.headlines[0].id;
  // The roster's ids never change, so the set is built once per session rather
  // than by walking eleven thousand drafts every midnight.
  const npcIds = heads.length ? rosterIds(state) : new Set<string>();
  for (const h of heads.reverse()) {
    if (!h.relatedEntities?.includes(p.id) || (h.priority ?? 0) < 3) continue;
    // Already written down by the system that made the news.
    if (h.category === 'award' || / v\. |sues |to court|comeback|retire|steps back|slows down/i.test(h.text)) continue;
    remember(state, HEADLINE_KIND[h.category] ?? 'career', h.text, { npcIds: h.relatedEntities.filter((id: string) => id !== p.id && npcIds.has(id)), weight: h.priority >= 6 ? 4 : 3, tone: h.category === 'scandal' ? 'bad' : undefined });
  }
  const notes: GameNotification[] = [];
  for (const n of state.notifications ?? []) { if (n.id === cur.notification || notes.length >= 30) break; notes.push(n); }
  if (state.notifications?.[0]) cur.notification = state.notifications[0].id;
  for (const n of notes.reverse()) {
    const k = NOTE_KIND[n.kind];
    if (k) remember(state, k.kind, n.title.replace(/^[^\p{L}\p{N}"“]+/u, ''), { weight: k.weight, tone: 'good' });
  }
}

let rosterIdCache: Set<string> | null = null;
function rosterIds(state: GameState): Set<string> {
  if (!rosterIdCache || rosterIdCache.size !== state.npcs.length) rosterIdCache = new Set((raw(state.npcs) as NPC[]).map((n) => n.id));
  return rosterIdCache;
}

/** An NPC posts on Chirp about something that just happened. */
function npcPost(state: GameState, npc: NPC, content: string): void {
  state.socialPosts.unshift({
    id: uuidv4(), platform: 'chirp', authorId: npc.id, authorName: npc.name, content,
    likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 40, daySerial: dateToSerial(state.gameDate),
  } as SocialPost);
  livenPost(state, state.socialPosts[0]);
}

// ─── DRIP ──────────────────────────────────────────────────────────────────

/** The player's look, filled in for careers from before looks existed. */
function lookOfPlayer(state: GameState): Look | null {
  const p = state.player;
  if (!p) return null;
  if (!p.look) p.look = lookFor(p.id, p.gender === 'female' ? 'female' : p.gender === 'male' ? 'male' : undefined);
  return p.look;
}

/** What you were already wearing becomes your first wardrobe: plain basics. */
function asOwned(w: Wearable, serial: number): OwnedItem {
  return { ...w, price: 0, paid: 0, bought: serial, brand: 'Own clothes', tier: 'basic', hype: 18, released: serial - 120, classic: true };
}

function dripOf(state: GameState): DripState {
  const serial = dateToSerial(state.gameDate);
  if (!state.drip) {
    state.drip = newDrip();
    const look = lookOfPlayer(state);
    if (look) for (const w of Object.values(look.outfit)) if (w && !state.drip.wardrobe.some((x) => x.id === w.id)) state.drip.wardrobe.push(asOwned(w, serial));
    runDrops(state.drip, serial, Math.random, collabNames(state));
  }
  return state.drip;
}

/** Fictional artists hot enough for a sneaker collab. Never real people. */
function collabNames(state: GameState): string[] {
  return (raw(state.npcs) as NPC[]).filter((n) => n.role === 'artist' && n.fame >= 62 && !isRealId(n.id)).slice(0, 30).map((n) => n.name);
}

/** The shop restocks every other Friday. */
function dripTick(state: GameState): void {
  if (!state.player) return;
  const d = dripOf(state);
  const fresh = runDrops(d, dateToSerial(state.gameDate), Math.random, collabNames(state));
  if (!fresh.length) return;
  const star = fresh.find((x) => x.collab) ?? fresh.find((x) => x.limited) ?? fresh.find((x) => x.slot === 'shoes');
  pushNotification(state, { kind: 'business', title: `👟 New drop: ${star?.name ?? `${fresh.length} pieces`}`, body: `${fresh.length} new pieces in the shop${fresh.some((x) => x.limited) ? ' — some are limited and will sell out' : ''}.`, artSeed: `drop|${d.drops}` });
}

/** Today's drip score for the player. */
function playerDrip(state: GameState): number {
  const look = state.player?.look;
  if (!look) return 20;
  return dripScore(look.outfit, dateToSerial(state.gameDate), state.drip, look.tattoos).score;
}

// ─── THE BANK ──────────────────────────────────────────────────────────────

/** What you've been earning a month lately (lifetime earnings, three months apart). */
export function monthlyIncomeOf(state: Pick<GameState, 'earningsMarks' | 'player'>): number {
  const marks = state.earningsMarks ?? [];
  const now = state.player?.career.totalEarnings ?? 0;
  if (!marks.length) return 0;
  const back = marks[Math.max(0, marks.length - 3)];
  const months = Math.max(1, marks.length - Math.max(0, marks.length - 3));
  return Math.max(0, Math.round((now - back.total) / months));
}

export function creditOf(state: GameState): number {
  const c = state.credit ?? { missedEver: 0, defaults: 0, paidOff: 0 };
  return creditScore({
    monthlyIncome: monthlyIncomeOf(state),
    reputation: state.player?.career.reputation ?? 50,
    missedEver: c.missedEver,
    defaults: c.defaults,
    paidOff: c.paidOff,
    monthsActive: (state.earningsMarks ?? []).length,
    netWorth: netWorthOf(state).total,
  });
}

/** A pseudo-account for an institution that can sue (a bank). */
function institution(state: GameState, id: string, name: string): NPC {
  let n = state.npcs.find((x) => x.id === id);
  if (!n) {
    n = { id, name, fame: 50, personality: ['calculating', 'patient'], role: 'lawyer', tier: 'national', country: state.player?.country ?? 'Ghana', relationshipScore: 0, relationshipStage: 'stranger', memoryLog: [], isAvailable: true, gender: 'other', age: 40 } as unknown as NPC;
    state.npcs.push(n);
  }
  return n;
}

/** Month-end: note what you've earned, then collect what you owe the banks. */
function bankTick(state: GameState, serial: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  const marks = state.earningsMarks ?? (state.earningsMarks = []);
  if (!marks.length || serial - marks[marks.length - 1].serial >= 30) {
    marks.push({ serial, total: p.career.totalEarnings });
    if (marks.length > 12) marks.splice(0, marks.length - 12);
  }
  const credit = state.credit ?? (state.credit = { missedEver: 0, defaults: 0, paidOff: 0 });
  for (const l of state.loans ?? []) {
    let guard = 0;
    while (l.status === 'active' && serial >= l.nextDue && guard++ < 12) {
      l.balance = Math.round(l.balance * (1 + l.apr / 12));
      const due = Math.min(l.monthly, l.balance);
      if (p.career.money >= due) {
        p.career.money -= due;
        ledgerAdd('loans', -due);
        l.balance -= due;
        l.paidMonths += 1;
        l.missed = 0;
        if (l.balance <= 1) {
          l.status = 'paid';
          l.balance = 0;
          credit.paidOff += 1;
          remember(state, 'money', `Paid off the ${l.kind === 'mortgage' ? 'mortgage' : 'loan'} with ${l.lender}. Debt-free on that one.`, { weight: 3, tone: 'good' });
          log.push(`🏦 Loan with ${l.lender} paid off.`);
        }
      } else {
        l.missed += 1;
        credit.missedEver += 1;
        l.balance += Math.round(l.monthly * 0.05);
        pushNotification(state, { kind: 'business', title: `🏦 Missed a payment to ${l.lender}`, body: `${money0(due)} was due and the account was short. Late fee added. ${l.missed >= 2 ? 'One more and they call it in.' : 'Your credit score just dropped.'}`, artSeed: `loan|${l.id}|${serial}`, action: { type: 'home', id: 'bank' } });
        log.push(`🏦 Missed the ${money0(due)} payment to ${l.lender}.`);
        if (l.missed >= 3) {
          l.status = 'default';
          credit.defaults += 1;
          const bank = institution(state, `bank:${l.lender}`, l.lender);
          let owed = l.balance;
          // A mortgage is secured: they take the house first.
          const home = l.homeId ? (state.homes ?? []).find((h) => h.id === l.homeId) : undefined;
          if (home) {
            const sale = Math.round(ownedValue(home, state.market?.propertyIndex ?? 100) * 0.75);
            owed = Math.max(0, owed - sale);
            state.homes = (state.homes ?? []).filter((h) => h.id !== home.id);
            if (state.home?.ownedId === home.id) state.home = newHome(home.city, home.country, serial);
            remember(state, 'money', `${l.lender} repossessed the ${homeDef(home.tier).name.toLowerCase()} in ${home.city}.`, { weight: 5, tone: 'bad' });
            pushNotification(state, { kind: 'business', title: '🏚️ Repossessed', body: `${l.lender} took the ${homeDef(home.tier).name.toLowerCase()} and sold it at auction for ${money0(sale)}.${owed > 0 ? ` You still owe ${money0(owed)}.` : ''}`, artSeed: `repo|${home.id}`, action: { type: 'home', id: 'bank' } });
            l.balance = owed;
          }
          if (owed > 0) {
            const c = npcSues(state, bank, 'debt', owed, 92, [`Borrowed ${money0(l.principal)} from ${l.lender} on ${formatGameDate(serialToDate(l.startSerial))}.`, `${l.paidMonths} payments made, then three missed in a row.`, `${money0(owed)} outstanding.`], l.id);
            l.caseId = c.id;
          } else {
            l.status = 'paid';
          }
        }
      }
      l.nextDue += 30;
    }
  }
}

// ─── HOME ──────────────────────────────────────────────────────────────────

function homeOf(state: GameState): HomeState {
  const p = state.player!;
  return state.home ?? (state.home = newHome(p.city, p.country, dateToSerial(state.gameDate)));
}

/** What staying alive and housed costs a month, and what comes back in. */
export function monthlyBurnOf(state: Pick<GameState, 'home' | 'homes' | 'ownedAssets' | 'player' | 'market'>): { rent: number; living: number; upkeep: number; tenants: number; total: number } {
  const p = state.player;
  const h = state.home ?? (p ? newHome(p.city, p.country, 0) : undefined);
  if (!h) return { rent: 0, living: 0, upkeep: 0, tenants: 0, total: 0 };
  const rent = h.ownedId || h.tier === 'family' ? 0 : rentFor(h.tier, h.country);
  const living = livingFor(h.tier, h.country);
  const idx = state.market?.propertyIndex ?? 100;
  const upkeep = (state.ownedAssets ?? []).reduce((a, x) => a + upkeepFor(x.category, x.cost), 0)
    + (state.homes ?? []).reduce((a, o) => a + Math.round(ownedValue(o, idx) * 0.0008), 0);
  const tenants = (state.homes ?? []).filter((o) => o.rentedOut && o.id !== h.ownedId).reduce((a, o) => a + rentIncome(o), 0);
  return { rent, living, upkeep, tenants, total: rent + living + upkeep - tenants };
}

/** Rent renewals, the landlord's patience, and the monthly bills. */
function homeTick(state: GameState, serial: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  const h = homeOf(state);
  const def = homeDef(h.tier);
  // Rent comes round: a year at a time in Ghana and Nigeria, monthly elsewhere.
  if (!h.ownedId && h.tier !== 'family' && !h.due && serial >= h.paidUntil) {
    const months = renewalMonths(h.country);
    const amount = rentFor(h.tier, h.country) * months;
    if (p.career.money >= amount) {
      p.career.money -= amount;
      ledgerAdd('housing', -amount);
      h.paidUntil += months * 30;
      log.push(`🔑 Rent paid on the ${def.name.toLowerCase()}: ${money0(amount)}${months > 1 ? ` for ${months} months` : ''}.`);
      if (months > 1) remember(state, 'money', `Paid ${money0(amount)} — a year's rent up front on the ${def.name.toLowerCase()}.`, { weight: 2 });
    } else {
      h.due = { amount, by: serial + 30 };
      pushNotification(state, { kind: 'business', title: '🔑 Rent is due', body: `The landlord wants ${money0(amount)}${months > 1 ? ' (a year up front)' : ''}. You have 30 days.`, artSeed: `home|${serial}`, action: { type: 'home', id: 'rent' } });
      log.push(`🔑 Rent is due on the ${def.name.toLowerCase()} — ${money0(amount)}. 30 days to pay.`);
    }
  }
  // Out of time: you're out.
  if (h.due && serial > h.due.by) {
    const was = def.name.toLowerCase();
    state.home = { ...newHome(h.city, h.country, serial) };
    pushNotification(state, { kind: 'business', title: '📦 Evicted', body: `You couldn't pay the rent on the ${was}. Your things are at the family house.`, artSeed: `home|evict|${serial}`, action: { type: 'home', id: 'evicted' } });
    remember(state, 'life', `Evicted from the ${was}. Back at the family house.`, { weight: 4, tone: 'bad' });
    log.push(`📦 Evicted from the ${was}. Back at the family house.`);
    if (blendedFame(p) >= 35) {
      p.career.reputation = Math.max(0, p.career.reputation - 2);
      const post: SocialPost = { id: uuidv4(), platform: 'chirp', authorId: 'scene_watch', authorName: 'Scene Watch', content: `👀 Hearing ${p.artistName} got put out of their place over rent. Fame doesn't pay the landlord.`, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 70, tags: [{ id: 'player', name: p.artistName }] };
      livenPost(state, post, { heat: 1.5 });
      state.socialPosts.unshift(post);
    }
    return;
  }
  // The month's bills: food, power, data, getting around, and what you own.
  let guard = 0;
  while (serial >= h.nextBill && guard++ < 24) {
    const b = monthlyBurnOf(state);
    const out = b.living + b.upkeep;
    p.career.money += b.tenants - out;
    ledgerAdd('living', -b.living);
    if (b.upkeep) ledgerAdd('upkeep', -b.upkeep);
    if (b.tenants) ledgerAdd('rent', b.tenants);
    if (p.career.money < 0) {
      const short = -p.career.money;
      p.career.money = 0;
      log.push(`🍲 Short ${money0(short)} on the month's bills — family covered the food.`);
      if (!state.storyFired?.['broke_month'] || serial - state.storyFired['broke_month'] > 120) {
        (state.storyFired ?? (state.storyFired = {}))['broke_month'] = serial;
        remember(state, 'money', `Couldn't cover the month's bills. Family stepped in.`, { weight: 3, tone: 'bad' });
      }
    }
    h.nextBill += 30;
  }
}

// ─── CLOTHING BRAND ────────────────────────────────────────────────────────

function brandOf(v: Venture, serial: number): BrandState {
  if (!v.brand) {
    v.brand = newBrand(serial, Math.random);
    const kind: ProductKind = 'tee';
    v.brand.products.push({
      id: uuidv4(), kind, name: 'Logo Tee', material: 'basic', design: 45, price: 30, stock: 150,
      incoming: [], unitCost: unitCostFor(kind, 'basic', 'local', 150), supplier: 'local', sold: 0, weeks: [], hype: 10,
      limited: false, launched: serial, soldOutWeeks: 0,
    });
    v.brand.log = ['Opened with 150 Logo Tees in stock.'];
  }
  return v.brand;
}

function brandWeekCtx(state: GameState, v: Venture): WeekCtx {
  const ctx = ventureCtx(state, v);
  return {
    fame: ctx.fame, fanbase: ctx.fanbase, momentum: ctx.momentum, reputation: v.reputation, brandHype: v.hype,
    level: v.level, staff: v.staff, marketing: v.marketing, month: state.gameDate.month, merchBoost: ctx.merchBoost,
    lawyer: (state.crew ?? []).some((c) => c.role === 'lawyer'),
  };
}

/** Run every brand week that has passed. */
function brandTick(state: GameState, serial: number, days: number, log: string[]): void {
  const p = state.player;
  if (!p) return;
  for (const v of state.ventures ?? []) {
    if (v.closed || v.type !== 'clothing') continue;
    const b = brandOf(v, serial);
    const week = Math.floor(serial / 7);
    let guard = 0;
    while (b.lastWeek < week && guard++ < 6) {
      b.lastWeek += 1;
      const res = weekTick(b, b.lastWeek * 7, brandWeekCtx(state, v), Math.random);
      v.reputation = Math.max(0, Math.min(100, v.reputation + res.repDelta));
      v.hype = Math.max(0, Math.min(100, v.hype * 0.9 + res.hypeDelta));
      p.career.money += res.week.profit;
      ledgerAdd('ventures', res.week.profit);
      if (res.events[0]) log.push(`👕 ${v.name}: ${res.events[0]}`);
    }
    if (days >= 7 && b.lastWeek < week) b.lastWeek = week;
  }
}

/** Daily: invitations arrive (more when you're hot) and old ones lapse. */
function interviewTick(state: GameState, serial: number, days: number, npcs?: NPC[]): void {
  const p = state.player;
  if (!p) return;
  const invites = state.interviewInvites ?? (state.interviewInvites = []);
  for (const inv of invites) {
    if (inv.status === 'open' && serial > inv.expiresSerial) {
      inv.status = 'expired';
      const rel = state.outletRel ?? (state.outletRel = {});
      rel[inv.outletId] = (rel[inv.outletId] ?? 0) - 2;
      for (const b of state.managerDesk ?? []) if (b.refId === inv.id && b.status !== 'done') { b.status = 'done'; b.outcome = 'Expired — nobody answered.'; }
    }
  }
  if (invites.length > 20) state.interviewInvites = invites.filter((x, i) => x.status === 'open' || i < 12);
  const open = invites.filter((x) => x.status === 'open').length;
  if (open >= 3) return;
  const fame = blendedFame(p);
  const released = state.songs.filter((s) => isSongReleased(s));
  const latest = released[released.length - 1];
  const st = latest ? state.platformStats?.[latest.id] : undefined;
  const recent = !!st && serial - st.release <= 21;
  const hotBeef = state.beefs.some((b) => !b.resolution && settleHeat(b, serial) >= 35);
  const press = (crewOn(state, 'publicist', 'press') ? 0.07 : 0) + (crewWithSkill(state.crew, 'hype_machine') ? 0.04 : 0);
  const chance = 1 - Math.pow(1 - Math.min(0.55, 0.05 + fame / 350 + p.career.momentum / 700 + (recent ? 0.1 : 0) + (hotBeef ? 0.08 : 0) + press), Math.min(days, 7));
  if (Math.random() > chance) return;
  if (!reaches(state.legacy?.mode, 'press', Math.random())) return;
  const ctx = { ...interviewContext(state, npcs), hasRecentRelease: recent, hotBeef };
  const pickd = pickInvite(outletsNow(state), ctx, state.outletRel ?? {}, Math.random);
  if (!pickd || invites.some((x) => x.status === 'open' && x.outletId === pickd.outlet.id)) return;
  const inv: InterviewInvite = {
    id: uuidv4(), outletId: pickd.outlet.id, outletName: pickd.outlet.name, format: pickd.format, reason: pickd.reason, fee: pickd.fee,
    receivedSerial: serial, expiresSerial: serial + 4, status: 'open',
  };
  invites.unshift(inv);
  if (managerOf(state, npcs)) {
    fileBrief(state, interviewBrief(state, inv, pickd.outlet));
  } else {
    state.mailbox.unshift({
      id: uuidv4(), from: pickd.outlet.id, fromName: pickd.outlet.name,
      subject: `${KIND_EMOJI[pickd.outlet.kind]} ${pickd.outlet.name} wants you on`,
      body: `${pickd.reason}\n\nFormat: ${FORMAT_INFO[pickd.format].label}.${pickd.fee ? ` Appearance fee $${pickd.fee.toLocaleString()}.` : ''}\nAnswer within 4 days — Interviews.`,
      timestamp: new Date().toISOString(), read: false, type: 'general',
    });
  }
  pushNotification(state, { kind: 'feature', title: `${pickd.outlet.name} wants you on`, body: `${FORMAT_INFO[pickd.format].emoji} ${FORMAT_INFO[pickd.format].label}${pickd.fee ? ` · $${pickd.fee.toLocaleString()}` : ''}`, artSeed: `outlet|${pickd.outlet.id}` });
}

/** The interview is over: apply everything it did. */
function finishInterview(state: GameState): InterviewRecord | null {
  const p = state.player;
  const ai = state.activeInterview;
  if (!p || !ai) return null;
  const outlet = outletsNow(state).find((o) => o.id === ai.outletId);
  if (!outlet) { state.activeInterview = null; return null; }
  const serial = dateToSerial(state.gameDate);
  const total = mergeEffects(ai.effects);
  const reach = Math.max(0.6, Math.min(1.4, Math.log10(outlet.reach) / 5.5));
  const clampN = (n: number) => Math.max(0, Math.min(100, n));
  const fame = (total.fame ?? 0) * reach;
  p.career.localFame = clampN(p.career.localFame + fame * 0.7);
  p.career.nationalFame = clampN(p.career.nationalFame + fame * 0.35);
  if (outlet.international) p.career.internationalFame = clampN(p.career.internationalFame + fame * 0.3);
  const crew = crewBonuses(raw(state.crew) as CrewMember[]);
  const rep = (total.rep ?? 0) < 0 ? (total.rep ?? 0) * crew.controversyMult : (total.rep ?? 0);
  p.career.reputation = clampN(p.career.reputation + rep);
  if (total.momentum) addMomentum(state, total.momentum);
  const fans = Math.round((total.fans ?? 0) * reach);
  p.career.fanbase = Math.max(0, p.career.fanbase + fans);
  const money = ai.walked ? 0 : ai.fee + (total.money ?? 0);
  p.career.money += money;
  if (money > 0) p.career.totalEarnings += money;
  p.stats.charisma = Math.min(100, p.stats.charisma + 0.6);
  p.stats.networking = Math.min(100, p.stats.networking + 0.3);
  const ctx = interviewContext(state);
  // The record you talked up gets a push.
  if ((total.song ?? 0) > 0 && ctx.latestSong) {
    const st = state.platformStats?.[ctx.latestSong.id];
    const age = st ? Math.max(0, serial - st.release) : 0;
    plantRevival(state, ctx.latestSong.id, { power: Math.min(0.9, (total.song ?? 0) * 0.45 * reach), width: 6, reason: `Talked up on ${outlet.name}` }, age);
  }
  // People you named.
  const reactions: string[] = [];
  for (const r of total.rel ?? []) {
    const n = state.npcs.find((x) => x.id === r.npcId);
    if (!n) continue;
    n.relationshipScore = Math.max(-100, Math.min(100, n.relationshipScore + r.v));
    n.memoryLog = [...(n.memoryLog ?? []).slice(-9), `${r.v > 0 ? 'You praised them' : 'You took a shot at them'} on ${outlet.name}.`];
    if (Math.abs(r.v) >= 5 && !isRealId(n.id) && n.role === 'artist' && !reactions.includes(n.id)) {
      reactions.push(n.id);
      const post: SocialPost = {
        id: uuidv4(), platform: 'chirp', authorId: n.id, authorName: n.name,
        content: r.v > 0 ? pick3([`Heard what @${p.artistName.replace(/\s+/g, '')} said on ${outlet.name} 🙏 love is love`, `Appreciate the flowers @${p.artistName.replace(/\s+/g, '')} 🫡`], n.id + serial) : pick3([`Heard what @${p.artistName.replace(/\s+/g, '')} said on ${outlet.name}. Okay. 👀`, `Some people get on a podcast and forget who they are.`], n.id + serial),
        likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: r.v > 0 ? 40 : 70,
        tags: [{ id: 'player', name: p.artistName }],
      };
      livenPost(state, post, { at: gameMinute(state) + 60 + Math.floor(Math.random() * 300), heat: r.v > 0 ? 0.5 : 1.5 });
      state.socialPosts.unshift(post);
      pushActivity(state, { kind: 'mention', text: `${n.name} reacted to your interview`, actorId: n.id, actorName: n.name, postId: post.id, minute: post.postedMinute! });
    }
  }
  if (total.heat) nudgeBeef(state, total.heat.npcId, total.heat.v, serial);
  if (total.beefStart && !state.beefs.some((b) => b.npcId === total.beefStart!.npcId && !b.resolution)) {
    const n = state.npcs.find((x) => x.id === total.beefStart!.npcId);
    if (n && !isRealId(n.id)) npcStartsBeef(state, n as NPC, serial, `you called them out on ${outlet.name}.`);
  }
  // The clip.
  const viral = !ai.walked ? Math.random() < (total.viral ?? 0) * reach : Math.random() < 0.6;
  const best = [...ai.transcript].reverse().find((t) => t.passed || t.tag === 'Savage' || t.tag === 'Walk out' || t.surprise) ?? ai.transcript[0];
  if (viral) { addMomentum(state, 3); p.career.localFame = clampN(p.career.localFame + 1); }
  const outletAuthor = `outlet_${outlet.id}`;
  const clip: SocialPost = {
    id: uuidv4(), platform: 'clip', authorId: outletAuthor, authorName: outlet.name,
    content: best ? `"${best.a}" — ${p.artistName} on ${outlet.name} 🎙️` : `${p.artistName} on ${outlet.name}`,
    likes: Math.round(outlet.reach / 60), shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: viral ? 85 : 40, kind: 'bts', viral: viral || undefined,
    tags: [{ id: 'player', name: p.artistName }],
  };
  livenPost(state, clip, { at: gameMinute(state) + 30, heat: viral ? 2 : 0.6, viral });
  state.socialPosts.unshift(clip);
  pushActivity(state, { kind: 'mention', text: `${outlet.name} posted your interview${viral ? ' — it\'s blowing up' : ''}`, actorName: outlet.name, postId: clip.id, minute: clip.postedMinute! });
  const top = best?.surprise ? 'moment' : best?.tag === 'Savage' ? 'comments' : 'interview';
  const headline = headlineFor(p.artistName, outlet, total, !!ai.walked, viral, top);
  state.headlines.unshift({ id: uuidv4(), text: headline, fullStory: ai.transcript.slice(-3).map((t) => `"${t.a}"`).join(' · '), date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: viral ? 7 : 5, category: total.beefStart ? 'beef' : 'general' });
  const orel = state.outletRel ?? (state.outletRel = {});
  orel[outlet.id] = Math.max(-50, Math.min(50, (orel[outlet.id] ?? 0) + (total.outlet ?? 0) + (ai.walked ? 0 : 3)));
  const rec: InterviewRecord = {
    id: ai.id, outletId: outlet.id, outletName: outlet.name, format: ai.format, headline, serial,
    highlights: ai.transcript.map((t) => t.a).slice(0, 6),
    deltas: { fame: Math.round(fame * 10) / 10, rep: Math.round(rep * 10) / 10, momentum: Math.round((total.momentum ?? 0) * 10) / 10, fans, money },
    viral, walked: !!ai.walked,
  };
  state.interviewLog = [rec, ...(state.interviewLog ?? [])].slice(0, 30);
  if (ai.inviteId) {
    const inv = (state.interviewInvites ?? []).find((x) => x.id === ai.inviteId);
    if (inv) inv.status = 'done';
  }
  state.activeInterview = null;
  return rec;
}

// ─── BEATS & THE BUILDING: STORE SIDE ──────────────────────────────────────
// The engine is `sim/beats.ts` and the building table lives in `sim/room.ts`.
// This keeps the library, delivers what the team makes and what was ordered,
// rotates the beat store weekly, and bills the building monthly.

function beatsOf(state: GameState): BeatsState {
  if (!state.beats || !Array.isArray(state.beats.library)) state.beats = emptyBeats();
  if (!state.beats.lastDrop) state.beats.lastDrop = {};
  if (!Array.isArray(state.beats.orders)) state.beats.orders = [];
  if (!Array.isArray(state.beats.store)) state.beats.store = [];
  return state.beats;
}

function refreshBeatStore(state: GameState, npcs: NPC[], serial: number): void {
  const p = state.player;
  if (!p) return;
  const b = beatsOf(state);
  const week = Math.floor(serial / 7);
  if (b.storeWeek === week && b.store.length) return;
  const producers: NPC[] = [];
  for (const n of npcs) if ((n.role === 'producer' || n.role === 'engineer') && !isRealId(n.id)) producers.push(n);
  b.store = storeCatalogue({ producers, genre: p.genre, country: p.country, week, fame: blendedFame(p) });
  b.storeWeek = week;
}

/** Keep the library from growing forever: unused beats first, newest first. */
function trimLibrary(b: BeatsState): void {
  if (b.library.length <= 60) return;
  const unused = b.library.filter((x) => !x.usedOnSongId).slice(0, 45);
  const used = b.library.filter((x) => x.usedOnSongId).slice(0, 15);
  b.library = [...unused, ...used].sort((x, y) => y.acquiredSerial - x.acquiredSerial);
}

function deliverBeatOrder(state: GameState, o: BeatOrder, serial: number): void {
  const b = beatsOf(state);
  const npc = state.npcs.find((n) => n.id === o.producerId);
  const crewMember = (state.crew ?? []).find((c) => c.npcId === o.producerId);
  const skill = crewMember ? Math.max(crewMember.skill, npc ? producerSkillOf(npc as NPC) : 0) : npc ? producerSkillOf(npc as NPC) : 50;
  const quality = customBeatQuality(skill, Math.random(), !!o.redoOf);
  const beat: OwnedBeat = {
    id: `beat:order:${o.id}`,
    name: beatName(`order|${o.id}`),
    quality,
    genre: o.genre,
    bpm: o.bpm,
    mood: o.mood,
    producerId: o.producerId,
    producerName: o.producerName,
    source: 'custom',
    license: o.inHouse ? 'inhouse' : 'exclusive',
    acquiredSerial: serial,
    price: o.fee || undefined,
    forTitle: o.forTitle,
    redos: o.redoOf ? (b.library.find((x) => x.id === o.redoOf)?.redos ?? 0) + 1 : 0,
  };
  b.library.unshift(beat);
  pushNotification(state, {
    kind: 'feature',
    title: `${o.producerName} sent the beat${o.forTitle ? ` for "${o.forTitle}"` : ''}`,
    body: `"${beat.name}" — ${beatGrade(quality)} (${quality}). ${o.redoOf ? 'The redo is in. Compare it with the first one.' : 'Built to your brief.'}`,
    artSeed: `beat|${beat.id}`,
  });
  state.lastEventLog.unshift(`🎹 ${o.producerName} delivered "${beat.name}"${o.forTitle ? ` for "${o.forTitle}"` : ''} — ${beatGrade(quality)}.`);
}

/** The facts the team talks from — for the AI layer. */
export function teamSnapshotOf(state: GameState): TeamSnapshot {
  return teamSnapshot(state, dateToSerial(state.gameDate));
}

function teamSnapshot(state: GameState, serial: number): TeamSnapshot {
  const p = state.player!;
  const now = nowMinuteOf(state);
  const plan = (state.appointments ?? []).filter((a) => a.status === 'confirmed' && a.atMinute > now).sort((a, b) => a.atMinute - b.atMinute)[0];
  const loan = (state.loans ?? []).filter((l) => l.status === 'active').sort((a, b) => a.nextDue - b.nextDue)[0];
  const openCase = (state.cases ?? []).find((c) => c.status === 'served' || c.status === 'hearing');
  const lastPost = Math.max(-999, ...Object.values(state.socialStats ?? {}).map((x) => x.lastPostSerial ?? -999));
  return {
    money: p.career.money, energy: p.energy, fame: blendedFame(p), momentum: p.career.momentum ?? 0, serial, minute: now,
    openOffers: (state.managerDesk ?? []).filter((b) => b.status === 'new').length + (state.moments ?? []).filter((m) => m.status === 'open').length,
    nextPlan: plan ? { label: `${KIND_LABEL[plan.kind].label.toLowerCase()} with ${plan.npcName.split(' ')[0]}`, inMin: plan.atMinute - now } : undefined,
    freshBeats: (state.beats?.library ?? []).filter((b) => !b.usedOnSongId).length,
    unreleased: state.songs.filter((x) => x.masterStatus === 'recorded' || x.masterStatus === 'mixed' || x.masterStatus === 'mastered').filter((x) => !x.archivedAt).length,
    rentDue: state.home?.due ? { amount: state.home.due.amount, days: Math.max(0, state.home.due.by - serial) } : undefined,
    loanDue: loan ? { amount: loan.monthly, days: Math.max(0, loan.nextDue - serial) } : undefined,
    openCase: openCase ? { kind: String(openCase.kind), claim: openCase.claim } : undefined,
    daysSincePost: lastPost < 0 ? 99 : Math.max(0, serial - lastPost),
    burn: monthlyBurnOf(state).total,
    vault: state.songs.filter((x) => isVaultMaster(x)).sort((a, b) => b.quality - a.quality).slice(0, 6).map((x) => ({ id: x.id, title: x.title, quality: x.quality, status: x.masterStatus ?? 'recorded' })),
    newest: (() => {
      const out = state.songs.filter((x) => isSongReleased(x)).sort((a, b) => releaseSerialOf(state, b, serial) - releaseSerialOf(state, a, serial))[0];
      return out ? { title: out.title, days: Math.max(0, serial - releaseSerialOf(state, out, serial)), weekly: Math.round(out.weeklyStreams ?? 0) } : undefined;
    })(),
    desk: (state.managerDesk ?? []).filter((b) => b.status !== 'done').slice(0, 4).map((b) => b.title),
    nextShow: (() => {
      const sh = [...state.scheduledShows].filter((x) => x.serial >= serial).sort((a, b) => a.serial - b.serial)[0];
      if (!sh) return undefined;
      const v = findVenue(sh.venueId);
      return { label: `the ${v ? `${v.name} show in ${v.city}` : 'show'}`, days: sh.serial - serial };
    })(),
    nextAward: (() => {
      const mine = Object.values(state.awardSeasons ?? {}).filter((x) => x.phase !== 'done' && !x.quiet && x.cal.ceremony >= serial).sort((a, b) => a.cal.ceremony - b.cal.ceremony)[0];
      const body = mine ? bodiesFor(state).find((b) => b.id === mine.bodyId) : undefined;
      return mine && body ? { name: `the ${body.name}`, days: mine.cal.ceremony - serial, entered: !!mine.entered || mine.cal.entriesClose === undefined || body.scope === 'global', nominated: mine.categories.filter((c) => c.nominees.some((n) => n.isPlayer)).length } : undefined;
    })(),
    policy: policyLines(policyOf(state.teamPolicy)),
    managerKind: (() => { const m = managerOf(state); return m ? SPECIALTIES[managerSpecialty(m)].label : undefined; })(),
    payroll: (state.crew ?? []).reduce((a, c) => a + (c.monthlyWage ?? 0), 0),
    me: p.artistName,
    ...dropFacts(state, serial),
    drafts: (state.albumDrafts ?? []).slice(0, 2).map((d) => ({ title: d.title, tracks: d.songIds.length, plannedDays: d.plannedSerial !== undefined ? Math.max(0, d.plannedSerial - serial) : undefined })),
    beef: (state.beefs ?? []).find((b) => !b.resolution)?.npcName,
    slackers: (state.crew ?? []).filter((c) => c.perf?.last === 'none').map((c) => c.npcName),
  };
}

/** What the team reads before they tell you when to drop. */
function dropFacts(state: GameState, serial: number): Pick<TeamSnapshot, 'dropPlan' | 'bigDrops'> {
  const p = state.player!;
  const fame = blendedFame(p);
  const best = state.songs.filter((x) => isVaultMaster(x)).sort((a, b) => b.quality - a.quality)[0];
  // Who just dropped: a big name from home (or a global star) in the last few days.
  const idx = npcIndex(baseNpcs(state));
  const bigDrops: { name: string; title: string }[] = [];
  for (const x of state.npcSongs) {
    if ((x.weeksOut ?? 9) > 0 || !x.ownerId) continue;
    const n = idx.get(x.ownerId);
    if (!n || n.fame < Math.max(55, fame + 15) || (n.country !== p.country && n.tier !== 'international')) continue;
    bigDrops.push({ name: n.name, title: x.title });
    if (bigDrops.length >= 2) break;
  }
  if (!best) return { bigDrops };
  let d = serial;
  while (serialWeekday(d) !== 5) d++;
  const newest = state.songs.filter((x) => isSongReleased(x)).reduce((m, x) => Math.max(m, releaseSerialOf(state, x, -999)), -999);
  const quietDays = newest > -999 ? serial - newest : undefined;
  const wait = bigDrops.length ? `${bigDrops[0].name} just dropped "${bigDrops[0].title}" — nobody hears you that week.`
    : quietDays !== undefined && quietDays < 14 ? `Your last release is only ${quietDays} days old.`
      : undefined;
  return {
    bigDrops,
    dropPlan: { id: best.id, title: best.title, quality: best.quality, status: best.masterStatus ?? 'recorded', friday: formatGameDate(serialToDate(d)), daysToFriday: d - serial, quietDays, wait },
  };
}

/** Everybody in the group as one list, the manager included. */
function teamMembers(state: GameState): TeamMember[] {
  const out: TeamMember[] = (state.crew ?? []).map((c) => ({ id: c.npcId, name: c.npcName, role: c.role, skill: c.skill, morale: c.morale ?? 70, style: workStyleOf(c), months: c.monthsServed ?? 0, last: c.perf?.last }));
  const mgr = managerOf(state);
  if (mgr) {
    const t = traitsFor(mgr as NPC);
    const c = state.contracts.find((x) => x.type === 'management' && x.active);
    const months = c ? Math.max(0, Math.floor((dateToSerial(state.gameDate) - serialOfGameDate(c.signedAt, dateToSerial(state.gameDate))) / 30)) : 0;
    out.unshift({ id: mgr.id, name: mgr.name, role: 'manager', skill: managerNetwork(mgr), morale: 55 + mgr.relationshipScore / 2.5, style: workStyleOf(t), months, isManager: true });
  }
  return out;
}

/**
 * What the team does when you ask them to: a beat, a mix, a push. Runs after
 * the message lands, through the same actions the buttons use, so a request in
 * the chat and a tap on a button cannot behave differently.
 */
function runTeamActions(actions: TeamAction[]): void {
  for (const a of actions.slice(0, 3)) {
    const st = useGameStore.getState();
    if (!st.player) return;
    if (a.kind === 'make_beat') {
      const song = a.songId ? st.songs.find((x) => x.id === a.songId) : undefined;
      const genre = song?.genre ?? st.player.genre;
      const r = st.orderBeat({ producerId: a.from, genre, bpm: song?.bpm ?? GENRE_BY_ID[genre]?.bpm ?? 95, mood: song?.mood ?? 'defiant', forTitle: song?.title });
      useGameStore.getState().noteTeam(a.from, r.ok ? `✅ ${r.message}` : r.message);
    } else if (a.kind === 'mix_song' && a.songId) {
      const r = st.mixMasterSong(a.songId, a.from, { fee: 0 });
      useGameStore.getState().noteTeam(a.from, r ? (r.ok === false ? r.read : `✅ Mixing "${st.songs.find((x) => x.id === a.songId)?.title ?? 'the record'}" now.`) : 'That one can\'t be mixed right now.');
    } else if (a.kind === 'push_shows' || a.kind === 'push_features' || a.kind === 'push_deals') {
      st.pushManager(a.kind === 'push_shows' ? 'shows' : a.kind === 'push_features' ? 'features' : 'deals');
    }
  }
}

function pushTeamLines(state: GameState, lines: TeamLine[], serial: number): void {
  const list = state.teamChat ?? (state.teamChat = []);
  for (const l of lines) {
    list.push({ id: uuidv4(), from: l.from, name: l.name, role: l.role, text: l.text, serial, at: new Date().toISOString(), ...(l.key ? { key: l.key } : {}) });
    state.teamChatUnread = (state.teamChatUnread ?? 0) + 1;
  }
  if (list.length > 120) list.splice(0, list.length - 120);
}

/** Once a day the team talks among themselves — news you can use. */
function teamChatTick(state: GameState, serial: number): void {
  if (!state.player || !(state.crew ?? []).length) return;
  const last = state.teamChat?.[state.teamChat.length - 1];
  if (last && last.serial === serial) return;
  // Nobody posts twice in a few days, and nobody repeats the same kind of
  // update for a fortnight — unless it's urgent (rent due, a show tomorrow).
  const recent = new Map<string, number>();
  const byKey = new Map<string, number>();
  for (const m of state.teamChat ?? []) {
    if (m.from === 'player') continue;
    recent.set(m.from, Math.max(recent.get(m.from) ?? -99, m.serial));
    if (m.key) byKey.set(m.key, Math.max(byKey.get(m.key) ?? -99, m.serial));
  }
  const snap = teamSnapshot(state, serial);
  const fresh = teamUpdates(state, snap, serial).filter((l) => {
    if (l.key && serial - (byKey.get(l.key) ?? -99) < (l.urgent ? 3 : 14)) return false;
    return serial - (recent.get(l.from) ?? -99) >= (l.urgent ? 1 : 4);
  });
  pushTeamLines(state, fresh, serial);
  teamDisputeTick(state, snap, serial);
}

/** Now and then two of them don't agree — more often the greener the team. */
function teamDisputeTick(state: GameState, snap: TeamSnapshot, serial: number): void {
  const d = state.teamDispute;
  const members = teamMembers(state);
  if (d && d.status === 'open') {
    if (serial <= d.expires) return;
    const out = lapseDispute(d, members, `${d.id}|lapse`);
    applyDisputeOutcome(state, out);
    pushTeamLines(state, out.lines, serial);
    d.status = 'expired';
    d.resolution = out.text;
    return;
  }
  if (serial - (state.lastDisputeSerial ?? -99) < 5) return;
  if (Math.random() >= disputeChance(members)) return;
  const draft = draftDispute(snap, members, `${serial}|${members.length}|${Math.random()}`);
  if (!draft) return;
  state.lastDisputeSerial = serial;
  state.teamDispute = {
    id: uuidv4(), serial, expires: serial + 2, topic: draft.topic, about: draft.about,
    a: { id: draft.a.id, name: draft.a.name, role: draft.a.role }, b: { id: draft.b.id, name: draft.b.name, role: draft.b.role },
    options: draft.options, status: 'open', songId: draft.songId,
  };
  pushTeamLines(state, draft.lines.map((l) => ({ ...l, key: `dispute:${draft.topic}` })), serial);
}

function applyDisputeOutcome(state: GameState, out: { morale: { id: string; v: number }[]; rel: { id: string; v: number }[]; warn?: string }): void {
  for (const m of out.morale) {
    const c = state.crew.find((x) => x.npcId === m.id);
    if (c) c.morale = Math.max(0, Math.min(100, (c.morale ?? 70) + m.v));
  }
  for (const r of out.rel) {
    const n = state.npcs.find((x) => x.id === r.id);
    if (n) n.relationshipScore = Math.max(-100, Math.min(100, n.relationshipScore + r.v));
  }
  if (out.warn) {
    const c = state.crew.find((x) => x.npcId === out.warn);
    if (c) c.warnedSerial = dateToSerial(state.gameDate);
  }
}

function beatsTick(state: GameState, npcs: NPC[], serial: number, days: number): void {
  const p = state.player;
  if (!p) return;
  const b = beatsOf(state);
  refreshBeatStore(state, npcs, serial);
  const tier = buildingTier(state.studio?.levels);

  // 1. The team's regular drops.
  for (const c of state.crew ?? []) {
    // Producers build beats. Engineers mix and master — they don't send beats.
    if (c.role !== 'producer') continue;
    // What you have them on changes how often they send you one.
    const asg = c.assignment;
    const factor = (asg === 'placements' ? 2.5 : asg === 'mentor' ? 1.6 : asg === 'beatmaking' ? 0.5 : 1) * (specialSkillOf(c.npcId, c.role, c.skill)?.id === 'fast_hands' ? 0.6 : 1);
    const every = Math.max(2, Math.round(dropInterval(c.role, tier.beatSpeed) * factor));
    const last = b.lastDrop[c.id] ?? c.hiredSerial ?? serial;
    const due = Math.min(3, Math.floor((serial - last) / every));
    if (due <= 0) continue;
    const made: OwnedBeat[] = [];
    for (let k = 0; k < due; k++) {
      // Mostly your lane; now and then something left-field.
      const genre = Math.random() < 0.8 ? p.genre : (['afrobeats', 'hip_hop', 'drill', 'rnb', 'dancehall', 'amapiano'] as Genre[])[Math.floor(Math.random() * 6)];
      const sk = specialSkillOf(c.npcId, c.role, c.skill)?.id;
      // They make beats as well as they do for anybody else: never below what they'd sell you outside.
      const them = state.npcs.find((n) => n.id === c.npcId);
      const ownSkill = them ? Math.max(c.skill, producerSkillOf(them as NPC)) : c.skill;
      made.push(teamBeat({ memberId: c.id, npcId: c.npcId, npcName: c.npcName, role: c.role, skill: Math.min(100, ownSkill + (sk === 'hitmaker' ? 5 : sk === 'golden_ears' ? 3 : 0)), genre, serial: serial - k, roll: Math.random() }));
    }
    b.library.unshift(...made);
    b.lastDrop[c.id] = serial;
    const best = made.reduce((a, x) => (x.quality > a.quality ? x : a), made[0]);
    state.lastEventLog.unshift(`🎹 ${c.npcName} sent ${made.length > 1 ? `${made.length} new beats` : 'a new beat'} — best is "${best.name}" (${beatGrade(best.quality)}).`);
    if (best.quality >= 75) {
      pushNotification(state, { kind: 'feature', title: `${c.npcName} made something special`, body: `"${best.name}" is ${beatGrade(best.quality).toLowerCase()}. It's in your beat library.`, artSeed: `beat|${best.id}` });
    }
  }

  // 2. Orders that are ready.
  const ready = b.orders.filter((o) => o.dueSerial <= serial);
  for (const o of ready) deliverBeatOrder(state, o, serial);
  if (ready.length) b.orders = b.orders.filter((o) => o.dueSerial > serial);
  trimLibrary(b);

  // 3. The building's monthly bills, and the rentals that offset them.
  if (Math.floor(serial / 30) !== Math.floor((serial - days) / 30) && tier.level > 0) {
    const upkeep = tier.upkeep;
    const rent = state.studio?.rentOut ? rentOutIncome(tier, blendedFame(p), Math.random()) : 0;
    p.career.money -= upkeep;
    ledgerAdd('studio_upkeep', -upkeep);
    if (rent) { p.career.money += rent; ledgerAdd('studio_rent', rent); }
    state.lastEventLog.unshift(`🏠 ${tier.name}: $${upkeep.toLocaleString()} upkeep${rent ? `, $${rent.toLocaleString()} back from renting it out` : ''}.`);
    // A real room brings people through the door.
    if (state.studio?.rentOut && tier.level >= 3 && Math.random() < 0.5) {
      const visitor = npcs.find((n) => n.role === 'artist' && n.country === p.country && !isRealId(n.id) && Math.abs(n.fame - blendedFame(p)) < 20 && n.relationshipScore < 40 && Math.random() < 0.02);
      if (visitor) {
        const d = state.npcs.find((n) => n.id === visitor.id);
        if (d) d.relationshipScore = Math.min(100, d.relationshipScore + 4);
        state.lastEventLog.unshift(`🎚️ ${visitor.name} booked your room for a week. You got talking.`);
      }
    }
  }
}

// ─── "PUT ME ON THE REMIX" ─────────────────────────────────────────────────
// A record that is actually moving gets the calls: artists at your level (or a
// bit above) want in on the remix. A record nobody is playing gets none.

function remixAsksTick(state: GameState, npcs: NPC[], serial: number): void {
  const p = state.player;
  if (!p) return;
  const fame = blendedFame(p);
  const flags = state.lifeFlags ?? (state.lifeFlags = {});
  const hot = state.songs.filter((x) => isSongReleased(x) && x.lineage !== 'remix' && serial - releaseSerialOf(state, x, serial) <= 75
    && ((x.chartPositions?.[p.country] ?? 99) <= 20 || (x.weeklyStreams ?? 0) >= Math.max(4000, p.career.fanbase * 0.6)));
  for (const song of hot) {
    const asked = flags[`remixAsk:${song.id}`] ?? 0;
    if (asked >= 2 || state.songs.some((x) => x.originalSongId === song.id && x.lineage === 'remix')) continue;
    if ((state.moments ?? []).some((m) => m.kind === 'remix_ask' && m.status === 'open')) return;
    if (Math.random() > 0.18) continue;
    const beefs = activeBeefIds(state);
    const n = sampleNpcs(npcs, 1, (x) => x.role === 'artist' && !isRealId(x.id) && x.country === p.country && x.fame >= fame - 12 && x.fame <= fame + 22 && !beefs.has(x.id) && !(song.featuredArtists ?? []).includes(x.id) && !isBlocked(state, x.id))[0];
    if (!n) continue;
    flags[`remixAsk:${song.id}`] = asked + 1;
    const where = (song.chartPositions?.[p.country] ?? 99) <= 20 ? `#${song.chartPositions![p.country]} in ${p.country}` : 'everywhere right now';
    deliverMoment(state, {
      kind: 'remix_ask', channel: 'dm', npcId: n.id, npcName: n.name,
      title: `${n.name} wants on the "${song.title}" remix`,
      body: pickLine([`Yo "${song.title}" is ${where} 🔥 put me on the remix, I already wrote to it`, `Bro I can't stop playing "${song.title}". Remix. Me. Let's go 😤`, `"${song.title}" needs a remix and I'm the one. Free, I just want in.`], `${song.id}|${n.id}`),
      options: [{ id: 'yes', label: 'Let\'s do it — send the verse', hint: 'A remix with their verse lands in your vault' }, { id: 'no', label: 'The original stays as it is' }, { id: 'ignore', label: 'Leave them on read' }],
      expiresSerial: serial + 3,
      data: { songId: song.id },
    }, serial);
  }
}

// ─── BIRTHDAYS ─────────────────────────────────────────────────────────────
// Yours once a year — planned a week out, celebrated on the day. Everybody
// else's too: the people you know have days that come round, and whether you
// remembered is remembered. See `sim/birthdays.ts`.

function birthdaysTick(state: GameState, npcs: NPC[], serial: number, days: number): void {
  const p = state.player;
  if (!p) return;
  const date = state.gameDate;
  const bd = birthdayOf(p.dateOfBirth);
  if (bd) {
    const until = daysUntil(bd, date);
    // The birthday this is about: the next one, or one that passed during a skip.
    let passed = -1;
    for (let k = 0; k < Math.min(days, 20); k++) { const d = serialToDate(serial - k); if (d.month === bd.month && d.day === bd.day) { passed = k; break; } }
    const year = passed >= 0 ? serialToDate(serial - passed).year : until === 0 ? date.year : serialToDate(serial + until).year;
    if (!state.birthday || state.birthday.year !== year) state.birthday = { year };
    const b = state.birthday;
    const age = year - Number(p.dateOfBirth.slice(0, 4));
    if (passed < 0 && until <= 7 && until >= 0 && !b.plan && !b.asked) {
      b.asked = true;
      const mgr = managerOf(state, npcs);
      const pa = state.crew.find((c) => c.role === 'personal_assistant');
      const asker = pa ? { name: pa.npcName, role: 'personal_assistant' } : mgr ? { name: mgr.name, role: 'manager' } : undefined;
      const fame = blendedFame(p);
      const idx = costIndex(p.country);
      deliverMoment(state, buildBirthdayPlan({ daysOut: until, age, cost: partyCost(fame, idx), dinner: dinnerCost(fame, idx), serial, asker }), serial);
      if (asker) pushTeamLines(state, [{ from: pa ? pa.npcId : mgr!.id, name: asker.name, role: asker.role, text: `${until === 0 ? 'It\'s your birthday today' : `Your birthday is in ${until} day${until === 1 ? '' : 's'}`} 🎂 Party, dinner, or keep it low-key? Tell me and I'll sort it.`, key: `bday-ask:${year}` }], serial);
    }
    if (passed >= 0 && !b.done) {
      b.done = true;
      celebrateBirthday(state, npcs, serial, age, b.plan ?? 'normal', passed);
    }
  }
  // Everybody else's.
  const year = date.year;
  const seen = new Set(state.birthdaysSeen ?? []);
  const crewIds = new Map((state.crew ?? []).map((c) => [c.npcId, c] as const));
  const mgr = managerOf(state, npcs);
  const todays: NPC[] = [];
  for (const n of npcs) {
    const close = crewIds.has(n.id) || n.id === mgr?.id || (n.relationshipScore >= 35 && n.role !== 'fan_account') || (isRealId(n.id) && n.relationshipScore >= 50);
    if (!close) continue;
    const nb = npcBirthday(n.id);
    let hit = false;
    for (let k = 0; k < Math.min(days, 3); k++) { const d = serialToDate(serial - k); if (d.month === nb.month && d.day === nb.day) { hit = true; break; } }
    if (!hit || seen.has(`${n.id}|${year}`)) continue;
    todays.push(n);
  }
  todays.sort((a, b) => (crewIds.has(b.id) || b.id === mgr?.id ? 100 : 0) + b.relationshipScore - ((crewIds.has(a.id) || a.id === mgr?.id ? 100 : 0) + a.relationshipScore));
  const list = state.birthdaysSeen ?? (state.birthdaysSeen = []);
  for (const n of todays.slice(0, 2)) {
    list.push(`${n.id}|${year}`);
    const c = crewIds.get(n.id);
    const real = isRealId(n.id);
    const gift = Math.max(50, Math.round(((c ? c.monthlyWage * 0.15 : 60 + n.fame * 8) * Math.max(0.5, costIndex(p.country))) / 10) * 10);
    deliverMoment(state, buildNpcBirthday({ npcId: n.id, name: n.name, role: c?.role ?? n.role, rel: n.relationshipScore, gift, crewId: c?.id, real, serial }), serial);
    // The group remembers its own.
    if (c || n.id === mgr?.id) {
      const other = (state.crew ?? []).find((x) => x.npcId !== n.id);
      if (other) pushTeamLines(state, [{ from: other.npcId, name: other.npcName, role: other.role, text: `Happy birthday @${n.name.split(' ')[0]} 🎂🎉`, key: `bday:${n.id}:${year}` }], serial);
    }
  }
  if (list.length > 300) list.splice(0, list.length - 300);
}

/** The day itself. */
function celebrateBirthday(state: GameState, npcs: NPC[], serial: number, age: number, plan: 'party' | 'dinner' | 'studio' | 'normal', lateBy: number): void {
  const p = state.player!;
  const now = nowMinuteOf(state);
  const fame = blendedFame(p);
  const me = p.artistName.split(' ')[0];
  const b = state.birthday!;
  // The texts: the people who actually think about you.
  const friends = sampleNpcs(npcs, 8, (n) => !isRealId(n.id) && n.relationshipScore >= 28 && n.role !== 'fan_account' && !isBlocked(state, n.id));
  if (!lateBy) friends.forEach((n, i) => scheduleDM(state, n.id, wishLine(`${n.id}|${serial}`, n.relationshipScore >= 60), now + 30 + i * 70 + Math.floor(Math.random() * 60)));
  // The group.
  const voices = [...(state.crew ?? []).map((c) => ({ from: c.npcId, name: c.npcName, role: c.role as string }))];
  const mgr = managerOf(state, npcs);
  if (mgr) voices.unshift({ from: mgr.id, name: mgr.name, role: 'manager' });
  pushTeamLines(state, voices.slice(0, 4).map((v) => ({ ...v, text: teamWish(`${v.from}|${serial}`, v.role) })), serial);
  // The fans.
  if (p.career.fanbase >= 500) {
    const fansPages = sampleNpcs(npcs, fame >= 40 ? 3 : 1, (n) => n.role === 'fan_account' && (n.country === p.country || fame >= 50));
    for (const f of fansPages) npcPost(state, f, fanWish(`${f.id}|${serial}`, p.artistName, age));
  }
  // A star you're close to marks it — an action, never words.
  const star = sampleNpcs(npcs, 1, (n) => isRealId(n.id) && n.role === 'artist' && n.relationshipScore >= 45)[0];
  let starLine = '';
  if (star && Math.random() < 0.5) {
    addMomentum(state, 2, `${star.name} marked your birthday`);
    starLine = ` ${star.name} posted you on their story.`;
  }
  const effects: MomentEffect[] = [];
  let story = '';
  if (plan === 'party') {
    const pool: Guest[] = [];
    for (const c of state.crew ?? []) pool.push({ id: c.npcId, name: c.npcName, rel: 60, fame: 10, real: false, role: c.role, crew: true });
    if (mgr) pool.push({ id: mgr.id, name: mgr.name, rel: mgr.relationshipScore, fame: mgr.fame, real: isRealId(mgr.id), role: 'manager', crew: true });
    for (const n of sampleNpcs(npcs, 14, (x) => x.role !== 'fan_account' && !isBlocked(state, x.id) && (x.role === 'artist' || x.role === 'producer' || x.role === 'dj' || x.role === 'blogger') && x.relationshipScore >= 15 && !(state.crew ?? []).some((c) => c.npcId === x.id))) {
      pool.push({ id: n.id, name: n.name, rel: n.relationshipScore, fame: n.fame, real: isRealId(n.id), role: n.role });
    }
    const night = partyNight({ guests: pool, playerFame: fame, charisma: p.stats.charisma, networking: p.stats.networking, roll: Math.random, me: p.artistName });
    effects.push(...night.effects);
    b.guests = night.came.map((g) => g.id);
    story = night.text;
    if (night.star) state.headlines.unshift({ id: uuidv4(), text: `${night.star.name} spotted at ${p.artistName}'s birthday party`, fullStory: `Photos from ${p.artistName}'s ${age}th birthday show ${night.star.name} in the room. The guest list says a lot about where ${p.artistName} is right now.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id, night.star.id], priority: 6, category: 'general' });
  } else if (plan === 'dinner') {
    for (const c of state.crew ?? []) effects.push({ k: 'morale', crewId: c.id, v: 6 });
    if (mgr) effects.push({ k: 'rel', npcId: mgr.id, v: 4 });
    for (const n of friends.slice(0, 3)) effects.push({ k: 'rel', npcId: n.id, v: 5 });
    effects.push({ k: 'energy', v: 10 });
    story = `Dinner with ${[...(state.crew ?? []).slice(0, 2).map((c) => c.npcName.split(' ')[0]), ...friends.slice(0, 2).map((n) => n.name.split(' ')[0])].join(', ') || 'the people who matter'}. Nobody looked at their phone. Best night in months.`;
  } else if (plan === 'studio') {
    effects.push({ k: 'stat', stat: 'creativity', v: 1 }, { k: 'stat', stat: 'songwriting', v: 0.6 }, { k: 'momentum', v: 1 });
    for (const c of state.crew ?? []) if (workStyleOf(c) === 'grinder') effects.push({ k: 'morale', crewId: c.id, v: 4 });
    story = 'You spent your birthday in the booth. Two ideas you love, one hook you can\'t stop humming. The team noticed.';
  } else {
    story = `Just a normal day. ${friends.length ? `${friends.length} people texted` : 'Quiet'} — that's enough.`;
  }
  // A brand that wants to be your friend.
  if (fame >= 35 && Math.random() < 0.5) effects.push({ k: 'dripGift', from: 'a brand that wants to work with you' });
  applyMomentEffects(state, effects, serial);
  b.story = `${story}${starLine}`;
  pushNotification(state, { kind: 'milestone', title: `🎂 ${lateBy ? `Your birthday — you turned ${age}` : `Happy birthday, ${me} — you're ${age}`}`, body: b.story, artSeed: `bday|${serial}` });
  remember(state, 'life', `Your ${age}th birthday: ${b.story}`, { weight: 3, tone: 'good' });
  state.lastEventLog.unshift(`🎂 ${age} today. ${b.story}`);
  state.lastEventLog = state.lastEventLog.slice(0, 12);
}

// ─── THE BIG NAMES MOVE ────────────────────────────────────────────────────
// Real artists live in this world: they drop records (the release engine does
// that), they announce shows, they sit at #1 — and when you get hot enough,
// they notice you. All of it is reported as what happened. Nobody real ever
// says a word here.

function starPulseTick(state: GameState, npcs: NPC[], serial: number): void {
  const p = state.player;
  if (!p) return;
  const week = Math.floor(serial / 7);
  if (state.starPulseWeek === week) return;
  state.starPulseWeek = week;
  const fame = blendedFame(p);
  const cont = getCountry(p.country)?.continent;
  const reals = npcs.filter((n) => n.role === 'artist' && isRealId(n.id) && (n.country === p.country || (n.fame >= 70 && getCountry(n.country)?.continent === cont) || n.fame >= 90));
  if (!reals.length) return;
  const flags = state.lifeFlags ?? (state.lifeFlags = {});
  const home = reals.filter((n) => n.country === p.country);
  const weighted = (list: NPC[]): NPC | undefined => {
    const total = list.reduce((a, n) => a + n.fame + (n.country === p.country ? 30 : 0), 0);
    let r = Math.random() * total;
    for (const n of list) { r -= n.fame + (n.country === p.country ? 30 : 0); if (r <= 0) return n; }
    return list[0];
  };
  // A show announcement: a big night somebody real is headlining.
  const star = weighted(home.length && Math.random() < 0.75 ? home : reals);
  if (star && Math.random() < 0.6) {
    const cities = SHOW_CITIES.filter((c) => c.country === star.country).sort((a, b) => venuesInCity(b.city, b.country).length - venuesInCity(a.city, a.country).length);
    const city = cities[Math.floor(Math.random() * Math.min(2, cities.length))];
    const room = city ? venuesInCity(city.city, city.country).filter((v) => v.capacity >= 2000).sort((a, b) => b.capacity - a.capacity)[Math.floor(Math.random() * 2)] : undefined;
    if (room) {
      const day = serial + 21 + Math.floor(Math.random() * 40);
      state.headlines.unshift({ id: uuidv4(), text: `${star.name} announces ${room.name}, ${room.city}`, fullStory: `${star.name} will headline ${room.name} in ${room.city} on ${formatGameDate(serialToDate(day))} — ${room.capacity.toLocaleString()} capacity. Tickets are expected to go fast.`, date: formatGameDate(state.gameDate), relatedEntities: [star.id], priority: star.country === p.country ? 5 : 3, category: 'show' });
      if (star.country === p.country) state.lastEventLog.unshift(`🎟️ ${star.name} announced ${room.name}, ${room.city}.`);
    }
  }
  // A home star sitting at #1.
  const top = state.npcSongs.find((x) => x.ownerId && x.ownerCountry === p.country && isRealId(x.ownerId) && x.chartPositions?.[p.country] === 1);
  if (top && flags[`no1:${top.id}`] === undefined) {
    flags[`no1:${top.id}`] = serial;
    state.headlines.unshift({ id: uuidv4(), text: `${top.ownerName}'s "${top.title}" is #1 in ${p.country}`, fullStory: `"${top.title}" has taken the top spot. Everybody else is releasing around it.`, date: formatGameDate(state.gameDate), relatedEntities: [top.ownerId!], priority: 4, category: 'chart' });
  }
  // When you're hot, they notice — a follow, a like. Actions, not words.
  const hot = (p.career.momentum ?? 0) >= 45 || state.songs.some((x) => isSongReleased(x) && (x.chartPositions?.[p.country] ?? 99) <= 10);
  if (hot && Math.random() < 0.45) {
    const watcher = home.filter((n) => flags[`follow:${n.id}`] === undefined && n.fame - fame <= 45).sort((a, b) => b.fame - a.fame)[0];
    if (watcher) {
      flags[`follow:${watcher.id}`] = serial;
      const live = state.npcs.find((x) => x.id === watcher.id);
      if (live) live.relationshipScore = Math.min(100, live.relationshipScore + 5);
      socialStatsOf(state).snapgram.followers += Math.round(200 + watcher.fame * 30);
      addMomentum(state, 2, `${watcher.name} followed you`);
      pushNotification(state, { kind: 'milestone', title: `👀 ${watcher.name} followed you on Snapgram`, body: 'The fan pages noticed before you did.', artSeed: `npc|${watcher.id}`, action: { type: 'artist', id: watcher.id } });
      remember(state, 'people', `${watcher.name} followed you on Snapgram.`, { npcIds: [watcher.id], weight: 3, tone: 'good' });
    }
  }
}

/** Daily: expire, wake follow-ups, and maybe somebody new reaches out. */
function momentsTick(state: GameState, npcs: NPC[], serial: number, days: number): void {
  if (!state.player) return;
  // A verse that came with a deadline: the record is still in the vault and
  // the window has closed.
  for (const r of state.featureRequests) {
    if (r.status !== 'added' || !r.conditions?.some((c) => c.kind === 'release_window' && c.bySerial !== undefined && serial > c.bySerial)) continue;
    if ((r.breaches ?? []).some((b) => b.kind === 'release_window')) continue;
    const song = state.songs.find((x) => x.id === r.songId);
    if (song && !isSongReleased(song)) checkFeatureTerms(state, song.id, false, false, npcs);
  }
  remixAsksTick(state, npcs, serial);
  const list = state.moments ?? (state.moments = []);
  for (const m of list) {
    if (m.status === 'scheduled' && (m.dueSerial ?? 0) <= serial) {
      m.status = 'open';
      m.createdSerial = serial;
      m.expiresSerial = Math.max(m.expiresSerial, serial + 3);
      announceMoment(state, m);
    } else if (m.status === 'open' && m.expiresSerial < serial) {
      const r = expireMoment(m, m.kind === 'feature_breach' || m.kind === 'npc_birthday' || m.kind === 'birthday_plan' ? momentWorld(state, npcs, serial) ?? undefined : undefined, Math.random());
      m.status = 'expired';
      m.resolution = { text: r.text };
      applyMomentEffects(state, r.effects, serial);
      // In the chat: you never answered. Some people follow up.
      if (m.channel === 'dm' && m.npcId && !isRealId(m.npcId)) {
        pushDM(state, m.npcId, { fromPlayer: false, system: true, content: r.text, chips: outcomeChips(r.effects, m.npcName), momentId: m.id });
      }
    }
  }
  const open = list.filter((m) => m.status === 'open');
  const recent = list.slice(0, 8).map((m) => m.kind);
  const fame = blendedFame(state.player);
  let world: MomentWorld | null = null;
  // Nobody knows you yet, so nobody is texting you much. The phone fills up
  // as the name grows.
  const chances: [Moment['channel'], number, number][] = [
    ['dm', 0.03 + fame / 380, fame < 15 ? 1 : fame < 40 ? 2 : 3],
    ['team', 0.07 + state.crew.length * 0.012, 2],
    ['life', 0.11 + fame / 1500, 2],
  ];
  for (const [channel, perDay, cap] of chances) {
    if (open.filter((m) => m.channel === channel).length >= cap) continue;
    if (Math.random() > 1 - Math.pow(1 - perDay, Math.min(days, 10))) continue;
    world = world ?? momentWorld(state, npcs, serial);
    if (!world) return;
    const draft = rollMoment(channel, world, recent, `${serial}|${channel}`, Math.random());
    if (draft) deliverMoment(state, draft, serial);
  }
}

export const useGameStore = create<GameState & GameActions>()(
  immer((set, get) => ({
    ...getInitialState(),

    // ─── NAVIGATION ─────────────────────────────────────────────────────
    setScreen: (screen) =>
      set((state) => {
        state.screen = screen;
      }),

    selectNPC: (npcId) =>
      set((state) => {
        state.selectedNPCId = npcId;
      }),

    openVideo: (videoId) =>
      set((state) => {
        state.selectedVideoId = videoId;
        state.screen = 'watch';
      }),

    openArtist: (artistId) =>
      set((state) => {
        state.selectedArtistId = artistId;
        state.screen = 'artist_page';
      }),

    openChannel: (artistId) =>
      set((state) => {
        state.selectedArtistId = artistId;
        state.screen = 'channel';
      }),

    openPlatform: (platformId) =>
      set((state) => {
        state.selectedPlatformId = platformId;
        state.screen = 'platform';
      }),

    selectSong: (songId) =>
      set((state) => {
        state.selectedSongId = songId;
      }),

    openSong: (songId) =>
      set((state) => {
        state.selectedSongId = songId;
        // Setting the id without moving the screen made every song link in the
        // app a silent no-op. `selectedSongId` is read by SongScreen.
        state.screen = 'song';
      }),

    setPendingFeatureNpc: (npcId) =>
      set((state) => {
        state.pendingFeatureNpcId = npcId;
      }),

    // ─── PLAYER CREATION ────────────────────────────────────────────────
    createPlayer: (data) =>
      set((state) => {
        const baseStats = getBaseStats();
        const stats = applyBackground(baseStats, data.background);
        const career = getStartingCareer(data.background);

        const gameDate = { ...INITIAL_GAME_DATE };
        const age = calculateAge(data.dateOfBirth, gameDate);

        state.player = {
          id: uuidv4(),
          artistName: data.artistName,
          realName: data.realName,
          dateOfBirth: data.dateOfBirth,
          age,
          gender: data.gender,
          genre: data.genre,
          continent: data.continent,
          country: data.country,
          city: data.city,
          background: data.background,
          stats,
          career,
          energy: MAX_ENERGY,
          maxEnergy: MAX_ENERGY,
          createdAt: new Date().toISOString(),
          look: data.look ?? defaultLook(data.gender === 'female' ? 'femme' : 'masc'),
        };

        state.gameDate = gameDate;
        state.initialized = true;
        state.screen = 'dashboard';
        state.cityFame[`${data.country}:${data.city}`] = career.localFame;
        // The football season is already under way: play it up to today.
        ensureFixtures(state);
        // The wardrobe starts with what they walked in wearing; the shop is stocked.
        state.drip = undefined;
        dripOf(state);
        state.memories = [];
        state.memoryCursor = undefined;
        remember(state, 'life', `You started out in ${data.city}, ${data.country}, with $${Math.round(career.money).toLocaleString()} to your name.`, { weight: 5 });

        // ─── THE WORLD WAS ALREADY RUNNING ───────────────────────────────
        // The player does not switch the industry on. Every record already in
        // the catalogue gets a month of real streaming history before the game
        // is handed over, so the platform pages, the charts and the video
        // counters are populated the moment it opens. Without this the whole
        // streaming layer read empty until the player simmed a day, which is
        // the opposite of a world that moves on its own.
        const startSerial = dateToSerial(gameDate);
        const rawRoster = raw(state.npcs) as NPC[];
        const seedStats = clonePlain<Record<string, SongPlatformState>>(
          raw(state.platformStats) ?? {},
        );
        const seedVideos = clonePlain<Video[]>(raw(state.videos) ?? []);
        advanceStreamingDays(state, startSerial - 29, startSerial, rawRoster, seedStats, seedVideos);
        state.platformStats = seedStats;
        state.videos = seedVideos as typeof state.videos;
        state.streamCursor = startSerial;

        // The engine is now the only source of streams, so read its numbers
        // back onto the records the charts and the pages actually read. This is
        // the same read-back `advanceTurn` does; skipping it here is how the
        // regional chart and the record page end up quoting two different
        // lifetimes for the same song.
        for (const song of state.npcSongs as Song[]) {
          const st = state.platformStats?.[song.id];
          if (!st) continue;
          const totals = songTotals(st);
          song.weeklyStreams = totals.week;
          song.totalStreams = totals.lifetime;
          song.peakWeeklyStreams = Math.max(song.peakWeeklyStreams ?? 0, totals.week);
        }

        // Build day-one charts from the NPC scene already in motion, so the
        // player walks into a living industry rather than an empty leaderboard.
        state.charts = updateCharts(
          {},
          [...liveSongs(state.songs), ...state.npcSongs] as Song[],
          state.npcs,
          state.player,
        ) as typeof state.charts;
        state.trending = buildTrending(state.charts as Record<string, ChartEntry[]>, state.player) as typeof state.trending;

        // ─── AND THE FIRST GLOBAL CHART ───────────────────────────────────
        // Published from that seeded month rather than from nothing, so the
        // BillBoard Global Top 100 and Top 200 have a real first week on the
        // board instead of an empty state the player has to sim past. Dated
        // with the Saturday that has actually passed, not the one still to
        // come — a chart published in the future is not a chart.
        publishGlobalCharts(state, rawRoster);

        // Seed the feed with the scene that is already talking.
        const seedPosts: SocialPost[] = [];
        const ghanaToday = state.charts['Ghana'] ?? [];
        seedPosts.push(...fanPosts(ghanaToday[0], undefined, raw(state.npcs) as NPC[], state.player, false) as SocialPost[]);
        for (const npc of pickRandomArtists(raw(state.npcs) as NPC[], 6)) {
          const own = (state.npcSongs as Song[]).filter(s => s.ownerId === npc.id);
          seedPosts.push(...npcArtistPosts(npc, own) as SocialPost[]);
        }
        if (seedPosts.length > 0) state.socialPosts.unshift(...seedPosts);

        // Welcome mail
        state.mailbox.push({
          id: uuidv4(),
          from: 'game_system',
          fromName: 'The Game',
          subject: `Welcome to the rap game, ${data.artistName}`,
          body: `Your journey begins in ${data.city}, ${data.country}. The grind is real. Make music, build relationships, stack money, and one day the world will know your name. Good luck.`,
          timestamp: new Date().toISOString(),
          read: false,
          type: 'general',
        });

        // Everybody starts at home.
        state.home = newHome(data.city, data.country, dateToSerial(state.gameDate));
        state.homes = [];

        // Initial Chirp post
        state.socialPosts.push({
          id: uuidv4(),
          platform: 'chirp',
          authorId: 'player',
          authorName: data.artistName,
          content: `New to the scene. Watch this space. 🎤 #${data.genre.replace('_', '')} #${data.country}`,
          likes: Math.floor(Math.random() * 30) + 5,
          shares: Math.floor(Math.random() * 5),
          comments: [],
          timestamp: new Date().toISOString(),
          isPlayerPost: true,
          trendingScore: 10,
        });
        // Friends, family and the few who heard you once show up for it.
        {
          const first = state.socialPosts[state.socialPosts.length - 1];
          const at = gameMinute(state) - 90;
          first.postedMinute = at;
          first.daySerial = Math.floor(at / MINUTES_PER_DAY);
          first.comments = socialComments(first, 3 + Math.floor(Math.random() * 3), commentContext(state, false, first.id), new Date().toISOString());
          const when = commentMinutes(at, first.comments.length, hashString(first.id) >>> 0);
          first.comments.forEach((c, i) => { c.minute = when[i]; });
          first.target = { likes: first.likes, shares: first.shares, comments: first.comments.length, views: first.likes * 14 };
        }
      }),

    // ─── THE ROOM ───────────────────────────────────────────────────────
    /**
     * Buy the next rung of one slot of the personal studio.
     *
     * Levels REPLACE rather than stack — you own one microphone — so the price
     * is the difference between where the slot is and where it is going, and
     * the bonus after the purchase is the new tier's, not the sum.
     *
     * Refuses in words for every way it can fail: no such slot, already at the
     * top, and not enough money. A silent no-op on a five-figure purchase is
     * the worst possible outcome, so there isn't one.
     */
    buyGear: (slotId) => {
      let result = { ok: false, message: 'Nothing was bought.' };
      set((state) => {
        if (!state.player) return;
        const slot = GEAR_SLOTS.find((s) => s.id === slotId);
        if (!slot) {
          result = { ok: false, message: 'There is no such piece of gear.' };
          return;
        }
        const have = state.studio?.levels?.[slotId] ?? 0;
        const next = nextGearTier(slotId, have);
        if (!next) {
          result = { ok: false, message: `Your ${slot.name.toLowerCase()} is already the best there is.` };
          return;
        }
        // The room has to be able to take it.
        const building = buildingTier(state.studio?.levels);
        if (next.level > building.gearCap) {
          const needs = HOME_STUDIO_TIERS.find((t) => t.gearCap >= next.level);
          result = { ok: false, message: `A ${building.name.toLowerCase()} can't take the ${next.name}. Build a ${needs?.name.toLowerCase() ?? 'bigger room'} first.` };
          return;
        }
        if (state.player.career.money < next.price) {
          result = {
            ok: false,
            message:
              `The ${next.name} is $${next.price.toLocaleString()}. ` +
              `You have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }
        state.player.career.money -= next.price;
        // The migration guarantees `levels`, but a career made before this
        // existed can still arrive with the object and no inner map.
        if (!state.studio) state.studio = { levels: {} };
        if (!state.studio.levels) state.studio.levels = {};
        const before = gearBonus(state.studio.levels);
        state.studio.levels[slotId] = next.level;
        const after = gearBonus(state.studio.levels);
        state.lastEventLog.unshift(
          `🎛️ ${slot.emoji} ${next.name} is in the studio — $${next.price.toLocaleString()}. ` +
            `The room is now +${before} → +${after} production.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        result = { ok: true, message: `${next.name} bought for $${next.price.toLocaleString()}.` };
      });
      return result;
    },

    // ─── STUDIO SESSION ─────────────────────────────────────────────────
    createStudioSong: (payload) => {
      // `set()` cannot return a value, so the result is captured here and
      // handed back to the caller after the state has committed.
      let result: StudioSessionResult | null = null;

      set((state) => {
        if (!state.player) return;

        const title = payload.title.trim();
        if (!title) return;
        // Back in the booth after retiring: that's semi-retirement.
        if (state.legacy.retired) unretire(state, 'semi', 'You went back in the studio. Semi-retired now.');

        const npcs = raw(state.npcs) as NPC[];
        // A beat from the library is already paid for and names its maker.
        const libBeat = payload.libraryBeatId
          ? (state.beats?.library ?? []).find((x) => x.id === payload.libraryBeatId && !x.usedOnSongId)
          : undefined;
        const producerIdUsed = libBeat ? libBeat.producerId ?? null : payload.producerId;
        const producer = producerIdUsed
          ? npcs.find(n => n.id === producerIdUsed) ?? null
          : null;
        const libMember = libBeat ? (state.crew ?? []).find((c) => c.npcId === libBeat.producerId) : undefined;
        const producerSkill = libMember ? libMember.skill : producer ? producerSkillOf(producer) : null;

        // Resolve the chosen beat from that producer's catalogue. If the id no
        // longer matches (roster regenerated, producer changed) fall back to
        // their first beat rather than failing the session.
        const beatOptions = producer
          ? getProducerBeats(producer.id, producerSkill!)
          : getSelfProducedBeats();
        const beat = libBeat
          ? { id: libBeat.id, name: libBeat.name, quality: libBeat.quality }
          : beatOptions.find(b => b.id === payload.beatId) ?? beatOptions[0];

        // A record is tracked solo. Anyone else on it is negotiated later.
        const features: Array<{ npc: NPC; relationship: number }> = [];

        // A hired pen, when the player used one. Their skill is the floor on
        // the lyrics — see `scoreStudioSession`.
        const ghostwriter = payload.ghostwriterId ? ghostwriterById(payload.ghostwriterId) : undefined;

        // Whoever is on the payroll is in the room. Read through the same
        // helper the editor preview uses, so the number on the button and the
        // number on the master can never disagree.
        const crewFx = crewBonuses(raw(state.crew) as CrewMember[]);
        const crewBooth = crewFx.productionBonus;

        // ── THE ROOM ────────────────────────────────────────────────────
        // Where this is being tracked: the player's own gear, or a room they
        // hired for the day. `roomProductionBonus` is the one place the two are
        // compared, and a rented room that beats the player's own studio does
        // NOT stack with it — it replaces it.
        //
        // The room is resolved and gated BEFORE the money is touched, so a
        // session that could never have happened is refused rather than billed.
        const room = roomById(payload.roomId);
        const roomFx = roomProductionBonus(state.studio?.levels, payload.roomId);
        if (room) {
          const lock = roomLockReason(room, blendedFame(state.player));
          if (lock) return;
        }

        // ── THE IN-HOUSE PRODUCER ──────────────────────────────────────
        // Two sides of the same seat, and both have to be real:
        //
        //   · their beats are YOURS. Booking them costs no producer fee at
        //     all, which is the thing the wage is actually buying.
        //   · but if you cut over somebody else's beat while they are on the
        //     payroll, they will take it badly — and it shows in what they
        //     put into the next session, not just in a line in the log.
        //
        // Self-produced beats are neither. That is your own work, not another
        // producer's, so nobody is slighted by it.
        const inHouse = (state.crew ?? []).find((c) => c.role === 'producer');
        const usedInHouse = !!(producer && inHouse && producer.id === inHouse.npcId);
        const cutOverSomeoneElse = !!(inHouse && producer && !usedInHouse);

        const scores = scoreStudioSession({
          stats: state.player.stats,
          lyrics: payload.lyrics,
          genre: payload.genre,
          bpm: payload.bpm,
          mood: payload.mood,
          vocals: payload.vocals,
          producerSkill,
          beatQuality: beat.quality,
          features,
          effort: payload.effort,
          ghostwriterSkill: ghostwriter ? ghostwriter.skill : null,
          crewProductionBonus: crewBooth,
          // The room. Same function the editor preview calls, so the number on
          // the button and the number on the master cannot disagree.
          studioBonus: roomFx.bonus,
        });

        // Session cost: studio time by effort, plus the producer's fee, plus
        // whatever the writer charged, plus the room if one was hired. The
        // effort table lives in sim/studio.ts so the editor, the vault's
        // re-record panel and this all agree.
        //
        // The engineer's session speed scales the studio time, because a
        // shorter session IS the saving — the room is billed by the day.
        const studioTime = Math.round(sessionCost(payload.effort) * crewFx.sessionCost);
        const fee = libBeat ? 0 : producerSkill === null ? 0 : usedInHouse ? 0 : producerFee(producerSkill);
        const roomFee = room?.price ?? 0;
        const cost = studioTime + fee + (ghostwriter?.fee ?? 0) + roomFee;

        // Backstop. The UI explains the shortfall; this prevents a bypass.
        if (state.player.career.money < cost) return;
        // A session is a physical day's work. Out of energy, no session.
        if (!spendEnergy(state, sessionEnergy(payload.effort))) return;

        const daysTotal = Math.max(1, Math.round(sessionDays(payload.effort) * crewFx.sessionSpeed));
        state.player.career.money -= cost;

        // The day the master is actually done. Derived here rather than read off
        // the clock at completion, so a 30-day sim that swallows this session
        // still dates the record on its own sixth day.
        const startSerial = dateToSerial(state.gameDate);
        const doneSerial = startSerial + daysTotal;
        const doneDate = formatGameDate(serialToDate(doneSerial));

        const song: Song = {
          id: uuidv4(),
          title,
          genre: payload.genre,
          quality: scores.quality,
          // A master has no release date yet — it is not out.
          releaseDate: doneDate,
          marketingBudget: 0,
          totalStreams: 0,
          weeklyStreams: 0,
          totalEarnings: 0,
          version: 'original',
          // A take of an existing master carries its lineage from the moment it
          // is built — it does not reach `state.songs` until the days are done,
          // and by then nobody is around to stamp it.
          originalSongId: payload.lineageOf?.songId,
          lineage: payload.lineageOf ? 'rerecord' : undefined,
          takeNumber: payload.lineageOf?.takeNumber,
          featuredArtists: features.map(f => f.npc.id),
          featureArtistNames: features.map(f => f.npc.name),
          chartPositions: {},
          certifications: [],
          hasVideo: false,
          videoViews: 0,

          // ── The session itself ──
          bpm: payload.bpm,
          mood: payload.mood,
          lyrics: payload.lyrics,
          lyricsQuality: scores.lyricsQuality,
          ghostwriterId: ghostwriter?.id,
          ghostwriterName: ghostwriter?.name,
          productionQuality: scores.productionQuality,
          productionCeiling: scores.productionCeiling,
          vocalPerformance: scores.vocalPerformance,
          chemistry: scores.chemistry,
          producerId: producer?.id,
          producerName: producer?.name,
          producerSkill: producerSkill ?? undefined,
          beatId: beat.id,
          beatName: beat.name,
          beatQuality: beat.quality,
          commercialPotential: scores.commercialPotential,
          criticalPotential: scores.criticalPotential,
          recordingCost: cost,
          masterStatus: 'recorded',
          recordingDate: doneDate,
          vocalSettings: { ...payload.vocals },
          // Where it was tracked. A rented room is stamped by name; the
          // player's own studio is stamped as their own, because "your studio"
          // is the answer the player is looking for and the slot levels that
          // made it good can change after the fact.
          roomId: room?.id,
          roomName: room
            ? room.name
            : roomFx.source === 'gear'
              ? 'Your own studio'
              : undefined,
          studioBonus: roomFx.bonus,
        };

        // ── THE SESSION IS BOOKED, NOT FINISHED ────────────────────────
        // The artist goes in the room, the room is paid for and the energy is
        // gone — and then the days have to actually pass. The master is built
        // here, because the performance happened and the score is whatever it
        // is, but it stays in the queue until the last day is behind it. That
        // is what lets the player go and do something else with the afternoon
        // they did not spend in the booth.
        addMomentum(state, 2);

        // Queue the job. Everything the completion needs travels with it: the
        // finished master and how much the session taught you.
        const workId = uuidv4();
        state.workItems.push({
          id: workId,
          kind: 'record',
          label: payload.lineageOf
            ? `Take ${payload.lineageOf.takeNumber} of "${payload.lineageOf.title}"`
            : `Recording "${title}"`,
          detail: `${daysTotal} day${daysTotal > 1 ? 's' : ''} in the room · $${cost.toLocaleString()}`,
          daysTotal,
          daysDone: 0,
          startedSerial: startSerial,
          payload: {
            song,
            growth: payload.effort === 1 ? 0.3 : payload.effort === 2 ? 0.6 : 1.0,
          } satisfies RecordWork,
        });

        const read = describeScore(scores.quality);
        // The line names the room, because WHERE the money went is the whole
        // point of hiring one — a session that quietly cost $9,500 more than
        // the last one has to say why.
        const where = room
          ? ` at ${room.name}`
          : roomFx.source === 'gear'
            ? ' in your own studio'
            : '';
        state.lastEventLog.unshift(
          `🎛️ Booked the room for "${title}"${where} — ${daysTotal} day${daysTotal > 1 ? 's' : ''}, $${cost.toLocaleString()}. The master lands when the days are done.`,
        );

        // ── WHAT THE PRODUCER MADE OF IT ───────────────────────────────
        // The exclusivity mechanic, settled where the decision was actually
        // made. A producer on the payroll who watches you book somebody else
        // is not annoyed in the prose — their morale drops, and morale is a
        // multiplier on everything they contribute from here.
        if (inHouse) {
          const member = (state.crew ?? []).find((c) => c.id === inHouse.id);
          if (member) {
            if (usedInHouse) {
              member.morale = Math.min(100, (member.morale ?? 70) + 6);
              state.lastEventLog.unshift(
                `🎛️ ${inHouse.npcName} was on the desk with you — their beat, no fee, and they are pleased about it.`,
              );
            } else if (cutOverSomeoneElse) {
              member.morale = Math.max(0, (member.morale ?? 70) - 22);
              state.lastEventLog.unshift(
                `🎛️ ${inHouse.npcName} watched you cut over another producer's beat. That is a slight, and it will show in the next session.`,
              );
            }
          }
        }

        // The beat is on a record now.
        if (libBeat) {
          const owned = state.beats?.library.find((x) => x.id === libBeat.id);
          if (owned) { owned.usedOnSongId = song.id; owned.usedOnTitle = title; }
        }

        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          songId: song.id,
          title,
          cost,
          daysSpent: daysTotal,
          scores,
          read,
          grade: gradeLabel(scores.quality),
          splitRead: describeSplit(scores.commercialPotential, scores.criticalPotential),
          chemistryRead: describeChemistry(scores.chemistry),
          producerName: producer?.name ?? null,
          featureNames: features.map(f => f.npc.name),
          inProgress: true,
          workId,
          readyOn: doneDate,
        };
      });

      return result;
    },

    mixMasterSong: (songId, producerId, deal) => {
      let result: MixResult | null = null;

      set((state) => {
        if (!state.player) return;
        // Retired and putting out music: that's semi-retirement now, not a dead button.
        if (state.legacy.retired) unretire(state, 'semi', 'You came out of retirement to put out a record.');

        const song = state.songs.find(s => s.id === songId);
        // Only an unmixed master can be mixed. Re-mixing a finished record is
        // not a thing, and releasing already means it is out of your hands.
        if (!song || song.masterStatus !== 'recorded') return;

        // The record is still `recorded` while it is away being mixed — that is
        // the whole point of the booking — so without this the player could
        // book the same mix four times over, paying four times and having the
        // last one land. Say so rather than silently taking the money.
        if ((state.workItems ?? []).some(w => w.kind === 'mix' && (w.payload as MixWork).songId === songId)) {
          result = {
            ok: false,
            songId,
            producerName: '',
            producerSkill: 0,
            cost: 0,
            daysSpent: 0,
            productionGain: 0,
            qualityBefore: song.quality,
            qualityAfter: song.quality,
            read: `"${song.title}" is already with a producer. One mix at a time — wait for it to come back.`,
          };
          return;
        }

        const producer = (raw(state.npcs) as NPC[]).find(n => n.id === producerId);
        if (!producer) return;

        const onTeam = (state.crew ?? []).find((c) => c.npcId === producer.id);
        const skill = onTeam ? Math.max(onTeam.skill, producerSkillOf(producer)) : producerSkillOf(producer);
        const craft = mixCraft(producer.role, skill);
        // Mixing is charged separately from the beat, at a lower rate — you are
        // buying their ear, not a fresh instrumental. Your own team does it
        // for the wage you already pay; a deal in the DMs is whatever was agreed.
        const cost = deal ? Math.round(deal.fee) : onTeam ? 0 : Math.round(producerFee(skill) * craft.feeMult);
        if (state.player.career.money < cost) return;
        // A mix session is a day in someone else's room (not when it's sent over the wire).
        if (!deal && !spendEnergy(state, ENERGY_COSTS.mixMaster)) return;

        const qualityBefore = song.quality;
        const productionBefore = song.productionQuality ?? 0;
        const ceilingBefore = song.productionCeiling ?? productionBefore;

        state.player.career.money -= cost;

        // What the mix can reach. This is the important part of the model:
        //
        // The recorded material sets a floor on ambition — you cannot mix a
        // rough self-produced loop into a masterpiece. But a genuinely good
        // producer does not merely polish what is there; they re-arrange,
        // replace sounds and re-track. So their skill raises the CEILING, not
        // just how much of a fixed gap they close. That is what makes hiring a
        // real producer the decision that matters.
        const skillCeiling = craft.ceiling;
        const target = Math.max(ceilingBefore, skillCeiling);
        const closingRate = craft.closing;
        const productionAfter = Math.round(Math.max(
          productionBefore,
          Math.min(target, productionBefore + (target - productionBefore) * closingRate),
        ));

        // Nothing is written to the record here. The mix is BOOKED: the ear is
        // hired and the room is paid for, but the record goes on reading as a
        // rough until the days are behind it. That is what stops a mix being a
        // free upgrade you can stack three of in one afternoon. The numbers are
        // worked out once and travel with the job.
        const qualityAfter = applyMoodPenalty(
          blendQuality({
            lyricsQuality: song.lyricsQuality ?? 0,
            productionQuality: productionAfter,
            vocalPerformance: song.vocalPerformance ?? 0,
            chemistry: song.chemistry ?? 0,
          }),
          song.mood ?? 'defiant',
          song.genre,
        );

        // Potentials ride the quality movement. Scaling by the ratio keeps the
        // mood skew (a celebratory record stays commercial-leaning) without
        // re-deriving the whole session.
        const ratio = qualityBefore > 0 ? qualityAfter / qualityBefore : 1;
        const commercialAfter = song.commercialPotential === undefined
          ? undefined
          : Math.max(1, Math.min(100, Math.round(song.commercialPotential * ratio)));
        const criticalAfter = song.criticalPotential === undefined
          ? undefined
          : Math.max(1, Math.min(100, Math.round(song.criticalPotential * ratio)));

        const daysTotal = craft.days;
        const startSerial = dateToSerial(state.gameDate);

        const gain = productionAfter - productionBefore;
        const read = gain >= 25
          ? `${producer.name} rebuilt this from the ground up. It barely resembles the rough.`
          : gain >= 14
          ? `${producer.name} opened the record right up. It sounds like a different song.`
          : gain >= 7
          ? `${producer.name} cleaned it up properly. Noticeably bigger than the rough.`
          : gain >= 3
          ? `${producer.name} tightened what was there. Modest lift.`
          : `${producer.name} did what they could with the material. It was not going to become much more.`;

        const workId = uuidv4();
        state.workItems.push({
          id: workId,
          kind: 'mix',
          label: `Mixing "${song.title}"`,
          detail: `${producer.name} · ${daysTotal} day${daysTotal > 1 ? 's' : ''} · $${cost.toLocaleString()}`,
          daysTotal,
          daysDone: 0,
          startedSerial: startSerial,
          payload: {
            songId: song.id,
            producerId: producer.id,
            producerName: producer.name,
            productionQuality: productionAfter,
            quality: qualityAfter,
            commercialPotential: commercialAfter,
            criticalPotential: criticalAfter,
            gain,
            read,
          } satisfies MixWork,
        });

        state.lastEventLog.unshift(
          `🎚️ ${producer.name} took "${song.title}" away to mix — ${daysTotal} days, $${cost.toLocaleString()}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          songId: song.id,
          producerName: producer.name,
          producerSkill: skill,
          cost,
          daysSpent: daysTotal,
          productionGain: gain,
          qualityBefore,
          qualityAfter,
          read,
          inProgress: true,
          workId,
          readyOn: formatGameDate(serialToDate(startSerial + daysTotal)),
        };
      });

      return result;
    },

    postTeamChat: (text) => {
      let actions: TeamAction[] = [];
      set((state) => {
        const p = state.player;
        const t = text.trim().slice(0, 300);
        if (!p || !t) return;
        const serial = dateToSerial(state.gameDate);
        const list = state.teamChat ?? (state.teamChat = []);
        list.push({ id: uuidv4(), from: 'player', name: p.artistName, role: 'player', text: t, serial, at: new Date().toISOString() });
        if (list.length > 120) list.splice(0, list.length - 120);
        const people = (state.crew ?? []).length + (managerOf(state) ? 1 : 0);
        if (!people) return;
        // With an AI key the team writes its own replies; the chat shows them
        // typing until the answer lands (or the built-in reply takes over).
        if (aiActiveFor('dms')) { state.teamChatPending = { since: Date.now(), text: t }; return; }
        const snap = teamSnapshot(state as GameState, serial);
        // "@Kofi …" is for Kofi: only he answers.
        const tag = /@([\p{L}'-]+)/u.exec(t)?.[1]?.toLowerCase();
        const only = tag ? teamMembers(state as GameState).find((m) => m.name.split(' ')[0].toLowerCase() === tag)?.id : undefined;
        let lines = teamReply(state as GameState, snap, t, only);
        if (only && !lines.length) {
          const m = teamMembers(state as GameState).find((x) => x.id === only)!;
          lines = [{ from: m.id, name: m.name, role: m.role, text: pickLine(['Yes boss?', 'I\'m here — what do you need?', 'Talk to me.'], `${serial}|${t.length}`) }];
        }
        pushTeamLines(state, lines, serial);
        actions = teamActions(state as GameState, snap, t, only);
      });
      if (actions.length) runTeamActions(actions);
    },

    applyAITeamChat: (payload) => {
      let actions: TeamAction[] = [];
      set((state) => {
        const pending = state.teamChatPending;
        if (!pending || !state.player) return;
        state.teamChatPending = undefined;
        const serial = dateToSerial(state.gameDate);
        const mgr = managerOf(state);
        const who = (id: string) => {
          const c = (state.crew ?? []).find((x) => x.npcId === id);
          if (c) return { from: c.npcId, name: c.npcName, role: c.role as string };
          if (mgr && mgr.id === id) return { from: mgr.id, name: mgr.name, role: 'manager' };
          return null;
        };
        const said = (state.teamChat ?? []).filter((m) => m.from !== 'player').slice(-8);
        const lines: TeamLine[] = [];
        for (const r of payload.replies.slice(0, 4)) {
          const w = who(r.from);
          const text = (r.text ?? '').trim().slice(0, 500);
          if (!w || !text || said.some((m) => nearDuplicate(m.text, text))) continue;
          lines.push({ ...w, text });
        }
        if (!lines.length) {
          // The AI said nothing usable: the built-in team answers.
          const snap = teamSnapshot(state as GameState, serial);
          pushTeamLines(state, teamReply(state as GameState, snap, pending.text), serial);
          actions = teamActions(state as GameState, snap, pending.text);
          return;
        }
        pushTeamLines(state, lines, serial);
        const ok: TeamAction['kind'][] = ['make_beat', 'mix_song', 'push_shows', 'push_features', 'push_deals'];
        for (const a of payload.actions ?? []) {
          if (!ok.includes(a.kind as TeamAction['kind']) || !who(a.from)) continue;
          const song = a.song ? state.songs.find((x) => !isSongReleased(x) && x.title.toLowerCase() === String(a.song).toLowerCase()) : undefined;
          const role = who(a.from)!.role;
          // Only the person whose job it is can do it.
          if (a.kind === 'make_beat' && role !== 'producer') continue;
          if (a.kind === 'mix_song' && role !== 'engineer' && role !== 'producer') continue;
          if (a.kind.startsWith('push') && role !== 'manager') continue;
          const mixTarget = a.kind === 'mix_song' ? (song ?? state.songs.find((x) => isVaultMaster(x) && x.masterStatus === 'recorded')) : song;
          if (a.kind === 'mix_song' && !mixTarget) continue;
          actions.push({ kind: a.kind as TeamAction['kind'], from: a.from, songId: mixTarget?.id });
        }
      });
      if (actions.length) runTeamActions(actions);
    },

    fallbackTeamChat: () => {
      let actions: TeamAction[] = [];
      set((state) => {
        const pending = state.teamChatPending;
        if (!pending || !state.player) return;
        state.teamChatPending = undefined;
        const serial = dateToSerial(state.gameDate);
        const snap = teamSnapshot(state as GameState, serial);
        pushTeamLines(state, teamReply(state as GameState, snap, pending.text), serial);
        actions = teamActions(state as GameState, snap, pending.text);
      });
      if (actions.length) runTeamActions(actions);
    },

    applyAITeamChatter: (lines) =>
      set((state) => {
        if (!state.player) return;
        const serial = dateToSerial(state.gameDate);
        const mgr = managerOf(state);
        const said = (state.teamChat ?? []).filter((m) => m.from !== 'player').slice(-10);
        const out: TeamLine[] = [];
        for (const l of lines.slice(0, 3)) {
          const c = (state.crew ?? []).find((x) => x.npcId === l.from);
          const w = c ? { from: c.npcId, name: c.npcName, role: c.role as string } : mgr && mgr.id === l.from ? { from: mgr.id, name: mgr.name, role: 'manager' } : null;
          const text = (l.text ?? '').trim().slice(0, 400);
          if (!w || !text || said.some((m) => nearDuplicate(m.text, text))) continue;
          out.push({ ...w, text });
        }
        pushTeamLines(state, out, serial);
      }),

    noteTeam: (from, text) =>
      set((state) => {
        const serial = dateToSerial(state.gameDate);
        const mgr = managerOf(state);
        const c = (state.crew ?? []).find((x) => x.npcId === from);
        const w = c ? { from: c.npcId, name: c.npcName, role: c.role as string } : mgr && mgr.id === from ? { from: mgr.id, name: mgr.name, role: 'manager' } : null;
        if (w) pushTeamLines(state, [{ ...w, text }], serial);
      }),

    readTeamChat: () =>
      set((state) => { state.teamChatUnread = 0; }),

    // ─── SEND A RECORD TO SOMEONE WHO MIXES ─────────────────────────────
    askToMix: (npcId, songId) => {
      let result: FeatureActionResult = { ok: false, message: 'They are not taking that.' };
      let book: { fee: number } | null = null;
      set((state) => {
        const p = state.player;
        const npc = state.npcs.find((n) => n.id === npcId);
        const song = state.songs.find((x) => x.id === songId);
        if (!p || !npc || !song || isBlocked(state, npcId)) return;
        const thread = state.dmThreads[npcId] ?? (state.dmThreads[npcId] = { npcId, messages: [], unread: 0 });
        const mk = (content: string, fromPlayer = false, extra: Partial<DMMessage> = {}) => thread.messages.push({ id: uuidv4(), npcId, fromPlayer, content, timestamp: new Date().toISOString(), read: fromPlayer, ...extra });
        const crew = (state.crew ?? []).find((c) => c.npcId === npcId);
        const first = npc.name.split(' ')[0];
        const eng = npc.role === 'engineer';
        mk(`Yo ${first} — sending you "${song.title}". Can you ${eng ? 'mix and master' : 'mix'} it for me?`, true, { attachedSongId: song.id, attachedTitle: song.title });
        if (isRealId(npc.id)) { mk(`📨 ${first}'s manager: Thanks for sending it. ${first} doesn't mix other people's records — but we'll keep you in mind.`); thread.unread += 1; result = { ok: false, message: 'They don\'t take outside mixes.' }; return; }
        if (song.masterStatus !== 'recorded') { mk(pick3(['That one\'s already out, I can only work on records that haven\'t dropped. Send me the next one.', 'It\'s already released — nothing to mix. What\'s the next record?'], song.id)); thread.unread += 1; result = { ok: false, message: 'Only a record that isn\'t out yet can be mixed.' }; return; }
        if ((state.workItems ?? []).some((w) => w.kind === 'mix' && (w.payload as MixWork).songId === songId)) { mk('I\'ve already got that one on my desk 😅'); thread.unread += 1; result = { ok: false, message: 'That record is already being mixed.' }; return; }
        if (thread.mixOffer) { mk('Let\'s finish the one we\'re talking about first.'); thread.unread += 1; return; }
        const persona = personaOf(npc);
        const skill = crew ? Math.max(crew.skill, producerSkillOf(npc as NPC)) : producerSkillOf(npc as NPC);
        const d = decideMix({ role: npc.role, skill, fame: npc.fame, rel: npc.relationshipScore, songQuality: song.quality, playerFame: blendedFame(p), generous: persona.warmth > 0.65, roll: Math.random() });
        const craft = mixCraft(npc.role, skill);
        if (crew && d.outcome !== 'declined') {
          // On your team: it's what you pay them for.
          mk(pick3([`On it. You'll have it back in ${craft.days} days.`, `Say less — I'll work on it now.`], song.id + 'c'));
          book = { fee: 0 };
        } else if (d.outcome === 'declined') {
          mk(d.why === 'bigger' ? pick3(['Appreciate you sending it, but my books are full. Maybe when we know each other better.', 'I don\'t take outside mixes right now. Respect for the hustle though.'], song.id)
            : d.why === 'rough' ? pick3(['Honestly it needs more work before it\'s ready for a mix — re-record the vocals and send it back.', 'It\'s not there yet. Tighten the record first, then I\'ll mix it.'], song.id)
            : pick3(['Slammed this week, can\'t take it. Try me later.', 'Not this week bro, sorry 🙏🏾'], song.id));
          npc.relationshipScore = Math.max(-100, npc.relationshipScore + (d.why === 'rough' ? 0 : -1));
          result = { ok: false, message: `${first} passed.` };
        } else if (d.outcome === 'free') {
          mk(pick3([`I like this one. Free — you don't owe me anything. Back in ${craft.days} days 🔥`, `For you? No charge. I'll get on it now.`, `Say less. On the house, I want to hear it finished 🙏🏾`], song.id));
          npc.relationshipScore = Math.min(100, npc.relationshipScore + 3);
          book = { fee: 0 };
        } else {
          thread.mixOffer = { songId, songTitle: song.title, fee: d.fee, days: craft.days };
          mk(pick3([`I'm down. $${d.fee.toLocaleString()} and it's back to you in ${craft.days} days.`, `Love the record. My rate is $${d.fee.toLocaleString()} for the ${eng ? 'mix and master' : 'mix'}, ${craft.days} days.`, `$${d.fee.toLocaleString()}. I'll do it properly — ${craft.days} days.`], song.id));
          result = { ok: true, message: `${first} quoted $${d.fee.toLocaleString()}.` };
        }
        thread.unread += 1;
        npc.memoryLog = [...npc.memoryLog.slice(-9), `[Mix] You sent "${song.title}" to be mixed.`];
      });
      const b = book as { fee: number } | null;
      if (b) {
        const r = get().mixMasterSong(songId, npcId, { fee: b.fee });
        result = r ? { ok: true, message: r.read } : { ok: false, message: 'Could not book that mix.' };
      }
      return result;
    },

    answerMixOffer: (npcId, accept) => {
      let result: FeatureActionResult = { ok: false, message: 'That offer has gone.' };
      const offer = get().dmThreads[npcId]?.mixOffer;
      if (!offer) return result;
      if (accept) {
        const money = get().player?.career.money ?? 0;
        if (money < offer.fee) return { ok: false, message: `You need $${offer.fee.toLocaleString()} for that.` };
        const r = get().mixMasterSong(offer.songId, npcId, { fee: offer.fee });
        set((state) => {
          const t = state.dmThreads[npcId];
          if (!t) return;
          t.mixOffer = undefined;
          t.messages.push({ id: uuidv4(), npcId, fromPlayer: true, content: pick3(['Deal. Let\'s do it.', 'Bet, go ahead.', 'Locked in 🤝🏾'], offer.songId), timestamp: new Date().toISOString(), read: true });
          t.messages.push({ id: uuidv4(), npcId, fromPlayer: false, content: r ? pick3(['Got it. I\'ll send it back when it\'s done.', 'Cool, starting now.'], offer.songId + 'a') : 'Something\'s off with that record, send it again?', timestamp: new Date().toISOString(), read: false });
          t.unread += 1;
        });
        result = r ? { ok: true, message: `Booked. Back in ${offer.days} days.` } : { ok: false, message: 'That mix could not be booked.' };
      } else {
        set((state) => {
          const t = state.dmThreads[npcId];
          if (!t) return;
          t.mixOffer = undefined;
          t.messages.push({ id: uuidv4(), npcId, fromPlayer: true, content: pick3(['That\'s too much for me right now, thanks.', 'Let me think about it.'], offer.songId + 'd'), timestamp: new Date().toISOString(), read: true });
          t.messages.push({ id: uuidv4(), npcId, fromPlayer: false, content: pick3(['No stress. The offer\'s there if you change your mind.', 'All good 🙏🏾'], offer.songId + 'e'), timestamp: new Date().toISOString(), read: false });
          t.unread += 1;
        });
        result = { ok: true, message: 'Passed on the mix.' };
      }
      return result;
    },

    releaseMaster: (songId, marketingBudget, platformIds, withVideos) =>
      set((state) => {
        if (!state.player) return;
        // Retired and putting out music: that's semi-retirement now, not a dead button.
        if (state.legacy.retired) unretire(state, 'semi', 'You came out of retirement to put out a record.');

        const song = state.songs.find(s => s.id === songId);
        if (!song || song.masterStatus === 'released') return;
        // The comeback single: everybody was waiting for this one.
        const cb = state.legacy.comeback;
        if (cb && !cb.used && dateToSerial(state.gameDate) <= cb.until) {
          cb.used = true;
          addMomentum(state, Math.round(cb.hype * 0.6));
          state.player.career.fanbase += Math.round(state.player.career.fanbase * cb.hype / 400);
          state.player.career.nationalFame = Math.min(100, state.player.career.nationalFame + cb.hype / 12);
          state.headlines.unshift({ id: uuidv4(), text: `${state.player.artistName} is back with "${song.title}"`, fullStory: 'The comeback is real. Fans who waited are running it up.', date: formatGameDate(state.gameDate), relatedEntities: [state.player.id], priority: 6, category: 'general' });
          remember(state, 'career', `Your comeback single "${song.title}" dropped.`, { weight: 4, tone: 'good' });
        }

        // A record has to go somewhere. An empty delivery list is a mistake,
        // not a choice — refuse it rather than releasing to nobody.
        const delivered = platformIds?.filter((id) => PLATFORM_BY_ID[id]);
        if (platformIds && delivered && delivered.length === 0) return;

        if (state.player.career.money < marketingBudget) return;
        // Release day is a long day — uploads, press, rollout.
        if (!spendEnergy(state, ENERGY_COSTS.release, { admin: true })) return;

        state.player.career.money -= marketingBudget;
        song.marketingBudget = marketingBudget;
        song.masterStatus = 'released';
        song.releaseDate = formatGameDate(state.gameDate);
        song.weeksOut = 0;
        // Every guest's terms are checked the day it comes out.
        checkFeatureTerms(state, song.id, false, true);
        rollBreakout(state, [song]);
        {
          // Your fans turn up on release day — more if you hyped them first.
          const club = fanClubOf(state);
          const lift = (club.hype + (club.preHype ?? 0)) / 300;
          if (lift >= 0.1) pushSong(state, song.id, lift, 10, club.preHype ? 'Your superfans were waiting for it' : 'Your fans turned up on release day');
          club.preHype = 0;
          club.hype = Math.min(100, club.hype + 12);
          club.loyalty = Math.min(100, club.loyalty + 1);
          // Somebody at your level dropped the same week: the fans want a winner.
          const fame0 = blendedFame(state.player);
          const idx0 = npcIndex(baseNpcs(state));
          const clash = state.npcSongs.find((x) => (x.weeksOut ?? 9) === 0 && x.ownerId && x.ownerCountry === state.player!.country && (() => { const n = idx0.get(x.ownerId!); return !!n && n.role === 'artist' && Math.abs(n.fame - fame0) <= 15 && n.relationshipScore < 30; })());
          if (clash && Math.random() < 0.6) {
            const rival = idx0.get(clash.ownerId!)!;
            sparkFanWar(state, rival, `${rival.name} dropped "${clash.title}" the same week as your "${song.title}". The timeline wants a winner.`, dateToSerial(state.gameDate), 30);
          }
        }
        // `undefined` means everywhere, which is what an untouched release
        // dialog means. An explicit list is what the engine reads to decide
        // where this record can actually be heard.
        song.platformIds = delivered && delivered.length < PLATFORM_LIST.length
          ? [...delivered]
          : undefined;
        // A record enters the world with a first week of movement — and heat
        // opens doors. The same record arriving while people are already
        // watching you does a bigger first week than it would in a quiet month.
        // This is the first thing momentum is actually for.
        const releaseHeat = 1 + state.player.career.momentum / 200;
        song.weeklyStreams = Math.max(
          50,
          Math.round((song.quality * 12 + marketingBudget * 0.4) * releaseHeat),
        );

        // The first week is scaled by the share of the world the record was
        // actually delivered to. Otherwise a SoundCloud-only release would open
        // with the same first-week figure as a full global rollout.
        if (song.platformIds) {
          const weights = platformWeights(
            {
              quality: song.quality,
              genre: song.genre,
              homeCountry: state.player.country,
              artistPopularity: blendedFame(state.player),
              fanbase: state.player.career.fanbase,
              marketing: marketingPush(marketingBudget),
              videoViews: 0,
              isNpc: false,
              weeksOut: 0,
            },
            0,
          );
          song.weeklyStreams = Math.max(
            20,
            Math.round(song.weeklyStreams * platformReach(song.platformIds, weights)),
          );
        }

        // ── A REMIX IS A SECOND WIND, FOR BOTH RECORDS ───────────────────
        //
        // This is the whole reason an artist remixes a record instead of
        // leaving it alone, and it is deliberately NOT a guaranteed boost.
        //
        // Two things happen. The original gets pulled back onto playlists for a
        // window, and the remix opens with the audience the original already
        // built. Both are driven off the original's REAL units and its age, so
        // a remix of a song nobody heard does neither — it inherits a small
        // number and stays small, which is the honest outcome.
        if (song.lineage === 'remix' && song.originalSongId) {
          const original = state.songs.find((s) => s.id === song.originalSongId);
          const originalState = state.platformStats?.[song.originalSongId];
          if (original && originalState) {
            const nowSerial = dateToSerial(state.gameDate);
            const { power, width, reason } = revivalFor(state, original, song);

            // The original's second wind, planted at the age it is today.
            plantRevival(
              state,
              original.id,
              { power, width, reason },
              nowSerial - originalState.release,
            );

            // The remix's own opening. Its state does not exist yet — the
            // streaming engine creates it on the next tick — so the carry-over
            // is recorded on the record itself, which is also what gets saved.
            const carry = {
              at: 0,
              power: power * 0.8,
              width,
              reason: 'carried over from the original',
            };
            song.revivals = [...(song.revivals ?? []), carry];
            if (!state.platformStats) state.platformStats = {};
            if (!state.platformStats[song.id]) {
              const fresh = newSongPlatformState(song.id, nowSerial, 0);
              fresh.revivals = [{ ...carry }];
              state.platformStats[song.id] = fresh;
            }
          }
        }

        addMomentum(state, 5, 'you put a record out');

        const { post: releasePost } = playerReleaseReactions(song, state.player, raw(state.npcs) as NPC[]);
        state.socialPosts.unshift(releasePost as SocialPost);
        // Everybody on the record posts about it, on every app.
        featureCrossPosts(state, song, dateToSerial(state.gameDate));

        state.headlines.unshift({
          id: uuidv4(),
          text: generateHeadline('release', state.player.artistName, song.title),
          fullStory:
            `${state.player.artistName} just dropped "${song.title}", a new ${song.genre.replace('_', '-')} record` +
            `${song.producerName ? ` produced by ${song.producerName}` : ''}. The internet is reacting.`,
          date: formatGameDate(state.gameDate),
          relatedEntities: [state.player.id],
          priority: 5,
          category: 'chart',
        });

        // Videos shot while it was in the vault: up with the record, or held for later.
        const held = (state.videos ?? []).filter((v) => v.isPlayer && v.songId === song.id && v.awaitingRelease && !v.removed);
        let videoUp = 0;
        for (const v of held) {
          v.awaitingRelease = false;
          if (withVideos && !withVideos.includes(v.id)) continue; // later, from Videos
          v.status = 'published';
          v.published = true;
          v.uploadSerial = dateToSerial(state.gameDate);
          v.uploadDate = formatGameDate(state.gameDate);
          song.hasVideo = true;
          videoUp++;
        }
        if (videoUp) state.lastEventLog.unshift(`🎬 The video for "${song.title}" went up with the record.`);
        state.lastEventLog.unshift(`🚀 "${song.title}" is out. Streams start next week.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      }),

    // ─── ALBUM / EP ASSEMBLY ────────────────────────────────────────────
    //
    // An album is not a new thing the game invents — it is a real bundle of
    // records that already exist. Its units are derived live from the tracks'
    // own streaming state (see `buildAlbumChart`), so putting a single on a
    // project genuinely carries its audience over, and a project of flops
    // charts like a project of flops.
    createAlbum: (data) => {
      let result: { ok: true; albumId: string } | { ok: false; error: string } = {
        ok: false,
        error: 'Something went wrong.',
      };

      set((state) => {
        if (!state.player) {
          result = { ok: false, error: 'No artist loaded.' };
          return;
        }

        const title = data.title.trim();
        if (!title) {
          result = { ok: false, error: 'Give the project a title.' };
          return;
        }
        if (data.songIds.length < MIN_PROJECT_TRACKS[data.type]) {
          result = { ok: false, error: PROJECT_TRACK_RULE[data.type] };
          return;
        }

        // Any of your own masters, released or still in the vault, and nothing
        // already on one of your projects. A song cannot be on two albums and
        // count twice.
        //
        // Unreleased tracks are allowed on purpose. In real life the tracklist
        // is decided before anybody hears it, and finishing the album is how
        // its songs come out — so putting one here is what releases it.
        const mine = new Map(state.songs.map((s) => [s.id, s]));
        const alreadyUsed = new Set<string>();
        for (const a of state.albums) {
          if ((a.ownerId ?? state.player.id) !== state.player.id) continue;
          for (const id of a.songs) alreadyUsed.add(id);
        }

        const tracks: Song[] = [];
        for (const id of data.songIds) {
          const song = mine.get(id);
          if (!song) {
            result = { ok: false, error: 'That track is not in your vault.' };
            return;
          }
          if (alreadyUsed.has(id)) {
            result = { ok: false, error: `"${song.title}" is already on one of your projects.` };
            return;
          }
          tracks.push(song as Song);
        }

        // Anything on this tracklist that was not out yet comes out with the
        // project. Done before the album record is written, so the album and
        // its tracks agree about what is live from the same instant.
        for (const t of tracks) {
          if (!isReleased(t)) releaseAsProjectTrack(state, t);
        }
        rollBreakout(state, tracks as Song[], 'album');

        const index = state.albums.filter((a) => (a.ownerId ?? state.player!.id) === state.player!.id).length;
        const albumId = `alb_player_${state.player.id.slice(0, 8)}_${index}`;
        const serial = dateToSerial(state.gameDate);

        state.albums.push({
          id: albumId,
          title,
          songs: tracks.map((t) => t.id),
          releaseDate: formatGameDate(state.gameDate),
          totalStreams: 0,
          totalEarnings: 0,
          certifications: [],
          ownerId: state.player.id,
          ownerName: state.player.artistName,
          ownerCountry: state.player.country,
          type: data.type,
          coverSeed: hashString(`rl-cover|${state.player.id}|${index}`),
          releaseSerial: serial,
        } as typeof state.albums[number]);

        state.headlines.unshift({
          id: uuidv4(),
          text: generateHeadline('release', state.player.artistName, title),
          fullStory:
            `${state.player.artistName} has released ${title}, a ${data.type === 'album' ? 'full-length album' : 'EP'} ` +
            `of ${tracks.length} tracks. It is on the charts from this week.`,
          date: formatGameDate(state.gameDate),
          relatedEntities: [state.player.id],
          priority: 7,
          category: 'chart',
        });

        state.lastEventLog.unshift(
          `💿 "${title}" — ${tracks.length}-track ${data.type === 'album' ? 'album' : 'EP'} is out.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = { ok: true, albumId };
      });

      return result;
    },

    scrapMaster: (songId) =>
      set((state) => {
        if (!state.player) return;
        const idx = state.songs.findIndex(s => s.id === songId);
        if (idx === -1) return;
        const song = state.songs[idx];
        if (song.masterStatus === 'released') return; // you cannot un-release

        // Studio time is spent, but the beat can be reused — small refund.
        const refund = Math.round((song.recordingCost ?? 0) * 0.15);
        state.player.career.money += refund;
        state.songs.splice(idx, 1);

        state.lastEventLog.unshift(`🗑️ Scrapped "${song.title}". Recovered $${refund.toLocaleString()}.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      }),

    updateMasterLyrics: (songId, lyrics) => {
      let result: VaultActionResult = {
        ok: false,
        message: 'That master is not in the vault.',
      };
      set((state) => {
        const song = state.songs.find(s => s.id === songId);
        if (!song) return;
        if (isReleased(song)) {
          result = {
            ok: false,
            message: 'That record is out. Rewriting the sheet now would change a song people already know — cut a remix instead.',
          };
          return;
        }
        const before = song.quality;
        song.lyrics = lyrics;
        // Rewriting the sheet after tracking is a different thing to writing it
        // in the booth, but it still moves the lyric read.
        const analysis = analyzeLyrics(lyrics);
        const stats = state.player?.stats;
        if (stats) {
          const writerSkill =
            stats.lyricism * 0.42 + stats.songwriting * 0.36 +
            stats.creativity * 0.14 + stats.originality * 0.08;
          song.lyricsQuality = Math.max(1, Math.min(100, Math.round(
            writerSkill * (0.45 + analysis.depth / 100 * 0.55) + analysis.depth * 0.18,
          )));
          song.quality = applyMoodPenalty(
            blendQuality({
              lyricsQuality: song.lyricsQuality,
              productionQuality: song.productionQuality ?? 0,
              vocalPerformance: song.vocalPerformance ?? 0,
              chemistry: song.chemistry ?? 0,
            }),
            song.mood ?? 'defiant',
            song.genre,
          );
        }
        const after = song.quality;
        // New words invalidate a mix. The production did not change, but the
        // record it was mixed around did, so it goes back to a rough master.
        // `mixed` is the legacy value for the same state — a save written
        // before `mastered` existed still has to be handled.
        if (song.masterStatus === 'mastered' || song.masterStatus === 'mixed') {
          song.masterStatus = 'recorded';
        }
        song.readyToRelease = false;
        result = {
          ok: true,
          message:
            after === before
              ? `Rewritten. "${song.title}" still reads ${gradeLabel(after)}.`
              : `Rewritten. "${song.title}" went ${gradeLabel(before)} → ${gradeLabel(after)}.`,
          qualityBefore: before,
          qualityAfter: after,
        };
      });
      return result;
    },

    // ─── STUDIO VAULT ───────────────────────────────────────────────────
    //
    // The vault is every master that is yours and not out yet. Everything here
    // refuses a released record: once a song is in the world it is out of your
    // hands, and the way to change it is a remix (see `createRemix`).

    archiveSong: (songId) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not in the vault.' };
      set((state) => {
        const song = state.songs.find((s) => s.id === songId);
        if (!song) return;
        if (isReleased(song)) {
          result = { ok: false, message: 'That record is already out. You cannot archive something the world already has.' };
          return;
        }
        if (song.archivedAt) {
          result = { ok: false, message: `"${song.title}" is already archived.` };
          return;
        }
        song.archivedAt = formatGameDate(state.gameDate);
        // An archived master is not waiting on anything any more.
        song.readyToRelease = false;
        result = { ok: true, message: `Archived "${song.title}". It is still here if you want it back.` };
        state.lastEventLog.unshift(`📦 Archived "${song.title}".`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });
      return result;
    },

    unarchiveSong: (songId) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not archived.' };
      set((state) => {
        const song = state.songs.find((s) => s.id === songId);
        if (!song || !song.archivedAt) return;
        song.archivedAt = undefined;
        result = { ok: true, message: `"${song.title}" is back in the vault.` };
      });
      return result;
    },

    // ─── EDIT: RETITLE IT ───────────────────────────────────────────────
    //
    // This action replaced `addFeatureToSong`, which put a guest on a record
    // in a single click. That is what made the reported bug possible: the
    // player asked an artist for a verse and the verse simply appeared, with
    // no fee, no wait and no conversation, because the whole thing was one
    // hidden dice roll behind a button. Putting a feature on a record now goes
    // through `sendFeatureRequest` and comes back days later like everything
    // else in this business.
    renameSong: (songId, rawTitle) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not in the vault.' };
      const title = rawTitle.trim().replace(/\s+/g, ' ');

      if (!title) {
        return { ok: false, message: 'A record needs a name. Type something first.' };
      }
      if (title.length > 60) {
        return { ok: false, message: 'That is a paragraph, not a title. Keep it under 60 characters.' };
      }

      set((state) => {
        const song = state.songs.find((s) => s.id === songId);
        if (!song) return;

        if (isReleased(song)) {
          result = {
            ok: false,
            message: `"${song.title}" is already out. The charts, the streams and other people's catalogues are all holding that name — renaming it now would be a lie.`,
          };
          return;
        }

        const before = song.title;
        if (before === title) {
          result = { ok: false, message: 'It is already called that.' };
          return;
        }

        song.title = title;

        // Anything that quoted the old name has to move with it, or the
        // vault, the feature letters and the DMs start describing a record
        // that no longer exists under that name.
        for (const req of state.featureRequests) {
          if (req.songId === songId) req.songTitle = title;
        }
        for (const thread of Object.values(state.dmThreads)) {
          for (const m of thread.messages) {
            if (m.attachedSongId === songId) m.attachedTitle = title;
          }
        }

        result = { ok: true, message: `"${before}" is now "${title}".` };
        state.lastEventLog.unshift(`✏️ Retitled "${before}" to "${title}".`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });

      return result;
    },


    // ─── DELETE ─────────────────────────────────────────────────────────
    deleteSong: (songId) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not in the vault.' };
      const state = get();
      const song = state.songs.find((s) => s.id === songId);
      if (!song) return result;

      if (isReleased(song)) {
        return {
          ok: false,
          message: `"${song.title}" is out in the world. You cannot delete a record people have heard — archive it instead.`,
        };
      }

      const title = song.title;

      set((s) => {
        s.songs = s.songs.filter((x) => x.id !== songId);
        // Everything that pointed at the record has to go with it, or the world
        // is left holding a reference to something that no longer exists — and
        // the chart and streaming code both assume those ids resolve.
        if (s.platformStats) delete s.platformStats[songId];
        for (const album of s.albums) {
          album.songs = album.songs.filter((id) => id !== songId);
        }
        if (s.chartRuns) {
          delete s.chartRuns[`songs|${songId}`];
          delete s.chartRuns[`albums|${songId}`];
        }
        if (s.chartMilestones) {
          s.chartMilestones = s.chartMilestones.filter((m) => m.itemId !== songId);
        }
        if (s.videos) {
          s.videos = s.videos.filter((v) => v.songId !== songId);
        }
        s.lastEventLog.unshift(`🗑️ "${title}" was deleted off the hard drive.`);
        s.lastEventLog = s.lastEventLog.slice(0, 10);
      });

      result = { ok: true, message: `"${title}" is gone. Nothing of it is left.` };
      return result;
    },

    setReadyToRelease: (songId, ready) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not in the vault.' };
      set((state) => {
        const song = state.songs.find((s) => s.id === songId);
        if (!song) return;
        if (isReleased(song)) {
          result = { ok: false, message: 'That record is already out.' };
          return;
        }
        if (song.archivedAt) {
          result = { ok: false, message: `"${song.title}" is archived. Bring it back first.` };
          return;
        }
        song.readyToRelease = ready;
        result = {
          ok: true,
          message: ready
            ? `"${song.title}" is marked ready to release.`
            : `"${song.title}" is back on the bench.`,
        };
      });
      return result;
    },

    setVaultNote: (songId, note) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not in the vault.' };
      set((state) => {
        const song = state.songs.find((s) => s.id === songId);
        if (!song) return;
        song.vaultNote = note.slice(0, 280);
        result = { ok: true, message: 'Note saved.' };
      });
      return result;
    },

    swapProduction: (songId, producerId, beatId) => {
      let result: VaultActionResult = { ok: false, message: 'That master is not in the vault.' };
      set((state) => {
        if (!state.player) return;
        const song = state.songs.find((s) => s.id === songId);
        if (!song) return;
        if (isReleased(song)) {
          result = {
            ok: false,
            message: 'That record is already out — you cannot re-produce it. Cut a remix instead.',
          };
          return;
        }

        const npcs = raw(state.npcs) as NPC[];
        const producer = producerId ? npcs.find((n) => n.id === producerId) ?? null : null;
        const skill = producer ? producerSkillOf(producer) : null;
        const beats = producer ? getProducerBeats(producer.id, skill!) : getSelfProducedBeats();
        const beat = beats.find((b) => b.id === beatId) ?? beats[0];
        if (!beat) {
          result = { ok: false, message: 'That producer has no beats to pick from.' };
          return;
        }

        // Re-tracking is a session, not a free edit.
        const cost = 450 + (skill === null ? 0 : producerFee(skill));
        if (state.player.career.money < cost) {
          result = {
            ok: false,
            message: `That session costs $${cost.toLocaleString()} and you have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }
        if (!spendEnergy(state, ENERGY_COSTS.recordStandard)) {
          result = { ok: false, message: 'You do not have the energy to get back in the booth today.' };
          return;
        }

        const qualityBefore = song.quality;
        state.player.career.money -= cost;

        // New material means the old mix is gone: rescore from scratch and drop
        // the record back to a rough master so it has to be mixed again.
        const fresh = rescoreMaster(state, song, { producerSkill: skill, beatQuality: beat.quality });
        applyRescore(song, fresh, false);
        song.producerId = producer?.id;
        song.producerName = producer?.name;
        song.producerSkill = skill ?? undefined;
        song.beatId = beat.id;
        song.beatName = beat.name;
        song.beatQuality = beat.quality;
        song.recordingCost = (song.recordingCost ?? 0) + cost;
        song.masterStatus = 'recorded';
        song.readyToRelease = false;

        result = {
          ok: true,
          message: `Re-tracked "${song.title}" with ${producer?.name ?? 'your own beat'}. It is a rough master again — it needs a mix.`,
          scores: fresh,
          qualityBefore,
          qualityAfter: song.quality,
        };
        state.lastEventLog.unshift(`🎛️ Re-tracked "${song.title}".`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });
      return result;
    },

    rerecordSong: (songId, payload) => {
      const before = get();
      const source = before.songs.find((s) => s.id === songId);
      if (!source || isReleased(source)) return null;

      // A fresh take is a whole new session, priced and scored like one. The
      // lineage travels WITH the booking rather than being patched on
      // afterwards: the take does not exist as a record until the days are
      // done, so there is nothing to look up when the session lands.
      return get().createStudioSong({
        ...payload,
        lineageOf: {
          songId: source.id,
          title: source.title,
          takeNumber: (source.takeNumber ?? 1) + 1,
        },
      });
    },

    // ─── REMIXES OF RELEASED RECORDS ────────────────────────────────────
    //
    // A remix is a new reading of a record that is already out, not a version of
    // an unreleased master. It is its own song with its own streaming state and
    // its own chart run; the link back to the original is only how the two
    // explain each other.
    //
    // The remix does NOT get a guaranteed boost. It goes out through the same
    // release path as anything else, and the only thing the original does for it
    // is decide how much of an audience there is to build on — which is why a
    // remix of a song nobody heard stays small.
    createRemix: (data) => {
      // One remix at a time per record: a second one this soon splits the audience.
      {
        const st0 = get();
        const origin = st0.songs.find((x) => x.id === data.originalSongId);
        const baseId = origin?.lineage === 'remix' && origin.originalSongId ? origin.originalSongId : data.originalSongId;
        if (origin?.lineage === 'remix') return { ok: false, message: 'That one is already a remix. Remix the original instead.' };
        const now = dateToSerial(st0.gameDate);
        const recent = st0.songs.find((x) => x.originalSongId === baseId && x.lineage === 'remix' && (!isSongReleased(x) || now - serialOfGameDate(x.releaseDate, now) < 90));
        if (recent) return { ok: false, message: isSongReleased(recent) ? `"${recent.title}" came out ${now - serialOfGameDate(recent.releaseDate, now)} days ago. Let it run — another remix this soon splits the audience.` : `"${recent.title}" is already in your vault. Release that one first.` };
      }
      let result: RemixResult = { ok: false, message: 'That record is not out yet.' };
      set((state) => {
        if (!state.player) return;

        const original = state.songs.find((s) => s.id === data.originalSongId);
        if (!original) {
          result = { ok: false, message: 'That record no longer exists.' };
          return;
        }
        if (!isReleased(original)) {
          result = {
            ok: false,
            message: 'You can only remix a record that is already out. Re-record an unreleased master instead.',
          };
          return;
        }

        const npcs = raw(state.npcs) as NPC[];
        const producer = data.producerId
          ? npcs.find((n) => n.id === data.producerId) ?? null
          : null;
        const skill = producer ? producerSkillOf(producer) : null;
        const beats = producer ? getProducerBeats(producer.id, skill!) : getSelfProducedBeats();
        const beat = beats.find((b) => b.id === data.beatId) ?? beats[0];
        if (!beat) {
          result = { ok: false, message: 'That producer has no beats to pick from.' };
          return;
        }

        const cost = 700 + (skill === null ? 0 : producerFee(skill));
        if (state.player.career.money < cost) {
          result = {
            ok: false,
            message: `A remix session costs $${cost.toLocaleString()} and you have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }
        if (!spendEnergy(state, ENERGY_COSTS.recordStandard)) {
          result = { ok: false, message: 'You do not have the energy to cut a remix today.' };
          return;
        }

        // Somebody was invited onto it. The ASK costs its own energy and takes
        // its own days, so it is paid for here rather than when the remix lands
        // — otherwise a player with no energy left at the end of the session
        // would quietly lose the guest they asked for.
        const invite = data.inviteNpcId
          ? (raw(state.npcs) as NPC[]).find((n) => n.id === data.inviteNpcId) ?? null
          : null;
        if (invite) {
          if (invite.role !== 'artist') {
            result = {
              ok: false,
              message: `${invite.name} is not an artist. You want a verse off them, not a meeting.`,
            };
            return;
          }
          if (!spendEnergy(state, ENERGY_COSTS.shopFeature, { admin: true })) {
            const need = effectiveEnergy(state, ENERGY_COSTS.shopFeature, { admin: true });
            result = {
              ok: false,
              message: `Asking ${invite.name} onto it takes ${need} energy and you are at ${Math.floor(state.player.energy)}. ${energyShortfallMessage(need, state.player.energy)}`,
            };
            return;
          }
        }

        const lyrics = data.lyrics && data.lyrics.trim() ? data.lyrics : original.lyrics ?? '';
        const title = data.title?.trim() || `${original.title} (Remix)`;

        // A remix is a session, so it takes the days a session takes.
        const daysTotal = Math.max(1, Math.round(sessionDays(2) * crewBonuses(raw(state.crew) as CrewMember[]).sessionSpeed));
        const startSerial = dateToSerial(state.gameDate);

        // Scored through the same session function as anything else, so a remix
        // is a real record and not a special case.
        const scores = rescoreMaster(state, original, {
          lyrics,
          producerSkill: skill,
          beatQuality: beat.quality,
        });

        state.player.career.money -= cost;

        const song: Song = {
          id: uuidv4(),
          title,
          genre: original.genre,
          quality: scores.quality,
          releaseDate: formatGameDate(state.gameDate),
          marketingBudget: 0,
          totalStreams: 0,
          weeklyStreams: 0,
          totalEarnings: 0,
          version: 'remix',
          // The link. Both records point at each other through this id, which is
          // what the record page reads to show "Remix of …" and "Original".
          originalSongId: original.id,
          lineage: 'remix',
          featuredArtists: [...(original.featuredArtists ?? [])],
          featureArtistNames: [...(original.featureArtistNames ?? [])],
          chartPositions: {},
          certifications: [],
          hasVideo: false,
          videoViews: 0,

          bpm: original.bpm ?? 90,
          mood: original.mood ?? 'defiant',
          lyrics,
          lyricsQuality: scores.lyricsQuality,
          ghostwriterId: original.ghostwriterId,
          ghostwriterName: original.ghostwriterName,
          productionQuality: scores.productionQuality,
          productionCeiling: scores.productionCeiling,
          vocalPerformance: scores.vocalPerformance,
          chemistry: scores.chemistry,
          producerId: producer?.id,
          producerName: producer?.name,
          producerSkill: skill ?? undefined,
          beatId: beat.id,
          beatName: beat.name,
          beatQuality: beat.quality,
          commercialPotential: scores.commercialPotential,
          criticalPotential: scores.criticalPotential,
          recordingCost: cost,
          // A remix still has to be mixed and released like anything else.
          masterStatus: 'recorded',
          recordingDate: formatGameDate(serialToDate(startSerial + daysTotal)),
          vocalSettings: { ...(original.vocalSettings ?? VOCAL_DEFAULTS) },
        };

        // A remix is a session like any other, so it takes the days it takes.
        // The guest ask travels with the booking: there is no record to send
        // until the remix is finished, and the energy for the ask is spent
        // below, at booking time, so nothing can fail for want of it later.
        const workId = uuidv4();
        state.workItems.push({
          id: workId,
          kind: 'record',
          label: `Remixing "${original.title}"`,
          detail: `${daysTotal} day${daysTotal > 1 ? 's' : ''} in the room · $${cost.toLocaleString()}`,
          daysTotal,
          daysDone: 0,
          startedSerial: startSerial,
          payload: {
            song,
            growth: 0.6,
            inviteNpcId: invite?.id,
          } satisfies RecordWork,
        });

        state.player.career.momentum = Math.min(100, state.player.career.momentum + 3);
        state.player.stats.productionKnowledge = Math.min(
          100,
          state.player.stats.productionKnowledge + 0.4,
        );

        result = {
          ok: true,
          message:
            `"${title}" is booked in for ${daysTotal} day${daysTotal > 1 ? 's' : ''}. ` +
            `Mix it, then release it — a remix goes out like any other record.` +
            (invite ? ` The ask has gone on file for ${invite.name} and goes out the day it is finished.` : ''),
          songId: song.id,
        };
        state.lastEventLog.unshift(
          `🔁 Remix of "${original.title}" booked in as "${title}" — ${daysTotal} day${daysTotal > 1 ? 's' : ''}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });

      return result;
    },

    // ─── DELUXE / MIXTAPE ───────────────────────────────────────────────

    createDeluxe: (albumId, songIds) => {
      let result: { ok: true; albumId: string } | { ok: false; error: string } = {
        ok: false,
        error: 'Something went wrong.',
      };
      set((state) => {
        if (!state.player) {
          result = { ok: false, error: 'No artist loaded.' };
          return;
        }
        const base = state.albums.find((a) => a.id === albumId);
        if (!base) {
          result = { ok: false, error: 'That project no longer exists.' };
          return;
        }
        if ((base.ownerId ?? state.player.id) !== state.player.id) {
          result = { ok: false, error: 'That is not your project.' };
          return;
        }
        if (base.type === 'deluxe') {
          result = { ok: false, error: 'That is already a deluxe edition.' };
          return;
        }
        if (songIds.length < MIN_PROJECT_TRACKS.deluxe) {
          result = { ok: false, error: PROJECT_TRACK_RULE.deluxe };
          return;
        }

        // A deluxe is usually old tracks plus whatever was finished too late
        // for the original, so unreleased masters belong here more than
        // anywhere. They come out with the deluxe.
        const mine = new Map(state.songs.map((s) => [s.id, s]));
        // Tracks already on the base edition are the whole point of a deluxe —
        // but a track cannot be listed twice, and it cannot already be on
        // another project of yours.
        const onBase = new Set(base.songs);
        for (const other of state.albums) {
          if (other.id === base.id) continue;
          if ((other.ownerId ?? state.player.id) !== state.player.id) continue;
          for (const id of other.songs) onBase.add(id);
        }

        const extra: Song[] = [];
        for (const id of songIds) {
          const song = mine.get(id);
          if (!song) {
            result = { ok: false, error: 'That track is not in your vault.' };
            return;
          }
          if (onBase.has(id)) {
            result = { ok: false, error: `"${song.title}" is already on one of your projects.` };
            return;
          }
          extra.push(song);
        }

        // The extras that were not out yet come out with the deluxe.
        for (const t of extra) {
          if (!isReleased(t)) releaseAsProjectTrack(state, t);
        }

        const nowSerial = dateToSerial(state.gameDate);
        const id = `alb_deluxe_${base.id}_${state.albums.length}`;
        state.albums.push({
          id,
          title: `${base.title} (Deluxe)`,
          songs: [...base.songs, ...extra.map((s) => s.id)],
          releaseDate: formatGameDate(state.gameDate),
          totalStreams: 0,
          totalEarnings: 0,
          certifications: [],
          ownerId: state.player.id,
          ownerName: state.player.artistName,
          ownerCountry: state.player.country,
          type: 'deluxe',
          originalAlbumId: base.id,
          coverSeed: hashString(`rl-cover|deluxe|${base.id}`),
          releaseSerial: nowSerial,
        } as typeof state.albums[number]);

        result = { ok: true, albumId: id };
        state.lastEventLog.unshift(
          `💿 "${base.title}" is back out as a deluxe edition with ${extra.length} extra track${extra.length === 1 ? '' : 's'}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });
      return result;
    },

    createMixtape: (data) => {
      let result: { ok: true; albumId: string } | { ok: false; error: string } = {
        ok: false,
        error: 'Something went wrong.',
      };
      set((state) => {
        if (!state.player) {
          result = { ok: false, error: 'No artist loaded.' };
          return;
        }
        const title = data.title.trim();
        if (!title) {
          result = { ok: false, error: 'Give the mixtape a name.' };
          return;
        }
        if (data.songIds.length < MIN_PROJECT_TRACKS.mixtape) {
          result = { ok: false, error: PROJECT_TRACK_RULE.mixtape };
          return;
        }

        // Same rule as an album: your own masters, out or not. A mixtape is
        // where unreleased material has always lived, so this is the format
        // that needs it most.
        const mine = new Map(state.songs.map((s) => [s.id, s]));
        const used = new Set<string>();
        for (const a of state.albums) {
          if ((a.ownerId ?? state.player.id) !== state.player.id) continue;
          for (const id of a.songs) used.add(id);
        }

        const tracks: Song[] = [];
        for (const id of data.songIds) {
          const song = mine.get(id);
          if (!song) {
            result = { ok: false, error: 'That track is not in your vault.' };
            return;
          }
          if (used.has(id)) {
            result = { ok: false, error: `"${song.title}" is already on one of your projects.` };
            return;
          }
          tracks.push(song);
        }

        // Whatever was not out yet comes out with the tape.
        for (const t of tracks) {
          if (!isReleased(t)) releaseAsProjectTrack(state, t);
        }
        rollBreakout(state, tracks as Song[], 'tape');

        const nowSerial = dateToSerial(state.gameDate);
        const id = `alb_tape_${state.player.id}_${state.albums.length}`;
        state.albums.push({
          id,
          title,
          songs: tracks.map((s) => s.id),
          releaseDate: formatGameDate(state.gameDate),
          totalStreams: 0,
          totalEarnings: 0,
          certifications: [],
          ownerId: state.player.id,
          ownerName: state.player.artistName,
          ownerCountry: state.player.country,
          type: 'mixtape',
          coverSeed: hashString(`rl-cover|tape|${id}`),
          releaseSerial: nowSerial,
        } as typeof state.albums[number]);

        for (const t of state.songs) {
          if (tracks.some((x) => x.id === t.id)) t.mixtapeId = id;
        }

        result = { ok: true, albumId: id };
        state.lastEventLog.unshift(`📼 "${title}" is out — ${tracks.length} tracks, mixtape rules.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });
      return result;
    },

    saveAlbumDraft: (d) => {
      let result: { ok: boolean; message: string; id?: string } = { ok: false, message: 'Nothing to save.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const title = d.title.trim();
        if (!title) { result = { ok: false, message: 'Give the project a title first.' }; return; }
        // Only your own records, and nothing already on a released project.
        const mine = new Set(state.songs.map((x) => x.id));
        const used = new Set<string>();
        for (const a of state.albums) if ((a.ownerId ?? p.id) === p.id) for (const id of a.songs) used.add(id);
        const ids = [...new Set(d.songIds)].filter((id) => mine.has(id) && !used.has(id));
        const serial = dateToSerial(state.gameDate);
        const list = state.albumDrafts ?? (state.albumDrafts = []);
        const planned = d.plannedSerial === null ? undefined : d.plannedSerial !== undefined ? Math.max(serial + 1, Math.round(d.plannedSerial)) : undefined;
        let draft = d.id ? list.find((x) => x.id === d.id) : undefined;
        if (draft) {
          draft.title = title;
          draft.type = d.type;
          draft.songIds = ids;
          draft.updatedSerial = serial;
          if (d.plannedSerial !== undefined) draft.plannedSerial = planned;
          if (d.note !== undefined) draft.note = d.note.slice(0, 300);
        } else {
          draft = { id: uuidv4(), title, type: d.type, songIds: ids, createdSerial: serial, updatedSerial: serial, plannedSerial: planned, note: d.note?.slice(0, 300), coverSeed: hashString(`draft|${title}|${serial}`) };
          list.unshift(draft);
        }
        const short = ids.length < MIN_PROJECT_TRACKS[d.type];
        result = {
          ok: true,
          id: draft.id,
          message: `"${title}" is saved in the album vault — ${ids.length} track${ids.length === 1 ? '' : 's'}.${short ? ` ${PROJECT_TRACK_RULE[d.type]}` : ''}${draft.plannedSerial ? ` Scheduled for ${formatGameDate(serialToDate(draft.plannedSerial))}.` : ''}`,
        };
      });
      return result;
    },

    deleteAlbumDraft: (id) =>
      set((state) => {
        state.albumDrafts = (state.albumDrafts ?? []).filter((x) => x.id !== id);
      }),

    releaseAlbumDraft: (id) => {
      const d0 = (get().albumDrafts ?? []).find((x) => x.id === id);
      if (!d0) return { ok: false, message: 'That project is not in the vault.' };
      // Songs deleted since, or already out on another project, quietly drop off.
      const st0 = get();
      const usedIds = new Set(st0.albums.filter((a) => (a.ownerId ?? st0.player?.id) === st0.player?.id).flatMap((a) => a.songs));
      const d = { ...d0, songIds: d0.songIds.filter((sid) => st0.songs.some((x) => x.id === sid) && !usedIds.has(sid)) };
      const res = d.type === 'mixtape' ? get().createMixtape({ title: d.title, songIds: d.songIds }) : get().createAlbum({ title: d.title, songIds: d.songIds, type: d.type });
      if (!res.ok) return { ok: false, message: res.error };
      set((state) => {
        state.albumDrafts = (state.albumDrafts ?? []).filter((x) => x.id !== id);
        // A track that just came out on this project is spoken for on every other draft.
        for (const other of state.albumDrafts) other.songIds = other.songIds.filter((sid) => !d.songIds.includes(sid));
      });
      return { ok: true, message: `"${d.title}" is out — it charts from this week.` };
    },

    // ─── VIDEO VAULT ────────────────────────────────────────────────────
    publishVideo: (videoId) => {
      let result: VaultActionResult = { ok: false, message: 'That video is not in the vault.' };
      set((state) => {
        const video = state.videos?.find((v) => v.id === videoId);
        if (!video) return;
        if (video.published) {
          result = { ok: false, message: 'That video is already up.' };
          return;
        }
        // A visual for a master that is not out cannot go up before the record.
        const song = state.songs.find((s) => s.id === video.songId);
        if (song && !isReleased(song)) {
          result = {
            ok: false,
            message: `"${song.title}" is not out yet. The video goes up with the record.`,
          };
          return;
        }
        video.status = 'published';
        video.published = true;
        video.awaitingRelease = false;
        // A live visual lifts the record it belongs to — the same flag a
        // same-day shoot sets. Without this, publishing a vaulted video left
        // the song thinking it had no video at all.
        if (song) song.hasVideo = true;
        result = { ok: true, message: `"${video.title}" is live.` };
      });
      return result;
    },

    // ─── FEATURE NEGOTIATION ────────────────────────────────────────────
    //
    // The track goes out; the answer comes back days later, during
    // `advanceTurn`. Nothing here decides the outcome — that is
    // `decideFeatureResponse` in sim/features.ts, kept pure so it can be
    // reasoned about (and tested) on its own.
    sendFeatureRequest: (songId, npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'That did not go through.' };

      set((state) => {
        if (!state.player) {
          result = { ok: false, message: 'There is no career open to send anything from.' };
          return;
        }

        const song = state.songs.find(s => s.id === songId);
        // Only your own unreleased material can be shopped. Once it is out,
        // the feature ship has sailed.
        if (!song) {
          result = { ok: false, message: 'That record is not in your vault.' };
          return;
        }
        if (song.masterStatus === 'released') {
          result = {
            ok: false,
            message: `"${song.title}" is already out. You cannot add a verse to a record people have heard — put one on a remix instead.`,
          };
          return;
        }

        const npc = state.npcs.find(n => n.id === npcId);
        if (!npc) {
          result = { ok: false, message: 'That artist is not in your world.' };
          return;
        }
        if (npc.role !== 'artist') {
          result = {
            ok: false,
            message: `${npc.name} is not an artist. You want a verse off them, not a meeting.`,
          };
          return;
        }

        // They are already on this record. There is nothing left to negotiate.
        if ((song.featuredArtists ?? []).includes(npcId)) {
          result = { ok: false, message: `${npc.name} is already on this record.` };
          return;
        }

        // Already talking to them about this record? A live conversation does
        // not need a second message — but a dead one can be reopened.
        const existing = state.featureRequests.find(
          r => r.songId === songId && r.npcId === npcId && r.status !== 'declined' && r.status !== 'ignored',
        );
        if (existing) {
          result = {
            ok: false,
            message: `You are already waiting on ${npc.name} about "${song.title}" — ${existing.status === 'sent' ? `they have until ${existing.dueDate} to answer` : 'their answer is already in your Mailbox'}.`,
          };
          return;
        }

        if (!spendEnergy(state, ENERGY_COSTS.shopFeature, { admin: true })) {
          const need = effectiveEnergy(state, ENERGY_COSTS.shopFeature, { admin: true });
          result = {
            ok: false,
            message: `Sending a track out takes ${need} energy and you are at ${Math.floor(state.player.energy)}. ${energyShortfallMessage(need, state.player.energy)}`,
          };
          return;
        }

        const days = featureResponseDays(npc as FeatureCandidate);
        const req = openFeatureRequest(state, song, npc);

        state.lastEventLog.unshift(
          `📤 Sent "${song.title}" to ${npc.name}. Expect an answer in about ${days} days.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          message: `Sent "${song.title}" to ${npc.name}. Expect an answer in about ${days} days — nothing happens fast in this business.`,
          // A plain copy, NOT the draft. The draft is revoked the moment the
          // producer returns, and a caller that holds it and reads `status` a
          // second later would be reading a proxy that throws.
          request: { ...req },
        };
      });

      return result;
    },

    /**
     * Push back on a price.
     *
     * The player names a number; what comes back is `counterFeatureFee`'s
     * answer. Nothing here decides it, exactly as with the opening reply, so
     * the two halves of the negotiation cannot drift apart.
     */
    counterFeatureOffer: (requestId, offer) => {
      let result: FeatureActionResult = { ok: false, message: 'That is not on the table.' };

      set((state) => {
        if (!state.player) return;

        const req = state.featureRequests.find(r => r.id === requestId);
        if (!req) {
          result = { ok: false, message: 'That negotiation is no longer open.' };
          return;
        }
        if (req.status !== 'terms') {
          result = { ok: false, message: 'There is no price to argue with — nothing is on the table.' };
          return;
        }
        // The UI hides the control past the cap; the store enforces it, because
        // a rule that only exists in the view is not a rule.
        if ((req.negotiationRound ?? 0) >= MAX_NEGOTIATION_ROUNDS) {
          result = {
            ok: false,
            message: `You have pushed ${MAX_NEGOTIATION_ROUNDS} times. ${req.npcName} is done talking — pay the number or walk away.`,
          };
          return;
        }

        const npc = state.npcs.find(n => n.id === req.npcId);
        if (!npc) {
          result = { ok: false, message: 'That artist is not in your world any more.' };
          return;
        }

        const counter = Math.round(offer);
        if (!Number.isFinite(counter) || counter <= 0) {
          result = { ok: false, message: 'Offer them an actual number.' };
          return;
        }
        if (counter >= req.fee) {
          result = {
            ok: false,
            message: `You are already being asked ${'$'}${req.fee.toLocaleString()}. Offering more than that is not a negotiation.`,
          };
          return;
        }
        if (counter > state.player.career.money) {
          result = {
            ok: false,
            message: `You have ${'$'}${Math.floor(state.player.career.money).toLocaleString()} — you cannot offer money you do not have.`,
          };
          return;
        }

        const song = state.songs.find(s => s.id === req.songId);
        const manager = activeManager(
          state.contracts as unknown as ActiveContract[],
          state.npcs as unknown as NPC[],
        );

        const round = (req.negotiationRound ?? 0) + 1;
        const out = counterFeatureFee({
          npc: npc as FeatureCandidate,
          songQuality: song?.quality ?? 50,
          managerSkill: managerSkillOf(manager),
          playerFame: blendedFame(state.player),
          genre: state.player.genre,
          currentFee: req.fee,
          offer: counter,
          round,
          roll: Math.random(),
        });

        const askedBefore = req.fee;
        req.originalFee = req.originalFee ?? req.fee;
        req.negotiationRound = round;
        req.lastOffer = counter;
        req.reason = out.reason;

        if (out.refused) {
          req.status = 'declined';
        } else {
          req.fee = out.fee;
        }

        // The conversation lives in the DMs as well as in the Mailbox —
        // a price is something somebody said to you.
        const thread = state.dmThreads[req.npcId] ?? { npcId: req.npcId, messages: [], unread: 0 };
        thread.messages.push({
          id: uuidv4(),
          npcId: req.npcId,
          fromPlayer: true,
          content: `${'$'}${counter.toLocaleString()} and I will put it out properly.`,
          timestamp: new Date().toISOString(),
          read: true,
        });
        // Their answer in their words; the read of it as a small note.
        const how = out.refused ? (out.final && out.fee > counter && out.fee < askedBefore ? 'final' : 'off') : out.fee <= counter ? 'took' : out.fee >= askedBefore ? 'hold' : 'counter';
        const realReq = isRealId(req.npcId);
        thread.messages.push({ id: uuidv4(), npcId: req.npcId, fromPlayer: false, content: realReq ? managerVoice(npc.name.split(' ')[0], how, out.fee, `${req.id}|${counter}`, req.songTitle) : featureVoice(how, out.fee, `${req.id}|${counter}`), timestamp: new Date().toISOString(), read: false });
        if (!realReq) thread.messages.push({ id: uuidv4(), npcId: req.npcId, fromPlayer: false, system: true, content: out.reason, timestamp: new Date().toISOString(), read: true });
        thread.unread += 1;
        state.dmThreads[req.npcId] = thread;

        result = out.refused
          ? { ok: false, message: out.reason }
          : { ok: true, message: out.reason };

        state.lastEventLog.unshift(
          out.refused
            ? `🚫 ${npc.name} walked away from the table on "${req.songTitle}".`
            : `🤝 Countered ${npc.name} at ${'$'}${counter.toLocaleString()} — they are at ${'$'}${req.fee.toLocaleString()}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });

      return result;
    },

    payFeatureFee: (requestId) => {
      let ok = false;

      set((state) => {
        if (!state.player) return;
        const req = state.featureRequests.find(r => r.id === requestId);
        if (!req || req.status !== 'terms') return;
        if (state.player.career.money < req.fee) return;

        state.player.career.money -= req.fee;
        req.paid = true;
        // Paying is not the verse arriving: they still have to record it, and
        // who they are decides whether that happens on time, late or never.
        req.status = 'paid_waiting';

        const npc = state.npcs.find(n => n.id === req.npcId);
        const serial = dateToSerial(state.gameDate);
        if (npc) {
          const song = state.songs.find(s => s.id === req.songId);
          req.verseQuality = verseQualityFor(npc as FeatureCandidate, song?.quality ?? 50);
          const plan = planDelivery(personaOf(npc), Math.random(), Math.random());
          req.delivery = { outcome: plan.outcome, lateBy: plan.lateBy };
          req.verseDueSerial = serial + plan.days;
          npc.memoryLog = [
            ...npc.memoryLog.slice(-9),
            `[Business] Paid $${req.fee.toLocaleString()} for a verse on "${req.songTitle}".`,
          ];
          receipt(state, npc.id, -req.fee, `💸 You paid ${req.npcName} $${req.fee.toLocaleString()} for a verse on "${req.songTitle}". Due in ${plan.days} days.`, { notify: false, memory: `You paid ${req.npcName} $${req.fee.toLocaleString()} for a verse on "${req.songTitle}".` });
          if (!isRealId(npc.id)) scheduleDM(state, npc.id, pickLine(['Received 🙏 give me a few days', 'Got it. I\'ll get in the booth this week', 'Payment received. On it 🎙️'], req.id), nowMinuteOf(state) + 25);
        }

        state.lastEventLog.unshift(
          `💸 Paid $${req.fee.toLocaleString()} to ${req.npcName}. The verse is due in a few days — track it in Studio → Features.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        ok = true;
      });

      return ok;
    },

    declineFeatureTerms: (requestId) =>
      set((state) => {
        const req = state.featureRequests.find(r => r.id === requestId);
        if (!req || req.status !== 'terms') return;
        req.status = 'declined';
        req.reason = 'You passed on the fee. No hard feelings — this time.';
        state.lastEventLog.unshift(`🚫 Walked away from ${req.npcName}'s terms.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      }),

    addFeatureVerse: (requestId) => {
      let ok = false;

      set((state) => {
        if (!state.player) return;
        const req = state.featureRequests.find(r => r.id === requestId);
        // Only a verse that has actually landed can be cut in.
        if (!req || req.status !== 'verse_ready') return;

        const song = state.songs.find(s => s.id === req.songId);
        if (!song || song.masterStatus === 'released') return;
        if (!spendEnergy(state, ENERGY_COSTS.addVerse)) return;

        const npc = state.npcs.find(n => n.id === req.npcId);
        if (!npc) return;

        const existing = song.featureArtistNames ?? [];
        const existingIds = song.featuredArtists ?? [];

        // Recompute through the SAME chemistry formula the studio uses, so a
        // verse that arrives late lands on exactly the scale the player was
        // shown when they recorded.
        const featureList = [
          ...existingIds
            .map(id => state.npcs.find(n => n.id === id))
            .filter((n): n is NPC => n !== undefined)
            .map(n => ({ npc: n, relationship: n.relationshipScore })),
          { npc, relationship: npc.relationshipScore },
        ];

        const updated = applyFeatureVerse({
          song: {
            lyricsQuality: song.lyricsQuality ?? 0,
            productionQuality: song.productionQuality ?? 0,
            vocalPerformance: song.vocalPerformance ?? 0,
            commercialPotential: song.commercialPotential ?? 50,
            mood: song.mood ?? 'defiant',
            genre: song.genre,
          },
          features: featureList,
          verseQuality: req.verseQuality ?? 60,
          verseFame: npc.fame,
          stats: state.player.stats,
          existingFeatureCount: existingIds.length,
        });

        song.chemistry = updated.chemistry;
        song.vocalPerformance = updated.vocalPerformance;
        song.commercialPotential = updated.commercialPotential;
        song.quality = updated.quality;
        song.featuredArtists = [...existingIds, npc.id];
        song.featureArtistNames = [...existing, npc.name];

        req.status = 'added';

        // Being on a record together changes the relationship.
        npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + (req.freeVerse ? 8 : 4)));
        npc.memoryLog = [
          ...npc.memoryLog.slice(-9),
          `[Studio] Cut a verse on "${song.title}".`,
        ];

        // A name agreeing to be on your record is attention arriving.
        addMomentum(state, 2);

        state.lastEventLog.unshift(
          `🎙️ ${npc.name} is on "${song.title}". The record reads ${describeScore(song.quality)}`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        ok = true;
      });

      return ok;
    },

    // ─── INBOUND: SOMEBODY WANTS YOU ON THEIR RECORD ────────────────────
    //
    // The mirror of the block above, and it is NOT the same code with the sign
    // flipped. When the player asks, the risk is silence and the thing they do
    // not know is whether they will be heard. Here they are the one being paid,
    // the risk is money, and the thing they do not know is what the verse is
    // worth to the person across the table. That number is `ceiling`, it is
    // never rendered, and the manager's read is the only honest estimate of it
    // in the game.

    readInboundWithManager: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'That ask is not open.' };

      set((state) => {
        if (!state.player) return;
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!req) {
          result = { ok: false, message: 'That ask is not open.' };
          return;
        }
        if (req.status !== 'open') {
          result = { ok: false, message: 'That one is already settled — the number is on the card.' };
          return;
        }

        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (!npc) {
          result = { ok: false, message: 'That artist is not in your world any more.' };
          return;
        }

        const manager = activeManager(raw(state.contracts) as ActiveContract[], raw(state.npcs) as NPC[]) ?? null;
        const read = managerReadOnInbound({
          npc: npc as unknown as InboundCandidate,
          songQuality: req.songQuality,
          playerFame: blendedFame(state.player),
          playerGenre: state.player.genre,
          manager,
          budget: req.ceiling,
          roll: Math.random(),
        });

        // Snapshotted onto the request. The number the player acts on has to be
        // the number they can still read back afterwards, or a reload turns a
        // decision into a guess they cannot explain.
        req.managerRead = {
          trackVerdict: read.trackVerdict,
          recommendedFee: read.recommendedFee,
          estimatedCeiling: read.estimatedCeiling,
          confidence: read.confidence,
          artistRead: read.artistRead,
          advice: read.advice,
          pass: read.pass,
          managerName: manager ? manager.name : 'Nobody',
        };

        state.lastEventLog.unshift(
          manager
            ? `💼 ${manager.name} has read the ${npc.name} ask — they say ask $${read.recommendedFee.toLocaleString()}.`
            : `🤔 No manager to call. You are guessing on the ${npc.name} ask.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          message: manager
            ? `${manager.name}: "${read.advice}"`
            : 'You do not have a manager, so there is nobody to ask. Read the record yourself.',
        };
      });

      return result;
    },

    quoteInboundVerse: (requestId, quote) => {
      let result: FeatureActionResult = { ok: false, message: 'That ask is not open.' };

      set((state) => {
        if (!state.player) return;
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!req) {
          result = { ok: false, message: 'That ask is not open.' };
          return;
        }
        if (req.status !== 'open') {
          result = { ok: false, message: 'That one is already settled.' };
          return;
        }
        // Same rule as the outbound haggle, enforced in the store rather than
        // only hidden in the view: a cap that lives in the UI is not a cap.
        if ((req.negotiationRound ?? 0) >= MAX_NEGOTIATION_ROUNDS) {
          result = {
            ok: false,
            message: `You have pushed ${MAX_NEGOTIATION_ROUNDS} times. ${req.npcName} is done — take the number or leave it.`,
          };
          return;
        }

        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (!npc) {
          result = { ok: false, message: 'That artist is not in your world any more.' };
          return;
        }

        const ask = Math.round(quote);
        if (!Number.isFinite(ask) || ask <= 0) {
          result = { ok: false, message: 'Ask for an actual number.' };
          return;
        }
        if (ask <= req.offer) {
          result = {
            ok: false,
            message: `They are already offering $${req.offer.toLocaleString()}. Asking for less than that is not a negotiation.`,
          };
          return;
        }

        const round = (req.negotiationRound ?? 0) + 1;
        const decision = decideInboundResponse({
          npc: npc as unknown as InboundCandidate,
          budget: req.ceiling,
          currentOffer: req.offer,
          quote: ask,
          round,
          roll: Math.random(),
        });

        req.negotiationRound = round;
        req.lastAsk = ask;
        req.offer = decision.fee;
        req.reason = decision.reason;

        if (decision.accepted) {
          // The terms decide what moves now: up front, half, or on delivery.
          sealInboundDeal(state, req, decision.fee);

          const npcRef = state.npcs.find((n) => n.id === req.npcId);
          if (npcRef) {
            npcRef.relationshipScore = Math.max(-100, Math.min(100, npcRef.relationshipScore + 3));
            npcRef.memoryLog = [
              ...npcRef.memoryLog.slice(-9),
              `[Feature] Agreed $${decision.fee.toLocaleString()} for a verse on "${req.npcSongTitle}".`,
            ];
          }

          state.lastEventLog.unshift(
            `🤝 ${req.npcName} agreed to $${decision.fee.toLocaleString()} for a verse on "${req.npcSongTitle}" (${TERMS_LABEL[req.payTerms ?? 'half'].toLowerCase()}). It's in Studio → Features.`,
          );
          state.lastEventLog = state.lastEventLog.slice(0, 10);
        } else if (decision.walked) {
          req.status = 'withdrawn';
          const npcRef = state.npcs.find((n) => n.id === req.npcId);
          if (npcRef) {
            npcRef.relationshipScore = Math.max(-100, Math.min(100, npcRef.relationshipScore - 5));
          }
          state.lastEventLog.unshift(`🚪 ${req.npcName} walked away from the verse.`);
          state.lastEventLog = state.lastEventLog.slice(0, 10);
        } else {
          state.lastEventLog.unshift(`↔️ ${req.npcName} came up to $${decision.fee.toLocaleString()}.`);
          state.lastEventLog = state.lastEventLog.slice(0, 10);
        }

        result = { ok: true, message: decision.reason };
      });

      return result;
    },

    acceptInboundOffer: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'That ask is not open.' };

      set((state) => {
        if (!state.player) return;
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!req) {
          result = { ok: false, message: 'That ask is not open.' };
          return;
        }
        if (req.status !== 'open') {
          result = { ok: false, message: 'That one is already settled.' };
          return;
        }
        if (req.offer <= 0) {
          result = { ok: false, message: 'There is no number on the table to take.' };
          return;
        }

        sealInboundDeal(state, req, req.offer);

        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (npc) {
          npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + 4));
          npc.memoryLog = [
            ...npc.memoryLog.slice(-9),
            `[Feature] Took $${req.offer.toLocaleString()} for a verse on "${req.npcSongTitle}" — no haggling.`,
          ];
        }

        state.lastEventLog.unshift(
          `🤝 Took ${req.npcName}'s $${req.offer.toLocaleString()} for a verse on "${req.npcSongTitle}" (${TERMS_LABEL[req.payTerms ?? 'half'].toLowerCase()}).`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          message: `Agreed at $${req.offer.toLocaleString()}: ${TERMS_LABEL[req.payTerms ?? 'half'].toLowerCase()}${(req.paidSoFar ?? 0) > 0 ? ` ($${(req.paidSoFar ?? 0).toLocaleString()} is in your account)` : ''}. "${req.npcSongTitle}" is in Studio → Features — due in ${VERSE_DEADLINE_DAYS} days.`,
        };
      });

      return result;
    },

    setVerseTerms: (requestId, terms) => {
      let result: FeatureActionResult = { ok: false, message: 'That ask is not open.' };
      set((state) => {
        const req = state.inboundRequests.find((r) => r.id === requestId);
        const npc = req ? state.npcs.find((n) => n.id === req.npcId) : undefined;
        if (!req || !npc || !state.player || (req.status !== 'open' && req.status !== 'agreed')) return;
        if (req.termsSet) { result = { ok: false, message: 'You already sent your terms on this one.' }; return; }
        if (!terms.length) { result = { ok: false, message: 'Pick at least one term.' }; return; }
        const persona = personaOf(npc);
        const j = judgeTerms(persona, terms, npc.fame - blendedFame(state.player), Math.random());
        req.termsSet = true;
        pushDM(state, npc.id, { fromPlayer: true, content: `My terms on "${req.npcSongTitle}": ${terms.map((t) => MY_TERMS[t.kind].label + (t.targets?.length ? ` (${t.targets.map((x) => x.name).join(', ')})` : '')).join(' · ')}` });
        if (j.walk && req.status === 'open') {
          req.status = 'withdrawn';
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - 3);
          if (!isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, content: pickLine(['Nah that\'s too much for one verse. I\'ll find someone else.', 'All these conditions? Forget it.'], req.id) });
          result = { ok: true, message: j.line };
          return;
        }
        req.myTerms = j.accepted;
        if (!isRealId(npc.id)) pushDM(state, npc.id, { fromPlayer: false, content: j.refused.length ? pickLine([`Most of that is fine. But ${j.refused.map((t) => MY_TERMS[t.kind].label).join(', ')}? Can't promise that.`, `I can do some of it. Not ${j.refused.map((t) => MY_TERMS[t.kind].label).join(' or ')}.`], req.id) : pickLine(['Fair. Done, in writing 🤝🏾', 'No problem. Your terms, your verse.'], req.id) });
        result = { ok: true, message: j.line };
      });
      return result;
    },

    declineInboundRequest: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'That ask is not open.' };

      set((state) => {
        if (!state.player) return;
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!req) {
          result = { ok: false, message: 'That ask is not open.' };
          return;
        }
        if (req.status !== 'open') {
          result = { ok: false, message: 'That one is already settled.' };
          return;
        }

        req.status = 'declined';
        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (npc) {
          // Turning somebody down is not free, but it is not a war either —
          // saying no to a record is a normal thing to do.
          npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore - 3));
        }

        state.lastEventLog.unshift(`🙅 Turned down ${req.npcName}'s ask for a verse.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = { ok: true, message: `You passed on ${req.npcName}'s record.` };
      });

      return result;
    },

    sendInboundVerse: (requestId, effort = 'standard') => {
      let result: FeatureActionResult = { ok: false, message: 'There is nothing agreed to send.' };

      set((state) => {
        if (!state.player) return;
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!req) {
          result = { ok: false, message: 'That ask is not open.' };
          return;
        }
        if (req.status !== 'agreed') {
          result = {
            ok: false,
            message: req.status === 'delivered'
              ? 'That verse is already on their record.'
              : 'Nothing is agreed yet — settle a number first.',
          };
          return;
        }
        if ((state.workItems ?? []).some((w) => w.kind === 'verse' && (w.payload as VerseWork).requestId === req.id)) {
          result = { ok: false, message: 'You are already writing this one.' };
          return;
        }
        const E = VERSE_EFFORT[effort] ?? VERSE_EFFORT.standard;
        // A verse is not a message. It is a session, and it costs one.
        const cost = Math.round(ENERGY_COSTS.writeVerse * E.energy);
        if (!spendEnergy(state, cost)) {
          const need = effectiveEnergy(state, cost);
          result = {
            ok: false,
            message: `Writing this one takes ${need} energy and you are at ${Math.floor(state.player.energy)}. ${energyShortfallMessage(need, state.player.energy)}`,
          };
          return;
        }

        const days = effort === 'quick' ? 1 : 2 + Math.round(state.player.stats.songwriting / 40) + E.days;
        const startSerial = dateToSerial(state.gameDate);
        req.effort = effort;
        const verseQuality = Math.max(10, Math.min(100, E.quality + inboundVerseQuality({
          lyricism: state.player.stats.lyricism,
          flow: state.player.stats.flow,
          delivery: state.player.stats.delivery,
          vocalAbility: state.player.stats.vocalAbility,
          songwriting: state.player.stats.songwriting,
        })));

        state.workItems.push({
          id: uuidv4(),
          kind: 'verse',
          label: `Verse for ${req.npcName}`,
          detail: `"${req.npcSongTitle}" · ${(req.paidSoFar ?? 0) > 0 ? `$${(req.paidSoFar ?? 0).toLocaleString()} paid` : (req.agreedFee ?? 0) > 0 ? `$${(req.agreedFee ?? 0).toLocaleString()} on delivery` : 'no fee'} · ${days} day${days > 1 ? 's' : ''} writing`,
          daysTotal: days,
          daysDone: 0,
          startedSerial: startSerial,
          payload: {
            requestId: req.id,
            npcId: req.npcId,
            npcName: req.npcName,
            songId: req.npcSongId,
            songTitle: req.npcSongTitle,
            verseQuality,
            fee: req.agreedFee ?? 0,
          } satisfies VerseWork,
        });

        // Whatever the terms paid up front is already banked; the rest comes on
        // delivery. The days are what stops the same verse being sent twice.
        state.player.stats.songwriting = Math.min(100, state.player.stats.songwriting + 0.3);

        state.lastEventLog.unshift(
          `✍️ Writing the verse for ${req.npcName}'s "${req.npcSongTitle}" — ${days} day${days > 1 ? 's' : ''}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          message: `You are writing it. ${days} day${days > 1 ? 's' : ''} — it lands on their record when it is done.`,
        };
      });

      return result;
    },

    acceptFreeAsk: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'That ask is not open.' };
      set((state) => {
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!state.player || !req || req.status !== 'open') return;
        if (req.offer > 0) { result.message = `They're offering $${req.offer.toLocaleString()} — take the money instead.`; return; }
        sealInboundDeal(state, req, 0);
        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (npc) npc.relationshipScore = Math.min(100, npc.relationshipScore + 6);
        result = { ok: true, message: `Done — "${req.npcSongTitle}" is in Studio → Features. Due in ${VERSE_DEADLINE_DAYS} days.` };
      });
      return result;
    },

    refundInbound: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to refund.' };
      set((state) => {
        const p = state.player;
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!p || !req || req.status !== 'agreed') return;
        const paid = req.paidSoFar ?? 0;
        if (paid > p.career.money) { result.message = `You need $${paid.toLocaleString()} to pay them back.`; return; }
        const trade = req.payTerms === 'trade';
        // A trade was paid in kind: you pay for the beat instead. It wasn't earnings.
        if (paid > 0) { p.career.money -= paid; if (!trade) p.career.totalEarnings = Math.max(0, p.career.totalEarnings - paid); }
        req.status = 'withdrawn';
        req.lapsed = true;
        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - (req.refundDemanded ? 2 : 4));
        if (paid > 0 && trade) receipt(state, req.npcId, -paid, `↩️ You paid ${req.npcName} $${paid.toLocaleString()} for the beat instead of the verse on "${req.npcSongTitle}".`, { notify: false, memory: `You paid ${req.npcName} for the beat instead of doing their tape.` });
        else if (paid > 0) receipt(state, req.npcId, -paid, `↩️ You refunded ${req.npcName} $${paid.toLocaleString()} and called off the verse on "${req.npcSongTitle}".`, { notify: false, memory: `You refunded ${req.npcName} and called off the verse on "${req.npcSongTitle}".` });
        else pushDM(state, req.npcId, { fromPlayer: true, content: 'I can\'t make the verse work, sorry. Let\'s do something another time 🙏🏾' });
        result = { ok: true, message: trade ? `Paid $${paid.toLocaleString()} for the beat. The beat stays yours; the tape goes on without you.` : paid > 0 ? `Refunded $${paid.toLocaleString()}. Deal off, no court.` : 'Deal called off.' };
      });
      return result;
    },

    chaseBalance: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing is owed.' };
      set((state) => {
        const req = state.inboundRequests.find((r) => r.id === requestId);
        if (!state.player || !req || req.status !== 'delivered' || !(req.balanceDue ?? 0)) return;
        const serial = dateToSerial(state.gameDate);
        if (req.balanceChased && serial - req.balanceChased < 5) { result.message = 'You just asked. Give it a few days.'; return; }
        req.balanceChased = serial;
        pushDM(state, req.npcId, { fromPlayer: true, content: `Bro, the balance on "${req.npcSongTitle}" — $${(req.balanceDue ?? 0).toLocaleString()}. When are you sending it?` });
        const npc = state.npcs.find((n) => n.id === req.npcId);
        if (req.balancePlan === 'late' && req.balanceDueSerial !== undefined) req.balanceDueSerial = Math.min(req.balanceDueSerial, serial + 2);
        if (npc && !isRealId(npc.id)) scheduleDM(state, npc.id, req.balancePlan === 'never' ? pickLine(['Things are tight right now, soon', 'I\'ll sort you out, relax', 'Did the record even do numbers? Let\'s talk'], req.id + serial) : 'Sending it this week, my bad 🙏', nowMinuteOf(state) + 40);
        result = { ok: true, message: 'Asked. If it still doesn\'t come, the Courthouse is an option.' };
      });
      return result;
    },

    chaseVerse: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to chase.' };
      set((state) => {
        const req = state.featureRequests.find((r) => r.id === requestId);
        if (!state.player || !req || req.status !== 'paid_waiting') return;
        const npc = state.npcs.find((n) => n.id === req.npcId);
        req.chased = (req.chased ?? 0) + 1;
        pushDM(state, req.npcId, { fromPlayer: true, content: req.chased > 1 ? `I paid for that verse. I need it.` : `How far with the verse for "${req.songTitle}"?` });
        if (npc && !isRealId(npc.id)) {
          const d = req.delivery;
          const reply = d?.outcome === 'ghost' ? (req.chased > 1 ? '' : pickLine(['Soon soon', 'On it 🙏', 'Busy week, I got you'], req.id)) : lateExcuse((hashString(req.id) >>> 0) + req.chased);
          if (reply) scheduleDM(state, npc.id, reply, nowMinuteOf(state) + 30 + Math.floor(Math.random() * 120));
          // A nudge makes a late (not a missing) verse come sooner.
          if (d?.outcome === 'late' && req.verseDueSerial) req.verseDueSerial = Math.max(dateToSerial(state.gameDate) + 1, req.verseDueSerial - 3);
        }
        result = { ok: true, message: 'Sent.' };
      });
      return result;
    },

    askVerseRefund: (requestId) => {
      let result: FeatureActionResult = { ok: false, message: 'No refund to ask for.' };
      set((state) => {
        const p = state.player;
        const req = state.featureRequests.find((r) => r.id === requestId);
        if (!p || !req || req.status !== 'paid_waiting') return;
        const serial = dateToSerial(state.gameDate);
        if ((req.verseDueSerial ?? serial) > serial) { result.message = 'It isn\'t even due yet.'; return; }
        if (req.refundAsked) { result.message = 'You already asked. Next step: the Courthouse.'; return; }
        req.refundAsked = serial;
        const npc = state.npcs.find((n) => n.id === req.npcId);
        pushDM(state, req.npcId, { fromPlayer: true, content: `The verse never came. I want my $${req.fee.toLocaleString()} back.` });
        const ans = npc ? refundResponse(personaOf(npc), Math.random()) : 'ignore';
        if (ans === 'ignore') { result = { ok: true, message: `${req.npcName} left it on read. You can take it to court.` }; return; }
        const back = ans === 'full' ? req.fee : Math.round(req.fee / 2);
        req.refunded = back;
        // A full refund ends the deal; half back leaves the rest worth fighting for.
        if (ans === 'full') req.status = 'declined';
        p.career.money += back;
        receipt(state, req.npcId, back, `↩️ ${req.npcName} refunded $${back.toLocaleString()}${ans === 'partial' ? ` of the $${req.fee.toLocaleString()}` : ''} for the verse that never came.`, { memory: `${req.npcName} refunded $${back.toLocaleString()} for a verse they never sent.` });
        if (npc && !isRealId(npc.id)) scheduleDM(state, npc.id, ans === 'full' ? 'My bad fr. Sent it back 🙏' : 'Sent half. I did put work in.', nowMinuteOf(state) + 20);
        result = { ok: true, message: ans === 'full' ? `Refunded in full: $${back.toLocaleString()}.` : `They sent back half ($${back.toLocaleString()}). Sue for the rest if you want.` };
      });
      return result;
    },

    openStudioAt: (mode) => set((state) => { state.pendingStudioMode = mode; state.screen = 'studio'; }),
    consumeStudioMode: () => {
      const m = get().pendingStudioMode ?? null;
      if (m) set((state) => { state.pendingStudioMode = null; });
      return m;
    },

    // ─── AWARD SEASONS ──────────────────────────────────────────────────
    enterAwards: (key) => {
      let r = { ok: false, message: 'Nothing to enter.' };
      set((state) => { r = enterAwardsFor(state as GameState, key); });
      return r;
    },

    followAward: (bodyId, on) => set((state) => {
      const f = new Set(state.awardFollows ?? []);
      if (on) f.add(bodyId); else f.delete(bodyId);
      state.awardFollows = [...f];
    }),

    campaignAward: (key, tier) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to campaign for.' };
      set((state) => {
        const p = state.player;
        const s = state.awardSeasons?.[key];
        if (!p || !s || s.phase !== 'nominations') return;
        if (!s.categories.some((c) => c.nominees.some((n) => n.isPlayer))) { result.message = 'You have to be nominated to campaign.'; return; }
        const T = { radio: { cost: 1500, lift: 0.05, what: 'Radio and blog push' }, press: { cost: 6000, lift: 0.1, what: 'Press run and listening sessions' }, full: { cost: 20000, lift: 0.18, what: 'Billboards, PR firm, industry dinners' } }[tier];
        if (p.career.money < T.cost) { result.message = `That's $${T.cost.toLocaleString()}.`; return; }
        if (s.campaign.academy >= 0.35) { result.message = 'The voters have heard enough. More would look desperate.'; return; }
        p.career.money -= T.cost;
        s.campaign.spent += T.cost;
        s.campaign.academy = Math.min(0.35, s.campaign.academy + T.lift);
        result = { ok: true, message: `${T.what}: done. The academy is paying attention.` };
      });
      return result;
    },

    rallyVotes: (key) => {
      const st = get();
      const s = st.awardSeasons?.[key];
      const serial = dateToSerial(st.gameDate);
      if (!s || s.phase !== 'nominations' || serial > s.cal.votingCloses) return { ok: false, message: 'Voting is closed.' };
      const cat = s.categories.find((c) => c.fanVote && c.nominees.some((n) => n.isPlayer));
      if (!cat) return { ok: false, message: 'You\'re not in a public-vote category.' };
      if (s.campaign.lastRally === serial) return { ok: false, message: 'You already asked today.' };
      const body = bodiesFor(st).find((b) => b.id === s.bodyId);
      const r = st.publishPost({ apps: ['chirp'], kind: 'announce', content: `Voting is open for the ${body?.name ?? 'awards'} 🗳️ ${cat.name} — I need you. Tap in 🙏🏾` });
      if (!r.ok) return r;
      set((state) => { const x = state.awardSeasons?.[key]; if (x) { x.campaign.lastRally = serial; x.campaign.rally = Math.min(1.5, x.campaign.rally + 0.15); } });
      return { ok: true, message: 'Posted. Your fans are voting.' };
    },

    rsvpAward: (key, going) => {
      let result: FeatureActionResult = { ok: false, message: 'Not available.' };
      set((state) => {
        const p = state.player;
        const s = state.awardSeasons?.[key];
        if (!p || !s || s.phase === 'done') return;
        if (!going) { s.rsvp = false; result = { ok: true, message: 'You\'ll watch from home.' }; return; }
        if (!s.invite) {
          const body = bodiesFor(state).find((b) => b.id === s.bodyId);
          const price = body?.ticket ?? 200;
          if (p.career.money < price) { result.message = `A ticket is $${price.toLocaleString()}.`; return; }
          p.career.money -= price;
          s.invite = 'ticket';
        }
        s.rsvp = true;
        result = { ok: true, message: s.invite === 'ticket' ? 'Ticket bought. See you on the night.' : 'You\'re on the list.' };
      });
      return result;
    },

    ceremonyAct: (action) => {
      let result: FeatureActionResult = { ok: false, message: '' };
      set((state) => {
        const p = state.player;
        const a = state.activeCeremony;
        const s = a ? state.awardSeasons?.[a.key] : undefined;
        if (!p || !a || !s) { state.activeCeremony = null; return; }
        if (action === 'close') { state.activeCeremony = null; state.clockPaused = false; result = { ok: true, message: '' }; return; }
        if (action === 'carpet' || action === 'slip_in') {
          if (action === 'carpet') {
            const look = p.look;
            const v = carpetVerdict(look ? dripScore(look.outfit, dateToSerial(state.gameDate), state.drip, look.tattoos).score : 20, Math.random());
            addMomentum(state, v.momentum);
            a.notes.push(v.text);
            if (v.tag !== 'fine' && blendedFame(p) >= 25) state.headlines.unshift({ id: uuidv4(), text: v.tag === 'best' ? `${p.artistName} tops the best-dressed list` : `${p.artistName}'s red carpet look has the internet talking`, fullStory: v.text, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 4, category: 'general' });
          } else a.notes.push('You skipped the cameras and went straight in.');
          a.step = s.invite === 'performer' ? 'show' : 'results';
        } else if (action === 'perform' || action === 'watch') {
          if (action === 'perform') {
            const score = p.stats.stagePresence * 0.5 + p.stats.performance * 0.5 + (Math.random() - 0.5) * 30;
            const hit = score >= 60;
            addMomentum(state, hit ? 12 : 2);
            p.career.fanbase += Math.round(p.career.fanbase * (hit ? 0.04 : 0.01));
            a.notes.push(hit ? 'Your performance was the moment of the night. The clip is everywhere.' : 'A solid set. The room enjoyed it.');
            if (hit) remember(state, 'career', `Your performance at the ${bodiesFor(state).find((b) => b.id === s.bodyId)?.name} was the moment of the night.`, { weight: 4, tone: 'good' });
          } else a.notes.push('You watched from your seat.');
          a.step = 'results';
        } else if (action === 'reveal') {
          a.revealed = Math.min(s.categories.length, a.revealed + 1);
          if (a.revealed >= s.categories.length) a.step = s.categories.some((c) => c.nominees.find((n) => n.id === c.winnerId)?.isPlayer) ? 'speech' : 'done';
        } else if (action.startsWith('speech_')) {
          if (action === 'speech_grateful') { p.career.reputation = Math.min(100, p.career.reputation + 2); a.notes.push('You thanked God, your team and the fans. The room stood up.'); }
          if (action === 'speech_hype') { addMomentum(state, 6); p.career.reputation = Math.max(0, p.career.reputation - 1); a.notes.push('"To everyone who doubted me —" The clip is already a meme. Half love it.'); }
          if (action === 'speech_short') { p.career.reputation = Math.min(100, p.career.reputation + 1); a.notes.push('Short, sharp, gone. Respect.'); }
          a.step = 'done';
        }
        result = { ok: true, message: a.notes[a.notes.length - 1] ?? '' };
      });
      return result;
    },

    // ─── THE COURTHOUSE ─────────────────────────────────────────────────
    fileCase: ({ kind, refId, lawyer }) => {
      let result: FeatureActionResult = { ok: false, message: 'There is no case to bring.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const serial = dateToSerial(state.gameDate);
        let npcId = '', npcName = '', claim = 0, evidence = 50, facts: string[] = [];
        const fr = state.featureRequests.find((r) => r.id === refId);
        const ir = state.inboundRequests.find((r) => r.id === refId);
        if (kind === 'breach_feature' && fr) {
          if (fr.status !== 'paid_waiting' || (fr.verseDueSerial ?? serial) + 7 > serial) { result.message = 'Give them a week past the due date first.'; return; }
          const owed = fr.fee - (fr.refunded ?? 0);
          npcId = fr.npcId; npcName = fr.npcName; claim = Math.round(owed * 1.5);
          evidence = 78 + (fr.chased ? 5 : 0) + (fr.refundAsked ? 7 : 0);
          facts = [`You paid ${fr.npcName} $${fr.fee.toLocaleString()} for a verse on "${fr.songTitle}".`, `It was due ${formatGameDate(serialToDate(fr.verseDueSerial ?? serial))}; it never came.`, ...(fr.chased ? [`You chased it ${fr.chased} time${fr.chased > 1 ? 's' : ''}.`] : []), ...(fr.refundAsked ? ['You asked for a refund and got nothing.'] : [])];
        } else if (kind === 'unpaid_fee' && ir) {
          if (ir.status !== 'delivered' || !(ir.balanceDue ?? 0)) { result.message = 'Nothing is owed on that one.'; return; }
          if ((ir.deliveredSerial ?? serial) + 14 > serial) { result.message = 'Give them two weeks after delivery before suing.'; return; }
          npcId = ir.npcId; npcName = ir.npcName; claim = Math.round((ir.balanceDue ?? 0) * 1.3);
          evidence = 80 + (ir.balanceChased ? 6 : 0);
          facts = [`You delivered your verse on "${ir.npcSongTitle}" on ${formatGameDate(serialToDate(ir.deliveredSerial ?? serial))}.`, `The deal: $${(ir.agreedFee ?? 0).toLocaleString()} (${TERMS_LABEL[ir.payTerms ?? 'half'].toLowerCase()}). $${(ir.balanceDue ?? 0).toLocaleString()} was never paid.`, ...(ir.balanceChased ? ['You asked for it and were put off.'] : [])];
        } else {
          return;
        }
        if ((state.cases ?? []).some((c) => c.refId === refId && ['served', 'hearing'].includes(c.status))) { result.message = 'There is already a case about this.'; return; }
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!npc) return;
        // Counsel: your own lawyer, someone hired for the case, or yourself.
        let counsel: Lawyer;
        const team = teamLawyer(state);
        if (lawyer === 'team') {
          if (!team) { result.message = 'You don\'t have a lawyer on your team. Hire one for the case.'; return; }
          counsel = team;
        } else if (lawyer === 'self') {
          counsel = { name: p.artistName, skill: 12, source: 'self', perHearing: 0 };
        } else {
          const opt = lawyerOptions(claim, 0).find((o) => o.source === lawyer);
          if (!opt) return;
          if (p.career.money < opt.retainer + 120) { result.message = `${opt.name} wants a $${opt.retainer.toLocaleString()} retainer, plus the $120 filing fee.`; return; }
          p.career.money -= opt.retainer;
          counsel = { name: opt.name, skill: opt.skill, source: opt.source, perHearing: opt.perHearing };
        }
        if (p.career.money < 120) { result.message = 'The filing fee is $120.'; return; }
        p.career.money -= 120;
        const c = openCase(state, { kind, side: 'plaintiff', npcId, npcName, claim, evidence, facts, refId, lawyer: counsel });
        c.costs = 120 + (counsel.source === 'team' || counsel.source === 'self' ? 0 : lawyerOptions(claim, 0).find((o) => o.source === lawyer)?.retainer ?? 0);
        if (fr) fr.caseId = c.id;
        if (ir) ir.caseId = c.id;
        result = { ok: true, message: `Filed at the ${c.court}. ${npcName} will be served; their answer comes within a week.` };
      });
      return result;
    },

    hireLawyer: (caseId, source) => {
      let result: FeatureActionResult = { ok: false, message: 'No such case.' };
      set((state) => {
        const p = state.player;
        const c = (state.cases ?? []).find((x) => x.id === caseId);
        if (!p || !c || !['served', 'hearing'].includes(c.status)) return;
        if (source === 'team') {
          const t = teamLawyer(state);
          if (!t) { result.message = 'No lawyer on your team.'; return; }
          c.ourLawyer = t;
          result = { ok: true, message: `${t.name} is on it.` };
          return;
        }
        const opt = lawyerOptions(c.claim, 0).find((o) => o.source === source);
        if (!opt) return;
        if (p.career.money < opt.retainer) { result.message = `${opt.name} wants $${opt.retainer.toLocaleString()} up front.`; return; }
        p.career.money -= opt.retainer;
        c.costs += opt.retainer;
        c.ourLawyer = { name: opt.name, skill: opt.skill, source: opt.source, perHearing: opt.perHearing };
        c.log.push({ serial: dateToSerial(state.gameDate), text: `You hired ${opt.name} ($${opt.retainer.toLocaleString()} retainer).` });
        result = { ok: true, message: `${opt.name} is representing you.` };
      });
      return result;
    },

    answerCase: (caseId, answer) => {
      let result: FeatureActionResult = { ok: false, message: 'No such case.' };
      set((state) => {
        const p = state.player;
        const c = (state.cases ?? []).find((x) => x.id === caseId);
        if (!p || !c || c.side !== 'defendant' || c.status !== 'served') return;
        const serial = dateToSerial(state.gameDate);
        c.answerBy = undefined;
        if (answer === 'pay') {
          if (p.career.money < c.claim) { result.message = `You need $${c.claim.toLocaleString()}.`; return; }
          closeCase(state, c, 'settled', `You paid ${c.plaintiff.name} the full $${c.claim.toLocaleString()}. No court.`, c.claim, 0);
          result = { ok: true, message: 'Paid. It\'s over.' };
          return;
        }
        if (answer === 'settle') {
          const npc = state.npcs.find((n) => n.id === c.plaintiff.id);
          const ask = npc ? npcSettlement(c, personaOf(npc), Math.random()) : Math.round(c.claim * 0.7);
          c.offers.push({ id: uuidv4(), from: 'them', amount: ask, serial, status: 'open' });
          c.log.push({ serial, text: `You asked to settle. ${c.plaintiff.name} wants $${ask.toLocaleString()}.` });
          scheduleHearing(state, c, 'mention', 14);
          result = { ok: true, message: `${c.plaintiff.name} would settle for $${ask.toLocaleString()}. Take it, counter, or see them in court.` };
          return;
        }
        c.log.push({ serial, text: `You're fighting it${c.ourLawyer ? ` with ${c.ourLawyer.name}` : ''}.` });
        scheduleHearing(state, c, 'mention', 14);
        result = { ok: true, message: c.ourLawyer ? 'You\'re fighting it. First hearing is set.' : 'You\'re fighting it. Get a lawyer before the hearing — or represent yourself.' };
      });
      return result;
    },

    offerSettlement: (caseId, amount) => {
      let result: FeatureActionResult = { ok: false, message: 'No such case.' };
      set((state) => {
        const p = state.player;
        const c = (state.cases ?? []).find((x) => x.id === caseId);
        if (!p || !c || !['served', 'hearing'].includes(c.status)) return;
        amount = Math.round(amount);
        if (!(amount > 0)) { result.message = 'Name a number.'; return; }
        const serial = dateToSerial(state.gameDate);
        if (c.offers.some((o) => o.from === 'player' && o.serial === serial)) { result.message = 'One offer a day.'; return; }
        const npc = state.npcs.find((n) => n.id === (c.side === 'plaintiff' ? c.defendant.id : c.plaintiff.id));
        const yes = npc ? npcAcceptsOffer(c, amount, personaOf(npc), Math.random()) : false;
        c.offers.push({ id: uuidv4(), from: 'player', amount, serial, status: yes ? 'accepted' : 'rejected' });
        if (c.side === 'defendant' && yes && p.career.money < amount) { result.message = `They'd take it, but you don't have $${amount.toLocaleString()}.`; c.offers[c.offers.length - 1].status = 'rejected'; return; }
        if (yes) {
          closeCase(state, c, 'settled', c.side === 'plaintiff' ? `${c.defendant.name} agreed to pay $${amount.toLocaleString()}. Settled.` : `${c.plaintiff.name} accepted $${amount.toLocaleString()}. Settled.`, c.side === 'defendant' ? amount : 0, c.side === 'plaintiff' ? amount : 0);
          result = { ok: true, message: 'They took it. Settled.' };
        } else {
          c.log.push({ serial, text: `They turned down $${amount.toLocaleString()}.` });
          result = { ok: false, message: 'They said no. Try another number — or let the judge decide.' };
        }
      });
      return result;
    },

    acceptSettlement: (caseId, offerId) => {
      let result: FeatureActionResult = { ok: false, message: 'That offer is gone.' };
      set((state) => {
        const p = state.player;
        const c = (state.cases ?? []).find((x) => x.id === caseId);
        const o = c?.offers.find((x) => x.id === offerId && x.status === 'open' && x.from === 'them');
        if (!p || !c || !o) return;
        if (c.side === 'defendant' && p.career.money < o.amount) { result.message = `You need $${o.amount.toLocaleString()}.`; return; }
        o.status = 'accepted';
        closeCase(state, c, 'settled', c.side === 'plaintiff' ? `You accepted $${o.amount.toLocaleString()} from ${c.defendant.name}. Settled.` : `You paid ${c.plaintiff.name} $${o.amount.toLocaleString()}. Settled.`, c.side === 'defendant' ? o.amount : 0, c.side === 'plaintiff' ? o.amount : 0);
        result = { ok: true, message: 'Settled.' };
      });
      return result;
    },

    rejectSettlement: (caseId, offerId) => {
      let result: FeatureActionResult = { ok: false, message: 'That offer is gone.' };
      set((state) => {
        const c = (state.cases ?? []).find((x) => x.id === caseId);
        const o = c?.offers.find((x) => x.id === offerId && x.status === 'open');
        if (!c || !o) return;
        o.status = 'rejected';
        c.log.push({ serial: dateToSerial(state.gameDate), text: `You turned down $${o.amount.toLocaleString()}.` });
        result = { ok: true, message: 'Turned down. See you in court.' };
      });
      return result;
    },

    withdrawCase: (caseId) => {
      let result: FeatureActionResult = { ok: false, message: 'No such case.' };
      set((state) => {
        const c = (state.cases ?? []).find((x) => x.id === caseId);
        if (!state.player || !c || c.side !== 'plaintiff' || !['served', 'hearing'].includes(c.status)) return;
        closeCase(state, c, 'withdrawn', `You dropped the case against ${c.defendant.name}.`, 0, 0);
        result = { ok: true, message: 'Case dropped.' };
      });
      return result;
    },

    attendHearing: (mode) => {
      let result: FeatureActionResult = { ok: false, message: 'No hearing right now.' };
      set((state) => {
        const [cid, hid] = (state.activeHearing ?? '').split('|');
        const c = (state.cases ?? []).find((x) => x.id === cid);
        const h = c?.hearings.find((x) => x.id === hid);
        state.activeHearing = null;
        state.clockPaused = false;
        if (!state.player || !c || !h || h.done) return;
        const note = runHearing(state, c, h, mode === 'leave' ? (c.ourLawyer ? 'lawyer' : 'absent') : mode === 'testify' ? 'testify' : (c.ourLawyer ? 'lawyer' : 'testify'));
        result = { ok: true, message: note };
      });
      return result;
    },

    // ─── JOBS ───────────────────────────────────────────────────────────
    refreshJobBoard: () =>
      set((state) => {
        if (!state.player) return;
        if (state.jobBoardTurn === state.turnCount && state.jobBoard.length > 0) return;
        state.jobBoard = generateJobBoard({
          seed: state.turnCount + 1,
          playerFame: blendedFame(state.player),
          stats: state.player.stats,
          city: state.player.city,
        }) as JobListing[];
        state.jobBoardTurn = state.turnCount;
      }),

    workJob: (jobId) => {
      let outcome = { ok: false, message: '' };

      set((state) => {
        if (!state.player) return;

        const job = state.jobBoard.find(j => j.id === jobId);
        if (!job) {
          outcome = { ok: false, message: 'That job is off the board.' };
          return;
        }

        if (!spendEnergy(state, job.energyCost)) {
          outcome = {
            ok: false,
            message: energyShortfallMessage(job.energyCost, state.player.energy),
          };
          return;
        }

        state.player.career.money += job.pay;
        state.player.career.totalEarnings += job.pay;

        state.jobShifts.unshift({
          id: uuidv4(),
          jobId: job.id,
          title: job.title,
          employer: job.employer,
          date: formatGameDate(state.gameDate),
          pay: job.pay,
          energySpent: job.energyCost,
        });
        state.jobShifts = state.jobShifts.slice(0, 40);

        // Working a shift for someone else still teaches you something,
        // depending on what the work actually was.
        const statByCategory: Record<string, keyof ArtistStats | undefined> = {
          performance: 'stagePresence',
          session: 'flow',
          writing: 'songwriting',
          media: 'charisma',
          brand: 'networking',
          labour: 'discipline',
        };
        const stat = statByCategory[job.category];
        if (stat) {
          state.player.stats[stat] = Math.min(100, state.player.stats[stat] + 0.6);
        }

        // The shift eats the days it took, and the board rotates with them.
        state.gameDate = advanceDate(state.gameDate, job.daysCost) as typeof state.gameDate;
        state.turnCount += 1;

        state.lastEventLog.unshift(
          `${JOB_CATEGORY_LABEL[job.category]?.emoji ?? '🧰'} ${job.title} for ${job.employer} — ` +
          `$${job.pay.toLocaleString()}, ${job.energyCost} energy, ${job.daysCost} day${job.daysCost > 1 ? 's' : ''}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        outcome = { ok: true, message: `${job.outcome} +$${job.pay.toLocaleString()}` };
      });

      // Rolling the board is a separate concern from working the shift.
      if (outcome.ok) get().refreshJobBoard();

      return outcome;
    },

    /**
     * Price the guest list before anything is ordered.
     *
     * The dialog and the shoot call the same function, so the number the player
     * is shown is the number that gets charged.
     */
    quoteCameos: (songId, npcIds, budget) => {
      const state = get();
      const empty = { quotes: [] as CameoQuote[], total: 0, qualityBonus: 0 };
      const song = state.songs.find(s => s.id === songId);
      if (!song || !state.player) return empty;

      const onRecord = new Set(song.featuredArtists ?? []);
      const guests = npcIds
        .filter(id => onRecord.has(id))
        .map(id => state.npcs.find(n => n.id === id))
        .filter((n): n is NPC => n !== undefined);

      return quoteCameos(guests as FeatureCandidate[], {
        playerFame: blendedFame(state.player),
        budget: Math.max(0, Math.round(budget)),
        songQuality: song.quality,
      });
    },

    createMusicVideo: (payload) => {
      // `set()` cannot return a value, so the outcome is captured here and
      // handed back once the state has committed.
      let result: MusicVideoResult = { ok: false, message: 'Shoot could not be started.' };

      set((state) => {
        if (!state.player) return;
        const player = state.player;

        const song = state.songs.find(s => s.id === payload.songId);
        if (!song) {
          result = { ok: false, message: 'That record no longer exists.' };
          return;
        }
        const nowSerial = dateToSerial(state.gameDate);
        // A shoot for a master that is not out yet is allowed, and it is the
        // normal way to work: you shoot the visual, then drop the record and
        // the video together. You do not have to wait for a release date first.
        const forUnreleased = !isReleased(song);
        if (!forUnreleased && payload.releaseSerial < nowSerial) {
          result = { ok: false, message: 'That release date is in the past.' };
          return;
        }

        const director = VIDEO_DIRECTORS.find(d => d.id === payload.directorId);
        if (!director) {
          result = { ok: false, message: 'Pick a director.' };
          return;
        }

        const budget = Math.max(0, Math.round(payload.budget));
        const marketing = Math.max(0, Math.round(payload.marketingBudget));

        // ── The guest list ─────────────────────────────────────────────
        // Only people who are already on the record. Somebody who is not on
        // the song is not turning up to be in its video, and asking them is
        // the feature negotiation, not this.
        const onRecord = new Set(song.featuredArtists ?? []);
        const invited = (payload.cameos ?? []).filter(id => onRecord.has(id));
        const guestQuotes = invited
          .map(id => state.npcs.find(n => n.id === id))
          .filter((n): n is NPC => n !== undefined)
          .map(npc => cameoQuote({
            npc: npc as FeatureCandidate,
            playerFame: blendedFame(player),
            budget,
            songQuality: song.quality,
          }));

        // A guest who will not do it stops the shoot. Quietly shooting the
        // video without them would be worse than refusing: the player asked
        // for something and would not find out they did not get it.
        const noShow = guestQuotes.find(q => !q.appears);
        if (noShow) {
          result = { ok: false, message: noShow.reason };
          return;
        }

        const cameoCost = guestQuotes.reduce((n, q) => n + q.fee, 0);
        const cameoBonus = guestQuotes.reduce((n, q) => n + q.qualityBonus, 0);
        const cost = budget + marketing + director.fee + cameoCost;

        if (player.career.money < cost) {
          result = {
            ok: false,
            message: cameoCost > 0
              ? `That shoot costs $${cost.toLocaleString()} — $${budget.toLocaleString()} production, $${marketing.toLocaleString()} promotion, $${director.fee.toLocaleString()} for ${director.name} and $${cameoCost.toLocaleString()} to the guests. You have $${Math.floor(player.career.money).toLocaleString()}.`
              : `That shoot costs $${cost.toLocaleString()} and you have $${Math.floor(player.career.money).toLocaleString()}.`,
          };
          return;
        }
        // A shoot day is a shoot day.
        if (!spendEnergy(state, ENERGY_COSTS.musicVideo)) {
          result = { ok: false, message: 'You do not have the energy for a shoot today.' };
          return;
        }

        const title = payload.title.trim() || videoTitle(song.title, hashString(`mv|${song.id}`), song.genre);
        const id = `vid-${song.id}-${nowSerial}-${(state.videos ?? []).length}`;
        const seed = videoSeed(id);
        const quality = shootQuality({
          directorSkill: director.skill,
          budget,
          songQuality: song.quality,
          seed,
          crewBonus: crewBonuses(raw(state.crew) as CrewMember[]).videoBonus,
          cameoBonus,
        });

        player.career.money -= cost;

        if (!state.videos) state.videos = [];
        const video = createVideo({
          id,
          songId: song.id,
          songTitle: song.title,
          title,
          artistId: player.id,
          artistName: player.artistName,
          artistCountry: player.country,
          artistGenre: song.genre ?? player.genre,
          directorId: director.id,
          directorName: director.name,
          concept: payload.concept,
          visualStyle: payload.visualStyle,
          quality,
          budget,
          marketingBudget: marketing,
          uploadSerial: payload.releaseSerial,
          uploadDate: formatGameDate(serialToDate(payload.releaseSerial)),
          isPlayer: true,
          songQuality: song.quality,
          cameoArtistIds: guestQuotes.map(q => q.npcId),
          cameoArtistNames: guestQuotes.map(q => q.name),
          cameoCost,
        });

        // ── A SHOOT IS DAYS ON SET, NOT A CLICK ────────────────────────
        // The video is built here — the money is spent, the director is booked
        // and the edit is what it is — but it does not exist on the platform
        // until the days are behind it. That also settles a thing the instant
        // version got wrong: a video can no longer be dated before the shoot
        // that produced it. The completion path clamps the release forward if
        // the shoot overran the gap the player left.
        const shootDays = videoShootDays(budget);
        const startSerial = dateToSerial(state.gameDate);
        const workId = uuidv4();
        state.workItems.push({
          id: workId,
          kind: 'video',
          label: `Shooting "${title}"`,
          detail: `${director.name} · ${shootDays} day${shootDays > 1 ? 's' : ''} · $${cost.toLocaleString()}`,
          daysTotal: shootDays,
          daysDone: 0,
          startedSerial: startSerial,
          payload: {
            video,
            songId: song.id,
            songTitle: song.title,
            releaseSerial: payload.releaseSerial,
            budget,
            marketing,
            quality,
            directorName: director.name,
            guestNames: guestQuotes.map(q => q.name),
          } satisfies VideoWork,
        });

        state.lastEventLog.unshift(
          `🎬 On set with ${director.name} for "${song.title}" — ${shootDays} day${shootDays > 1 ? 's' : ''}, $${cost.toLocaleString()}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          message: `Shooting "${title}" with ${director.name} — ${shootDays} day${shootDays > 1 ? 's' : ''} on set. The edit lands when the days are done.`,
          videoId: id,
        };
      });

      return result;
    },

    deleteVideo: (videoId) =>
      set((state) => {
        const video = (state.videos ?? []).find(v => v.id === videoId);
        if (!video || !video.isPlayer) return;
        video.removed = true;
        video.published = false;
        video.status = 'draft';
      }),

    loadComments: (videoId) =>
      set((state) => {
        const video = (state.videos ?? []).find(v => v.id === videoId);
        if (!video) return;
        if (!state.videoComments) state.videoComments = {};

        const existing = state.videoComments[videoId] ?? [];
        const ctx = commentContextFor(state, video);
        const roster = (raw(state.npcs) as NPC[]).filter(n => n.role === 'artist' || n.tier !== 'local');
        const offset = existing.filter(c => !c.isPlayer && !c.parentId).length;
        const next = commentPage(video, ctx, roster, offset, COMMENT_PAGE);
        if (next.length === 0) return;
        state.videoComments[videoId] = [...existing, ...next];
      }),

    postComment: (videoId, content, parentId) =>
      set((state) => {
        const text = content.trim();
        if (!text) return;
        const video = (state.videos ?? []).find(v => v.id === videoId);
        if (!video) return;
        if (!state.videoComments) state.videoComments = {};

        const serial = dateToSerial(state.gameDate);
        const minute = 1 + (hashString(`${videoId}|${text}|${serial}`) % 1439);
        const comment = playerComment(videoId, text, serial, minute, parentId);

        const existing = state.videoComments[videoId] ?? [];
        state.videoComments[videoId] = [...existing, comment];
        video.commentCount += 1;

        // The world answers the player's own comment a day or two later. Only
        // for top-level comments — a reply to a reply would need its own thread.
        if (!parentId) {
          const ctx = commentContextFor(state, video);
          const roster = (raw(state.npcs) as NPC[]).filter(n => n.role === 'artist' || n.tier !== 'local');
          const replies = repliesTo(video, ctx, roster, comment, serial);
          state.videoComments[videoId] = [...state.videoComments[videoId], ...replies];
          video.commentCount += replies.length;
        }
      }),

    deleteComment: (videoId, commentId) =>
      set((state) => {
        const list = state.videoComments?.[videoId];
        if (!list) return;
        // Only the player's own comment, and only when it is still theirs.
        const target = list.find(c => c.id === commentId && c.isPlayer);
        if (!target) return;
        state.videoComments![videoId] = list.filter(
          c => c.id !== commentId && c.parentId !== commentId,
        );
      }),

    reactToComment: (commentId, value) =>
      set((state) => {
        if (!state.commentReactions) state.commentReactions = {};
        const previous = state.commentReactions[commentId];

        // Reactions on generated comments are derived, so a change of mind is
        // applied as a delta to the stored counter rather than a new row.
        const findComment = (): VideoComment | undefined => {
          for (const list of Object.values(state.videoComments ?? {})) {
            const hit = list.find(c => c.id === commentId);
            if (hit) return hit;
          }
          return undefined;
        };
        const comment = findComment();

        if (comment) {
          if (previous === 1) comment.likes = Math.max(0, comment.likes - 1);
          if (previous === -1) comment.dislikes = Math.max(0, comment.dislikes - 1);
          if (previous === value) {
            delete state.commentReactions[commentId];
            return;
          }
          if (value === 1) comment.likes += 1;
          if (value === -1) comment.dislikes += 1;
        } else if (previous === value) {
          delete state.commentReactions[commentId];
          return;
        }

        state.commentReactions[commentId] = value;
      }),

    // ─── DMs ────────────────────────────────────────────────────────────
    sendDM: (npcId, message, attachedSongId) =>
      set((state) => {
        if (isBlocked(state, npcId)) return;
        if (!state.dmThreads[npcId]) {
          state.dmThreads[npcId] = { npcId, messages: [], unread: 0 };
        }

        const playerMsg: DMMessage = {
          id: uuidv4(),
          npcId,
          fromPlayer: true,
          content: message,
          timestamp: new Date().toISOString(),
          attachedSongId,
          read: true,
        };

        state.dmThreads[npcId].messages.push(playerMsg);

        // Generate NPC reply — a person deciding whether you are worth answering.
        const npc = state.npcs.find(n => n.id === npcId);
        if (npc) {
          const serial = dateToSerial(state.gameDate);
          const thread = state.dmThreads[npcId];
          const today = thread.sentToday && thread.sentToday.serial === serial ? thread.sentToday.count : 0;
          thread.sentToday = { serial, count: today + 1 };
          let replyContent: string | null;
          let relChange: number;
          let note: string | undefined;

          const song = attachedSongId ? state.songs.find(s => s.id === attachedSongId) : undefined;
          if (thread.mutedUntil !== undefined && thread.mutedUntil > serial) {
            // They've stopped answering you. Delivered, read, nothing back.
            npc.memoryLog = [...npc.memoryLog.slice(-9), `[DM] You: "${message.slice(0, 40)}" — left on read`];
            return;
          }
          if (aiActiveFor('dms') && !isRealId(npc.id) && today < 8) {
            // The AI writes their answer; the chat shows them typing until it lands.
            thread.pendingAI = { since: Date.now() };
            npc.memoryLog = [...npc.memoryLog.slice(-9), `[DM] You: "${message.slice(0, 50)}"${song ? ` (sent "${song.title}")` : ''}`];
            return;
          }
          const onTeam = (state.crew ?? []).some((c) => c.npcId === npc.id) || managerOf(state)?.id === npc.id;
          if (onTeam && !song && !isRealId(npc.id)) {
            // Your own people answer about their job, with real numbers — and
            // do what you ask them to if it is theirs to do.
            const snap = teamSnapshot(state as GameState, serial);
            const lines = teamReply(state as GameState, snap, message, npc.id);
            const acts = teamActions(state as GameState, snap, message, npc.id);
            if (lines.length) {
              pushDM(state, npcId, { fromPlayer: false, content: lines[0].text, read: false });
              npc.relationshipScore = Math.min(100, npc.relationshipScore + 0.5);
              npc.memoryLog = [...npc.memoryLog.slice(-9), `[DM] You: "${message.slice(0, 40)}" — they: "${lines[0].text.slice(0, 40)}"`];
              if (acts.length) queueMicrotask(() => runTeamActions(acts));
              return;
            }
          }
          if (song && today < 3 && !isRealId(npc.id)) {
            const reaction = generateSongReaction(npc, song.title, song.quality);
            replyContent = isRealId(npc.id) ? null : reaction.text;
            relChange = isRealId(npc.id) ? 0 : reaction.relationshipChange;
            if (replyContent === null) note = 'Delivered.';
          } else {
            const reply = chatReply(npc as NPC, song && isRealId(npc.id) ? `${message} feature` : message, {
              playerFame: state.player ? blendedFame(state.player) : 0,
              sentToday: today,
              beef: activeBeefIds(state).has(npcId),
              seed: `${serial}|${today}`,
            }, Math.random());
            replyContent = reply.text;
            relChange = reply.relationship;
            note = reply.note;
          }

          if (replyContent) {
            const npcMsg: DMMessage = {
              id: uuidv4(),
              npcId,
              fromPlayer: false,
              content: replyContent,
              timestamp: new Date().toISOString(),
              read: false,
            };
            thread.messages.push(npcMsg);
            thread.unread += 1;
          } else if (note) {
            thread.messages.push({ id: uuidv4(), npcId, fromPlayer: false, system: true, content: note, timestamp: new Date().toISOString(), read: true });
          }

          npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + relChange));
          const memEntry = `[DM] You: "${message.slice(0, 40)}"${replyContent ? ` — they: "${replyContent.slice(0, 40)}"` : ' — no reply'}`;
          npc.memoryLog = [...npc.memoryLog.slice(-9), memEntry];
        }
      }),

    reachOutToNpc: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'That went nowhere.' };

      set((state) => {
        if (!state.player) {
          result = { ok: false, message: 'There is no career open.' };
          return;
        }

        const npc = state.npcs.find((n) => n.id === npcId);
        if (!npc) {
          result = { ok: false, message: 'That person is not in your world.' };
          return;
        }

        // ── One ask at a time ───────────────────────────────────────────
        // Asking someone to link up is a text, not an evening. They answer in
        // their own words — yes with a time, "this week is mad", or nothing —
        // and the evening (and what it does for you two) happens when you
        // actually meet. The cooldown stops it being a button you hold down.
        const nowSerial = dateToSerial(state.gameDate);
        const last = npc.lastReachOut;
        if (last !== undefined) {
          const since = nowSerial - last;
          if (since < REACH_OUT_COOLDOWN_DAYS) {
            const wait = REACH_OUT_COOLDOWN_DAYS - since;
            result = { ok: false, message: `You asked ${npc.name.split(' ')[0]} ${since <= 0 ? 'today' : `${since} day${since === 1 ? '' : 's'} ago`}. Give it ${wait} more day${wait === 1 ? '' : 's'} — double-texting doesn't help.` };
            return;
          }
        }
        if ((state.appointments ?? []).some((a) => a.npcId === npc.id && (a.status === 'confirmed' || a.status === 'proposed'))) {
          result = { ok: false, message: `You already have plans with ${npc.name.split(' ')[0]}. Check your diary.` };
          return;
        }
        npc.lastReachOut = nowSerial;
        pushDM(state, npcId, { fromPlayer: true, content: pickLine(['You around this week? Would be good to link up properly, no agenda.', 'Let\'s link this week. Food on me 🍽️', 'Been a minute. You free this week? Let\'s catch up'], `${npcId}|${nowSerial}`) });

        const now = nowMinuteOf(state);
        const first = npc.name.split(' ')[0];
        const real = isRealId(npc.id);
        const gap = npc.fame - blendedFame(state.player);
        const beef = activeBeefIds(state).has(npc.id);
        const p = personaOf(npc);
        const odds = beef ? 0.1 : Math.max(0.05, Math.min(0.95, 0.55 + npc.relationshipScore / 160 + p.warmth * 0.2 - Math.max(0, gap) / 70 - (real ? 0.3 : 0)));
        const roll = Math.random();
        if (roll < odds) {
          // Yes — with a time. They pick it, 1-3 evenings out.
          const day = Math.floor(now / MINUTES_PER_DAY) + 1 + Math.floor(Math.random() * 3);
          const at = day * MINUTES_PER_DAY + (19 + Math.floor(Math.random() * 3)) * 60;
          const when = whenLabel(at, now);
          if (!real) pushDM(state, npcId, { fromPlayer: false, content: pickLine(p.style === 'formal' ? [`I'd like that. ${when}?`, `Sounds good. How's ${when}?`] : p.style === 'street' ? [`Say less. ${when} 🍻`, `Bet. ${when}, I'll send the location`] : [`Yes!! ${when}? 🙌🏾`, `Been meaning to. ${when} works for me`], `${npcId}|${day}`) });
          const a = createAppointment(state, npc as NPC, real ? 'meeting' : 'linkup', at, 'npc');
          if (real) a.title = `Meeting with ${npc.name}'s team and ${first}`;
          result = { ok: true, message: `${first} said yes — ${when}, ${a.place}. It's in your diary.` };
          return;
        }
        if (roll < odds + 0.3 && !beef) {
          // Busy. No hard feelings, no plans.
          if (!real) pushDM(state, npcId, { fromPlayer: false, content: pickLine(['This week is mad 😩 next week?', 'Travelling till the weekend. Hit me after 🙏🏾', 'Can\'t this week, studio every night. Soon though'], `${npcId}|${nowSerial}|busy`) });
          else pushDM(state, npcId, { fromPlayer: false, content: `${first}'s schedule is full for the next few weeks.` });
          result = { ok: true, message: `${first} is busy this week. Try again in a few days.` };
          return;
        }
        // Nothing. Bigger names and people who don't rate you leave it on read.
        if (beef && !real) scheduleDM(state, npcId, pickLine(['Link up for what? 😂', 'Nah.'], `${npcId}|${nowSerial}|beef`), now + 40);
        result = { ok: true, message: beef ? `${first} wasn't having it.` : `Delivered. ${first} hasn't replied.` };
      });

      return result;
    },

    markDMRead: (npcId) =>
      set((state) => {
        if (state.dmThreads[npcId]) {
          state.dmThreads[npcId].unread = 0;
          state.dmThreads[npcId].messages.forEach(m => { m.read = true; });
        }
      }),

    // ─── SOCIAL ─────────────────────────────────────────────────────────
    createPost: (platform, content, relatedSongId) =>
      set((state) => {
        if (!state.player) return;
        if (!spendEnergy(state, ENERGY_COSTS.socialPost, { admin: true })) return;

        const post: SocialPost = {
          id: uuidv4(),
          platform: platform as SocialPost['platform'],
          authorId: 'player',
          authorName: state.player.artistName,
          content,
          likes: Math.floor(state.player.career.fanbase * 0.01) + Math.floor(Math.random() * 20),
          shares: Math.floor(Math.random() * 10),
          comments: [],
          timestamp: new Date().toISOString(),
          relatedSongId,
          isPlayerPost: true,
          trendingScore: Math.floor(state.player.career.localFame * 0.3),
          // Stamped with the GAME day, not just the wall clock, so the feed can
          // say how old a post is in game time.
          daySerial: dateToSerial(state.gameDate),
        };

        // NPC reactions — sample a bounded set rather than filtering every artist,
        // media account and fan account in the roster just to use four of them.
        const reactingNPCs: NPC[] = [];
        for (const npc of raw(state.npcs) as NPC[]) {
          if (npc.role !== 'artist' && npc.role !== 'media' && npc.role !== 'fan_account') continue;
          if (Math.random() < 0.3) {
            reactingNPCs.push(npc);
            if (reactingNPCs.length >= 4) break;
          }
        }

        for (const npc of reactingNPCs) {
          const reaction = generatePostComment(npc, content);
          post.comments.push({
            id: uuidv4(),
            authorId: npc.id,
            authorName: npc.name,
            content: reaction.text,
            likes: Math.floor(Math.random() * 30),
            timestamp: new Date().toISOString(),
          });
        }

        state.socialPosts.unshift(post);
        socialMomentum(state, 1);
      }),

    likePost: (postId) =>
      set((state) => {
        const post = state.socialPosts.find(p => p.id === postId);
        if (!post) return;
        if (post.liked) { post.liked = false; post.likes = Math.max(0, post.likes - 1); return; }
        post.liked = true;
        post.likes += 1;
        // Liking somebody's post is noticed — once per post.
        if (!post.isPlayerPost && post.authorId !== 'player' && !post.authorId.startsWith('fan:')) {
          const serial = dateToSerial(state.gameDate);
          if (socialTouch(state, `like:${post.id}`, serial) === 1) bumpRel(state, post.authorId, 1, serial);
        }
      }),

    publishPost: (opts) => {
      let result: { ok: boolean; message: string; viral?: boolean } = { ok: false, message: 'Nothing to post.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const content = opts.content.trim();
        if (!content && !opts.songId) { result.message = 'Write something first.'; return; }
        const apps = (opts.apps.length ? opts.apps : ['chirp']) as SocialApp[];
        const serial = dateToSerial(state.gameDate);
        const k0 = kindDef(opts.kind as PostKind);
        let song = opts.songId ? state.songs.find((s) => s.id === opts.songId && isSongReleased(s)) : undefined;
        // A sound: one of yours, or somebody else's record that is trending.
        const sound = opts.soundSongId ? (state.songs.find((s) => s.id === opts.soundSongId && isSongReleased(s)) ?? state.npcSongs.find((s) => s.id === opts.soundSongId)) : undefined;
        const soundIsTheirs = !!sound && !state.songs.some((s) => s.id === sound.id);
        if (sound && !soundIsTheirs && !song) song = sound;
        if (k0.needsSong && !song && !sound) { result.message = `A ${k0.label.toLowerCase()} needs a song — one of yours, or a trending sound.`; return; }
        const energy = k0.energy + (apps.length - 1);
        if (!spendEnergy(state, energy, { admin: true })) { result.message = energyShortfallMessage(energy, p.energy); return; }

        // Tags: up to five, each one a real person who will see it.
        const tagged = (opts.tags ?? []).slice(0, 5).map((id) => state.npcs.find((n) => n.id === id)).filter(Boolean) as NPC[];
        const today = state.postsToday && state.postsToday.serial === serial ? state.postsToday.count : 0;
        state.postsToday = { serial, count: today + 1 };
        const beefs = activeBeefIds(state);
        const insulting = detectIntent(content) === 'insult';
        // Calling a litigious person names in public can end up in court.
        if (insulting) {
          for (const n of tagged) {
            const pp = personaOf(n);
            const already = (state.cases ?? []).some((c) => c.kind === 'defamation' && c.plaintiff.id === n.id && ['served', 'hearing'].includes(c.status));
            if (!already && !isRealId(n.id) && n.fame >= 30 && pp.litigious > 0.62 && Math.random() < 0.18 + (pp.litigious - 0.62)) {
              const claim = Math.round((15000 + n.fame * 1800) / 500) * 500;
              npcSues(state, n as NPC, 'defamation', claim, 38 + Math.round(Math.random() * 25), [`On ${APP_META[apps[0]].name}, you posted about ${n.name}: "${content.slice(0, 120)}"`, `${n.name} says it was false and damaged their reputation and deals.`]);
              break;
            }
          }
        }
        const controversy = insulting || tagged.some((n) => beefs.has(n.id));
        const stats = socialStatsOf(state);
        const tagList = tagged.map((n) => ({ id: n.id, name: n.name }));
        const now = new Date().toISOString();
        let viralAny = false;
        let lead: SocialPost | undefined;
        const notes: string[] = [];

        for (const app of apps) {
          const kind = kindOnApp(k0.id, app, !!song);
          const craft = kind === 'freestyle' ? p.stats.freestyle : kind === 'skit' ? p.stats.charisma : kind === 'challenge' ? p.stats.stagePresence : p.stats.marketing;
          // The blue tick and a trending sound both carry a post further.
          // What you're wearing shows on the visual apps; a fit pic in new pieces most of all.
          const looks = app === 'snapgram' || app === 'clip' ? dripReach(playerDrip(state)) * (opts.fit ? 1.12 : 1) : 1;
          const lift = (state.verified ? 1.15 : 1) * (soundIsTheirs && app === 'clip' ? 1.35 : 1) * looks;
          const r = postReach({ boost: socialBoost(state),
            app, kind, followers: Math.round(stats[app].followers * lift), fame: blendedFame(p), momentum: p.career.momentum,
            songQuality: (song ?? sound)?.quality, postsToday: today, taggedFame: tagged.map((n) => n.fame), controversy, craft, roll: Math.random(),
          });
          const post: SocialPost = {
            id: uuidv4(), platform: app as SocialPost['platform'], authorId: 'player', authorName: p.artistName,
            content: content || (song ? `"${song.title}" out now 🎧` : ''),
            likes: r.likes, shares: r.shares, comments: [],
            timestamp: now, relatedSongId: (app === 'clip' && sound ? sound.id : song?.id), isPlayerPost: true,
            soundSongId: app === 'clip' ? (sound ?? song)?.id : undefined,
            trendingScore: Math.round(10 + (r.viral ? 80 : 0) + (controversy ? 30 : 0)),
            daySerial: serial, kind, tags: tagList.length ? tagList : undefined,
            views: r.views || undefined, viral: r.viral || undefined,
            // Live: the numbers arrive over the next hours, read through `liveCounts`.
            target: { likes: r.likes, shares: r.shares, comments: r.comments, views: r.views },
            postedMinute: gameMinute(state),
            growth: { likes: 0, shares: 0, comments: Math.min(15, Math.round(r.comments * 0.3)), views: 0, follows: Math.round(r.follows * 0.6), days: 3 },
          };
          // The comment section fills in through the hours after posting, and
          // you hear about it as it happens.
          const nComments = Math.max(3, Math.min(14, r.comments));
          post.comments = socialComments(post, nComments, commentContext(state, controversy, `${serial}|${post.id}`), now);
          const at = commentMinutes(post.postedMinute!, post.comments.length, hashString(post.id) >>> 0);
          post.comments.forEach((c, i) => { c.minute = at[i]; });
          post.target!.comments = Math.max(post.target!.comments, post.comments.length);
          if (!lead) {
            for (const c of post.comments.slice(0, 3)) pushActivity(state, { kind: 'comment', text: `${c.authorName} commented: "${c.content}"`, actorName: c.authorName, actorId: c.authorId, postId: post.id, minute: c.minute! });
          }
          stats[app].followers += Math.round(r.follows * 0.4);
          stats[app].lastPostSerial = serial;
          state.socialPosts.unshift(post);
          if (!lead) lead = post;
          if (r.note) notes.push(`${APP_META[app].name}: ${r.note}`);

          // A Q&A or a community post builds the core.
          if (kind === 'qa' || kind === 'community') p.career.reputation = Math.min(100, p.career.reputation + (kind === 'qa' ? 1 : 0.3));

          if (r.viral) {
            viralAny = true;
            addMomentum(state, 5);
            p.career.localFame = Math.min(100, p.career.localFame + 0.8);
            p.career.nationalFame = Math.min(100, p.career.nationalFame + 0.3);
            state.headlines.unshift({ id: uuidv4(), text: `${p.artistName}'s ${APP_META[app].name} ${kindDef(kind).label.toLowerCase()} is everywhere`, fullStory: `"${post.content.slice(0, 80)}" — ${r.views ? `${r.views.toLocaleString()} views` : `${r.likes.toLocaleString()} likes`} and climbing.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 6, category: 'general' });
            if (song && (kind === 'challenge' || app === 'clip')) {
              const st = state.platformStats?.[song.id];
              const age = st ? Math.max(0, serial - st.release) : 0;
              plantRevival(state, song.id, { power: 0.6 + Math.random() * 1.2, width: 10 + Math.floor(Math.random() * 15), reason: `Went viral on ${APP_META[app].name}` }, age);
              notes.push(`"${song.title}" is getting pulled back up by the clip.`);
            }
          }
        }

        // Friends like it — and you see who.
        if (lead) {
          const friends = (raw(state.npcs) as NPC[]).filter((n) => n.relationshipScore >= 30 && n.role === 'artist' && !isBlocked(state, n.id));
          for (let i = 0; i < Math.min(3, friends.length); i++) {
            const f = friends[Math.floor(Math.random() * friends.length)];
            if (Math.random() < 0.55) pushActivity(state, { kind: 'like', text: `${f.name} liked your post`, actorId: f.id, actorName: f.name, postId: lead.id, minute: lead.postedMinute! + 3 + Math.floor(Math.random() * 300) });
          }
          if (sound && soundIsTheirs) {
            const owner = state.npcs.find((n) => n.id === sound.ownerId);
            if (owner) bumpRel(state, owner.id, 2, serial, `You used "${sound.title}" as a sound.`);
            notes.push(`Riding "${sound.title}" — a trending sound carries further.`);
          }
        }

        // The people you tagged see it.
        for (const npc of tagged) {
          const tr = tagResponse({ npc: npc as NPC, playerFame: blendedFame(p), beef: beefs.has(npc.id), insulting, roll: Math.random() });
          bumpRel(state, npc.id, tr.rel, serial, `Tagged by you: "${content.slice(0, 40)}" (${tr.action})`);
          if (tr.heat) nudgeBeef(state, npc.id, tr.heat, serial);
          if (lead && tr.text) {
            lead.comments.unshift({ id: uuidv4(), authorId: npc.id, authorName: npc.name, content: tr.text, likes: Math.round(100 + npc.fame * 40), timestamp: now, tone: tr.action === 'clapback' ? 'hater' : 'artist' });
            pushActivity(state, { kind: 'comment', text: `${npc.name} ${tr.action === 'clapback' ? 'clapped back' : 'replied'}: "${tr.text}"`, actorId: npc.id, actorName: npc.name, postId: lead.id, minute: lead.postedMinute! + 10 + Math.floor(Math.random() * 120) });
          }
          if (lead && (tr.action === 'like' || tr.action === 'repost')) {
            pushActivity(state, { kind: tr.action === 'like' ? 'like' : 'repost', text: `${npc.name} ${tr.action === 'like' ? 'liked' : 'reposted'} your post`, actorId: npc.id, actorName: npc.name, postId: lead.id, minute: lead.postedMinute! + 5 + Math.floor(Math.random() * 200) });
          }
          if (lead && tr.action === 'repost') {
            const rp: SocialPost = { ...lead, id: uuidv4(), authorId: npc.id, authorName: npc.name, isPlayerPost: false, repostOf: lead.id, comments: [], growth: undefined, target: undefined, postedMinute: undefined, liked: false, reposted: false, trendingScore: 30 };
            livenPost(state, rp, { at: lead.postedMinute! + 30 });
            state.socialPosts.unshift(rp);
            stats[lead.platform].followers += Math.round(20 + npc.fame * 12);
          }
          if (tr.action !== 'ignore') notes.push(`${npc.name} ${tr.action === 'clapback' ? 'clapped back' : tr.action === 'repost' ? 'reposted it' : tr.action === 'reply' ? 'replied' : 'liked it'}.`);
          else notes.push(`${npc.name} didn't respond.`);
          if (tr.action === 'clapback' && !beefs.has(npc.id) && npc.relationshipScore < -20) {
            npcStartsBeef(state, npc as NPC, serial, 'you tagged them with something they did not like.');
          }
        }

        socialMomentum(state, controversy ? 2 : 1);
        result = { ok: true, viral: viralAny, message: `Posted to ${apps.map((a) => APP_META[a].name).join(', ')}.${notes.length ? ' ' + notes.join(' ') : ''}` };
      });
      return result;
    },

    repostPost: (postId) => {
      let result: FeatureActionResult = { ok: false, message: 'Post not found.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const post = state.socialPosts.find((x) => x.id === postId);
        if (!post) return;
        if (post.reposted) { result.message = 'You already reposted that.'; return; }
        post.reposted = true;
        post.shares += 1;
        const serial = dateToSerial(state.gameDate);
        state.socialPosts.unshift({ ...post, id: uuidv4(), authorId: 'player', authorName: p.artistName, isPlayerPost: true, repostOf: post.id, comments: [], liked: false, reposted: false, growth: undefined, daySerial: serial, timestamp: new Date().toISOString(), likes: 0, shares: 0, target: undefined, postedMinute: gameMinute(state) });
        if (!post.isPlayerPost && !post.authorId.startsWith('fan:')) {
          bumpRel(state, post.authorId, post.relatedSongId ? 3 : 2, serial, 'You reposted them.');
          if (activeBeefIds(state).has(post.authorId)) { result = { ok: true, message: 'You reposted your rival. The timeline is confused.' }; return; }
        }
        result = { ok: true, message: post.isPlayerPost ? 'Reposted.' : `Reposted ${post.authorName}. They noticed.` };
      });
      return result;
    },

    quotePost: (postId, text) => {
      let result: FeatureActionResult = { ok: false, message: 'Post not found.' };
      set((state) => {
        const p = state.player;
        if (!p || !text.trim()) return;
        const post = state.socialPosts.find((x) => x.id === postId);
        if (!post) return;
        if (!spendEnergy(state, ENERGY_COSTS.socialPost, { admin: true })) { result.message = energyShortfallMessage(ENERGY_COSTS.socialPost, p.energy); return; }
        const serial = dateToSerial(state.gameDate);
        const insulting = detectIntent(text) === 'insult';
        const stats = socialStatsOf(state);
        const r = postReach({ boost: socialBoost(state), app: 'chirp', kind: 'thought', followers: stats.chirp.followers, fame: blendedFame(p), momentum: p.career.momentum, postsToday: 0, taggedFame: [], controversy: insulting, craft: p.stats.charisma, roll: Math.random() });
        const quote: SocialPost = {
          id: uuidv4(), platform: 'chirp', authorId: 'player', authorName: p.artistName, content: text.trim(),
          likes: r.likes, shares: r.shares, comments: [], timestamp: new Date().toISOString(),
          isPlayerPost: true, trendingScore: insulting ? 60 : 15, daySerial: serial, quoteOf: post.id, kind: 'thought',
          target: { likes: r.likes, shares: r.shares, comments: r.comments, views: r.views }, postedMinute: gameMinute(state),
          growth: { likes: 0, shares: 0, comments: Math.min(10, Math.round(r.comments * 0.3)), views: 0, follows: Math.round(r.follows * 0.5), days: 3 },
        };
        quote.comments = socialComments(quote, 3, commentContext(state, insulting, `${serial}|${quote.id}`), quote.timestamp);
        state.socialPosts.unshift(quote);
        const npc = !post.isPlayerPost && !post.authorId.startsWith('fan:') ? state.npcs.find((n) => n.id === post.authorId) : undefined;
        if (npc) {
          if (insulting) {
            bumpRel(state, npc.id, -8, serial, 'You quote-tweeted them with an insult.');
            nudgeBeef(state, npc.id, 10, serial);
            if (npc.relationshipScore <= -25 && npc.role === 'artist') npcStartsBeef(state, npc as NPC, serial, 'you quote-tweeted them.');
            result = { ok: true, message: `Quoted ${npc.name}. That's going to start something.` };
            return;
          }
          bumpRel(state, npc.id, 1, serial, 'You quoted them.');
        } else if (post.authorId.startsWith('fan:') && insulting) {
          addMomentum(state, Math.random() < 0.5 ? 3 : -3);
        }
        result = { ok: true, message: 'Quoted.' };
      });
      return result;
    },

    commentOnPost: (postId, text, replyToCommentId) => {
      let result: FeatureActionResult = { ok: false, message: 'Post not found.' };
      set((state) => {
        const p = state.player;
        if (!p || !text.trim()) return;
        const post = state.socialPosts.find((x) => x.id === postId);
        if (!post) return;
        const serial = dateToSerial(state.gameDate);
        const now = new Date().toISOString();
        const fame = blendedFame(p);
        const mine: SocialComment = { id: uuidv4(), authorId: 'player', authorName: p.artistName, content: text.trim(), likes: Math.round(20 + fame * fame * 0.9 + fame * 8), timestamp: now };
        const parent = replyToCommentId ? post.comments.find((c) => c.id === replyToCommentId) : undefined;
        if (parent) (parent.replies ?? (parent.replies = [])).push(mine);
        else post.comments.push(mine);
        const intent = detectIntent(text);
        const minuteNow = gameMinute(state);
        const fbName = state.fanbaseName;
        /** People piling in under what you just said. */
        const storm = (holder: SocialComment, where: BuzzWhere, opName: string, count?: number) => {
          const list = holder.replies ?? (holder.replies = []);
          for (const r of replyStorm({ where, fame, seed: `${mine.id}|${where}`, playerName: p.artistName, opName, fanbaseName: fbName, count, gender: p.gender })) {
            list.push({ id: uuidv4(), authorId: r.authorId, authorName: r.authorName, content: r.content, likes: r.likes, timestamp: now, tone: r.tone });
          }
        };
        const fanPage = post.authorId.startsWith('fan:') || state.npcs.find((n) => n.id === post.authorId)?.role === 'fan_account';

        // Commenting on a fan's post: that fan's day is made, and everyone sees it.
        if (!parent && !post.isPlayerPost && fanPage) {
          const op = post.authorName.replace(/^@/, '');
          (mine.replies ?? (mine.replies = [])).push({ id: uuidv4(), authorId: post.authorId, authorName: post.authorName, content: fanScream(`${mine.id}|op`, p.artistName), likes: Math.round(60 + fame * 25), timestamp: now, tone: 'stan' });
          storm(mine, 'fanPost', op);
          const boost = Math.round(200 + fame * fame * 6);
          post.likes += boost;
          post.shares += Math.round(boost / 9);
          post.trendingScore = Math.min(100, post.trendingScore + 25);
          // The fan's friends show up in the main thread too.
          for (const r of replyStorm({ where: 'fanPost', fame, seed: `${mine.id}|top`, playerName: p.artistName, opName: op, fanbaseName: fbName, count: Math.min(6, 2 + Math.round(fame / 20)), gender: p.gender })) {
            post.comments.push({ id: uuidv4(), authorId: r.authorId, authorName: r.authorName, content: r.content, likes: r.likes, timestamp: now, tone: r.tone, minute: minuteNow + 2 });
          }
          addMomentum(state, 1);
          const stats = socialStatsOf(state);
          if (stats[post.platform]) stats[post.platform].followers += Math.round(20 + fame * 4);
          // They post the screenshot.
          const shot: SocialPost = {
            id: uuidv4(), platform: post.platform, authorId: post.authorId, authorName: post.authorName,
            content: pick3([`${p.artistName.toUpperCase()} COMMENTED ON MY POST 😭😭😭 I'm not okay`, `Screenshot this. ${p.artistName} replied to ME. Day one forever 🫡`, `Woke up and ${p.artistName} was in my comments?? 😭🙏🏾`], mine.id),
            likes: 0, shares: 0, comments: [], timestamp: now, isPlayerPost: false, trendingScore: 55, daySerial: serial, kind: 'thought',
            tags: [{ id: 'player', name: p.artistName }],
          } as SocialPost;
          livenPost(state, shot, { at: minuteNow + 15, heat: 1, audience: Math.round(2000 + fame * fame * 40) });
          state.socialPosts.unshift(shot);
          pushActivity(state, { kind: 'mention', text: `${op} posted about your comment 😭`, actorName: op, actorId: post.authorId, postId: shot.id, minute: minuteNow + 15 });
          result = { ok: true, message: `${op} lost their mind — and the whole comment section showed up.` };
          return;
        }

        // Replying to a fan.
        const target = parent ?? (post.isPlayerPost ? undefined : post);
        const targetId = parent ? parent.authorId : post.authorId;
        if (parent && targetId.startsWith('fan:')) {
          if (parent.tone === 'hater' || parent.tone === 'troll') {
            const won = Math.random() + p.stats.charisma / 200 > 0.7;
            addMomentum(state, won ? 2 : -2);
            parent.replies!.push({ id: uuidv4(), authorId: targetId, authorName: parent.authorName, content: won ? 'ok that was funny 😭' : 'he really replied to me 😂😂 ratio', likes: won ? 40 : 300, timestamp: now });
            result = { ok: true, message: won ? 'You cooked the hater. Fans are loving it.' : 'Replying to a hater made it worse. They are screenshotting it.' };
          } else {
            parent.replies!.push({ id: uuidv4(), authorId: targetId, authorName: parent.authorName, content: fanScream(`${serial}|${parent.id}`, p.artistName), likes: Math.round(60 + fame * 20), timestamp: now, tone: 'stan' });
            storm(parent, 'fanComment', parent.authorName, Math.max(3, Math.min(10, Math.round(3 + fame / 10))));
            addMomentum(state, 0.5);
            const stats = socialStatsOf(state);
            stats[post.platform].followers += Math.round(15 + fame * 2);
            result = { ok: true, message: 'The fan lost their mind. Fans love an artist who replies.' };
          }
          return;
        }

        // Commenting on (or replying to) an NPC.
        const npc = targetId !== 'player' && !targetId.startsWith('fan:') ? state.npcs.find((n) => n.id === targetId) : undefined;
        if (npc && target) {
          const beef = activeBeefIds(state).has(npc.id);
          const delta = intent === 'insult' ? -7 : intent === 'compliment' ? 2 : intent === 'apology' ? 3 : 1;
          bumpRel(state, npc.id, delta, serial, `You commented: "${text.slice(0, 40)}"`);
          if (intent === 'insult' || beef) nudgeBeef(state, npc.id, intent === 'insult' ? 8 : 3, serial);
          const reply = chatReply(npc as NPC, text, { playerFame: blendedFame(p), sentToday: 0, beef, seed: `${serial}|${post.id}` }, Math.random());
          if (reply.text) {
            const holder = parent ?? mine;
            (holder.replies ?? (holder.replies = [])).push({ id: uuidv4(), authorId: npc.id, authorName: npc.name, content: reply.text, likes: Math.round(50 + npc.fame * 20), timestamp: now, tone: 'artist' });
          }
          // The timeline notices two artists talking.
          if (npc.role === 'artist') storm(mine, 'artistPost', npc.name, Math.max(3, Math.min(12, Math.round(3 + (fame + npc.fame) / 14))));
          if (intent === 'insult' && npc.relationshipScore <= -25 && npc.role === 'artist') npcStartsBeef(state, npc as NPC, serial, 'you went at them in their comments.');
          result = { ok: true, message: reply.text ? `${npc.name} replied.` : (reply.note ?? `${npc.name} hasn't replied.`) };
          return;
        }
        if (post.isPlayerPost) storm(mine, 'ownPost', p.artistName, Math.max(2, Math.min(8, Math.round(2 + fame / 12))));
        result = { ok: true, message: 'Commented.' };
      });
      return result;
    },

    likeComment: (postId, commentId) =>
      set((state) => {
        const post = state.socialPosts.find((x) => x.id === postId);
        if (!post) return;
        const all = [...post.comments, ...post.comments.flatMap((c) => c.replies ?? [])];
        const c = all.find((x) => x.id === commentId);
        if (!c || c.liked) return;
        c.liked = true;
        c.likes += 1;
        if (!c.authorId.startsWith('fan:') && c.authorId !== 'player') bumpRel(state, c.authorId, 1, dateToSerial(state.gameDate));
      }),

    setFanbaseName: (name) =>
      set((state) => {
        const n = name.trim().slice(0, 28);
        if (n.length >= 2) state.fanbaseName = n;
      }),

    fanClubAction: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'Not now.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const club = fanClubOf(state);
        const a = FAN_ACTIONS[id];
        const serial = dateToSerial(state.gameDate);
        const since = serial - (club.used[id] ?? -999);
        if (since < a.cooldown) { result.message = `You did that ${since === 0 ? 'today' : `${since} day${since === 1 ? '' : 's'} ago`}. Again in ${a.cooldown - since} day${a.cooldown - since === 1 ? '' : 's'}.`; return; }
        if (p.career.fanbase < a.minFans) { result.message = `You need about ${a.minFans.toLocaleString()} fans for that — you have ${p.career.fanbase.toLocaleString()}.`; return; }
        const fame = blendedFame(p);
        const cost = fanCost(id, fame, costIndex(p.country));
        if (cost > p.career.money) { result.message = `That costs $${cost.toLocaleString()}.`; return; }
        const newest = state.songs.filter((x) => isSongReleased(x)).sort((x, y) => releaseSerialOf(state, y, serial) - releaseSerialOf(state, x, serial))[0];
        if (id === 'stream_party' && (!newest || serial - releaseSerialOf(state, newest, serial) > 60)) { result.message = 'A stream party needs something fresh — nothing out in the last two months.'; return; }
        if (id === 'listening' && !state.songs.some((x) => isVaultMaster(x))) { result.message = 'There\'s nothing unreleased to play them.'; return; }
        if (!spendEnergy(state, a.energy, { admin: id === 'reply' || id === 'shoutout' })) { result.message = energyShortfallMessage(a.energy, p.energy); return; }
        p.career.money -= cost;
        const page = sampleNpcs(baseNpcs(state), 1, (n) => n.role === 'fan_account' && n.country === p.country)[0];
        const r = fanAction(id, club, { fans: p.career.fanbase, fame, charisma: p.stats.charisma, city: p.city, pageName: page?.name ?? `@${fanbaseNameOf(state).toLowerCase().replace(/\s+/g, '')}hq`, roll: Math.random() });
        club.used[id] = serial;
        club.loyalty = Math.max(0, Math.min(100, club.loyalty + r.loyalty));
        club.hype = Math.max(0, Math.min(100, club.hype + r.hype));
        if (r.preHype) club.preHype = Math.min(40, (club.preHype ?? 0) + r.preHype);
        p.career.fanbase += r.fans;
        const st = socialStatsOf(state);
        st.snapgram.followers += Math.round(r.fans * 0.5); st.chirp.followers += Math.round(r.fans * 0.3); st.clip.followers += Math.round(r.fans * 0.2);
        if (r.momentum) addMomentum(state, r.momentum);
        if (r.reputation) p.career.reputation = Math.max(0, Math.min(100, p.career.reputation + r.reputation));
        if (r.push && newest) pushSong(state, newest.id, r.push, 7, 'Stream party');
        if (r.edge) for (const w of state.fanWars ?? []) if (w.status === 'active') { w.edge = Math.max(-50, Math.min(50, w.edge + r.edge)); w.log = [`Stream party: ${fanbaseNameOf(state)} ran the numbers up.`, ...w.log].slice(0, 12); }
        if (id === 'meetup' || id === 'giveaway') state.socialPosts.unshift({ id: uuidv4(), platform: 'snapgram', authorId: 'player', authorName: p.artistName, content: id === 'meetup' ? `${p.city} you showed UP today 😭❤️ ${fanbaseNameOf(state)} forever` : `Giveaway time 🎁 ${fanbaseNameOf(state)} this one's for you`, likes: Math.round(300 + fame * 80), shares: Math.round(30 + fame * 8), comments: [], timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 55, daySerial: serial, kind: 'photo' } as SocialPost);
        result = { ok: true, message: `${r.text}${cost ? ` (−$${cost.toLocaleString()})` : ''}` };
      });
      return result;
    },

    fanWarAction: (warId, action) => {
      let result: FeatureActionResult = { ok: false, message: 'That war is over.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const war = (state.fanWars ?? []).find((w) => w.id === warId && w.status === 'active');
        if (!war) return;
        const serial = dateToSerial(state.gameDate);
        if (war.lastSerial === serial && war.log[0]?.startsWith('You:')) { result.message = 'You already said something about this today.'; return; }
        if (!spendEnergy(state, 4, { admin: true })) { result.message = energyShortfallMessage(4, p.energy); return; }
        const m = fanWarMove(action, { intensity: war.intensity, edge: war.edge, charisma: p.stats.charisma, roll: Math.random() });
        war.intensity = m.intensity;
        war.edge = m.edge;
        war.lastSerial = serial;
        war.log = [`You: ${FANWAR_ACTIONS[action].label}. ${m.text}`, ...war.log].slice(0, 12);
        addMomentum(state, m.momentum);
        p.career.reputation = Math.max(0, Math.min(100, p.career.reputation + m.reputation));
        p.career.localFame = Math.min(100, p.career.localFame + m.fame);
        if (action === 'fuel') nudgeBeef(state, war.npcId, 6, serial);
        if (action === 'peace') bumpRel(state, war.npcId, 4, serial, 'You told your fans to stop the war.');
        state.socialPosts.unshift({
          id: uuidv4(), platform: 'chirp', authorId: 'player', authorName: p.artistName,
          content: action === 'rally' ? `${fanbaseNameOf(state)}, you already know what it is. 📢` : action === 'peace' ? `Love to my fans, but let's keep it about the music. Respect to ${war.theirFans}. 🕊️` : `Imagine being a ${war.npcName} fan and thinking this is a good point 😂`,
          likes: Math.round(200 + blendedFame(p) * 60), shares: Math.round(20 + blendedFame(p) * 6), comments: [], timestamp: new Date().toISOString(),
          isPlayerPost: true, trendingScore: 50, daySerial: serial, kind: 'thought',
        });
        result = { ok: true, message: m.text };
      });
      return result;
    },

    acceptInterview: (inviteId) => {
      let result: FeatureActionResult = { ok: false, message: 'That invitation is gone.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        if (state.activeInterview) { result.message = 'Finish the interview you\'re in first.'; return; }
        const inv = (state.interviewInvites ?? []).find((x) => x.id === inviteId && x.status === 'open');
        if (!inv) return;
        const outlet = outletsNow(state).find((o) => o.id === inv.outletId);
        if (!outlet) return;
        if (!spendEnergy(state, ENERGY_COSTS.interview, { admin: true })) { result.message = energyShortfallMessage(ENERGY_COSTS.interview, p.energy); return; }
        inv.status = 'accepted';
        startInterviewSession(state, outlet, inv.format as InterviewFormat, inv.fee, inv.id);
        for (const b of state.managerDesk ?? []) if (b.refId === inv.id) { b.status = 'done'; b.outcome = 'Accepted — you did the interview.'; }
        result = { ok: true, message: `You're on ${outlet.name}. ${outlet.host} is ready.` };
      });
      return result;
    },

    declineInterview: (inviteId) =>
      set((state) => {
        const inv = (state.interviewInvites ?? []).find((x) => x.id === inviteId && x.status === 'open');
        if (!inv) return;
        inv.status = 'declined';
        const rel = state.outletRel ?? (state.outletRel = {});
        rel[inv.outletId] = (rel[inv.outletId] ?? 0) - 1;
        for (const b of state.managerDesk ?? []) if (b.refId === inv.id) { b.status = 'done'; b.outcome = 'Declined.'; }
      }),

    pitchInterview: (outletId, format) => {
      let result: FeatureActionResult = { ok: false, message: 'They didn\'t answer.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        if (state.activeInterview) { result.message = 'Finish the interview you\'re in first.'; return; }
        const serial = dateToSerial(state.gameDate);
        if (state.lastPitchSerial === serial) { result.message = 'You already pitched yourself today. Try again tomorrow.'; return; }
        const outlet = outletsNow(state).find((o) => o.id === outletId);
        if (!outlet) return;
        const fame = blendedFame(p);
        if (fame < outlet.minFame - 10) { result.message = `${outlet.name} books artists around fame ${outlet.minFame}. You're not there yet.`; return; }
        state.lastPitchSerial = serial;
        const rel = state.outletRel?.[outlet.id] ?? 0;
        // A manager gets you through doors you can't open yourself.
        const boost = managerOf(state) ? 8 : 0;
        if (!pitchAccepted(outlet, fame + boost, rel, Math.random)) { result.message = `${outlet.name} passed — "schedule's full." Build your name or try another outlet.`; return; }
        if (!spendEnergy(state, ENERGY_COSTS.interview, { admin: true })) { result.message = energyShortfallMessage(ENERGY_COSTS.interview, p.energy); return; }
        const fmt = (outlet.formats.includes(format as InterviewFormat) ? format : outlet.formats[0]) as InterviewFormat;
        startInterviewSession(state, outlet, fmt, 0);
        result = { ok: true, message: `${outlet.name} said yes. You're on air.` };
      });
      return result;
    },

    answerInterview: (optionId) => {
      let result: { ok: boolean; reaction: string; done: boolean; record?: InterviewRecord; passed?: boolean } = { ok: false, reaction: '', done: false };
      set((state) => {
        const p = state.player;
        const ai = state.activeInterview;
        if (!p || !ai) return;
        const q = ai.questions[ai.idx];
        const o = q?.options.find((x) => x.id === optionId);
        if (!q || !o) return;
        const r = resolveAnswer(o, { charisma: p.stats.charisma, freestyle: p.stats.freestyle, lyricism: p.stats.lyricism, performance: p.stats.performance }, Math.random);
        ai.effects.push(r.effect);
        ai.transcript.push({ q: q.host, a: o.text, reaction: r.text, tag: o.tag, surprise: q.surprise, passed: r.passed });
        if (o.ends) ai.walked = true;
        ai.idx += 1;
        const done = !!o.ends || ai.idx >= ai.questions.length;
        result = { ok: true, reaction: r.text, done, passed: r.passed };
        if (done) {
          const rec = finishInterview(state);
          if (rec) result.record = rec;
        }
      });
      return result;
    },

    actOnBrief: (briefId, action) => {
      const st = get();
      const b = (st.managerDesk ?? []).find((x) => x.id === briefId);
      if (!b || b.status === 'done' || (!b.refId && b.kind !== 'pitch')) return { ok: false, message: 'That\'s already handled.' };
      let r: { ok: boolean; message: string } = { ok: false, message: 'Nothing happened.' };
      if (b.kind === 'show') {
        const offer = st.showOffers.find((o) => o.id === b.refId!);
        if (!offer || offer.status !== 'open') r = { ok: false, message: 'That offer is gone.' };
        else if (action === 'accept') r = st.acceptShowOffer(b.refId!);
        else if (action === 'decline') r = st.declineShowOffer(b.refId!, 'none', true);
        else r = st.counterShowOffer(b.refId!, { ...offer.terms, fee: b.counterAt ?? Math.round(offer.fair) });
      } else if (b.kind === 'feature') {
        if (action === 'accept') r = st.acceptInboundOffer(b.refId!);
        else if (action === 'decline') r = st.declineInboundRequest(b.refId!);
        else r = st.quoteInboundVerse(b.refId!, b.counterAt ?? 0);
      } else if (b.kind === 'interview') {
        if (action === 'accept') r = st.acceptInterview(b.refId!);
        else { st.declineInterview(b.refId!); r = { ok: true, message: 'Declined.' }; }
      } else if (b.kind === 'pitch') {
        if (action === 'accept') r = st.acceptPitch(briefId);
        else {
          r = { ok: true, message: 'Passed.' };
          // Turning down somebody who said yes is noticed.
          const npcId = String(b.data?.npcId ?? '');
          if (npcId) set((state) => { const n = state.npcs.find((x) => x.id === npcId); if (n) n.relationshipScore = Math.max(-100, n.relationshipScore - 2); });
        }
      }
      set((state) => {
        const brief = (state.managerDesk ?? []).find((x) => x.id === briefId);
        if (!brief) return;
        // A counter keeps it open — the other side still has to answer.
        if (action === 'counter' && r.ok) { brief.status = 'seen'; brief.outcome = r.message; return; }
        if (r.ok) { brief.status = 'done'; brief.outcome = r.message; }
      });
      return r;
    },

    acceptPitch: (briefId) => {
      let result: { ok: boolean; message: string } = { ok: false, message: 'That has gone.' };
      let payFor: string | null = null;
      set((state) => {
        const p = state.player;
        const b = (state.managerDesk ?? []).find((x) => x.id === briefId);
        if (!p || !b || b.kind !== 'pitch' || b.status === 'done') return;
        const serial = dateToSerial(state.gameDate);
        if (b.expiresSerial !== undefined && serial > b.expiresSerial) {
          b.status = 'done';
          b.outcome = 'Lapsed — they moved on.';
          result = { ok: false, message: 'That lapsed. They moved on.' };
          return;
        }
        const d = b.data ?? {};
        const fee = Math.max(0, Math.round(Number(d.fee ?? 0)));
        const mgr = managerOf(state);
        switch (b.pitch) {
          case 'big_feature':
          case 'abroad_feature': {
            const npc = state.npcs.find((n) => n.id === d.npcId);
            const song = state.songs.find((x) => x.id === d.songId);
            if (!npc || !song) return;
            if (isSongReleased(song)) { result = { ok: false, message: `"${song.title}" is already out — too late for a verse.` }; return; }
            if (p.career.money < fee) { result = { ok: false, message: `You need $${fee.toLocaleString()} for ${npc.name}'s verse.` }; return; }
            const req: FeatureRequest = {
              id: uuidv4(), songId: song.id, songTitle: song.title, npcId: npc.id, npcName: npc.name, status: 'terms',
              sentDate: formatGameDate(state.gameDate), dueDate: formatGameDate(state.gameDate), fee, freeVerse: false,
              reason: `${mgr?.name ?? 'Your manager'} arranged it with ${isRealId(npc.id) ? `${npc.name}'s team` : npc.name}.`, originalFee: fee,
            };
            state.featureRequests.push(req);
            attachTerms(state, req, npc as NPC, baseNpcs(state), serial);
            payFor = req.id;
            result = { ok: true, message: `Paid. ${npc.name} is recording a verse for "${song.title}" — track it in Studio → Features.${req.conditions?.length ? ` Their terms: ${req.conditions.map((c) => c.text.replace(/^📨[^:]+: /, '')).join(' ')}` : ''}` };
            break;
          }
          case 'brand': {
            const kind = String(d.kind ?? 'brand');
            const months = Number(d.months ?? 6);
            p.career.money += fee;
            p.career.totalEarnings += fee;
            const rep = Number(d.rep ?? 0);
            p.career.reputation = Math.max(0, Math.min(100, p.career.reputation + rep));
            addMomentum(state, rep < 0 ? 1 : 2);
            if (rep < 0) p.career.fanbase = Math.max(0, Math.round(p.career.fanbase * (1 + rep / 200)));
            const flags = state.lifeFlags ?? (state.lifeFlags = {});
            flags[`brand:${kind}`] = serial + months * 30;
            state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} signs with ${String(d.brand)}`, fullStory: `A ${months}-month ambassador deal with the ${kind} brand.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: blendedFame(p) >= 30 ? 5 : 3, category: 'business' });
            remember(state, 'money', `You signed a ${months}-month deal with ${String(d.brand)} for $${fee.toLocaleString()}.`, { weight: 3, tone: rep < 0 ? 'bad' : 'good' });
            result = { ok: true, message: `Signed. $${fee.toLocaleString()} is in your account.${rep < 0 ? ' The comments are not all kind.' : ''}` };
            break;
          }
          case 'sync': {
            const song = state.songs.find((x) => x.id === d.songId);
            if (!song) return;
            p.career.money += fee;
            p.career.totalEarnings += fee;
            pushSong(state, song.id, 0.5 + Math.max(0, song.quality - 55) / 120, 18, `Synced in ${String(d.where ?? 'a film')}`);
            p.career.fanbase += Math.round(200 + blendedFame(p) * 12);
            addMomentum(state, 2);
            remember(state, 'career', `"${song.title}" was placed in ${String(d.where ?? 'a film')}.`, { weight: 3, tone: 'good' });
            result = { ok: true, message: `Done. $${fee.toLocaleString()} in, and "${song.title}" is about to find a new audience.` };
            break;
          }
          case 'intro': {
            const npc = state.npcs.find((n) => n.id === d.npcId);
            if (!npc) return;
            const at = Number(d.atMinute ?? 0);
            if (at <= nowMinuteOf(state)) { result = { ok: false, message: 'That meeting time has passed.' }; return; }
            if ((state.appointments ?? []).some((x) => x.status === 'confirmed' && Math.abs(x.atMinute - at) < 120)) { result = { ok: false, message: 'You already have something at that time. Clear it first.' }; return; }
            const real = isRealId(npc.id);
            const a = createAppointment(state, npc as NPC, 'meeting', at, 'npc', 'confirmed', {
              title: `Meeting with ${real ? `${npc.name}'s team` : npc.name}`,
              place: real ? `${npc.name}'s team's office, ${npc.city ?? npc.country}` : `a private studio in ${npc.city ?? npc.country}`,
              pitch: { starId: npc.id, starName: npc.name, real, fame: Math.round(npc.fame) },
            });
            remember(state, 'career', `${mgr?.name ?? 'Your manager'} got you a meeting with ${real ? `${npc.name}'s team` : npc.name}.`, { npcIds: [npc.id], weight: 3, tone: 'good' });
            result = { ok: true, message: `Locked in: ${whenLabel(a.atMinute, nowMinuteOf(state))} at ${a.place}. Bring your best record.` };
            break;
          }
          case 'producer': {
            const npc = state.npcs.find((n) => n.id === d.npcId);
            if (!npc) return;
            if (p.career.money < fee) { result = { ok: false, message: `You need $${fee.toLocaleString()} for the beat.` }; return; }
            p.career.money -= fee;
            const days = Math.max(2, Number(d.days ?? 4));
            beatsOf(state).orders.push({
              id: uuidv4(), producerId: npc.id, producerName: npc.name, genre: p.genre, bpm: GENRE_BY_ID[p.genre]?.bpm ?? 95, mood: 'defiant',
              fee, orderedSerial: serial, dueSerial: serial + days, inHouse: false,
            });
            npc.relationshipScore = Math.min(100, npc.relationshipScore + 4);
            result = { ok: true, message: `${npc.name} is building it. Ready in ${days} days — it lands in Studio → Beats.` };
            break;
          }
          default:
            return;
        }
        b.status = 'done';
        b.outcome = result.message;
      });
      if (payFor) {
        const ok = get().payFeatureFee(payFor);
        if (!ok) {
          result = { ok: false, message: 'The payment did not go through.' };
          set((state) => { const r = state.featureRequests.find((x) => x.id === payFor); if (r) r.status = 'declined'; const b = (state.managerDesk ?? []).find((x) => x.id === briefId); if (b) { b.status = 'seen'; b.outcome = undefined; } });
        }
      }
      return result;
    },

    runAutopilot: () => {
      const auto = (get().managerDesk ?? []).filter((b) => b.auto && b.status !== 'done');
      for (const b of auto) {
        const r = get().actOnBrief(b.id, 'accept');
        set((state) => {
          const x = (state.managerDesk ?? []).find((y) => y.id === b.id);
          if (!x) return;
          x.auto = false;
          const mgr = managerOf(state);
          if (r.ok) {
            x.status = 'done';
            x.outcome = `Accepted for you (your rule) — ${r.message}`;
            if (mgr) pushDM(state, mgr.id, { fromPlayer: false, content: `✅ Took it for you, like you told me to: ${x.title}. ${r.message}` });
          } else if (mgr) {
            pushDM(state, mgr.id, { fromPlayer: false, content: `I tried to lock in ${x.title} for you but it didn't go through: ${r.message} It's on the desk.` });
          }
        });
      }
    },

    setTeamPolicy: (patch) =>
      set((state) => {
        const next = { ...policyOf(state.teamPolicy), ...patch };
        next.minShowFee = Math.max(0, Math.round(Number(next.minShowFee) || 0));
        next.cashFloor = Math.max(0, Math.round(Number(next.cashFloor) || 0));
        next.restDay = Math.max(-1, Math.min(6, Math.round(Number(next.restDay))));
        state.teamPolicy = next;
      }),

    pushManager: (kind) => {
      let result = { ok: false, message: 'You have no manager to push.' };
      set((state) => {
        const mgr = managerOf(state);
        if (!mgr || !state.player) return;
        const serial = dateToSerial(state.gameDate);
        if (state.managerPush && state.managerPush.until >= serial && state.managerPush.kind === kind) {
          result = { ok: false, message: `${mgr.name.split(' ')[0]} is already pushing for that.` };
          return;
        }
        state.managerPush = { kind, until: serial + 30 };
        const sp = SPECIALTIES[managerSpecialty(mgr)];
        const lane = (kind === 'shows' && (sp.id === 'booker' || sp.id === 'global')) || (kind === 'features' && sp.id === 'connector') || (kind === 'deals' && sp.id === 'dealmaker');
        pushDM(state, mgr.id, { fromPlayer: false, content: lane ? `On it. ${kind === 'shows' ? 'Dates' : kind === 'features' ? 'Features' : 'Deals'} are what I do — give me a few weeks.` : `I'll try. It's not really my lane — ${sp.tagline.toLowerCase()} is — but I know people who know people.` });
        result = { ok: true, message: `${mgr.name.split(' ')[0]} will push for ${kind} over the next month.` };
      });
      return result;
    },

    markDeskSeen: () =>
      set((state) => {
        for (const b of state.managerDesk ?? []) if (b.status === 'new') b.status = 'seen';
      }),

    deleteThread: (npcId) =>
      set((state) => {
        // A thread with a question still waiting keeps the question — it just loses the history.
        delete state.dmThreads[npcId];
        for (const m of state.moments ?? []) if (m.npcId === npcId && m.channel === 'dm' && m.status === 'open') m.status = 'expired';
      }),

    clearReadThreads: () =>
      set((state) => {
        for (const [id, t] of Object.entries(state.dmThreads)) {
          const waiting = (state.moments ?? []).some((m) => m.npcId === id && m.channel === 'dm' && m.status === 'open');
          if (t.unread === 0 && !waiting) delete state.dmThreads[id];
        }
      }),

    followAccount: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'Account not found.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const list = raw(state.npcs) as NPC[];
        const npc = npcIndex(list).get(npcId);
        if (!npc) return;
        const following = followingOf(state, list);
        if (following.includes(npcId)) { result.message = `You already follow ${npc.name}.`; return; }
        if (isBlocked(state, npcId)) state.blocked = (state.blocked ?? []).filter((x) => x !== npcId);
        state.following = [...following, npcId];
        const minute = gameMinute(state);
        const fame = blendedFame(p);
        const by = state.followedBy ?? (state.followedBy = []);
        const beef = activeBeefIds(state).has(npcId);
        // Will they follow back? Friends do; much bigger names mostly don't.
        const odds = Math.max(0.02, Math.min(0.9, 0.25 + npc.relationshipScore / 120 - Math.max(0, npc.fame - fame) / 60 - (beef ? 0.5 : 0)));
        const back = !by.includes(npcId) && Math.random() < odds;
        if (back) {
          by.push(npcId);
          pushActivity(state, { kind: 'follow', text: `${npc.name} followed you back`, actorId: npc.id, actorName: npc.name, minute: minute + 20 + Math.floor(Math.random() * 400) });
          bumpRel(state, npcId, 2, dateToSerial(state.gameDate));
        }
        if (beef) {
          nudgeBeef(state, npcId, -6, dateToSerial(state.gameDate));
          result = { ok: true, message: `You followed ${npc.name} — mid-beef. Fans are reading it as an olive branch.` };
          return;
        }
        result = { ok: true, message: `Following ${npc.name}. Their posts show in your Following feed.` };
      });
      return result;
    },

    unfollowAccount: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'Account not found.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const list = raw(state.npcs) as NPC[];
        const npc = npcIndex(list).get(npcId);
        if (!npc) return;
        const following = followingOf(state, list);
        if (!following.includes(npcId)) { result.message = `You don't follow ${npc.name}.`; return; }
        state.following = following.filter((x) => x !== npcId);
        const serial = dateToSerial(state.gameDate);
        const minute = gameMinute(state);
        const followsYou = (state.followedBy ?? []).includes(npcId);
        // People notice an unfollow — the closer they were, the more it stings.
        const noticed = followsYou && Math.random() < 0.35 + npc.relationshipScore / 200;
        if (!noticed) { result = { ok: true, message: `Unfollowed ${npc.name}. Nobody seems to have noticed. Yet.` }; return; }
        bumpRel(state, npcId, -(npc.relationshipScore >= 40 ? 8 : 4), serial, 'You unfollowed them.');
        const unfollowBack = Math.random() < 0.55;
        if (unfollowBack) {
          state.followedBy = (state.followedBy ?? []).filter((x) => x !== npcId);
          pushActivity(state, { kind: 'unfollow', text: `${npc.name} unfollowed you back`, actorId: npcId, actorName: npc.name, minute: minute + 30 + Math.floor(Math.random() * 300) });
        }
        if (npc.fame >= 35 && blendedFame(p) >= 15 && Math.random() < 0.5) {
          const post: SocialPost = { id: uuidv4(), platform: 'chirp', authorId: 'scene_watch', authorName: 'Scene Watch', content: `👀 ${p.artistName} and ${npc.name} ${unfollowBack ? 'have unfollowed each other' : `— ${p.artistName} just unfollowed`}. Something happened.`, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 65, tags: [{ id: 'player', name: p.artistName }] };
          livenPost(state, post, { at: minute + 60, heat: 1.5 });
          state.socialPosts.unshift(post);
          addMomentum(state, 1);
          if (activeBeefIds(state).has(npcId)) nudgeBeef(state, npcId, 5, serial);
          else if (npc.relationshipScore < 0 && npc.role === 'artist') sparkFanWar(state, npc as NPC, `${p.artistName} unfollowed ${npc.name} and the fans are picking sides.`, serial, 14);
          result = { ok: true, message: `${npc.name} noticed${unfollowBack ? ' and unfollowed you back' : ''}. A blog picked it up.` };
          return;
        }
        result = { ok: true, message: `${npc.name} noticed${unfollowBack ? ' and unfollowed you back' : ''}.` };
      });
      return result;
    },

    blockAccount: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'Account not found.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const list = raw(state.npcs) as NPC[];
        const npc = npcIndex(list).get(npcId);
        if (!npc) return;
        if (isBlocked(state, npcId)) { result.message = `${npc.name} is already blocked.`; return; }
        state.blocked = [...(state.blocked ?? []), npcId];
        state.following = followingOf(state, list).filter((x) => x !== npcId);
        state.followedBy = (state.followedBy ?? []).filter((x) => x !== npcId);
        const serial = dateToSerial(state.gameDate);
        bumpRel(state, npcId, -15, serial, 'You blocked them.');
        // Their pending moments go quiet.
        for (const m of state.moments ?? []) if (m.npcId === npcId && (m.status === 'open' || m.status === 'scheduled')) m.status = 'expired';
        // A public figure finds out sooner or later.
        if (npc.fame >= 30 && Math.random() < 0.4) {
          const post: SocialPost = { id: uuidv4(), platform: 'chirp', authorId: 'scene_watch', authorName: 'Scene Watch', content: `${npc.name} says ${p.artistName} blocked them 😳 The screenshots are everywhere.`, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 70, tags: [{ id: 'player', name: p.artistName }] };
          livenPost(state, post, { at: gameMinute(state) + 120, heat: 2 });
          state.socialPosts.unshift(post);
          addMomentum(state, 2);
          if (activeBeefIds(state).has(npcId)) nudgeBeef(state, npcId, 10, serial);
          else if (npc.relationshipScore <= -35 && npc.role === 'artist') npcStartsBeef(state, npc as NPC, serial, 'you blocked them and they made it public.');
          result = { ok: true, message: `Blocked ${npc.name}. They found out and posted the screenshot.` };
          return;
        }
        result = { ok: true, message: `Blocked ${npc.name}. Their posts, comments, tags and messages won't reach you.` };
      });
      return result;
    },

    unblockAccount: (npcId) =>
      set((state) => {
        state.blocked = (state.blocked ?? []).filter((x) => x !== npcId);
      }),

    loadMoreComments: (postId) =>
      set((state) => {
        const post = state.socialPosts.find((x) => x.id === postId);
        if (!post) return;
        const live = liveCounts(post, gameMinute(state)).comments;
        const room = Math.min(80, live) - post.comments.length;
        if (room <= 0) return;
        const npc = npcIndex(raw(state.npcs) as NPC[]).get(post.authorId);
        const ctx = post.isPlayerPost
          ? commentContext(state, post.trendingScore >= 60, `${gameMinute(state)}|${post.id}|more`)
          : { fame: npc?.fame ?? 30, reputation: 60, controversy: post.trendingScore >= 60, artistFriends: [], seed: `${gameMinute(state)}|${post.id}|more` };
        post.comments.push(...socialComments(post, Math.min(10, room), ctx, new Date().toISOString()).map((c, i) => ({ ...c, id: `${c.id}-m${post.comments.length + i}` })));
      }),

    markActivityRead: () =>
      set((state) => {
        const minute = gameMinute(state);
        for (const a of state.socialActivity ?? []) if (a.minute <= minute) a.read = true;
      }),

    postStory: (kind, songId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to post.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const k = STORY_KINDS.find((x) => x.id === kind);
        if (!k) return;
        const song = songId ? state.songs.find((s) => s.id === songId && isSongReleased(s)) : undefined;
        if ('needsSong' in k && k.needsSong && !song) { result.message = 'A teaser needs one of your released songs.'; return; }
        if (!spendEnergy(state, k.energy, { admin: true })) { result.message = energyShortfallMessage(k.energy, p.energy); return; }
        const minute = gameMinute(state);
        const serial = dateToSerial(state.gameDate);
        const stats = socialStatsOf(state);
        const reach = Math.round(stats.snapgram.followers * (0.15 + Math.random() * 0.2) * (1 + p.career.momentum / 200));
        const stories = state.stories ?? (state.stories = []);
        stories.unshift({
          id: uuidv4(), authorId: 'player', authorName: p.artistName, postedMinute: minute, views: reach, reach, kind,
          frames: k.frames.map((emoji, i) => ({ emoji, bg: `${kind}|${minute}|${i}`, songTitle: i === 0 && song ? song.title : undefined, text: i === 0 ? k.label : undefined })),
        });
        const notes: string[] = [`${reach.toLocaleString()} people will see it.`];
        stats.snapgram.followers += Math.round(reach * 0.01);
        switch (kind) {
          case 'studio': socialMomentum(state, 1); notes.push('Fans love a peek at the process.'); break;
          case 'teaser':
            if (song) {
              socialMomentum(state, 2);
              song.weeklyStreams += Math.round(reach * 0.05);
              notes.push(`A few thousand went and played "${song.title}".`);
            }
            break;
          case 'night': {
            const friend = (raw(state.npcs) as NPC[]).find((n) => n.role === 'artist' && n.relationshipScore >= 35 && !isBlocked(state, n.id) && Math.random() < 0.05);
            if (friend) { bumpRel(state, friend.id, 3, serial, 'You tagged them in your story.'); notes.push(`You tagged ${friend.name} — they reposted it.`); }
            break;
          }
          case 'bts': socialMomentum(state, 1); break;
          case 'qa': p.career.reputation = Math.min(100, p.career.reputation + 0.8); notes.push('Hundreds of questions. Answering a few built real loyalty.'); break;
          case 'flex':
            if (Math.random() < 0.55) { p.career.localFame = Math.min(100, p.career.localFame + 0.3); notes.push('The flex landed.'); }
            else { p.career.reputation = Math.max(0, p.career.reputation - 1); notes.push('Some of the replies called it tone-deaf.'); }
            break;
        }
        pushActivity(state, { kind: 'story', text: `Your story reached ${reach.toLocaleString()} people`, minute: minute + 180 });
        result = { ok: true, message: `Story is up. ${notes.join(' ')}` };
      });
      return result;
    },

    viewStory: (storyId) =>
      set((state) => {
        const s = (state.stories ?? []).find((x) => x.id === storyId);
        if (s) s.seen = true;
      }),

    goLive: (app) => {
      let result: { ok: boolean; message: string; session?: LiveSession } = { ok: false, message: 'You can\'t go live right now.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const serial = dateToSerial(state.gameDate);
        if (state.lastLive && state.lastLive.serial === serial) { result.message = 'You already went live today. Leave them wanting more.'; return; }
        if (!spendEnergy(state, 12, { admin: true })) { result.message = energyShortfallMessage(12, p.energy); return; }
        const stats = socialStatsOf(state);
        const list = raw(state.npcs) as NPC[];
        const friends = list.filter((n) => n.role === 'artist' && n.relationshipScore >= 40 && !isBlocked(state, n.id) && (!isRealId(n.id) || n.relationshipScore >= 60));
        const guest = friends.length && Math.random() < 0.35 ? friends[Math.floor(Math.random() * friends.length)] : undefined;
        const loyalty = fanbaseOf(state).loyalty;
        const s = liveSession({ app, followers: stats[app].followers, momentum: p.career.momentum, charisma: p.stats.charisma, loyalty, guest: guest ? { id: guest.id, name: guest.name, fame: guest.fame } : undefined, roll: Math.random(), minute: gameMinute(state) });
        p.career.money += s.gifts;
        if (s.gifts > 0) p.career.totalEarnings += s.gifts;
        stats[app].followers += s.follows;
        addMomentum(state, s.trolls ? -1 : 3);
        if (s.trolls) p.career.reputation = Math.max(0, p.career.reputation - 1);
        p.stats.charisma = Math.min(100, p.stats.charisma + 0.4);
        if (guest) bumpRel(state, guest.id, 4, serial, 'They joined your live.');
        state.lastLive = { ...s, serial };
        result = { ok: true, message: s.lines.join(' '), session: s };
      });
      return result;
    },

    buyBeat: (listingId, license) => {
      let result: FeatureActionResult = { ok: false, message: 'That beat is gone.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const b = beatsOf(state);
        const l = b.store.find((x) => x.id === listingId);
        if (!l || l.sold) return;
        const price = license === 'lease' ? l.lease : l.exclusive;
        if (p.career.money < price) { result.message = `That ${license} is $${price.toLocaleString()}. You have $${Math.floor(p.career.money).toLocaleString()}.`; return; }
        p.career.money -= price;
        l.sold = true;
        const serial = dateToSerial(state.gameDate);
        b.library.unshift({
          id: `beat:${l.id}:${license}`,
          name: l.name,
          quality: license === 'lease' ? Math.max(15, l.quality - LEASE_PENALTY) : l.quality,
          genre: l.genre, bpm: l.bpm, mood: l.mood,
          producerId: l.producerId, producerName: l.producerName,
          source: 'store', license, acquiredSerial: serial, price,
        });
        trimLibrary(b);
        const npc = state.npcs.find((n) => n.id === l.producerId);
        if (npc) npc.relationshipScore = Math.min(100, npc.relationshipScore + (license === 'exclusive' ? 3 : 1));
        result = { ok: true, message: `"${l.name}" is yours (${license}, $${price.toLocaleString()}). It's in your beat library.` };
      });
      return result;
    },

    orderBeat: (opts) => {
      let result: FeatureActionResult = { ok: false, message: 'Nobody to make it.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const b = beatsOf(state);
        const npc = state.npcs.find((n) => n.id === opts.producerId);
        if (!npc) return;
        const member = (state.crew ?? []).find((c) => c.npcId === npc.id && (c.role === 'producer' || c.role === 'engineer'));
        const skill = member ? member.skill : producerSkillOf(npc as NPC);
        if (b.orders.filter((o) => o.producerId === npc.id).length >= (member ? 2 : 1)) { result.message = `${npc.name} is already working on something for you.`; return; }
        const q = orderQuote(skill, !!member);
        const tier = buildingTier(state.studio?.levels);
        const days = Math.max(1, Math.round(q.days / (member ? tier.beatSpeed : 1)));
        if (!member) {
          if (activeBeefIds(state).has(npc.id)) { result.message = `${npc.name} won't work with you right now.`; return; }
          if (!takesOrder(npc as NPC, blendedFame(p), Math.random())) {
            result.message = `${npc.name}'s team passed — "fully booked". Build the relationship first, or try someone closer to your level.`;
            return;
          }
          if (p.career.money < q.fee) { result.message = `${npc.name} charges $${q.fee.toLocaleString()} for a custom beat.`; return; }
          p.career.money -= q.fee;
        }
        const serial = dateToSerial(state.gameDate);
        b.orders.push({
          id: uuidv4(), producerId: npc.id, producerName: npc.name, genre: opts.genre, bpm: opts.bpm, mood: opts.mood,
          forTitle: opts.forTitle?.trim() || undefined, fee: member ? 0 : q.fee, orderedSerial: serial, dueSerial: serial + days, inHouse: !!member,
        });
        result = { ok: true, message: `${npc.name} is on it${opts.forTitle ? ` — a beat for "${opts.forTitle.trim()}"` : ''}. Ready in ${days} day${days === 1 ? '' : 's'}${member ? ' (your team, no fee)' : ` ($${q.fee.toLocaleString()})`}.` };
      });
      return result;
    },

    redoBeat: (beatId) => {
      let result: FeatureActionResult = { ok: false, message: 'That beat is not in your library.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const b = beatsOf(state);
        const beat = b.library.find((x) => x.id === beatId);
        if (!beat || !beat.producerId) return;
        if (beat.usedOnSongId) { result.message = 'That beat is already on a record.'; return; }
        if (beat.source === 'store') { result.message = 'Store beats are sold as they are. Order a custom one instead.'; return; }
        if (b.orders.some((o) => o.redoOf === beat.id)) { result.message = 'A redo is already on the way.'; return; }
        const member = (state.crew ?? []).find((c) => c.npcId === beat.producerId);
        const npc = state.npcs.find((n) => n.id === beat.producerId);
        const skill = member ? member.skill : npc ? producerSkillOf(npc as NPC) : 50;
        const q = orderQuote(skill, !!member);
        const fee = member ? 0 : Math.round(q.fee * 0.5 / 10) * 10;
        if (p.career.money < fee) { result.message = `A redo costs $${fee.toLocaleString()}.`; return; }
        p.career.money -= fee;
        // Asking for a third and fourth go wears on people.
        if ((beat.redos ?? 0) >= 2 && npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 2);
        const serial = dateToSerial(state.gameDate);
        const days = Math.max(1, Math.round(q.days * 0.6));
        b.orders.push({ id: uuidv4(), producerId: beat.producerId, producerName: beat.producerName, genre: beat.genre, bpm: beat.bpm, mood: beat.mood, forTitle: beat.forTitle, fee, orderedSerial: serial, dueSerial: serial + days, inHouse: !!member, redoOf: beat.id });
        result = { ok: true, message: `${beat.producerName} will take another pass. ${days} day${days === 1 ? '' : 's'}${fee ? `, $${fee.toLocaleString()}` : ''}.${(beat.redos ?? 0) >= 2 ? ' They are starting to sigh.' : ''}` };
      });
      return result;
    },

    discardBeat: (beatId) =>
      set((state) => {
        const b = beatsOf(state);
        b.library = b.library.filter((x) => x.id !== beatId || !!x.usedOnSongId);
      }),

    upgradeStudioBuilding: () => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to build.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        if (!state.studio) state.studio = { levels: {} };
        if (!state.studio.levels) state.studio.levels = {};
        const cur = buildingLevel(state.studio.levels);
        const next = HOME_STUDIO_TIERS[cur + 1];
        if (!next) { result.message = 'You already own the best room in the country.'; return; }
        if (p.career.money < next.build) { result.message = `The ${next.name} costs $${next.build.toLocaleString()} to build. You have $${Math.floor(p.career.money).toLocaleString()}.`; return; }
        p.career.money -= next.build;
        state.studio.levels.building = next.level;
        if (next.level >= 3) {
          p.career.reputation = Math.min(100, p.career.reputation + (next.level === 4 ? 4 : 2));
          state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} opens a ${next.name.toLowerCase()}`, fullStory: `${p.artistName} has built ${next.level === 4 ? 'one of the biggest recording complexes in the country' : 'a full professional studio'}. Artists are already asking for time in it.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 5, category: 'business' });
        }
        state.lastEventLog.unshift(`🏗️ ${next.emoji} Your ${next.name.toLowerCase()} is built — $${next.build.toLocaleString()}. Upkeep is $${next.upkeep.toLocaleString()}/month.`);
        result = { ok: true, message: `${next.emoji} ${next.name} built. ${next.perks.join(' · ')}. Upkeep $${next.upkeep.toLocaleString()} a month.` };
      });
      return result;
    },

    setStudioRentOut: (on) =>
      set((state) => {
        if (!state.studio) state.studio = { levels: {} };
        state.studio.rentOut = on;
      }),

    sendGift: (npcId, tier) => {
      let result: FeatureActionResult = { ok: false, message: 'They are not reachable.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!npc) return;
        const gifts = { flowers: { cost: 150, rel: 3, label: 'flowers and a note' }, bottle: { cost: 800, rel: 6, label: 'a bottle of something expensive' }, chain: { cost: 6000, rel: 12, label: 'a custom chain' } } as const;
        const g = gifts[tier];
        if (p.career.money < g.cost) { result.message = `That costs $${g.cost.toLocaleString()}.`; return; }
        const serial = dateToSerial(state.gameDate);
        // A gift is a gesture — the second one in a week is a bribe.
        const recent = npc.lastReachOut !== undefined && serial - npc.lastReachOut < 7;
        p.career.money -= g.cost;
        const t = traitsOf(npc as NPC);
        let delta = recent ? Math.round(g.rel / 3) : g.rel;
        if (activeBeefIds(state).has(npc.id)) delta = Math.random() < 0.4 ? 6 : -2;
        if (t.diva && tier === 'flowers') delta = 1;
        npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + delta));
        npc.lastReachOut = serial;
        npc.memoryLog = [...(npc.memoryLog ?? []).slice(-9), `You sent ${g.label}.`];
        const thread = state.dmThreads[npcId] ?? { npcId, messages: [], unread: 0 };
        thread.messages.push({ id: uuidv4(), npcId, fromPlayer: true, content: `🎁 Sent ${g.label}.`, timestamp: new Date().toISOString(), read: true });
        const reply = isRealId(npc.id) ? null : delta >= 6 ? 'Yo this is too much 😭 thank you fr' : delta > 0 ? 'Appreciate it 🙏' : 'Is this supposed to fix things?';
        if (reply) { thread.messages.push({ id: uuidv4(), npcId, fromPlayer: false, content: reply, timestamp: new Date().toISOString(), read: false }); thread.unread += 1; }
        state.dmThreads[npcId] = thread;
        result = { ok: true, message: recent ? `${npc.name} appreciated it, but a second gift this week reads as trying too hard (+${delta}).` : `${npc.name} got ${g.label} (${delta >= 0 ? '+' : ''}${delta}).` };
      });
      return result;
    },


    // ─── THE FEED ───────────────────────────────────────────────────────
    //
    // The feed used to change on exactly one schedule: the weekly boundary. A
    // "refresh" control on top of that could only ever be decoration. This
    // generates a batch from what is TRUE right now — the chart that was just
    // published, the artists who have records out, the arguments running in the
    // world and the player's own — and it is stamped against the game clock, so
    // the cooldown is real and closing the tab does not clear it.
    //
    // It is an ACTION and not a render, which is the only way this can work:
    // a feed that re-rolls itself every time the screen opens is a feed that
    // shows the player a different world every time they look at it.
    refreshFeed: (app) => {
      let outcome: FeedRefreshResult = { ok: false, message: '', added: 0, waitMinutes: 0 };

      set((state) => {
        if (!state.player) {
          outcome = { ok: false, message: 'There is no career to refresh.', added: 0, waitMinutes: 0 };
          return;
        }

        const now = gameMinute(state);
        const cooldown = feedCooldown(state);
        if (!cooldown.ready) {
          outcome = {
            ok: false,
            message: `Nothing new since the last pull. Give it ${cooldown.waitMinutes} more game minutes.`,
            added: 0,
            waitMinutes: cooldown.waitMinutes,
          };
          return;
        }

        const today = dateToSerial(state.gameDate);
        const npcs = raw(state.npcs) as NPC[];
        const npcSongs = raw(state.npcSongs) as Song[];
        const charts = state.charts as Record<string, ChartEntry[]>;
        const fresh: SocialPost[] = [];

        // The outlet that reports on the scene. One lookup, not a scan per post.
        const outlet = npcs.find(n => n.role === 'media');
        const outletId = outlet?.id ?? 'scene_watch';
        const outletName = outlet?.name ?? 'Scene Watch';

        // 1. The charts, if they have anything to say.
        const home = charts[state.player.country] ?? [];
        let mover: ChartEntry | undefined;
        let bestJump = 0;
        for (const entry of home) {
          const jump = (entry.lastPosition ?? 0) - entry.position;
          if (jump > bestJump) {
            bestJump = jump;
            mover = entry;
          }
        }
        const playerOnChart = Object.values(charts).some(list =>
          list.some(e => e.artistId === state.player!.id),
        );
        fresh.push(...(fanPosts(home[0], mover, npcs, state.player, playerOnChart) as SocialPost[]));

        // 2. Artists talking about their own week.
        for (const npc of pickRandomArtists(npcs, 6)) {
          const own = npcSongs.filter(s => s.ownerId === npc.id);
          fresh.push(...(npcArtistPosts(npc, own) as SocialPost[]));
        }

        // 3. The arguments the player is not part of. This is the whole point
        //    of seeding rivalries: the world has a conversation going whether
        //    or not the player ever opens this screen.
        const hottest = worldBeefs(npcs, today)[0];
        if (hottest) {
          fresh.push({
            id: uuidv4(),
            platform: 'chirp',
            authorId: outletId,
            authorName: outletName,
            content: `${hottest.lastEventLine} ${hottest.aName} and ${hottest.bName}.`,
            likes: Math.round(hottest.heat * 12),
            shares: Math.round(hottest.heat * 1.6),
            comments: [],
            timestamp: new Date().toISOString(),
            isPlayerPost: false,
            trendingScore: hottest.heat,
            daySerial: today,
          } as SocialPost);
        }

        // 4. The player's own arguments, which they are expected to feed.
        for (const beef of state.beefs) {
          if (beef.resolution) continue;
          const heat = decayedHeat(beef, today);
          const standing = beef.rung > 0
            ? `It has reached the ${beefRung(beef.rung)?.name.toLowerCase() ?? 'next'} stage.`
            : 'Neither side has said anything yet.';
          fresh.push({
            id: uuidv4(),
            platform: 'chirp',
            authorId: outletId,
            authorName: outletName,
            content: `${state.player.artistName} against ${beef.npcName}. ${standing} Heat: ${Math.round(heat)}. Record: ${beef.wins}-${beef.losses}.`,
            likes: Math.round(heat * 9) + 20,
            shares: Math.round(heat * 1.2),
            comments: [],
            timestamp: new Date().toISOString(),
            isPlayerPost: false,
            trendingScore: heat,
            daySerial: today,
          } as SocialPost);
        }

        if (fresh.length === 0) {
          outcome = {
            ok: false,
            message: 'Nothing is moving anywhere. Release something, play somewhere, or start something with somebody.',
            added: 0,
            waitMinutes: 0,
          };
          return;
        }

        settleScenePosts(state, fresh, npcs);
        state.socialPosts.unshift(...fresh);
        // And the apps move: a few people post right now.
        const live = scenePosts(state, npcs, today, 1, { app: SOCIAL_APPS.includes(app as SocialApp) ? (app as SocialApp) : undefined, live: true });
        for (const post of state.socialPosts) if (post.isPlayerPost) announceMilestones(state, post, now);
        trimFeed(state);
        state.trending = buildTrending(charts, state.player) as typeof state.trending;
        state.feedRefreshedAt = now;

        outcome = {
          ok: true,
          message: `${fresh.length + live} new post${fresh.length + live === 1 ? '' : 's'}.`,
          added: fresh.length + live,
          waitMinutes: FEED_REFRESH_MINUTES,
        };
      });

      return outcome;
    },

    // ─── TAGGING ────────────────────────────────────────────────────────
    //
    // Free, instant and the one thing in here that could be farmed, so it has a
    // daily cap that resets on the GAME day. Whether they answer is the
    // relationship, their fame and how much attention they already get — a
    // friend answers, and an artist with eighty fame and a thousand mentions a
    // day does not.
    tagArtist: (npcId, text) => {
      let outcome: FeatureActionResult = { ok: false, message: '' };

      set((state) => {
        if (!state.player) {
          outcome = { ok: false, message: 'There is nobody to post as.' };
          return;
        }

        const npc = state.npcs.find(n => n.id === npcId);
        if (!npc) {
          outcome = { ok: false, message: 'There is nobody with that name in the scene.' };
          return;
        }
        if (npc.role !== 'artist' && npc.role !== 'producer' && npc.role !== 'media') {
          outcome = {
            ok: false,
            message: `${npc.name} is not somebody you tag. They run the business, not the timeline.`,
          };
          return;
        }

        const today = dateToSerial(state.gameDate);
        // The quota resets on the game day, not on a timer — a cap that resets
        // on a wall clock would let a player farm it by waiting. The rule
        // itself lives in `tagsLeftToday`, so the screen's counter and this
        // refusal are reading the same number.
        const quota =
          state.tagQuota && state.tagQuota.serial === today
            ? state.tagQuota
            : { serial: today, count: 0 };
        if (tagsLeftToday(state) <= 0) {
          state.tagQuota = quota;
          outcome = {
            ok: false,
            message:
              `You have tagged ${TAGS_PER_DAY} people today. Any more and it stops being a mention ` +
              `and starts being a bot. Come back tomorrow.`,
          };
          return;
        }

        if (!spendEnergy(state, ENERGY_COSTS.socialPost, { admin: true })) {
          outcome = {
            ok: false,
            message: energyShortfallMessage(ENERGY_COSTS.socialPost, state.player.energy),
          };
          return;
        }
        quota.count += 1;
        state.tagQuota = quota;

        const disposition = featureDisposition(raw(npc) as NPC);
        const odds = Math.max(
          0.03,
          Math.min(
            0.9,
            0.14 +
              npc.relationshipScore / 200 +
              blendedFame(state.player) / 400 -
              npc.fame / 500 -
              (1 - disposition.replySpeed) * 0.12,
          ),
        );
        const replied = Math.random() < odds;

        const post: SocialPost = {
          id: uuidv4(),
          platform: 'chirp',
          authorId: 'player',
          authorName: state.player.artistName,
          content: text,
          likes: Math.floor(state.player.career.fanbase * 0.005) + Math.floor(Math.random() * 12),
          shares: 0,
          comments: [],
          timestamp: new Date().toISOString(),
          isPlayerPost: true,
          trendingScore: Math.floor(state.player.career.localFame * 0.2),
          daySerial: today,
        };

        if (replied) {
          post.comments.push({
            id: uuidv4(),
            authorId: npc.id,
            authorName: npc.name,
            content: generatePostComment(raw(npc) as NPC, text).text,
            likes: Math.floor(npc.fame * 4 + Math.random() * 40),
            timestamp: new Date().toISOString(),
          });
          npc.relationshipScore = Math.min(100, npc.relationshipScore + 2);
          // Borrowing somebody's audience. Scaled by THEIR fame, which is the
          // reason tagging a big name is worth doing and tagging a small one
          // is not — and capped by the daily quota above.
          const reach = Math.round(npc.fame * 12);
          state.player.career.fanbase += reach;
          state.lastEventLog.unshift(
            `📣 ${npc.name} answered you. ${reach.toLocaleString()} of their people saw it.`,
          );
          state.lastEventLog = state.lastEventLog.slice(0, 10);
        }

        state.socialPosts.unshift(post);

        outcome = {
          ok: true,
          message: replied
            ? `${npc.name} answered.`
            : `${npc.name} saw it and said nothing. That is an answer too.`,
        };
      });

      return outcome;
    },

    // ─── BEEF ───────────────────────────────────────────────────────────
    //
    // Opening one is free and says nothing. The ladder is climbed with
    // `beefMove`, and each rung is gated on heat, so the expensive end of this
    // is only reachable by a beef that has actually been running.
    startBeef: (npcId) => {
      let outcome: FeatureActionResult = { ok: false, message: '' };

      set((state) => {
        if (!state.player) {
          outcome = { ok: false, message: 'There is nobody to start an argument.' };
          return;
        }
        const npc = state.npcs.find(n => n.id === npcId);
        if (!npc) {
          outcome = { ok: false, message: 'There is nobody with that name in the scene.' };
          return;
        }
        if (npc.role !== 'artist') {
          outcome = { ok: false, message: `${npc.name} does not make records. There is nothing to argue about.` };
          return;
        }
        if (!npc.isAvailable) {
          outcome = {
            ok: false,
            message: `${npc.name} is unreachable. You can say whatever you like and they will never hear it.`,
          };
          return;
        }
        const open = state.beefs.find(b => b.npcId === npcId && !b.resolution);
        if (open) {
          outcome = {
            ok: false,
            message: `You are already in it with ${npc.name}. Take it up a rung instead.`,
          };
          return;
        }

        const today = dateToSerial(state.gameDate);
        const beef: BeefState = {
          id: uuidv4(),
          npcId: npc.id,
          npcName: npc.name,
          rung: 0,
          heat: 0,
          heatSerial: today,
          startedSerial: today,
          lastMoveSerial: today,
          wins: 0,
          losses: 0,
          moves: [],
        };
        state.beefs.push(beef);
        state.lastEventLog.unshift(
          `⚔️ You have opened something with ${npc.name}. Nothing has been said yet — the first move is yours.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        outcome = {
          ok: true,
          message: 'Opened. Nothing has been said yet — the first move is yours.',
        };
      });

      return outcome;
    },

    beefMove: (beefId, rungLevel) => {
      let outcome: BeefActionResult = { ok: false, message: '' };

      set((state) => {
        if (!state.player) {
          outcome = { ok: false, message: 'There is nobody to make the move.' };
          return;
        }

        const beef = state.beefs.find(b => b.id === beefId);
        if (!beef) {
          outcome = { ok: false, message: 'That argument is not in your list.' };
          return;
        }
        if (beef.resolution) {
          outcome = {
            ok: false,
            message: `That one is over — ${RESOLUTION_LABEL[beef.resolution.kind].toLowerCase()}.`,
          };
          return;
        }

        const rung = beefRung(rungLevel);
        if (!rung) {
          outcome = { ok: false, message: 'There is no such rung.' };
          return;
        }
        // No skipping. The ladder IS the mechanic — a single "go nuclear"
        // button would make every rung below it pointless.
        if (rung.level !== beef.rung + 1) {
          const expected = beefRung(beef.rung + 1);
          outcome = {
            ok: false,
            message:
              rung.level <= beef.rung
                ? `You are already past the ${rung.name.toLowerCase()}. The ladder only goes up.`
                : `You cannot skip to the ${rung.name.toLowerCase()}. ` +
                  `${expected ? `The ${expected.name.toLowerCase()} comes first.` : 'That is the top.'}`,
          };
          return;
        }

        const today = dateToSerial(state.gameDate);
        const heat = decayedHeat(beef, today);
        if (rung.requiresHeat > heat) {
          outcome = {
            ok: false,
            message:
              `Not yet. The ${rung.name.toLowerCase()} needs the beef at ${rung.requiresHeat} heat and it is at ` +
              `${Math.round(heat)}. Feed it first — ${Math.ceil(rung.requiresHeat - heat)} more.`,
          };
          return;
        }

        const npc = state.npcs.find(n => n.id === beef.npcId);
        if (!npc) {
          outcome = { ok: false, message: `${beef.npcName} is not in the scene any more.` };
          return;
        }

        if (rung.cost > state.player.career.money) {
          outcome = {
            ok: false,
            message:
              `The ${rung.name.toLowerCase()} costs $${rung.cost.toLocaleString()}. ` +
              `You have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }
        if (!spendEnergy(state, rung.energy)) {
          outcome = { ok: false, message: energyShortfallMessage(rung.energy, state.player.energy) };
          return;
        }

        const playerFame = blendedFame(state.player);
        const result = settleBeef({
          rung,
          roll: Math.random(),
          playerFame,
          npcFame: npc.fame,
          heat,
          penQuality: bestPenQuality(state),
          reputation: state.player.career.reputation,
          crewReach: crewReachOf(state),
        });

        state.player.career.money -= rung.cost;

        // ── The player's own move ──
        beef.moves.unshift({
          serial: today,
          by: 'player',
          rung: rung.level,
          line: result.line,
          landed: result.landed,
          score: result.score,
          heatDelta: result.heatDelta,
        });
        beef.rung = rung.level;
        beef.lastMoveSerial = today;
        if (result.landed) beef.wins += 1;

        // ── The other side's answer ──
        // Their own score is their fame and the heat they are standing in.
        // They do not get the player's pen, which is the whole reason a small
        // artist can win one of these.
        let npcLanded = false;
        if (result.npcLine) {
          const npcScore = Math.max(0, Math.min(95, 30 + npc.fame * 0.5 + heat * 0.1));
          npcLanded = Math.random() < npcScore / 100;
          beef.moves.unshift({
            serial: today,
            by: 'npc',
            rung: rung.level,
            line: result.npcLine,
            landed: npcLanded,
            score: npcScore,
            heatDelta: npcLanded ? result.npcHeatDelta : 0,
          });
          if (npcLanded) beef.losses += 1;
        }

        // Heat: the player's move, plus whatever their answer was worth. Capped
        // at 100, and written with the serial so the lazy decay stays honest.
        beef.heat = Math.max(
          0,
          Math.min(100, heat + result.heatDelta + (npcLanded ? result.npcHeatDelta : 0)),
        );
        beef.heatSerial = today;
        beef.moves = beef.moves.slice(0, 20);

        // ── The consequences ──
        state.player.career.localFame = Math.max(
          0,
          Math.min(100, state.player.career.localFame + result.fameDelta),
        );
        state.player.career.fanbase = Math.max(0, state.player.career.fanbase + result.fansDelta);
        addMomentum(state, result.landed ? 3 : -1, result.landed ? `the ${rung.name.toLowerCase()} landed` : undefined);

        // A missed move costs reputation. It is the one thing a beef can take
        // off you that a chart run cannot give back.
        if (!result.landed) {
          state.player.career.reputation = Math.max(0, state.player.career.reputation - 2);
        }

        state.lastEventLog.unshift(
          `${result.landed ? '⚔️' : '💨'} ${result.headline} — ${npc.name}. Heat ${Math.round(beef.heat)}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        outcome = {
          ok: true,
          message: result.line,
          result: {
            landed: result.landed,
            line: result.line,
            headline: result.headline,
            heatDelta: result.heatDelta,
            fameDelta: result.fameDelta,
            fansDelta: result.fansDelta,
          },
        };
      });

      return outcome;
    },

    endBeef: (beefId, kind) => {
      let outcome: FeatureActionResult = { ok: false, message: '' };

      set((state) => {
        if (!state.player) {
          outcome = { ok: false, message: 'There is nobody to end it.' };
          return;
        }
        const beef = state.beefs.find(b => b.id === beefId);
        if (!beef) {
          outcome = { ok: false, message: 'That argument is not in your list.' };
          return;
        }
        if (beef.resolution) {
          outcome = { ok: false, message: 'That one is already over.' };
          return;
        }

        const today = dateToSerial(state.gameDate);
        const heat = decayedHeat(beef, today);
        const npc = state.npcs.find(n => n.id === beef.npcId);
        const npcFame = npc?.fame ?? 0;
        const relationship = npc?.relationshipScore ?? 0;
        const playerFame = blendedFame(state.player);

        const available = availableResolutions({
          heat,
          wins: beef.wins,
          losses: beef.losses,
          relationship,
          npcFame,
          playerFame,
        });
        if (!available.includes(kind)) {
          outcome = {
            ok: false,
            message:
              kind === 'ko'
                ? `You cannot call it a knockout. That needs the beef at 90 heat with three landed moves and none against — you are at ${Math.round(heat)} heat and ${beef.wins}-${beef.losses}.`
                : `They have no reason to concede. You need to be ahead on the record and the beef needs to be at 60 heat — it is at ${Math.round(heat)} and you are ${beef.wins}-${beef.losses}.`,
          };
          return;
        }

        // A truce is not a free action: somebody who is winning does not take it.
        if (kind === 'truce' && !truceAccepted({ heat, wins: beef.wins, losses: beef.losses, relationship, npcFame, playerFame }, Math.random())) {
          beef.heat = Math.min(100, heat + 6);
          beef.heatSerial = today;
          beef.lastMoveSerial = today;
          state.lastEventLog.unshift(`🚫 ${beef.npcName} is not interested in ending it. Heat went up.`);
          state.lastEventLog = state.lastEventLog.slice(0, 10);
          outcome = {
            ok: false,
            message: `${beef.npcName} is not interested in ending it. The heat went up instead.`,
          };
          return;
        }

        const line =
          kind === 'truce'
            ? `${beef.npcName} took the call. Both sides stood down and neither will explain why.`
            : kind === 'concession'
              ? `${beef.npcName} stopped answering. In this scene that is the same as conceding.`
              : `${beef.npcName} had nothing left to say. This one goes on the record as yours.`;

        beef.resolution = { kind, at: today, line };
        beef.heat = heat;
        beef.heatSerial = today;
        state.lastEventLog.unshift(`🤝 ${RESOLUTION_LABEL[kind]} — ${beef.npcName}.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        outcome = { ok: true, message: line };
      });

      return outcome;
    },

    // ─── SHOWS ──────────────────────────────────────────────────────────
    //
    // `planShowAt` is a pure read; `bookShow` is the commitment. Both run the
    // SAME engine over the same state, so the number the player acted on is the
    // number the night was planned around. The old version computed the
    // estimate in the component and the outcome in the store, from different
    // formulas, which is how the two drifted apart.
    // ─── INDUSTRY & LIFE ───────────────────────────────────────────────
    requestSampleClearance: (songId, sampleName, rightsHolder) => {
      let result: FeatureActionResult = { ok: false, message: 'Unable to request clearance.' };
      set((state) => {
        if (!state.player) return;
        const song = state.songs.find(s => s.id === songId);
        if (!song || !isSongReleased(song)) { result.message = 'The song must be released first.'; return; }
        if (!sampleName.trim() || !rightsHolder.trim()) { result.message = 'Add the sample and rights holder.'; return; }
        if (state.sampleClearances.some(c => c.songId === songId && c.status === 'pending')) { result.message = 'A clearance request is already pending.'; return; }
        const cost = Math.max(500, Math.round(song.quality * 180 + (state.player.career.localFame + state.player.career.nationalFame + state.player.career.internationalFame) * 80));
        const clearance: SampleClearance = { id: uuidv4(), songId, songTitle: song.title, sampleName: sampleName.trim(), rightsHolder: rightsHolder.trim(), quotedCost: cost, status: 'pending', requestedDate: formatGameDate(state.gameDate), deadlineSerial: dateToSerial(state.gameDate) + 30 };
        state.sampleClearances.unshift(clearance);
        state.openThreads.unshift({ id: uuidv4(), type: 'legal', description: `Sample clearance pending for "${song.title}" with ${rightsHolder.trim()}.`, involvedNPCIds: [], startDate: formatGameDate(state.gameDate), lastUpdated: formatGameDate(state.gameDate), resolved: false, priority: 6, escalationCount: 0 });
        state.industryNotices.unshift({ id: uuidv4(), type: 'sample', title: 'Sample clearance requested', body: `Rights holder ${rightsHolder.trim()} quoted ${money0(cost)} for "${song.title}".`, date: formatGameDate(state.gameDate), relatedSongId: songId, read: false });
        result = { ok: true, message: `Clearance requested. Quoted cost: ${money0(cost)}.` };
      });
      return result;
    },
    approveSampleClearance: (clearanceId) => {
      let result: FeatureActionResult = { ok: false, message: 'Clearance not found.' };
      set((state) => {
        const c = state.sampleClearances.find(x => x.id === clearanceId);
        if (!c || c.status !== 'pending') return;
        if (!state.player || state.player.career.money < c.quotedCost) { result.message = `You need ${money0(c.quotedCost)} to clear this sample.`; return; }
        state.player.career.money -= c.quotedCost;
        c.status = 'cleared';
        state.industryNotices.unshift({ id: uuidv4(), type: 'sample', title: 'Sample cleared', body: `"${c.songTitle}" is cleared for release and distribution.`, date: formatGameDate(state.gameDate), relatedSongId: c.songId, read: false });
        result = { ok: true, message: `Sample cleared for ${money0(c.quotedCost)}.` };
      });
      return result;
    },
    launchPayola: (songId, city, country) => {
      let result: FeatureActionResult = { ok: false, message: 'Campaign could not start.' };
      set((state) => {
        if (!state.player) return;
        const song = state.songs.find(s => s.id === songId);
        if (!song || !isSongReleased(song)) { result.message = 'Release the song before pitching radio.'; return; }
        const cost = 2500 + Math.round(state.player.career.localFame * 45);
        if (state.player.career.money < cost) { result.message = `You need ${money0(cost)} for the campaign.`; return; }
        state.player.career.money -= cost;
        state.payolaCampaigns.unshift({ id: uuidv4(), songId, songTitle: song.title, city, country, cost, remainingDays: 7, boost: 0.28, exposed: false, completed: false });
        state.openThreads.unshift({ id: uuidv4(), type: 'scandal', description: `An unofficial radio campaign is running for "${song.title}" in ${city}.`, involvedNPCIds: [], startDate: formatGameDate(state.gameDate), lastUpdated: formatGameDate(state.gameDate), resolved: false, priority: 5, escalationCount: 0 });
        state.industryNotices.unshift({ id: uuidv4(), type: 'payola', title: 'Radio campaign launched', body: `"${song.title}" is getting extra radio pressure in ${city}. There is a chance the campaign gets exposed.`, date: formatGameDate(state.gameDate), relatedSongId: songId, read: false });
        result = { ok: true, message: `Radio campaign launched in ${city} for ${money0(cost)}.` };
      });
      return result;
    },
    completeScoutMission: (missionId) => {
      let result: FeatureActionResult = { ok: false, message: 'Mission unavailable.' };
      set((state) => {
        const m = state.scoutMissions.find(x => x.id === missionId);
        if (!m || m.status !== 'open' || !state.player) return;
        if (dateToSerial(state.gameDate) > m.expiresSerial) { m.status = 'expired'; result.message = 'The scout moved on.'; return; }
        const target = state.npcs.find(n => n.id === m.targetNpcId);
        if (!target) { result.message = 'Target no longer available.'; return; }
        if (target.relationshipScore < 10) { result.message = `Build a relationship with ${target.name} first.`; return; }
        m.status = 'completed';
        state.player.career.money += m.rewardMoney;
        state.player.career.localFame = Math.min(100, state.player.career.localFame + m.rewardFame);
        state.player.career.momentum = Math.min(100, state.player.career.momentum + 3);
        state.industryNotices.unshift({ id: uuidv4(), type: 'scout', title: 'A&R mission completed', body: `${m.scoutName} credited you for connecting with ${m.targetName}.`, date: formatGameDate(state.gameDate), relatedNpcId: m.targetNpcId, read: false });
        result = { ok: true, message: `Mission complete: +${money0(m.rewardMoney)}, +${m.rewardFame.toFixed(1)} local fame.` };
      });
      return result;
    },
    retireCareer: () => get().setCareerMode('retired'),
    attemptComeback: () => get().announceComeback(),

    setCareerMode: (mode) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing changed.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const L = state.legacy;
        const from = L.mode ?? (L.retired ? 'retired' : 'active');
        if (from === mode) { result.message = `You're already ${MODES[mode].label.toLowerCase()}.`; return; }
        const serial = dateToSerial(state.gameDate);
        L.mode = mode;
        L.modeSince = serial;
        L.retired = mode === 'retired';
        if (mode === 'retired') {
          L.retiredAt = formatGameDate(state.gameDate);
          L.legacyScore = Math.max(L.legacyScore, legacyScoreOf(state));
          L.titles = legacyTitles(state);
          state.industryNotices.unshift({ id: uuidv4(), type: 'retirement', title: 'You retired', body: `${p.artistName} has stepped away from recording and touring.`, date: formatGameDate(state.gameDate), read: false });
        }
        if (mode === 'active') L.comeback = undefined;
        const fame = blendedFame(p);
        if (fame >= 20 && mode !== 'active') {
          const text = mode === 'retired' ? `${p.artistName} announces retirement` : mode === 'business' ? `${p.artistName} steps back from music to focus on business` : `${p.artistName} slows down: "I'll drop when I feel like it"`;
          state.headlines.unshift({ id: uuidv4(), text, fullStory: mode === 'retired' ? `After ${Math.max(1, Math.round((serial - dateToSerial(INITIAL_GAME_DATE)) / 365))} year(s), one of the scene's names calls it a day.` : 'Fans react to the news.', date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: mode === 'retired' ? 7 : 4, category: 'general' });
        }
        remember(state, 'career', mode === 'retired' ? 'You retired from music.' : mode === 'business' ? 'You stepped back from music to focus on business.' : mode === 'semi' ? 'You went semi-retired: music when you feel like it.' : 'You went back to being a full-time artist.', { weight: mode === 'retired' ? 5 : 3 });
        result = { ok: true, message: `${MODES[mode].emoji} ${MODES[mode].label}. ${MODES[mode].blurb}` };
      });
      return result;
    },

    announceComeback: () => {
      let result: FeatureActionResult = { ok: false, message: 'You never left.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const L = state.legacy;
        const from = L.mode ?? (L.retired ? 'retired' : 'active');
        if (from === 'active') return;
        const serial = dateToSerial(state.gameDate);
        const hype = comebackHype(Math.max(L.legacyScore, legacyScoreOf(state)), serial - (L.modeSince ?? serial), blendedFame(p));
        L.comebackAttempts += 1;
        L.mode = 'active';
        L.retired = false;
        L.modeSince = serial;
        L.comeback = { announced: serial, until: serial + COMEBACK_DAYS, hype };
        addMomentum(state, Math.round(hype / 3));
        state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} announces a comeback`, fullStory: 'New music is promised. The clock is running.', date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 6, category: 'general' });
        remember(state, 'career', 'You announced your comeback.', { weight: 4 });
        result = { ok: true, message: `You're back. Drop something within ${COMEBACK_DAYS} days — the first release rides the hype (+${hype}). Leave them waiting and it backfires.` };
      });
      return result;
    },
    choosePostCareerRole: (role: PostCareerRole) => {
      let result: FeatureActionResult = { ok: false, message: 'Role unavailable.' };
      set((state) => {
        if (!state.legacy.retired) { result.message = 'Choose a post-career role after retirement.'; return; }
        state.legacy.postCareerRole = role;
        result = { ok: true, message: `Post-career role set to ${role}.` };
      });
      return result;
    },
    acceptChildSupport: (coParentName) => {
      let result: FeatureActionResult = { ok: false, message: 'Family plan unavailable.' };
      set((state) => {
        if (!state.player) return;
        if (state.family.children >= 3) { result.message = 'The family system is intentionally lightweight: three children maximum.'; return; }
        state.family.children += 1;
        state.family.coParentName = coParentName.trim() || 'Co-parent';
        state.family.monthlyChildSupport = 350 + (state.player.career.localFame + state.player.career.nationalFame) * 4;
        state.family.nextReviewSerial = dateToSerial(state.gameDate) + 30;
        state.industryNotices.unshift({ id: uuidv4(), type: 'family', title: 'Family responsibility', body: `You now have a recurring monthly child-support obligation of ${money0(state.family.monthlyChildSupport)}.`, date: formatGameDate(state.gameDate), read: false });
        result = { ok: true, message: `Family obligation created: ${money0(state.family.monthlyChildSupport)} per month.` };
      });
      return result;
    },

    planShowAt: (venueId, price) => {
      const state = get();
      if (!state.player) return { ok: false, message: 'No career to plan for.' };
      const venue = findVenue(venueId);
      if (!venue) return { ok: false, message: 'That room is not on the list.' };
      const lock = venueLockReason(venue, blendedFame(state.player));
      if (lock) return { ok: false, message: lock };
      return { ok: true, message: '', plan: planShow(showInputFrom(state, venue, price)) };
    },

    inquireVenue: (venueId, wantedSerial) => {
      let out: { ok: boolean; message: string; result?: InquiryResult } = {
        ok: false,
        message: 'That room is not on the list.',
      };

      set((state) => {
        if (!state.player) return;
        if (state.legacy.retired) { out = { ok: false, message: 'You\'re retired. Go semi-retired (Industry & Life) or announce a comeback to play shows.' }; return; }
        const venue = findVenue(venueId);
        if (!venue) return;

        const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
        const hasBooker = bonuses.promoterCut > 0;
        const wanted = wantedSerial ?? dateToSerial(state.gameDate);
        const cost = hasBooker ? INQUIRY_ENERGY_WITH_TEAM : INQUIRY_ENERGY;

        if (!spendEnergy(state, cost)) {
          const need = effectiveEnergy(state, cost);
          out = {
            ok: false,
            message:
              `Working the phones takes ${need} energy and you are at ${Math.floor(state.player.energy)}. ` +
              `${energyShortfallMessage(need, state.player.energy)}`,
          };
          return;
        }

        // The same cooldown `bookShow` enforces, so the nights this report
        // offers are nights the booking gate would actually accept.
        const market = state.cityMarkets[venue.city];
        const cd = checkCooldown(venue.cls, market?.lastShowSerial, dateToSerial(state.gameDate));
        const earliestSerial = cd.ok ? wanted : Math.max(wanted, dateToSerial(state.gameDate) + cd.daysLeft);

        const result = inquire({ venue, wantedSerial: wanted, hasBooker, earliestSerial });
        out = {
          ok: true,
          message: inquiryReport(result, venue, (s) => formatGameDate(serialToDate(s))),
          result,
        };

        state.lastEventLog.unshift(
          `📞 ${venue.name} — ${
            result.bookable
              ? 'the night is open.'
              : result.free
                ? 'the night is open, but not to you yet.'
                : 'that night is gone.'
          }`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      });

      return out;
    },

    bookShow: (venueId, type, price) => {
      let result: FeatureActionResult = { ok: false, message: 'That room is not on the list.' };

      set((state) => {
        if (!state.player) return;
        if (state.legacy.retired) { result = { ok: false, message: 'You\'re retired. Go semi-retired (Industry & Life) or announce a comeback to play shows.' }; return; }
        const venue = findVenue(venueId);
        if (!venue) return;

        // ── The room ──────────────────────────────────────────────────────
        const fame = blendedFame(state.player);
        const lock = venueLockReason(venue, fame);
        if (lock) {
          result = { ok: false, message: lock };
          return;
        }

        const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);

        // ── A booked date owns its night ──────────────────────────────────
        // A tour is a commitment, not a suggestion. Without this a player could
        // sell tickets for a one-off in a city they will not even be in, on a
        // night the tour has already sold — and the tour would then play that
        // night on top of it.
        const tourNight = dateToSerial(state.gameDate);
        const clashingTour = state.tours.find(
          (t) =>
            t.status !== 'cancelled' &&
            t.legs.some((l) => l.playedSerial === undefined && l.serial === tourNight),
        );
        if (clashingTour) {
          const leg = clashingTour.legs.find(
            (l) => l.playedSerial === undefined && l.serial === tourNight,
          );
          result = {
            ok: false,
            message: `You are on tour that night — ${clashingTour.name} is in ${leg?.city ?? 'another city'}.`,
          };
          return;
        }

        // ── The slot ──────────────────────────────────────────────────────
        const gate = slotRequirement(
          type, venue, state.player.country, fame, bonuses.promoterCut, bonuses.logisticsMult,
        );
        if (gate) {
          result = { ok: false, message: gate };
          return;
        }

        // ── Is the room even free? ────────────────────────────────────────
        // A room is not a button. Somebody else's night is often already in
        // it, and the answer is a report rather than a wall: who has it, and
        // which nearby nights are open. With a promoter on the payroll the
        // report covers a month and a half of the diary instead of a fortnight.
        //
        // This gate sits ABOVE the cooldown on purpose. The other way round, a
        // player standing in both would be told only about the cooldown, wait
        // it out, and *then* be told the room was taken — two dead ends for one
        // booking, and the second one arrives after a two-week wait. And the
        // nights this report offers are filtered past `earliestSerial`, so a
        // night it suggests is always a night the player can actually take.
        const nowSerial = dateToSerial(state.gameDate);
        const market = state.cityMarkets[venue.city];
        const cd = checkCooldown(venue.cls, market?.lastShowSerial, nowSerial);
        const earliestSerial = cd.ok ? nowSerial : nowSerial + cd.daysLeft;

        const tonight = nightAt(venue, nowSerial);
        if (tonight.status === 'taken') {
          const looked = inquire({
            venue,
            wantedSerial: nowSerial,
            hasBooker: bonuses.promoterCut > 0,
            earliestSerial,
          });
          result = {
            ok: false,
            message: inquiryReport(looked, venue, (s) => formatGameDate(serialToDate(s))),
          };
          return;
        }

        // ── The cooldown ──────────────────────────────────────────────────
        // A refusal, not a reschedule. The old code moved the calendar forward
        // a day per booking, which produced a one-day gap that LOOKED like a
        // cooldown while refusing nothing — four Accra shows went through on
        // four consecutive days.
        if (!cd.ok) {
          result = { ok: false, message: cd.reason };
          return;
        }

        // ── Can they even open the doors? ─────────────────────────────────
        const input = showInputFrom(state, venue, price);
        const plan = planShow(input);
        if (state.player.career.money < plan.totalCosts) {
          result = {
            ok: false,
            message:
              `Opening ${venue.name} costs about $${plan.totalCosts.toLocaleString()} before a single ticket. ` +
              `You have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }

        const energy = showEnergy(type);
        const energyBefore = state.player.energy / Math.max(1, state.player.maxEnergy);
        if (!spendEnergy(state, energy)) {
          const need = effectiveEnergy(state, energy);
          result = {
            ok: false,
            message: `A show takes ${need} energy and you are at ${Math.floor(state.player.energy)}. ${energyShortfallMessage(need, state.player.energy)}`,
          };
          return;
        }

        // ── The night ─────────────────────────────────────────────────────
        // One roll, and the only random number in the whole show. Everything
        // else — the seats, the money, the review — follows from it.
        const roll = 0.82 + Math.random() * 0.36;
        const night = settleShow(input, roll);

        const performanceQuality = performanceScore({
          stagePresence: state.player.stats.stagePresence,
          performance: state.player.stats.performance,
          charisma: state.player.stats.charisma,
          consistency: state.player.stats.consistency,
          stageBonus: bonuses.stageBonus,
          energyRatio: energyBefore,
          fill: night.fill,
        });

        // Everything from here down is shared with the tour tick. The only
        // difference is that a single show is played now and eats the day,
        // while a tour date has already arrived on the clock.
        const settled = applyShowOutcome(state, {
          venue,
          type,
          price,
          night,
          performanceQuality,
          energy,
          nowSerial,
          controversyMult: bonuses.controversyMult,
          advanceCalendar: true,
        });
        const attendance = settled.attendance;

        result = {
          ok: true,
          message: attendance === 0
            ? `${venue.name} was empty. $${Math.abs(night.net).toLocaleString()} lost.`
            : `${attendance.toLocaleString()} of ${venue.capacity.toLocaleString()} at ${venue.name} — $${night.net.toLocaleString()} ${night.net >= 0 ? 'clear' : 'lost'}.`,
        };
      });

      return result;
    },

    // ─── TOURS ───────────────────────────────────────────────────────────
    //
    // A tour is a run of dates, not a bigger show. `planTourAt` is a pure read
    // over the same engine `bookShow` runs; `bookTour` is the commitment. Both
    // go through `planTour` in `sim/tours.ts`, so the schedule the player reads
    // is the schedule the tick will play — the estimate cannot be a different
    // tour, which is the failure mode the whole show rebuild exists to kill.
    planTourAt: (stops, startSerial) => {
      const state = get();
      if (!state.player) return { ok: false, message: 'No career to plan for.' };
      if (stops.length < 2) {
        return { ok: false, message: 'A tour is two dates or more. Pick at least one more city.' };
      }
      const missing = unresolvedStops(stops);
      if (missing.length) {
        return {
          ok: false,
          message:
            `${missing.length} of those ${stops.length} rooms could not be found, so nothing ` +
            `has been planned. Nothing was booked and no money moved.`,
        };
      }
      const nowSerial = dateToSerial(state.gameDate);
      const plan = planTour({
        stops: tourStopsFrom(state, stops),
        startSerial: startSerial ?? nowSerial,
        daysSinceRelease: daysSinceLastRelease(state, nowSerial),
      });
      return {
        ok: plan.isTour,
        message: tourReport(plan, (s) => formatGameDate(serialToDate(s))),
        plan,
      };
    },

    bookTour: (stops, startSerial) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to book.' };

      set((state) => {
        if (!state.player) return;

        const missing = unresolvedStops(stops);
        if (missing.length) {
          result = {
            ok: false,
            message:
              `${missing.length} of those ${stops.length} rooms could not be found, so nothing ` +
              `has been booked. Nothing was charged.`,
          };
          return;
        }

        const nowSerial = dateToSerial(state.gameDate);
        const plan = planTour({
          stops: tourStopsFrom(state, stops),
          startSerial: startSerial ?? nowSerial,
          daysSinceRelease: daysSinceLastRelease(state, nowSerial),
        });

        if (!plan.isTour) {
          result = {
            ok: false,
            message: plan.unavailable.length
              ? `${plan.unavailable.length} of ${stops.length} dates cannot be had. ${tourReport(plan, (s) => formatGameDate(serialToDate(s)))}`
              : 'A tour is two dates or more.',
          };
          return;
        }

        // The routing is real money that leaves before a single ticket, and it
        // is charged ONCE, here. Each night still pays its own freight inside
        // its own settlement, so the two bills never get confused.
        const perLeg = plan.legs.reduce((s, l) => s + l.plan.totalCosts, 0);
        const need = plan.totalTravel + perLeg;
        if (state.player.career.money < need) {
          result = {
            ok: false,
            message:
              `This run costs about $${Math.round(need).toLocaleString()} to put on — ` +
              `$${plan.totalTravel.toLocaleString()} of it moving between cities. ` +
              `You have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }

        state.player.career.money -= plan.totalTravel;

        const tour: Tour = {
          id: uuidv4(),
          name: plan.countries.length > 1 ? 'The Run' : `${plan.countries[0]} Run`,
          createdAt: formatGameDate(state.gameDate),
          legs: plan.legs.map((l) => ({
            id: uuidv4(),
            type: l.type,
            venueId: l.venue.id,
            city: l.city,
            country: l.country,
            serial: l.serial,
            price: l.price,
          })),
          travelCost: plan.totalTravel,
          // Locked at booking, so a record that lands mid-tour cannot retro-
          // lift the dates the player already sold.
          buzz: plan.buzz,
          status: 'booked',
        };
        state.tours.push(tour);

        state.lastEventLog.unshift(
          `🚌 Tour booked — ${tour.legs.length} dates, ${plan.cities.join(', ')}. ` +
            `$${plan.totalTravel.toLocaleString()} on the road. ` +
            `Projected $${plan.projected.netAfterTravel.toLocaleString()}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        result = {
          ok: true,
          message:
            `Booked ${tour.legs.length} dates from ${formatGameDate(serialToDate(plan.firstNight!))} ` +
            `to ${formatGameDate(serialToDate(plan.lastNight!))}. ` +
            `$${plan.totalTravel.toLocaleString()} paid on the road; ` +
            `$${plan.projected.netAfterTravel.toLocaleString()} projected.`,
        };
      });

      return result;
    },

    // ─── SHOW OFFERS ─────────────────────────────────────────────────────
    //
    // Offers arrive from the tick (see "SHOW OFFERS" in `advanceTurnBy`). The
    // player answers them here: counter, accept, or decline with a reason. The
    // NPC reaction is a pure function of who they are (`sim/offers.ts`), and
    // the store only applies it.
    showOfferContext: (id) => {
      const state = get();
      const offer = state.showOffers.find((o) => o.id === id);
      const npc = offer ? state.npcs.find((n) => n.id === offer.hostId) : undefined;
      if (!offer || !npc) return null;
      const now = dateToSerial(state.gameDate);
      return {
        mood: moodOf(npc.id, now),
        relationship: npc.relationshipScore,
        managerSkill: playerNegotiatorSkill(state, 'manager'),
        lawyerSkill: playerNegotiatorSkill(state, 'lawyer'),
        competing: state.showOffers.filter((o) => o.id !== id && o.status === 'open').length,
        traits: traitsOf(npc),
        hostTier: npc.tier,
        hostFame: npc.fame,
        calendarBusy: playerBusyOn(state, offer.serial),
      };
    },

    counterShowOffer: (id, ask) => {
      let out: { ok: boolean; message: string; outcome?: CounterResult['outcome'] } = { ok: false, message: 'That offer is gone.' };
      set((state) => {
        const offer = state.showOffers.find((o) => o.id === id);
        const npc = offer ? state.npcs.find((n) => n.id === offer.hostId) : undefined;
        if (!offer || !npc || offer.status !== 'open') return;
        const now = dateToSerial(state.gameDate);
        if (now > offer.expiresSerial) {
          offer.status = 'expired';
          closeBriefs(state, offer.id, 'Expired — nobody answered.');
          out = { ok: false, message: 'That offer has expired.' };
          return;
        }
        const res = negotiate(
          offer,
          ask,
          {
            relationship: npc.relationshipScore,
            mood: moodOf(npc.id, now),
            managerSkill: playerNegotiatorSkill(state, 'manager'),
            lawyerSkill: playerNegotiatorSkill(state, 'lawyer'),
            competing: state.showOffers.filter((o) => o.id !== id && o.status === 'open').length,
            traits: traitsOf(npc),
          },
          Math.random(),
        );
        offer.round += 1;
        offer.patience = res.patience;
        offer.log.unshift(res.line);
        offer.log = offer.log.slice(0, 10);
        if (res.outcome === 'accepted' || res.outcome === 'met_halfway') {
          offer.terms = res.terms;
          offer.agreed = res.outcome === 'accepted';
        }
        if (res.outcome === 'walked') {
          offer.status = 'walked';
          closeBriefs(state, offer.id, 'They walked away from the table.');
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - 2);
          state.lastEventLog.unshift(`🚪 ${npc.name}'s camp walked away from the ${offer.city} offer.`);
          state.lastEventLog = state.lastEventLog.slice(0, 10);
        }
        out = { ok: true, message: res.line, outcome: res.outcome };
      });
      return out;
    },

    acceptShowOffer: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'That offer is gone.' };
      set((state) => {
        const offer = state.showOffers.find((o) => o.id === id);
        const npc = offer ? state.npcs.find((n) => n.id === offer.hostId) : undefined;
        if (!offer || !npc || !state.player || offer.status !== 'open') return;
        const now = dateToSerial(state.gameDate);
        if (now > offer.expiresSerial) {
          offer.status = 'expired';
          closeBriefs(state, offer.id, 'Expired — nobody answered.');
          result = { ok: false, message: 'That offer has expired.' };
          return;
        }
        if (playerBusyOn(state, offer.serial)) {
          result = { ok: false, message: `You already have something on ${formatGameDate(serialToDate(offer.serial))}. Decline it, or clear the date first.` };
          return;
        }
        const clash = state.bookedGigs.find(
          (g) => g.terms.exclusivityDays > 0 && g.city === offer.city && Math.abs(g.serial - offer.serial) < g.terms.exclusivityDays,
        );
        if (clash) {
          result = { ok: false, message: `${clash.hostName}'s radius clause bars you from playing ${offer.city} that close to ${formatGameDate(serialToDate(clash.serial))}.` };
          return;
        }

        const gig: BookedGig = {
          id: uuidv4(),
          offerId: offer.id,
          hostId: offer.hostId,
          hostName: offer.hostName,
          archetype: offer.archetype,
          kind: offer.kind,
          venueId: offer.venueId,
          venueName: offer.venueName,
          city: offer.city,
          country: offer.country,
          capacity: offer.capacity,
          serial: offer.serial,
          acceptedSerial: now,
          terms: { ...offer.terms },
          reminded: [],
          lineup: offer.lineup ? offer.lineup.map((a) => ({ ...a })) : undefined,
        };
        state.bookedGigs.push(gig);
        offer.status = 'accepted';
        closeBriefs(state, offer.id, 'Booked.');
        npc.relationshipScore = Math.min(100, npc.relationshipScore + 2);
        npc.memoryLog = [`Accepted their ${offer.city} date`, ...(npc.memoryLog ?? [])].slice(0, 10);

        const when = formatGameDate(serialToDate(offer.serial));
        state.lastEventLog.unshift(`🤝 Booked: ${offer.venueName}, ${offer.city} — ${when}.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        const bits: string[] = [];
        if (offer.hidden.includes('cancel') && playerNegotiatorSkill(state, 'lawyer') <= 0) {
          bits.push(`You signed without a lawyer. The fine print has a ${CANCEL_LABEL[offer.terms.cancel].label.toLowerCase()} cancellation clause.`);
        }
        if (offer.terms.exclusivityDays > 0) {
          bits.push(`There is a ${offer.terms.exclusivityDays}-day radius clause around ${offer.city}.`);
        }
        result = {
          ok: true,
          message: `Booked ${offer.venueName} on ${when}. $${offer.terms.fee.toLocaleString()} guaranteed.${bits.length ? ' ' + bits.join(' ') : ''}`,
        };
      });
      return result;
    },

    declineShowOffer: (id, reason, soften) => {
      let result: FeatureActionResult = { ok: false, message: 'That offer is gone.' };
      set((state) => {
        const offer = state.showOffers.find((o) => o.id === id);
        const npc = offer ? state.npcs.find((n) => n.id === offer.hostId) : undefined;
        if (!offer || !npc || !state.player || offer.status !== 'open') return;
        const now = dateToSerial(state.gameDate);
        const eff = declineEffect({
          archetype: offer.archetype,
          traits: traitsOf(npc),
          reason,
          relationship: npc.relationshipScore,
          mood: moodOf(npc.id, now),
          calendarBusy: playerBusyOn(state, offer.serial),
          runDown: state.player.energy / Math.max(1, state.player.maxEnergy) < 0.5,
          negotiated: offer.round > 0,
          soften,
          hostTier: npc.tier,
          roll: Math.random(),
        });
        npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + eff.relationship));
        npc.memoryLog = [`Turned down their ${offer.city} date (${reason})`, ...(npc.memoryLog ?? [])].slice(0, 10);
        state.player.career.reputation = Math.max(0, Math.min(100, state.player.career.reputation + eff.reputation));
        offer.status = 'declined';
        closeBriefs(state, offer.id, 'Declined.');
        offer.log.unshift(eff.line);

        if (eff.grudge || (eff.relationship <= -5 && npc.tier !== 'local')) {
          state.headlines.unshift({
            id: uuidv4(),
            text: `Word is ${state.player.artistName} turned down ${npc.name}'s ${offer.city} date`,
            fullStory: `Industry chatter says the invitation was declined. ${eff.line}`,
            date: formatGameDate(serialToDate(now)),
            relatedEntities: [state.player.id, npc.id],
            priority: 3,
            category: 'show',
          });
        }
        const delta = eff.relationship === 0 ? 'no change' : `${eff.relationship > 0 ? '+' : ''}${eff.relationship} relationship`;
        result = { ok: true, message: `${eff.line} (${delta}).` };
      });
      return result;
    },

    quoteDecline: (id, reason, soften) => {
      const state = get();
      const offer = state.showOffers.find((o) => o.id === id);
      const npc = offer ? state.npcs.find((n) => n.id === offer.hostId) : undefined;
      if (!offer || !npc || !state.player) return null;
      const now = dateToSerial(state.gameDate);
      return declineEffect({
        archetype: offer.archetype,
        traits: traitsOf(npc),
        reason,
        relationship: npc.relationshipScore,
        mood: moodOf(npc.id, now),
        calendarBusy: playerBusyOn(state, offer.serial),
        runDown: state.player.energy / Math.max(1, state.player.maxEnergy) < 0.5,
        negotiated: offer.round > 0,
        soften,
        hostTier: npc.tier,
        roll: 0,
      });
    },

    answerMoment: (momentId, optionId) => {
      let result: FeatureActionResult = { ok: false, message: 'That moment has passed.' };
      set((state) => {
        if (!state.player) return;
        const m = (state.moments ?? []).find((x) => x.id === momentId);
        if (!m || m.status !== 'open') return;
        const option = m.options.find((o) => o.id === optionId);
        if (!option) return;
        if (option.cost && state.player.career.money < option.cost) { result.message = `You need $${option.cost.toLocaleString()} for that.`; return; }
        if (option.energy && state.player.energy < option.energy && !(m.kind === 'studio_invite' && optionId === 'go')) { result.message = `You need ${option.energy} energy for that. Rest first.`; return; }
        const serial = dateToSerial(state.gameDate);
        const npc = m.npcId ? state.npcs.find((n) => n.id === m.npcId) : undefined;
        const seed = `${m.id}|${optionId}`;

        // Saying yes to a plan puts it in the diary instead of resolving now.
        const planKind: Appointment['kind'] | null = m.channel === 'dm' && optionId === 'go' && npc
          ? (m.kind === 'studio_invite' ? 'studio' : m.kind === 'party_invite' ? 'party' : null)
          : null;
        let r: { text: string; effects: MomentEffect[] };
        let appt: Appointment | null = null;
        if (planKind && npc) {
          const at = defaultSlot(nowMinuteOf(state), planKind);
          r = { text: `It's in your diary: ${whenLabel(at, nowMinuteOf(state))}.`, effects: [{ k: 'rel', npcId: npc.id, v: 2 }] };
          appt = { id: '', npcId: npc.id, npcName: npc.name, kind: planKind, title: '', place: '', atMinute: at, from: 'npc', status: 'confirmed', createdSerial: serial };
        } else {
          const world = momentWorld(state, raw(state.npcs) as NPC[], serial);
          if (!world) return;
          r = resolveMoment(m, optionId, world, Math.random());
        }
        m.status = 'resolved';
        m.resolution = { optionId, label: option.label, text: r.text };
        // In a chat, the conversation comes first and what it set in motion
        // (a diary entry, a beat, a deal) after it.
        const chat = m.channel === 'dm' && !!m.npcId;
        if (!chat) applyMomentEffects(state, r.effects, serial);

        if (m.channel === 'dm' && m.npcId) {
          m.data = { ...(m.data ?? {}), inChat: true };
          const real = isRealId(m.npcId);
          const persona = npc ? personaOf(npc) : null;
          if (isSilentOption(optionId)) {
            pushDM(state, m.npcId, { fromPlayer: true, system: true, content: 'Seen' });
            // Their nudge comes before what happened next, not after it.
            const fu = persona && !real ? followUpFor(m.kind, persona, seed) : null;
            if (fu) pushDM(state, m.npcId, { fromPlayer: false, content: fu.text });
          } else {
            pushDM(state, m.npcId, { fromPlayer: true, content: playerLine(m.kind, optionId, option.label, seed) });
            if (!real && persona) {
              if (aiActiveFor('moments')) {
                const thread = state.dmThreads[m.npcId];
                thread.pendingAI = { since: Date.now(), momentId: m.id, optionId };
              } else {
                const reply = npcReply(m.kind, optionId, toneOf(r.effects, m.npcId), persona, seed);
                if (reply) pushDM(state, m.npcId, { fromPlayer: false, content: reply });
              }
            }
          }
          applyMomentEffects(state, r.effects, serial);
          if (appt && npc) {
            const made = createAppointment(state, npc, appt.kind, appt.atMinute, 'npc');
            result = { ok: true, message: `${made.title} — ${whenLabel(made.atMinute, nowMinuteOf(state))}.` };
          } else if (!r.effects.some((e) => e.k === 'gig')) {
            // (A gig already put its own diary card in the chat.)
            pushDM(state, m.npcId, { fromPlayer: false, system: true, content: r.text, chips: outcomeChips(r.effects, m.npcName), momentId: m.id });
          }
        }
        if (npc) npc.memoryLog = [`${m.title} — you chose "${option.label}"`, ...(npc.memoryLog ?? [])].slice(0, 10);
        if (!appt) result = { ok: true, message: r.text };
      });
      return result;
    },

    planAppointment: (npcId, kind, atMinute) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not plan that.' };
      set((state) => {
        const p = state.player;
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!p || !npc) return;
        if (isBlocked(state, npcId)) { result.message = 'You blocked them.'; return; }
        const now = nowMinuteOf(state);
        if (atMinute - now < 45) { result.message = 'Give them at least an hour\'s notice.'; return; }
        if ((state.appointments ?? []).some((a) => a.status === 'confirmed' && Math.abs(a.atMinute - atMinute) < 120)) { result.message = 'You already have something around then.'; return; }
        const serial = dateToSerial(state.gameDate);
        const label = KIND_LABEL[kind];
        pushDM(state, npcId, { fromPlayer: true, content: kind === 'studio' ? `You free ${whenLabel(atMinute, now).toLowerCase()}? Let's lock in at the studio 🎙️` : kind === 'party' ? `Coming out ${whenLabel(atMinute, now).toLowerCase()}? It's going to be a madness` : kind === 'meeting' ? `Can we meet ${whenLabel(atMinute, now).toLowerCase()}? Got something to talk about` : `Let's link ${whenLabel(atMinute, now).toLowerCase()}. Food on me` });
        if (isRealId(npc.id)) {
          pushDM(state, npcId, { fromPlayer: false, system: true, content: 'Delivered. Their team handles their schedule.' });
          result = { ok: true, message: 'Sent. Their team handles their schedule.' };
          return;
        }
        const persona = personaOf(npc);
        const fameGap = (blendedFame(p) - npc.fame) / 200;
        const chance = Math.max(0.05, Math.min(0.95, 0.35 + npc.relationshipScore / 160 + fameGap + persona.warmth * 0.2 - (npc.lastReachOut === serial ? 0.2 : 0)));
        const yes = Math.random() < chance;
        npc.lastReachOut = serial;
        if (!yes) {
          const no = persona.style === 'formal' ? 'Unfortunately I\'m booked then. Another time.' : persona.style === 'dry' ? 'Can\'t.' : persona.warmth > 0.6 ? 'Ahh I can\'t make it then 😩 another time for sure' : 'Busy then, sorry';
          scheduleDM(state, npcId, no, now + 8 + Math.floor(Math.random() * 30));
          result = { ok: true, message: `Sent. ${npc.name.split(' ')[0]} will get back to you.` };
          return;
        }
        const ok = persona.style === 'formal' ? 'Works for me. See you then.' : persona.style === 'dry' ? 'Fine.' : persona.style === 'spiritual' ? 'God willing, I\'ll be there 🙏🏾' : persona.style === 'flashy' ? 'Say less 💎 I\'ll pull up' : 'Bet 🔥 see you then';
        pushDM(state, npcId, { fromPlayer: false, content: ok });
        const a = createAppointment(state, npc, kind, atMinute, 'player');
        result = { ok: true, message: `${label.emoji} ${a.title} — ${whenLabel(atMinute, now)}.` };
      });
      return result;
    },

    rescheduleAppointment: (id, atMinute) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not move it.' };
      set((state) => {
        const a = (state.appointments ?? []).find((x) => x.id === id && x.status === 'confirmed');
        const npc = a ? state.npcs.find((n) => n.id === a.npcId) : undefined;
        if (!a || !npc) return;
        const now = nowMinuteOf(state);
        if (atMinute - now < 45) { result.message = 'Too soon.'; return; }
        const persona = personaOf(npc);
        a.atMinute = atMinute;
        pushDM(state, a.npcId, { fromPlayer: true, content: `Can we move it to ${whenLabel(atMinute, now).toLowerCase()}?` });
        if (persona.ego > 0.75 && Math.random() < 0.4) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 2);
        scheduleDM(state, a.npcId, persona.ego > 0.75 ? 'Fine. Don\'t move it again.' : persona.warmth > 0.6 ? 'No wahala 👍🏾' : 'Ok', now + 5);
        pushDM(state, a.npcId, { fromPlayer: false, system: true, content: `${KIND_LABEL[a.kind].emoji} Moved to ${whenLabel(atMinute, now)} · ${a.place}`, appointmentId: a.id });
        result = { ok: true, message: `Moved to ${whenLabel(atMinute, now)}.` };
      });
      return result;
    },

    cancelAppointment: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not cancel.' };
      set((state) => {
        const a = (state.appointments ?? []).find((x) => x.id === id && (x.status === 'confirmed' || x.status === 'live'));
        const npc = a ? state.npcs.find((n) => n.id === a.npcId) : undefined;
        if (!a || !npc) return;
        const now = nowMinuteOf(state);
        const persona = personaOf(npc);
        pushDM(state, a.npcId, { fromPlayer: true, content: a.atMinute - now > 180 ? 'Something came up, can\'t make it. My bad 🙏🏾' : 'Bro I\'m so sorry, I can\'t make it tonight' });
        if (a.atMinute - now > 180) {
          const hurt = Math.round(3 * (1.2 - persona.forgiveness));
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - hurt);
          a.status = 'cancelled';
          a.outcome = 'You cancelled with notice.';
          scheduleDM(state, a.npcId, persona.forgiveness > 0.6 ? 'All good, another time' : 'Ok.', now + 10);
          result = { ok: true, message: `Cancelled. ${npc.name.split(' ')[0]} ${hurt > 2 ? 'wasn\'t happy' : 'took it fine'}.` };
          return;
        }
        const res = noShow(a, persona, 'bail', a.id);
        finishAppointment(state, a, res, 'cancelled');
        result = { ok: true, message: res.text };
      });
      return result;
    },

    attendAppointment: (choiceId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing is happening right now.' };
      set((state) => {
        const p = state.player;
        const a = (state.appointments ?? []).find((x) => x.id === state.activeAppointment);
        const npc = a ? state.npcs.find((n) => n.id === a.npcId) : undefined;
        if (!p || !a || !npc) { state.activeAppointment = null; return; }
        if (a.pitch) {
          const { best: out, fresh } = pitchSongs(state as GameState);
          const pc = pitchChoices(out ? { title: out.title } : undefined, fresh ? { title: fresh.title } : undefined).find((c) => c.id === choiceId);
          if (!pc) return;
          if (p.energy < pc.energy) { result.message = `You need ${pc.energy} energy for that.`; return; }
          const played = choiceId === 'play_new' ? fresh : choiceId === 'play_best' ? out : (out ?? fresh);
          const mgr = managerOf(state);
          const r = resolvePitch({
            pitch: a.pitch, choice: pc.id, songTitle: played?.title, songId: fresh?.id, quality: played?.quality ?? 40,
            playerFame: blendedFame(p), charisma: p.stats.charisma, networking: p.stats.networking, businessKnowledge: p.stats.businessKnowledge,
            managerSkill: mgr ? managerNetwork(mgr) : 30, rel: npc.relationshipScore, roll: Math.random(), seed: a.id,
          });
          // An unreleased record played in somebody else's room can travel.
          if (choiceId === 'play_new' && fresh && Math.random() < 0.08) r.effects.push({ k: 'momentum', v: 2 }, { k: 'headline', text: `A snippet of an unreleased ${p.artistName} record is going round`, story: 'Somebody in a meeting room had their phone out. Fans are already asking when it drops.', category: 'general' });
          finishAppointment(state, a, { text: r.text, npcLine: r.npcLine ?? '', effects: r.effects }, 'done');
          if (mgr) scheduleDM(state, mgr.id, r.outcome === 'feature' ? 'That went better than I hoped. Check the terms before you pay — big camps always have conditions.' : r.outcome === 'cosign' ? 'You see your phone? That\'s what a room like that does. Keep the momentum.' : r.outcome === 'door' ? 'Door is open. Next record goes to them first — make it a strong one.' : 'Not this time. But they know your name now. That counts.', nowMinuteOf(state) + 30);
          state.clockPaused = false;
          result = { ok: true, message: a.outcome ?? r.text };
          return;
        }
        const best = (state.songs ?? []).filter((s) => !isSongReleased(s) && !s.archivedAt).reduce((m, s) => Math.max(m, s.quality), 0);
        const choice = sceneChoices(a, best > 0).find((c) => c.id === choiceId);
        if (!choice) return;
        if (p.energy < choice.energy) { result.message = `You need ${choice.energy} energy for that.`; return; }
        const res = resolveScene(a, choiceId, personaOf(npc), { rel: npc.relationshipScore, unreleasedQuality: best, playerFame: blendedFame(p), producerSkill: npc.role === 'producer' ? producerSkillOf(npc as NPC) : undefined }, Math.random());
        const late = a.outcome?.startsWith('You\'re') ? `${a.outcome} ` : '';
        finishAppointment(state, a, res, 'done', late);
        state.clockPaused = false;
        result = { ok: true, message: a.outcome ?? res.text };
      });
      return result;
    },

    bailAppointment: (mode = 'excuse') => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to bail on.' };
      set((state) => {
        const a = (state.appointments ?? []).find((x) => x.id === state.activeAppointment);
        const npc = a ? state.npcs.find((n) => n.id === a.npcId) : undefined;
        if (!a || !npc) { state.activeAppointment = null; return; }
        if (mode === 'excuse') pushDM(state, a.npcId, { fromPlayer: true, content: pickLine(['Something came up, I can\'t make it tonight 🙏🏾', 'Bro I\'m so sorry, can\'t make it', 'Can\'t come through tonight, my bad'], a.id) });
        const res = noShow(a, personaOf(npc), mode === 'ghost' ? 'missed' : 'bail', a.id);
        finishAppointment(state, a, res, mode === 'ghost' ? 'missed' : 'cancelled');
        state.clockPaused = false;
        result = { ok: true, message: res.text };
      });
      return result;
    },

    cypherRound: (move) => {
      let result = { ok: false, message: 'There is no cypher going on.' };
      set((state) => {
        const p = state.player;
        const a = (state.appointments ?? []).find((x) => x.id === state.activeAppointment);
        if (!p || !a || a.kind !== 'cypher' || !a.cypher) return;
        const rounds = a.cypherRounds ?? (a.cypherRounds = []);
        if (rounds.length >= CYPHER_ROUNDS) { result.message = 'That was the last round.'; return; }
        const m = CYPHER_MOVES[move];
        if (!m) return;
        if (p.energy < m.energy) { result.message = `You need ${m.energy} energy for that round. You're running on empty.`; return; }
        p.energy = Math.max(0, p.energy - m.energy);
        const r = playRound({ stats: p.stats, move, spec: a.cypher, prev: rounds, energy: p.energy, roll: Math.random(), me: p.artistName, seed: `${a.id}|${rounds.length}` });
        rounds.push(r);
        result = { ok: true, message: r.text };
      });
      return result;
    },

    cypherFinish: () => {
      let result: FeatureActionResult = { ok: false, message: 'There is no cypher going on.' };
      set((state) => {
        const p = state.player;
        const a = (state.appointments ?? []).find((x) => x.id === state.activeAppointment);
        if (!p || !a || a.kind !== 'cypher' || !a.cypher || !(a.cypherRounds ?? []).length) return;
        const before = { ...p.stats };
        const res = finishCypherNight({ spec: a.cypher, rounds: a.cypherRounds!, playerFame: blendedFame(p), me: p.artistName, stats: p.stats, seed: a.id });
        finishAppointment(state, a, { text: `${VERDICT_LABEL[res.verdict]} — ${res.text}`, npcLine: res.npcLine, effects: res.effects }, 'done');
        statUps(state, before, 'the cypher');
        if (res.verdict === 'legendary' || res.verdict === 'bodied') remember(state, 'music', res.verdict === 'legendary' ? `You bodied the cypher at ${a.place}.` : `You got bodied at the cypher at ${a.place}.`, { npcIds: [a.npcId], weight: 3, tone: res.verdict === 'legendary' ? 'good' : 'bad' });
        state.clockPaused = false;
        result = { ok: true, message: a.outcome ?? res.text };
      });
      return result;
    },

    setArrangement: (songId, arr) => {
      let result: { ok: boolean; message: string; notes: string[] } = { ok: false, message: 'That record is not in your vault.', notes: [] };
      set((state) => {
        const p = state.player;
        const song = state.songs.find((x) => x.id === songId);
        if (!p || !song) return;
        if (isSongReleased(song)) { result = { ok: false, message: `"${song.title}" is out — the layout is fixed now.`, notes: [] }; return; }
        const guests = (song.featuredArtists ?? []).map((id) => state.npcs.find((n) => n.id === id)).filter((n): n is NPC => !!n)
          .map((n) => ({ id: n.id, name: n.name, fame: n.fame, singer: /afro|rnb|r&b|dancehall|highlife|pop|soul|gospel|reggae/i.test(String(n.genre ?? '')) }));
        const clean = arr.filter((x) => x.who === 'player' || guests.some((g) => g.id === x.who)).slice(0, 14);
        const e = arrangementEffect(clean, guests, { playerFame: blendedFame(p), genre: String(song.genre) });
        const prev = song.arrangementBonus ?? { q: 0, c: 0 };
        song.quality = Math.max(1, Math.min(99, Math.round((song.quality + e.quality - prev.q) * 10) / 10));
        song.commercialPotential = Math.max(1, Math.min(100, (song.commercialPotential ?? 50) + e.commercial - prev.c));
        song.arrangement = clean;
        song.arrangementBonus = { q: e.quality, c: e.commercial };
        result = { ok: true, message: `Layout saved. "${song.title}" now reads ${describeScore(song.quality)}`, notes: e.notes };
      });
      return result;
    },

    applyBoothTake: (songId, take) => {
      let result: FeatureActionResult = { ok: false, message: 'That record is not in your vault.' };
      set((state) => {
        const p = state.player;
        const song = state.songs.find((x) => x.id === songId);
        if (!p || !song) return;
        if (isSongReleased(song)) { result.message = `"${song.title}" is already out — the vocal can't change now.`; return; }
        if (!spendEnergy(state, 10)) { result.message = energyShortfallMessage(10, p.energy); return; }
        const before = { ...p.stats };
        const was = song.vocalPerformance ?? 50;
        song.vocalPerformance = Math.round(was * 0.4 + take.score * 0.6);
        const delta = Math.max(-6, Math.min(6, (song.vocalPerformance - was) * 0.15));
        song.quality = Math.max(1, Math.min(99, Math.round((song.quality + delta) * 10) / 10));
        song.boothTake = { score: take.score, timing: take.timing, at: dateToSerial(state.gameDate), seconds: take.seconds };
        // Doing it for real is how you get better at it.
        const grow = (k: keyof ArtistStats, v: number) => { p.stats[k] = Math.min(100, (p.stats[k] ?? 0) + v * Math.max(0.3, 1 - (p.stats[k] ?? 0) / 120)); };
        grow('delivery', 0.25 + take.score / 400);
        grow('flow', 0.2 + take.timing / 500);
        grow('vocalAbility', 0.15);
        grow('consistency', 0.1);
        statUps(state, before, 'the booth');
        const read = take.score >= 80 ? 'a great take' : take.score >= 60 ? 'a solid take' : take.score >= 40 ? 'a rough take' : 'not really a take';
        result = { ok: true, message: `That's ${read} (${take.score}/100 — on-beat ${take.timing}, presence ${take.presence}). "${song.title}" ${delta >= 0.5 ? 'got better' : delta <= -0.5 ? 'lost a little' : 'held steady'}. ${describeScore(song.quality)}` };
      });
      return result;
    },

    settleTeamDispute: (optionId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to settle.' };
      set((state) => {
        const d = state.teamDispute;
        const p = state.player;
        if (!d || d.status !== 'open' || !p) return;
        const serial = dateToSerial(state.gameDate);
        const label = d.options.find((o) => o.id === optionId)?.label ?? '';
        const out = settleDispute(d, optionId, teamMembers(state), `${d.id}|${optionId}`);
        applyDisputeOutcome(state, out);
        const said = optionId === 'calm' ? label : optionId === 'a' ? `${d.a.name.split(' ')[0]} is right on this one.` : `${d.b.name.split(' ')[0]} is right on this one.`;
        pushTeamLines(state, [{ from: 'player', name: p.artistName, role: 'artist', text: said }, ...out.lines], serial);
        state.teamChatUnread = 0;
        d.status = 'settled';
        d.resolution = out.text;
        result = { ok: true, message: out.text };
      });
      return result;
    },

    ignoreInvite: (appointmentId) => {
      let result: FeatureActionResult = { ok: false, message: 'That invite has gone.' };
      set((state) => {
        const a = (state.appointments ?? []).find((x) => x.id === appointmentId && x.status === 'proposed');
        const npc = a ? state.npcs.find((n) => n.id === a.npcId) : undefined;
        if (!a || !npc) return;
        a.ignored = true;
        const pp = personaOf(npc);
        const now = nowMinuteOf(state);
        const first = npc.name.split(' ')[0];
        // Some people chase a read receipt. Some take the hint, loudly.
        if (!isRealId(npc.id)) {
          if (pp.warmth > 0.55 && pp.forgiveness > 0.4) scheduleDM(state, npc.id, pickLine(['You saw my message? 👀', 'Hello?? lol', 'No pressure, just let me know'], a.id), now + 60 + Math.floor(Math.random() * 120));
          else if (pp.ego > 0.65) scheduleDM(state, npc.id, pickLine(['Say less.', 'Aight. Noted.', 'Cool.'], a.id), now + 20 + Math.floor(Math.random() * 60));
        }
        const read = isRealId(npc.id) ? '' : pp.forgiveness < 0.35 || pp.ego > 0.7 ? `${first} won't take that well.` : pp.forgiveness > 0.65 ? `${first} probably won't hold it against you.` : `${first} will notice.`;
        result = { ok: true, message: `Left on read.${read ? ` ${read}` : ''}` };
      });
      return result;
    },

    // ─── DRIP ───────────────────────────────────────────────────────────
    openDrip: () => set((state) => { if (state.player) dripOf(state); }),

    buyDrip: (itemId) => {
      let result: FeatureActionResult = { ok: false, message: 'That piece is gone.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const d = dripOf(state);
        const item = d.shop.find((x) => x.id === itemId);
        if (!item) return;
        if (d.wardrobe.some((x) => x.id === itemId)) { result.message = 'Already in your wardrobe.'; return; }
        if (item.limited && (item.stock ?? 0) <= 0) { result.message = 'Sold out. Resellers have it at a markup now.'; return; }
        if (p.career.money < item.price) { result.message = `That's $${item.price.toLocaleString()}. You have $${Math.floor(p.career.money).toLocaleString()}.`; return; }
        p.career.money -= item.price;
        if (item.limited && item.stock) item.stock -= 1;
        const serial = dateToSerial(state.gameDate);
        d.wardrobe.unshift({ ...item, bought: serial, paid: item.price });
        const look = lookOfPlayer(state);
        if (look) look.outfit = { ...look.outfit, [item.slot]: { id: item.id, slot: item.slot, shape: item.shape, name: item.name, c1: item.c1, c2: item.c2, c3: item.c3, text: item.text } };
        if (item.price >= 2500 || item.limited || item.tier === 'grail') remember(state, 'style', `You copped the ${item.name}${item.colorway ? ` (${item.colorway})` : ''} for $${item.price.toLocaleString()}.`, { weight: item.tier === 'grail' ? 4 : 2, tone: 'good' });
        result = { ok: true, message: `Copped: ${item.name}. You've got it on.` };
      });
      return result;
    },

    equipDrip: (slot, itemId) => {
      let result: FeatureActionResult = { ok: false, message: 'Not in your wardrobe.' };
      set((state) => {
        const look = lookOfPlayer(state);
        if (!look) return;
        const d = dripOf(state);
        if (!itemId) {
          if (slot === 'top' || slot === 'bottom' || slot === 'shoes') { result.message = 'You need something on.'; return; }
          look.outfit = { ...look.outfit, [slot]: undefined };
          result = { ok: true, message: 'Taken off.' };
          return;
        }
        const it = d.wardrobe.find((x) => x.id === itemId && x.slot === slot);
        if (!it) return;
        look.outfit = { ...look.outfit, [slot]: { id: it.id, slot: it.slot, shape: it.shape, name: it.name, c1: it.c1, c2: it.c2, c3: it.c3, text: it.text } };
        result = { ok: true, message: `Wearing ${it.name}.` };
      });
      return result;
    },

    sellDrip: (itemId) => {
      let result: FeatureActionResult = { ok: false, message: 'Not in your wardrobe.' };
      set((state) => {
        const p = state.player;
        const look = lookOfPlayer(state);
        if (!p || !look) return;
        const d = dripOf(state);
        const it = d.wardrobe.find((x) => x.id === itemId);
        if (!it) return;
        const worn = look.outfit[it.slot]?.id === it.id;
        if (worn && (it.slot === 'top' || it.slot === 'bottom' || it.slot === 'shoes')) { result.message = 'Change out of it first.'; return; }
        const serial = dateToSerial(state.gameDate);
        const value = resaleValue(it, serial, d.lines);
        p.career.money += value;
        d.wardrobe = d.wardrobe.filter((x) => x.id !== itemId);
        if (worn) look.outfit = { ...look.outfit, [it.slot]: undefined };
        result = { ok: true, message: value > 0 ? `Sold ${it.name} for $${value.toLocaleString()}${value > it.paid ? ' — more than you paid' : ''}.` : `Gave ${it.name} away.` };
      });
      return result;
    },

    getTattoo: (spot, design) => {
      let result: FeatureActionResult = { ok: false, message: 'The studio is closed.' };
      let minutes = 0;
      set((state) => {
        const p = state.player;
        const look = lookOfPlayer(state);
        if (!p || !look) return;
        const q = tattooQuote(spot, design);
        const existing = look.tattoos.find((t) => t.spot === spot);
        const price = Math.round(q.price * (existing ? 1.3 : 1));
        if (p.career.money < price) { result.message = `That piece is $${price.toLocaleString()}.`; return; }
        const energy = Math.min(24, q.hours * 4);
        if (!spendEnergy(state, energy, { admin: true })) { result.message = `${q.hours} hours in the chair takes ${energy} energy. Rest first.`; return; }
        p.career.money -= price;
        const serial = (look.tattoos.reduce((m, t) => Math.max(m, t.serial), 0) || 0) + 1;
        look.tattoos = [...look.tattoos.filter((t) => t.spot !== spot), { id: uuidv4(), spot, design, serial }];
        minutes = q.hours * 60;
        const where = spot.replace('_', ' ');
        remember(state, 'style', existing ? `You covered up your ${where} tattoo with a ${q.label.toLowerCase()}.` : `You got a ${q.label.toLowerCase()} tattoo on your ${where}.`, { weight: spot === 'face' || design === 'sleeve' ? 4 : 2 });
        if (spot === 'face' && blendedFame(p) >= 20) state.headlines.unshift({ id: uuidv4(), text: `${p.artistName} debuts a new face tattoo`, fullStory: `Fans are split on the new ${q.label.toLowerCase()}.`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 3, category: 'general' });
        result = { ok: true, message: `${q.hours} hour${q.hours > 1 ? 's' : ''} later: fresh ink. ${existing ? 'The old one is gone under it.' : 'It\'s permanent.'}` };
      });
      if (minutes) passTime(minutes);
      return result;
    },

    removeTattoo: (tattooId) => {
      let result: FeatureActionResult = { ok: false, message: 'No such tattoo.' };
      let minutes = 0;
      set((state) => {
        const p = state.player;
        const look = lookOfPlayer(state);
        if (!p || !look) return;
        const t = look.tattoos.find((x) => x.id === tattooId);
        if (!t) return;
        const q = removalQuote(t);
        if (p.career.money < q.price) { result.message = `Laser removal is $${q.price.toLocaleString()} — three times what it cost to put on.`; return; }
        p.career.money -= q.price;
        look.tattoos = look.tattoos.filter((x) => x.id !== tattooId);
        minutes = q.hours * 60;
        remember(state, 'style', `You had your ${t.spot.replace('_', ' ')} tattoo lasered off.`, { weight: 2 });
        result = { ok: true, message: `Gone, for $${q.price.toLocaleString()}. That stung.` };
      });
      if (minutes) passTime(minutes);
      return result;
    },

    visitBarber: (next) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to change.' };
      let minutes = 0;
      set((state) => {
        const p = state.player;
        const look = lookOfPlayer(state);
        if (!p || !look) return;
        const q = barberQuote(look, next);
        if (!q.price) return;
        if (p.career.money < q.price) { result.message = `That's $${q.price} at the shop.`; return; }
        p.career.money -= q.price;
        const big = next.hair !== look.hair;
        p.look = { ...look, hair: next.hair, hairColor: next.hairColor, facialHair: next.facialHair };
        minutes = Math.max(30, q.hours * 60);
        if (big) remember(state, 'style', `New hair: ${next.hair.replace(/_/g, ' ')}.`, { weight: 1 });
        result = { ok: true, message: `Fresh. $${q.price}${q.hours > 1 ? `, ${q.hours} hours in the chair` : ''}.` };
      });
      if (minutes) passTime(minutes);
      return result;
    },

    postFit: (caption) => {
      const st = get();
      const look = st.player?.look;
      const d = st.drip;
      if (!look || !d) return { ok: false, message: 'Get dressed first.' };
      const fresh = Object.values(look.outfit).filter((w): w is Wearable => !!w && !d.flexed.includes(w.id) && d.wardrobe.some((x) => x.id === w.id && x.paid > 0));
      const pieces = fresh.map((w) => w.name).slice(0, 2);
      const content = caption.trim() || (pieces.length ? `Fit check. ${pieces.join(' + ')} 🔥` : 'Fit check 📸');
      const r = st.publishPost({ apps: ['snapgram'], kind: 'photo', content, fit: true });
      if (r.ok) set((state) => { const dd = dripOf(state); dd.flexed = [...dd.flexed, ...fresh.map((w) => w.id)].slice(-200); remember(state, 'style', `You posted a fit pic${pieces.length ? ` in the ${pieces[0]}` : ''}${r.viral ? ' and it went viral' : ''}.`, { weight: r.viral ? 3 : 1, tone: 'good' }); });
      return r;
    },

    // ─── THE JOURNAL ────────────────────────────────────────────────────
    pinMemory: (id, pinned) => set((state) => {
      const m = (state.memories ?? []).find((x) => x.id === id);
      if (m) m.pinned = pinned;
    }),
    addJournalNote: (text) => set((state) => {
      const t = text.trim();
      if (t) remember(state, 'life', t.slice(0, 200), { weight: 3 });
    }),


    askToDropAct: (offerId, npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'That offer is closed.' };
      set((state) => {
        if (!state.player) return;
        const offer = state.showOffers.find((o) => o.id === offerId);
        if (!offer || offer.status !== 'open') return;
        const act = (offer.lineup ?? []).find((a) => a.npcId === npcId);
        const host = state.npcs.find((n) => n.id === offer.hostId);
        if (!act || !host) { result.message = 'They are not on this bill.'; return; }
        if (act.npcId === offer.hostId) { result.message = 'You cannot ask the host to leave their own show.'; return; }
        if (offer.log.some((l) => l.startsWith('You asked to drop'))) { result.message = 'You already made that ask. Twice is a tantrum.'; return; }
        const d = dropActDecision({ host: host as NPC, playerFame: blendedFame(state.player), act: act as LineupAct, roll: Math.random() });
        offer.log = [`You asked to drop ${act.name}. ${d.text}`, ...offer.log];
        const serial = dateToSerial(state.gameDate);
        const rival = state.npcs.find((n) => n.id === npcId);
        if (d.outcome === 'dropped') {
          offer.lineup = (offer.lineup ?? []).filter((a) => a.npcId !== npcId);
          if (rival) rival.relationshipScore = Math.max(-100, rival.relationshipScore - 6);
          nudgeBeef(state, npcId, 8, serial);
          result = { ok: true, message: `${d.text} ${act.name} will hear about it.` };
        } else if (d.outcome === 'refused') {
          offer.patience = Math.max(0, offer.patience - 1);
          host.relationshipScore = Math.max(-100, host.relationshipScore - 2);
          result = { ok: false, message: d.text };
        } else {
          offer.status = 'walked';
          host.relationshipScore = Math.max(-100, host.relationshipScore - 4);
          result = { ok: false, message: d.text };
        }
      });
      return result;
    },

    setGigAvoidRival: (gigId, avoid) =>
      set((state) => {
        const gig = state.bookedGigs.find((g) => g.id === gigId);
        if (gig) gig.avoidRival = avoid;
      }),

    showGuestCandidates: (showId, role) => {
      const state = get();
      const show = state.scheduledShows.find((s) => s.id === showId);
      if (!show || !state.player) return [];
      const fame = blendedFame(state.player);
      const beefs = activeBeefIds(state);
      const taken = new Set((show.guests ?? []).map((g) => g.npcId));
      const out: { npc: NPC; fee: number; beef: boolean; score: number }[] = [];
      for (const n of state.npcs) {
        if (n.role !== 'artist' || taken.has(n.id)) continue;
        if (role === 'opener' && n.fame > fame + 5) continue;
        if (n.fame > fame + 35) continue;
        const near = n.country === show.country;
        if (!near && n.relationshipScore < 30) continue;
        // People you know first, then names who would actually say yes:
        // near your level, from that city's country.
        const fit = role === 'special_guest' ? -Math.abs(n.fame - (fame + 8)) : -Math.abs(n.fame - (fame - 10));
        const score = n.relationshipScore * 2 + (near ? 15 : 0) + fit * 1.5 + (beefs.has(n.id) ? -500 : 0);
        out.push({ npc: n, fee: guestFee(n, fame, show.capacity), beef: beefs.has(n.id), score });
      }
      return out.sort((a, b) => b.score - a.score).slice(0, 12).map(({ npc, fee, beef }) => ({ npc, fee, beef }));
    },

    inviteShowGuest: (showId, npcId, role, fee) => {
      let result: FeatureActionResult = { ok: false, message: 'That show is not on sale.' };
      set((state) => {
        if (!state.player) return;
        const show = state.scheduledShows.find((s) => s.id === showId);
        if (!show) return;
        show.guests = show.guests ?? [];
        if (show.guests.filter((g) => g.status === 'confirmed').length >= 3) { result.message = 'Three guests is a festival, not a show.'; return; }
        if (show.guests.some((g) => g.npcId === npcId && g.status === 'confirmed')) { result.message = 'They are already on the bill.'; return; }
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!npc) return;
        const serial = dateToSerial(state.gameDate);
        if (show.serial - serial < 2) { result.message = 'Too late to change the poster.'; return; }
        const fame = blendedFame(state.player);
        const quoted = guestFee(npc as NPC, fame, show.capacity);
        const busy = state.bookedGigs.some((g) => g.serial === show.serial && g.hostId === npcId);
        const beef = activeBeefIds(state).has(npcId);
        const raw0 = guestAnswer({ npc: npc as NPC, playerFame: fame, role, fee, quoted, beefWithPlayer: beef, busy, roll: Math.random() });
        // Real artists' replies come from their team — nobody puts words in their mouth.
        const ans = isRealId(npc.id)
          ? { yes: raw0.yes, text: raw0.yes ? '[Their team] Confirmed — they will be there.' : '[Their team] Not available for this date.' }
          : raw0;
        const thread = state.dmThreads[npcId] ?? { npcId, messages: [], unread: 0 };
        thread.messages.push({ id: uuidv4(), npcId, fromPlayer: true, content: `Want to ${role === 'special_guest' ? 'come out as my special guest' : 'open for me'} at ${show.city} on ${formatGameDate(serialToDate(show.serial))}? I can do $${fee.toLocaleString()}.`, timestamp: new Date().toISOString(), read: true });
        thread.messages.push({ id: uuidv4(), npcId, fromPlayer: false, content: ans.text, timestamp: new Date().toISOString(), read: true });
        state.dmThreads[npcId] = thread;
        if (!ans.yes) {
          show.guests.push({ npcId, name: npc.name, fame: Math.round(npc.fame), role, fee, status: 'declined', askedSerial: serial });
          if (fee < quoted * 0.6) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 2);
          result = { ok: false, message: `${npc.name}: ${ans.text}` };
          return;
        }
        show.guests = show.guests.filter((g) => g.npcId !== npcId);
        show.guests.push({ npcId, name: npc.name, fame: Math.round(npc.fame), role, fee, status: 'confirmed', askedSerial: serial });
        show.notes.unshift(`${npc.name} confirmed as ${role === 'special_guest' ? 'special guest' : 'opener'} ($${fee.toLocaleString()} on the night).`);
        npc.relationshipScore = Math.min(100, npc.relationshipScore + 2);
        if (role === 'special_guest') {
          state.socialPosts.unshift({
            id: uuidv4(), platform: 'chirp', authorId: 'player', authorName: state.player.artistName,
            content: `${show.city}. ${formatGameDate(serialToDate(show.serial))}. Special guest: ${npc.name}. 🎤 Get your tickets.`,
            likes: Math.round(30 + (fame + npc.fame) * 20), shares: Math.round(5 + npc.fame * 3), comments: [],
            timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 10 + npc.fame / 3, daySerial: serial,
          });
        }
        result = { ok: true, message: `${npc.name}: ${ans.text} They're on the poster — watch ticket sales move.` };
      });
      return result;
    },

    removeShowGuest: (showId, npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'Not on the bill.' };
      set((state) => {
        const show = state.scheduledShows.find((s) => s.id === showId);
        const g = show?.guests?.find((x) => x.npcId === npcId && x.status === 'confirmed');
        if (!show || !g) return;
        show.guests = (show.guests ?? []).filter((x) => x !== g);
        const npc = state.npcs.find((n) => n.id === npcId);
        if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 8);
        show.notes.unshift(`Took ${g.name} off the bill.`);
        result = { ok: true, message: `${g.name} is off the bill. They did not take it well.` };
      });
      return result;
    },

    backOutOfGig: (gigId) => {
      let result: FeatureActionResult = { ok: false, message: 'No such date.' };
      set((state) => {
        const gig = state.bookedGigs.find((g) => g.id === gigId);
        const npc = gig ? state.npcs.find((n) => n.id === gig.hostId) : undefined;
        if (!gig || !state.player) return;
        const now = dateToSerial(state.gameDate);
        const t = backOutTerms(gig, gig.serial - now, npc?.tier ?? 'local');
        state.player.career.money -= t.penalty;
        state.player.career.reputation = Math.max(0, state.player.career.reputation + t.reputation);
        if (npc) {
          npc.relationshipScore = Math.max(-100, npc.relationshipScore + t.relationship);
          npc.memoryLog = [`Backed out of their ${gig.city} date`, ...(npc.memoryLog ?? [])].slice(0, 10);
        }
        state.bookedGigs = state.bookedGigs.filter((g) => g.id !== gigId);
        state.lastEventLog.unshift(`🚫 Backed out of ${gig.hostName}'s ${gig.city} date. -$${t.penalty.toLocaleString()}.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        result = {
          ok: true,
          message: `You pulled out. $${t.penalty.toLocaleString()} penalty, ${t.relationship} relationship, ${t.reputation} reputation.`,
        };
      });
      return result;
    },

    // ─── SCHEDULED SHOWS ─────────────────────────────────────────────────
    //
    // A show is announced, sold over weeks, and played on its night. The
    // clock does the playing: nothing here settles a show, it only commits,
    // reprices, promotes, moves or cancels one. The tick sells the tickets
    // and plays the night (see "SCHEDULED SHOWS" in `advanceTurnBy`).
    scheduleShow: (venueId, type, price, serial) => {
      let result: FeatureActionResult = { ok: false, message: 'That room is not on the list.' };

      set((state) => {
        if (!state.player) return;
        if (state.legacy.retired) { result = { ok: false, message: 'You\'re retired. Go semi-retired (Industry & Life) or announce a comeback to play shows.' }; return; }
        const venue = findVenue(venueId);
        if (!venue) return;

        const now = dateToSerial(state.gameDate);
        const lead = serial - now;
        const need = MIN_LEAD_DAYS[venue.cls];
        if (lead < need) {
          result = {
            ok: false,
            message: `${VENUE_CLASS_LABEL[venue.cls]} dates need at least ${need} days to sell. The earliest you can announce is ${formatGameDate(serialToDate(now + need))}.`,
          };
          return;
        }
        if (lead > MAX_LEAD_DAYS) {
          result = { ok: false, message: `Nobody books more than ${MAX_LEAD_DAYS} days out.` };
          return;
        }
        if (state.scheduledShows.length >= MAX_OPEN_SHOWS) {
          result = {
            ok: false,
            message: `You already have ${MAX_OPEN_SHOWS} shows on sale. Play or cancel one first.`,
          };
          return;
        }

        const fame = blendedFame(state.player);
        const lock = venueLockReason(venue, fame);
        if (lock) {
          result = { ok: false, message: lock };
          return;
        }
        const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
        const gate = slotRequirement(
          type, venue, state.player.country, fame, bonuses.promoterCut, bonuses.logisticsMult,
        );
        if (gate) {
          result = { ok: false, message: gate };
          return;
        }

        // ── Is the night yours to sell? ───────────────────────────────
        if (!isNightFree(venue, serial)) {
          result = { ok: false, message: `${venue.name} is already booked that night. Pick another date.` };
          return;
        }
        const ownClash = state.scheduledShows.find((s) => s.serial === serial);
        if (ownClash) {
          result = { ok: false, message: `You are already playing ${ownClash.city} that night.` };
          return;
        }
        const tourClash = state.tours.find(
          (t) => t.status !== 'cancelled' && t.legs.some((l) => l.playedSerial === undefined && l.serial === serial),
        );
        if (tourClash) {
          result = { ok: false, message: `${tourClash.name} has you on the road that night.` };
          return;
        }

        const gigClash = state.bookedGigs.find((g) => g.serial === serial);
        if (gigClash) {
          result = { ok: false, message: `You are on ${gigClash.hostName}'s bill that night.` };
          return;
        }
        const radius = state.bookedGigs.find(
          (g) => g.terms.exclusivityDays > 0 && g.city === venue.city && Math.abs(g.serial - serial) < g.terms.exclusivityDays,
        );
        if (radius) {
          result = {
            ok: false,
            message: `${radius.hostName}'s radius clause bars you from playing ${venue.city} within ${radius.terms.exclusivityDays} days of ${formatGameDate(serialToDate(radius.serial))}.`,
          };
          return;
        }

        // ── The city needs a breather ─────────────────────────────────
        // Measured against every date the player has in this city, played OR
        // still to come, so announcing three nights in a week cannot dodge the
        // cooldown by being sold before any of them is played.
        const gap = VENUE_CLASSES[venue.cls].cooldownDays;
        const others = [
          ...state.scheduledShows.filter((s) => s.city === venue.city).map((s) => s.serial),
          ...(state.cityMarkets[venue.city]?.lastShowSerial !== undefined
            ? [state.cityMarkets[venue.city]!.lastShowSerial as number]
            : []),
        ];
        const tooClose = others.find((o) => Math.abs(o - serial) < gap);
        if (tooClose !== undefined) {
          result = {
            ok: false,
            message: `${venue.city} needs ${gap} days between your shows. You have a date on ${formatGameDate(serialToDate(tooClose))}.`,
          };
          return;
        }

        const input = showInputFrom(state, venue, price, serial);
        const plan = planShow(input);
        const deposit = Math.round((venue.hireCost * input.venueHireMult * 0.25) / 10) * 10;
        if (state.player.career.money < deposit) {
          result = {
            ok: false,
            message: `Holding ${venue.name} takes a $${deposit.toLocaleString()} deposit. You have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }
        if (plan.tickets.likely === 0) {
          result = { ok: false, message: 'At that price nobody is coming. Lower the ticket price first.' };
          return;
        }

        state.player.career.money -= deposit;
        const show: ScheduledShow = {
          id: uuidv4(),
          type,
          venueId: venue.id,
          city: venue.city,
          country: venue.country,
          serial,
          originalSerial: serial,
          announcedSerial: now,
          price,
          capacity: venue.capacity,
          luck: 0.82 + Math.random() * 0.36,
          ticketsSold: 0,
          salesCursor: now,
          deposit,
          marketingSpend: 0,
          postponements: 0,
          status: 'on_sale',
          remindersSent: [],
          sales: [{ serial: now, sold: 0 }],
          notes: [`Announced for ${formatGameDate(serialToDate(serial))} at $${price}.`],
          milestone: 0,
        };
        state.scheduledShows.push(show);

        const when = formatGameDate(serialToDate(serial));
        state.lastEventLog.unshift(`🎟️ ${venue.name} announced for ${when}. Tickets on sale at $${price}.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        state.mailbox.unshift({
          id: uuidv4(),
          from: 'booking_desk',
          fromName: 'Booking desk',
          subject: `🎟️ On sale: ${venue.name}, ${venue.city} — ${when}`,
          body:
            `Tickets for ${venue.name} (${venue.capacity.toLocaleString()} capacity) are live at $${price}.\n\n` +
            `Deposit paid: $${deposit.toLocaleString()}. You will get updates as they sell, and a reminder as the night gets close. ` +
            `If sales are slow you can cut the price, add promotion, move the date or cancel — the sooner the cheaper.`,
          timestamp: new Date().toISOString(),
          read: false,
          type: 'general',
        });

        result = {
          ok: true,
          message: `Announced ${venue.name} for ${when}. $${deposit.toLocaleString()} deposit paid. Tickets are on sale.`,
        };
      });

      return result;
    },

    repriceScheduledShow: (id, price) => {
      let result: FeatureActionResult = { ok: false, message: 'No such show.' };
      set((state) => {
        const show = state.scheduledShows.find((s) => s.id === id);
        if (!show || !state.player) return;
        const p = Math.max(5, Math.round(price));
        if (p === show.price) {
          result = { ok: false, message: 'That is already the price.' };
          return;
        }
        const was = show.price;
        show.price = p;
        show.notes.unshift(
          p < was
            ? `Price cut $${was} → $${p}. Earlier buyers keep their tickets.`
            : `Price raised $${was} → $${p}.`,
        );
        show.notes = show.notes.slice(0, 12);
        result = {
          ok: true,
          message: p < was
            ? `Tickets now $${p}. A cut brings in new buyers — expect a bump in sales.`
            : `Tickets now $${p}. Fewer new buyers at the higher price.`,
        };
      });
      return result;
    },

    promoteScheduledShow: (id, tierId) => {
      let result: FeatureActionResult = { ok: false, message: 'No such show.' };
      set((state) => {
        const show = state.scheduledShows.find((s) => s.id === id);
        if (!show || !state.player) return;
        const tier = MARKETING_TIERS.find((t) => t.id === tierId);
        if (!tier) return;
        if (show.serial - dateToSerial(state.gameDate) < 2) {
          result = { ok: false, message: 'Too late to promote — the show is the day after tomorrow or sooner.' };
          return;
        }
        const cost = marketingCost(tier, show.capacity, show.price);
        if (state.player.career.money < cost) {
          result = {
            ok: false,
            message: `${tier.label} costs $${cost.toLocaleString()}. You have $${Math.floor(state.player.career.money).toLocaleString()}.`,
          };
          return;
        }
        state.player.career.money -= cost;
        show.marketingSpend += cost;
        show.notes.unshift(`${tier.label}: $${cost.toLocaleString()} spent.`);
        show.notes = show.notes.slice(0, 12);
        result = { ok: true, message: `${tier.label} is running. $${cost.toLocaleString()} spent.` };
      });
      return result;
    },

    quoteScheduledCancel: (id, reason) => {
      const state = get();
      const show = state.scheduledShows.find((s) => s.id === id);
      const venue = show ? findVenue(show.venueId) : undefined;
      if (!show || !venue || !state.player) return null;
      const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
      return cancelTerms({
        daysOut: show.serial - dateToSerial(state.gameDate),
        deposit: show.deposit,
        hireCost: Math.round(venue.hireCost * bonuses.venueHireMult),
        ticketsSold: show.ticketsSold,
        reason,
        energyRatio: state.player.energy / Math.max(1, state.player.maxEnergy),
        cutRelief: bonuses.cutRelief,
      });
    },

    cancelScheduledShow: (id, reason) => {
      let result: FeatureActionResult = { ok: false, message: 'No such show.' };
      set((state) => {
        const show = state.scheduledShows.find((s) => s.id === id);
        const venue = show ? findVenue(show.venueId) : undefined;
        if (!show || !venue || !state.player) return;

        const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
        const terms = cancelTerms({
          daysOut: show.serial - dateToSerial(state.gameDate),
          deposit: show.deposit,
          hireCost: Math.round(venue.hireCost * bonuses.venueHireMult),
          ticketsSold: show.ticketsSold,
          reason,
          energyRatio: state.player.energy / Math.max(1, state.player.maxEnergy),
          cutRelief: bonuses.cutRelief,
        });

        // The deposit is already gone. Anything beyond it is billed now.
        const extra = Math.max(0, terms.penalty - show.deposit);
        state.player.career.money -= extra;
        state.player.career.reputation = Math.max(
          0,
          state.player.career.reputation + terms.reputation * bonuses.controversyMult,
        );
        state.scheduledShows = state.scheduledShows.filter((s) => s.id !== id);

        const what = `${venue.name}, ${venue.city}`;
        state.lastEventLog.unshift(
          `🚫 ${what} cancelled. ${show.ticketsSold.toLocaleString()} tickets refunded. -$${terms.penalty.toLocaleString()}.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        state.mailbox.unshift({
          id: uuidv4(),
          from: 'booking_desk',
          fromName: 'Booking desk',
          subject: `🚫 Cancelled: ${what}`,
          body:
            `${show.ticketsSold.toLocaleString()} ticket-holders are being refunded in full.\n\n` +
            `${terms.explain}\n\nTotal cost to you: $${terms.penalty.toLocaleString()}.`,
          timestamp: new Date().toISOString(),
          read: false,
          type: 'general',
        });

        if (terms.backlash !== 'none') {
          const fan = state.npcs.find((n) => n.role === 'fan_account');
          if (fan) {
            state.socialPosts.unshift({
              id: uuidv4(),
              platform: 'chirp',
              authorId: fan.id,
              authorName: fan.name,
              content: terms.backlash === 'loud'
                ? `Cancelled the week of?? ${state.player.artistName} had people booking flights for ${show.city}. Not good enough. 😤`
                : `${state.player.artistName} just called off the ${show.city} show. Refunds are coming but man, we wanted this one.`,
              likes: Math.max(20, show.ticketsSold),
              shares: Math.round(show.ticketsSold / 6),
              comments: [],
              timestamp: new Date().toISOString(),
              isPlayerPost: false,
              trendingScore: terms.backlash === 'loud' ? 55 : 25,
              daySerial: dateToSerial(state.gameDate),
            });
          }
          state.headlines.unshift({
            id: uuidv4(),
            text: terms.backlash === 'loud'
              ? `${state.player.artistName} pulls ${show.city} show days before the doors`
              : `${state.player.artistName} cancels ${show.city} date`,
            fullStory: `${terms.explain} ${show.ticketsSold.toLocaleString()} fans were refunded.`,
            date: formatGameDate(serialToDate(dateToSerial(state.gameDate))),
            relatedEntities: [state.player.id],
            priority: terms.backlash === 'loud' ? 5 : 2,
            category: 'show',
          });
        }

        result = {
          ok: true,
          message: `${what} is off. ${terms.explain} It cost $${terms.penalty.toLocaleString()}.`,
        };
      });
      return result;
    },

    quoteScheduledPostpone: (id, newSerial) => {
      const state = get();
      const show = state.scheduledShows.find((s) => s.id === id);
      const venue = show ? findVenue(show.venueId) : undefined;
      if (!show || !venue || !state.player) return null;
      const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
      return postponeTerms({
        daysOut: show.serial - dateToSerial(state.gameDate),
        moveDays: Math.max(1, newSerial - show.serial),
        hireCost: Math.round(venue.hireCost * bonuses.venueHireMult),
        ticketsSold: show.ticketsSold,
        postponements: show.postponements,
      });
    },

    postponeScheduledShow: (id, newSerial) => {
      let result: FeatureActionResult = { ok: false, message: 'No such show.' };
      set((state) => {
        const show = state.scheduledShows.find((s) => s.id === id);
        const venue = show ? findVenue(show.venueId) : undefined;
        if (!show || !venue || !state.player) return;

        const now = dateToSerial(state.gameDate);
        if (show.postponements >= MAX_POSTPONEMENTS) {
          result = { ok: false, message: 'You have already moved this one twice. Promoters will not do it a third time.' };
          return;
        }
        if (newSerial <= show.serial) {
          result = { ok: false, message: 'Pick a date after the current one.' };
          return;
        }
        if (newSerial - now > MAX_LEAD_DAYS) {
          result = { ok: false, message: `Nobody books more than ${MAX_LEAD_DAYS} days out.` };
          return;
        }
        if (!isNightFree(venue, newSerial)) {
          result = { ok: false, message: `${venue.name} is booked on ${formatGameDate(serialToDate(newSerial))}.` };
          return;
        }
        if (state.scheduledShows.some((s) => s.id !== id && s.serial === newSerial)) {
          result = { ok: false, message: 'You already have a show that night.' };
          return;
        }
        const gap = VENUE_CLASSES[venue.cls].cooldownDays;
        const clash = state.scheduledShows.find(
          (s) => s.id !== id && s.city === venue.city && Math.abs(s.serial - newSerial) < gap,
        );
        if (clash) {
          result = { ok: false, message: `That is too close to your ${formatGameDate(serialToDate(clash.serial))} date in ${venue.city}.` };
          return;
        }

        const bonuses = crewBonuses(raw(state.crew) as CrewMember[]);
        const terms = postponeTerms({
          daysOut: show.serial - now,
          moveDays: newSerial - show.serial,
          hireCost: Math.round(venue.hireCost * bonuses.venueHireMult),
          ticketsSold: show.ticketsSold,
          postponements: show.postponements,
        });
        if (state.player.career.money < terms.fee) {
          result = { ok: false, message: `Moving the date costs $${terms.fee.toLocaleString()}. You have $${Math.floor(state.player.career.money).toLocaleString()}.` };
          return;
        }

        state.player.career.money -= terms.fee;
        state.player.career.reputation = Math.max(
          0,
          state.player.career.reputation + terms.reputation * bonuses.controversyMult,
        );
        const oldWhen = formatGameDate(serialToDate(show.serial));
        const newWhen = formatGameDate(serialToDate(newSerial));
        show.ticketsSold -= terms.refunds;
        show.serial = newSerial;
        show.postponements += 1;
        show.status = 'on_sale';
        show.remindersSent = [];
        show.milestone = Math.min(show.milestone, Math.floor((show.ticketsSold / Math.max(1, show.capacity)) * 4) * 25);
        show.notes.unshift(`Postponed ${oldWhen} → ${newWhen}. ${terms.refunds.toLocaleString()} refunds.`);
        show.notes = show.notes.slice(0, 12);

        state.lastEventLog.unshift(`📅 ${venue.name} moved to ${newWhen}. ${terms.refunds.toLocaleString()} refunds.`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        state.mailbox.unshift({
          id: uuidv4(),
          from: 'booking_desk',
          fromName: 'Booking desk',
          subject: `📅 Postponed: ${venue.name} is now ${newWhen}`,
          body:
            `Ticket-holders have been told. ${terms.refunds.toLocaleString()} asked for a refund and ${show.ticketsSold.toLocaleString()} are keeping their seats.\n\n` +
            `${terms.explain}`,
          timestamp: new Date().toISOString(),
          read: false,
          type: 'general',
        });

        result = {
          ok: true,
          message: `Moved to ${newWhen}. $${terms.fee.toLocaleString()} in fees, ${terms.refunds.toLocaleString()} refunds.`,
        };
      });
      return result;
    },

    cancelTour: (tourId) => {
      let result: FeatureActionResult = { ok: false, message: 'No such tour.' };
      set((state) => {
        const tour = state.tours.find((t) => t.id === tourId);
        if (!tour) return;
        if (tour.status === 'done') {
          result = { ok: false, message: 'That run is already finished.' };
          return;
        }
        if (tour.status === 'cancelled') {
          result = { ok: false, message: 'That run is already off.' };
          return;
        }
        // Dates already played stay in the history — you cannot un-play a show.
        const played = tour.legs.filter((l) => l.playedSerial !== undefined).length;
        tour.status = 'cancelled';
        state.lastEventLog.unshift(
          `🚫 ${tour.name} called off — ${played} of ${tour.legs.length} dates were already played.`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        result = {
          ok: true,
          message: `Called off. ${played} of ${tour.legs.length} dates had already been played and stay in the history.`,
        };
      });
      return result;
    },

    // ─── INVESTMENTS ─────────────────────────────────────────────────────
    buyInvestment: (type, name, cost, riskLevel) =>
      set((state) => {
        if (!state.player || state.player.career.money < cost) return;

        state.player.career.money -= cost;

        const monthlyIncomeRates: Record<string, number> = {
          real_estate: 0.005,
          stock: 0,
          music_catalog: 0.008,
          restaurant: 0.03,
          tech_startup: 0,
          clothing_brand: 0.02,
        };

        const investment: Investment = {
          id: uuidv4(),
          type,
          name,
          initialCost: cost,
          currentValue: cost,
          monthlyIncome: cost * (monthlyIncomeRates[type] ?? 0),
          riskLevel,
          purchaseDate: formatGameDate(state.gameDate),
        };

        state.investments.push(investment);
      }),

    sellInvestment: (investmentId) =>
      set((state) => {
        if (!state.player) return;
        const idx = state.investments.findIndex(i => i.id === investmentId);
        if (idx === -1) return;
        const inv = state.investments[idx];
        state.player.career.money += inv.currentValue;
        state.investments.splice(idx, 1);
      }),

    // ─── BUSINESSES ─────────────────────────────────────────────────────
    buyBusiness: (type, name, cost) =>
      set((state) => {
        if (!state.player) return;
        if (state.player.career.money < cost) return;
        if (state.businesses.some(b => b.type === type)) return;
        // Labels are founded from My Label now, not bought as a flat earner.
        if (type === 'record_label') return;

        state.player.career.money -= cost;

        // Each business pays back its purchase price over roughly 5 years.
        // Profitability scales with the player's business knowledge — a
        // sharper operator runs leaner costs, not bigger revenue.
        const revenueRate: Record<string, number> = {
          record_label: 0.028,
          recording_studio: 0.030,
          clothing_line: 0.024,
          nightclub: 0.026,
          media_company: 0.023,
        };
        const costRate: Record<string, number> = {
          record_label: 0.011,
          recording_studio: 0.009,
          clothing_line: 0.008,
          nightclub: 0.012,
          media_company: 0.007,
        };

        const skill = state.player.stats.businessKnowledge ?? 50;
        const efficiency = 1 - (skill - 50) / 250; // 0.8 at skill 100, 1.2 at skill 0
        const monthlyRevenue = cost * (revenueRate[type] ?? 0.02);
        const monthlyCosts = cost * (costRate[type] ?? 0.01) * efficiency;

        const business: Business = {
          id: uuidv4(),
          type,
          name,
          monthlyRevenue,
          monthlyCosts,
          reputation: 50,
          purchaseDate: formatGameDate(state.gameDate),
        };

        state.businesses.push(business);

        const post: SocialPost = {
          id: uuidv4(),
          platform: 'chirp',
          authorId: 'player',
          authorName: state.player.artistName,
          content: `New venture: I own a ${name.toLowerCase()} now. Bought and paid for. 🏢`,
          likes: 0,
          shares: 0,
          comments: [],
          timestamp: formatGameDate(state.gameDate),
          isPlayerPost: true,
          trendingScore: 12,
        };
        state.socialPosts.unshift(post);

        state.lastEventLog.unshift(`Bought ${name} for $${cost.toLocaleString()}`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      }),

    sellBusiness: (businessId) =>
      set((state) => {
        if (!state.player) return;
        const idx = state.businesses.findIndex(b => b.id === businessId);
        if (idx === -1) return;
        const biz = state.businesses[idx];
        // Resale value is derived back from monthly revenue (the purchase price
        // is not stored on the record), discounted 30% for it being used.
        const value = Math.round((biz.monthlyRevenue / 0.026) * 0.7);
        state.player.career.money += value;
        state.businesses.splice(idx, 1);
        state.lastEventLog.unshift(`Sold ${biz.name} for $${value.toLocaleString()}`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
      }),

    // ─── MONEY: SHARES & CRYPTO ─────────────────────────────────────────
    buyAsset: (kind, ticker, dollars) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not buy.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const m = marketOf(state);
        const asset = kind === 'stock' ? m.stocks.find((s) => s.ticker === ticker) : m.coins.find((c) => c.ticker === ticker);
        if (!asset) { result.message = 'Not listed.'; return; }
        if ('dead' in asset && asset.dead) { result.message = `${asset.name} is dead. Nobody is selling it to you.`; return; }
        dollars = Math.round(dollars);
        if (!Number.isFinite(dollars) || dollars < 50) { result.message = 'The minimum order is $50.'; return; }
        if (dollars > p.career.money) { result.message = 'You don\'t have that much cash.'; return; }
        const fee = dollars * (kind === 'stock' ? STOCK_FEE : COIN_FEE);
        const units = (dollars - fee) / asset.price;
        const pf = portfolioOf(state);
        const book = kind === 'stock' ? pf.stocks : pf.coins;
        const h = book.find((x) => x.ticker === ticker);
        if (h) { h.avgCost = (h.units * h.avgCost + dollars) / (h.units + units); h.units += units; }
        else book.push({ ticker, units, avgCost: dollars / units });
        p.career.money -= dollars;
        result = { ok: true, message: `Bought ${units < 1 ? units.toFixed(4) : units < 100 ? units.toFixed(2) : Math.round(units).toLocaleString()} ${ticker} for $${dollars.toLocaleString()}.` };
      });
      return result;
    },

    sellAsset: (kind, ticker, fraction) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not sell.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const m = marketOf(state);
        const pf = portfolioOf(state);
        const book = kind === 'stock' ? pf.stocks : pf.coins;
        const i = book.findIndex((x) => x.ticker === ticker);
        if (i < 0) { result.message = 'You don\'t own any.'; return; }
        const h = book[i];
        const price = priceMapOf(m).get(ticker) ?? 0;
        const f = Math.min(1, Math.max(0.01, fraction));
        const units = f >= 0.999 ? h.units : h.units * f;
        const gross = units * price;
        const proceeds = Math.round(gross * (1 - (kind === 'stock' ? STOCK_FEE : COIN_FEE)));
        const pnl = proceeds - units * h.avgCost;
        p.career.money += proceeds;
        pf.realized += Math.round(pnl);
        h.units -= units;
        if (h.units <= 1e-9 || f >= 0.999) book.splice(i, 1);
        result = { ok: true, message: proceeds <= 0 ? `Wrote off your ${ticker}. It's worth nothing.` : `Sold for $${proceeds.toLocaleString()} — ${pnl >= 0 ? `+$${Math.round(pnl).toLocaleString()} profit` : `−$${Math.round(-pnl).toLocaleString()} loss`}.` };
      });
      return result;
    },

    // ─── MONEY: BUSINESSES YOU RUN ──────────────────────────────────────
    openVenture: (type, name) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not open it.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const def = VENTURE_BY_TYPE[type];
        if (!def) return;
        const open = (state.ventures ?? []).filter((v) => !v.closed);
        if (open.length >= 8) { result.message = 'Eight businesses is plenty. Sell one first.'; return; }
        if (open.some((v) => v.type === type)) { result.message = `You already run a ${def.name.toLowerCase()}. Grow that one.`; return; }
        const cost = Math.round(def.startCost * (1 - dealDiscount(state)));
        if (p.career.money < cost) { result.message = `You need $${cost.toLocaleString()} to open it.`; return; }
        if (!spendEnergy(state, 6, { admin: true })) { result.message = energyShortfallMessage(6, p.energy); return; }
        p.career.money -= cost;
        const clean = name.trim().slice(0, 40) || `${p.artistName} ${def.name}`;
        const v = newVenture(type, clean, dateToSerial(state.gameDate), uuidv4());
        v.invested = cost;
        if (type === 'clothing') brandOf(v, dateToSerial(state.gameDate));
        (state.ventures ??= []).push(v);
        state.socialPosts.unshift({
          id: uuidv4(), platform: 'snapgram', authorId: 'player', authorName: p.artistName,
          content: `${def.emoji} ${clean} is OPEN. Pull up.`, likes: 0, shares: 0, comments: [],
          timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 18, daySerial: dateToSerial(state.gameDate), kind: 'announce',
        } as SocialPost);
        livenPost(state, state.socialPosts[0], { npcs: raw(state.npcs) as NPC[] });
        result = { ok: true, message: `${clean} is open. $${cost.toLocaleString()} in${dealDiscount(state) ? ' (your accountant got 8% off)' : ''}.` };
      });
      return result;
    },

    upgradeVenture: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not upgrade.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === id && !x.closed);
        if (!p || !v) return;
        const def = VENTURE_BY_TYPE[v.type];
        const next = def.levels[v.level];
        if (!next) { result.message = 'It\'s as big as it gets.'; return; }
        const cost = Math.round(next.cost * (1 - dealDiscount(state)));
        if (p.career.money < cost) { result.message = `You need $${cost.toLocaleString()}.`; return; }
        p.career.money -= cost;
        v.level += 1;
        v.invested += cost;
        v.hype = Math.min(100, v.hype + 15);
        v.log = [`Grew into: ${next.label}.`, ...v.log].slice(0, 12);
        result = { ok: true, message: `${v.name}: ${next.label}. $${cost.toLocaleString()} spent.` };
      });
      return result;
    },

    setVenture: (id, patch) => {
      let result: FeatureActionResult = { ok: false, message: 'Not found.' };
      set((state) => {
        const v = (state.ventures ?? []).find((x) => x.id === id && !x.closed);
        if (!v) return;
        if (patch.staff !== undefined) v.staff = patch.staff;
        if (patch.price) v.price = patch.price;
        if (patch.marketing !== undefined) v.marketing = Math.max(0, Math.min(500_000, Math.round(patch.marketing / 100) * 100));
        result = { ok: true, message: 'Updated. You\'ll see it in next month\'s numbers.' };
      });
      return result;
    },

    ventureSpecial: (id, plan) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not do that.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === id && !x.closed);
        if (!p || !v) return;
        const def = VENTURE_BY_TYPE[v.type];
        const serial = dateToSerial(state.gameDate);
        if (v.lastSpecialSerial !== undefined && serial - v.lastSpecialSerial < 30) { result.message = `Not again yet — ${30 - (serial - v.lastSpecialSerial)} days.`; return; }
        const ctx = ventureCtx(state, v);
        if (def.special.id === 'drop') {
          if (!plan || plan.units < 50) { result.message = 'Pick how many pieces and what quality.'; return; }
          const cost = dropCost(plan, v.level);
          if (p.career.money < cost) { result.message = `Producing that costs $${cost.toLocaleString()}.`; return; }
          if (!spendEnergy(state, def.special.energy, { admin: true })) { result.message = energyShortfallMessage(def.special.energy, p.energy); return; }
          p.career.money -= cost;
          const res = resolveDrop(v, plan, ctx, Math.random);
          p.career.money += res.revenue;
          v.reputation = Math.max(0, Math.min(100, v.reputation + res.rep));
          v.hype = Math.max(0, Math.min(100, v.hype + res.hype));
          v.lastSpecialSerial = serial;
          const net = res.revenue - cost;
          v.months = [...v.months, { serial, revenue: res.revenue, costs: cost, profit: net, note: 'Collection drop' }].slice(-24);
          v.log = [res.text, ...v.log].slice(0, 12);
          if (res.hype >= 40) addMomentum(state, 3);
          result = { ok: true, message: `${res.text} ${net >= 0 ? `+$${net.toLocaleString()}` : `−$${Math.abs(net).toLocaleString()}`} on the drop.` };
          return;
        }
        const cost = def.special.cost;
        if (p.career.money < cost) { result.message = `That costs $${cost.toLocaleString()}.`; return; }
        if (!spendEnergy(state, def.special.energy, { admin: true })) { result.message = energyShortfallMessage(def.special.energy, p.energy); return; }
        p.career.money -= cost;
        const res = resolveSpecial(v, ctx, Math.random);
        p.career.money += res.cash;
        v.reputation = Math.max(0, Math.min(100, v.reputation + res.rep));
        v.hype = Math.max(0, Math.min(100, v.hype + res.hype));
        if (res.ownership !== undefined) v.ownership = res.ownership;
        if (res.fame) p.career.localFame = Math.min(100, p.career.localFame + res.fame);
        v.lastSpecialSerial = serial;
        v.log = [res.text, ...v.log].slice(0, 12);
        result = { ok: true, message: res.text };
      });
      return result;
    },

    sellVenture: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not sell.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === id && !x.closed);
        if (!p || !v) return;
        const value = ventureValue(v);
        p.career.money += value;
        v.closed = true;
        v.log = [`Sold for $${value.toLocaleString()}.`, ...v.log].slice(0, 12);
        const pnl = value - v.invested + v.months.reduce((a, m) => a + m.profit, 0);
        result = { ok: true, message: `Sold ${v.name} for $${value.toLocaleString()}. Lifetime ${pnl >= 0 ? 'profit' : 'loss'}: $${Math.abs(pnl).toLocaleString()}.` };
      });
      return result;
    },

    closeVenture: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not close.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === id && !x.closed);
        if (!p || !v) return;
        const scrap = Math.round(VENTURE_BY_TYPE[v.type].startCost * 0.15);
        p.career.money += scrap;
        v.closed = true;
        v.log = [`Closed down. Equipment sold for $${scrap.toLocaleString()}.`, ...v.log].slice(0, 12);
        result = { ok: true, message: `${v.name} is closed. You got $${scrap.toLocaleString()} for the equipment.` };
      });
      return result;
    },

    // ─── CLOTHING BRAND ─────────────────────────────────────────────────
    brandDesign: (ventureId, spec) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not design that.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed && x.type === 'clothing');
        if (!p || !v) return;
        const serial = dateToSerial(state.gameDate);
        const b = brandOf(v, serial);
        if (b.products.filter((x) => !x.retired).length >= 10) { result.message = 'Ten live products is the most you can run. Retire one first.'; return; }
        const sample = Math.round(400 * MATERIALS[spec.material].cost);
        if (p.career.money < sample) { result.message = `Samples cost $${sample.toLocaleString()}.`; return; }
        if (!spendEnergy(state, 6, { admin: true })) { result.message = energyShortfallMessage(6, p.energy); return; }
        let collab: Product['collab'];
        if (spec.collabNpcId) {
          const n = state.npcs.find((x) => x.id === spec.collabNpcId);
          if (!n || isRealId(n.id) || n.role !== 'artist') { result.message = 'They can\'t do a collab.'; return; }
          if (n.relationshipScore < 25) { result.message = `${n.name.split(' ')[0]} isn't close enough to you to put their name on it.`; return; }
          const fee = Math.round(n.fame * 300);
          if (p.career.money < sample + fee) { result.message = `${n.name.split(' ')[0]} wants $${fee.toLocaleString()} up front plus 25% of sales.`; return; }
          p.career.money -= fee;
          n.relationshipScore = Math.min(100, n.relationshipScore + 5);
          collab = { npcId: n.id, name: n.name, fame: n.fame, split: 0.25 };
        }
        p.career.money -= sample;
        const stylist = (state.crew ?? []).find((c) => c.role === 'stylist');
        const trend = spec.trendId ? b.trends.find((t) => t.id === spec.trendId) : undefined;
        const design = rollDesign(spec.material, trend, { creativity: p.stats.creativity, stylistSkill: stylist?.skill ?? 0, trendsetter: !!crewWithSkill(state.crew, 'trendsetter') }, Math.random);
        const fair = fairPrice(spec.kind, spec.material, blendedFame(p));
        const prod: Product = {
          id: uuidv4(), kind: spec.kind, name: (spec.name.trim() || PRODUCT_NAMES[spec.kind][0]).slice(0, 32), material: spec.material, design,
          price: fair, stock: 0, incoming: [], unitCost: unitCostFor(spec.kind, spec.material, 'local', 100), supplier: 'local',
          sold: 0, weeks: [], hype: 15 + (collab ? 25 : 0) + (spec.limited ? 15 : 0), limited: spec.limited, trend: trend?.id, collab, launched: serial, soldOutWeeks: 0,
        };
        b.products.push(prod);
        const verdict = design >= 80 ? 'The samples are incredible.' : design >= 60 ? 'The samples look good.' : design >= 40 ? 'The samples are fine — nothing special.' : 'The samples came out weak.';
        b.log = [`Designed ${prod.name} (design ${design}). ${verdict}`, ...b.log].slice(0, 20);
        result = { ok: true, message: `${prod.name}: design ${design}/100. ${verdict} Now order stock.` };
      });
      return result;
    },

    brandOrder: (ventureId, productId, units, supplier) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not place the order.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed);
        if (!p || !v?.brand) return;
        const prod = v.brand.products.find((x) => x.id === productId && !x.retired);
        if (!prod) return;
        const sup = SUPPLIERS[supplier];
        if (v.level < sup.minLevel) { result.message = `${sup.label} unlocks at level ${sup.minLevel}.`; return; }
        if (prod.limited && prod.runOrdered) { result.message = 'Limited pieces are one run only. That\'s what makes them limited.'; return; }
        units = Math.round(units);
        if (units < sup.moq) { result.message = `${sup.label} needs at least ${sup.moq} pieces.`; return; }
        const unitCost = unitCostFor(prod.kind, prod.material, supplier, units);
        const cost = Math.round(unitCost * units * (1 - dealDiscount(state) * 0.5));
        if (p.career.money < cost) { result.message = `That order costs $${cost.toLocaleString()}.`; return; }
        p.career.money -= cost;
        const serial = dateToSerial(state.gameDate);
        prod.incoming.push({ units, arrive: serial + sup.days, supplier, unitCost });
        prod.supplier = supplier;
        if (prod.limited) prod.runOrdered = true;
        if (supplier === 'premium_mill') prod.design = Math.min(99, prod.design + 3);
        v.invested += cost;
        result = { ok: true, message: `Ordered ${units.toLocaleString()} × ${prod.name} for $${cost.toLocaleString()} ($${unitCost.toFixed(2)} each). Arrives in ${sup.days} days.` };
      });
      return result;
    },

    brandPrice: (ventureId, productId, price) =>
      set((state) => {
        const v = (state.ventures ?? []).find((x) => x.id === ventureId);
        const prod = v?.brand?.products.find((x) => x.id === productId);
        if (prod) prod.price = Math.max(5, Math.min(2000, Math.round(price)));
      }),

    brandChannel: (ventureId, patch) => {
      let result: FeatureActionResult = { ok: false, message: 'Not available.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed);
        if (!p || !v?.brand) return;
        const b = v.brand;
        if (patch.popup !== undefined) {
          if (patch.popup && v.level < 2) { result.message = 'Pop-ups unlock at level 2.'; return; }
          b.channels.popup = patch.popup;
          result = { ok: true, message: patch.popup ? 'Pop-up shop running — about $1,800 a week.' : 'Pop-up closed.' };
        }
        if (patch.stores !== undefined) {
          const max = v.level >= 5 ? 3 : v.level >= 4 ? 1 : 0;
          const n = Math.max(0, Math.min(max, patch.stores));
          if (patch.stores > max) { result.message = max ? `Your level allows ${max} store${max > 1 ? 's' : ''}.` : 'Stores unlock at level 4.'; return; }
          if (n > b.channels.stores) {
            const fit = Math.round(35_000 * (1 - dealDiscount(state)));
            if (p.career.money < fit) { result.message = `Fitting out a store costs $${fit.toLocaleString()}.`; return; }
            p.career.money -= fit;
            v.invested += fit;
          }
          b.channels.stores = n;
          result = { ok: true, message: `${n} store${n === 1 ? '' : 's'} open — about $${(n * 4200).toLocaleString()} a week in rent and staff.` };
        }
        if (patch.wholesale !== undefined) {
          if (patch.wholesale && v.level < 5) { result.message = 'Wholesale unlocks at level 5.'; return; }
          b.channels.wholesale = patch.wholesale;
          result = { ok: true, message: patch.wholesale ? 'Selling through other shops: more volume, half the margin on those pieces.' : 'Wholesale stopped.' };
        }
      });
      return result;
    },

    brandSeed: (ventureId, productId) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not do that.' };
      set((state) => {
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed);
        const prod = v?.brand?.products.find((x) => x.id === productId && !x.retired);
        if (!v?.brand || !prod) return;
        const serial = dateToSerial(state.gameDate);
        if (v.brand.lastSeed !== undefined && serial - v.brand.lastSeed < 14) { result.message = `Influencers need a break — ${14 - (serial - v.brand.lastSeed)} days.`; return; }
        if (prod.stock < 30) { result.message = 'You need 30 pieces in stock to send out.'; return; }
        prod.stock -= 30;
        prod.hype = Math.min(100, prod.hype + 30);
        v.hype = Math.min(100, v.hype + 8);
        v.brand.lastSeed = serial;
        v.brand.log = [`Sent 30 ${prod.name}s to influencers.`, ...v.brand.log].slice(0, 20);
        result = { ok: true, message: `30 ${prod.name}s are on their way to influencers. Watch the hype.` };
      });
      return result;
    },

    brandSale: (ventureId) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not start a sale.' };
      set((state) => {
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed);
        if (!v?.brand) return;
        const serial = dateToSerial(state.gameDate);
        if (v.brand.saleUntil !== undefined && serial - v.brand.saleUntil < 30) { result.message = 'Too soon for another sale — it cheapens the brand.'; return; }
        const recent = v.brand.saleUntil !== undefined && serial - v.brand.saleUntil < 60;
        v.brand.saleUntil = serial + 7;
        if (recent) v.reputation = Math.max(0, v.reputation - 2);
        result = { ok: true, message: `30% off everything for a week.${recent ? ' Two sales close together — people notice.' : ''}` };
      });
      return result;
    },

    brandRetire: (ventureId, productId) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not retire it.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed);
        const prod = v?.brand?.products.find((x) => x.id === productId && !x.retired);
        if (!p || !v?.brand || !prod) return;
        const cash = Math.round(prod.stock * prod.price * 0.4);
        p.career.money += cash;
        prod.retired = true;
        prod.stock = 0;
        prod.incoming = [];
        result = { ok: true, message: cash ? `Cleared the remaining ${prod.name}s to a discounter for $${cash.toLocaleString()}.` : `${prod.name} retired.` };
      });
      return result;
    },

    brandWarehouse: (ventureId) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not expand.' };
      set((state) => {
        const p = state.player;
        const v = (state.ventures ?? []).find((x) => x.id === ventureId && !x.closed);
        if (!p || !v?.brand) return;
        const cost = Math.round(6000 * (v.brand.warehouse / 600) * (1 - dealDiscount(state)));
        if (p.career.money < cost) { result.message = `Expanding costs $${cost.toLocaleString()}.`; return; }
        p.career.money -= cost;
        v.invested += cost;
        v.brand.warehouse += 600;
        result = { ok: true, message: `Warehouse now holds ${v.brand.warehouse.toLocaleString()} pieces.` };
      });
      return result;
    },

    // ─── MONEY: PROPERTY DEVELOPMENT ────────────────────────────────────
    buyPlot: (zone) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not buy the land.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const z = zoneOf(zone);
        const m = marketOf(state);
        const live = (state.devProjects ?? []).filter((d) => d.stage !== 'sold');
        if (live.length >= 10) { result.message = 'Ten properties at once is the limit.'; return; }
        const price = Math.round(z.land * (m.propertyIndex / 100) * (1 - dealDiscount(state)));
        if (p.career.money < price) { result.message = `That plot costs $${price.toLocaleString()}.`; return; }
        p.career.money -= price;
        const serial = dateToSerial(state.gameDate);
        (state.devProjects ??= []).push({
          id: uuidv4(), zone, stage: 'land', landCost: price, buildCost: 0, spent: price, boughtSerial: serial, indexAtBuy: m.propertyIndex,
          quality: Math.round(45 + (p.stats.businessKnowledge ?? 40) / 5), renting: false, owed: 0, totalRent: 0,
          log: [`Bought a plot in the ${z.name.toLowerCase()} for $${price.toLocaleString()}.`],
        });
        result = { ok: true, message: `${z.emoji} Plot bought: $${price.toLocaleString()}. Build on it, or sit on it and wait.` };
      });
      return result;
    },

    startBuild: (projectId, build) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not start.' };
      set((state) => {
        const p = state.player;
        const d = (state.devProjects ?? []).find((x) => x.id === projectId);
        if (!p || !d || d.stage !== 'land') return;
        const b = buildOf(build);
        const cost = Math.round(buildCostFor(d.zone, build) * (1 - dealDiscount(state)));
        if (p.career.money < cost) { result.message = `Building that costs $${cost.toLocaleString()}.`; return; }
        if (!spendEnergy(state, 5, { admin: true })) { result.message = energyShortfallMessage(5, p.energy); return; }
        p.career.money -= cost;
        const serial = dateToSerial(state.gameDate);
        d.build = build;
        d.stage = 'building';
        d.buildCost = cost;
        d.spent += cost;
        d.startSerial = serial;
        d.doneSerial = serial + b.days;
        d.log = [`Broke ground on ${b.name.toLowerCase()}. About ${Math.round(b.days / 30)} months.`, ...d.log];
        result = { ok: true, message: `${b.emoji} Construction started — about ${Math.round(b.days / 30)} months if nothing goes wrong.` };
      });
      return result;
    },

    payOverrun: (projectId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing owed.' };
      set((state) => {
        const p = state.player;
        const d = (state.devProjects ?? []).find((x) => x.id === projectId);
        if (!p || !d || d.owed <= 0) return;
        if (p.career.money < d.owed) { result.message = `You need $${d.owed.toLocaleString()} to get work moving again.`; return; }
        p.career.money -= d.owed;
        d.spent += d.owed;
        d.log = [`Paid $${d.owed.toLocaleString()}. Work is moving again.`, ...d.log];
        result = { ok: true, message: `Paid $${d.owed.toLocaleString()}. The crew is back on site.` };
        d.owed = 0;
      });
      return result;
    },

    setRenting: (projectId, on) => {
      let result: FeatureActionResult = { ok: false, message: 'Not found.' };
      set((state) => {
        const d = (state.devProjects ?? []).find((x) => x.id === projectId);
        if (!d || d.stage !== 'done') return;
        d.renting = on;
        result = { ok: true, message: on ? 'Tenants moving in. Rent starts next month.' : 'Kept empty — ready to sell.' };
      });
      return result;
    },

    sellProject: (projectId) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not sell.' };
      set((state) => {
        const p = state.player;
        const d = (state.devProjects ?? []).find((x) => x.id === projectId);
        if (!p || !d || d.stage === 'sold') return;
        const m = marketOf(state);
        const value = Math.round(projectValue(d, m.propertyIndex, dateToSerial(state.gameDate)) * 0.97 - d.owed);
        p.career.money += Math.max(0, value);
        const pnl = value + d.totalRent - d.spent;
        d.stage = 'sold';
        d.soldFor = value;
        d.owed = 0;
        d.renting = false;
        d.log = [`Sold for $${value.toLocaleString()}.`, ...d.log];
        result = { ok: true, message: `Sold for $${value.toLocaleString()} after agent fees. ${pnl >= 0 ? `Profit: $${pnl.toLocaleString()}` : `Loss: $${Math.abs(pnl).toLocaleString()}`} including rent.` };
      });
      return result;
    },

    // ─── MONEY: THE CASINO ──────────────────────────────────────────────
    enterCasino: () => {
      let result: FeatureActionResult = { ok: false, message: 'Could not get in.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const cas = casinoOf(state);
        const serial = dateToSerial(state.gameDate);
        if (cas.visitSerial === serial) { result = { ok: true, message: 'Back at the tables.' }; return; }
        if (!spendEnergy(state, 3, { admin: true })) { result.message = energyShortfallMessage(3, p.energy); return; }
        cas.visitSerial = serial;
        if (cas.day.serial !== serial) cas.day = { serial, net: 0 };
        result = { ok: true, message: `Welcome in. ${vipTier(cas.vipPoints)} table limit: $${casinoLimitOf(state).toLocaleString()}.` };
      });
      return result;
    },

    casinoBlackjack: (action, bet) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not play.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const cas = casinoOf(state);
        const finish = (h: BlackjackHand) => {
          const line = settleBet(state, h.bet, h.payout ?? 0, h.result === 'blackjack' ? 'Blackjack!' : `Blackjack (${h.result})`);
          h.deck = [];
          result = { ok: true, message: line };
        };
        if (action === 'deal') {
          if (cas.blackjack && !cas.blackjack.done) { result.message = 'Finish this hand first.'; return; }
          const stake = Math.round(bet ?? 0);
          const err = canStake(state, stake);
          if (err) { result.message = err; return; }
          p.career.money -= stake;
          const h = dealBlackjack(stake, Math.random);
          cas.blackjack = h;
          if (h.done) finish(cas.blackjack);
          else result = { ok: true, message: 'Dealt.' };
          return;
        }
        const h = cas.blackjack;
        if (!h || h.done) { result.message = 'Deal a hand first.'; return; }
        if (action === 'hit') hit(h);
        else if (action === 'stand') stand(h);
        else if (action === 'double') {
          if (h.player.length !== 2) { result.message = 'You can only double on your first two cards.'; return; }
          if (p.career.money < h.bet) { result.message = 'Not enough cash to double.'; return; }
          p.career.money -= h.bet;
          doubleDown(h);
        }
        if (h.done) finish(h);
        else result = { ok: true, message: action === 'hit' ? 'Another card.' : 'OK.' };
      });
      return result;
    },

    casinoRoulette: (bet, stake) => {
      let result: FeatureActionResult & { n?: number } = { ok: false, message: 'Could not spin.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        stake = Math.round(stake);
        const err = canStake(state, stake);
        if (err) { result.message = err; return; }
        p.career.money -= stake;
        const spin = spinRoulette(bet, stake, Math.random);
        const line = settleBet(state, stake, spin.payout, `Roulette ${spin.n} ${spin.n === 0 ? 'green' : isRed(spin.n) ? 'red' : 'black'}`);
        result = { ok: true, message: line, n: spin.n };
      });
      return result;
    },

    casinoSlots: (stake) => {
      let result: FeatureActionResult & { reels?: string[] } = { ok: false, message: 'Could not spin.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        stake = Math.round(stake);
        const err = canStake(state, stake);
        if (err) { result.message = err; return; }
        p.career.money -= stake;
        const spin = spinSlots(stake, Math.random);
        const line = settleBet(state, stake, spin.payout, `Slots ${spin.reels.join('')}`);
        result = { ok: true, message: `${spin.text} ${line.split(': ')[1] ?? ''}`.trim(), reels: spin.reels };
      });
      return result;
    },

    casinoDice: (bet, stake) => {
      let result: FeatureActionResult & { dice?: [number, number] } = { ok: false, message: 'Could not roll.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        stake = Math.round(stake);
        const err = canStake(state, stake);
        if (err) { result.message = err; return; }
        p.career.money -= stake;
        const roll = rollDice(bet, stake, Math.random);
        const line = settleBet(state, stake, roll.payout, `Dice ${roll.dice[0]}+${roll.dice[1]}=${roll.total}`);
        result = { ok: true, message: line, dice: roll.dice };
      });
      return result;
    },

    placeSportsBet: (fixtureId, pick, stake) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not place the bet.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const cas = casinoOf(state);
        const f = cas.fixtures.find((x) => x.id === fixtureId);
        if (!f || f.result) { result.message = 'That match is closed.'; return; }
        stake = Math.round(stake);
        if (!Number.isFinite(stake) || stake < 10) { result.message = 'The minimum bet is $10.'; return; }
        if (stake > casinoLimitOf(state)) { result.message = `Your limit is $${casinoLimitOf(state).toLocaleString()}.`; return; }
        if (stake > p.career.money) { result.message = 'You don\'t have that much cash.'; return; }
        if (cas.bets.filter((b) => !b.settled).length >= 8) { result.message = 'Eight open bets at once is the limit.'; return; }
        const odds = f.odds[pick];
        p.career.money -= stake;
        cas.net -= stake;
        cas.vipPoints += stake;
        const label = `${pick === 'home' ? f.home : pick === 'away' ? f.away : `${f.home} v ${f.away} draw`} @ ${odds.toFixed(2)} · $${stake.toLocaleString()}`;
        cas.bets.push({ id: uuidv4(), fixtureId, pick, stake, odds, label });
        result = { ok: true, message: `Bet placed. Pays $${Math.round(stake * odds).toLocaleString()} if it lands — tomorrow.` };
      });
      return result;
    },

    // ─── TEAM: WHAT EVERYONE WORKS ON ───────────────────────────────────
    placeFootballBet: (picks, stake) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not place the bet.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        ensureFixtures(state);
        const fb = footballOf(state);
        const cas = casinoOf(state);
        const now = nowMinuteOf(state);
        stake = Math.round(stake);
        if (!picks.length) { result.message = 'Pick something first.'; return; }
        if (picks.length > 10) { result.message = 'Ten selections at most.'; return; }
        if (new Set(picks.map((x) => x.matchId)).size !== picks.length) { result.message = 'One pick per match in an accumulator.'; return; }
        if (!Number.isFinite(stake) || stake < 10) { result.message = 'The minimum bet is $10.'; return; }
        if (stake > casinoLimitOf(state)) { result.message = `Your limit is $${casinoLimitOf(state).toLocaleString()}.`; return; }
        if (stake > p.career.money) { result.message = 'You don\'t have that much cash.'; return; }
        if (fb.bets.filter((b) => b.status === 'open').length >= 15) { result.message = 'Fifteen open bets is the limit.'; return; }
        const selections = [];
        for (const x of picks) {
          const m = fb.matches.find((mm) => mm.id === x.matchId);
          if (!m) { result.message = 'That match is gone.'; return; }
          if (m.kickoff <= now) { result.message = `${m.home} v ${m.away} has already kicked off.`; return; }
          const odds = m.odds[x.pick];
          selections.push({ matchId: m.id, market: x.market, pick: x.pick, odds, label: `${pickLabel(x.pick, m)}${x.market === '1x2' ? '' : ''} (${m.home} v ${m.away})` });
        }
        const odds = Math.round(selections.reduce((a, x) => a * x.odds, 1) * 100) / 100;
        p.career.money -= stake;
        cas.net -= stake;
        cas.vipPoints += stake;
        fb.bets.push({ id: uuidv4(), selections, stake, odds, placedMinute: now, status: 'open', payout: 0 });
        result = { ok: true, message: `Bet placed: $${stake.toLocaleString()} @ ${odds.toFixed(2)} — pays $${Math.round(stake * odds).toLocaleString()} if it lands.` };
      });
      return result;
    },

    assignCrew: (crewId, assignmentId) => {
      let result: FeatureActionResult = { ok: false, message: 'Not on the payroll.' };
      set((state) => {
        const c = (state.crew ?? []).find((x) => x.id === crewId);
        if (!c) return;
        const a = assignmentsFor(c.role).find((x) => x.id === assignmentId);
        if (!a) { result.message = 'They don\'t do that.'; return; }
        c.assignment = a.id;
        result = { ok: true, message: `${c.npcName.split(' ')[0]} is on ${a.label.toLowerCase()} now.` };
      });
      return result;
    },

    // ─── THE AI WRITES BACK ──────────────────────────────────────────────
    applyAIChat: (npcId, payload) =>
      set((state) => {
        const thread = state.dmThreads[npcId];
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!thread || !npc || isRealId(npc.id)) return;
        // Only one answer per message: a late or doubled reply is dropped.
        if (!thread.pendingAI) return;
        thread.pendingAI = undefined;
        const serial = dateToSerial(state.gameDate);
        let text = payload.reply.trim().slice(0, 600);
        // They don't say the same thing twice.
        const theirs = thread.messages.filter((m) => !m.fromPlayer && !m.system).slice(-6);
        if (text && theirs.some((m) => nearDuplicate(m.content, text))) text = '';
        if (text) pushDM(state, npcId, { fromPlayer: false, content: text, read: false, ai: true });
        const rel = Math.max(-6, Math.min(6, Math.round(payload.rel ?? 0)));
        if (rel) npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + rel));
        if (text) npc.memoryLog = [...npc.memoryLog.slice(-9), `[DM] They: "${text.slice(0, 50)}"`];
        const now = nowMinuteOf(state);
        let action = payload.action;
        let time = payload.time;
        // "See you at 20:00" with nothing booked: book it, so 20:00 actually happens.
        const implied = text && (!action || action === 'none') ? impliedPlan(text) : null;
        if (implied) {
          const lastMine = [...thread.messages].reverse().find((m) => m.fromPlayer && !m.system);
          const agreed = implied.confirmed || (!!lastMine && soundsLikeYes(lastMine.content));
          action = `${agreed ? 'accept' : 'invite'}_${implied.kind}`;
          time = time || implied.time;
        }
        const at = parseClock(time, now);
        const kind = action === 'invite_studio' || action === 'accept_studio' ? 'studio'
          : action === 'invite_party' || action === 'accept_party' ? 'party'
          : action === 'invite_linkup' || action === 'accept_linkup' ? 'linkup' : null;
        const open = (state.appointments ?? []).find((a) => a.npcId === npcId && (a.status === 'confirmed' || a.status === 'proposed'));
        if (kind && open && open.status === 'proposed' && action?.startsWith('accept')) {
          // They're confirming the plan that's already on the table.
          if (at && at - now >= 45) open.atMinute = at;
          open.status = 'confirmed';
          pushDM(state, npcId, { fromPlayer: false, system: true, content: `${KIND_LABEL[open.kind].emoji} ${KIND_LABEL[open.kind].label} · ${whenLabel(open.atMinute, now)} · ${open.place}`, appointmentId: open.id });
        } else if (kind && !open) {
          const when = at ?? defaultSlot(now, kind);
          createAppointment(state, npc, kind, when, action?.startsWith('accept') ? 'player' : 'npc', action?.startsWith('accept') ? 'confirmed' : 'proposed');
        }
        if (payload.action === 'offer_collab') applyMomentEffects(state, [{ k: 'inboundAsk', npcId, free: true }], serial);
        // Your own people can be asked to do their job in a DM, too.
        const crewRole = (state.crew ?? []).find((c) => c.npcId === npcId)?.role ?? (managerOf(state)?.id === npcId ? 'manager' : null);
        const act = payload.action ?? '';
        if (crewRole && ['make_beat', 'mix_song', 'push_shows', 'push_features', 'push_deals'].includes(act)) {
          const fits = (act === 'make_beat' && crewRole === 'producer') || (act === 'mix_song' && (crewRole === 'engineer' || crewRole === 'producer')) || (act.startsWith('push') && crewRole === 'manager');
          if (fits) {
            const songT = payload.song ? state.songs.find((x) => !isSongReleased(x) && x.title.toLowerCase() === String(payload.song).toLowerCase()) : undefined;
            const target = act === 'mix_song' ? (songT ?? state.songs.find((x) => isVaultMaster(x) && x.masterStatus === 'recorded')) : songT;
            if (act !== 'mix_song' || target) {
              const a: TeamAction = { kind: act as TeamAction['kind'], from: npcId, songId: target?.id };
              queueMicrotask(() => runTeamActions([a]));
            }
          }
        }
        if (payload.action === 'go_quiet') {
          thread.mutedUntil = serial + 5;
          pushDM(state, npcId, { fromPlayer: false, system: true, content: `${npc.name.split(' ')[0]} has stopped replying.` });
        }
      }),

    applyAIMomentReply: (npcId, momentId, text) =>
      set((state) => {
        const thread = state.dmThreads[npcId];
        if (!thread) return;
        thread.pendingAI = undefined;
        const clean = text.trim().slice(0, 400);
        if (!clean) return;
        const msg: DMMessage = { id: uuidv4(), npcId, fromPlayer: false, content: clean, timestamp: new Date().toISOString(), read: false, ai: true };
        // Their answer goes above the grey "what happened" line for that decision.
        const at = thread.messages.findIndex((m) => m.system && m.momentId === momentId);
        if (at >= 0) thread.messages.splice(at, 0, msg); else thread.messages.push(msg);
        thread.unread += 1;
      }),

    /** The AI didn't answer in time (or is off): use the built-in reply. */
    fallbackAI: (npcId) =>
      set((state) => {
        const thread = state.dmThreads[npcId];
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!thread?.pendingAI || !npc) return;
        const pending = thread.pendingAI;
        thread.pendingAI = undefined;
        const serial = dateToSerial(state.gameDate);
        if (pending.momentId) {
          const m = (state.moments ?? []).find((x) => x.id === pending.momentId);
          if (!m) return;
          const reply = npcReply(m.kind, pending.optionId ?? '', 'neutral', personaOf(npc), `${m.id}|fb`);
          if (!reply) return;
          const msg: DMMessage = { id: uuidv4(), npcId, fromPlayer: false, content: reply, timestamp: new Date().toISOString(), read: false };
          const at = thread.messages.findIndex((x) => x.system && x.momentId === m.id);
          if (at >= 0) thread.messages.splice(at, 0, msg); else thread.messages.push(msg);
          thread.unread += 1;
          return;
        }
        const last = [...thread.messages].reverse().find((x) => x.fromPlayer && !x.system);
        if (!last) return;
        if (!last.attachedSongId && ((state.crew ?? []).some((c) => c.npcId === npc.id) || managerOf(state)?.id === npc.id)) {
          const snap = teamSnapshot(state as GameState, serial);
          const lines = teamReply(state as GameState, snap, last.content, npc.id);
          if (lines.length) {
            pushDM(state, npcId, { fromPlayer: false, content: lines[0].text, read: false });
            const acts = teamActions(state as GameState, snap, last.content, npc.id);
            if (acts.length) queueMicrotask(() => runTeamActions(acts));
            return;
          }
        }
        const today = thread.sentToday?.serial === serial ? thread.sentToday.count - 1 : 0;
        const reply = chatReply(npc as NPC, last.content, { playerFame: state.player ? blendedFame(state.player) : 0, sentToday: today, beef: activeBeefIds(state).has(npcId), seed: `${serial}|fb|${today}` }, Math.random());
        if (reply.text) pushDM(state, npcId, { fromPlayer: false, content: reply.text, read: false });
        else if (reply.note) pushDM(state, npcId, { fromPlayer: false, system: true, content: reply.note });
        npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + reply.relationship));
      }),

    respondToPlan: (appointmentId, accept, atMinute) => {
      let result: FeatureActionResult = { ok: false, message: 'That invite has gone.' };
      set((state) => {
        const a = (state.appointments ?? []).find((x) => x.id === appointmentId && x.status === 'proposed');
        const npc = a ? state.npcs.find((n) => n.id === a.npcId) : undefined;
        if (!a || !npc) return;
        const now = nowMinuteOf(state);
        if (accept) {
          if (atMinute && atMinute - now >= 45) a.atMinute = atMinute;
          a.status = 'confirmed';
          pushDM(state, a.npcId, { fromPlayer: true, content: atMinute && atMinute !== a.atMinute ? `Can we do ${whenLabel(a.atMinute, now).toLowerCase()} instead?` : pickLine(['I\'m there 🔥', 'Bet, see you then', 'Locked in'], a.id) });
          pushDM(state, a.npcId, { fromPlayer: false, system: true, content: `${KIND_LABEL[a.kind].emoji} ${KIND_LABEL[a.kind].label} · ${whenLabel(a.atMinute, now)} · ${a.place}`, appointmentId: a.id });
          npc.relationshipScore = Math.min(100, npc.relationshipScore + 2);
          result = { ok: true, message: `In your diary: ${whenLabel(a.atMinute, now)}.` };
        } else {
          a.status = 'cancelled';
          a.outcome = 'You turned it down.';
          pushDM(state, a.npcId, { fromPlayer: true, content: pickLine(['Can\'t make that one, next time 🙏🏾', 'Not this time, I\'m tied up', 'I\'ll pass on that, sorry'], a.id) });
          const p = personaOf(npc);
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - (p.ego > 0.7 ? 3 : 1));
          scheduleDM(state, a.npcId, p.warmth > 0.6 ? 'No wahala, another time' : 'Ok', now + 6);
          remember(state, 'plans', `You turned down ${a.npcName}'s ${KIND_LABEL[a.kind].label.toLowerCase()} invite.`, { npcIds: [a.npcId], weight: 1 });
          result = { ok: true, message: 'Declined.' };
        }
      });
      return result;
    },

    applyAIDirector: (events) => {
      let applied = 0;
      set((state) => {
        const p = state.player;
        if (!p) return;
        const now = nowMinuteOf(state);
        const serial = dateToSerial(state.gameDate);
        for (const e of events.slice(0, 5)) {
          const npc = state.npcs.find((n) => n.id === e.npcId);
          if (!npc || isRealId(npc.id) || isBlocked(state, npc.id)) continue;
          const text = (e.text ?? '').trim().slice(0, 400);
          const later = now + 10 + Math.floor(Math.random() * 240);
          if (e.type === 'dm' && text) {
            const said = (state.dmThreads[npc.id]?.messages ?? []).filter((m) => !m.fromPlayer && !m.system).slice(-6);
            if (said.some((m) => nearDuplicate(m.content, text)) || (state.pendingDMs ?? []).some((d) => d.npcId === npc.id)) continue;
            const plan = impliedPlan(text);
            if (plan && !(state.appointments ?? []).some((a) => a.npcId === npc.id && (a.status === 'confirmed' || a.status === 'proposed'))) {
              // "Pull up at 9" is an invite: it comes with a card you can answer.
              pushDM(state, npc.id, { fromPlayer: false, content: text, read: false, ai: true });
              createAppointment(state, npc, plan.kind, parseClock(plan.time, now) ?? defaultSlot(now, plan.kind), 'npc', 'proposed');
            } else scheduleDM(state, npc.id, text, later);
            applied++;
          }
          else if (e.type === 'invite') {
            const kind: Appointment['kind'] = e.kind === 'party' ? 'party' : e.kind === 'linkup' ? 'linkup' : 'studio';
            if ((state.appointments ?? []).some((a) => a.npcId === npc.id && (a.status === 'confirmed' || a.status === 'proposed'))) continue;
            if (text) pushDM(state, npc.id, { fromPlayer: false, content: text, read: false, ai: true });
            createAppointment(state, npc, kind, parseClock(e.time, now) ?? defaultSlot(now, kind), 'npc', 'proposed');
            applied++;
          } else if (e.type === 'post' && text) {
            const app = e.app === 'snapgram' ? 'snapgram' : 'chirp';
            state.socialPosts.unshift({
              id: uuidv4(), platform: app, authorId: npc.id, authorName: npc.name, content: text,
              likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false,
              trendingScore: /@|you|${p.artistName}/i.test(text) ? 45 : 20, daySerial: serial, kind: app === 'snapgram' ? 'photo' : 'thought',
            } as SocialPost);
            livenPost(state, state.socialPosts[0], { at: later });
            applied++;
          } else if (e.type === 'gossip' && text && (npc.role === 'blogger' || npc.role === 'media')) {
            state.headlines.unshift({ id: uuidv4(), text: text.slice(0, 120), fullStory: `${npc.name} reports: ${text}`, date: formatGameDate(state.gameDate), relatedEntities: [p.id], priority: 4, category: 'general' });
            applied++;
          }
        }
      });
      return applied;
    },

    rewriteInterviewQuestion: (idx, text) =>
      set((state) => {
        const live = state.activeInterview;
        if (!live || live.idx !== idx) return;
        const q = live.questions[idx];
        if (q && text.trim()) q.host = text.trim().slice(0, 500);
      }),

    addAIReplies: (postId, commentId, replies) =>
      set((state) => {
        const post = state.socialPosts.find((x) => x.id === postId);
        const p = state.player;
        if (!post || !p) return;
        const mine = [...post.comments, ...post.comments.flatMap((c) => c.replies ?? [])].find((c) => c.id === commentId);
        if (!mine) return;
        // The fans' pile-on is where the AI's replies go. The fan you answered,
        // and any artist who answered, keep their place.
        const holder = post.comments.find((c) => c.replies?.some((r) => r.id === commentId)) ?? mine;
        const keep = (holder.replies ?? []).filter((r) => r.authorId === 'player' || !r.authorId.startsWith('fan:') || r.authorId === post.authorId || r.authorId === holder.authorId);
        const fame = blendedFame(p);
        const tones = ['stan', 'love', 'neutral', 'hater', 'troll'] as const;
        const fresh: SocialComment[] = replies.slice(0, 12).map((r, i) => {
          const name = r.name.replace(/^@/, '').replace(/\s+/g, '_').slice(0, 24);
          return {
            id: uuidv4(), authorId: `fan:${name.toLowerCase()}`, authorName: `@${name}`, content: r.text.slice(0, 280),
            likes: Math.round(30 * (1 + fame / 15) * (0.3 + Math.random() * 2) / (1 + i * 0.25)), timestamp: new Date().toISOString(),
            tone: (tones as readonly string[]).includes(r.tone ?? '') ? r.tone as SocialComment['tone'] : 'love',
          };
        });
        holder.replies = [...keep, ...fresh];
      }),

    addAIFeed: (posts) => {
      let made = 0;
      set((state) => {
        const p = state.player;
        if (!p) return;
        const serial = dateToSerial(state.gameDate);
        const minute = gameMinute(state);
        for (const x of posts.slice(0, 10)) {
          const npc = state.npcs.find((n) => n.id === x.authorId);
          if (npc && (isRealId(npc.id) || isBlocked(state, npc.id))) continue;
          const at = minute + 5 + Math.floor(Math.random() * 900);
          const app = (x.app === 'snapgram' || x.app === 'clip' ? x.app : 'chirp') as SocialApp;
          const aboutYou = new RegExp(p.artistName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(x.text);
          const post: SocialPost = {
            id: uuidv4(), platform: app, authorId: x.authorId, authorName: x.authorName, content: x.text.slice(0, 400),
            likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false,
            trendingScore: aboutYou ? 45 : 25, daySerial: serial, kind: app === 'clip' ? 'bts' : app === 'snapgram' ? 'photo' : 'thought',
            tags: aboutYou ? [{ id: 'player', name: p.artistName }] : undefined,
          } as SocialPost;
          post.comments = x.comments.slice(0, 4).map((c, i) => ({
            id: uuidv4(), authorId: c.authorId, authorName: c.authorId.startsWith('fan:') ? `@${c.authorName.replace(/^@/, '')}` : c.authorName,
            content: c.text.slice(0, 280), likes: Math.round(10 + Math.random() * 80 / (i + 1)), timestamp: new Date().toISOString(),
            tone: c.authorId.startsWith('fan:') ? 'love' : 'artist', minute: at + 4 + i * 11,
          } as SocialComment));
          livenPost(state, post, { at, audience: npc ? undefined : Math.round(600 + Math.random() * 3000) });
          state.socialPosts.unshift(post);
          if (aboutYou) pushActivity(state, { kind: 'mention', text: `${x.authorName} posted about you`, actorId: x.authorId, actorName: x.authorName, postId: post.id, minute: at });
          made++;
        }
        if (state.socialPosts.length > 320) trimFeed(state);
      });
      return made;
    },

    addAIComments: (postId, comments) =>
      set((state) => {
        const post = state.socialPosts.find((x) => x.id === postId);
        if (!post) return;
        const fresh: SocialComment[] = comments.slice(0, 10).map((c, i) => ({
          id: uuidv4(), authorId: c.npcId ?? `fan:${c.name.replace(/\s+/g, '').toLowerCase()}`, authorName: c.name.slice(0, 30),
          content: c.text.slice(0, 280), likes: Math.max(0, Math.round((post.likes || 50) * (0.02 + Math.random() * 0.08) / (i + 1))),
          timestamp: new Date().toISOString(), tone: c.tone ?? 'neutral',
        }));
        post.comments = [...fresh, ...post.comments].slice(0, 40);
      }),

    // ─── YOUR OWN LABEL ─────────────────────────────────────────────────
    foundLabel: (opts) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not found the label.' };
      set((state) => {
        if (!state.player) return;
        if (state.label) { result.message = `You already run ${state.label.name}.`; return; }
        const name = opts.name.trim().replace(/\s+/g, ' ').slice(0, 32);
        if (name.length < 2) { result.message = 'Give the label a name.'; return; }
        const fame = blendedFame(state.player);
        const existing = state.businesses.find((b) => b.type === 'record_label');
        if (!existing && fame < FOUNDING_MIN_FAME) {
          result.message = `Nobody takes a label call from an unknown. Get to ${FOUNDING_MIN_FAME} fame first.`;
          return;
        }
        let cash = 0;
        if (existing) {
          // The old "record label" business becomes the real thing. Its resale
          // value is the label's opening balance, so nothing is lost.
          cash = Math.round((existing.monthlyRevenue / 0.026) * 0.7);
          state.businesses = state.businesses.filter((b) => b.id !== existing.id);
        } else {
          if (state.player.career.money < FOUNDING_COST) {
            result.message = `Registering the company, a lawyer and a small office costs ${money(FOUNDING_COST)}.`;
            return;
          }
          state.player.career.money -= FOUNDING_COST;
          cash = Math.round(FOUNDING_COST * 0.6);
        }
        const serial = dateToSerial(state.gameDate);
        const label: PlayerLabel = {
          id: uuidv4(),
          name,
          color: opts.color || LABEL_COLORS[0],
          country: opts.country || state.player.country,
          genreFocus: opts.genreFocus,
          foundedSerial: serial,
          reputation: startingReputation(fame, !!existing),
          cash,
          roster: [],
          alumni: [],
          pitches: [],
          prospects: [],
          prospectsSerial: serial,
          staff: [],
          history: [],
          events: [],
          submissions: [],
          policy: { ...DEFAULT_POLICY },
          studio: emptyStudio(),
          monthRevenue: 0,
          monthCosts: 0,
          monthKey: monthKeyOf(state.gameDate),
          debtMonths: 0,
          totalInvested: existing ? 0 : FOUNDING_COST,
          totalWithdrawn: 0,
        };
        label.prospects = pickProspects(raw(state.npcs) as NPC[], label, fame, 0, serial);
        state.label = label;
        labelEvent(label, serial, `${name} is open for business.`, 'good');
        state.socialPosts.unshift({
          id: uuidv4(), platform: 'chirp', authorId: 'player', authorName: state.player.artistName,
          content: `Officially launched my own label: ${name}. 🏷️ We're signing. Send the music.`,
          likes: Math.round(60 + fame * 40), shares: Math.round(8 + fame * 6), comments: [],
          timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 20 + fame / 3, daySerial: serial,
        });
        state.lastEventLog.unshift(`Founded ${name}`);
        state.lastEventLog = state.lastEventLog.slice(0, 10);
        result = {
          ok: true,
          message: existing
            ? `${name} is live. Your record-label business became the company, with ${money(cash)} in the bank.`
            : `${name} is live with ${money(cash)} in the bank. Time to find some artists.`,
        };
      });
      return result;
    },

    labelDeposit: (amount) => {
      let result: FeatureActionResult = { ok: false, message: 'No label.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        const amt = Math.floor(amount);
        if (amt <= 0) { result.message = 'Enter an amount.'; return; }
        if (state.player.career.money < amt) { result.message = `You only have ${money(state.player.career.money)}.`; return; }
        state.player.career.money -= amt;
        label.cash += amt;
        label.totalInvested += amt;
        labelEvent(label, dateToSerial(state.gameDate), `You put ${money(amt)} into the label.`, 'neutral');
        result = { ok: true, message: `${money(amt)} moved into ${label.name}.` };
      });
      return result;
    },

    labelWithdraw: (amount) => {
      let result: FeatureActionResult = { ok: false, message: 'No label.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        const amt = Math.floor(amount);
        if (amt <= 0) { result.message = 'Enter an amount.'; return; }
        if (label.cash < amt) { result.message = `The label only has ${money(label.cash)}.`; return; }
        label.cash -= amt;
        label.totalWithdrawn += amt;
        state.player.career.money += amt;
        state.player.career.totalEarnings += amt;
        labelEvent(label, dateToSerial(state.gameDate), `You took a ${money(amt)} dividend.`, 'neutral');
        result = { ok: true, message: `${money(amt)} paid out to you.` };
      });
      return result;
    },

    refreshLabelProspects: () => {
      let result: FeatureActionResult = { ok: false, message: 'No label.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        const serial = dateToSerial(state.gameDate);
        if (serial - label.prospectsSerial < PROSPECT_REFRESH_DAYS) {
          result.message = `The scouting report updates every ${PROSPECT_REFRESH_DAYS} days. Next one in ${PROSPECT_REFRESH_DAYS - (serial - label.prospectsSerial)}.`;
          return;
        }
        label.prospects = pickProspects(raw(state.npcs) as NPC[], label, blendedFame(state.player), staffSkill(label.staff, 'ar'), serial);
        label.prospectsSerial = serial;
        result = { ok: true, message: 'New scouting report in.' };
      });
      return result;
    },

    setLabelPolicy: (patch) =>
      set((state) => {
        if (!state.label) return;
        normalizeLabel(state.label, dateToSerial(state.gameDate));
        state.label.policy = { ...state.label.policy, ...patch };
      }),

    openLabelPitch: (npcId, dealType, allIn) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not reach them.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        const live = labelSigneeIds(label);
        if (live.size >= rosterLimit(label.reputation)) {
          result.message = `${label.name} can carry ${rosterLimit(label.reputation)} artists at this reputation. Grow the name or let someone go.`;
          return;
        }
        if (label.pitches.some((p) => p.npcId === npcId && p.status === 'open')) { result.message = 'You are already talking to them.'; return; }
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!npc || !isSignable(npc as NPC, live)) { result.message = 'They are not available to sign.'; return; }
        const fame = blendedFame(state.player);
        const cap = fameCap(label.reputation, fame);
        if (npc.fame > cap) {
          result.message = `${npc.name}'s camp will not take the meeting. ${label.name} is not big enough for them yet.`;
          return;
        }
        const serial = dateToSerial(state.gameDate);
        const competing = npc.fame >= 25 && unit(`comp|${npcId}|${Math.floor(serial / 14)}`) < 0.3;
        const wants = wantsFor(npc as NPC, dealType, { labelRep: label.reputation, playerFame: fame, relationship: npc.relationshipScore, competing, allIn: !!allIn });
        const pitch: LabelPitch = {
          id: uuidv4(),
          npcId,
          name: npc.name,
          openedSerial: serial,
          expiresSerial: serial + (competing ? 9 : PITCH_WINDOW_DAYS),
          terms: openingOffer(wants),
          wants,
          patience: patienceFor(npc as NPC),
          rounds: 0,
          status: 'open',
          competing: competing ? RIVAL_LABELS[hashString(`pc|${npcId}`) % RIVAL_LABELS.length] : undefined,
          warmth: 0,
          usedTactics: [],
          revealed: [],
        };
        label.pitches.unshift(pitch);
        labelEvent(label, serial, `Opened talks with ${npc.name}${allIn ? ' (all-in deal)' : ''}.`, 'neutral');
        result = { ok: true, message: competing ? `Talks open — but ${pitch.competing} is also chasing ${npc.name}. Move fast.` : `Talks open with ${npc.name}.` };
      });
      return result;
    },

    labelPitchContext: (pitchId) => {
      const state = get();
      const label = state.label;
      if (!label || !state.player) return null;
      const pitch = label.pitches.find((p) => p.id === pitchId);
      if (!pitch) return null;
      const npc = state.npcs.find((n) => n.id === pitch.npcId);
      if (!npc) return null;
      const legal = labelLegalSkill(state);
      const serial = dateToSerial(state.gameDate);
      const negotiator = labelNegotiatorSkill(state);
      const playerFame = blendedFame(state.player);
      const { score } = scoreOffer(npc, pitch.terms, pitch.wants);
      return {
        mood: moodOf(npc.id, serial),
        legalSkill: legal,
        lawyerNotes: lawyerRead(pitch.wants, legal),
        npc,
        potentialEstimate: potentialEstimate(potentialOf(npc), staffSkill(label.staff, 'ar'), npc.id),
        cap: fameCap(label.reputation, playerFame),
        negotiator,
        leverage: leverage({ labelRep: label.reputation, playerFame, negotiator, relationship: npc.relationshipScore }, npc.fame, !!pitch.competing),
        // Only a lawyer (or their own words) tells you how warm the table is.
        temperature: legal >= 30 || (pitch.rounds ?? 0) > 0 ? temperature(score + (pitch.warmth ?? 0)) : null,
        energy: state.player.energy,
      };
    },

    counterLabelPitch: (pitchId, terms) => {
      let out: { outcome: 'accepted' | 'countered' | 'refused' | 'walked' | 'error'; message: string } = { outcome: 'error', message: 'Those talks are over.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        const pitch = label.pitches.find((p) => p.id === pitchId);
        if (!pitch || pitch.status !== 'open') return;
        const npc = state.npcs.find((n) => n.id === pitch.npcId);
        if (!npc) return;
        const serial = dateToSerial(state.gameDate);
        const r = negotiateLabel(
          npc as NPC,
          pitch,
          normalizeTerms(terms),
          {
            labelRep: label.reputation,
            playerFame: blendedFame(state.player),
            relationship: npc.relationshipScore,
            moodShift: MOOD_INFO[moodOf(npc.id, serial)].shift,
            legalSkill: labelLegalSkill(state),
            negotiator: labelNegotiatorSkill(state),
          },
          Math.random(),
        );
        pitch.rounds += 1;
        pitch.patience = r.patience;
        pitch.lastReply = r.message;
        if (r.revealed) pitch.revealed = [...(pitch.revealed ?? []), r.revealed].slice(-6);
        if (r.outcome === 'walked') {
          pitch.status = 'walked';
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - 3);
          labelEvent(label, serial, `${pitch.name} walked away from the table.`, 'bad');
          if (pitch.renewal) {
            const s = label.roster.find((x) => x.npcId === pitch.npcId);
            if (s) retireSignee(state, label, s, 'left');
          }
        } else if (r.outcome === 'countered') {
          // Their counter is an offer they would sign as it stands.
          pitch.terms = r.terms;
          pitch.agreedTerms = { ...r.terms };
        } else if (r.outcome === 'accepted') {
          pitch.terms = normalizeTerms(terms);
          pitch.agreedTerms = normalizeTerms(terms);
        } else {
          pitch.agreedTerms = undefined;
        }
        out = { outcome: r.outcome, message: r.message };
      });
      return out;
    },

    labelTactic: (pitchId, tactic) => {
      let out: { ok: boolean; message: string; outcome?: 'accepted' | 'walked' } = { ok: false, message: 'Those talks are over.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        const pitch = label.pitches.find((p) => p.id === pitchId);
        if (!pitch || pitch.status !== 'open') return;
        const npc = state.npcs.find((n) => n.id === pitch.npcId);
        if (!npc) return;
        pitch.usedTactics = pitch.usedTactics ?? [];
        const once: LabelTactic[] = ['vision', 'personal', 'hardball'];
        if (once.includes(tactic) && pitch.usedTactics.includes(tactic)) { out = { ok: false, message: 'You already tried that with them.' }; return; }
        if (tactic === 'personal') {
          if (!spendEnergy(state, 25)) { out = { ok: false, message: 'A proper sit-down takes 25 energy. Rest first.' }; return; }
        }
        const serial = dateToSerial(state.gameDate);
        const r = applyTactic(npc as NPC, pitch, tactic, {
          labelRep: label.reputation,
          playerFame: blendedFame(state.player),
          relationship: npc.relationshipScore,
          moodShift: MOOD_INFO[moodOf(npc.id, serial)].shift,
          legalSkill: labelLegalSkill(state),
          negotiator: labelNegotiatorSkill(state),
        }, Math.random());
        pitch.usedTactics.push(tactic);
        pitch.warmth = Math.max(-0.2, Math.min(0.2, r.warmth));
        pitch.patience = r.patience;
        pitch.lastReply = r.message;
        if (r.revealed) pitch.revealed = [...(pitch.revealed ?? []), r.revealed].slice(-6);
        if (tactic === 'personal' && r.ok) npc.relationshipScore = Math.min(100, npc.relationshipScore + 4);
        if (r.concede) {
          // They drop the ask: your current line on that term is now fine.
          const k = r.concede as keyof LabelTerms;
          (pitch.wants as unknown as Record<string, unknown>)[k] = (pitch.terms as unknown as Record<string, unknown>)[k];
        }
        if (r.outcome === 'accepted') {
          pitch.agreedTerms = { ...pitch.terms };
          pitch.wants = { ...pitch.terms };
        } else if (r.outcome === 'walked') {
          pitch.status = 'walked';
          npc.relationshipScore = Math.max(-100, npc.relationshipScore - 5);
          labelEvent(label, serial, `${pitch.name} walked out after your ${TACTIC_INFO[tactic].label.toLowerCase()}.`, 'bad');
          if (pitch.renewal) {
            const s = label.roster.find((x) => x.npcId === pitch.npcId);
            if (s) retireSignee(state, label, s, 'left');
          }
        } else if (pitch.patience <= 0) {
          pitch.status = 'walked';
        }
        out = { ok: r.ok, message: r.message, outcome: r.outcome };
      });
      return out;
    },

    signLabelPitch: (pitchId) => {
      let result: FeatureActionResult = { ok: false, message: 'Those talks are over.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        normalizeLabel(label, dateToSerial(state.gameDate));
        const pitch = label.pitches.find((p) => p.id === pitchId);
        if (!pitch || pitch.status !== 'open') return;
        const npc = state.npcs.find((n) => n.id === pitch.npcId);
        if (!npc) return;
        const terms = normalizeTerms(pitch.terms);
        const agreed = pitch.agreedTerms && JSON.stringify(normalizeTerms(pitch.agreedTerms)) === JSON.stringify(terms);
        const { score } = scoreOffer(npc as NPC, terms, pitch.wants);
        if (!agreed && score < 1) {
          result.message = 'They have not agreed to these terms. Send them as an offer first.';
          return;
        }
        const due = signingCost(terms);
        if (label.cash < due) {
          result.message = `Signing costs ${money(due)} today (advance${terms.signingBonus ? ' + bonus' : ''}${terms.allIn ? ' + recording fund' : ''}). The label has ${money(label.cash)}. Put money in first.`;
          return;
        }
        const serial = dateToSerial(state.gameDate);
        labelSpend(label, due);
        pitch.status = 'signed';
        const recoup = terms.advance * recoupShare(terms.dealType, 'advance') + (terms.allIn ? terms.recordingFund * recoupShare(terms.dealType, 'fund') : 0);

        const existing = label.roster.find((s) => s.npcId === pitch.npcId);
        if (pitch.renewal && existing) {
          existing.terms = terms;
          existing.status = 'active';
          existing.signedSerial = serial;
          existing.endsSerial = serial + terms.termMonths * 30;
          existing.releasesDelivered = 0;
          existing.albumsDelivered = 0;
          existing.optionsUsed = 0;
          existing.recoupBalance += recoup;
          existing.fund += terms.allIn ? terms.recordingFund : 0;
          existing.fameAtSigning = existing.fame;
          existing.mood = Math.min(100, existing.mood + 15);
          existing.loyalty = Math.min(100, existing.loyalty + 10);
          existing.notes.unshift(`Re-signed: ${DEAL_INFO[terms.dealType].label}${terms.allIn ? ' (all-in)' : ''}, ${terms.royalty}% royalty.`);
          labelEvent(label, serial, `${pitch.name} re-signed with ${label.name}.`, 'good');
          result = { ok: true, message: `${pitch.name} re-signed.` };
          return;
        }

        const signee: LabelSignee = {
          npcId: npc.id,
          name: npc.name,
          genre: (npc.genre ?? 'hip_hop') as LabelSignee['genre'],
          country: npc.country,
          tier: npc.tier,
          signedSerial: serial,
          endsSerial: serial + terms.termMonths * 30,
          terms,
          fameAtSigning: npc.fame,
          fame: npc.fame,
          potential: potentialOf(npc as NPC),
          recoupBalance: recoup,
          fund: terms.allIn ? terms.recordingFund : 0,
          mood: 70 + Math.min(15, Math.round(terms.signingBonus / 2000)),
          loyalty: Math.round(Math.max(20, Math.min(80, 40 + npc.relationshipScore / 3))),
          releases: [],
          albums: [],
          releasesDelivered: 0,
          albumsDelivered: 0,
          singlesSinceAlbum: 0,
          workSerial: serial + 10 + Math.floor(unit(`first|${npc.id}`) * 12),
          optionsUsed: 0,
          status: 'active',
          grossEarned: 0,
          labelEarned: 0,
          artistPaid: 0,
          monthGross: 0,
          notes: [`Signed: ${DEAL_INFO[terms.dealType].label}${terms.allIn ? ` (all-in, ${money(terms.recordingFund)} fund)` : ''}, ${terms.royalty}% royalty, ${money(terms.advance)} advance.`],
        };
        label.roster.push(signee);
        npc.team = { ...(npc.team ?? {}), label: label.name };
        npc.relationshipScore = Math.min(100, npc.relationshipScore + 8);
        label.prospects = label.prospects.filter((p) => p.npcId !== npc.id);
        label.reputation = Math.min(100, label.reputation + (npc.fame >= 40 ? 3 : 1));
        labelEvent(label, serial, `Signed ${npc.name}. ${money(due)} paid today. They are already writing.`, 'good');
        labelPost(state, label, [['chirp', `Welcome to the family, ${npc.name} ✍🏾 New era loading.`, 'announce'], ['snapgram', `${label.name} × ${npc.name} — signed.`, 'photo']], undefined, npc.id);
        state.socialPosts.unshift({
          id: uuidv4(), platform: 'chirp', authorId: 'player', authorName: state.player.artistName,
          content: `Welcome ${npc.name} to ${label.name}. 🏷️ The family just got bigger.`,
          likes: Math.round(50 + npc.fame * 35 + blendedFame(state.player) * 20), shares: Math.round(6 + npc.fame * 5), comments: [],
          timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 15 + npc.fame / 2, daySerial: serial,
        });
        pushNotification(state, {
          kind: 'business',
          title: `${npc.name} signed to ${label.name}`,
          body: `${DEAL_INFO[terms.dealType].label}${terms.allIn ? ' (all-in)' : ''} · ${terms.royalty}% royalty · ${terms.releasesOwed} singles, ${terms.albumsOwed} album${terms.albumsOwed === 1 ? '' : 's'}.`,
          artSeed: `artist|${npc.id}`,
          action: { type: 'artist', id: npc.id },
        });
        result = { ok: true, message: `${npc.name} is signed to ${label.name}. Their first demo should land in a couple of weeks.` };
      });
      return result;
    },

    withdrawLabelPitch: (pitchId) =>
      set((state) => {
        const label = state.label;
        if (!label) return;
        const pitch = label.pitches.find((p) => p.id === pitchId);
        if (!pitch || pitch.status !== 'open') return;
        pitch.status = 'withdrawn';
        if (pitch.renewal) {
          const s = label.roster.find((x) => x.npcId === pitch.npcId);
          if (s) retireSignee(state, label, s, 'left');
        }
      }),

    exerciseLabelOption: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'No option to exercise.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s || s.status !== 'expiring') return;
        if (s.terms.optionYears <= s.optionsUsed) { result.message = 'There are no option years left on this deal.'; return; }
        const serial = dateToSerial(state.gameDate);
        s.optionsUsed += 1;
        s.status = 'active';
        s.endsSerial = serial + 365;
        // Being held to old terms after you blew up stings; a happy artist shrugs.
        const grew = s.fame - s.fameAtSigning;
        const hit = s.mood < 50 || grew >= 12 ? 12 : 3;
        s.mood = Math.max(0, s.mood - hit);
        s.loyalty = Math.max(0, s.loyalty - (hit > 5 ? 8 : 1));
        label.pitches = label.pitches.map((p) => (p.npcId === npcId && p.status === 'open' && p.renewal ? { ...p, status: 'withdrawn' as const } : p));
        labelEvent(label, serial, `Exercised an option year on ${s.name}.${hit > 5 ? ' They feel trapped.' : ''}`, hit > 5 ? 'bad' : 'neutral');
        result = { ok: true, message: hit > 5 ? `${s.name} is yours for another year — and they are not happy about the old terms.` : `${s.name} is yours for another year.` };
      });
      return result;
    },

    answerLabelSubmission: (subId, answer, tier) => {
      let result: FeatureActionResult = { ok: false, message: 'That demo is not waiting on you.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        normalizeLabel(label, dateToSerial(state.gameDate));
        const sub = label.submissions.find((x) => x.id === subId);
        if (!sub || sub.status !== 'pending') return;
        const s = label.roster.find((x) => x.npcId === sub.npcId);
        if (!s) { sub.status = 'rejected'; return; }
        const npc = state.npcs.find((n) => n.id === sub.npcId) as NPC | undefined;
        const serial = dateToSerial(state.gameDate);
        if (answer === 'approve') {
          if (s.status === 'dispute') { result.message = `${s.name} is refusing to record until the dispute is settled.`; return; }
          const err = startLabelSession(state, label, s, sub, tier ?? sub.askTier, serial);
          if (err) { result.message = err; return; }
          sub.status = 'approved';
          // Giving them less than they asked for is noticed.
          const order: LabelReleaseTier[] = ['demo', 'standard', 'major'];
          const gap = order.indexOf(sub.askTier) - order.indexOf(tier ?? sub.askTier);
          if (gap > 0) { s.mood = Math.max(0, s.mood - gap * 4); s.notes.unshift(`Wanted a ${RELEASE_TIERS[sub.askTier].label.toLowerCase()}; got less.`); }
          if (gap < 0) s.mood = Math.min(100, s.mood + 4);
          result = { ok: true, message: `Approved. ${s.name} is in the studio — out in ${(s.inStudio?.until ?? serial) - serial} days.` };
        } else if (answer === 'rework') {
          const r = reworkOutcome(npc, sub, Math.random());
          sub.status = 'reworking';
          sub.reworks += 1;
          sub.quality = r.quality;
          sub.dueSerial = serial + 8 + Math.floor(Math.random() * 10);
          s.mood = Math.max(0, Math.min(100, s.mood + r.mood));
          labelEvent(label, serial, `Sent "${sub.title}" back to ${s.name}. ${r.text}`, r.mood < -5 ? 'bad' : 'neutral');
          result = { ok: true, message: `${r.text} The new version comes back in about ${sub.dueSerial - serial} days.` };
        } else {
          sub.status = 'rejected';
          // A shelved album sends them back to singles for a while.
          if (sub.kind === 'album') s.singlesSinceAlbum = 1;
          const t = npc ? traitsOf(npc) : null;
          const hit = t?.diva ? 14 : t?.petty ? 10 : 6;
          s.mood = Math.max(0, s.mood - hit);
          s.loyalty = Math.max(0, s.loyalty - Math.round(hit / 3));
          s.workSerial = serial + 15 + Math.floor(Math.random() * 15);
          labelEvent(label, serial, `Shelved ${s.name}'s "${sub.title}".`, 'bad');
          result = { ok: true, message: `Shelved. ${s.name} ${hit >= 10 ? 'took it personally' : 'is disappointed'} and is back writing.` };
        }
      });
      return result;
    },

    fundLabelRelease: (npcId, tier) => {
      let result: FeatureActionResult = { ok: false, message: 'Not on the roster.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        normalizeLabel(label, dateToSerial(state.gameDate));
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s) return;
        if (s.status === 'dispute') { result.message = `${s.name} is refusing to record until the dispute is settled.`; return; }
        if (s.status !== 'active' && s.status !== 'expiring') { result.message = `${s.name} is not under contract.`; return; }
        if (s.inStudio) { result.message = `${s.name} is already in the studio.`; return; }
        const serial = dateToSerial(state.gameDate);
        const sinceLast = serial - (s.lastReleaseSerial ?? -999);
        if (sinceLast < 30) {
          result.message = `${s.name}'s last record came out ${sinceLast} day${sinceLast === 1 ? '' : 's'} ago. Give it at least a month.`;
          return;
        }
        const err = startLabelSession(state, label, s, null, tier, serial);
        if (err) { result.message = err; return; }
        const booked = s.inStudio as LabelSession | undefined;
        result = { ok: true, message: `${s.name} is in the studio. The record lands in ${(booked?.until ?? serial) - serial} days.` };
      });
      return result;
    },

    shootLabelVideo: (songId, tierId) => {
      let result: FeatureActionResult = { ok: false, message: 'Not a label record.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        normalizeLabel(label, dateToSerial(state.gameDate));
        const s = label.roster.find((x) => x.releases.includes(songId));
        const song = state.npcSongs.find((x) => x.id === songId);
        if (!s || !song) { result.message = 'Only records by artists currently on your label can be shot.'; return; }
        const tier = VIDEO_TIERS.find((v) => v.id === tierId) ?? VIDEO_TIERS[1];
        const payer = s.terms.allIn ? 'fund' : 'label';
        const err = startLabelVideo(state, label, s, song, tier.budget, tier.days, payer, dateToSerial(state.gameDate));
        if (err) { result.message = err; return; }
        result = { ok: true, message: `${s.name} is shooting a ${tier.label.toLowerCase()} for "${song.title}". It premieres in ${tier.days} days.` };
      });
      return result;
    },

    topUpLabelFund: (npcId, amount) => {
      let result: FeatureActionResult = { ok: false, message: 'Not on the roster.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s) return;
        if (!s.terms.allIn) { result.message = `${s.name} is on a label-funded deal; you pay per record.`; return; }
        const amt = Math.floor(amount);
        if (amt <= 0) { result.message = 'Enter an amount.'; return; }
        if (label.cash < amt) { result.message = `The label only has ${money(label.cash)}.`; return; }
        labelSpend(label, amt);
        s.fund += amt;
        s.recoupBalance += amt;
        s.mood = Math.min(100, s.mood + 4);
        if (s.workSerial > dateToSerial(state.gameDate) + 14 && !label.submissions.some((x) => x.npcId === npcId && (x.status === 'pending' || x.status === 'reworking'))) {
          s.workSerial = dateToSerial(state.gameDate) + 3;
        }
        labelEvent(label, dateToSerial(state.gameDate), `Topped up ${s.name}'s fund by ${money(amt)} (recoupable).`, 'neutral');
        result = { ok: true, message: `${s.name}'s fund is now ${money(s.fund)}.` };
      });
      return result;
    },

    promoteLabelSong: (songId, amount) => {
      let result: FeatureActionResult = { ok: false, message: 'Not a label record.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = [...label.roster, ...label.alumni].find((x) => x.releases.includes(songId));
        const song = state.npcSongs.find((x) => x.id === songId);
        if (!s || !song) return;
        const amt = Math.floor(amount);
        if (amt <= 0) { result.message = 'Enter an amount.'; return; }
        if (label.cash < amt) { result.message = `The label only has ${money(label.cash)}.`; return; }
        labelSpend(label, amt);
        if (labelSigneeIds(label).has(s.npcId)) s.recoupBalance += amt * recoupShare(s.terms.dealType, 'marketing');
        song.marketingBudget = (song.marketingBudget ?? 0) + Math.round(amt * marketingEfficiency(staffSkill(label.staff, 'marketing')));
        s.mood = Math.min(100, s.mood + 2);
        labelEvent(label, dateToSerial(state.gameDate), `Pushed ${money(amt)} behind "${song.title}".`, 'neutral');
        result = { ok: true, message: `${money(amt)} campaign behind "${song.title}".` };
      });
      return result;
    },

    answerLabelDemand: (npcId, answer) => {
      let result: FeatureActionResult = { ok: false, message: 'No open demand.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s?.demand) return;
        const serial = dateToSerial(state.gameDate);
        const d = s.demand;
        if (answer === 'raise' && d.royalty) {
          s.notes.unshift(`Royalty raised ${s.terms.royalty}% → ${d.royalty}%.`);
          s.terms.royalty = d.royalty;
          s.mood = Math.min(100, s.mood + 18);
          s.loyalty = Math.min(100, s.loyalty + 10);
          labelEvent(label, serial, `Gave ${s.name} the raise.`, 'good');
          result = { ok: true, message: `${s.name} is happy. Royalty now ${d.royalty}%.` };
        } else if (answer === 'bonus' && d.bonus) {
          if (label.cash < d.bonus) { result.message = `The bonus is ${money(d.bonus)}; the label has ${money(label.cash)}.`; return; }
          labelSpend(label, d.bonus);
          s.mood = Math.min(100, s.mood + 12);
          s.loyalty = Math.min(100, s.loyalty + 4);
          labelEvent(label, serial, `Paid ${s.name} a ${money(d.bonus)} bonus.`, 'good');
          result = { ok: true, message: `${s.name} took the bonus. For now.` };
        } else {
          s.mood = Math.max(0, s.mood - 15);
          s.loyalty = Math.max(0, s.loyalty - 10);
          labelEvent(label, serial, `Told ${s.name} no.`, 'bad');
          result = { ok: true, message: `${s.name}'s camp did not take it well.` };
          if (s.mood < 25) {
            s.status = 'dispute';
            labelMail(state, `⚠️ ${s.name} is in dispute`, `${s.name} says they are done recording for ${label.name} until the deal is fixed.`);
          }
        }
        s.demand = undefined;
      });
      return result;
    },

    answerRivalOffer: (npcId, answer) => {
      let result: FeatureActionResult = { ok: false, message: 'No offer on the table.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s?.rivalOffer) return;
        const serial = dateToSerial(state.gameDate);
        const offer = s.rivalOffer;
        if (answer === 'match') {
          s.notes.unshift(`Matched ${offer.labelName}: royalty ${s.terms.royalty}% → ${offer.royalty}%.`);
          s.terms.royalty = offer.royalty;
          s.mood = Math.min(100, s.mood + 12);
          s.loyalty = Math.min(100, s.loyalty + 15);
          s.rivalOffer = undefined;
          labelEvent(label, serial, `Matched ${offer.labelName} to keep ${s.name}.`, 'good');
          result = { ok: true, message: `${s.name} stays, on ${offer.royalty}%.` };
        } else if (answer === 'sell') {
          labelEarn(label, offer.buyout);
          s.labelEarned += offer.buyout;
          retireSignee(state, label, s, 'sold');
          labelEvent(label, serial, `Sold ${s.name}'s contract to ${offer.labelName} for ${money(offer.buyout)}.`, 'neutral');
          labelMail(state, `🤝 ${s.name} → ${offer.labelName}`, `${offer.labelName} paid ${money(offer.buyout)} to take over ${s.name}'s contract. The records ${label.name} already released stay in your catalogue.`);
          result = { ok: true, message: `Contract sold for ${money(offer.buyout)}.` };
        } else {
          s.rivalOffer = undefined;
          if (s.loyalty >= 70) {
            s.mood = Math.max(0, s.mood - 3);
            result = { ok: true, message: `${s.name} understands. They were staying anyway.` };
          } else {
            s.mood = Math.max(0, s.mood - 18);
            s.loyalty = Math.max(0, s.loyalty - 8);
            result = { ok: true, message: `You kept ${s.name}. They are not happy about it.` };
            if (s.mood < 25) s.status = 'dispute';
          }
          labelEvent(label, serial, `Refused to release ${s.name} to ${offer.labelName}.`, s.loyalty >= 70 ? 'neutral' : 'bad');
        }
      });
      return result;
    },

    settleLabelDispute: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'No dispute.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s || s.status !== 'dispute') return;
        const cost = settlementCost(s, labelLegalSkill(state));
        if (label.cash < cost) { result.message = `Settling costs ${money(cost)}; the label has ${money(label.cash)}.`; return; }
        labelSpend(label, cost);
        s.status = 'active';
        s.mood = 50;
        s.loyalty = Math.max(0, s.loyalty - 5);
        s.demand = undefined;
        labelEvent(label, dateToSerial(state.gameDate), `Settled with ${s.name} for ${money(cost)}.`, 'neutral');
        result = { ok: true, message: `Settled for ${money(cost)}. ${s.name} is back in the studio.` };
      });
      return result;
    },

    dropLabelArtist: (npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'Not on the roster.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.roster.find((x) => x.npcId === npcId);
        if (!s) return;
        const serial = dateToSerial(state.gameDate);
        const optics = dropOptics(s);
        label.reputation = Math.max(0, label.reputation + optics);
        const npc = state.npcs.find((n) => n.id === npcId);
        if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 12);
        if (s.inStudio) labelEvent(label, serial, `The unfinished ${s.name} record is shelved for good.`, 'bad');
        retireSignee(state, label, s, 'dropped');
        label.pitches = label.pitches.map((p) => (p.npcId === npcId && p.status === 'open' ? { ...p, status: 'withdrawn' as const } : p));
        labelEvent(label, serial, `Dropped ${s.name}.${optics < 0 ? ' People noticed.' : ''}`, 'bad');
        result = { ok: true, message: `${s.name} is off the label.${s.recoupBalance > 0 ? ` ${money(s.recoupBalance)} unrecouped is written off.` : ''}` };
      });
      return result;
    },

    upgradeLabelStudio: () => {
      let result: FeatureActionResult = { ok: false, message: 'No label.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        normalizeLabel(label, dateToSerial(state.gameDate));
        const next = label.studio.tier + 1;
        if (next >= STUDIO_TIERS.length) { result.message = 'The studio is already the best in the country.'; return; }
        const t = STUDIO_TIERS[next];
        if (label.cash < t.cost) { result.message = `${t.name} costs ${money(t.cost)}. The label has ${money(label.cash)}.`; return; }
        labelSpend(label, t.cost);
        label.studio.tier = next;
        labelEvent(label, dateToSerial(state.gameDate), `Built the ${t.name.toLowerCase()} (${money(t.cost)}).`, 'good');
        for (const s of label.roster) s.mood = Math.min(100, s.mood + 2);
        result = { ok: true, message: `${t.name} is open. ${t.blurb}` };
      });
      return result;
    },

    buyLabelGear: (gear) => {
      let result: FeatureActionResult = { ok: false, message: 'No label.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        normalizeLabel(label, dateToSerial(state.gameDate));
        const lvl = label.studio.gear[gear] ?? 0;
        if (lvl >= gearCap(label.studio.tier)) {
          result.message = label.studio.tier === 0 ? 'Build a studio first.' : `The ${STUDIO_TIERS[label.studio.tier].name.toLowerCase()} has no room for more. Upgrade the building.`;
          return;
        }
        const cost = GEAR_INFO[gear].costs[lvl];
        if (label.cash < cost) { result.message = `That costs ${money(cost)}. The label has ${money(label.cash)}.`; return; }
        labelSpend(label, cost);
        label.studio.gear[gear] = lvl + 1;
        labelEvent(label, dateToSerial(state.gameDate), `Upgraded the ${GEAR_INFO[gear].label.toLowerCase()} to level ${lvl + 1} (${money(cost)}).`, 'good');
        result = { ok: true, message: `${GEAR_INFO[gear].label} upgraded.` };
      });
      return result;
    },

    labelStaffCandidates: (role) => {
      const state = get();
      const label = state.label;
      if (!label) return [];
      const from = STAFF_INFO[role].from;
      const taken = new Set(label.staff.map((s) => s.npcId));
      const out: { npcId: string; name: string; skill: number; salary: number; country: string }[] = [];
      for (const n of state.npcs) {
        if (!from.includes(n.role) || taken.has(n.id)) continue;
        const skill = npcSkill(n);
        out.push({ npcId: n.id, name: n.name, skill, salary: staffSalary(skill), country: n.country });
      }
      out.sort((a, b) => (Number(b.country === label.country) - Number(a.country === label.country)) || b.skill - a.skill);
      const home = out.filter((c) => c.country === label.country).slice(0, 4);
      const abroad = out.filter((c) => c.country !== label.country).slice(0, 2);
      return [...home, ...abroad];
    },

    hireLabelStaff: (role, npcId) => {
      let result: FeatureActionResult = { ok: false, message: 'Could not hire.' };
      set((state) => {
        const label = state.label;
        if (!label) return;
        if (label.staff.some((s) => s.role === role)) { result.message = `You already have a ${STAFF_INFO[role].title}. Let them go first.`; return; }
        const npc = state.npcs.find((n) => n.id === npcId);
        if (!npc || !STAFF_INFO[role].from.includes(npc.role)) return;
        const skill = npcSkill(npc as NPC);
        const salary = staffSalary(skill);
        if (label.cash < salary) { result.message = `The first month's salary is ${money(salary)}. The label has ${money(label.cash)}.`; return; }
        const serial = dateToSerial(state.gameDate);
        label.staff.push({ role, npcId, name: npc.name, skill, salary, hiredSerial: serial });
        labelEvent(label, serial, `Hired ${npc.name} as ${STAFF_INFO[role].title} (${money(salary)}/month).`, 'good');
        if (role === 'ar') label.prospectsSerial = -999;
        result = { ok: true, message: `${npc.name} joins as ${STAFF_INFO[role].title}.${role === 'engineer' && label.studio.tier === 0 ? ' They need a studio to work in — build one.' : ''}` };
      });
      return result;
    },

    fireLabelStaff: (role) =>
      set((state) => {
        const label = state.label;
        if (!label) return;
        const s = label.staff.find((x) => x.role === role);
        if (!s) return;
        label.staff = label.staff.filter((x) => x.role !== role);
        labelEvent(label, dateToSerial(state.gameDate), `${s.name} left the ${STAFF_INFO[role].title} job.`, 'neutral');
      }),

    // ─── LUXURY ─────────────────────────────────────────────────────────
    sellLuxury: (assetId) => {
      let result: FeatureActionResult = { ok: false, message: 'You don\'t own that.' };
      set((state) => {
        const p = state.player;
        const i = (state.ownedAssets ?? []).findIndex((a) => a.id === assetId);
        if (!p || i < 0) return;
        const a = state.ownedAssets[i];
        const age = a.purchaseDate ? dateToSerial(state.gameDate) - serialOfGameDate(a.purchaseDate, dateToSerial(state.gameDate)) : 0;
        const value = a.category === 'home'
          ? Math.round(a.cost * (state.market?.propertyIndex ?? 100) / 100 * 0.97)
          : resaleFor(a.category, a.cost, age, (hashString(a.id + age) % 1000) / 1000);
        p.career.money += value;
        state.ownedAssets.splice(i, 1);
        if (a.disciplineBonus) p.stats.discipline = Math.max(0, p.stats.discipline - a.disciplineBonus);
        remember(state, 'money', `Sold the ${a.name} for ${money0(value)} (paid ${money0(a.cost)}).`, { weight: 2 });
        result = { ok: true, message: `Sold the ${a.name} for ${money0(value)}.` };
      });
      return result;
    },

    moveHome: (tier, how, ownedId) => {
      let result: FeatureActionResult = { ok: false, message: 'You can\'t move right now.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const h = homeOf(state);
        const today = dateToSerial(state.gameDate);
        const idx = state.market?.propertyIndex ?? 100;
        const def = homeDef(tier);
        if (h.due) { result.message = `Settle the ${money0(h.due.amount)} you owe the landlord first.`; return; }
        if (how === 'own') {
          const o = (state.homes ?? []).find((x) => x.id === ownedId);
          if (!o) { result.message = 'You don\'t own that place.'; return; }
          if (h.ownedId === o.id) { result.message = 'You already live there.'; return; }
          const fee = movingFee(o.tier, o.country);
          if (p.career.money < fee) { result.message = `Movers want ${money0(fee)}.`; return; }
          if (!spendEnergy(state, 15)) { result.message = energyShortfallMessage(15, p.energy); return; }
          p.career.money -= fee;
          const tenants = o.rentedOut;
          o.rentedOut = false;
          if (h.deposit) p.career.money += h.deposit;
          state.home = { tier: o.tier, city: o.city, country: o.country, ownedId: o.id, since: today, paidUntil: today + 100_000, nextBill: h.nextBill };
          remember(state, 'life', `Moved into my own ${homeDef(o.tier).name.toLowerCase()} in ${o.city}.`, { weight: 3, tone: 'good' });
          result = { ok: true, message: `Moved into your ${homeDef(o.tier).name.toLowerCase()}.${tenants ? ' The tenants have moved out.' : ''}` };
          return;
        }
        if (how === 'rent') {
          if (tier === h.tier && !h.ownedId) { result.message = 'You already live in one.'; return; }
          const cost = tier === 'family' ? 0 : moveInCost(tier, p.country);
          if (p.career.money < cost) { result.message = `Moving in costs ${money0(cost)} — ${renewalMonths(p.country) >= 12 ? 'a year of rent up front, the way landlords here want it' : 'first month and a deposit'}, plus movers.`; return; }
          if (!spendEnergy(state, 15)) { result.message = energyShortfallMessage(15, p.energy); return; }
          p.career.money -= cost;
          if (h.deposit && !h.ownedId) p.career.money += h.deposit;
          const prepaid = tier === 'family' ? 0 : renewalMonths(p.country);
          const rent = rentFor(tier, p.country);
          const deposit = tier === 'family' ? 0 : Math.max(0, cost - movingFee(tier, p.country) - rent * prepaid);
          state.home = { tier, city: p.city, country: p.country, since: today, paidUntil: tier === 'family' ? today + 100_000 : today + prepaid * 30, nextBill: h.nextBill, deposit };
          remember(state, 'life', tier === 'family' ? 'Moved back into the family house.' : `Moved into a ${def.name.toLowerCase()} in ${p.city}. ${money0(cost)} to get the keys.`, { weight: 3, tone: tier === 'family' ? 'neutral' : 'good' });
          result = { ok: true, message: tier === 'family' ? 'Back at the family house. Your mum is happy.' : `Moved in. ${money0(cost)} paid${prepaid >= 12 ? ' — rent is covered for the year' : ''}.` };
        } else if (how === 'mortgage') {
          const price = priceFor(tier, p.country, idx);
          if (!price) { result.message = 'That isn\'t for sale.'; return; }
          const score = creditOf(state);
          const offer = mortgageOffer(score, monthlyIncomeOf(state), price, p.country);
          if (!offer) { result.message = score < 600 ? `The bank turned you down — your credit score is ${score}.` : `The bank won't lend that much on what you earn (${money0(monthlyIncomeOf(state))}/month). The payment would be over 40% of it.`; return; }
          const cost = offer.down + movingFee(tier, p.country);
          if (p.career.money < cost) { result.message = `You need ${money0(offer.down)} down (20%) plus movers.`; return; }
          if (!spendEnergy(state, 15)) { result.message = energyShortfallMessage(15, p.energy); return; }
          p.career.money -= cost;
          if (h.deposit && !h.ownedId) p.career.money += h.deposit;
          const id = uuidv4();
          (state.homes ?? (state.homes = [])).push({ id, tier, city: p.city, country: p.country, paid: price, indexAtBuy: idx, boughtSerial: today });
          state.home = { tier, city: p.city, country: p.country, ownedId: id, since: today, paidUntil: today + 100_000, nextBill: h.nextBill };
          const lender = LENDERS[hashString(p.id) % LENDERS.length];
          (state.loans ?? (state.loans = [])).push({ id: uuidv4(), kind: 'mortgage', lender, principal: offer.loan, balance: offer.loan, apr: offer.apr, months: offer.months, monthly: offer.monthly, startSerial: today, nextDue: today + 30, paidMonths: 0, missed: 0, status: 'active', homeId: id });
          remember(state, 'money', `Bought a ${def.name.toLowerCase()} in ${p.city} with a mortgage from ${lender}: ${money0(offer.monthly)} a month for ${offer.months / 12} years.`, { weight: 5, tone: 'good' });
          result = { ok: true, message: `Keys in hand. ${money0(offer.monthly)}/month to ${lender} for ${offer.months / 12} years at ${(offer.apr * 100).toFixed(1)}%.` };
        } else {
          const price = priceFor(tier, p.country, idx);
          if (!price) { result.message = 'That isn\'t for sale.'; return; }
          const cost = price + movingFee(tier, p.country);
          if (p.career.money < cost) { result.message = `It's ${money0(price)}, plus ${money0(cost - price)} to move. You have ${money0(p.career.money)}.`; return; }
          if (!spendEnergy(state, 15)) { result.message = energyShortfallMessage(15, p.energy); return; }
          p.career.money -= cost;
          if (h.deposit && !h.ownedId) p.career.money += h.deposit;
          const id = uuidv4();
          (state.homes ?? (state.homes = [])).push({ id, tier, city: p.city, country: p.country, paid: price, indexAtBuy: idx, boughtSerial: today });
          state.home = { tier, city: p.city, country: p.country, ownedId: id, since: today, paidUntil: today + 100_000, nextBill: h.nextBill };
          remember(state, 'money', `Bought a ${def.name.toLowerCase()} in ${p.city} for ${money0(price)}. Mine.`, { weight: 5, tone: 'good' });
          pushNotification(state, { kind: 'business', title: `${def.emoji} You bought a ${def.name.toLowerCase()}`, body: `${p.city}. ${money0(price)}. The keys are yours.`, artSeed: `home|${id}`, action: { type: 'home', id } });
          result = { ok: true, message: `Bought for ${money0(price)}. Welcome home.` };
        }
        // People notice a big move.
        if (def.image >= 3 && blendedFame(p) >= 20) {
          const handle = `@${fanHandle(`${today}|move`)}`;
          const post: SocialPost = { id: uuidv4(), platform: 'chirp', authorId: `fan:${handle}`, authorName: handle, content: pickLine([`${p.artistName} moved into a ${def.name.toLowerCase()}?? 😳 the music paying`, `Not ${p.artistName} upgrading the crib 🏡 we love to see it`, `${p.artistName} new house is crazy. Started from the family house 🙏`], `${today}`), likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: false, trendingScore: 40, tags: [{ id: 'player', name: p.artistName }] };
          livenPost(state, post, { at: gameMinute(state) + 120 });
          state.socialPosts.unshift(post);
        }
      });
      return result;
    },

    takeLoan: (amount) => {
      let result: FeatureActionResult = { ok: false, message: 'The bank said no.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const active = (state.loans ?? []).filter((l) => l.status === 'active');
        if (active.some((l) => l.kind === 'personal')) { result.message = 'You already have a personal loan. Pay it down first.'; return; }
        if ((state.loans ?? []).some((l) => l.status === 'default')) { result.message = 'No bank will touch you while a default is on your record.'; return; }
        const score = creditOf(state);
        const offer = personalOffer(score, monthlyIncomeOf(state), p.country);
        if (!offer) { result.message = `Declined. Credit score ${score}, and the bank wants to see steady income first.`; return; }
        const amt = Math.min(offer.max, Math.max(500, Math.round(amount / 100) * 100));
        const lender = LENDERS[(hashString(p.id) + 1) % LENDERS.length];
        const today = dateToSerial(state.gameDate);
        const monthly = paymentFor(amt, offer.apr, offer.months);
        (state.loans ?? (state.loans = [])).push({ id: uuidv4(), kind: 'personal', lender, principal: amt, balance: amt, apr: offer.apr, months: offer.months, monthly, startSerial: today, nextDue: today + 30, paidMonths: 0, missed: 0, status: 'active' });
        p.career.money += amt;
        remember(state, 'money', `Borrowed ${money0(amt)} from ${lender} at ${(offer.apr * 100).toFixed(1)}%.`, { weight: 2 });
        result = { ok: true, message: `${money0(amt)} is in your account. ${money0(monthly)} a month for ${offer.months} months, ${(offer.apr * 100).toFixed(1)}% a year.` };
      });
      return result;
    },

    repayLoan: (loanId) => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to repay.' };
      set((state) => {
        const p = state.player;
        const l = (state.loans ?? []).find((x) => x.id === loanId && x.status === 'active');
        if (!p || !l) return;
        if (p.career.money < l.balance) { result.message = `The balance is ${money0(l.balance)}. You have ${money0(p.career.money)}.`; return; }
        p.career.money -= l.balance;
        l.balance = 0;
        l.status = 'paid';
        (state.credit ?? (state.credit = { missedEver: 0, defaults: 0, paidOff: 0 })).paidOff += 1;
        remember(state, 'money', `Paid off the ${l.kind === 'mortgage' ? 'mortgage' : 'loan'} with ${l.lender} early.`, { weight: 3, tone: 'good' });
        result = { ok: true, message: `Paid off. ${l.lender} sends its regards.` };
      });
      return result;
    },

    payRent: () => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing is owed.' };
      set((state) => {
        const p = state.player;
        const h = state.home;
        if (!p || !h?.due) return;
        if (p.career.money < h.due.amount) { result.message = `You need ${money0(h.due.amount)}. You have ${money0(p.career.money)}.`; return; }
        p.career.money -= h.due.amount;
        const months = Math.max(1, Math.round(h.due.amount / Math.max(1, rentFor(h.tier, h.country))));
        h.paidUntil += months * 30;
        h.due = undefined;
        result = { ok: true, message: `Paid. The landlord is smiling again.` };
      });
      return result;
    },

    sellHome: (id) => {
      let result: FeatureActionResult = { ok: false, message: 'You don\'t own that.' };
      set((state) => {
        const p = state.player;
        const list = state.homes ?? [];
        const i = list.findIndex((x) => x.id === id);
        if (!p || i < 0) return;
        if (state.home?.ownedId === id) { result.message = 'You live there. Move somewhere else first.'; return; }
        const o = list[i];
        const value = Math.round(ownedValue(o, state.market?.propertyIndex ?? 100) * 0.97);
        // The mortgage comes out of the sale first.
        const loan = (state.loans ?? []).find((l) => l.homeId === o.id && l.status === 'active');
        if (loan && loan.balance > value + p.career.money) { result.message = `The mortgage balance is ${money0(loan.balance)} and the sale would raise ${money0(value)}. You can't cover the difference.`; return; }
        if (loan) { p.career.money -= loan.balance; loan.balance = 0; loan.status = 'paid'; (state.credit ?? (state.credit = { missedEver: 0, defaults: 0, paidOff: 0 })).paidOff += 1; }
        p.career.money += value;
        list.splice(i, 1);
        remember(state, 'money', `Sold the ${homeDef(o.tier).name.toLowerCase()} in ${o.city} for ${money0(value)} (paid ${money0(o.paid)}).`, { weight: 3 });
        result = { ok: true, message: `Sold for ${money0(value)} after the agent's 3%.` };
      });
      return result;
    },

    setHomeRentedOut: (id, on) => {
      let result: FeatureActionResult = { ok: false, message: 'You don\'t own that.' };
      set((state) => {
        const o = (state.homes ?? []).find((x) => x.id === id);
        if (!o) return;
        if (on && state.home?.ownedId === id) { result.message = 'You live there.'; return; }
        o.rentedOut = on;
        result = { ok: true, message: on ? `Let to tenants: ${money0(rentIncome(o))} a month after the agent.` : 'The tenants will be out by the end of the month.' };
      });
      return result;
    },

    postAsLabel: (o) => {
      let result: FeatureActionResult = { ok: false, message: 'You don\'t run a label.' };
      set((state) => {
        const label = state.label;
        if (!label || !state.player) return;
        if (!o.content.trim()) { result.message = 'Write something first.'; return; }
        if (!spendEnergy(state, 2, { admin: true })) { result.message = energyShortfallMessage(2, state.player.energy); return; }
        labelPost(state, label, o.apps.map((a) => [a, o.content.trim(), o.kind] as [SocialApp, string, PostKind]), o.songId);
        result = { ok: true, message: `Posted on ${label.name}${/s$/i.test(label.name) ? '\'' : '\'s'} page.` };
      });
      return result;
    },

    houseTour: () => {
      let result: FeatureActionResult = { ok: false, message: 'Nothing to show.' };
      set((state) => {
        const p = state.player;
        if (!p) return;
        const h = homeOf(state);
        const def = homeDef(h.tier);
        if (def.image < 2) { result.message = 'Nobody wants a tour of your old bedroom. Yet.'; return; }
        if (h.toured) { result.message = 'You already showed this place.'; return; }
        if (!spendEnergy(state, 10, { admin: true })) { result.message = energyShortfallMessage(10, p.energy); return; }
        h.toured = true;
        const minute = gameMinute(state);
        const stats = socialStatsOf(state);
        const post: SocialPost = { id: uuidv4(), platform: 'clip', authorId: 'player', authorName: p.artistName, content: `House tour 🏡 ${def.emoji} welcome to the new place`, likes: 0, shares: 0, comments: [], timestamp: new Date().toISOString(), isPlayerPost: true, trendingScore: 30 + def.image * 10, daySerial: dateToSerial(state.gameDate), kind: 'bts' };
        const r = postReach({ boost: socialBoost(state), app: 'clip', kind: 'bts', followers: stats.clip.followers, fame: blendedFame(p), momentum: p.career.momentum, postsToday: 0, taggedFame: [], controversy: false, craft: p.stats.charisma + def.image * 6, roll: Math.random() });
        post.target = { likes: r.likes, shares: r.shares, comments: Math.max(4, r.comments), views: r.views };
        post.postedMinute = minute;
        post.views = r.views;
        post.comments = socialComments(post, Math.max(4, Math.min(14, r.comments)), commentContext(state, false, `${minute}|tour`), new Date().toISOString());
        const when = commentMinutes(minute, post.comments.length, hashString(post.id) >>> 0);
        post.comments.forEach((c, i) => { c.minute = when[i]; });
        state.socialPosts.unshift(post);
        stats.clip.followers += Math.round(r.follows * (0.6 + def.image * 0.2));
        stats.clip.lastPostSerial = dateToSerial(state.gameDate);
        if (def.image >= 4) addMomentum(state, 2, 'the house tour');
        result = { ok: true, message: `Posted. ${r.views.toLocaleString()} views on the way.` };
      });
      return result;
    },

    buyLuxuryItem: (itemId) =>
      set((state) => {
        if (!state.player) return;
        const item = LUXURY_CATALOG.find(i => i.id === itemId);
        if (!item) return;
        if (state.player.career.money < item.cost) return;
        if (state.ownedAssets.find(a => a.id === itemId)) return;

        state.player.career.money -= item.cost;
        state.ownedAssets.push({ ...item, purchaseDate: formatGameDate(state.gameDate) });

        if (item.disciplineBonus) {
          state.player.stats.discipline = Math.min(100, state.player.stats.discipline + item.disciplineBonus);
        }

        const post: SocialPost = {
          id: uuidv4(),
          platform: 'snapgram',
          authorId: 'player',
          authorName: state.player.artistName,
          content: `Just picked up the ${item.name} 🤑 Hard work pays off. ${item.category === 'car' ? '🏎️' : item.category === 'home' ? '🏠' : item.category === 'jewelry' ? '💎' : '✨'}`,
          likes: Math.floor(state.player.career.fanbase * 0.05) + 100,
          shares: Math.floor(Math.random() * 50),
          comments: [],
          timestamp: new Date().toISOString(),
          isPlayerPost: true,
          trendingScore: 30,
        };
        state.socialPosts.unshift(post);
      }),

    // ─── MAILBOX ────────────────────────────────────────────────────────
    deleteMail: (mailId) =>
      set((state) => {
        state.mailbox = state.mailbox.filter((m) => m.id !== mailId);
      }),

    markAllMailRead: () =>
      set((state) => {
        for (const m of state.mailbox) m.read = true;
      }),

    readMail: (mailId) =>
      set((state) => {
        const mail = state.mailbox.find(m => m.id === mailId);
        if (mail) mail.read = true;
      }),

    acceptOffer: (mailId, kind) => {
      const before = get();
      if (!before.player) return { ok: false, message: 'There is nobody to sign anything.' };

      const mail = before.mailbox.find((m) => m.id === mailId);
      if (!mail || !mail.offerData) {
        return { ok: false, message: 'That offer is no longer on the table.' };
      }

      const offer = mail.offerData as ActiveContract['terms'];

      // ── Management is exclusive ────────────────────────────────────────
      // One manager at a time is the whole point of the deal. A manager with
      // no exclusivity cannot promise anybody anything, and the player cannot
      // tell which of two people is doing the work. Taking a new one means
      // firing the old one first — that is what the Team screen is for.
      if (offer.type === 'management') {
        const current = before.contracts.find((c) => c.type === 'management' && c.active);
        if (current) {
          return {
            ok: false,
            message: `${current.npcName} already manages you. Fire them first — nobody works a roster they are not on.`,
          };
        }
      }

      // ── Which structure did the player choose? ─────────────────────────
      const feeKind: ManagementFeeKind =
        kind ?? offer.feeKind ?? (offer.monthlyFee && !offer.percentage ? 'retainer' : 'commission');

      const terms: ActiveContract['terms'] = { ...offer };
      if (offer.type === 'management') {
        terms.feeKind = feeKind;
        if (feeKind === 'retainer') {
          terms.percentage = 0;
          terms.monthlyFee = offer.monthlyFee ?? 0;
        } else {
          terms.monthlyFee = 0;
          terms.percentage = offer.percentage;
        }
      }

      set((state) => {
        if (!state.player) return;

        const m = state.mailbox.find((x) => x.id === mailId);
        if (m) m.read = true;

        if (mail.type === 'contract' || mail.type === 'offer') {
          const newContract: ActiveContract = {
            id: uuidv4(),
            type: terms.type,
            npcId: mail.from,
            npcName: mail.fromName,
            terms,
            signedAt: formatGameDate(state.gameDate),
            expiresAt: `${state.gameDate.year + (terms.lengthYears ?? 2)}`,
            active: true,
          };
          state.contracts.push(newContract);

          if (terms.advance && terms.advance > 0) {
            state.player.career.money += terms.advance;
          }

          const npc = state.npcs.find((n) => n.id === mail.from);
          if (npc) npc.relationshipScore = Math.min(100, npc.relationshipScore + 10);

          // The offer has been answered — it stops being a pending decision.
          state.mailbox = state.mailbox.filter((x) => x.id !== mailId);
        }
      });

      if (terms.type === 'management') {
        return {
          ok: true,
          message:
            feeKind === 'retainer'
              ? `${mail.fromName} is your manager — $${(terms.monthlyFee ?? 0).toLocaleString()} a month, nothing off your income.`
              : `${mail.fromName} is your manager — ${terms.percentage}% of gross for ${terms.lengthYears ?? 2} years.`,
        };
      }
      return { ok: true, message: `Signed with ${mail.fromName}.` };
    },

    declineOffer: (mailId) =>
      set((state) => {
        const mail = state.mailbox.find(m => m.id === mailId);
        if (!mail) return;
        mail.read = true;
        // Dropping an offer can cost a little goodwill with the sender.
        const npc = state.npcs.find(n => n.id === mail.from);
        if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 5);
        state.mailbox = state.mailbox.filter(m => m.id !== mailId);
      }),

    /**
     * Push back on the terms.
     *
     * Deliberately a trade rather than a discount. Each round the other side
     * moves on the number the player cares about and takes something back on a
     * different axis — the commission comes down but the term goes up, or the
     * retainer comes down but the minimum months go up. A relationship makes
     * the trade better; pushing a hostile counterparty just ends the call.
     */
    negotiateOffer: (mailId) => {
      const before = get();
      if (!before.player) return { ok: false, message: 'There is nobody to negotiate.' };

      const mail = before.mailbox.find((m) => m.id === mailId);
      if (!mail || !mail.offerData) return { ok: false, message: 'That offer is gone.' };

      const offer = mail.offerData as ActiveContract['terms'];
      const rounds = mail.negotiationRounds ?? 0;
      const npc = before.npcs.find((n) => n.id === mail.from);
      const warmth = npc?.relationshipScore ?? 0;

      if (rounds >= 3) {
        return {
          ok: false,
          message: `${mail.fromName} has already moved twice. The number on the table is the number. Sign it or leave it.`,
        };
      }

      // A cold counterparty does not want to be haggled with.
      if (rounds === 0 && warmth < -20) {
        return {
          ok: false,
          message: `${mail.fromName} is not in the mood to be negotiated with. Fix the relationship before you start asking for better terms.`,
        };
      }

      const leverage = Math.max(0, Math.min(1, (warmth + 40) / 120)); // 0 … 1
      // The first round is generous, later ones less so. That is the whole
      // reason not to spam the button.
      const give = 1 - rounds * 0.28;

      const newTerms: ActiveContract['terms'] = { ...offer };
      let change = '';

      if (offer.type === 'management') {
        const pctCut = Math.max(1, Math.round((1 + leverage * 3) * give));
        const newPct = Math.max(5, (offer.percentage ?? 15) - pctCut);
        const feeCut = Math.round((((offer.monthlyFee ?? 1000) * (0.06 + leverage * 0.12)) * give) / 50) * 50;
        const newFee = Math.max(150, (offer.monthlyFee ?? 1000) - feeCut);

        newTerms.percentage = newPct;
        newTerms.monthlyFee = newFee;
        newTerms.lengthYears = Math.min(5, (offer.lengthYears ?? 2) + (rounds === 0 ? 0 : 1));
        newTerms.minMonths = (offer.minMonths ?? 12) + (rounds === 0 ? 0 : 6);

        change =
          `${newPct}% of gross, or $${newFee.toLocaleString()} a month` +
          (rounds === 0 ? '' : ` — and the term is now ${newTerms.lengthYears} years.`);
      } else if (offer.type === 'label') {
        const adv = Math.round((offer.advance * (0.08 + leverage * 0.17) * give) / 500) * 500;
        const roy = Math.min(30, (offer.royaltyRate ?? 15) + Math.max(1, Math.round(1 + leverage * 2)));
        newTerms.advance = offer.advance + adv;
        newTerms.royaltyRate = roy;
        newTerms.percentage = 100 - roy;
        newTerms.albumRequirements = (offer.albumRequirements ?? 1) + (rounds === 0 ? 0 : 1);
        change = `$${newTerms.advance.toLocaleString()} advance and ${roy}% royalty`;
      } else {
        return { ok: false, message: 'There is nothing to negotiate on that one.' };
      }

      set((state) => {
        const m = state.mailbox.find((x) => x.id === mailId);
        if (!m || !m.offerData) return;
        m.offerData = newTerms;
        m.negotiationRounds = rounds + 1;
        m.renegotiated = true;
        m.body =
          `You came back to me. Fine — I have moved.\n\n` +
          `New terms: ${change}\n\n` +
          (rounds === 0
            ? `This is a real concession. I do not do this often.`
            : `That is as far as I go. The rest is up to you.`) +
          `\n\n— ${mail.fromName}`;
        const n = state.npcs.find((x) => x.id === mail.from);
        // Haggling wears on people, however well it goes.
        if (n) n.relationshipScore = Math.max(-100, n.relationshipScore - 2);
      });

      return { ok: true, message: `${mail.fromName} came back with ${change}` };
    },

    // ─── THE TEAM ────────────────────────────────────────────────────────
    hireCrew: (npcId) => {
      const state = get();
      if (!state.player) return { ok: false, message: 'There is nobody to hire for.' };

      const npc = state.npcs.find((n) => n.id === npcId);
      if (!npc) return { ok: false, message: 'That person is not in your world.' };

      const check = hireCheck(npc, state.crew ?? [], state.player.career.money);
      if (!check.ok) return check;

      const wage = crewWage(npc, npc.role);
      const upfront = hireUpfrontCost(npc, npc.role);
      const skill = npc.role === 'producer' || npc.role === 'engineer' ? Math.max(npcSkill(npc), producerSkillOf(npc as NPC)) : npcSkill(npc);
      const serial = dateToSerial(state.gameDate);
      // Their characteristics, frozen onto the record. Deterministic from the
      // id, so this is a cache the tick can fold without the whole roster.
      const traits = traitsFor(npc);

      set((s) => {
        if (!s.player) return;
        s.player.career.money -= upfront;
        const member: CrewMember = {
          id: uuidv4(),
          npcId: npc.id,
          npcName: npc.name,
          role: npc.role,
          monthlyWage: wage,
          hiredAt: formatGameDate(s.gameDate),
          hiredSerial: serial,
          skill,
          visible: traits.visible,
          hidden: traits.hidden,
          // Tenure and morale both start neutral. `chemistryOf` reads the first
          // and `moraleFactor` the second, and neither means anything on day
          // one — a writer you met this morning does not know your voice yet.
          monthsServed: 0,
          morale: 70,
        };
        s.crew.push(member);
        pushTeamLines(s as GameState, [{ from: npc.id, name: npc.name, role: npc.role, text: pick3([`Glad to be on the team, ${(s.player?.artistName ?? 'boss').split(' ')[0]}. Let's work 🙏🏾`, 'Happy to be here. Tell me what you need first.', `Thanks for the opportunity. I'll post updates here.`], npc.id) }], dateToSerial(s.gameDate));
        const n = s.npcs.find((x) => x.id === npc.id);
        if (n) {
          n.relationshipScore = Math.min(100, n.relationshipScore + 6);
          n.memoryLog = [...n.memoryLog.slice(-9), `Hired onto the payroll as ${roleSpec(npc.role).title.toLowerCase()} (${formatGameDate(s.gameDate)}).`];
        }
        s.lastEventLog.unshift(`🤝 ${npc.name} joined the team as your ${roleSpec(npc.role).title.toLowerCase()}.`);
        s.lastEventLog = s.lastEventLog.slice(0, 10);
      });

      return {
        ok: true,
        message: `${npc.name} is on the payroll at $${wage.toLocaleString()} a month. Two months up front came to $${upfront.toLocaleString()}.`,
      };
    },

    fireCrew: (crewId) => {
      const state = get();
      const member = (state.crew ?? []).find((c) => c.id === crewId);
      if (!member) return { ok: false, message: 'They are not on your payroll.' };
      if (!state.player) return { ok: false, message: 'There is nobody to fire anyone.' };

      const severance = severanceFor(member);

      set((s) => {
        if (!s.player) return;
        s.player.career.money -= severance;
        s.crew = s.crew.filter((c) => c.id !== crewId);
        const n = s.npcs.find((x) => x.id === member.npcId);
        if (n) {
          n.relationshipScore = Math.max(-100, n.relationshipScore - 18);
          n.memoryLog = [...n.memoryLog.slice(-9), `Let go from the payroll (${formatGameDate(s.gameDate)}).`];
        }
        s.lastEventLog.unshift(`👋 ${member.npcName} is off the payroll. Severance: $${severance.toLocaleString()}.`);
        s.lastEventLog = s.lastEventLog.slice(0, 10);
        // The rest of the team watches how you let people go.
        const dead = (member.strikes ?? 0) >= 1 || member.lastReview?.grade === 'D' || member.lastReview?.grade === 'F';
        const star = member.lastReview?.grade === 'A';
        for (const c of s.crew) c.morale = Math.max(0, Math.min(100, (c.morale ?? 70) + (dead ? 3 : star ? -5 : -1)));
        const mgr = managerOf(s as GameState);
        const voice = mgr ? { from: mgr.id, name: mgr.name, role: 'manager' } : s.crew[0] ? { from: s.crew[0].npcId, name: s.crew[0].npcName, role: s.crew[0].role } : null;
        if (voice) pushTeamLines(s as GameState, [{ ...voice, text: dead ? `${member.npcName.split(' ')[0]} is off the team. It needed to happen.` : star ? `${member.npcName.split(' ')[0]} is gone? They were carrying us. Hope you know what you're doing.` : `${member.npcName.split(' ')[0]} is off the team. We move.` }], dateToSerial(s.gameDate));
      });

      return {
        ok: true,
        message: `${member.npcName} is off the payroll. One month's severance — $${severance.toLocaleString()} — and they are not happy about it.`,
      };
    },

    warnCrew: (crewId) => {
      let result: TeamActionResult = { ok: false, message: 'They are not on your team.' };
      set((state) => {
        const c = state.crew.find((x) => x.id === crewId);
        if (!c || !state.player) return;
        const serial = dateToSerial(state.gameDate);
        const n = c.npcName.split(' ')[0];
        if (c.warnedSerial !== undefined && serial - c.warnedSerial < 14) { result = { ok: false, message: `You talked to ${n} about it ${serial - c.warnedSerial} day${serial - c.warnedSerial === 1 ? '' : 's'} ago. Give it time to show.` }; return; }
        const o = warnOutcome(workStyleOf(c), c.lastReview?.grade, Math.random(), c.npcName);
        pushDM(state, c.npcId, { fromPlayer: true, content: pickLine(['We need to talk about your work. I need more from you.', 'Real talk — you\'re not pulling your weight. Pick it up.', 'I\'m not happy with how the last few weeks went. Lock in.'], `${c.id}|${serial}`) });
        pushDM(state, c.npcId, { fromPlayer: false, system: true, content: o.text });
        if (o.quit) {
          applyMomentEffects(state, [{ k: 'quit', crewId: c.id }], serial);
          const npc = state.npcs.find((x) => x.id === c.npcId);
          if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 15);
          pushTeamLines(state, [{ from: c.npcId, name: c.npcName, role: c.role, text: pickLine(['I\'m done. Good luck.', 'Nobody talks to me like that. I\'m out.'], c.id) }], serial);
          result = { ok: true, message: o.text };
          return;
        }
        c.morale = Math.max(0, Math.min(100, (c.morale ?? 70) + o.morale));
        if (o.warned) c.warnedSerial = serial;
        result = { ok: true, message: o.text };
      });
      return result;
    },

    praiseCrew: (crewId) => {
      let result: TeamActionResult = { ok: false, message: 'They are not on your team.' };
      set((state) => {
        const c = state.crew.find((x) => x.id === crewId);
        if (!c || !state.player) return;
        const serial = dateToSerial(state.gameDate);
        const n = c.npcName.split(' ')[0];
        if (c.praisedSerial !== undefined && serial - c.praisedSerial < 14) { result = { ok: false, message: `You already told ${n} ${serial - c.praisedSerial === 0 ? 'today' : `${serial - c.praisedSerial} days ago`}. Too much and it stops meaning anything.` }; return; }
        const o = praiseOutcome(workStyleOf(c), c.npcName);
        c.morale = Math.max(0, Math.min(100, (c.morale ?? 70) + o.morale));
        c.praisedSerial = serial;
        if (workStyleOf(c) === 'coaster') c.warnedSerial = undefined;
        pushDM(state, c.npcId, { fromPlayer: true, content: pickLine(['Just want to say — you\'ve been killing it. Appreciate you.', 'Great work this month. I see it.', 'You\'re a big part of this. Thank you.'], `${c.id}|${serial}|p`) });
        pushDM(state, c.npcId, { fromPlayer: false, system: true, content: o.text });
        result = { ok: true, message: o.text };
      });
      return result;
    },

    fireManager: () => {
      const state = get();
      const contract = state.contracts.find((c) => c.type === 'management' && c.active);
      if (!contract) return { ok: false, message: 'Nobody manages you right now.' };
      if (!state.player) return { ok: false, message: 'There is nobody to fire anyone.' };

      const months = Math.max(
        1,
        Math.round(
          (dateToSerial(state.gameDate) -
            dateToSerial(parseGameDate(contract.signedAt) ?? state.gameDate)) /
            30,
        ),
      );
      const minMonths = contract.terms.minMonths ?? 0;
      // Walking before the minimum term is a real cost, and the game says so
      // rather than quietly letting it slide.
      const penalty =
        months < minMonths
          ? Math.round(state.player.career.totalEarnings * 0.02 / 100) * 100
          : 0;

      set((s) => {
        if (!s.player) return;
        s.player.career.money -= penalty;
        const c = s.contracts.find((x) => x.id === contract.id);
        if (c) c.active = false;
        const n = s.npcs.find((x) => x.id === contract.npcId);
        if (n) {
          n.relationshipScore = Math.max(-100, n.relationshipScore - 30);
          n.memoryLog = [...n.memoryLog.slice(-9), `Fired as manager after ${months} month${months === 1 ? '' : 's'} (${formatGameDate(s.gameDate)}).`];
        }
        s.lastEventLog.unshift(`📤 You let ${contract.npcName} go as your manager.`);
        s.lastEventLog = s.lastEventLog.slice(0, 10);
      });

      return {
        ok: true,
        message:
          penalty > 0
            ? `${contract.npcName} is out. You were inside the ${minMonths}-month minimum, so the buy-out cost $${penalty.toLocaleString()}.`
            : `${contract.npcName} is out. You are representing yourself again — which means the phone only rings when you make it ring.`,
      };
    },

    // ─── INTERVIEWS ─────────────────────────────────────────────────────
    startInterview: (stationId) =>
      set((state) => {
        const interview: Interview = {
          id: uuidv4(),
          stationId,
          date: formatGameDate(state.gameDate),
          qa: [],
          headline: '',
          completed: false,
          fameGained: 0,
          reputationChange: 0,
        };
        state.interviews.push(interview);
      }),

    answerQuestion: (interviewId, questionIdx, tone) =>
      set((state) => {
        const interview = state.interviews.find(i => i.id === interviewId);
        if (!interview || interview.qa[questionIdx]) return;

        // Tone effects (rule-based)
        const toneEffects: Record<InterviewTone, { fame: number; rep: number; street: number }> = {
          diplomatic: { fame: 2, rep: 3, street: 0 },
          dismissive: { fame: -1, rep: -2, street: 2 },
          aggressive: { fame: 3, rep: -3, street: 5 },
          humorous: { fame: 4, rep: 1, street: 1 },
          honest: { fame: 2, rep: 2, street: 1 },
        };

        const effect = toneEffects[tone];
        interview.fameGained += effect.fame;
        interview.reputationChange += effect.rep;
      }),

    completeInterview: (interviewId) =>
      set((state) => {
        if (!state.player) return;
        const interview = state.interviews.find(i => i.id === interviewId);
        if (!interview || interview.completed) return;
        // Sitting for an interview is a press day.
        if (!spendEnergy(state, ENERGY_COSTS.interview, { admin: true })) return;

        interview.completed = true;
        interview.headline = `${state.player.artistName} Opens Up in New Interview`;

        state.player.career.localFame = Math.min(100, state.player.career.localFame + interview.fameGained);
        // A bad interview is the classic thing a publicist is paid to survive.
        // What they cannot do is make a good one land harder.
        state.player.career.reputation = Math.min(
          100,
          state.player.career.reputation + (
            interview.reputationChange < 0
              ? interview.reputationChange * crewBonuses(raw(state.crew) as CrewMember[]).controversyMult
              : interview.reputationChange
          ),
        );
        state.player.stats.charisma = Math.min(100, state.player.stats.charisma + 0.5);
        state.player.stats.networking = Math.min(100, state.player.stats.networking + 0.3);

        // A press day puts your name in front of people who were not looking.
        addMomentum(state, 2);

        // Post headline
        const post: SocialPost = {
          id: uuidv4(),
          platform: 'chirp',
          authorId: 'blog_kojo',
          authorName: 'Kojo Writes',
          content: `📰 JUST OUT: ${interview.headline} Read it here → [link]`,
          likes: Math.floor(Math.random() * 200) + 50,
          shares: Math.floor(Math.random() * 50),
          comments: [],
          timestamp: new Date().toISOString(),
          isPlayerPost: false,
          trendingScore: 40,
        };
        state.socialPosts.unshift(post);

        state.headlines.unshift({
          id: uuidv4(),
          text: interview.headline,
          fullStory: `${state.player.artistName} sat down for a candid interview. ${interview.reputationChange >= 0 ? 'Came across well.' : 'Some comments are raising eyebrows.'}`,
          date: formatGameDate(state.gameDate),
          relatedEntities: [state.player.id],
          priority: 5,
          category: 'general',
        });
      }),

    // ─── TURN ADVANCEMENT ───────────────────────────────────────────────
    advanceTurn: (unit, opts) => {
      // A deferred half of the previous day goes first, so the world never
      // runs out of order.
      flushSideTicks();
      set((state) => {
        if (!state.player) return;

        const days = unit === 'day' ? 1 : unit === 'week' ? 7 : 30;
        // The clock's own midnight: the world's chatter (awards, moments, the
        // feed, interviews, the team group) runs a beat later, in its own
        // frame, so the day change itself stays short. See `runSideTicks`.
        const deferSide = unit === 'day' && !!opts?.silent && typeof window !== 'undefined';
        // Read before anything moves, so the report can state the balance
        // either side of the turn rather than reconstructing it.
        const fromDate = formatGameDate(state.gameDate);
        const moneyBefore = state.player.career.money;
        const energyBefore = state.player.energy;
        // Every money write in this tick is recorded against a name, and the
        // report is drained at the bottom. The ledger is opened here rather
        // than inside a branch so a turn that moves no money still closes it.
        openTurnLedger();
        state.gameDate = advanceDate(state.gameDate, days) as typeof state.gameDate;
        state.turnCount += 1;

        // ─── WHAT KIND OF DAY IS IT ───────────────────────────────────
        // The clock hands the tick one day at a time, so "+1 Month" is not the
        // only way a month passes. The calendar decides: a Monday closes the
        // week (statements, momentum, weekly coaching, the scene's albums and
        // videos), and the 1st of the month is payday (wages, retainers, the
        // manager's monthly work). Before this, a career played on the clock
        // never paid its team and its manager never did a month's work.
        const calTo = dateToSerial(state.gameDate);
        let weeksCrossed = 0;
        let monthsCrossed = 0;
        for (let d = calTo - days + 1; d <= calTo; d++) {
          if (serialWeekday(d) === 1) weeksCrossed++;
          if (serialToDate(d).day === 1) monthsCrossed++;
        }
        const isWeek = unit !== 'day' || weeksCrossed > 0;
        const isMonth = unit === 'month' || monthsCrossed > 0;

        // Plain, non-draft views for the read-heavy parts of the tick. Scanning
        // the roster through the immer proxy costs ~7x more (see `raw()`), and
        // this tick scans it in a dozen places.
        const rawNPCs = raw(state.npcs) as NPC[];
        const rawNPCSongs = raw(state.npcSongs) as Song[];
        const rawSongs = raw(state.songs) as Song[];

        // Who manages the player, resolved once. Two different parts of the tick
        // need it — the fanbase conversion rate and the offer engine — and
        // looking it up twice is how the two halves drift apart.
        const currentManager = activeManager(
          raw(state.contracts) as ActiveContract[],
          rawNPCs,
        );

        // ─── THE CREW ─────────────────────────────────────────────────
        // Folded ONCE, at the top, before anything reads it. Everything the
        // payroll does for the player lands in this one object, so a hire can
        // never be half-applied — and the energy line further down needs it,
        // which is why it moved up here from beside the payroll block.
        const crew = crewBonuses(raw(state.crew) as CrewMember[]);

        // The energy ceiling is DERIVED, not accumulated. A trainer raises it
        // while they are on the payroll and it falls back the moment they
        // leave; adding to `maxEnergy` in place would ratchet it upwards for
        // ever and fire the trainer twice.
        //
        // Rounded, because a fractional ceiling is a number the player will
        // eventually read off a bar and it should be a whole point of energy.
        // Where you sleep is how well you sleep.
        const ceiling = Math.round(MAX_ENERGY + crew.maxEnergyBonus + homeDef(state.home?.tier).energy);
        if (state.player.maxEnergy !== ceiling) {
          state.player.maxEnergy = ceiling;
          state.player.energy = Math.min(state.player.energy, ceiling);
        }

        // ─── STREAMING, DAY BY DAY ────────────────────────────────────────
        // The clock jumps 1, 7 or 30 days in one go, but streams are earned one
        // day at a time. This walks every day the cursor has not seen yet, so a
        // skipped month processes all thirty days and no day is ever counted
        // twice — the cursor only moves forward, to the day just reached.
        const targetSerial = dateToSerial(state.gameDate);
        const fromSerial = (state.streamCursor ?? targetSerial - days) + 1;

        // ── OFF THE DRAFT ─────────────────────────────────────────────
        // Both engines push and shift a day array per platform per song, and
        // per video. Through immer's proxy each of those writes costs an order
        // of magnitude more than a plain array write, and the bill is paid
        // every single game day: measured at ~330ms per day, against ~1ms once
        // the same work runs on plain objects.
        //
        // So the streaming state is copied out, the engines run on the copy,
        // and the result goes back in one write. Nothing outside this block
        // ever sees the plain version.
        const plainStats = clonePlain<Record<string, SongPlatformState>>(
          raw(state.platformStats) ?? {},
        );
        const plainVideos = clonePlain<Video[]>(raw(state.videos) ?? []);

        const streamRun = advanceStreamingDays(
          state,
          fromSerial,
          targetSerial,
          rawNPCs,
          plainStats,
          plainVideos,
        );

        state.platformStats = plainStats;
        state.videos = plainVideos as typeof state.videos;
        state.streamCursor = targetSerial;

        // NOTE: the engine computes the revenue here, but it is NOT banked here.
        // The credit happens once, further down, where the crew's payout
        // multiplier is known — otherwise a distribution deal could never lift
        // the money, and crediting in both places paid every stream twice.
        // `streamRun.revenue` is read-only from this point on.

        // Video views are produced by the same loop. Write them back onto the
        // song records the rest of the game reads, so a record's video views
        // and its video's views are never two different numbers.
        for (const song of state.songs) {
          const views = streamRun.viewsBySong[song.id];
          if (views !== undefined) song.videoViews = (song.videoViews ?? 0) + views;
        }
        for (const song of state.npcSongs) {
          const views = streamRun.viewsBySong[song.id];
          if (views !== undefined) song.videoViews = (song.videoViews ?? 0) + views;
        }
        let totalWeeklyStreams = 0;

        // Update player age
        state.player.age = calculateAge(state.player.dateOfBirth, state.gameDate);

        // ─── ENERGY ──────────────────────────────────────────────────────
        // Letting the clock run is the price of doing anything that costs
        // effort. This is what kills the "tour every day forever" exploit: a
        // tour is 52 of your 100, so a second one needs a night off.
        //
        // Recovery is computed from the time the turn was actually worth, by
        // the same rule a rest uses (three hours is a full night). A day, a
        // week and a month all exceed that and so still leave you fresh — but
        // the rule is now one rule, and a turn shorter than a night would no
        // longer be an unconditional reset.
        //
        // Nothing on the payroll scales this, and that is not an oversight. A
        // turn of a day or more is ALREADY a full refill, so a multiplier here
        // would be applied to a number that is always the ceiling and would do
        // precisely nothing — a mechanic that reads as working and is not. The
        // assistant's energy effect lives in `spendEnergy` and `rest`, which
        // are the two places energy actually moves.
        state.player.energy = elapsedRecovery(days, state.player.energy, state.player.maxEnergy);

        const log: string[] = [];
        /**
         * The tour dates played during this turn, kept apart from `log`.
         *
         * They are earned FIRST (the run settles before the tax and the payroll
         * are worked out) but they are the last thing the player should be able
         * to miss. Pushed into `log` with everything else, a busy month simply
         * cuts them: `log.slice(-10)` keeps the newest ten, and a tour date is
         * the oldest thing in the turn. A night the player played that never
         * appears in the feed is a night they never saw happen.
         */
        const tourLines: string[] = [];

        // ─── TOUR DATES ──────────────────────────────────────────────────
        // A booked run plays itself as the clock reaches each night.
        //
        // Two things here are load-bearing. First, every due leg is settled in
        // date order, and dated to its OWN night — a month-long jump has to
        // play all of them, and a city's fatigue has to be measured against the
        // night it was caused on, not the night the jump happened to land.
        // Second, each leg goes through `applyShowOutcome`, the very same
        // settlement a one-off uses, so a tour can never pay differently from a
        // show on the same night.
        if (state.tours.length) {
          const due: { tour: Tour; leg: TourLeg }[] = [];
          for (const t of state.tours) {
            if (t.status === 'cancelled' || t.status === 'done') continue;
            for (const leg of t.legs) {
              if (leg.playedSerial === undefined && leg.serial <= targetSerial) {
                due.push({ tour: t, leg });
              }
            }
          }
          due.sort((a, b) => a.leg.serial - b.leg.serial);

          for (const { tour, leg } of due) {
            const venue = findVenue(leg.venueId);
            // A room that no longer resolves cannot be played. Mark it so the
            // run still finishes instead of blocking on it for ever.
            if (!venue) {
              leg.playedSerial = leg.serial;
              continue;
            }

            const input = showInputFrom(state, venue, leg.price, leg.serial);
            const roll = 0.82 + Math.random() * 0.36;
            const night = settleShow({ ...input, promo: input.promo * tour.buzz }, roll);

            // Rested: the nights between dates are what pays for a tour, and a
            // turn of a day or more is already a full recovery.
            const quality = performanceScore({
              stagePresence: state.player.stats.stagePresence,
              performance: state.player.stats.performance,
              charisma: state.player.stats.charisma,
              consistency: state.player.stats.consistency,
              stageBonus: crew.stageBonus,
              energyRatio: 1,
              fill: night.fill,
            });

            const settled = applyShowOutcome(state, {
              venue,
              type: leg.type,
              price: leg.price,
              night,
              performanceQuality: quality,
              energy: 0,
              nowSerial: leg.serial,
              controversyMult: crew.controversyMult,
              advanceCalendar: false,
              tourId: tour.id,
              logSink: tourLines,
            });

            leg.playedSerial = leg.serial;
            leg.net = night.net;
            leg.tickets = settled.attendance;

            // You are where the last date was. A tour moves the artist, which
            // is the whole reason the nights either side of it are spoken for.
            state.player.city = leg.city;
            state.player.country = leg.country;
          }

          for (const t of state.tours) {
            if (t.status === 'cancelled') continue;
            const played = t.legs.filter((l) => l.playedSerial !== undefined).length;
            if (played === 0) t.status = 'booked';
            else if (played < t.legs.length) t.status = 'running';
            else t.status = 'done';
          }
        }
        // ─── SCHEDULED SHOWS ─────────────────────────────────────────────
        // Announced shows sell DAY BY DAY and play on their night.
        //
        // Sales are brought up to the earlier of today and the show's date,
        // one day at a time, so a thirty-day jump sells thirty days of
        // tickets and never skips the presale spike. Messages are sent for
        // where the show ends up, not for every day it passed through — a
        // month turn must not drop four stale reminders into the inbox.
        if (state.scheduledShows.length) {
          for (const show of state.scheduledShows) {
            const venue = findVenue(show.venueId);
            if (!venue) continue;
            const until = Math.min(targetSerial, show.serial);
            if (show.salesCursor >= until) continue;

            const target = liveShowTarget(state, show, venue);
            for (let d = show.salesCursor + 1; d <= until; d++) {
              show.ticketsSold = soldBy(
                { announcedSerial: show.announcedSerial, serial: show.serial, ticketsSold: show.ticketsSold, capacity: show.capacity },
                d,
                target,
              );
              show.sales.push({ serial: d, sold: show.ticketsSold });
            }
            if (show.sales.length > 70) show.sales = show.sales.slice(-70);
            show.salesCursor = until;

            const daysOut = show.serial - targetSerial;
            if (daysOut <= 0) continue; // the night itself is reported on settlement

            const fill = show.ticketsSold / Math.max(1, show.capacity);
            const pct = Math.floor(fill * 100);
            const where = `${venue.name}`;

            if (show.ticketsSold >= show.capacity && show.status !== 'sold_out') {
              show.status = 'sold_out';
              show.milestone = 100;
              show.notes.unshift('SOLD OUT.');
              tourLines.push(`🔥 ${where} is SOLD OUT — ${show.capacity.toLocaleString()} tickets gone, ${daysOut} days to spare.`);
              state.mailbox.unshift({
                id: uuidv4(), from: 'booking_desk', fromName: 'Booking desk',
                subject: `🔥 SOLD OUT: ${where}, ${show.city}`,
                body: `Every one of ${show.capacity.toLocaleString()} tickets is gone with ${daysOut} days still to go. You could have filled a bigger room — remember that for the next announcement.`,
                timestamp: new Date().toISOString(), read: false, type: 'general',
              });
              const fan = state.npcs.find((n) => n.role === 'fan_account');
              if (fan) {
                state.socialPosts.unshift({
                  id: uuidv4(), platform: 'chirp', authorId: fan.id, authorName: fan.name,
                  content: `${show.city} is SOLD OUT!! ${state.player.artistName} said ${show.capacity.toLocaleString()} seats and we took them all. 🔥🔥`,
                  likes: Math.max(50, Math.round(show.capacity * 0.4)), shares: Math.round(show.capacity * 0.08),
                  comments: [], timestamp: new Date().toISOString(), isPlayerPost: false,
                  trendingScore: 60, daySerial: targetSerial,
                });
              }
              addMomentum(state, 3);
            } else if (show.status !== 'sold_out') {
              const crossed = [25, 50, 75].filter((m) => pct >= m && m > show.milestone);
              if (crossed.length) {
                const top = crossed[crossed.length - 1];
                show.milestone = top;
                show.notes.unshift(`${top}% sold (${show.ticketsSold.toLocaleString()}).`);
                tourLines.push(`🎟️ ${where}: ${show.ticketsSold.toLocaleString()} of ${show.capacity.toLocaleString()} sold (${pct}%). ${daysOut} days to go.`);
              }
            }

            // Reminders: the nearest threshold crossed, once.
            const rem = dueReminder(daysOut, show.remindersSent);
            if (rem !== null) {
              show.remindersSent = [...show.remindersSent, ...REMINDER_DAYS.filter((d) => d >= rem)];
              const mood = salesMood(
                { announcedSerial: show.announcedSerial, serial: show.serial, ticketsSold: show.ticketsSold, capacity: show.capacity },
                targetSerial,
                target,
              );
              tourLines.push(`⏰ ${where} in ${daysOut} day${daysOut === 1 ? '' : 's'} — ${show.ticketsSold.toLocaleString()}/${show.capacity.toLocaleString()} sold.`);
              state.mailbox.unshift({
                id: uuidv4(), from: 'booking_desk', fromName: 'Booking desk',
                subject: `⏰ ${daysOut} day${daysOut === 1 ? '' : 's'} to ${where} — ${pct}% sold`,
                body:
                  `${reminderTone(daysOut)}\n\n${show.ticketsSold.toLocaleString()} of ${show.capacity.toLocaleString()} tickets sold at $${show.price} (${MOOD_LABEL[mood].toLowerCase()}).` +
                  (mood === 'slow' || mood === 'at_risk'
                    ? `\n\nSales are behind where they should be. Cut the price, add promotion, move the date, or cancel while it is still cheap.`
                    : ''),
                timestamp: new Date().toISOString(), read: false, type: 'general',
              });
            } else if (
              show.status !== 'sold_out' &&
              (show.lastWarnSerial === undefined || targetSerial - show.lastWarnSerial >= 7)
            ) {
              const mood = salesMood(
                { announcedSerial: show.announcedSerial, serial: show.serial, ticketsSold: show.ticketsSold, capacity: show.capacity },
                targetSerial,
                target,
              );
              if (mood === 'at_risk') {
                show.lastWarnSerial = targetSerial;
                show.notes.unshift(`Warning: only ${pct}% sold with ${daysOut} days left.`);
                tourLines.push(`⚠️ ${where}: only ${pct}% sold with ${daysOut} days left. Act now.`);
                state.mailbox.unshift({
                  id: uuidv4(), from: 'booking_desk', fromName: 'Booking desk',
                  subject: `⚠️ ${where} is struggling — ${pct}% sold`,
                  body: `With ${daysOut} days left only ${show.ticketsSold.toLocaleString()} of ${show.capacity.toLocaleString()} tickets have gone. Open Shows → Upcoming to cut the price, buy promotion, postpone or cancel. The earlier you decide, the less it costs.`,
                  timestamp: new Date().toISOString(), read: false, type: 'general',
                });
              }
            }
          }

          // ── Play every night the clock has reached, in date order ─────
          const tonight = state.scheduledShows
            .filter((s) => s.serial <= targetSerial)
            .sort((a, b) => a.serial - b.serial);
          for (const show of tonight) {
            const venue = findVenue(show.venueId);
            state.scheduledShows = state.scheduledShows.filter((s) => s.id !== show.id);
            if (!venue) continue;

            const input = showInputFrom(state, venue, show.price, show.serial);
            const prepaid: ShowCostLine[] = show.marketingSpend > 0
              ? [{ key: 'promotion', label: 'Promotion (prepaid)', amount: show.marketingSpend }]
              : [];
            const night = settleSoldShow(input, show.ticketsSold, prepaid);
            const quality = performanceScore({
              stagePresence: state.player.stats.stagePresence,
              performance: state.player.stats.performance,
              charisma: state.player.stats.charisma,
              consistency: state.player.stats.consistency,
              stageBonus: crew.stageBonus,
              energyRatio: 1,
              fill: night.fill,
            });
            const balanceBefore = state.player.career.money;
            const settled = applyShowOutcome(state, {
              venue, type: show.type, price: show.price, night,
              performanceQuality: quality, energy: 0, nowSerial: show.serial,
              controversyMult: crew.controversyMult, advanceCalendar: false, logSink: tourLines,
            });
            // The deposit and promotion were paid weeks ago. The settlement
            // charged them as costs, so hand the cash back or they are paid twice.
            state.player.career.money += show.deposit + show.marketingSpend;
            // Your guests: paid on the night, if they turned up.
            const guestLines: string[] = [];
            for (const g of show.guests ?? []) {
              if (g.status !== 'confirmed') continue;
              const npc = state.npcs.find((n) => n.id === g.npcId);
              if (guestShowsUp(npc as NPC | undefined, Math.random())) {
                g.status = 'played';
                state.player.career.money -= g.fee;
                if (npc) npc.relationshipScore = Math.min(100, npc.relationshipScore + (quality >= 65 ? 6 : 3));
                guestLines.push(`${g.name} came out as your ${g.role === 'special_guest' ? 'special guest' : 'opener'} (${g.role === 'special_guest' ? 'the room lost it' : 'warmed them up'}) — paid $${g.fee.toLocaleString()}.`);
                if (g.role === 'special_guest') addMomentum(state, 2);
              } else {
                g.status = 'no_show';
                state.player.career.reputation = Math.max(0, state.player.career.reputation - 2);
                if (npc) npc.relationshipScore = Math.max(-100, npc.relationshipScore - 10);
                guestLines.push(`${g.name} never showed. The crowd booed when the screen said their name. You did not pay them.`);
              }
            }
            ledgerAdd('shows', state.player.career.money - balanceBefore);
            void settled;
            if (guestLines.length) tourLines.push(...guestLines.map((l) => `🎤 ${l}`));

            const fillPct = Math.round(night.fill * 100);
            state.mailbox.unshift({
              id: uuidv4(), from: 'booking_desk', fromName: 'Booking desk',
              subject: `🎤 Settlement: ${venue.name}, ${venue.city}`,
              body:
                `${night.tickets.toLocaleString()} of ${venue.capacity.toLocaleString()} came (${fillPct}%).\n` +
                `Door $${night.gross.toLocaleString()} + merch $${night.merch.toLocaleString()}.\n` +
                `Costs $${night.totalCosts.toLocaleString()}.\n` +
                `Net ${night.net >= 0 ? '+' : '−'}$${Math.abs(night.net).toLocaleString()}.\n\n` +
                `Reviewed ${quality}/100.${show.postponements ? ` (Postponed ${show.postponements}×.)` : ''}` +
                ((show.guests ?? []).length ? `\n\n${(show.guests ?? []).map((g) => `${g.name}: ${g.status === 'played' ? `played, $${g.fee.toLocaleString()}` : g.status.replace('_', ' ')}`).join('\n')}` : ''),
              timestamp: new Date().toISOString(), read: false, type: 'general',
            });
          }
        }

        // ─── SHOW OFFERS ─────────────────────────────────────────────────
        // Offers expire; new ones arrive; accepted dates are played.
        //
        // Offers are rare on purpose. A fee can never exceed what the room can
        // pay (`fairFee` is capacity-bounded), each host can only have one
        // offer open, and with no manager the stream is thinner and the
        // window shorter — some offers expire unseen, as the spec has it.
        {
          const hasManagerNow = !!currentManager || crew.promoterCut > 0 || playerNegotiatorSkill(state, 'manager') > 0;

          for (const o of state.showOffers) {
            if (o.status === 'open' && targetSerial > o.expiresSerial) {
              o.status = 'expired';
              closeBriefs(state, o.id, 'Expired — nobody answered.');
              const host = state.npcs.find((n) => n.id === o.hostId);
              // Leaving a friend on read is a small slight.
              if (host && o.hostRole === 'artist' && host.relationshipScore > 10) {
                host.relationshipScore -= 2;
              }
              tourLines.push(`⌛ The offer from ${o.hostName} (${o.city}) expired unanswered.`);
            }
          }
          // Keep a short history of answered offers, and every open one.
          const open = state.showOffers.filter((o) => o.status === 'open');
          const done = state.showOffers.filter((o) => o.status !== 'open').slice(-10);
          state.showOffers = [...open, ...done];

          const modeDef = MODES[state.legacy?.mode ?? 'active'];
          const fresh = rollShowOffers(state, rawNPCs, targetSerial, days, hasManagerNow, crew.promoterCut > 0, rawSongs).filter(() => reaches(state.legacy?.mode, 'shows', Math.random()));
          // Semi-retired: the dates you do play are rare, and priced like it.
          if (modeDef.showFee !== 1) for (const o of fresh) { o.terms.fee = Math.round(o.terms.fee * modeDef.showFee); o.fair = Math.round(o.fair * modeDef.showFee); o.ceiling = Math.round(o.ceiling * modeDef.showFee); }
          const mgrNow = managerOf(state, rawNPCs);
          const pol = policyOf(state.teamPolicy);
          for (const o of fresh) {
            state.showOffers.push(o);
            // With a manager it goes to their desk; they brief you — and the
            // rules you set are theirs to follow.
            if (mgrNow) {
              const why = showBreaksPolicy(pol, {
                fee: o.terms.fee,
                weekday: serialWeekday(o.serial),
                abroad: o.country !== state.player.country,
                sameContinent: getCountry(o.country)?.continent === getCountry(state.player.country)?.continent,
              });
              if (why) {
                o.status = 'declined';
                const b = fileBrief(state, { ...showBrief(state, o), advice: 'pass', reason: `I passed on this one for you. ${why}` });
                b.status = 'done';
                b.outcome = `Passed for you — ${why}`;
                tourLines.push(`📋 ${mgrNow.name} passed on ${o.venueName}, ${o.city}: ${why}`);
                continue;
              }
              const b = fileBrief(state, showBrief(state, o));
              if (pol.autoTake && b.advice === 'take') b.auto = true;
              tourLines.push(`📋 ${mgrNow.name} has a show offer for you: ${o.venueName}, ${o.city}.`);
              continue;
            }
            tourLines.push(`📩 New offer: ${o.hostName} — ${o.venueName}, ${o.city}. See Shows → Offers.`);
            // Without one, the host is in your DMs.
            if (state.npcs.some((n) => n.id === o.hostId) && !isBlocked(state, o.hostId)) {
              const thread = state.dmThreads[o.hostId] ?? { npcId: o.hostId, messages: [], unread: 0 };
              thread.messages.push({ id: uuidv4(), npcId: o.hostId, fromPlayer: false, content: `${isRealId(o.hostId) ? `📨 ${o.hostName}'s team: ` : 'Yo! '}${o.reason} ${o.venueName}, ${formatWeekEnding(serialToDate(o.serial))} — $${o.terms.fee.toLocaleString()}, ${BILLING_LABEL[o.terms.billing].toLowerCase()}. You in?`, timestamp: new Date().toISOString(), read: false });
              thread.messages.push({ id: uuidv4(), npcId: o.hostId, fromPlayer: false, system: true, content: '📩 The offer is in Shows → Offers — accept, counter or decline there.', timestamp: new Date().toISOString(), read: true });
              thread.unread += 1;
              state.dmThreads[o.hostId] = thread;
            }
            state.mailbox.unshift({
              id: uuidv4(), from: o.hostId, fromName: o.hostName,
              subject: `📩 ${o.hostRole === 'artist' ? 'Invitation' : 'Offer'}: ${o.venueName}, ${o.city} — ${formatGameDate(serialToDate(o.serial))}`,
              body:
                `${o.reason}\n\n${BILLING_LABEL[o.terms.billing]} · ${o.terms.slotMins} min · $${o.terms.fee.toLocaleString()} guaranteed.\n` +
                `Reply by ${formatGameDate(serialToDate(o.expiresSerial))}. Open Shows → Offers to negotiate, accept or decline.`,
              timestamp: new Date().toISOString(), read: false, type: 'general',
            });
          }

          // Reminders for accepted dates.
          for (const g of state.bookedGigs) {
            const rem = dueReminder(g.serial - targetSerial, g.reminded);
            if (rem !== null) {
              g.reminded = [...g.reminded, ...REMINDER_DAYS.filter((d) => d >= rem)];
              tourLines.push(`⏰ ${g.hostName}'s ${g.city} date is in ${g.serial - targetSerial} day${g.serial - targetSerial === 1 ? '' : 's'}.`);
            }
          }

          // Play the nights the clock has reached.
          const nights = state.bookedGigs.filter((g) => g.serial <= targetSerial).sort((a, b) => a.serial - b.serial);
          for (const gig of nights) {
            state.bookedGigs = state.bookedGigs.filter((g) => g.id !== gig.id);
            playBookedGig(state, gig, crew, tourLines);
          }
        }

        // World news goes here instead. The dashboard feed is ten lines long,
        // and on a month turn the scene alone generates a dozen of them — every
        // NPC release and every show. Pushed into the same array they crowded
        // out the player's own business entirely: the tax withholding, the
        // accountant's recovery, the manager's monthly report, the payroll. The
        // feed is the ONLY place the turn is shown, so it has to be about YOU
        // first and the scene second.
        const worldLog: string[] = [];

        // ─── FEATURE REPLIES ─────────────────────────────────────────────
        // Anything shopped out that is now due comes back. The decision itself
        // lives in `decideFeatureResponse`; this only applies it and posts the
        // answer into the player's DMs, because silence is also an answer.
        for (const req of state.featureRequests) {
          if (req.status !== 'sent') continue;
          if (!dateReached(req.dueDate, state.gameDate)) continue;

          const npc = state.npcs.find((n) => n.id === req.npcId);
          if (!npc) {
            req.status = 'ignored';
            continue;
          }

          const song = state.songs.find((s) => s.id === req.songId);
          const manager = activeManager(raw(state.contracts) as ActiveContract[], rawNPCs);

          // Sometimes the answer does not arrive on time. Real artists are
          // never written into a twist — their side of it would be invented.
          const generatedNpc = !isRealId(npc.id);
          const lateAlready = (state.moments ?? []).some((m) => m.kind === 'feature_late' && m.data?.requestId === req.id);
          if (generatedNpc && !lateAlready && Math.random() < 0.15) {
            req.dueDate = formatGameDate(advanceDate(state.gameDate, 6) as GameDate);
            deliverMoment(state, buildFeatureTwist('late', { id: req.id, songTitle: req.songTitle, npcId: npc.id, npcName: npc.name, fee: req.fee }, targetSerial), targetSerial);
            continue;
          }

          const decision = decideFeatureResponse({
            npc: npc as FeatureCandidate,
            playerFame: blendedFame(state.player),
            songQuality: song?.quality ?? 50,
            managerSkill: managerSkillOf(manager),
            genre: state.player.genre,
            roll: Math.random(),
          });

          req.reason = decision.reason;
          req.fee = decision.fee;
          // What they opened at, so the screen can show how far the player has
          // already talked them down.
          if (decision.outcome === 'terms') {
            req.originalFee = decision.fee;
            req.negotiationRound = 0;
            // A counter-idea instead of a price: verse for a verse, or billing.
            if (generatedNpc && Math.random() < 0.3) {
              const kind = npc.fame > blendedFame(state.player) + 5 && Math.random() < 0.45 ? 'lead' : 'swap';
              deliverMoment(state, buildFeatureTwist(kind, { id: req.id, songTitle: req.songTitle, npcId: npc.id, npcName: npc.name, fee: decision.fee }, targetSerial), targetSerial);
            }
          }

          if (decision.outcome === 'free') {
            req.status = 'verse_ready';
            req.freeVerse = true;
            req.verseQuality = verseQualityFor(npc as FeatureCandidate, song?.quality ?? 50);

            // ── A CO-SIGN IS AN EVENT, NOT A SENTENCE ──────────────────
            // The letter promises that they are telling people about it. That
            // has to actually happen, or the best moment in the whole feature
            // system is just a nicer paragraph. So they post — in their own
            // voice, to their own audience — and the industry notices.
            if (!isRealId(npc.id)) state.socialPosts.unshift({
              id: uuidv4(),
              platform: 'chirp',
              authorId: npc.id,
              authorName: npc.name,
              content: song
                ? `Been sitting with "${song.title}" all week. ${state.player.artistName} is the one. Verse is in. 🎙️`
                : `${state.player.artistName} is the one. Verse is in. 🎙️`,
              likes: Math.round(npc.fame * 400 + Math.random() * 5000),
              shares: Math.round(npc.fame * 60 + Math.random() * 400),
              comments: [],
              timestamp: new Date().toISOString(),
              relatedSongId: song?.id,
              isPlayerPost: false,
              trendingScore: 70 + npc.fame * 0.3,
            } as SocialPost);

            state.headlines.unshift({
              id: uuidv4(),
              text: generateHeadline('feature', state.player.artistName, npc.name),
              fullStory:
                `${npc.name} has gone public on ${state.player.artistName}, calling ` +
                `"${song?.title ?? 'the record'}" their pick of the moment and jumping on it for free. ` +
                `A co-sign from that name is worth more than the verse would have cost.`,
              date: formatGameDate(state.gameDate),
              relatedEntities: [state.player.id, npc.id],
              priority: 8,
              category: 'feature',
            });

            // The co-sign lands on the player's standing: their audience is
            // looking now, and their own regard for you deepens because you
            // were worth the gesture.
            const coSignFame = Math.max(1, Math.round(npc.fame * 0.05));
            state.player.career.localFame = Math.min(
              100,
              state.player.career.localFame + coSignFame * 0.5,
            );
            state.player.career.nationalFame = Math.min(
              100,
              state.player.career.nationalFame + coSignFame * 0.25,
            );
            npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + 3));
            addMomentum(state, 5 + npc.fame * 0.05, `${npc.name} went public on you`);
            log.push(`🤝 ${npc.name} co-signed you publicly — worth more than the fee.`);
          } else if (decision.outcome === 'terms') {
            req.status = 'terms';
          } else {
            req.status = decision.outcome; // 'declined' | 'ignored'
          }
          // A yes often comes with conditions.
          if (decision.outcome === 'terms' || decision.outcome === 'free') attachTerms(state, req, npc as NPC, rawNPCs, targetSerial);

          const thread = state.dmThreads[req.npcId] ?? {
            npcId: req.npcId,
            messages: [],
            unread: 0,
          };

          // ── Silence is silent ──────────────────────────────────────────
          // An "ignored" outcome means they never opened it. Writing a DM that
          // says "Sarkodie never replied" was a contradiction — if he did not
          // reply, there is nothing in the thread. The letter in the Mailbox
          // is where "no word back" belongs; the DM stays as it was, with only
          // the player's own outgoing message in it.
          if (decision.outcome !== 'ignored') {
            const kind = decision.outcome === 'terms' ? 'terms' : decision.outcome === 'declined' ? 'declined' : 'free';
            const realFeat = isRealId(req.npcId);
            thread.messages.push({ id: uuidv4(), npcId: req.npcId, fromPlayer: false, content: realFeat ? managerVoice(req.npcName.split(' ')[0], kind, decision.fee, req.id, req.songTitle) : featureVoice(kind, decision.fee, req.id), timestamp: new Date().toISOString(), read: false });
            if (!realFeat) thread.messages.push({
              id: uuidv4(),
              npcId: req.npcId,
              fromPlayer: false,
              system: true,
              content: decision.reason,
              timestamp: new Date().toISOString(),
              read: true,
            });
            thread.unread += 1;
            state.dmThreads[req.npcId] = thread;
          } else if (!state.dmThreads[req.npcId]) {
            state.dmThreads[req.npcId] = thread;
          }

          // ─── And into the Mailbox ──────────────────────────────────────
          // DMs are where the conversation lives; the Mailbox is where the
          // *decision* lands, because a reply with a price on it needs to be
          // actioned and mail is the screen with an action on it. Silence
          // gets a letter too — "they never came back to you" is information.
          const subject =
            decision.outcome === 'free'
              ? `${req.npcName} is sending you a verse for "${req.songTitle}"`
              : decision.outcome === 'terms'
                ? `${req.npcName} will jump on "${req.songTitle}" — for a price`
                : decision.outcome === 'declined'
                  ? `${req.npcName} passed on "${req.songTitle}"`
                  : `No word back from ${req.npcName} on "${req.songTitle}"`;

          const nextStep =
            decision.outcome === 'free'
              ? `\n\nThey are doing this for the relationship, not the money. Open the track in the Studio and add the verse to the record.`
              : decision.outcome === 'terms'
                ? `\n\nTheir fee is $${decision.fee.toLocaleString()}. Pay it and the verse is yours, or pass — either is a real answer.`
                : decision.outcome === 'declined'
                  ? `\n\nNothing to action here. Worth remembering who said no, and why.`
                  : `\n\nNothing to action. Silence is an answer too — reach them another way, or build more of a name first.`;

          state.mailbox.unshift({
            id: uuidv4(),
            // A letter that says "they never replied" cannot be from them. When
            // the outcome is silence it is a PingChat notification, not a
            // message from the artist — otherwise the inbox contradicts itself.
            from: decision.outcome === 'ignored' ? 'pingchat' : req.npcId,
            fromName: decision.outcome === 'ignored' ? 'PingChat' : req.npcName,
            subject,
            body: `${decision.reason}${nextStep}`,
            timestamp: new Date().toISOString(),
            read: false,
            type: 'feature_reply',
            featureRequestId: req.id,
          });

          log.push(
            decision.outcome === 'ignored'
              ? `🔇 ${req.npcName} never came back to you about "${req.songTitle}".`
              : `📥 ${req.npcName} came back to you about "${req.songTitle}".`,
          );
        }

        // ─── JOB BOARD ROTATION ──────────────────────────────────────────
        // New week, new board. Rolled here rather than lazily so the player
        // never opens the screen to a stale list.
        state.jobBoard = generateJobBoard({
          seed: state.turnCount + 1,
          playerFame: blendedFame(state.player),
          stats: state.player.stats,
          city: state.player.city,
        }) as JobListing[];
        state.jobBoardTurn = state.turnCount;

        // ─── STREAM TICKING ──────────────────────────────────────────
        // The engine has already done the work, one day at a time. This reads
        // its results back onto the song records the rest of the game reads, so
        // there is exactly one place streams are ever produced.
        const totalPayout = streamRun.revenue;
        const songBreakdown: WeeklyStatement['songBreakdown'] = [];

        for (const song of liveSongs(state.songs)) {
          const st = state.platformStats?.[song.id];
          if (!st) {
            song.weeklyStreams = 0;
            continue;
          }

          const totals = songTotals(st);
          song.weeklyStreams = totals.week;
          song.totalStreams = totals.lifetime;
          totalWeeklyStreams += totals.week;

          // The rate actually paid: money earned this tick divided by the units
          // that earned it. Read off the engine, not modelled separately.
          const tickUnits = streamRun.perSong[song.id] ?? 0;
          const earned = streamRun.revenueBySong[song.id] ?? 0;
          song.totalEarnings += earned;
          song.lastRatePerStream = tickUnits > 0 ? earned / tickUnits : undefined;

          if (totals.week > 0) {
            songBreakdown.push({
              songId: song.id,
              title: song.title,
              streams: totals.week,
              payout: earned,
            });
          }

          // Video views are owned entirely by the video engine, which has
          // already written them back onto this record above. Nothing to do
          // here — a second source would double-count.

          // Check certifications
          const units = getUnitsForCertification(song.totalStreams, song.videoViews);
          const certLevels: Array<[string, number]> = [
            ['legendary', 100_000_000 / 150],
            ['diamond', 10_000_000 / 150],
            ['platinum', 1_000_000 / 150],
            ['gold', 500_000 / 150],
            ['silver', 100_000 / 150],
          ];

          for (const [level, threshold] of certLevels) {
            const certKey = `${state.player.country}:${level}`;
            if (units >= threshold && !song.certifications.includes(certKey)) {
              song.certifications.push(certKey);
              state.certifications.push({
                id: uuidv4(),
                songId: song.id,
                songTitle: song.title,
                level: level as Certification['level'],
                multiplier: 1,
                country: state.player.country,
                awardedDate: formatGameDate(state.gameDate),
                units,
              });
              log.push(`🏆 "${song.title}" is now ${level.toUpperCase()} certified in ${state.player.country}!`);
              break;
            }
          }
        }

        // ─── THE CREW ─────────────────────────────────────────────────
        // Folded at the top of the tick, where the energy line needs it. The
        // payroll block below reads the same object.

        // Payout — with the crew's cut of the upside. A distribution plug
        // earns their wage by getting a better rate, so the multiplier lands
        // here, before the statement is written: the statement has to show
        // what actually arrived, not what would have arrived without them.
        const paidPayout = totalPayout * crew.payoutMult;
        state.player.career.money += paidPayout;
        ledgerAdd('streams', paidPayout);
        // Lifetime streams are the sum of the records' lifetimes — one source
        // of truth. Adding the rolling 7-day figure on every daily tick counted
        // each stream seven times.
        state.player.career.totalStreams = (state.songs as Song[]).reduce((a, x) => a + (x.totalStreams ?? 0), 0);
        state.player.career.totalEarnings += paidPayout;

        // ─── MOMENTUM ─────────────────────────────────────────────────
        // Momentum is the industry's attention on you *right now*. It is the
        // one number with no way to grind: it moves when something actually
        // happens and bleeds when nothing does.
        //
        // This is why it used to sit at zero. Its only sources were recording
        // and releasing — both rare, worth a couple of points each — against a
        // monthly decay, so a player who was not mid-release lived at the
        // floor. The week itself is now a source: a record doing real numbers
        // keeps you hot, and a record doing nothing does not.
        if (isWeek) {
          const weeks = unit === 'month' ? 4 : 1;
          const perWeek = totalWeeklyStreams / weeks;
          // A log curve. The gap between 1k and 10k weekly streams is a career;
          // the gap between 10M and 20M is a rounding error.
          const streamHeat = perWeek > 0 ? Math.log10(perWeek + 1) * 0.6 : 0;
          const hasSongs = liveSongs(rawSongs).length > 0;

          // Momentum is not "are you big" — it is "are you bigger than you
          // were". The yardstick is therefore your OWN recent form, not an
          // absolute number of streams: a newcomer's 2,000 streams are a
          // breakthrough, and a star's twenty million are a flop if they were
          // doing thirty. An absolute floor made the bleed unreachable — the
          // engine scales a record's streams with the artist, so every live
          // release clears any constant you could pick, and momentum could
          // only ever rise.
          // Read the recent weeks through a PLAIN copy. Calling a prototype
          // method straight onto the draft array (`state.weeklyStatements
          // .slice(...)`) registers child drafts against that array, and the
          // tick then mutates the same array with `unshift` — which leaves
          // revoked child drafts inside the committed state. The symptom is
          // that Save throws, permanently, from a completely unrelated place.
          // `raw()` here is free: the array has not been touched yet.
          const priorWeeks = raw(state.weeklyStatements) as WeeklyStatement[];
          const form = priorWeeks
            .slice(0, 4)
            .map(w => w.totalStreams)
            .filter(v => v > 0);
          const baseline = form.length ? form.reduce((a, b) => a + b, 0) / form.length : 0;

          if (!hasSongs) {
            // Nothing out. There is nothing to be hot off, and nothing to lose.
          } else if (baseline === 0 || perWeek >= baseline * 1.05) {
            addMomentum(state, Math.min(2, streamHeat) * weeks);
          } else if (perWeek < baseline * 0.9) {
            // A record that is falling off. Attention is not a savings
            // account, and stopping the room forgetting you is a publicist's
            // whole job — which is the same effect measured from the other end.
            addMomentum(state, -0.6 * weeks * crew.fameDecayMult);
          }
          // Within 10% of your own recent form you are neither rising nor
          // falling, so momentum holds.

          // Out of sight, out of mind: three weeks with no record and no post
          // and the room starts forgetting you, songs or not.
          const today = dateToSerial(state.gameDate);
          const lastPost = Math.max(-1, ...Object.values(state.socialStats ?? {}).map((x) => x?.lastPostSerial ?? -1));
          const lastDrop = Math.max(-1, ...liveSongs(rawSongs).map((x) => serialOfGameDate(x.releaseDate, -1)));
          if (today - Math.max(lastPost, lastDrop) > 21) addMomentum(state, -0.5 * weeks * crew.fameDecayMult);
        }

        // Weekly statement
        if (isWeek) {
          const stmt: WeeklyStatement = {
            id: uuidv4(),
            weekStartDate: formatGameDate(state.gameDate),
            totalStreams: totalWeeklyStreams,
            totalPayout: paidPayout,
            songBreakdown,
            flavorText: generateRoyaltyFlavor(),
          };
          state.weeklyStatements.unshift(stmt);
          if (state.weeklyStatements.length > 52) {
            state.weeklyStatements = state.weeklyStatements.slice(0, 52);
          }
        }

        // ─── CONTRACT CUTS ────────────────────────────────────────────
        // Two structures, two mechanics. A commission deal takes a slice of
        // what came in — so it costs nothing in a bad week. A retainer costs
        // the same every month whether or not a single stream landed, which is
        // exactly why it is cheaper over a career.
        for (const contract of state.contracts.filter(c => c.active)) {
          if (contract.terms.feeKind === 'retainer') {
            if (isMonth) {
              const fee = contract.terms.monthlyFee ?? 0;
              state.player.career.money -= fee;
              ledgerAdd('management', -fee);
              log.push(`💼 ${contract.npcName}: $${fee.toLocaleString()} monthly retainer.`);
            }
            continue;
          }
          if (contract.terms.percentage && paidPayout > 0) {
            const gross = paidPayout * (contract.terms.percentage / 100);
            // A lawyer on the payroll reads the third page and gets some of it
            // back. This is the only place their fee turns into money.
            const saved = gross * crew.cutRelief;
            const cut = gross - saved;
            state.player.career.money -= cut;
            ledgerAdd('management', -cut);
            log.push(
              `💼 ${contract.npcName} took their ${contract.terms.percentage}% cut ($${cut.toFixed(2)})` +
                (saved > 0.5 ? ` — your lawyer clawed back $${saved.toFixed(2)} of it.` : ''),
            );
          }
        }

        // ─── PAYROLL ──────────────────────────────────────────────────
        // Wages go out every month, and the people earning them do their job
        // every week. Both halves are here so a hire is never just a bill.
        if (crew.monthlyWage > 0 && isMonth) {
          state.player.career.money -= crew.monthlyWage;
          ledgerAdd('payroll', -crew.monthlyWage);
          log.push(`👥 Payroll: $${crew.monthlyWage.toLocaleString()} across ${(state.crew ?? []).length} people.`);
        }

        if (isWeek) {
          const weeks = unit === 'month' ? 4 : 1;
          const raised: string[] = [];
          for (const [stat, perWeek] of Object.entries(crew.stats)) {
            const gain = (perWeek ?? 0) * weeks;
            if (gain <= 0) continue;
            const key = stat as keyof ArtistStats;
            const before = state.player.stats[key];
            state.player.stats[key] = Math.min(100, before + gain);
            if (state.player.stats[key] > before) {
              raised.push(`${key} +${(state.player.stats[key] - before).toFixed(1)}`);
            }
          }
          if (raised.length > 0) {
            log.push(`👥 Your team put in the work: ${raised.join(', ')}.`);
          }
        }

        // ─── THE VOCAL COACH ──────────────────────────────────────────
        // The one thing a hire can give you that outlives them. A coach writes
        // to the STAT, not to a bonus, and the tick never takes it back — so
        // firing them stops the growth, it does not undo the work. Capped below
        // 100, because a stat you cannot lose the top of is not a stat.
        if (isMonth && Object.keys(crew.coaching).length > 0) {
          const COACHING_CAP = 92;
          const improved: string[] = [];
          for (const [stat, perMonth] of Object.entries(crew.coaching)) {
            const key = stat as keyof ArtistStats;
            const before = state.player.stats[key];
            if (before >= COACHING_CAP) continue;
            const gain = perMonth ?? 0;
            if (gain <= 0) continue;
            state.player.stats[key] = Math.min(COACHING_CAP, before + gain);
            if (state.player.stats[key] > before) {
              improved.push(`${key.replace(/([A-Z])/g, ' $1').toLowerCase()} +${(state.player.stats[key] - before).toFixed(1)}`);
            }
          }
          if (improved.length > 0) {
            log.push(`🎤 Coaching is showing: ${improved.join(', ')}. That stays with you.`);
          }
        }

        // ─── THE PEOPLE GET BETTER, OR THEY DO NOT ────────────────────
        // Everybody on the payroll improves while they are working — but only
        // up to their own ceiling, which comes from who they are. A hard
        // working unknown has somewhere to go; a lazy one is already as good as
        // they will ever be. That is what makes a cheap hire a bet rather than
        // a saving, and it is why the payroll screen shows the ceiling.
        //
        // Tenure and morale are settled in the same pass, because all three are
        // facts about the same month of employment.
        if (isMonth && (state.crew ?? []).length > 0) {
          for (const member of state.crew) {
            // Months served is what `chemistryOf` reads. It is the tick's
            // number, the way `skill` is.
            member.monthsServed = (member.monthsServed ?? 0) + 1;

            // Morale drifts back toward 70 — neither a grudge nor a honeymoon
            // lasts for ever. What moves it off 70 is an event, and the events
            // are in `createStudioSong`, where the slight actually happens.
            const morale = member.morale ?? 70;
            if (morale !== 70) {
              const drift = Math.max(1, Math.round(Math.abs(morale - 70) * 0.12));
              member.morale = morale > 70 ? Math.max(70, morale - drift) : Math.min(70, morale + drift);
            }

            const npc = state.npcs.find((n) => n.id === member.npcId);
            if (!npc) continue;
            crewCharacterGrowth(state, member, log);
            // Who they are decides how fast they get better: grinders climb,
            // the lazy stall, and the ones who have been with you from the
            // start grow with you.
            const st = workStyleOf(member);
            const styleRate = st === 'grinder' ? 1.6 : st === 'loyalist' ? 1.3 : st === 'timer' ? 1.2 : st === 'coaster' ? 0.5 : st === 'diva' || st === 'mercenary' || st === 'hothead' ? 0.9 : 1;
            const moodRate = (member.morale ?? 70) >= 70 ? 1.1 : (member.morale ?? 70) < 40 ? 0.6 : 1;
            const tenure = (member.monthsServed ?? 0) >= 6 ? 1.25 : 1;
            const rate = growthPerMonth(npc) * styleRate * moodRate * tenure;
            if (rate <= 0) continue;

            const before = npcSkill(npc);
            npc.skillBonus = (npc.skillBonus ?? 0) + rate;
            const after = npcSkill(npc);
            // The payroll record mirrors the person: `crewBonuses` folds the
            // crew without the roster in hand, so this is the number it reads.
            member.skill = after;

            // `npcDeltas` is collected from the plain `rawNPCs` snapshot taken
            // at the top of the tick, which does not see a write made here — so
            // the growth is mirrored onto that snapshot too, or it would be
            // lost on the next load while the roster regenerated without it.
            const mirror = rawNPCs.find((n) => n.id === member.npcId);
            if (mirror) mirror.skillBonus = npc.skillBonus;

            if (after > before && after % 5 === 0) {
              log.push(
                stillGrowing(npc)
                  ? `📈 ${npc.name} is improving — now rated ${after}, with room left.`
                  : `📈 ${npc.name} has topped out at ${after}. That is as good as they get.`,
              );
            }
          }
        }

        // Investments and businesses pay at every month boundary now — see
        // `moneyTick`, below, so a day-by-day player is paid too.

        // ─── BEEF: DECAY, AND THE ONES THAT END THEMSELVES ────────────
        // Heat is stored "as of `heatSerial`" and read through `decayedHeat`,
        // so this is not what makes a beef cool — the decay is lazy and always
        // correct. What this block does is two things the lazy read cannot:
        // bring the stored figure up to date so the screen is not doing maths
        // on a stale number, and CLOSE the beefs that have gone cold. A beef
        // nobody fed for a month is over, and it has to be marked over or the
        // screen keeps offering rungs on an argument that ended.
        if (state.beefs.length > 0) {
          const nowSerial = dateToSerial(state.gameDate);
          for (const beef of state.beefs) {
            if (beef.resolution) continue;
            beef.heat = settleHeat(beef, nowSerial);
            beef.heatSerial = nowSerial;

            const fizzled = fizzleIfCold(beef, nowSerial);
            if (!fizzled) continue;
            beef.resolution = {
              kind: fizzled,
              at: nowSerial,
              line: `Nobody fed it. ${beef.npcName} stopped answering and so did you, and the timeline moved on.`,
            };
            state.lastEventLog.unshift(
              `💤 The ${beef.npcName} thing is over. It went quiet for ${FIZZLE_DAYS} days and nobody picked it back up.`,
            );
          }
          state.lastEventLog = state.lastEventLog.slice(0, 10);
        }

        // ─── FAME DECAY ───────────────────────────────────────────────
        // Momentum's form-based bleed lives beside its gains, in the weekly
        // block near the payout above. On top of that, attention simply fades:
        // every day the room forgets a little (about a month's half-life), so
        // 100 means a lot is happening right now — not that a lot once did.
        // A publicist slows the fade.
        {
          const keep = Math.pow(1 - 0.02 * crew.fameDecayMult, days);
          state.player.career.momentum = Math.round(state.player.career.momentum * keep * 10) / 10;
        }

        // ─── FANBASE GROWTH ───────────────────────────────────────────
        // A manager is not a wage and not a percentage — they are a network.
        // Their one measurable effect is that the audience you do reach
        // converts better, because somebody is working the room on your behalf.
        // A charismatic hire adds on top of that: people liking *them* is a
        // separate, smaller effect from them knowing people.
        const mgrNet = managerNetwork(currentManager);
        // The arithmetic lives in `sim/fanbase.ts` so the fanbase screen and
        // this tick cannot quote different numbers. It used to be inline here,
        // which meant the panel was re-deriving it and free to drift.
        // The formula is per WEEK; the clock ticks a day at a time, and the
        // stream figure is a rolling seven-day number.
        const fanGrowth = fanGrowthFor({
          weeklyStreams: totalWeeklyStreams,
          momentum: state.player.career.momentum,
          managerNet: mgrNet,
          fanMult: crew.fanMult,
        }) * (days / 7);
        // Fractions carry by chance, so a slow week still adds up over a month.
        state.player.career.fanbase = Math.round(state.player.career.fanbase) + Math.floor(fanGrowth) + (Math.random() < fanGrowth % 1 ? 1 : 0);

        // ─── AND THEY ACTUALLY WORK FOR YOU ───────────────────────────
        // A manager is not a wage, so a manager who takes a cut and changes
        // nothing visible is a bill with a name on it. Every month they place
        // you and they chase money on your behalf, and then they tell you what
        // happened — including when the answer was nothing.
        //
        // The odds and the sizes are `managerMonth`'s, so the number the Team
        // screen promises and the number the tick pays come from one place.
        // A manager who signed you early grows with you: better at the job,
        // and better known as your name gets bigger.
        if (isMonth && currentManager) {
          const mNpc = state.npcs.find((n) => n.id === currentManager.id);
          if (mNpc && !isRealId(mNpc.id)) {
            const gain = growthPerMonth(mNpc as NPC) * (traitsFor(mNpc as NPC).hidden.includes('hard_working') ? 1.5 : traitsFor(mNpc as NPC).hidden.includes('lazy') ? 0.5 : 1);
            mNpc.skillBonus = (mNpc.skillBonus ?? 0) + gain;
            const pf = blendedFame(state.player);
            if (pf > mNpc.fame) mNpc.fame = Math.min(100, Math.round((mNpc.fame + (pf - mNpc.fame) * 0.04) * 10) / 10);
            const mirror = rawNPCs.find((n) => n.id === mNpc.id);
            if (mirror) { mirror.skillBonus = mNpc.skillBonus; mirror.fame = mNpc.fame; }
          }
        }
        if (isMonth && currentManager) {
          const mm = managerMonth({
            net: mgrNet,
            playerFame: blendedFame(state.player),
            fanbase: state.player.career.fanbase,
            rollPlacement: Math.random(),
            rollEndorsement: Math.random(),
            pickOutlet: Math.random(),
            pickBrand: Math.random(),
            sizeRoll: Math.random(),
            placeMult: SPECIALTIES[managerSpecialty(currentManager)].placeMult,
            dealMult: SPECIALTIES[managerSpecialty(currentManager)].dealMult,
          });

          if (mm.placement) {
            // A placement is a room you walk into, and a photographer changes
            // how far you carry out of it. This is the visual multiplier's one
            // hook: it scales the reach of anything the public sees.
            const vis = crew.visualMult;
            state.player.career.localFame = Math.min(
              100,
              state.player.career.localFame + mm.placement.fame * vis,
            );
            state.player.career.nationalFame = Math.min(
              100,
              state.player.career.nationalFame + mm.placement.fame * 0.5 * vis,
            );
            state.player.career.fanbase = Math.round(
              state.player.career.fanbase + mm.placement.fans * vis,
            );
          }
          if (mm.endorsement) {
            state.player.career.money += mm.endorsement.amount;
            ledgerAdd('endorsement', mm.endorsement.amount);
          }

          log.push(`💼 ${currentManager.name} ${mm.report}.`);
          // And the work their specialty is for: features, dates, deals,
          // producers, radio, abroad — filed on the desk, reported in the DMs.
          managerPitchTick(state, rawNPCs, currentManager, targetSerial, log);
        }

        // ─── WHO THEY ARE, SHOWING UP ─────────────────────────────────
        // The hidden layer is not a stat block; it is behaviour. A lazy or
        // angry operator costs you something visible every so often, and the
        // event log is where the player finds out what they actually hired.
        // Chance-based, so it reads as a person rather than a debuff timer.
        // A week's worth of chance, spread over the days that passed.
        if ((state.crew ?? []).length > 0 && crew.events.length > 0 && Math.random() < Math.min(0.6, 0.14 * days / 7)) {
          const line = crew.events[Math.floor(Math.random() * crew.events.length)];
          const who = state.crew[Math.floor(Math.random() * state.crew.length)];
          if (who) {
            log.push(`👥 ${who.npcName} ${line}.`);
            // Whoever it was, the team notices — and so does their own regard
            // for you, scaled by how thin-skinned they are about it.
            const n = state.npcs.find((x) => x.id === who.npcId);
            if (n) {
              n.relationshipScore = Math.max(
                -100,
                Math.min(100, n.relationshipScore - Math.round(crew.friction)),
              );
            }
          }
        }

        // ─── LOCAL FAME GROWTH ────────────────────────────────────────
        // Per week, scaled to the days that passed, and graded: ten thousand
        // streams a week makes you known on your block; a million makes you
        // known in the country. The clock ticks daily, so a flat +0.2 per tick
        // was +1.4 a week and every artist with a pulse hit 100 within months.
        {
          const wk = days / 7;
          const tier = (floor: number) => (totalWeeklyStreams > floor ? Math.log10(totalWeeklyStreams / floor) : 0);
          const c = state.player.career;
          c.localFame = Math.min(100, c.localFame + wk * Math.min(1.2, 0.3 + tier(10_000) * 0.4) * (totalWeeklyStreams > 10_000 ? 1 : 0));
          c.nationalFame = Math.min(100, c.nationalFame + wk * Math.min(0.9, 0.2 + tier(100_000) * 0.35) * (totalWeeklyStreams > 100_000 ? 1 : 0));
          c.internationalFame = Math.min(100, c.internationalFame + wk * Math.min(0.5, 0.1 + tier(1_000_000) * 0.2) * (totalWeeklyStreams > 1_000_000 ? 1 : 0));
        }

        // ─── CHARTS ───────────────────────────────────────────────────
        // Player and NPC songs compete on the same regional charts.
        state.charts = updateCharts(
          raw(state.charts) as Record<string, ChartEntry[]>,
          [...liveSongs(rawSongs), ...rawNPCSongs] as Song[],
          rawNPCs,
          raw(state.player) as Player,
          // The chart week turns over on Sunday, the day after the week ends.
          days > 1 || serialWeekday(targetSerial) === 0,
        ) as typeof state.charts;

        // ─── GLOBAL CHARTS ────────────────────────────────────────────
        // Weekly, from the seven days just gone. The cursor holds the last
        // Saturday already published for, so this is a no-op on every day but
        // Saturday — and a jump of a month lands one fresh chart, not four
        // identical ones with different dates on them.
        publishGlobalCharts(state, rawNPCs);

        // Refresh trending topics from the new chart state.
        state.trending = buildTrending(state.charts as Record<string, ChartEntry[]>, state.player) as typeof state.trending;

        // ─── SOCIAL WORLD ─────────────────────────────────────────────
        // NPCs and fans post about what actually just happened on the charts.
        const ghanaChart = state.charts['Ghana'] ?? [];
        const leader = ghanaChart[0];
        const bestMover = [...ghanaChart]
          .filter(e => e.lastPosition > e.position)
          .sort((a, b) => (b.lastPosition - b.position) - (a.lastPosition - a.position))[0];

        const playerOnChart = Object.values(state.charts).some(
          list => list.some(e => e.artistId === state.player!.id)
        );

        const newSocial: SocialPost[] = [];

        // Fans reacting to the real chart state.
        newSocial.push(...fanPosts(leader, bestMover, rawNPCs, state.player, playerOnChart) as SocialPost[]);

        // A couple of NPC artists posting about their own records.
        // Scanned on the raw roster, not the draft: picking 5 random artists out
        // of 11,851 is a full sort, and the proxy makes that ~7x dearer.
        const artistsForPosts = pickRandomArtists(rawNPCs, 5);
        for (const npc of artistsForPosts) {
          const own = rawNPCSongs.filter(s => s.ownerId === npc.id);
          newSocial.push(...npcArtistPosts(npc, own) as SocialPost[]);
        }

        if (newSocial.length > 0) {
          settleScenePosts(state, newSocial, rawNPCs);
          state.socialPosts.unshift(...newSocial);
          // Keep the feed bounded.
          if (state.socialPosts.length > 320) {
            trimFeed(state);
          }
        }

        // One lookup map for the whole tick — an earlier version ran
        // `state.npcs.find(n => ev.involvedNPCIds.includes(n.id))` per event,
        // which is a full roster scan nested inside a per-event loop.
        const npcById = new Map(rawNPCs.map(n => [n.id, n]));

        // ─── AWARD SEASONS ────────────────────────────────────────────
        // Calendars, nominations, fan voting and ceremonies run daily (see
        // awardsTick); the old year-end batch is gone.
        if (!deferSide) awardsTick(state, targetSerial, rawNPCs, rawNPCSongs);

        // ─── STORY DIRECTOR ───────────────────────────────────────────
        // Shallow spread of the draft, NOT `raw(state)`.
        //
        // `raw(state)` routes through immer's `current()`, which deep-clones
        // the entire state — the 11.6k roster, every song, every platform's
        // day history — purely to hand a read-only engine a snapshot. That
        // clone measured ~230ms on every single tick, day or month, and was
        // the largest remaining cost in the whole advance. The director reads
        // only `player`, `openThreads`, `songs` and `turnCount` (see
        // `scanTriggers`), so a shallow spread is equivalent and costs ~60
        // property reads. The three big collections are swapped for the plain
        // arrays the tick already made, so the engine never walks a proxy.
        const storyState = {
          ...(state as unknown as GameState),
          npcs: rawNPCs,
          npcSongs: rawNPCSongs,
          songs: rawSongs,
        } as GameState;
        const { events: storyEvents, newOpenThreads, escalated } = runStoryDirector(storyState);

        for (const thread of newOpenThreads) {
          state.openThreads.push({ ...thread, openedSerial: targetSerial } as typeof state.openThreads[0]);
        }
        for (const t of state.openThreads) {
          if (escalated.includes(t.id)) { t.escalationCount += 1; t.lastUpdated = formatGameDate(state.gameDate); }
          // Nothing lasts forever: six weeks untouched and the story is over.
          if (t.openedSerial === undefined) t.openedSerial = targetSerial;
          if (!t.resolved && targetSerial - t.openedSerial > 42) t.resolved = true;
        }
        if (state.openThreads.length > 60) state.openThreads = state.openThreads.filter((t) => !t.resolved).slice(-40);

        for (const ev of storyEvents) {
          if (ev.key) (state.storyFired ?? (state.storyFired = {}))[ev.key] = targetSerial;
          log.push(`📰 ${ev.headline}: ${ev.description}`);

          // Apply effects
          if (ev.effectType === 'fame') state.player.career.localFame = Math.min(100, state.player.career.localFame + ev.effectValue);
          if (ev.effectType === 'reputation') {
            // The press cycle is where a publicist earns their fee: a story
            // that damages you damages you less while somebody is handling it.
            const rep = ev.effectValue < 0 ? ev.effectValue * crew.controversyMult : ev.effectValue;
            state.player.career.reputation = Math.min(100, Math.max(0, state.player.career.reputation + rep));
          }
          if (ev.effectType === 'money') state.player.career.money = Math.max(0, state.player.career.money + ev.effectValue);
          // The story does what it says.
          if (ev.special === 'start_beef') {
            const rival = state.npcs.find((n) => n.id === ev.involvedNPCIds[0]);
            if (rival && !isBlocked(state, rival.id)) npcStartsBeef(state, rival as NPC, targetSerial, 'a subliminal post the whole timeline read as being about you');
            continue;
          }
          if (ev.special === 'collab_ask') {
            const ally = rawNPCs.find((n) => n.id === ev.involvedNPCIds[0]);
            const theirSong = ally ? (state.npcSongs as Song[]).filter((x) => x.ownerId === ally.id && x.releaseDate).sort((a, b) => b.quality - a.quality)[0] : undefined;
            const busy = state.inboundRequests.some((r) => r.npcId === ev.involvedNPCIds[0] && (r.status === 'open' || r.status === 'agreed'));
            if (ally && theirSong && !busy && !isBlocked(state, ally.id) && !isRealId(ally.id)) {
              openInboundAsk(state, ally, theirSong, pickLine([`We've been talking about this for too long. Jump on "${theirSong.title}" with me?`, `Got a record with your name on it — "${theirSong.title}". You in?`], ally.id + targetSerial));
            }
          }
          if (ev.special === 'revive' && ev.songId) {
            pushSong(state, ev.songId, 0.35, 14, ev.headline);
            addMomentum(state, 2);
            state.player.career.fanbase += Math.round(80 + blendedFame(state.player) * 8);
          }
          if (ev.special === 'intl_buzz') {
            state.player.career.internationalFame = Math.min(100, state.player.career.internationalFame + 1.5);
            addMomentum(state, 1);
          }

          // Add NPC social post for the event
          if (ev.involvedNPCIds.length > 0) {
            const npc = ev.involvedNPCIds.map(id => npcById.get(id)).find(Boolean);
            // The game doesn't write posts in real people's names.
            if (npc && !isRealId(npc.id)) {
              const npcPost: SocialPost = {
                id: uuidv4(),
                platform: 'chirp',
                authorId: npc.id,
                authorName: npc.name,
                content: generateNPCChirpPost(npc),
                likes: Math.floor(npc.fame * 10 + Math.random() * 200),
                shares: Math.floor(Math.random() * 50),
                comments: [],
                timestamp: new Date().toISOString(),
                isPlayerPost: false,
                trendingScore: npc.fame,
              };
              state.socialPosts.unshift(npcPost);
            }
          }
        }

        // ─── NPC MUSIC WORLD ──────────────────────────────────────────
        // NPC songs live their own lives: they climb, decay, surge, and die out.
        const npcTick = tickNPCSongs(state.npcSongs as Song[], rawNPCs);
        for (const ev of npcTick.events) worldLog.push(ev);
        // `tickNPCSongs` adds one "week" per TURN, and the running clock turns
        // once a day — so a record was "13 weeks old" on its thirteenth day.
        // Age is a fact about the calendar; read it off the release date.
        for (const song of state.npcSongs as Song[]) {
          const released = serialOfGameDate(song.releaseDate, targetSerial);
          song.weeksOut = Math.max(0, Math.floor((targetSerial - released) / 7));
        }

        // ─── ONE SOURCE OF TRUTH FOR THE NUMBERS ──────────────────────
        // The streaming engine writes per-platform daily values into
        // `platformStats`, and that is what every chart is built from. The NPC
        // scalar model above keeps its own `weeklyStreams` / `totalStreams`, and
        // the two drifted a long way apart: a record sitting at #1 on the global
        // chart displayed a 279K lifetime next to an 82M week, because the
        // read-back below the stream tick only ever covered the player's songs.
        // Read the engine back onto the record here too, so the chart, the
        // record page and the cards all quote the same number.
        for (const song of state.npcSongs as Song[]) {
          const st = state.platformStats?.[song.id];
          if (!st) continue;
          const totals = songTotals(st);
          song.weeklyStreams = totals.week;
          song.totalStreams = totals.lifetime;
          song.peakWeeklyStreams = Math.max(song.peakWeeklyStreams ?? 0, totals.week);
        }

        // NPC artists keep releasing — the scene never stands still.
        const { songs: fresh, events: releaseEvents } = npcReleaseTick(
          rawNPCs,
          state.npcSongs as Song[],
          state.gameDate,
          state.turnCount,
          (state.npcUpcoming ?? []).map((u) => u.song.ownerId ?? ''),
        );
        // Artists signed to the player's label release through the label, on
        // the label's money — never on the world's own schedule.
        if (state.label && fresh.length > 0) {
          const signed = labelSigneeIds(state.label);
          for (let i = fresh.length - 1; i >= 0; i--) {
            if (fresh[i].ownerId && signed.has(fresh[i].ownerId as string)) fresh.splice(i, 1);
          }
          releaseEvents.splice(0, releaseEvents.length, ...fresh.map((s) => `🎵 ${s.ownerName} dropped "${s.title}".`));
        }
        // Established artists roll a release out: announce it, then drop it a
        // few days later. Newcomers just drop.
        rolloutReleases(state, fresh, releaseEvents, rawNPCs, targetSerial);
        if (fresh.length > 0) {
          state.npcSongs.push(...fresh);
          worldLog.push(...releaseEvents);
          // Subscribers hear about it. Nobody else does — a notification for an
          // artist you do not follow would be noise, not news.
          for (const song of fresh) {
            const npc = rawNPCs.find((n) => n.id === song.ownerId);
            if (!npc) continue;
            const follows = (state.subscriptions ?? []).some((s) => s.artistId === npc.id);
            // A superstar from home dropping is news whether you follow them or not.
            const bigHome = npc.country === state.player.country && npc.fame >= 70;
            if (!follows && !bigHome) continue;
            pushNotification(state, {
              kind: 'artist_release',
              title: bigHome && !follows ? `🔥 ${npc.name} just dropped "${song.title}"` : `${npc.name} dropped "${song.title}"`,
              body: bigHome && !follows ? `The whole of ${npc.country} is on it. Maybe don't release this week.` : `${npc.name} released a new record.`,
              artSeed: `song|${song.id}`,
              action: { type: 'song', id: song.id },
            });
          }
        }
        state.npcSongs = pruneNPCSongs(
          state.npcSongs as Song[],
          // Every record the player has been asked onto and not yet delivered.
          // Losing one of these to the trim means the player writes a verse for
          // a song that no longer exists.
          new Set([
            ...state.inboundRequests
              .filter((r) => r.status === 'open' || r.status === 'agreed')
              .map((r) => r.npcSongId),
            // The label's catalogue is an asset the player paid for.
            ...(state.label
              ? [...state.label.roster, ...state.label.alumni].flatMap((s) => s.releases)
              : []),
          ]),
        ) as typeof state.npcSongs;

        // ─── NPC ALBUM WORLD ──────────────────────────────────────────
        // Artists who just put out a single sometimes bundle their recent work
        // into an EP or album. Without this the Global Top 200 only ever
        // shrinks: the recurrent rule retires entries and nothing replaces them.
        if (isWeek && fresh.length > 0) {
          const albums = state.npcAlbums ?? (state.npcAlbums = []);
          const owners = new Set<string>();
          for (const s of fresh) if (s.ownerId) owners.add(s.ownerId);

          let madeAlbums = 0;
          for (const ownerId of owners) {
            if (madeAlbums >= 3) break;
            const npc = rawNPCs.find(n => n.id === ownerId);
            if (!npc) continue;
            const own = (state.npcSongs as Song[]).filter(s => s.ownerId === ownerId);
            const ownProjects = albums.filter(a => a.ownerId === ownerId);
            const project = buildNewProject(
              npc,
              own,
              ownProjects as unknown as Project[],
              targetSerial,
            );
            if (!project) continue;
            albums.push(project as (typeof albums)[number]);
            madeAlbums++;
          }
          if (albums.length > 900) {
            state.npcAlbums = albums.slice(0, 900) as typeof state.npcAlbums;
          }
        }

        // ─── NPC VIDEO WORLD ──────────────────────────────────────────
        // NPC artists shoot visuals for their current singles on their own, so
        // the video platform is alive whether or not the player ever opens it.
        if (isWeek) {
          const freshVideos = npcVideoTick(
            state,
            rawNPCs,
            dateToSerial(chartWeekEnding(state.gameDate)),
          );
          for (const v of freshVideos) {
            // Only notify for artists the player actually follows.
            const follows = (state.subscriptions ?? []).some(
              (s) => s.artistId === v.artistId,
            );
            if (follows) {
              pushNotification(state, {
                kind: 'artist_video',
                title: `${v.artistName} uploaded "${v.title}"`,
                body: `A new visual for "${v.songTitle}".`,
                artSeed: `video|${v.id}`,
                action: { type: 'video', id: v.id },
              });
            }
          }
        }

        // ─── NPC WORLD FLAVOUR ────────────────────────────────────────
        const npcEvents = simulateNPCWorld(rawNPCs, state.turnCount);
        worldLog.push(...npcEvents.map(e => `🌍 ${e}`));

        // ─── YOUR OWN LABEL ───────────────────────────────────────────
        // After the streaming engine (it needs what the records earned) and
        // after the NPC release tick (so a signee's record is never released
        // twice). The label has its own bank account; nothing here touches
        // the player's money.
        if (state.label) {
          labelTick(state, rawNPCs, streamRun.labelRevenueBySong, targetSerial, days, worldLog);
        }

        // ─── MOMENTS ──────────────────────────────────────────────────
        // People text you; your team walks in with problems. Decisions
        // with consequences, some of them weeks later.
        if (!deferSide) momentsTick(state, rawNPCs, targetSerial, days);

        // Plans you skipped past, and messages that were due.
        {
          const nowAbs = nowMinuteOf(state);
          for (const ap of state.appointments ?? []) {
            if (ap.status === 'confirmed' && (ap.atMinute < nowAbs - 120 || (!opts?.silent && ap.atMinute <= nowAbs))) autoAttendOrMiss(state, ap, 'skip');
          }
          deliverPendingDMs(state, nowAbs);
        }

        // ─── SOCIAL ───────────────────────────────────────────────────
        // Posts keep collecting, the scene posts, fan wars burn, rivals
        // hit back.
        if (!deferSide) socialTick(state, rawNPCs, targetSerial, days);

        // ─── INTERVIEWS ───────────────────────────────────────────────
        if (!deferSide) interviewTick(state, targetSerial, days, rawNPCs);

        // ─── BEATS & THE BUILDING ─────────────────────────────────────
        // The team's beat drops, commissioned beats arriving, the weekly
        // store, and the studio's monthly bills.
        beatsTick(state, rawNPCs, targetSerial, days);
        if (!deferSide) teamChatTick(state, targetSerial);
        if (!deferSide) birthdaysTick(state, rawNPCs, targetSerial, days);
        if (!deferSide) starPulseTick(state, rawNPCs, targetSerial);
        if (!deferSide) breakoutTick(state, targetSerial);
        if (!deferSide) fanClubTick(state, targetSerial, days);
        if (deferSide) pendingSide = { serial: targetSerial };

        // ─── MONEY & THE TEAM'S WEEK ──────────────────────────────────
        // Markets move daily; businesses, rent and dividends at the month;
        // building sites progress; yesterday's matches settle. Then whatever
        // each person on the payroll was put on this week.
        moneyTick(state, targetSerial, days, log);
        teamWorkTick(state, targetSerial, days, (streamRun.revenue / Math.max(1, days)) * 7, log);

        // ─── INDUSTRY & LIFE TICK ─────────────────────────────────────
        const todaySerial = dateToSerial(state.gameDate);
        for (const campaign of state.payolaCampaigns) {
          if (campaign.completed || campaign.remainingDays <= 0) continue;
          const song = state.songs.find(s => s.id === campaign.songId);
          if (!song) { campaign.completed = true; continue; }
          // Extra attention is applied after the normal streaming calculation.
          const activeDays = Math.min(days, campaign.remainingDays);
          song.weeklyStreams = Math.round(song.weeklyStreams * (1 + campaign.boost * (activeDays / 7)));
          campaign.remainingDays -= days;
          // Exposure is uncommon, but becomes more likely when the player is
          // famous enough for journalists and radio insiders to care.
          if (!campaign.exposed && Math.random() < (0.015 + state.player.career.reputation / 5000) * Math.max(1, days) / 7) {
            campaign.exposed = true;
            state.player.career.reputation = Math.max(0, state.player.career.reputation - 4);
            state.headlines.unshift({ id: uuidv4(), text: `Questions surround ${state.player.artistName}'s radio push`, fullStory: `Industry insiders are questioning the radio campaign behind "${song.title}" in ${campaign.city}. No formal finding has been made, but the story is spreading.`, date: formatGameDate(state.gameDate), relatedEntities: [state.player.id, song.id], priority: 6, category: 'scandal' });
            state.industryNotices.unshift({ id: uuidv4(), type: 'payola', title: 'Radio campaign exposed', body: `The campaign for "${song.title}" is being questioned publicly. Reputation took a hit.`, date: formatGameDate(state.gameDate), relatedSongId: song.id, read: false });
            log.push(`📻 Radio campaign exposed in ${campaign.city}. Reputation -4.`);
          }
          if (campaign.remainingDays <= 0) campaign.completed = true;
        }

        // Expired sample requests become legal risks instead of silently vanishing.
        for (const c of state.sampleClearances) {
          if (c.status === 'pending' && todaySerial > c.deadlineSerial) {
            c.status = 'expired';
            // The song is out and the sample isn't cleared: the rights holder comes for it.
            const outSong = state.songs.find((x) => x.id === c.songId);
            if (outSong && isSongReleased(outSong) && Math.random() < 0.6) {
              const holder = { id: `rights:${c.rightsHolder}`, name: c.rightsHolder, fame: 40, personality: ['calculating'], role: 'lawyer', tier: 'established' } as unknown as NPC;
              if (!state.npcs.some((n) => n.id === holder.id)) state.npcs.push({ ...holder, relationshipScore: 0, memoryLog: [] } as unknown as NPC);
              npcSues(state, state.npcs.find((n) => n.id === holder.id)!, 'copyright', Math.max(5000, c.quotedCost * 3), 88, [`"${c.songTitle}" uses "${c.sampleName}" without a licence.`, `Clearance was requested on ${c.requestedDate} and never completed.`, 'The song is out and earning.'], c.id);
            }
            state.openThreads.unshift({ id: uuidv4(), type: 'legal', description: `Clearance deadline expired for "${c.songTitle}".`, involvedNPCIds: [], startDate: formatGameDate(state.gameDate), lastUpdated: formatGameDate(state.gameDate), resolved: false, priority: 8, escalationCount: 1 });
            log.push(`⚖️ Sample clearance expired for "${c.songTitle}".`);
          }
        }

        // Rent, bills and what you own cost money every month — and the bank
        // wants its payment whatever kind of month it was.
        homeTick(state, todaySerial, log);
        bankTick(state, todaySerial, log);

        // Monthly family obligation. It is an actual ledger expense, not flavour.
        if (state.family.children > 0 && state.family.nextReviewSerial !== undefined && todaySerial >= state.family.nextReviewSerial) {
          const months = Math.max(1, Math.floor((todaySerial - state.family.nextReviewSerial) / 30) + 1);
          const charge = Math.round(state.family.monthlyChildSupport * months);
          state.player.career.money -= charge;
          ledgerAdd('child_support', -charge);
          state.family.nextReviewSerial += months * 30;
          log.push(`👶 Family support: ${money0(charge)}.`);
        }

        // A&R missions are generated only when the player's career has enough
        // traction. They expire, so they behave like real industry work rather
        // than a permanent quest list.
        if (isWeek && state.player.career.localFame >= 20 && state.scoutMissions.filter(m => m.status === 'open').length < 2 && Math.random() < 0.18) {
          // A different artist and a local scout each time — not the first name in the roster forever.
          const busyTargets = new Set(state.scoutMissions.filter((m) => m.status === 'open').map((m) => m.targetNpcId));
          const target = sampleNpcs(rawNPCs, 1, (n) => n.role === 'artist' && n.country === state.player!.country && n.id !== state.player!.id && n.relationshipScore < 60 && !busyTargets.has(n.id) && Math.abs(n.fame - blendedFame(state.player!)) < 30)[0];
          const scout = sampleNpcs(rawNPCs, 1, (n) => (n.role === 'a_and_r_scout' || n.role === 'ar') && n.country === state.player!.country)[0] ?? sampleNpcs(rawNPCs, 1, (n) => n.role === 'a_and_r_scout' || n.role === 'ar')[0];
          if (target && scout) {
            state.scoutMissions.unshift({ id: uuidv4(), scoutName: scout.name, targetNpcId: target.id, targetName: target.name, objective: `Build a working relationship with ${target.name}.`, rewardMoney: 1000 + Math.round(state.player.career.localFame * 50), rewardFame: 2 + state.player.career.localFame / 25, expiresSerial: todaySerial + 45, status: 'open' });
            state.industryNotices.unshift({ id: uuidv4(), type: 'scout', title: `${scout.name} noticed your work`, body: `A&R wants you to build a connection with ${target.name}.`, date: formatGameDate(state.gameDate), relatedNpcId: target.id, read: false });
            log.push(`🔎 A&R scout ${scout.name} opened a mission involving ${target.name}.`);
          }
        }

        // Rare, earned "they noticed you" moments. This is a social/world event,
        // not a free reward: the relationship starts neutral and the opportunity
        // must still be handled by the player.
        if (isWeek && state.player.career.nationalFame >= 45 && Math.random() < 0.035 * 7) {
          // Somebody among the biggest names — not the same one every time.
          const recent = new Set(state.industryNotices.filter((n) => n.type === 'noticed').slice(0, 8).map((n) => n.relatedNpcId));
          const tops = rawNPCs.filter(n => n.role === 'artist' && n.tier === 'international' && n.fame > state.player!.career.nationalFame && !recent.has(n.id)).sort((a,b) => b.fame-a.fame).slice(0, 12);
          const big = tops[Math.floor(Math.random() * tops.length)];
          if (big) {
            state.industryNotices.unshift({ id: uuidv4(), type: 'noticed', title: `${big.name} noticed your rise`, body: `${big.name}'s team has been watching your recent numbers. Nothing is promised — but your name is in the room.`, date: formatGameDate(state.gameDate), relatedNpcId: big.id, read: false });
            // No words in a real person's mouth: the notice above is the news.
            if (!isRealId(big.id)) state.mailbox.unshift({ id: uuidv4(), from: big.id, fromName: big.name, subject: 'Been seeing the work', body: `My team has been watching what you've been doing lately. Keep going.`, timestamp: new Date().toISOString(), read: false, type: 'general' });
            log.push(`👀 ${big.name} noticed your rise.`);
          }
        }

        // Legacy score remains visible while active and updates from real career
        // achievements, so retirement is a summary of a life rather than a reset.
        state.legacy.legacyScore = Math.max(state.legacy.legacyScore, Math.round(state.player.career.totalStreams / 100000 + state.awards.filter(a => a.winner === state.player!.id).length * 250 + state.certifications.length * 100 + state.player.career.totalEarnings / 10000 + state.player.career.internationalFame * 20));
        const titles: string[] = [];
        if (state.legacy.legacyScore >= 500) titles.push('Hall of Famer');
        if (state.legacy.legacyScore >= 1000) titles.push('Mogul');
        if (state.legacy.legacyScore >= 2000) titles.push('Cultural Icon');
        state.legacy.titles = titles;

        // ─── MANAGER APPROACH ─────────────────────────────────────────
        // Several manager archetypes circle once the player shows traction —
        // and once one of them is signed, the rest start trying to take them
        // off you. A manager who is never challenged is not a deal.
        // Weekly, not daily: the chances below are a week's worth of interest.
        // Rolled every day on the clock, a hot artist got a new manager pitch
        // or label offer almost every morning.
        const mgrOffers = isWeek ? generateManagerOffers(
          state.player,
          rawNPCs,
          state.turnCount,
          currentManager ? 1 : 0,
          currentManager,
        ) : [];
        const fired = state.storyFired ?? (state.storyFired = {});
        for (const offer of mgrOffers) {
          // Avoid stacking identical pending offers — and nobody pitches the
          // same artist twice in six weeks.
          const dupe = state.mailbox.some(m => m.type === 'offer' && !m.read && m.from === offer.from);
          if (dupe) continue;
          if (fired[`mgrOffer:${offer.from}`] !== undefined && targetSerial - fired[`mgrOffer:${offer.from}`] < 45) continue;
          fired[`mgrOffer:${offer.from}`] = targetSerial;
          state.mailbox.unshift(offer as typeof state.mailbox[0]);
          log.push(
            currentManager
              ? `💼 ${offer.fromName} wants to take you off ${currentManager.name} — check your Mailbox.`
              : `💼 ${offer.fromName} wants to manage you — check your Mailbox.`,
          );
        }

        // ─── LABEL INTEREST ───────────────────────────────────────────
        // Labels compete for a hot artist rather than one static offer.
        const hasLabel = state.contracts.some(c => c.type === 'label' && c.active);
        const labelOffers = isWeek ? generateLabelOffers(
          state.player,
          rawNPCs,
          bestSongQuality(rawSongs),
          hasLabel,
        ) : [];
        for (const offer of labelOffers) {
          const dupe = state.mailbox.some(m => m.type === 'contract' && !m.read && m.fromName === offer.fromName);
          if (dupe) continue;
          // A label that was turned down waits a couple of months before trying again.
          if (fired[`labelOffer:${offer.fromName}`] !== undefined && targetSerial - fired[`labelOffer:${offer.fromName}`] < 60) continue;
          fired[`labelOffer:${offer.fromName}`] = targetSerial;
          state.mailbox.unshift(offer as typeof state.mailbox[0]);
          log.push(`📬 ${offer.fromName} sent you a contract offer.`);
        }

        // ─── TAX ──────────────────────────────────────────────────────
        // The ledger is drained HERE rather than at the report, because the tax
        // charge is worked out on the ledger's own income total and then added
        // back into it — one account of the money, read and written once.
        const ledgerEntries = drainTurnLedger();
        let turnIncome = 0;
        for (const [, amount] of ledgerEntries) {
          if (amount > 0) turnIncome += amount;
        }

        // ─── WHAT THE ACCOUNTANT AND THE STYLIST BRING IN ─────────────
        // Both are sized as a share of the turn's music income, because both
        // are really buying the same thing: reach. A brand pays for audience
        // and an accountant's recovery is proportional to what there was to
        // lose. A flat figure would be pocket change at the top and a jackpot
        // at the bottom, which is how a mechanic becomes a money printer.
        //
        // Sited here rather than in the payroll block because this is the one
        // place in the tick where the turn's income is known — the ledger has
        // just been read.
        if (turnIncome > 0 && (crew.recoveryRate > 0 || crew.brandRate > 0)) {
          const recovered = Math.round(turnIncome * crew.recoveryRate);
          const brand = Math.round(turnIncome * crew.brandRate);
          if (recovered > 0) {
            state.player.career.money += recovered;
            ledgerEntries.set('recovery', (ledgerEntries.get('recovery') ?? 0) + recovered);
            log.push(`💰 Your accountant found ${money0(recovered)} that was going missing — unpaid royalties and overbilled fees.`);
          }
          if (brand > 0) {
            state.player.career.money += brand;
            ledgerEntries.set('brand', (ledgerEntries.get('brand') ?? 0) + brand);
            log.push(`👗 Brand work brought in ${money0(brand)} this month. That money has nothing to do with music.`);
          }
          // Both are income like any other and are taxed like any other. A
          // recovered royalty is not a gift from the taxman.
          turnIncome += recovered + brand;
        }

        const thisYear = state.gameDate.year;
        // Months since year zero, so "has the month turned over?" is one
        // comparison rather than a year/month pair that can half-match.
        const thisMonth = thisYear * 12 + state.gameDate.month;

        // Open the books on the first turn of a career, and charge nothing:
        // there is no month behind you yet to bill for.
        if (state.taxYear === undefined || state.taxMonth === undefined) {
          state.taxYear = thisYear;
          state.taxMonth = thisMonth;
          state.taxYearIncome = 0;
          state.taxPaidThisYear = 0;
        }

        // A new game year settles the annual charge on what the player owns.
        if (state.taxYear !== thisYear) {
          const holdings = [
            ...state.ownedAssets.map((a) => ({ label: a.name, value: a.cost })),
            ...state.businesses.map((b) => ({ label: b.name, value: b.monthlyRevenue * 24 })),
            ...state.investments.map((i) => ({ label: i.name, value: i.currentValue })),
            // Buildings and land you developed are property too.
            ...(state.devProjects ?? []).filter((d) => d.stage !== 'sold').map((d) => ({ label: d.build ?? 'land', value: projectValue(d, state.market?.propertyIndex ?? 100, dateToSerial(state.gameDate)) })),
            ...(state.homes ?? []).map((h) => ({ label: homeDef(h.tier).name, value: ownedValue(h, state.market?.propertyIndex ?? 100) })),
          ];
          const propTax = propertyTax(holdings);
          if (propTax > 0) {
            state.player.career.money -= propTax;
            ledgerEntries.set('property_tax', -(ledgerEntries.get('property_tax') ?? 0) - propTax);
            log.push(`🏛️ Property tax on ${money0(holdingsValue(holdings))} of holdings: ${money0(propTax)}.`);
          }
          log.push(`🏛️ New tax year. Last year you paid ${money0(state.taxPaidThisYear ?? 0)} on ${money0(state.taxYearIncome ?? 0)} earned.`);
          state.taxYear = thisYear;
          state.taxYearIncome = 0;
          state.taxPaidThisYear = 0;
          state.taxMonth = thisMonth;
        }

        // Every turn's income is recorded, whatever the turn's length — the
        // running clock ticks a day at a time, and a month's bill has to be
        // built out of thirty of those.
        //
        // An accountant shelters a slice of it. This is a REAL effect on a real
        // number: the tax screen's "earned this year" is the figure the bill is
        // worked out on, so a deduction that only existed in the prose would
        // show up as a promise the tax line contradicts.
        state.taxYearIncome = (state.taxYearIncome ?? 0) + turnIncome * (1 - crew.deductionRate);

        // ── WITHHOLDING IS MONTHLY ────────────────────────────────────
        // It used to be charged on EVERY turn with the cumulative method. The
        // money was the same in the end, but it came out in a hundred small
        // pieces — a player watching the running clock saw tax leave on a
        // single day's earnings and reasonably read it as a daily tax.
        //
        // The trigger is the MONTH BOUNDARY, not the +1 Month button, so a
        // player who never sims is still billed the moment the clock rolls the
        // month over. The method stays cumulative: the bill is worked out on
        // the whole year so far and only the gap against what has already been
        // paid is taken, so a month that was missed is made up by the next one
        // and a year that ends badly does not leave you having overpaid on a
        // good spring.
        if (state.taxMonth !== thisMonth) {
          const withholding = monthlyWithholding({
            yearToDateIncome: state.taxYearIncome,
            yearToDatePaid: state.taxPaidThisYear ?? 0,
          });
          if (withholding.due > 0.5) {
            state.player.career.money -= withholding.due;
            state.taxPaidThisYear = (state.taxPaidThisYear ?? 0) + withholding.due;
            state.taxPaidLifetime = (state.taxPaidLifetime ?? 0) + withholding.due;
            ledgerEntries.set('tax', -(ledgerEntries.get('tax') ?? 0) - withholding.due);
            log.push(
              `🏛️ Tax withholding ${money0(withholding.due)} for the month — you are keeping ${pct0(1 - withholding.bill.effectiveRate)} of what you earn.`,
            );
          }
          state.taxMonth = thisMonth;
        }

        // ─── INBOUND: SOMEBODY WANTS YOU ON THEIR RECORD ──────────────
        // The complaint this answers is "I am famous now and nobody has asked
        // me for a verse". The outbound system has always let the player ask;
        // nothing ever asked THEM. So once the player is actually worth asking,
        // artists come to them — and the player is the one quoting a number.
        //
        // Two details matter more than they look:
        //
        //  · It only asks about artists who have RELEASED something, because
        //    you cannot be asked onto a record that does not exist.
        //  · `weeksElapsed` scales the chance, because this runs once per
        //    `advanceTurn` whatever the unit — without it, tapping +1 Day would
        //    generate thirty times the asks of skipping a month.
        if (state.player) {
          const openAsks = state.inboundRequests.filter(
            (r) => r.status === 'open' || r.status === 'agreed',
          );
          const busy = state.inboundRequests
            .filter((r) => r.status === 'open')
            .map((r) => r.npcId);

          // How hot the player is right now: the best record they have put out
          // in the last couple of months. A record that is still moving is the
          // single most common reason anybody picks up the phone.
          let recentHeat = 0;
          for (const s of rawSongs) {
            if (!isReleased(s)) continue;
            if ((s.weeksOut ?? 99) > 8) continue;
            if (s.quality > recentHeat) recentHeat = s.quality;
          }

          const artistPool = rawNPCs.filter((n) => n.role === 'artist');
          const releasedOwners = new Set(
            (state.npcSongs as Song[])
              .filter((s) => s.ownerId && s.releaseDate)
              .map((s) => s.ownerId as string),
          );

          const ask = generateInboundAsk({
            playerFame: blendedFame(state.player),
            playerGenre: state.player.genre,
            playerCountry: state.player.country,
            recentHeat,
            pool: artistPool
              .filter((n) => releasedOwners.has(n.id))
              .map((n) => n as unknown as InboundCandidate),
            busyIds: busy,
            openCount: openAsks.length,
            weeksElapsed: days / 7,
            roll: Math.random(),
            // A connector gets you asked more, and by bigger names; a global
            // operator brings asks from abroad.
            ...(currentManager ? (() => {
              const sp = SPECIALTIES[managerSpecialty(currentManager)];
              const push = state.managerPush?.kind === 'features' && state.managerPush.until >= targetSerial ? 0.06 : 0;
              return { pull: sp.askRate * (0.5 + managerNetwork(currentManager) / 100) + push, reachUp: sp.reachUp, abroadOk: sp.id === 'global' && state.player.career.nationalFame >= 30 };
            })() : {}),
          });

          if (ask.npc && reaches(state.legacy?.mode, 'asks', Math.random())) {
            const host = (state.npcSongs as Song[]).find(
              (s) => s.ownerId === ask.npc!.id && s.releaseDate,
            );
            const npc = rawNPCs.find((n) => n.id === ask.npc!.id);
            // A record to be asked onto. Without one there is no ask, however
            // much they rate the player.
            if (host && npc && !isBlocked(state, npc.id)) {
              openInboundAsk(state, npc, host, isRealId(npc.id) ? `${npc.name} wants a verse from you on "${host.title}". The team will handle the paperwork.` : ask.reason);
              // Deliberately NOT pushed into `log`.
              //
              // The turn feed is ten lines and it belongs to the turn's own
              // receipts. An ask already reaches the player three other ways —
              // a notification, a DM and a letter in the Mailbox — and pushing
              // it here as well meant that on a busy month it evicted the
              // manager line from the feed, which is the same event delivered
              // once and lost once.
            }
          }
        }

        // ─── FEATURE DEALS AND THE COURTHOUSE ─────────────────────────
        // Verses owed both ways, balances owed both ways, and the cases that
        // come out of the ones that went wrong.
        featureDealsTick(state, dateToSerial(state.gameDate), log);
        courtTick(state, dateToSerial(state.gameDate));

        // ─── WORK IN PROGRESS ─────────────────────────────────────────
        // Every job the player has committed to eats the days that just passed,
        // and the ones that are done land here. This sits at the END of the
        // tick on purpose: a master that is finished today starts earning
        // tomorrow, rather than being credited with streams from days it spent
        // as a rough.
        //
        // Money and energy were taken when the job was ORDERED, so nothing is
        // charged here — this only puts the finished thing in the player's
        // hands.
        if ((state.workItems ?? []).length > 0) {
          const stillWorking: WorkItem[] = [];
          for (const item of state.workItems) {
            item.daysDone += days;
            if (item.daysDone >= item.daysTotal) {
              finishWork(state, item, log);
            } else {
              stillWorking.push(item);
            }
          }
          state.workItems = stillWorking;
        }

        // ─── UPDATE EVENT LOG ─────────────────────────────────────────
        // `log` is built in CHRONOLOGICAL order with `push`, but the feed is
        // rendered newest-first and every other writer in this file `unshift`es
        // into it. `slice(0, 10)` therefore kept the turn's OLDEST ten lines and
        // silently discarded the tail — and the tail is where the money is: the
        // accountant's recovery, the stylist's brand cheque and the month's tax
        // withholding are all pushed last, so on any busy month the player never
        // saw any of them.
        //
        // So the player's own turn takes the feed, newest first, and the scene
        // gets whatever room is left — capped at three lines, because a dozen
        // NPC releases a month would otherwise bury the player's own business.
        // Nothing is lost by the cap: the full account of the turn is in
        // `lastTurnReport`, which the dashboard shows as a receipt.
        const WORLD_LINES = 3;
        // The tour dates get a reserved place rather than being folded into the
        // tail of `log`, where a busy month would cut them. They stay in
        // chronological order: they happened first, so they read last.
        //
        // The reservation is generous on purpose. A night the player PLAYED is
        // the last thing that should ever be dropped from the feed, so a run of
        // up to six dates gets all of its lines even on a month turn where the
        // payroll and the tax are competing for the same ten. Six is the ceiling
        // because a run longer than that spans more than one tick anyway, and a
        // feed that is nothing but tour lines is not a feed. Anything squeezed
        // out is still itemised in `lastTurnReport`, and the tour's own panel
        // keeps every leg's takings.
        const TOUR_LINES_MAX = 6;
        const reserved = tourLines.slice(-TOUR_LINES_MAX);
        const keep = Math.max(0, 10 - reserved.length);
        const mine = [
          ...log.slice(-keep).reverse(),
          ...reserved.slice().reverse(),
        ];
        const room = Math.max(0, 10 - mine.length);
        const world = room > 0 ? worldLog.slice(-Math.min(WORLD_LINES, room)).reverse() : [];
        state.lastEventLog = [...mine, ...world].slice(0, 10);

        // ─── THE TURN REPORT ──────────────────────────────────────────
        // `ledgerEntries` was drained at the top of the tax block and has been
        // added to since, so this is the complete account of the turn. A
        // `silent` turn (the background clock catching up) still drains it and
        // writes nothing, so the player is never handed a receipt for time they
        // did not ask to pass.
        if (!opts?.silent) {
          state.lastTurnReport = buildTurnReport({
            turnCount: state.turnCount,
            unit,
            days,
            fromDate,
            toDate: formatGameDate(state.gameDate),
            moneyBefore,
            moneyAfter: state.player.career.money,
            entries: ledgerEntries,
            streams: totalWeeklyStreams,
            fans: fanGrowth,
            energyBefore,
            energyAfter: state.player.energy,
          }) as TurnReport;
        }

        // The manager's one message a day about everything new on the desk.
        managerDigest(state, targetSerial, rawNPCs);

        // ─── SAVE ────────────────────────────────────────────────────
        // Not here: serialising the whole career inside the day change is what
        // made midnight stutter. The save runs a moment later, when the
        // browser is idle (see `scheduleAutosave`), with the same full list
        // Save now uses.
      });
      // What the rules say the manager may take on their own, they take.
      if ((get().managerDesk ?? []).some((b) => b.auto && b.status !== 'done')) get().runAutopilot();
      // Projects scheduled in the album vault come out on their day.
      {
        const today = dateToSerial(get().gameDate);
        for (const d of (get().albumDrafts ?? []).filter((x) => x.plannedSerial !== undefined && x.plannedSerial <= today)) {
          const r = get().releaseAlbumDraft(d.id);
          set((state) => {
            if (r.ok) {
              pushNotification(state, { kind: 'milestone', title: `💿 "${d.title}" is out`, body: 'Your scheduled project dropped today. It charts from this week.', artSeed: `album|${d.id}` });
            } else {
              const x = (state.albumDrafts ?? []).find((y) => y.id === d.id);
              if (x) x.plannedSerial = undefined;
              pushNotification(state, { kind: 'business', title: `💿 "${d.title}" couldn't come out`, body: `${r.message} It's back in the album vault, unscheduled.`, artSeed: `album|${d.id}|fail` });
            }
          });
        }
      }
      if (pendingSide) scheduleSideTicks();
      scheduleAutosave();
    },

    /** The player has read the report — take it down. */
    dismissTurnReport: () =>
      set((state) => {
        state.lastTurnReport = null;
      }),

    // ─── THE RUNNING CLOCK ──────────────────────────────────────────────
    //
    // The clock is not decoration. It advances game minutes on a real timer and,
    // when it passes midnight, hands the day to `advanceTurn` — the same tick a
    // manual "+1 Day" uses. That is deliberate: a second simulation path would
    // drift from the first, and the world would then have two versions of
    // itself depending on how the player got there.
    advanceClock: (minutes) => {
      const before = get();
      if (!before.player || before.clockPaused) return;

      const next = (before.clockMinute ?? 0) + minutes;
      if (next < MINUTES_PER_DAY) {
        const nowAbs = dateToSerial(before.gameDate) * MINUTES_PER_DAY + next;
        const due = (before.pendingDMs ?? []).some((d) => d.atMinute <= nowAbs)
          || (before.appointments ?? []).some((a) => (a.status === 'confirmed' || a.status === 'proposed') && a.atMinute <= nowAbs)
          || clockEventsDue(before, nowAbs)
          || (before.cases ?? []).some((c) => c.status === 'hearing' && c.hearings.some((h) => !h.done && h.atMinute <= nowAbs))
          || Object.values(before.awardSeasons ?? {}).some((x) => x.phase === 'nominations' && x.cal.ceremonyMinute <= nowAbs);
        set((state) => {
          state.clockMinute = next;
          if (due) minuteTick(state, 'clock');
        });
        return;
      }

      // Roll the remainder onto the new day first, so the day tick's auto-save
      // writes a clock that already belongs to the date it saves.
      const days = Math.floor(next / MINUTES_PER_DAY);
      set((state) => {
        state.clockMinute = next % MINUTES_PER_DAY;
      });

      // A tab left in the background can owe a lot of days. Capped, because
      // each one is a full tick and an uncapped catch-up on a week-old tab
      // would stall the frame it lands on.
      const owed = Math.min(days, MAX_CLOCK_CATCHUP_DAYS);
      // Silent: this is time the player did not ask for, so it must not raise a
      // turn report. Only the explicit +1 Day / +1 Week / +1 Month do that.
      for (let i = 0; i < owed; i++) get().advanceTurn('day', { silent: true });
      set((state) => { minuteTick(state, 'clock'); });
    },

    // ─── SLEEP ──────────────────────────────────────────────────────────
    //
    // The other way back up, and the cheap one in time. Letting a whole day run
    // refills you completely but costs the day; three hours of sleep does the
    // same and costs three hours. That is the whole trade, and it is why the
    // rest control exists next to the clock rather than instead of it.
    rest: (minutes) => {
      const before = get();
      if (!before.player) return { ok: false, message: 'There is nobody to put to bed.' };

      const p = before.player;
      const refusal = restRefusal(minutes, p.energy, p.maxEnergy);
      if (refusal) return { ok: false, message: refusal };

      const from = Math.round(p.energy);
      // A personal assistant scales the GAIN, not the total. Scaling the total
      // would push past the ceiling and then be clamped back to it, so the
      // whole benefit would land in the range where there was nothing left to
      // recover — a mechanic that reads as working and does nothing.
      const base = restRecovery(minutes, p.energy, p.maxEnergy);
      const restMult = crewBonuses(before.crew).energyRecovery * ((before.crew ?? []).some((c) => c.role === 'personal_assistant' && (c.assignment ?? 'diary') === 'diary') ? 1.1 : 1) * (crewWithSkill(before.crew, 'stamina_coach') ? 1.1 : 1);
      const recovered = Math.min(
        p.maxEnergy,
        Math.round(p.energy + (base - p.energy) * restMult),
      );
      // Does this rest run past midnight? If it does the day has to be
      // processed, exactly as the clock would have done it.
      const totalMinutes = (before.clockMinute ?? 0) + minutes;
      const daysRolled = Math.floor(totalMinutes / MINUTES_PER_DAY);

      set((state) => {
        if (!state.player) return;
        state.player.energy = recovered;
        state.clockMinute = totalMinutes % MINUTES_PER_DAY;
      });

      // Silent, and capped for the same reason the clock is: a nap that crosses
      // midnight is one day, not a receipt.
      for (let i = 0; i < Math.min(daysRolled, MAX_CLOCK_CATCHUP_DAYS); i++) {
        get().advanceTurn('day', { silent: true });
      }
      set((state) => { minuteTick(state, 'rest'); });

      const after = Math.round(get().player?.energy ?? recovered);
      const hours = minutes >= 60
        ? `${Math.floor(minutes / 60)}h${minutes % 60 ? ` ${minutes % 60}m` : ''}`
        : `${minutes} min`;

      return {
        ok: true,
        message: `Slept ${hours}. Energy ${from} → ${after}.`,
      };
    },

    setClockPaused: (paused) =>
      set((state) => {
        state.clockPaused = paused;
      }),

    setClockSpeed: (speed) =>
      set((state) => {
        state.clockSpeed = speed;
      }),

    // ─── STATS ──────────────────────────────────────────────────────────
    updatePlayerStat: (stat, amount) =>
      set((state) => {
        if (!state.player) return;
        state.player.stats[stat] = Math.max(0, Math.min(100, state.player.stats[stat] + amount));
      }),

    // ─── TRAINING ───────────────────────────────────────────────────────
    trainStat: (stat, intensity) =>
      set((state) => {
        if (!state.player) return;

        const cost = TRAINING_COST[intensity];
        const days = TRAINING_DAYS[intensity];
        const current = state.player.stats[stat];

        if (state.player.career.money < cost) return;
        if (current >= 100) return;
        if (!spendEnergy(state, trainingEnergy(intensity))) return;

        const gain = trainingGain(current, intensity);

        state.player.career.money -= cost;
        state.player.stats[stat] = Math.min(100, current + gain);

        const coach = COACHES[stat];
        state.lastEventLog.unshift(
          `${coach ? coach.emoji : '🏋️'} Trained ${stat} (+${gain}) over ${days} days — $${cost.toLocaleString()}`,
        );
        state.lastEventLog = state.lastEventLog.slice(0, 10);

        // Time passes. The date and the turn counter move directly rather than
        // through `advanceTurn`, because training has already charged its own
        // cost and logged its own line. The streaming cursor is left alone, so
        // the next real turn picks these days up — no day is skipped, it is
        // only settled later.
        state.gameDate = advanceDate(state.gameDate, days) as typeof state.gameDate;
        state.turnCount += 1;
      }),

    // A direct setter for arranging a world, not something the player does.
    // See the interface declaration for why the free button that used to call
    // this was removed rather than rebalanced.
    updateNPCRelationship: (npcId, change) =>
      set((state) => {
        const npc = state.npcs.find(n => n.id === npcId);
        if (npc) {
          npc.relationshipScore = Math.max(-100, Math.min(100, npc.relationshipScore + change));
        }
      }),

    resolveOpenThread: (threadId) =>
      set((state) => {
        const thread = state.openThreads.find(t => t.id === threadId);
        if (thread) thread.resolved = true;
      }),

    // ─── STREAMING / CHARTS / VIDEO ACTIONS ──────────────────────────────

    setScreenCountry: (screenKey, country) =>
      set((state) => {
        if (!state.screenCountry) state.screenCountry = {};
        state.screenCountry[screenKey] = country;
        if (!state.recentCountries) state.recentCountries = [];
        const home = state.player?.country;
        state.recentCountries = [
          country,
          ...state.recentCountries.filter((c) => c !== country),
        ]
          // The home country is pinned separately in the picker, so it does not
          // need to occupy one of the recent slots.
          .filter((c) => c !== home)
          .slice(0, 5);
      }),

    subscribe: (artistId, artistName, kind) =>
      set((state) => {
        if (!state.subscriptions) state.subscriptions = [];
        const exists = state.subscriptions.some(
          (s) => s.artistId === artistId && s.kind === kind,
        );
        if (exists) return;
        state.subscriptions.push({
          artistId,
          artistName,
          kind,
          subscribedAt: formatDateString(state.gameDate),
          lastNotified: dateToSerial(state.gameDate),
        });
      }),

    unsubscribe: (artistId, kind) =>
      set((state) => {
        if (!state.subscriptions) return;
        state.subscriptions = state.subscriptions.filter(
          (s) => !(s.artistId === artistId && s.kind === kind),
        );
      }),

    recordWatch: (videoId) =>
      set((state) => {
        if (!state.watchHistory) state.watchHistory = [];
        state.watchHistory = [
          videoId,
          ...state.watchHistory.filter((v) => v !== videoId),
        ].slice(0, 60);
      }),

    reactToVideo: (videoId, value) =>
      set((state) => {
        const video = (state.videos ?? []).find((v) => v.id === videoId);
        if (!video) return;
        if (!state.videoReactions) state.videoReactions = {};
        const previous = state.videoReactions[videoId];

        // Undo the old reaction before applying the new one, so a change of mind
        // never leaves a vote behind and the same button cannot be spammed.
        if (previous === 1) video.likes = Math.max(0, video.likes - 1);
        if (previous === -1) video.dislikes = Math.max(0, video.dislikes - 1);

        if (previous === value) {
          delete state.videoReactions[videoId];
          return;
        }
        if (value === 1) video.likes += 1;
        else video.dislikes += 1;
        state.videoReactions[videoId] = value;
      }),

    markNotificationRead: (id) =>
      set((state) => {
        const n = (state.notifications ?? []).find((x) => x.id === id);
        if (n) n.read = true;
      }),

    markAllNotificationsRead: () =>
      set((state) => {
        for (const n of state.notifications ?? []) n.read = true;
      }),

    clearNotifications: () =>
      set((state) => {
        state.notifications = [];
      }),

    // ─── SAVE/LOAD ───────────────────────────────────────────────────────
    resetSession: () => set((state) => { Object.assign(state, getInitialState()); }),

    saveGame: () => {
      const state = get();
      if (!state.activeSlotId) {
        set((s) => {
          s.saveError =
            'This career is not attached to a save slot, so nothing is being written. ' +
            'Start a new career, or open one from the careers list.';
        });
        return;
      }
      const result = writeSlot(state.activeSlotId, buildSavePayload(state));
      set((s) => {
        s.saveError = result.ok ? null : result.error;
      });
    },

    /** Open a career that is already on disk, without disturbing the others. */
    loadSlot: (slotId) => {
      const saved = readSlot(slotId);
      if (!saved || !saved.player) return false;
      set((state) => {
        applySlotPayload(state, saved);
        // The payload does not carry its own slot id — that belongs to the
        // index, not the career — so it is set here, after the merge, or the
        // next auto-save would have nowhere to go.
        state.activeSlotId = slotId;
      });
      setActiveSlot(slotId);
      return true;
    },

    /** Resume whichever career was last played. */
    loadGame: () => {
      const index = readIndex();
      if (!index.activeSlotId) return false;
      return get().loadSlot(index.activeSlotId);
    },

    /** Every career on disk, newest first. */
    listSaves: () => readIndex().slots,

    /**
     * Start a career in a slot of its own.
     *
     * This is the fix for the bug where starting a new career destroyed the old
     * one: `newGame` used to `removeItem` the single save key. Nothing is
     * deleted now — a new career is a new slot, and the previous ones are left
     * exactly where they are.
     */
    newCareer: () => {
      const index = readIndex();
      if (index.slots.length >= maxSlots()) {
        set((s) => {
          s.saveError =
            `You are already keeping ${maxSlots()} careers, which is as many as this ` +
            'browser will hold. Delete one you are finished with, then start another.';
        });
        return false;
      }
      const id = newSlotId();
      set((state) => {
        Object.assign(state, getInitialState());
        state.activeSlotId = id;
        state.initialized = true;
        state.saveError = null;
      });
      setActiveSlot(id);
      return true;
    },

    /**
     * Throw a career away for good.
     *
     * If it was the one being played, the player has to end up somewhere: the
     * most recent other career, or the splash screen if that was the last one.
     * Leaving them on a dashboard for a career that no longer exists would be
     * the same class of bug as the one this whole change is fixing.
     */
    deleteSlot: (slotId) => {
      const index = readIndex();
      if (!index.slots.some((s) => s.id === slotId)) return false;
      const wasActive = index.activeSlotId === slotId;
      removeSlot(slotId);
      set((state) => {
        if (wasActive) {
          const next = readIndex().activeSlotId;
          const saved = next ? readSlot(next) : null;
          if (next && saved && saved.player) {
            applySlotPayload(state, saved);
            state.activeSlotId = next;
          } else {
            Object.assign(state, getInitialState());
          }
        }
        state.saveError = null;
      });
      return true;
    },

    /** Give a career a name the player will recognise. */
    renameSlot: (slotId, label) => {
      renameSaveSlot(slotId, label);
      set((state) => {
        state.saveError = null;
      });
    },

    /**
     * The splash screen's "start new career".
     *
     * It used to be `Object.assign(state, getInitialState())` plus
     * `localStorage.removeItem(SAVE_KEY)` — which is to say, it deleted the
     * only save that existed. It now opens a slot of its own and leaves every
     * other career alone.
     */
    newGame: () => {
      get().newCareer();
    },
  }))
);

// ─── ONE-TIME MIGRATION ─────────────────────────────────────────────────────
//
// This game shipped with a single save at one fixed key. The first time this
// build runs, that career is moved into a slot of its own so the player does
// not lose it — and the old key is only removed after the copy has been read
// back and compared, so an interrupted migration leaves the original intact
// rather than destroying the only copy of somebody's career.
// (Run by the boot in main.tsx once the local database is open.)
